-- X-TOOLS | Project and integration: Casual_Alvarez | Module: about_author.lua
-- Original third-party credits, where present, are retained below.
local M={}
function M.draw(rt)
 local g=rt.imgui
 if not rt.aboutArt then
  rt.aboutArt={}
  local file=io.open(rt.base..'/assets/about-author.png','rb')
  if file then
   local bytes=file:read('*a');file:close()
   local ffi=require('ffi')
   local pointer=tonumber(ffi.cast('uintptr_t',ffi.cast('const char*',bytes)))
   local ok,texture=pcall(g.CreateTextureFromMemory,pointer,#bytes)
   if ok and texture and texture~=0 then rt.aboutArt.texture=texture end
  end
 end
 local width=math.max(1,g.GetContentRegionAvailWidth())
 local art=rt.aboutArt.texture
 local appearance=rt:service('appearance.lua')
 local style=rt.preferences.data.main.backgroundStyle or 0
 rt.art=rt.art or rt:service('art.lua').new(g,rt.base,rt.api)
 local backdrop=style>0 and rt.art:get(appearance.asset('background',style))
 if backdrop then art=backdrop.texture end
 if art then
  local start=g.GetCursorPos()
  local height=width/3
  if backdrop then g.Image(art,g.ImVec2(width,height),g.ImVec2(0,.45),g.ImVec2(1,.95))
  else g.Image(art,g.ImVec2(width,height))end
  local after=g.GetCursorPos()
  if width>=420 then
   g.SetCursorPos(g.ImVec2(start.x+24,start.y+height*0.32))
   g.TextColored(rt.theme.color(g,rt.theme.palette.accent),'CASUAL ALVAREZ')
   g.SetCursorPos(g.ImVec2(start.x+24,start.y+height*0.32+26))
   g.Text('История X-TOOLS')
   if backdrop then
    local logo=rt.art:get(appearance.asset('logo',rt.preferences.data.main.logoStyle))
    if logo then
     local size=math.min(110,height*.65)
     g.SetCursorPos(g.ImVec2(start.x+width-size-24,start.y+(height-size)/2))
     g.Image(logo.texture,g.ImVec2(size,size))
    end
   end
  end
  g.SetCursorPos(after)
  g.Spacing()
 end
 local function paragraph(text,accent)
  g.Spacing()
  if accent then g.PushStyleColor(g.Col.Text,rt.theme.color(g,rt.theme.palette.accent))end
  g.TextWrapped(text)
  if accent then g.PopStyleColor()end
  g.Spacing()
 end
 paragraph('Casual Alvarez · автор X-TOOLS',true)
 g.TextDisabled('В игре с 2013 · В администрации примерно с 2015')
 g.Spacing()
 paragraph('Привет! Мой ник — Casual Alvarez. Играю с 2013 года, а примерно с 2015-го периодически возвращаюсь на админку — за это время успел побывать на самых разных уровнях и поработать в самых разных направлениях.')
 paragraph('Скрывать нечего: этот текст, как и многое при разработке X-TOOLS, написан с помощью ИИ.')
 g.Separator()
 paragraph('Этот скрипт — буквально то, о чём я в своё время даже не мог мечтать. За годы админки накопилось огромное количество мыслей в духе: «а вот было бы удобно, если бы это работало вот так». Большую часть из них я постарался реализовать здесь.')
 paragraph('Что-то в X-TOOLS — полностью мои идеи и наработки. Что-то подсмотрено в других скриптах. Что-то я вообще нагло украл, вырезал имя автора и забрал себе — возможно, когда-нибудь доберусь и добавлю авторов обратно :)')
 paragraph('Сейчас X-TOOLS всё ещё находится в разработке, но уже на этом этапе, на мой взгляд, он с огромным запасом перекрывает возможности привычного нам AdminTools от David Garner.')
 g.Separator()
 paragraph('Что забавно, сам X-TOOLS изначально вообще не планировался как отдельный большой проект. Всё началось гораздо проще: я открыл AdminTools и решил вырезать из него нерабочий и устаревший мусор.')
 paragraph('Потом захотелось кое-что исправить.')
 paragraph('Потом — кое-что добавить.')
 paragraph('А потом это превратилось в X-TOOLS.',true)
end
return M

