-- X-TOOLS | Project and integration: Casual_Alvarez | Module: authenticator.lua
-- Original third-party credits, where present, are retained below.
local Auth={};Auth.__index=Auth
local function protect(bytes,decode)
    local ffi=require('ffi')
    if not pcall(ffi.typeof,'XT_AUTH_BLOB') then ffi.cdef[[
        typedef struct { unsigned long size; unsigned char *data; } XT_AUTH_BLOB;
        int __stdcall CryptProtectData(XT_AUTH_BLOB*, const wchar_t*, XT_AUTH_BLOB*, void*, void*, unsigned long, XT_AUTH_BLOB*);
        int __stdcall CryptUnprotectData(XT_AUTH_BLOB*, wchar_t**, XT_AUTH_BLOB*, void*, void*, unsigned long, XT_AUTH_BLOB*);
        void* __stdcall LocalFree(void*);
    ]] end
    local crypt=ffi.load('crypt32');local kernel=ffi.load('kernel32')
    local buffer=ffi.new('unsigned char[?]',#bytes);ffi.copy(buffer,bytes,#bytes)
    local input=ffi.new('XT_AUTH_BLOB',{#bytes,buffer});local output=ffi.new('XT_AUTH_BLOB')
    local fn=decode and crypt.CryptUnprotectData or crypt.CryptProtectData
    if fn(input,nil,nil,nil,nil,1,output)==0 then return nil end
    local result=ffi.string(output.data,output.size);kernel.LocalFree(output.data)
    return result
end
function Auth.new(rt)
    local path=rt.storage:path('settings','authenticator.ini')
    return setmetatable({rt=rt,path=path,secretPath=rt.storage:path('data','authenticator.dpapi'),
        data=rt.storage:loadIni({main={enabled=false,nickname=''}},path),status=''},Auth)
end
function Auth:nickname()
    local a=self.rt.api
    local found,id=a.sampGetPlayerIdByCharHandle(a.PLAYER_PED)
    return found and a.sampGetPlayerNickname(id) or nil
end
function Auth:save(secret)
    secret=self.rt:service('totp.lua').normalize(secret)
    if not secret then self.status='Нужен секретный ключ Base32, не шестизначный код.';return false end
    local nick=self:nickname()
    if not nick or nick=='' then self.status='Сначала войдите своим персонажем.';return false end
    local ok,encrypted=pcall(protect,secret,false)
    if not ok or not encrypted then self.status='Windows не смогла защитить ключ.';return false end
    if not self.rt.storage:write(self.secretPath,encrypted) then self.status='Не удалось сохранить ключ.';return false end
    self.data.main.nickname=nick
    self.rt.storage:saveIni(self.data,self.path)
    self.status='Ключ сохранён для текущего персонажа.';return true
end
function Auth:dialog(id,style,title,body)
    local rt=self.rt
    if id==1 and title=='Авторизация' and not body:find('Неверный',1,true) then self.attempted=false end
    if id~=88 or style~=1 or title~='Код с приложения' or not body:find('Authenticator',1,true) then return end
    if self.data.main.enabled~=true or self.attempted or not rt:serverSupports() then return end
    if self:nickname()~=self.data.main.nickname then return end
    local encrypted=rt.storage:read(self.secretPath);if not encrypted then return end
    local ok,secret=pcall(protect,encrypted,true);if not ok or not secret then self.status='Не удалось открыть ключ Windows.';return end
    local code=rt:service('totp.lua').code(secret,rt.api.os.time())
    if not code then return end
    self.attempted=true
    rt.api.sampSendDialogResponse(88,1,-1,code)
    return false
end
function Auth:draw(g)
    self.buffer=self.buffer or g.ImBuffer(160)
    local enabled=g.ImBool(self.data.main.enabled==true)
    if g.Checkbox('Google Auth: вводить код автоматически',enabled) then self.data.main.enabled=enabled.v;self.rt.storage:saveIni(self.data,self.path) end
    g.SameLine()
    if g.Button('Настройки##authenticator') then self.settingsExpanded=not self.settingsExpanded end
    if not self.settingsExpanded then return end
    g.InputText('Ключ Google Auth##totp_secret',self.buffer,g.InputTextFlags.Password)
    if g.Button('Привязать ключ##totp_save') then if self:save(self.buffer.v) then self.buffer.v='' end end
    g.SameLine()
    if g.Button('Удалить ключ##totp_delete') then
        if not self.rt.storage:write(self.secretPath,'') then self.status='Не удалось удалить ключ.';return end
        self.rt.storage:remove(self.secretPath..'.bak');self.data.main.enabled=false;self.data.main.nickname=''
        self.rt.storage:saveIni(self.data,self.path);self.buffer.v='';self.status='Ключ удалён.'
    end
    
    if self.status~='' then g.TextWrapped(self.status) end
end
return Auth

    end
    sources["automatic_leader.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: automatic_leader.lua
-- Original third-party credits, where present, are retained below.
local M={}
function M.new(rt,settings)
    local self={lastPayday=-100000}
    local a=rt.api
    function self:reset()
        self.due=nil;self.ready=nil;self.loginDone=false;self.paydayArgs=nil;self.lastPayday=-100000
    end
    local function valid(args)
        return type(args)=='string' and args~='0 0' and args:match('^%d+%s+%d+$')~=nil
    end
    function self:observe(event,...)
        if event=='onConnectionLost' or event=='onConnectionClosed' or event=='onInitGame' then self:reset();return end
        local enabled,args=settings()
        if not enabled or not valid(args) or not rt.access:can(4) or rt.powered==false then return end
        if event~='onServerMessage' then return end
        local _,raw=...
        local line=tostring(a.require('encoding').UTF8(raw or '')):gsub('{%x+}',''):match('^%s*(.-)%s*$')
        local now=a.getGameTimer()
        if line=='БАНКОВСКИЙ ЧЕК' and now-self.lastPayday>=30000 then
            self.lastPayday=now;self.paydayArgs=args;self.resetSeen=false
            self.due=now+8000;self.pendingArgs=args;self.revision=rt.access:revision()
        elseif line:match('^Вы покинули временную семью') and self.paydayArgs==args
            and not self.resetSeen and now-self.lastPayday<=120000 then
            -- The family reset marks the late payday reset phase, after the bank cheque.
            self.resetSeen=true;self.due=now+2000;self.pendingArgs=args
        end
    end
    function self:update()
        local enabled,args=settings();local revision=rt.access:revision()
        if not enabled or not valid(args) or not rt.access:can(4) or a.sampGetGamestate()~=3 then self:reset();return end
        if self.revision and self.revision~=revision then self:reset()end
        self.revision=revision
        if self.pendingArgs and self.pendingArgs~=args then self:reset();self.revision=revision end
        if not a.sampIsLocalPlayerSpawned() or a.sampIsDialogActive() then self.ready=nil;return end
        local now=a.getGameTimer()
        if not self.due and not self.loginDone then
            self.ready=self.ready or now
            if now-self.ready>=1500 then self.due=now;self.pendingArgs=args end
        end
        if self.due and now>=self.due then
            self.due=nil;self.loginDone=true
            rt:send('core','sampSendChat','/templeader '..args)
        end
    end
    return self
end
return M

    end
    sources["automatic_skin.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: automatic_skin.lua
-- Original third-party credits, where present, are retained below.
local M={}
function M.new(rt,settings)
    local self={nextAt=0}
    local a=rt.api
    function self:update()
        local enabled,skin=settings()
        if not enabled then self.state=nil;self.nextAt=0;return end
        skin=tonumber(skin)
        local menu=rt.modules.menu
        local observed=menu and menu.enabled and menu.bridge.observation and rt:call(menu,menu.bridge.observation)
        local state
        if not rt.access:can(4) then state='waiting for admin level 4'
        elseif a.sampGetGamestate()~=3 or not a.sampIsLocalPlayerSpawned() then state='waiting for spawn'
        elseif observed then state='spectating'
        elseif not a.doesCharExist(a.PLAYER_PED) or a.isCharDead(a.PLAYER_PED) then state='waiting for live player'
        elseif not skin or skin<0 or skin>311 or skin==74 or skin%1~=0 then state='invalid configured skin'
        elseif a.getCharModel(a.PLAYER_PED)==skin then state='selected skin active'
        else state='ready' end
        if self.state~=state then
            self.state=state
        end
        if state~='ready' then self.nextAt=0;return end
        local now=a.getGameTimer()
        if now<self.nextAt then return end
        local ok,id=a.sampGetPlayerIdByCharHandle(a.PLAYER_PED)
        if not ok or type(id)~='number' or id<0 or id>1003 then return end
        self.nextAt=now+3000
        rt:send('core','sampSendChat',string.format('/skin %d %d',id,skin))
    end
    return self
end
return M

    end
    sources["avatar.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: avatar.lua
-- Original third-party credits, where present, are retained below.
-- The player's current stock GTA skin, loaded locally and clipped to a circle.
-- Asset provenance: assets/skins/sources.json. No network access at runtime.
local Avatar = {}
Avatar.__index = Avatar

local ffi = require 'ffi'
local SEGMENTS = 48
local ring = {}
for i = 0, SEGMENTS do
    local angle = i * (math.pi * 2 / SEGMENTS)
    ring[i + 1] = {math.cos(angle), math.sin(angle)}
end

local function stockSkin(id)
    return type(id) == 'number' and id == math.floor(id) and id >= 0 and id <= 311 and id ~= 74
end

local function pngSize(data)
    if type(data) ~= 'string' or #data < 24 or data:sub(1, 8) ~= '\137PNG\13\10\26\10' then return end
    local function integer(offset)
        local a, b, c, d = data:byte(offset, offset + 3)
        return ((a * 256 + b) * 256 + c) * 256 + d
    end
    local w, h = integer(17), integer(21)
    if w < 1 or h < 1 or w > 2048 or h > 2048 then return end
    return w, h
end

function Avatar.new(imgui, basePath, api)
    return setmetatable({
        imgui = imgui,
        api = api or _G,
        basePath = assert(basePath, 'avatar requires the admintools resource directory'):gsub('[/\\]+$', ''),
        model = nil, texture = nil, attempted = nil, error = nil,
    }, Avatar)
end

function Avatar:release()
    if self.texture then
        pcall(self.imgui.ReleaseTexture, self.texture)
        self.texture = nil
    end
end

function Avatar:currentModel()
    local api = self.api
    if type(api.getCharModel) ~= 'function' or api.PLAYER_PED == nil then return end
    if type(api.doesCharExist) == 'function' then
        local ok, exists = pcall(api.doesCharExist, api.PLAYER_PED)
        if not ok or not exists then return end
    end
    local ok, model = pcall(api.getCharModel, api.PLAYER_PED)
    if ok then return model end
end

-- Call before submitting this frame's avatar draw commands. At most one texture
-- exists: changing the skin releases the previous resource before loading once.
-- Failed loads are remembered too; a missing file must never cause frame I/O.
function Avatar:update(model)
    if model == nil then model = self:currentModel() end
    if self.model == model and self.attempted then return self.texture ~= nil end
    self:release()
    self.model, self.attempted, self.error = model, true, nil
    if not stockSkin(model) then return false end

    local path = self.basePath .. '/assets/skins/' .. model .. '.png'
    local file = io.open(path, 'rb')
    if not file then self.error = 'portrait file unavailable'; return false end
    local data = file:read('*a')
    file:close()
    local width, height = pngSize(data)
    if not width then self.error = 'invalid portrait PNG'; return false end

    -- Read through Lua's path handling, then send bytes to the renderer. The
    -- Direct3D helper never has to reinterpret a Cyrillic installation path.
    local address = tonumber(ffi.cast('uintptr_t', ffi.cast('const char*', data)))
    local ok, texture = pcall(self.imgui.CreateTextureFromMemory, address, #data)
    if not ok or texture == nil or texture == false or texture == 0 then
        self.error = 'portrait texture unavailable'
        return false
    end
    self.texture = texture
    -- A square head-and-shoulders crop, adjusted from the actual PNG dimensions.
    self.u0, self.u1 = 0.22, 0.78
    self.v0, self.v1 = 0.08, math.min(1, 0.08 + width * 0.56 / height)
    return true
end

-- Coordinates are screen-space and radius includes the portrait, not the ring.
-- MoonImGui 1.1.2 has no AddImageRounded; degenerate image quads form textured
-- triangles. UVs follow the same affine transform, so no square corners bleed.
function Avatar:draw(drawList, cx, cy, radius, background, border)
    local g, vec = self.imgui, self.imgui.ImVec2
    local centre = vec(cx, cy)
    drawList:AddCircleFilled(centre, radius + 3, background, SEGMENTS)
    if self.texture then
        local uc, vc = (self.u0 + self.u1) / 2, (self.v0 + self.v1) / 2
        local ur, vr = (self.u1 - self.u0) / 2, (self.v1 - self.v0) / 2
        local uvCentre = vec(uc, vc)
        for i = 1, SEGMENTS do
            local a, b = ring[i], ring[i + 1]
            drawList:AddImageQuad(self.texture,
                centre, vec(cx + a[1] * radius, cy + a[2] * radius),
                vec(cx + b[1] * radius, cy + b[2] * radius), centre,
                uvCentre, vec(uc + a[1] * ur, vc + a[2] * vr),
                vec(uc + b[1] * ur, vc + b[2] * vr), uvCentre, 0xFFFFFFFF)
        end
    else
        -- An explicit unavailable-avatar symbol rather than another player's
        -- skin when disconnected, using a custom model, or missing an asset.
        drawList:AddCircleFilled(vec(cx, cy - radius * 0.23), radius * 0.23, border, 24)
        drawList:AddCircle(vec(cx, cy + radius * 0.26), radius * 0.39, border, 32, 2)
    end
    drawList:AddCircle(centre, radius + 2, border, SEGMENTS, 1.5)
    return self.texture ~= nil
end

function Avatar:shutdown()
    self:release()
    self.model, self.attempted, self.error = nil, nil, nil
end

return Avatar

    end
    sources["beautifulsky/model.lua"] = function()
-- Pure sky mathematics. No game memory, network, or rendering dependencies.
local M = {}
local pi, sin, cos, sqrt = math.pi, math.sin, math.cos, math.sqrt
function M.clamp(x, a, b) return math.max(a or 0, math.min(b or 1, x)) end
function M.finite(x) return type(x)=='number' and x==x and x~=math.huge and x~=-math.huge end
function M.mix(a, b, t) return a + (b - a) * t end
function M.smooth(a, b, x)
    local t = M.clamp((x - a) / (b - a))
    return t * t * (3 - 2 * t)
end
function M.normalize(x, y, z)
    local n = sqrt(x*x + y*y + z*z)
    if n < 1e-9 then return 0, 0, 1 end
    return x/n, y/n, z/n
end
function M.color(a, b, t)
    return {M.mix(a[1], b[1], t), M.mix(a[2], b[2], t), M.mix(a[3], b[3], t)}
end

-- Zenith and horizon for EVERY hour, interpolated continuously through midnight.
M.hours = {
    {{5,9,25}, {23,34,58}}, {{4,7,22}, {18,28,49}},
    {{4,7,21}, {18,28,47}}, {{5,9,26}, {24,34,56}},
    {{11,17,40}, {58,54,79}}, {{34,34,72}, {166,95,101}},
    {{56,74,120}, {249,153,100}}, {{49,109,177}, {255,201,143}},
    {{33,122,203}, {199,227,247}}, {{26,123,208}, {178,219,248}},
    {{22,117,204}, {168,214,248}}, {{20,110,199}, {166,214,249}},
    {{20,103,190}, {175,221,253}}, {{23,108,194}, {177,222,251}},
    {{27,113,199}, {184,224,249}}, {{37,115,194}, {199,227,244}},
    {{51,111,180}, {228,219,196}}, {{67,94,153}, {255,180,122}},
    {{62,65,120}, {247,116,83}}, {{32,35,79}, {149,75,103}},
    {{14,21,49}, {62,56,85}}, {{8,15,37}, {34,43,67}},
    {{6,12,30}, {27,38,62}}, {{5,10,27}, {24,35,59}}
}

-- GTA SA weather IDs: 0..19 outdoors; 20..22 underwater/interior presets.
-- Special timecycle IDs 23..45 receive a restrained fallback, not array indexing.
local clear = {cloud=.22, wind=.35, haze=.05, stars=1, sun=1, tint={175,192,205}}
local sunny = {cloud=.38, wind=.5, haze=.08, stars=.92, sun=.95, tint={174,191,203}}
local cloudy = {cloud=.83, wind=.75, haze=.28, stars=.34, sun=.38, tint={133,151,168}}
local rain = {cloud=1, wind=1.45, haze=.78, stars=0, sun=.025, tint={76,88,104}}
local fog = {cloud=.68, wind=.24, haze=.92, stars=.025, sun=.06, tint={154,170,177}}
local smog = {cloud=.42, wind=.4, haze=.49, stars=.45, sun=.68, tint={179,165,134}}
local desert = {cloud=.12, wind=.7, haze=.16, stars=1, sun=1.1, tint={212,179,131}}
local storm = {cloud=.95, wind=2.1, haze=.96, stars=0, sun=.035, tint={166,120,67}}
M.weatherNames = {
    [0]='Extra sunny LA', 'Sunny LA', 'Extra sunny smog LA', 'Sunny smog LA',
    'Cloudy LA', 'Sunny SF', 'Extra sunny SF', 'Cloudy SF', 'Rainy SF', 'Foggy SF',
    'Sunny LV', 'Extra sunny LV', 'Cloudy LV', 'Extra sunny countryside',
    'Sunny countryside', 'Cloudy countryside', 'Rainy countryside',
    'Extra sunny desert', 'Sunny desert', 'Sandstorm', 'Underwater',
    'Extra colours 1', 'Extra colours 2'
}
local weather = {[0]=clear, sunny, smog, smog, cloudy, sunny, clear, cloudy,
    rain, fog, sunny, clear, cloudy, clear, sunny, cloudy, rain, desert, desert,
    storm, fog, cloudy, cloudy}
function M.profile(id)
    id = math.floor(tonumber(id) or 0)
    return weather[id] or cloudy
end
function M.sample(hour, oldWeather, newWeather, blend)
    hour = (hour or 12) % 24
    local h = math.floor(hour)
    local t = M.smooth(0,1,hour-h)
    local a,b = M.hours[h+1],M.hours[(h+1)%24+1]
    local p,q = M.profile(oldWeather),M.profile(newWeather or oldWeather)
    blend = M.clamp(blend or 0)
    local s={hour=hour, top=M.color(a[1],b[1],t), bottom=M.color(a[2],b[2],t)}
    s.starCos,s.starSin=cos(hour*pi/12),sin(hour*pi/12)
    for _,k in ipairs({'cloud','wind','haze','stars','sun'}) do s[k]=M.mix(p[k],q[k],blend) end
    s.mist=M.mix(p==fog and 1 or 0,q==fog and 1 or 0,blend)
    s.dust=M.mix(p==storm and 1 or 0,q==storm and 1 or 0,blend)
    local daylight = M.smooth(4.8,7.3,hour)*(1-M.smooth(17.5,20.2,hour))
    s.night = 1-M.smooth(4.4,6.8,hour)*(1-M.smooth(18.0,20.8,hour))
    s.daylight = daylight
    local tint = M.color(p.tint,q.tint,blend)
    local dark = .13+.87*daylight
    for i=1,3 do tint[i]=tint[i]*dark end
    s.top=M.color(s.top,tint,s.haze*.88)
    s.bottom=M.color(s.bottom,tint,s.haze*.86)
    s.cloudColor=M.color({52,63,87},{245,248,253},daylight)
    local warmth=math.exp(-((hour-6.4)/1.05)^2)+math.exp(-((hour-18)/1.2)^2)
    s.cloudColor=M.color(s.cloudColor,{255,164,117},M.clamp(warmth*.66)*(1-s.haze))
    s.cloudColor=M.color(s.cloudColor,tint,s.haze*.68)
    s.stars=s.stars*s.night*(1-s.haze)
    s.sun=s.sun*(1-s.night*.97)
    local angle=(hour-6)*pi/12
    s.sx,s.sy,s.sz=M.normalize(cos(angle),.22,sin(angle))
    s.mx,s.my,s.mz=-s.sx,-s.sy,-s.sz
    return s
end

function M.random(seed)
    local x=seed or 1729
    return function() x=(x*16807)%2147483647; return x/2147483647 end
end
function M.stars(count)
    local rnd=M.random(71931)
    local out={}
    for i=1,count do
        local z=rnd()*2-1
        local az=rnd()*2*pi
        local r=sqrt(1-z*z)
        local x,y=r*cos(az),r*sin(az)
        if i%3==0 then
            local scatter=(rnd()+rnd()+rnd()-1.5)*.18
            x,y,z=M.normalize(-.584*cos(az)-.307*sin(az)+.75*scatter,
                .811*cos(az)-.221*sin(az)+.54*scatter,.925*sin(az)+.38*scatter)
        end
        out[i]={x=x,y=y,z=z,brightness=.42+.58*rnd()^2,
            size=.8+1.6*rnd()^4,phase=rnd()*2*pi,speed=.6+rnd()*1.7,warm=rnd()}
    end
    return out
end
function M.clouds(count)
    local rnd=M.random(8921)
    local out={}
    for i=1,count do
        out[i]={az=rnd()*2*pi,elevation=.12+rnd()*.92,size=.19+rnd()*.38,
            speed=.6+rnd()*.7,opacity=.85+rnd()*.14,threshold=(i-1)/count}
    end
    return out
end
function M.cloudDirection(cloud, phase)
    local a=cloud.az+phase*cloud.speed
    local r=cos(cloud.elevation)
    return r*cos(a),r*sin(a),sin(cloud.elevation)
end
function M.twinkle(star, seconds)
    return star.brightness*(.75+.25*sin(seconds*star.speed+star.phase))
end
function M.meteor(seconds, interval)
    interval=interval or 13
    local cycle=math.floor(seconds/interval)
    local rnd=M.random(971+cycle%100000*7919)
    local offset=2+rnd()*math.max(0,interval-4)
    local age=seconds%interval-offset
    if age<0 or age>1.25 then return nil end
    local az=rnd()*2*pi
    local el=.48+rnd()*.55
    return {az=az+age*.29,el=el-age*.19,alpha=sin(age/1.25*pi),age=age}
end
-- Row-vector D3D view and projection convention; translation intentionally ignored.
function M.project(x,y,z,view,projection,width,height)
    local cx=x*view[1]+y*view[5]+z*view[9]
    local cy=x*view[2]+y*view[6]+z*view[10]
    local cz=x*view[3]+y*view[7]+z*view[11]
    if cz<=.02 then return nil end
    return (1+cx*projection[1]/cz+projection[9])*width*.5,
        (1-cy*projection[6]/cz-projection[10])*height*.5,cz
end
function M.ray(nx,ny,view,projection)
    local x,y=(nx-projection[9])/projection[1],(ny-projection[10])/projection[6]
    return M.normalize(x*view[1]+y*view[2]+view[3],
        x*view[5]+y*view[6]+view[7],x*view[9]+y*view[10]+view[11])
end
-- A cloud occupies a fixed tangent plane in world space. Clip in camera space,
-- including UVs, so camera roll is respected and a cloud does not disappear when
-- only its centre crosses the camera plane. Returned RHW enables perspective UVs.
function M.cloudPolygon(cloud,phase,size,view,projection,width,height,aspect)
    local az=cloud.az+phase*cloud.speed
    local el=cloud.elevation
    local dx,dy,dz=cos(el)*cos(az),cos(el)*sin(az),sin(el)
    local rx,ry,rz=-sin(az),cos(az),0
    local ux,uy,uz=-sin(el)*cos(az),-sin(el)*sin(az),cos(el)
    local hw,hh=size*(aspect or 1)*.5,size*.5
    local polygon={}
    for _,corner in ipairs({{-1,1,0,0},{1,1,1,0},{1,-1,1,1},{-1,-1,0,1}}) do
        local a,b=corner[1]*hw,corner[2]*hh-size*.1
        local x,y,z=dx+rx*a+ux*b,dy+ry*a+uy*b,dz+rz*a+uz*b
        polygon[#polygon+1]={x*view[1]+y*view[5]+z*view[9],
            x*view[2]+y*view[6]+z*view[10],x*view[3]+y*view[7]+z*view[11],corner[3],corner[4]}
    end
    local clipped={}
    local near=.05
    local previous=polygon[#polygon]
    for _,current in ipairs(polygon) do
        local prevIn,currIn=previous[3]>=near,current[3]>=near
        if prevIn~=currIn then
            local t=(near-previous[3])/(current[3]-previous[3])
            local cut={}
            for i=1,5 do cut[i]=M.mix(previous[i],current[i],t) end
            cut[3]=near;clipped[#clipped+1]=cut
        end
        if currIn then clipped[#clipped+1]=current end
        previous=current
    end
    if #clipped<3 then return nil end
    local minX,minY,maxX,maxY=math.huge,math.huge,-math.huge,-math.huge
    for _,vertex in ipairs(clipped) do
        local rhw=1/vertex[3]
        local x=(1+vertex[1]*projection[1]*rhw+projection[9])*width*.5
        local y=(1-vertex[2]*projection[6]*rhw-projection[10])*height*.5
        vertex[1],vertex[2],vertex[3]=x,y,rhw
        minX=math.min(minX,x);minY=math.min(minY,y);maxX=math.max(maxX,x);maxY=math.max(maxY,y)
    end
    if maxX<0 or maxY<0 or minX>width or minY>height then return nil end
    return clipped
end
function M.atmosphere(s,x,y,z,showStars)
    local h=M.clamp(z)
    local t=h^.48
    local r=M.mix(s.bottom[1],s.top[1],t)
    local g=M.mix(s.bottom[2],s.top[2],t)
    local b=M.mix(s.bottom[3],s.top[3],t)
    local dot=M.clamp(x*s.sx+y*s.sy+z*s.sz)
    local halo=dot^18*s.sun*(1-s.haze)*.32
    r=M.mix(r,255,halo);g=M.mix(g,220,halo);b=M.mix(b,160,halo)
    if showStars~=false and s.stars>.01 and z>0 then
        local gx=x*s.starCos+y*s.starSin
        local gy=-x*s.starSin+y*s.starCos
        local distance=math.abs(gx*.75+gy*.54+z*.38)
        local band=math.exp(-(distance/.12)^2)
        local dust=.62+.22*sin(gx*29+gy*17+z*23)+.12*sin(gx*67-gy*43+z*37)
        local light=band*dust*s.stars*M.smooth(0,.2,z)
        r=r+light*11;g=g+light*15;b=b+light*24
    end
    return r,g,b
end
return M

    end
    sources["beautifulsky/native.lua"] = function()
-- One-way calls into the native renderer. Never creates an FFI Lua callback.
local ffi=require 'ffi'
ffi.cdef[[
typedef struct {
 float top[3],bottom[3],cloudColor[3];
 float starCos,starSin,cloud,haze,stars,sun,mist,dust,night;
 float sx,sy,sz,mx,my,mz,seconds,phase,moonSize,interval;
 int quality,flags,enabled;
} XTSkyFrame;
int __cdecl bs_abi(void);
int __cdecl bs_init(void*,const char*);
int __cdecl bs_install(void);
void __cdecl bs_update(const XTSkyFrame*);
void __cdecl bs_lost(void);
int __cdecl bs_reset(void);
void __cdecl bs_close(void);
int __cdecl bs_error(void);
]]
local libraries={}
local fields={'starCos','starSin','cloud','haze','stars','sun','mist','dust','night','sx','sy','sz','mx','my','mz'}
local M={}
function M.new(device,path)
    assert(ffi.abi('32bit'),'BeautifulSky requires 32-bit GTA SA')
    local library=libraries[path]
    if not library then library=ffi.load(path..'/xt_sky.dll');libraries[path]=library end
    assert(library.bs_abi()==ffi.sizeof('XTSkyFrame'),'BeautifulSky native ABI mismatch')
    assert(library.bs_init(ffi.cast('void*',device),path)==1,'BeautifulSky DirectX initialization failed: '..library.bs_error())
    if library.bs_install()~=1 then library.bs_close();error('BeautifulSky hook conflict or unsupported executable')end
    local self={library=library,frame=ffi.new('XTSkyFrame[1]'),closed=false}
    function self:update(s,config,seconds,phase,enabled)
        if self.closed then return end
        local f=self.frame[0]
        for _,key in ipairs({'top','bottom','cloudColor'})do for i=0,2 do f[key][i]=s[key][i+1]end end
        for _,key in ipairs(fields)do f[key]=s[key]end
        f.seconds=seconds;f.phase=phase;f.moonSize=config.moonSize;f.interval=config.meteorInterval
        f.quality=config.quality=='low'and 0 or config.quality=='high'and 2 or 1
        f.flags=(config.stars and 1 or 0)+(config.moon and 2 or 0)+(config.meteors and 4 or 0)+(config.clouds and 8 or 0)
        local preset=({sakura=1,inferno=2,tsukuyomi=3})[config.preset]or 0
        f.flags=f.flags+preset*256
        f.enabled=enabled and 1 or 0
        self.library.bs_update(self.frame)
    end
    function self:error()return self.library.bs_error()end
    function self:lost()if not self.closed then self.library.bs_lost()end end
    function self:reset()if not self.closed then assert(self.library.bs_reset()==1,'BeautifulSky device reset failed')end end
    function self:close()if not self.closed then self.library.bs_close();self.closed=true end end
    return self
end
return M

    end
    sources["beautifulsky/presets.lua"] = function()
-- Custom sky palettes; original weather model remains unchanged.
local M={}
M.items={
 {id='none',name='Обычное небо',description='Игровое время, погода и стандартная луна.'},
 {id='sakura',name='Цветение сакуры',description='Розово-сиреневое небо, нежные облака и луна в цветах.'},
 {id='inferno',name='Ад в Аду',description='Багровый горизонт, дымные тучи и пылающее светило.'},
 {id='tsukuyomi',name='Вечное Цукиеми',description='Вечная ночь, красная луна и холодные звёзды.'}}
function M.index(id)for i,p in ipairs(M.items)do if p.id==id then return i-1 end end;return 0 end
function M.apply(s,id)
 local i=M.index(id);if i==0 then return s end
 local palettes={
  {{94,45,124},{255,174,203},{255,210,233},.48,.3,1.1},
  {{22,3,12},{174,32,12},{112,32,26},.72,0,1.7},
  {{4,3,16},{69,10,41},{63,25,58},.32,.85,.65}}
 local p=palettes[i]
 s.top={unpack(p[1])};s.bottom={unpack(p[2])};s.cloudColor={unpack(p[3])}
 s.cloud=p[4];s.stars=p[5];s.wind=p[6];s.haze=0;s.mist=0;s.dust=0;s.sun=0;s.night=1
 s.mx,s.my,s.mz=0,.8660254,.5
 return s
end
return M

