    sources["bootstrap.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: bootstrap.lua
-- Original third-party credits, where present, are retained below.
-- Runs before any optional Lua/native dependency is loaded.
local M={}
function M.prepare(a,root,packs,hash,notify)
    root=root:gsub('\\','/'):gsub('/$','')
    local function exists(path)
        local f=a.io.open(path,'rb');if not f then return false end;f:close();return true
    end
    local function read(path)
        local f=assert(a.io.open(path,'rb'));local bytes=f:read('*a');f:close();return assert(bytes)
    end
    local function ensure(path)
        if a.doesDirectoryExist(path) then return end
        local parent=path:match('^(.*)/[^/]+$');if parent and parent~=path then ensure(parent)end
        a.createDirectory(path);assert(a.doesDirectoryExist(path),'Cannot create '..path)
    end
    local function write(path,bytes)
        local f=assert(a.io.open(path,'wb'));local ok,err=f:write(bytes);local closed,why=f:close()
        assert(ok,err);assert(closed,why)
    end
    local function relative(path)
        assert(type(path)=='string' and path:match('^[%w_./%-]+$') and not path:find('..',1,true)
            and path:sub(1,1)~='/','Invalid setup path')
        return path
    end
    ensure(root..'/X-TOOL')
    for _,kind in ipairs({'settings','data','cache','logs'})do ensure(root..'/X-TOOL/'..kind)end
    for _,pack in ipairs(packs)do
        local destination=root..'/'..relative(pack.directory)
        local missing,seen={},{}
        for _,file in ipairs(pack.files)do
            relative(file.path)
            assert(not seen[file.path:lower()],'Duplicate setup path');seen[file.path:lower()]=true
            assert(type(file.bytes)=='number' and file.bytes>0 and file.bytes%1==0
                and type(file.offset)=='number' and file.offset>=0 and file.offset%1==0
                and file.offset+file.bytes<=pack.bytes and #file.sha256==64,'Invalid setup descriptor')
            local target=destination..'/'..file.path
            if not exists(target) and pack.legacyDirectory then
                local legacy=root..'/'..relative(pack.legacyDirectory)..'/'..file.path
                if exists(legacy)then
                    local old=read(legacy)
                    if #old==file.bytes and hash(old)==file.sha256 then
                        ensure(target:match('^(.*)/[^/]+$'))
                        local stage=target..'.xt-setup'
                        if exists(stage)then assert(a.os.remove(stage))end
                        write(stage,old);assert(hash(read(stage))==file.sha256)
                        if exists(target)then assert(a.os.remove(stage))else assert(a.os.rename(stage,target))end
                    end
                end
            end
            if not exists(target)then missing[#missing+1]=file end
        end
        if #missing>0 then
            notify('Подготовка '..(pack.label=='resources' and 'ресурсов' or 'библиотек')..': файлов для скачивания - '..#missing..'.')
            ensure(destination)
            local temp
            repeat temp=root..'/X-TOOL/cache/setup-'..a.getGameTimer()..'-'..math.random(100000,999999)..'.tmp' until not exists(temp)
            local finished=false
            a.downloadUrlToFile(pack.url,temp,function(_,status)
                if status==6 or status==58 then finished=true end
            end)
            local started=a.getGameTimer()
            while not finished and a.getGameTimer()-started<120000 do a.wait(100)end
            -- A timed-out native download may still own its temp file. Never reuse it.
            assert(finished,'Setup download timed out; /xtsetup to retry')
            local bytes=read(temp)
            if #bytes~=pack.bytes or hash(bytes)~=pack.sha256 then
                a.os.remove(temp);error('Setup package checksum mismatch: '..pack.label)
            end
            for _,file in ipairs(missing)do
                assert(hash(bytes:sub(file.offset+1,file.offset+file.bytes))==file.sha256,'Setup file checksum mismatch: '..file.path)
                a.wait(0)
            end
            for _,file in ipairs(missing)do
                local target=destination..'/'..file.path
                if not exists(target)then
                    ensure(target:match('^(.*)/[^/]+$'))
                    local stage=target..'.xt-setup'
                    -- This suffix belongs only to bootstrap. Recover interrupted writes.
                    if exists(stage)then assert(a.os.remove(stage))end
                    write(stage,bytes:sub(file.offset+1,file.offset+file.bytes))
                    assert(hash(read(stage))==file.sha256,'Setup write checksum mismatch: '..file.path)
                    if exists(target)then assert(a.os.remove(stage))else assert(a.os.rename(stage,target))end
                end
                a.wait(0)
            end
            a.os.remove(temp)
        end
    end
    return true
end
return M

    end
    sources["capture_native.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: capture_native.lua
-- Original third-party credits, where present, are retained below.
-- Version-specific SA-MP R1/R3 profiles, verified against the supplied DLLs.
-- Match the PE entry point and original instructions before patching.
-- Opcode signatures were also checked against the user's original samp.dll / gta_sa.exe.
local M = {}
local profiles={
    [0x31DF13]={nick=0x70F4E,health=0x6FC30,signature='\xE8\xA0\x4C\x04\0\x8B\x46\x0B'},
    [0xCC4D0]={nick=0x74E3F,health=0x73B20,signature='\xE8\x4F\x2D\x05\0\x8B\x86\x0C\x01\0\0'}
}
local function uint32(bytes)
    if type(bytes) ~= 'string' or #bytes ~= 4 then return nil end
    local a,b,c,d = bytes:byte(1,4)
    return a + b*256 + c*65536 + d*16777216
end
function M.check(read, sampBase, gameBase, feature, state)
    -- Skeletons read GTA bones only; they do not patch or inspect SA-MP nametags.
    if feature == 'skeletal' then
        if gameBase ~= 0x400000 or read(gameBase+0x1E4280,8) ~= '\x8A\x44\x24\x0C\x83\xEC\x0C\x56' then
            return false, 'Версия GTA SA не поддерживает этот скелетный рендер'
        end
        return true
    end
    if not sampBase or sampBase == 0 then return false, 'SA-MP не загружен' end
    if read(sampBase,2) ~= 'MZ' then return false, 'Неизвестный модуль SA-MP' end
    local offset = uint32(read(sampBase+0x3C,4))
    if not offset or offset < 0x40 or offset > 0x1000 then return false, 'Неизвестный заголовок SA-MP' end
    local profile=profiles[uint32(read(sampBase+offset+0x28,4))]
    if read(sampBase+offset,4) ~= 'PE\0\0' or not profile then
        return false, 'Эта функция поддерживает SA-MP 0.3.7-R1 и R3'
    end
    state = state or {}
    if feature == 'nametags' then
        local call = state.renderNickHookInstalled and '\xE8' or profile.signature
        local health = state.drawHealthBarPatchInstalled and '\xC3' or '\x55\x8B\xEC\x83\xE4\xF8\x83\xEC'
        if read(sampBase+profile.nick,#call) ~= call or read(sampBase+profile.health,#health) ~= health then
            return false, 'Код никнеймов отличается от ожидаемого; возможен конфликт или оставшийся патч после обновления'
        end
    else return false, 'Неизвестная функция' end
    return true, nil, profile
end
return M

    end
    sources["chat_animation.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: chat_animation.lua
-- Original third-party credits, where present, are retained below.
local M={};M.__index=M
function M.new()return setmetatable({rows={},lastActivity=0},M)end
function M:update(rows,now)
    local old=self.rows;local shift
    for offset=0,#old do
        if #old-offset<=#rows then
            local same=true
            for i=1,#old-offset do if old[i+offset].key~=rows[i].key then same=false;break end end
            if same then shift=offset;break end
        end
    end
    local changed=#old~=#rows or shift~=0
    for i,row in ipairs(rows)do
        local previous=shift and old[i+shift]
        row.born=previous and previous.born or (#old==0 and now-400 or now)
    end
    if changed then self.lastActivity=now end
    self.rows=rows
end
function M:frame(row,now,options)
    local progress=math.max(0,math.min(1,(now-row.born)/280))
    local alpha=options.appear and progress or 1
    if options.fade then alpha=alpha*(1-.72*math.max(0,math.min(1,(now-self.lastActivity-7000)/1200)))end
    return alpha,options.slide and (1-progress)^3 or 0
end
return M

    end
    sources["chat_style.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: chat_style.lua
-- Original third-party credits, where present, are retained below.
-- SA-MP color markup only; ordinary/server chat passes through unchanged.
local M={}
local function fold(text)
    text=text:lower()
    local upper,lower='АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ','абвгдеёжзийклмнопрстуфхцчшщъыьэюя'
    for i=1,#upper,2 do text=text:gsub(upper:sub(i,i+1),lower:sub(i,i+1)) end
    return text
end
function M.format(text,palette)
    local accent=palette and string.format('%06X',palette.accent)or 'B995FF'
    local muted=palette and string.format('%06X',palette.muted)or '817594' 
    text=tostring(text or '')
    local stripped=text
    repeat local before=stripped;stripped=stripped:gsub('^%s*{%x%x%x%x%x%x}','');if before==stripped then break end until false
    stripped=stripped:gsub('^%s+','')
    if stripped:sub(1,9):lower()~='[x-tools]' then return text end
    local body=stripped:sub(10):gsub('^%s*:%s*',''):gsub('^%s+','')
    body=body:gsub(' +Нажмите ','\nНажмите '):gsub(' +нажмите ','\nНажмите ')
    local plain=fold(body:gsub('{%x+}',''))
    local color='D8D1EB'
    if plain:find('не удалось',1,true) or plain:find('ошибка',1,true) or plain:find('недоступ',1,true) then color='FF8093'
    elseif plain:find('возможн',1,true) or plain:find('подозрен',1,true) or plain:find('внимание',1,true) then color='FFD178'
    elseif plain:find('успеш',1,true) or plain:find('сохран',1,true) or plain:find('выполнена',1,true) or plain:find('готово',1,true) then color='72E4B6' end
    body=body:gsub('{(%x%x%x%x%x%x)}',function(hex)
        local neutral={FFFFFF=true,E8E8E8=true,D9D9E5=true}
        return '{'..(neutral[hex:upper()] and color or hex)..'}'
    end)
    -- Highlight commands and player IDs while retaining each segment's active color.
    local result,active={},color
    local cursor=1
    local function segment(value)
        value=value:gsub('(ID%s+%d+)',function(id)return '{7BDFFF}'..id..'{'..active..'}'end)
        value=value:gsub('(%s)(/[A-Za-z][A-Za-z0-9_]*)',function(space,command)return space..'{7BDFFF}'..command..'{'..active..'}'end)
        value=value:gsub('^(/[A-Za-z][A-Za-z0-9_]*)',function(command)return '{7BDFFF}'..command..'{'..active..'}'end)
        return value
    end
    while true do
        local first,last,hex=body:find('{(%x%x%x%x%x%x)}',cursor)
        if not first then result[#result+1]=segment(body:sub(cursor));break end
        result[#result+1]=segment(body:sub(cursor,first-1));result[#result+1]=body:sub(first,last)
        active=hex;cursor=last+1
    end
    return '{'..accent..'}[X-TOOLS] {'..muted..'}| {'..color..'}'..table.concat(result)
end
-- Input is CP1251: one visible character occupies one byte. Bound both
-- visible length and the wire string including SA-MP color markup.
function M.lines(text,palette)
    local accent=palette and string.format('%06X',palette.accent)or 'B995FF'
    local muted=palette and string.format('%06X',palette.muted)or '817594' 
    if not text:gsub('{%x%x%x%x%x%x}',''):match('^%[X%-TOOLS%]') then return {text} end
    local _,tagEnd=text:find('%[X%-TOOLS%]')
    local body=text:sub(tagEnd+1):gsub('^%s*{%x%x%x%x%x%x}%s*|%s*',''):gsub('^%s*|%s*',''):gsub('^%s+','')
    local prefix='{'..accent..'}[X-TOOLS] {'..muted..'}| '
    local result,active={},'D8D1EB'
    local function visible(value)return #value:gsub('{%x%x%x%x%x%x}','') end
    local function render(words,first,last)
        local color=words[first].before
        local chunks={}
        -- Start each continuation in the original color; redundant tags consume
        -- SA-MP's byte limit without adding visible content.
        for i=first,last do
            local lead=''
            if words[i].before:upper()~=color:upper()then
                color=words[i].before;lead='{'..color..'}'
            end
            chunks[#chunks+1]=lead..words[i].raw:gsub('{(%x%x%x%x%x%x)}',function(hex)
                if hex:upper()==color:upper()then return ''end
                color=hex;return '{'..hex..'}'
            end)
        end
        return prefix..'{'..words[first].before..'}'..table.concat(chunks,' ')
    end
    local function fits(line)return #line<=140 and visible(line)<=85 end
    local function plain(word)return word.raw:gsub('{%x%x%x%x%x%x}','')end
    for paragraph in body:gmatch('[^\r\n]+')do
        local words={}
        for raw in paragraph:gmatch('%S+')do
            local before=active
            for hex in raw:gmatch('{(%x%x%x%x%x%x)}')do active=hex end
            -- A color at the beginning belongs in the prefix, not after it.
            while raw:match('^{%x%x%x%x%x%x}')do before=raw:sub(2,7);raw=raw:sub(9)end
            if raw~=''then words[#words+1]={raw=raw,before=before}end
        end
        -- Keep short quoted button names and commands with a numeric argument
        -- together. Long quotes still wrap normally, rather than overflowing.
        local grouped={};local i=1
        while i<=#words do
            local first,last=i,i;local value=plain(words[i])
            local close=value:sub(1,1)==string.char(171) and string.char(187) or (value:sub(1,1)=='"' and '"' or nil)
            if close and not value:sub(2):find(close,1,true)then
                for j=i+1,#words do
                    if plain(words[j]):find(close,1,true)then
                        if visible(render(words,i,j))<=65 and fits(render(words,i,j))then last=j end
                        break
                    end
                end
            elseif value:match('^/[%w_]+$')and words[i+1]and plain(words[i+1]):match('^%d+[,%.]?$')then last=i+1 end
            local chunks={};local color=words[first].before
            for j=first,last do
                chunks[#chunks+1]=(words[j].before~=color and '{'..words[j].before..'}'or '')..words[j].raw
                color=words[j].before;for hex in words[j].raw:gmatch('{(%x%x%x%x%x%x)}')do color=hex end
            end
            local unit={raw=table.concat(chunks,' '),before=words[first].before}
            if fits(render({unit},1,1))then grouped[#grouped+1]=unit
            else
                -- Only a single word longer than the complete line is split.
                local part={raw='',before=unit.before};local current=unit.before;local n=1
                while n<=#unit.raw do
                    local atom=unit.raw:sub(n):match('^{%x%x%x%x%x%x}')or unit.raw:sub(n,n)
                    local candidate={raw=part.raw..atom,before=part.before}
                    if not fits(render({candidate},1,1))then
                        if visible(part.raw)>0 then grouped[#grouped+1]=part end
                        part={raw='',before=current}
                    end
                    part.raw=part.raw..atom
                    if #atom==8 then current=atom:sub(2,7)end
                    n=n+#atom
                end
                if visible(part.raw)>0 then grouped[#grouped+1]=part end
            end
            i=last+1
        end
        -- Greedy wrapping followed by a small tail adjustment avoids a last
        -- line made of one short word. Explicit paragraph breaks stay intact.
        local ranges={};i=1
        while i<=#grouped do
            local last=i
            while last<#grouped and fits(render(grouped,i,last+1))do last=last+1 end
            ranges[#ranges+1]={i,last};i=last+1
        end
        if #ranges>1 then
            local previous,tail=ranges[#ranges-1],ranges[#ranges]
            while previous[2]>previous[1] and visible(render(grouped,tail[1],tail[2]))-12<18 do
                if not fits(render(grouped,previous[2],tail[2]))then break end
                tail[1]=previous[2];previous[2]=previous[2]-1
            end
        end
        for _,range in ipairs(ranges)do result[#result+1]=render(grouped,range[1],range[2])end
    end
    return result
end
return M

    end
