-- X-TOOLS | Project and integration: Casual_Alvarez | Module: cj_movement.lua
-- Original third-party credits, where present, are retained below.
-- GTA SA CPed::m_nAnimGroup (plugin-sdk CPed.h); opcode 0245 selects PLAYER.
local M={}
function M.new(env)
    local self={owned=nil}
    local function identity()
        local ped=env.PLAYER_PED
        if not ped or not env.doesCharExist(ped) then return end
        local pointer=env.getCharPointer(ped)
        if not pointer or pointer==0 then return end
        return ped,pointer,env.getCharModel(ped)
    end
    function self:stop()
        local old=self.owned
        self.owned=nil
        if not old then return end
        local ped,pointer,model=identity()
        if ped==old.ped and pointer==old.pointer and model==old.model
            and env.readMemory(pointer+0x4D4,4,false)==old.applied then
            env.writeMemory(pointer+0x4D4,4,old.original,false)
        end
    end
    function self:update(enabled)
        if not enabled then self:stop();return end
        if env.sampGetGamestate()~=3 then self:stop();return end
        local ped,pointer,model=identity()
        if not ped then self.owned=nil;return end
        if env.isCharDead(ped) then self:stop();return end
        if type(env.setAnimGroupForChar)~='function' then return end
        local current=env.readMemory(pointer+0x4D4,4,false)
        local old=self.owned
        if old and old.ped==ped and old.pointer==pointer and old.model==model and current==old.applied then return end
        -- A new ped/skin or an external reset supplies a new restoration value.
        self.owned=nil
        env.setAnimGroupForChar(ped,'PLAYER')
        self.owned={ped=ped,pointer=pointer,model=model,original=current,
            applied=env.readMemory(pointer+0x4D4,4,false)}
    end
    return self
end
return M

    end
