-- X-TOOLS | Project and integration: Casual_Alvarez | Module: clipboard_unicode.lua
-- Original third-party credits, where present, are retained below.
-- Explicit UTF-16 clipboard output, independent of the Windows ANSI code page.
local ffi=require('ffi')
for _,decl in ipairs({
 'int __stdcall MultiByteToWideChar(unsigned int,unsigned long,const char*,int,unsigned short*,int);',
 'void* __stdcall GlobalAlloc(unsigned int,size_t);',
 'void* __stdcall GlobalLock(void*);',
 'int __stdcall GlobalUnlock(void*);',
 'void* __stdcall GlobalFree(void*);',
 'int __stdcall OpenClipboard(void*);',
 'int __stdcall EmptyClipboard(void);',
 'void* __stdcall SetClipboardData(unsigned int,void*);',
 'int __stdcall CloseClipboard(void);'
})do pcall(ffi.cdef,decl)end
local M={}
function M.copy(text,codepage)
 local kernel=ffi.load('kernel32');local user=ffi.load('user32')
 local count=kernel.MultiByteToWideChar(codepage or 1251,0,text,#text,nil,0)
 if count<=0 then return false end
 local handle=kernel.GlobalAlloc(0x42,(count+1)*2)
 if handle==nil then return false end
 local ptr=kernel.GlobalLock(handle)
 if ptr==nil then kernel.GlobalFree(handle);return false end
 local converted=kernel.MultiByteToWideChar(codepage or 1251,0,text,#text,ffi.cast('unsigned short*',ptr),count)
 kernel.GlobalUnlock(handle)
 if converted~=count then kernel.GlobalFree(handle);return false end
 if user.OpenClipboard(nil)==0 then kernel.GlobalFree(handle);return false end
 local success=false
 if user.EmptyClipboard()~=0 then success=user.SetClipboardData(13,handle)~=nil end
 user.CloseClipboard()
 if not success then kernel.GlobalFree(handle)end
 return success
end
return M

    end
