-- X-TOOLS | Project and integration: Casual_Alvarez | Module: combo_settings.lua
-- Original third-party credits, where present, are retained below.
-- Import only the requested COMBO sections; legacy Lua is parsed as data, never run.
local M={}
function M.load(integration,kind,defaults)
    local storage=integration.storage
    local path=storage:path('settings',kind..'.ini')
    local exists=storage:exists(path)
    local data=storage:loadIni(defaults,path)
    if not exists then
        local legacy=storage:path('data','combo-import.lua',{integration.root..'/combo_report_assistant/settings.lua'})
        local old=storage:loadTable(legacy)
        if type(old)=='table' then
            local main=old[kind=='autostart' and 'autostart' or 'report']
            if type(main)=='table' then for key,value in pairs(defaults.main) do if type(main[key])==type(value) then data.main[key]=main[key] end end end
            for key,section in pairs(old) do
                local n=tonumber(tostring(key):match(kind=='autostart' and '^autostart_cmd_(%d+)$' or '^report_bind_(%d+)$'))
                if n and n>=1 and n<=(kind=='autostart' and 20 or 100) and type(section)=='table' then
                    local target={}
                    for k,v in pairs(section) do if type(v)=='string' or type(v)=='boolean' or type(v)=='number' then target[k]=v end end
                    data['row'..n]=target
                end
            end
        end
        storage:saveIni(data,path)
    end
    return data,path
end
function M.integer(g,label,data,key,default,min,max)
    local current=g.ImInt(tonumber(data[key]) or default)
    if g.InputInt(label,current,0,0) then data[key]=math.max(min,math.min(max,current.v));return true end
end
function M.toggle(g,label,data,key)
    local current=g.ImBool(data[key]==true)
    if g.Checkbox(label,current) then data[key]=current.v;return true end
end
function M.limit(value,default,min,max)
    local number=tonumber(value)
    if not number or number~=number then number=default end
    return math.max(min,math.min(max,number))
end
return M

    end
    sources["death_animation.lua"] = function()
-- X-TOOLS | Casual_Alvarez | Local decapitation animation, GTA SA 1.0 US.
-- Native signatures/offsets: Plugin-SDK common.cpp and CAnimBlendAssociation.h.
-- KO_SHOT_FACE (default group, id 19) is selected by CEventDamage for decapitation.
local M={}
function M.new(ffi,bit,native)
    local n=native or {}
    local function initialize()
        n.find=n.find or ffi.cast('void* (__cdecl*)(void*, const char*)',0x4D6870)
        n.blend=n.blend or ffi.cast('void* (__cdecl*)(void*, int, int, float)',0x4D4610)
    end
    local function field(p,offset,kind)return ffi.cast(kind..'*',ffi.cast('uint8_t*',p)+offset)end
    local function valid(p)return p~=nil and p~=ffi.NULL end
    local api={}
    function api.start(clump)
        initialize()
        local c=ffi.cast('void*',clump)
        local previous=n.find(c,'KO_shot_face')
        local assoc=n.blend(c,0,19,8.0)
        if not valid(assoc)then return end
        local flags=field(assoc,0x2E,'uint16_t')
        local speed=field(assoc,0x24,'float')
        local token={address=tonumber(ffi.cast('uintptr_t',assoc)),created=not valid(previous),flags=tonumber(flags[0]),speed=tonumber(speed[0])}
        -- Run once, retain the final pose; never change a ped task or health.
        flags[0]=bit.band(flags[0],bit.bnot(0xA))
        speed[0]=.75
        return token
    end
    function api.release(clump,token)
        if not token then return end
        initialize()
        -- Resolve again: the game may already have deleted/replaced the association.
        local assoc=n.find(ffi.cast('void*',clump),'KO_shot_face')
        if not valid(assoc)or tonumber(ffi.cast('uintptr_t',assoc))~=token.address then return end
        local flags=field(assoc,0x2E,'uint16_t')
        local speed=field(assoc,0x24,'float')
        if speed[0]==.75 then speed[0]=token.speed end
        flags[0]=bit.bor(bit.band(flags[0],bit.bnot(0xA)),bit.band(token.flags,0xA))
        if token.created then
            field(assoc,0x1C,'float')[0]=-8
            flags[0]=bit.bor(flags[0],4)
        end
    end
    return api
end
return M

    end
