-- X-TOOLS | Project and integration: Casual_Alvarez | Module: death_effect.lua
-- Original third-party credits, where present, are retained below.
-- GTA SA 1.0 US CPed layout (Plugin SDK) and CPed::PreRender (gta-reversed).
-- Visual head/bodypart flags and one animation; no damage or task replacement.
local M={};M.__index=M
function M.new(api,bit)return setmetatable({api=api,bit=bit,owned={}},M)end
function M:compatible()
    local a=self.api
    if type(a.readMemory)~='function' or type(a.writeMemory)~='function' or type(a.addBlood)~='function'then return false end
    local version=a.readMemory(0x401000,4,false)
    return version==0x53EC8B55 or version==0x16197BE9
end
function M:identity(ped)
    local a=self.api
    if not ped or ped==0 or not a.doesCharExist(ped)then return end
    local ptr=a.getCharPointer(ped)
    if not ptr or ptr<0x10000 or ptr>=0x80000000 then return end
    local clump=a.readMemory(ptr+0x18,4,false)
    if not clump or clump<0x10000 or clump>=0x80000000 then return end
    return ptr,clump,a.getCharModel(ped)
end
function M:release(ped)
    local old=self.owned[ped];self.owned[ped]=nil;if not old then return end
    local ptr,clump,model=self:identity(ped)
    if ptr~=old.ptr or clump~=old.clump or model~=old.model then return end
    local a,b=self.api,self.bit
    if old.animation and a.releaseDeathAnimation then a.releaseDeathAnimation(clump,old.animation)end
    if a.readMemory(ptr+0x754,1,false)==2 then
        a.writeMemory(ptr+0x754,1,old.part,false)
        local flags=a.readMemory(ptr+0x46C,1,false)
        a.writeMemory(ptr+0x46C,1,b.bor(b.band(flags,0x7F),old.headFlag),false)
    end
end
function M:stop()for ped in pairs(self.owned)do self:release(ped)end end
function M:update(peds,now)
    local a,b=self.api,self.bit;local seen={};local emitBudget=16
    for _,ped in ipairs(peds)do
        local ptr,clump,model=self:identity(ped)
        if ptr and a.isCharDead(ped)then
            seen[ped]=true;local old=self.owned[ped]
            if old and (old.ptr~=ptr or old.clump~=clump or old.model~=model)then self.owned[ped]=nil;old=nil end
            if not old then
                old={ptr=ptr,clump=clump,model=model,part=a.readMemory(ptr+0x754,1,false),
                    headFlag=b.band(a.readMemory(ptr+0x46C,1,false),0x80),started=now,nextBlood=now}
                self.owned[ped]=old
                if a.startDeathAnimation then old.animation=a.startDeathAnimation(ped,clump)end
            end
            a.writeMemory(ptr+0x754,1,2,false)
            a.writeMemory(ptr+0x46C,1,b.bor(a.readMemory(ptr+0x46C,1,false),0x80),false)
            if now>=old.nextBlood and now>=old.started and now-old.started<4000 and emitBudget>0 then
                old.nextBlood=now+160;emitBudget=emitBudget-1
                local x,y,z=a.headPosition(ped,ptr)
                local function finite(v)return type(v)=='number'and v==v and math.abs(v)<100000 end
                if finite(x)and finite(y)and finite(z)then a.addBlood(x,y,z,0,0,.6,16,ped)end
            end
        end
    end
    for ped in pairs(self.owned)do if not seen[ped]then self:release(ped)end end
end
return M

    end
    sources["dependencies.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: dependencies.lua
-- Original third-party credits, where present, are retained below.
-- Installs only missing files from the release-pinned library catalogue.
local M={}
function M.new(api,catalog,hash,notify)
    local self={busy=false,status='Нажмите «Проверить библиотеки».',missing={}}
    local root=api.getWorkingDirectory():gsub('\\','/')..'/lib'
    local function exists(path)local f=api.io.open(path,'rb');if f then f:close();return true end;return false end
    local function read(path)local f=assert(api.io.open(path,'rb'));local b=f:read('*a');f:close();return b end
    local function ensure(path)
        if api.doesDirectoryExist(path) then return end
        local parent=path:match('^(.*)/[^/]+$');if parent then ensure(parent)end
        api.createDirectory(path);assert(api.doesDirectoryExist(path),'Cannot create '..path)
    end
    local seen={}
    for _,f in ipairs(catalog.files)do
        assert(type(f.path)=='string' and f.path:match('^[%w_./%-]+$') and not f.path:find('..',1,true)
            and f.path:sub(1,1)~='/' and not seen[f.path:lower()],'Invalid dependency path')
        assert(type(f.bytes)=='number' and f.bytes>0 and type(f.offset)=='number' and f.offset>=0
            and f.offset+f.bytes<=catalog.bytes and #f.sha256==64,'Invalid dependency descriptor')
        seen[f.path:lower()]=true
    end
    function self:check()
        self.missing={}
        for _,f in ipairs(catalog.files)do if not exists(root..'/'..f.path)then self.missing[#self.missing+1]=f end end
        self.status=#self.missing==0 and 'Все файлы комплекта библиотек присутствуют.' or ('Отсутствует файлов: '..#self.missing)
        return #self.missing
    end
    function self:install()
        if self.busy then return end
        if self:check()==0 then notify(self.status);return end
        self.busy=true;self.status='Скачивание библиотек…'
        api.lua_thread.create(function()
            local temp
            local ok,err=pcall(function()
                ensure(root)
                repeat temp=root..'/xt-libraries-'..tostring(api.getGameTimer())..'-'..tostring(math.random(100000,999999))..'.tmp' until not exists(temp)
                local finished=false
                api.downloadUrlToFile(catalog.url,temp,function(_,status)if status==6 or status==58 then finished=true end end)
                local deadline=api.getGameTimer()+120000
                while not finished and api.getGameTimer()<deadline do api.wait(100)end
                assert(finished,'Download timeout')
                local bytes=read(temp)
                assert(#bytes==catalog.bytes and hash(bytes)==catalog.sha256,'Library package checksum mismatch')
                -- Validate every missing file before committing any of them.
                for _,f in ipairs(self.missing)do
                    assert(hash(bytes:sub(f.offset+1,f.offset+f.bytes))==f.sha256,'Library checksum mismatch: '..f.path)
                    api.wait(0)
                end
                local installed=0
                for _,f in ipairs(self.missing)do
                    local path=root..'/'..f.path
                    if not exists(path)then
                        ensure(path:match('^(.*)/[^/]+$'))
                        local stage=path..'.xt-new'
                        assert(not exists(stage),'Staging file exists: '..stage)
                        local output=assert(api.io.open(stage,'wb'))
                        assert(output:write(bytes:sub(f.offset+1,f.offset+f.bytes)));assert(output:close())
                        assert(hash(read(stage))==f.sha256,'Written library checksum mismatch')
                        if exists(path)then api.os.remove(stage)
                        else assert(api.os.rename(stage,path));installed=installed+1 end
                    end
                    api.wait(0)
                end
                self:check();self.status='Добавлено файлов: '..installed..'. Перезапустите игру.'
            end)
            if temp then api.os.remove(temp)end
            self.busy=false
            if not ok then
                if api.print then api.print('[X-Tools Libraries ERROR] '..tostring(err))end
                self.status='Не удалось установить все библиотеки.\nПроверьте интернет, доступ к папке игры и свободное место.\nПодробности: moonloader.log. Повторная попытка: /xtlibs.\nПосле установки перезапустите игру.'
            end
            notify(self.status)
        end)
    end
    function self:draw(g)
        g.Separator();g.TextWrapped('Библиотеки X-Tools');g.TextWrapped(self.status)
        if not self.busy then
            if g.Button('Проверить библиотеки##xt_dependencies')then self:check()end
            if #self.missing>0 and g.Button('Скачать недостающие библиотеки##xt_dependencies_install')then self:install()end
        end
        
    end
    return self
end
return M

    end
    sources["discord_transport.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: discord_transport.lua
-- Original third-party credits, where present, are retained below.
-- LuaSec 0.6-compatible HTTPS with chain AND DNS identity validation.
-- Primary API: https://github.com/lunarmodules/luasec/wiki/LuaSec-0.6
-- SAN layout: cert:extensions()['2.5.29.17'].dNSName (LuaSec src/x509.c).
local M = {}

function M.hostnameMatches(host, name)
    if type(host) ~= 'string' or type(name) ~= 'string' or name:find('%z') then return false end
    host, name = host:lower(), name:lower()
    if host == name then return true end
    local suffix = name:match('^%*%.([%w%-]+%.[%w%.%-]+)$')
    if not suffix then return false end
    local label, rest = host:match('^([%w%-]+)%.(.+)$')
    return label ~= nil and rest == suffix
end

function M.verifyHostname(certificate, host)
    if not certificate then return false end
    local ok, extensions = pcall(function() return certificate:extensions() end)
    if not ok or type(extensions) ~= 'table' then return false end
    local san = extensions['2.5.29.17']
    if type(san) ~= 'table' or type(san.dNSName) ~= 'table' then return false end
    for _, name in ipairs(san.dNSName) do
        if M.hostnameMatches(host, name) then return true end
    end
    -- Public Discord certificates must contain DNS SANs; no CN fallback.
    return false
end

function M.request(method, address, headers, payload, caFile)
    local host = type(address) == 'string' and address:match('^https://([^/]+)/api/webhooks/%d+/[%w_%-]+$')
    if host ~= 'discord.com' and host ~= 'discordapp.com' then
        return false, 0, '', '', 'Only HTTPS Discord webhooks are supported'
    end
    return M.perform(method,address,headers,payload,caFile,host,4*1024*1024)
end

-- The release service supplies a configured, direct HTTPS URL. Redirects are
-- deliberately not followed, so certificate and host checks cover every byte.
function M.get(address, caFile, maxBytes)
    local host,path
    if type(address)=='string' then
        local base=address
        if address:find('?',1,true) then
            base=address:match('^(https://[%w%.%-]+/[%w%._/%-]*manifest%.json)%?xt=%d+%-%d+$')
            if not base then return false,0,'','','Invalid release URL' end
        end
        host,path=base:match('^https://([%w%.%-]+)(/[%w%._/%-]+)$')
    end
    if not host or not path or path:find('..',1,true) then return false,0,'','','Invalid release URL' end
    if type(maxBytes)~='number' or maxBytes<1 or maxBytes>96*1024*1024 then return false,0,'','','Invalid download limit' end
    return M.perform('GET',address,{['User-Agent']='CasualTool'},'',caFile,host,maxBytes)
end

function M.perform(method, address, headers, payload, caFile, host, maxBytes)
    local socket = require('socket')
    local ssl = require('ssl')
    local http = require('socket.http')
    local ltn12 = require('ltn12')
    if http.PROXY then return false, 0, '', '', 'HTTPS proxy is not supported' end
    local response,received = {},0
    local function sink(chunk,err)
        if err then return nil,err end
        if chunk then
            received=received+#chunk
            if received>maxBytes then return nil,'Response exceeds release size limit' end
            response[#response+1]=chunk
        end
        return 1
    end
    local function create()
        local conn = {sock = socket.try(socket.tcp())}
        local checked = false
        local try = socket.newtry(function() pcall(function() conn.sock:close() end) end)
        function conn:settimeout() return self.sock:settimeout(12) end
        function conn:close() return self.sock:close() end
        function conn:connect(connectHost, port)
            try(connectHost == host and tonumber(port) == 443, 'Unexpected HTTPS endpoint')
            try(self.sock:connect(host, 443))
            self.sock = try(ssl.wrap(self.sock, {
                mode = 'client', protocol = 'tlsv1_2', verify = 'peer', cafile = caFile,
                options = {'all', 'no_sslv2', 'no_sslv3', 'no_tlsv1', 'no_tlsv1_1'}
            }))
            try(self.sock:settimeout(12))
            self.sock:sni(host)
            try(self.sock:dohandshake())
            try(M.verifyHostname(self.sock:getpeercertificate(), host), 'TLS certificate hostname mismatch')
            checked = true
            return 1
        end
        setmetatable(conn, {__index = function(_, name)
            return function(self, ...)
                try(checked, 'TLS identity has not been verified')
                return self.sock[name](self.sock, ...)
            end
        end})
        return conn
    end
    local ok, code, _, status = http.request({url = address, port = 443, method = method,
        headers = headers, source = ltn12.source.string(payload), sink = sink,
        create = create, redirect = false})
    local body = table.concat(response)
    if ok then return true, tonumber(code) or 0, body, tostring(status or ''), '' end
    return false, tonumber(code) or 0, body, tostring(status or ''), tostring(code or 'HTTPS failed')
end

return M

    end
    sources["dm_informer.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: dm_informer.lua
-- Original third-party credits, where present, are retained below.
-- Integrated DM Informer TOP10, adapted from the user's passive observer.
-- Bullet estimates and local damage RPCs remain independent. Kills: server feed only.
local M={}
local weights={[22]=8.25,[23]=13.2,[24]=46.2,[28]=6.6,[29]=8.25,[30]=9.9,[31]=9.9,[32]=6.6,[33]=24.75,[34]=41.25,[38]=46.2}
local weapons={[24]='Deagle',[31]='M4',[30]='AK-47',[34]='Sniper',[25]='Shotgun',[26]='Sawn-off',[27]='SPAS-12',[22]='Glock',[23]='Silenced',[28]='Uzi',[29]='MP5',[32]='TEC-9',[33]='Rifle',[38]='Minigun'}
local function finite(v)return type(v)=='number' and v==v and math.abs(v)<math.huge end
function M.new(a,p,save)
    local self={rows={},players={},moving=nil,total=0,given=0,taken=0,kills=0}
    local u8=a.require('encoding').UTF8
    local font,size,cache,nextRefresh=nil,nil,{},0
    local function release()if font then a.renderReleaseFont(font);font=nil end end
    local function own()local ok,id=a.sampGetPlayerIdByCharHandle(a.PLAYER_PED);return ok and id or nil end
    local function player(id)
        if not finite(id) or id<0 or id>999 or id%1~=0 then return end
        if id~=own() and not a.sampIsPlayerConnected(id)then return end
        local name=tostring(u8(a.sampGetPlayerNickname(id))):gsub('{%x%x%x%x%x%x}','')
        local key=name:lower()
        local row=self.players[key]
        if not row then
            local count=0;for _ in pairs(self.players)do count=count+1 end
            if count>=2048 then return end
            row={name=name,id=id,estimate=0,rpc=0,hits=0,kills=0,deaths=0};self.players[key]=row
        end
        row.id=id;return row
    end
    local function append(text,weapon)
        self.rows[#self.rows+1]={text=text,red=weapon~=24 and weapon~=31}
        if #self.rows>300 then table.remove(self.rows,1)end
    end
    function self:reset()
        self.rows={};self.players={};self.total=0;self.given=0;self.taken=0;self.kills=0;cache={};nextRefresh=0
    end
    function self:stop()self.moving=nil;release()end
    function self:bullet(id,d)
        if not p.enabled or not d or tonumber(d.targetType)~=1 then return end
        local victim,w=tonumber(d.targetId),tonumber(d.weaponId)
        if id==victim or not finite(w) or w%1~=0 or w<0 or w>255 then return end
        local s,v=player(id),player(victim);if not s or not v then return end
        local amount=weights[w];s.hits=s.hits+1
        if amount then s.estimate=s.estimate+amount;self.total=self.total+amount end
        if p.mode~=1 then append(('%s  %s[%d] → %s[%d] · %s · %s'):format(a.os.date('%H:%M:%S'),s.name,id,v.name,victim,weapons[w]or('Оружие '..w),amount and ('~%.1f'):format(amount)or'?'),w)end
    end
    function self:rpc(id,amount,weapon,give)
        if not p.enabled or not finite(amount)or amount<=0 or amount>100000 then return end
        local localId=own();if id==localId then return end
        local s,v=player(give and localId or id),player(give and id or localId);if not s or not v then return end
        s.rpc=s.rpc+amount
        if give then self.given=self.given+amount else self.taken=self.taken+amount end
        if p.mode==1 then append(('%s  %s → %s · %s · %.1f'):format(a.os.date('%H:%M:%S'),s.name,v.name,weapons[weapon]or('Оружие '..tostring(weapon)),amount),weapon)end
    end
    function self:death(killer,victim,reason)
        if not p.enabled or reason==200 or reason==201 then return end
        local v=player(victim);if not v then return end
        v.deaths=v.deaths+1
        local s=killer~=victim and player(killer)
        if s then s.kills=s.kills+1;self.kills=self.kills+1 end
    end
    function self:rating(kind)
        local rows={};local field=kind=='kills' and 'kills' or(p.mode==1 and 'rpc' or 'estimate')
        for _,r in pairs(self.players)do if r[field]>0 then rows[#rows+1]=r end end
        table.sort(rows,function(x,y)if x[field]~=y[field]then return x[field]>y[field]end;return x.name<y.name end)
        while #rows>10 do table.remove(rows)end
        return rows
    end
    function self:draw(preview,px,py)
        if not preview and not p.enabled then self:stop();return end
        if a.sampGetGamestate()~=3 or not a.isGameWindowForeground()or a.isPauseMenuActive()then return end
        if not font or size~=p.font then release();size=p.font;font=a.renderCreateFont('Verdana',size,5,true)end
        if not font then return end
        local t=a.getGameTimer();if t>=nextRefresh or nextRefresh-t>1000 then cache={damage=self:rating('damage'),kills=self:rating('kills')};nextRefresh=t+250 end
        local sw,sh=a.getScreenResolution();local height=math.max(1,a.renderGetFontDrawHeight(font))
        local function panel(id,title,rows)
            local xkey,ykey=id=='log'and'x'or(id..'X'),id=='log'and'y'or(id..'Y')
            local x,y=tonumber(p[xkey])or 30,tonumber(p[ykey])or 180
            if preview and preview~=id then return end
            if preview then x,y=px,py elseif self.moving==id then x,y=a.getCursorPos()end
            x=math.max(0,math.min(x,sw-160));y=math.max(0,math.min(y,sh-math.min(#rows+1,15)*height))
            if not preview then p[xkey],p[ykey]=x,y end
            local function line(text,color)a.renderFontDrawText(font,u8:decode(text),x,y,color);y=y+height end
            line(title..(self.moving==id and ' · Enter — сохранить'or''),0xFFB995FF)
            for _,row in ipairs(rows)do if y+height<=sh then line(row.text,row.red and 0xFFFF6060 or 0xFFE8E4EF)end end
        end
        if preview=='log' or p.logVisible or self.moving=='log' then
            local rows={{text=('Урон ~%.1f · Нанесено %.1f · Получено %.1f · Фраги %d'):format(self.total,self.given,self.taken,self.kills)}}
            for i=math.max(1,#self.rows-p.lines+1),#self.rows do rows[#rows+1]=self.rows[i]end
            if #self.rows==0 then rows[#rows+1]={text='Ожидание попаданий'}end
            panel('log','Попадания',rows)
        end
        for _,kind in ipairs({'damage','kills'})do
            if preview==kind or p[kind..'Visible']or self.moving==kind then
                local rows={}
                for i,r in ipairs(cache[kind]or{})do rows[#rows+1]={text=('%d. %s[%d]  ·  %s'):format(i,r.name,r.id,kind=='kills'and(r.kills..' фр. / '..r.deaths..' смерт.')or('%.1f'):format(p.mode==1 and r.rpc or r.estimate))}end
                if #rows==0 then rows[1]={text='Пока нет результатов'}end
                panel(kind,kind=='kills'and'ТОП-10 · Фраги'or(p.mode==1 and'ТОП-10 · Урон с вашим участием'or'ТОП-10 · Урон ~'),rows)
            end
        end
    end
    return self
end
return M

    end
    sources["dossier_ui.lua"] = function()
-- X-TOOLS | Casual_Alvarez | Measured dossier tables in the host's single scroll flow.
local D={}
function D.new(g,bridge,art)
    local U={}
    local wrap=bridge.service('ui_components.lua').wrap
    local function font(size,bold)
        local f=bridge.fontFace(size or 14,bold)
        if f then g.PushFont(f)end
        return f
    end
    function U.cursor()return g.ImVec2(g.GetCursorPosX(),g.GetCursorPosY())end
    function U.scale()return math.max(1,g.GetFontSize()/16)end
    local function point(x,y)
        local origin=g.GetWindowPos()
        return g.ImVec2(origin.x+x-g.GetScrollX(),origin.y+y-g.GetScrollY())
    end
    function U.color(tone,alpha)
        local p=bridge.palette
        local hex=type(tone)=='number' and tone or ({normal=p.text,muted=p.muted,accent=p.accent,alert=p.danger,good=p.green})[tone or 'normal'] or p.text
        local c=bridge.color(hex);c.w=alpha or 1
        return g.GetColorU32(c)
    end
    function U.rect(x,y,w,h,tone,r,alpha)
        g.GetWindowDrawList():AddRectFilled(point(x,y),point(x+w,y+h),U.color(tone,alpha),r or 0)
    end
    function U.measure(text,width,size,bold)
        local f=font(size,bold)
        local visible=tostring(text or '')
        if bridge.maskText then visible=bridge.maskText(visible)end
        local value=wrap(g,visible,math.max(1,width))
        local height=g.CalcTextSize(value).y
        if f then g.PopFont()end
        return math.max(size or 14,height),value
    end
    function U.text(x,y,w,text,tone,size,bold,click)
        local h,value=U.measure(text,w,size,bold)
        local f=font(size,bold)
        g.SetCursorPos(g.ImVec2(x,y));g.PushTextWrapPos(x+w)
        local p=bridge.palette
        local hex=({normal=p.text,muted=p.muted,accent=p.accent,alert=p.danger,good=p.green})[tone or 'normal'] or p.text
        g.PushStyleColor(g.Col.Text,bridge.color(hex));g.TextWrapped(value);g.PopStyleColor();g.PopTextWrapPos()
        if click then
            if g.IsItemHovered()then g.SetTooltip('Нажмите, чтобы открыть подробности')end
            if g.IsItemClicked(0)then click()end
        end
        if f then g.PopFont()end
        return h
    end
    function U.finish(x,y,w,h)
        g.SetCursorPos(g.ImVec2(x,y+h));g.Dummy(g.ImVec2(w,8))
    end
    function U.banner(name,meta,status)
        local pos=U.cursor();local w=g.GetContentRegionAvailWidth()
        local textW=math.max(120,w-40-(w>600 and w*.22 or 0))
        local nameH=U.measure(name,textW,22,true)
        local metaH=U.measure(meta,textW,13)
        local statusH=U.measure(status,textW,13)
        local h=16+U.measure('ЛИЧНОЕ ДЕЛО',textW,13,true)+5+nameH+4+metaH+5+statusH+16
        U.rect(pos.x,pos.y,w,h,bridge.palette.surface,8)
        local texture=art and art('lookup-header')
        if texture then
            local ratio=w/h;local aspect=texture.width/texture.height
            local crop=math.min(1,aspect/ratio)
            g.GetWindowDrawList():AddImage(texture.texture,point(pos.x,pos.y),point(pos.x+w,pos.y+h),g.ImVec2(0,(1-crop)/2),g.ImVec2(1,(1+crop)/2),U.color('accent'))
        end
        U.rect(pos.x,pos.y+16,3,h-32,'accent',1)
        local y=pos.y+16
        y=y+U.text(pos.x+20,y,textW,'ЛИЧНОЕ ДЕЛО','accent',13,true)+5
        y=y+U.text(pos.x+20,y,textW,name,'normal',22,true)+4
        y=y+U.text(pos.x+20,y,textW,meta,'muted',13)+5
        U.text(pos.x+20,y,textW,status,'accent',13)
        U.finish(pos.x,pos.y,w,h)
    end
    local function cell(value)
        if type(value)=='table'then return value end
        return {text=tostring(value or '—')}
    end
    function U.actionLayout(actions,width)
        local scale=U.scale();local gap=5*scale;local items={};local x,y,lineH=0,0,0
        local f=font(14)
        for _,action in ipairs(actions)do
            local bw=math.min(width,g.CalcTextSize(action.label).x+24*scale)
            local bh=math.max(32*scale,U.measure(action.label,math.max(1,bw-20*scale),14)+16*scale)
            if x>0 and x+bw>width then x=0;y=y+lineH+gap;lineH=0 end
            items[#items+1]={action=action,x=x,y=y,w=bw,h=bh}
            x=x+bw+gap;lineH=math.max(lineH,bh)
        end
        if f then g.PopFont()end
        return items,y+lineH
    end
    function U.table(id,title,columns,rows,empty,x,y,w)
        local pos=U.cursor();x,y=x or pos.x,y or pos.y;w=w or g.GetContentRegionAvailWidth()
        local pad=12;local inner=w-pad*2;local widths,total={},0
        for _,col in ipairs(columns)do total=total+(col.weight or 1)end
        for i,col in ipairs(columns)do widths[i]=inner*(col.weight or 1)/total end
        local scale=U.scale()
        local stacked=#columns>3 and w<(columns[#columns].actions and 1000 or 680)*scale
        local titleH=U.measure(title,inner,14,true)+24
        local headH=0
        if not stacked then
            for i,col in ipairs(columns)do headH=math.max(headH,U.measure(col.label,widths[i]-16,12,true)+16)end
        end
        local heights,cellHeights={},{};local height=titleH+headH+12
        for r,row in ipairs(rows)do
            local rh=0;cellHeights[r]={}
            for c=1,#columns do
                local value=cell(row[c]);local ch
                if value.actions then
                    local _,ah=U.actionLayout(value.actions,math.max(1,(stacked and inner or widths[c])-16))
                    ch=ah+12+(value.note and U.measure(value.note,(stacked and inner or widths[c])-16,13)+6 or 0)
                elseif value.button then
                    -- Runtime's shared button wrapper adds scaled minimum height and padding.
                    ch=math.max(32*scale,U.measure(value.button,(stacked and inner or widths[c])-12-20*scale,14)+16*scale)+8
                elseif stacked then
                    ch=U.measure(columns[c].label..': '..tostring(value.text or ''),inner-16,14,c==1 and #columns>3)+12
                else ch=U.measure(value.text or '',widths[c]-16,14,c==1 and #columns>3)+12 end
                cellHeights[r][c]=ch
                rh=stacked and rh+ch or math.max(rh,ch)
            end
            heights[r]=rh;height=height+rh
        end
        if #rows==0 then height=height+U.measure(empty or 'Нет данных',inner,14)+24 end
        U.rect(x,y,w,height,bridge.palette.surface,8,.98)
        U.text(x+pad,y+12,inner,title,'accent',14,true)
        local cy=y+titleH
        if not stacked then
            U.rect(x+pad,cy,inner,headH,bridge.palette.selection,3,.7)
            local cx=x+pad
            for c,col in ipairs(columns)do U.text(cx+8,cy+8,widths[c]-16,col.label,'muted',12,true);cx=cx+widths[c]end
            cy=cy+headH
        end
        for r,row in ipairs(rows)do
            local rh=heights[r];local cx=x+pad;local sy=cy
            if r%2==0 then U.rect(cx,cy,inner,rh,bridge.palette.button,0,.35)end
            for c,col in ipairs(columns)do
                local value=cell(row[c]);local width=stacked and inner or widths[c]
                local text=stacked and (col.label..': '..tostring(value.text or '')) or tostring(value.text or '—')
                if value.actions then
                    local ay=sy+6
                    if value.note then ay=ay+U.text(cx+8,ay,width-16,value.note,'alert',13)+6 end
                    local items=U.actionLayout(value.actions,math.max(1,width-16));local f=font(14)
                    for _,item in ipairs(items)do
                        local action=item.action
                        g.SetCursorPos(g.ImVec2(cx+8+item.x,ay+item.y))
                        if action.tone=='alert'then g.PushStyleColor(g.Col.Text,bridge.color(bridge.palette.danger))end
                        if g.Button(action.label..'##'..action.id,g.ImVec2(item.w,item.h))then action.click()end
                        if action.tone=='alert'then g.PopStyleColor()end
                        if action.tooltip and g.IsItemHovered()then g.SetTooltip(action.tooltip)end
                    end
                    if f then g.PopFont()end
                elseif value.button then
                    local f=font(14)
                    g.SetCursorPos(g.ImVec2(cx+6,sy+4))
                    if g.Button(value.button..'##'..id..'_'..r..'_'..c,g.ImVec2(math.max(16,width-12),cellHeights[r][c]-8))and value.click then value.click()end
                    if f then g.PopFont()end
                else
                    U.text(cx+8,sy+6,width-16,text,value.tone or (c==1 and 'muted' or 'normal'),14,c==1 and #columns>3,value.click or row.click)
                end
                if stacked then sy=sy+cellHeights[r][c] else cx=cx+width end
            end
            cy=cy+rh
            g.GetWindowDrawList():AddLine(point(x+pad,cy),point(x+w-pad,cy),U.color(bridge.palette.border,.3),1)
        end
        if #rows==0 then U.text(x+pad,cy+12,inner,empty or 'Нет данных','muted',14)end
        U.finish(x,y,w,height)
        return height
    end
    function U.rows(id,title,rows,empty,onSelect,x,y,w)
        local data={}
        for _,row in ipairs(rows or {})do
            local label,value=row.label,row.value
            if not label or label==''then label,value=tostring(row.text or ''):match('^([^:]+):%s*(.*)$')end
            if not label then label='Сведения';value=row.text end
            if value=='' then label='Сведения';value=row.text end
            local source=row
            data[#data+1]={{text=label,tone='muted'},{text=value or row.text,tone=row.tone,click=onSelect and function()onSelect(source)end}}
        end
        return U.table(id,title,{{label='Параметр',weight=.42},{label='Значение',weight=.58}},data,empty,x,y,w)
    end
    return U
end
return D

    end
    sources["event_notice.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: event_notice.lua
-- Original third-party credits, where present, are retained below.
local N={};N.__index=N
function N.new(storage)
 local path=storage:path('settings','event-notice.ini')
 local cfg=storage:loadIni({main={enabled=true,corner=0},sent={}},path)
 cfg.sent=type(cfg.sent)=='table'and cfg.sent or {}
 cfg.main.corner=math.max(0,math.min(3,math.floor(tonumber(cfg.main.corner)or 0)))
 return setmetatable({storage=storage,path=path,cfg=cfg,queue={},seen={}},N)
end
function N:save()return self.storage:saveIni(self.cfg,self.path)end
function N:update(schedule,epoch,ms,active)
 if not active or not self.cfg.main.enabled then self.queue={};self.item=nil;return end
 if self.item and (ms<self.item.started or ms-self.item.started>=6500 or epoch>=self.item.at)then self.item=nil end
 if not self.nextPoll or ms>=self.nextPoll or ms<self.nextPoll-1000 then
  self.nextPoll=ms+1000
  local saved={};local changed=false;self.seen={}
  for _,value in pairs(self.cfg.sent)do
   local at=tonumber(tostring(value):match('^(%d+):'))
   if at and at>=epoch-86400 then saved[#saved+1]=value;self.seen[value]=true end
  end
  for _,event in ipairs(schedule:nextEvents(epoch,false))do
   if event.seconds>0 and event.seconds<=300 then
    local at=epoch+event.seconds;local key=string.format('%.0f:%s',at,event.name)
    if not self.seen[key]then
     self.seen[key]=true;saved[#saved+1]=key;changed=true
     self.queue[#self.queue+1]={name=event.name,at=at}
    end
   end
  end
  if changed then
   self.cfg.sent={};for i,value in ipairs(saved)do self.cfg.sent['event'..i]=value end
   self:save()
  end
 end
 while not self.item and #self.queue>0 do
  local item=table.remove(self.queue,1)
  if item.at>epoch then item.started=ms;item.minutes=math.max(1,math.ceil((item.at-epoch)/60));self.item=item end
 end
end
function N:visible()return self.item~=nil and self.cfg.main.enabled end
function N:settings(g,rt)
 local enabled=g.ImBool(self.cfg.main.enabled)
 if g.Checkbox('Напоминать о событиях за 5 минут',enabled)then self.cfg.main.enabled=enabled.v;if not enabled.v then self.item=nil;self.queue={}end;self:save()end
 if self.cfg.main.enabled then
  local corner=g.ImInt(self.cfg.main.corner)
  if g.Combo('Угол уведомления',corner,'Справа сверху\0Справа снизу\0Слева сверху\0Слева снизу\0\0')then self.cfg.main.corner=corner.v;self:save()end
  if g.Button('Показать пример уведомления')then
   local nextEvent=rt.schedule:nextEvents(os.time(),false)[1]
   self.item={name=nextEvent and nextEvent.name or 'Пример мероприятия',minutes=5,at=os.time()+300,started=rt.api.getGameTimer()}
  end
 end
end
function N:draw(rt)
 if not self:visible()then return end
 local g=rt.imgui;local sw,sh=rt.api.getScreenResolution();local item=self.item
 local age=rt.api.getGameTimer()-item.started
 local a=math.max(0,math.min(1,age/350,(6500-age)/650));a=a*a*(3-2*a)
 local w=math.min(430,sw-32);local h=math.max(138,w/3)
 local corner=self.cfg.main.corner;local right=corner<2;local lower=corner%2==1
 local x=right and sw-w-16 or 16;local y=lower and sh-h-24 or 24
 x=x+(right and 1 or -1)*(1-a)*24
 local flags=0
 for _,name in ipairs({'NoTitleBar','NoResize','NoMove','NoScrollbar','NoSavedSettings','NoInputs','NoFocusOnAppearing','NoBringToFrontOnFocus'})do flags=flags+(g.WindowFlags[name]or 0)end
 g.SetNextWindowPos(g.ImVec2(0,0),g.Cond.Always);g.SetNextWindowSize(g.ImVec2(sw,sh),g.Cond.Always)
 g.PushStyleColor(g.Col.WindowBg,g.ImVec4(0,0,0,0));g.PushStyleColor(g.Col.Border,g.ImVec4(0,0,0,0))
 g.Begin('##xt_event_notice',nil,flags)
 local d=g.GetWindowDrawList();local p=rt.theme.palette
 local function color(hex,alpha)local v=rt.theme.color(g,hex);v.w=a*(alpha or 1);return g.GetColorU32(v)end
 local function pos(dx,dy)return g.ImVec2(x+dx,y+dy)end
 rt.art=rt.art or rt:service('art.lua').new(g,rt.base,rt.api)
 local art=rt.art:get('event-notice')
 if art then d:AddImage(art.texture,pos(0,0),pos(w,h),g.ImVec2(0,0),g.ImVec2(1,1),color(p.accent))
 else d:AddRectFilled(pos(0,0),pos(w,h),color(p.bg,.96),12);d:AddRect(pos(0,0),pos(w,h),color(p.accent),12)end
 local left=24;local textWidth=w-48
 local title='СОБЫТИЕ · ЧЕРЕЗ '..item.minutes..' МИН.'
 d:AddText(pos(left,24),color(p.accent),title)
 local wrapped=rt:service('ui_components.lua').wrap(g,item.name,textWidth)
 local count=0;local lineHeight=g.CalcTextSize('A').y+3
 for line in wrapped:gmatch('[^\n]+')do
  count=count+1;if count>2 then break end
  if count==2 and select(2,wrapped:gsub('\n',''))>=2 then
   while #line>0 and g.CalcTextSize(line..'…').x>textWidth do line=line:gsub('[%z\1-\127\194-\244][\128-\191]*$','')end
   line=line..'…'
  end
  d:AddText(pos(left,48+(count-1)*lineHeight),color(p.text),line)
 end
 d:AddRectFilled(pos(left,h-22),pos(left+textWidth*math.max(0,1-age/6500),h-20),color(p.accent),1)
 g.End();g.PopStyleColor(2)
end
return N

    end
    sources["family_highlight.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: family_highlight.lua
-- Original third-party credits, where present, are retained below.
-- Screen-space body overlay driven by streamed character bones. No model patches.
local M={}
-- MoonImGui does not expose the global background/overlay draw lists.
function M.frame(g,width,height,body,windowId)
 local getter=g.GetBackgroundDrawList or g.GetOverlayDrawList
 if getter then return body(getter()) end
 local f=g.WindowFlags
 g.SetNextWindowPos(g.ImVec2(0,0),g.Cond.Always)
 g.SetNextWindowSize(g.ImVec2(width,height),g.Cond.Always)
 g.PushStyleColor(g.Col.WindowBg,g.ImVec4(0,0,0,0))
 g.PushStyleColor(g.Col.Border,g.ImVec4(0,0,0,0))
 local visible=g.Begin(windowId or '##xt_family_highlight',nil,f.NoTitleBar+f.NoResize+f.NoMove+f.NoScrollbar+f.NoSavedSettings+f.NoInputs+f.NoFocusOnAppearing+f.NoBringToFrontOnFocus)
 local ok,err=true,nil
 if visible then ok,err=pcall(function()body(g.GetWindowDrawList())end) end
 g.End();g.PopStyleColor(2)
 if not ok then error(err) end
end
function M.draw(g,points,color,style,drawList)
 local function distance(a,b)return math.sqrt((a.x-b.x)^2+(a.y-b.y)^2)end
 local torso=distance(points[3],points[1]);if torso<2 or torso>600 then return end
 local width=math.max(2,math.min(65,torso*0.3))
 local d=drawList or (g.GetBackgroundDrawList and g.GetBackgroundDrawList())or (g.GetOverlayDrawList and g.GetOverlayDrawList())
 assert(d,'Family highlight requires a draw list inside its frame')
 local function point(p)return g.ImVec2(p.x,p.y)end
 if style>=2 then
  if style==7 then
   local bit=require('bit');M.draw(g,points,bit.bor(bit.band(color,0xFFFFFF),0x33000000),0,d)
  end
  for _,pair in ipairs({{1,3},{3,4},{4,5},{4,22},{22,23},{23,24},{4,32},{32,33},{33,34},{1,41},{41,42},{42,43},{1,51},{51,52},{52,53}})do
   local a,b=points[pair[1]],points[pair[2]]
   if style==5 then
    local length=distance(a,b);local count=math.max(1,math.ceil(length/8))
    for i=0,count-1 do
     local t=i/count;local u=math.min(1,(i+0.55)/count)
     d:AddLine(g.ImVec2(a.x+(b.x-a.x)*t,a.y+(b.y-a.y)*t),g.ImVec2(a.x+(b.x-a.x)*u,a.y+(b.y-a.y)*u),color,2)
    end
   elseif style==6 then
    local length=math.max(0.01,distance(a,b));local nx,ny=-(b.y-a.y)/length*2,(b.x-a.x)/length*2
    for _,sign in ipairs({-1,1})do d:AddLine(g.ImVec2(a.x+nx*sign,a.y+ny*sign),g.ImVec2(b.x+nx*sign,b.y+ny*sign),color,1)end
   else
    if style==4 then
     local bit=require('bit')
     d:AddLine(point(a),point(b),bit.bor(bit.band(color,0xFFFFFF),0x33000000),7)
     d:AddLine(point(a),point(b),color,3)
    end
    d:AddLine(point(a),point(b),style==4 and 0xFFFFFFFF or color,1.5)
    if style==3 then d:AddCircleFilled(point(a),2.5,color,10);d:AddCircleFilled(point(b),2.5,color,10)end
   end
  end
  d:AddCircle(point(points[5]),width,color,16,1.5)
  return
 end
 local function limb(a,b,r)
  a,b=points[a],points[b];local length=distance(a,b);if length<0.01 then return end
  if style==0 then
   d:AddLine(point(a),point(b),color,r*2)
   d:AddCircleFilled(point(a),r,color,12);d:AddCircleFilled(point(b),r,color,12)
  else
   local nx,ny=-(b.y-a.y)/length*r,(b.x-a.x)/length*r
   d:AddLine(g.ImVec2(a.x+nx,a.y+ny),g.ImVec2(b.x+nx,b.y+ny),color,1.5)
   d:AddLine(g.ImVec2(a.x-nx,a.y-ny),g.ImVec2(b.x-nx,b.y-ny),color,1.5)
  end
 end
 limb(1,3,width*1.6);limb(3,4,width*0.8)
 for _,pair in ipairs({{22,23},{23,24},{32,33},{33,34},{41,42},{42,43},{51,52},{52,53}})do limb(pair[1],pair[2],width*0.65)end
 if style==0 then d:AddCircleFilled(point(points[5]),width,color,16)
 else d:AddCircle(point(points[5]),width,color,16,1.5)end
end
return M

    end
    sources["family_question.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: family_question.lua
-- Original third-party credits, where present, are retained below.
local M={}
local function lower(text)
    text=text:lower()
    local upper,small='АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ','абвгдеёжзийклмнопрстуфхцчшщъыьэюя'
    for i=1,#upper,2 do text=text:gsub(upper:sub(i,i+1),small:sub(i,i+1)) end
    return text
end
function M.target(text)
    text=tostring(text or ''):match('^%s*(.-)%s*$')
    -- Reports use both "144 id family?" and "id 144 family?".
    -- Resolve an explicit numeric ID before spaces become nickname underscores.
    local normalized=lower(text)
    for _,marker in ipairs({'id','ид','айди'}) do
        local id=normalized:match('^(%d+)%s+'..marker..'$')
            or normalized:match('^'..marker..'%s+(%d+)$')
            or normalized:match('^'..marker..'%s*[:#]%s*(%d+)$')
        if id then return id end
    end
    text=text:gsub('%s*%[%d+%]$',''):gsub('%s*%(%d+%)$',''):match('^%s*(.-)%s*$')
    if text:match('^%d+$') then return text end
    text=text:gsub('%s+','_')
    if #text>24 or not text:match('^[A-Za-z0-9_]+$') or text:find('__',1,true) or text:sub(1,1)=='_' or text:sub(-1)=='_' then return end
    local count=0;for _ in text:gmatch('[^_]+') do count=count+1 end
    if count>=1 and count<=3 then return text end
end
M.defaults={'в какой фаме','какая фама','в какой семье','какая семья','фама','семья','family'}
function M.parse(question,keywords)
    local original=tostring(question or ''):gsub('{%x%x%x%x%x%x}',''):gsub('%s+',' '):match('^%s*(.-)%s*$')
    original=original:gsub('[%?%!%.,]+$',''):match('^%s*(.-)%s*$')
    local text=lower(original)
    for _,word in ipairs(keywords or M.defaults) do
        local suffix=lower(tostring(word)):gsub('%s+',' '):match('^%s*(.-)%s*$')
        if suffix~='' and text:sub(-#suffix)==suffix then
            local prefix=original:sub(1,#original-#suffix)
            if prefix:match('%s$')then
                local subject=M.target(prefix)
                if subject then return subject end
            end
        end
    end
end
return M

    end
