-- X-TOOLS | Project and integration: Casual_Alvarez | Module: family_roster.lua
-- Original third-party credits, where present, are retained below.
-- Dialog-driven roster scan. Only a complete set of pages replaces stored data.
local M={}
local function clean(s)return tostring(s or ''):gsub('{%x%x%x%x%x%x}',''):match('^%s*(.-)%s*$')end
M.clean=clean
function M.members(body)
 local out,seen={},{}
 for line in (clean(body)..'\n'):gmatch('(.-)\n')do
  local cell=clean(line:match('^([^\t]+)')or line):gsub('^%d+%.%s*','')
  local name=cell:match('^([%w_%.]+)')
  local rank=line:match('^[^\t]+\t%s*(%d+)')
  if name and rank and not seen[name:lower()]then
   seen[name:lower()]=true;out[#out+1]=name
  end
 end
 return out
end
function M.new(a)
 local self={active=false,status='Проверка не запущена'}
 local function stage(name,delay)
  self.stage=name;self.due=a.now()+(delay or 0);self.deadline=a.now()+15000
 end
 local labels={leave_initial='Отправка /tempfamily перед проверкой',settle_initial='Пауза после выхода из временной семьи',join='Отправка команды вступления',wait_join='Ожидание подтверждения вступления в чате',open='Отправка /family',menu='Ожидание меню «Семья» (3112)',members='Ожидание страницы участников (3117)',advance='Переход к следующей семье',settle_between='Пауза после выхода перед следующей семьёй',leave_final='Отправка /tempfamily для завершения',settle_final='Пауза после завершающего выхода'}
 function self:progress()
  if not self.active then return self.status end
  local label=labels[self.stage]or self.stage
  if self.stage=='response'and self.response then
   local r=self.response
   label=('Ответ на диалог %d: кнопка %d, строка %d → %s'):format(r.id,r.button,r.row,labels[r.nextStage]or r.nextStage)
  end
  local seconds=math.max(0,math.ceil((self.deadline-a.now())/1000))
  return self.status..'\nЭтап: '..label..'\nДо тайм-аута: '..seconds..' сек.'..(a.dialogOpen()and '\nОжидание закрытия игрового диалога.'or '')
 end
 function self:cleanup(reason)
  self.status=reason or self.status
  if not self.currentOnly and a.ready()then stage('leave_final',800)else self.active=false;self.stage=nil end
 end
 function self:cancel(reason,disconnected)
  if not self.active then return end
  if disconnected then self.active=false;self.stage=nil;self.status=reason or 'Проверка прервана';return end
  self:cleanup(reason or 'Проверка остановлена')
 end
 function self:start(entries,currentOnly)
  if self.active or #entries==0 or not a.ready()then return false end
  self.entries={};for _,e in ipairs(entries)do self.entries[#self.entries+1]={name=e.name,key=e.key}end
  self.currentName=nil;self.attemptedName=nil;self.index=0;self.active=true;self.currentOnly=currentOnly==true
  if self.currentOnly then self:next();return true end
  self.status='Выход из временной семьи перед проверкой';stage('leave_initial');return true
 end
 function self:next()
  self.index=self.index+1
  local e=self.entries[self.index]
  if not e then self:cleanup('Составы семей сохранены');return end
  self.entry=e;self.names={};self.seen={};self.pages={};self.pageCount=0;self.entrySaved=false
  self.status=('Проверка %d/%d: %s'):format(self.index,#self.entries,e.name)
  stage(self.currentOnly and 'open'or 'join',800)
 end
 function self:joined(name)
  if not self.active then return end
  if self.stage=='wait_join' and name==self.entry.name then
   self.currentName=name;stage('open',800)

  end
 end
 function self:tick()
  if not self.active then return end
  if not a.ready()then self:cancel('Проверка прервана: нет доступа или соединения',true);return end
  if a.now()>self.deadline then
   if self.stage=='leave_final'or self.stage=='settle_final'then
    self.active=false;self.stage=nil;self.status=self.status..' · Не удалось завершить выход из временной семьи'
   else self:cleanup('Этап: '..(labels[self.stage]or self.stage)..'. Нет ответа сервера для '..(self.entry and self.entry.name or 'начала проверки')..(self.entrySaved and '; собранный состав уже сохранён'or '; прежний состав сохранён'))end
   return
  end
  if a.now()<self.due or a.dialogOpen()then return end
  if self.stage=='leave_initial'then
   stage('settle_initial',1200)
   if a.send('/tempfamily')==false then self:cancel('Команда выхода отклонена',true)end
  elseif self.stage=='settle_initial'then self:next()
  elseif self.stage=='join'then
   self.attemptedName=self.entry.name
   stage('wait_join');if a.send('/tempfamily '..self.entry.name)==false then self:cancel('Команда вступления отклонена',true)end
  elseif self.stage=='open'then
   stage('menu');a.send('/family')
  elseif self.stage=='response'then
   local r=self.response;self.response=nil;stage(r.nextStage)
   a.respond(r.id,r.button,r.row)
  elseif self.stage=='advance'then
   if self.index<#self.entries then
    self.status='Выход из '..self.entry.name..' перед следующей семьёй'
    stage('settle_between',1200)
    if a.send('/tempfamily')==false then self:cancel('Команда выхода отклонена',true)end
   else self:next()end
  elseif self.stage=='settle_between'then self:next()
  elseif self.stage=='leave_final'then
   stage('settle_final',2000)
   if a.send('/tempfamily')==false then self:cancel('Команда выхода отклонена',true)end
  elseif self.stage=='settle_final'then
   self.active=false;self.stage=nil;self.currentName=nil
   self.status=self.status..' · Отправлен /tempfamily'
  end
 end
 function self:dialog(id,style,title,b1,b2,body)
  if not self.active then return end
  title=clean(title);body=clean(body);b2=clean(b2)
  if self.stage=='advance'and id==3112 and title=='Семья'then
   self.response={id=id,button=0,row=-1,nextStage='advance'};stage('response',500);return false
  end
  if self.stage=='menu'and id==3112 and title=='Семья'and style==4 then
   local index=0;local selected
   for line in (body..'\n'):gmatch('(.-)\n')do
    if line:find('Участники семьи',1,true)then selected=index;break end
    index=index+1
   end
   if not selected then self:cleanup('Не найден пункт «Участники семьи»');return end
   self.response={id=id,button=1,row=selected,nextStage='members'};stage('response',500);return false
  elseif self.stage=='members'and id==3117 and style==5 and title:find('Список игроков в семье',1,true)then
   if self.pages[body]or self.pageCount>=100 then self:cleanup('Повтор страницы состава; прежний список сохранён');return false end
   local members=M.members(body)
   if #members==0 then self:cleanup('Не удалось распознать состав '..self.entry.name);return end
   self.pages[body]=true;self.pageCount=self.pageCount+1
   for _,name in ipairs(members)do if not self.seen[name:lower()]then self.seen[name:lower()]=true;self.names[#self.names+1]=name end end
   -- Style 5 has a non-selectable header; listitem indices start after it.
   local nextRow;local row=-1
   for line in (body..'\n'):gmatch('(.-)\n')do
    if row>=0 then
     local cell=clean(line:match('^([^\t]+)')or line)
     if cell:match('^Далее%s*>>%s*$')then nextRow=row;break end
    end
    row=row+1
   end
   local more=nextRow~=nil or b2:find('>>',1,true)or b2:find('След',1,true)or b2:find('Стр.',1,true)
   if not more and b2~='Назад'and b2~='Закрыть'then self:cleanup('Неизвестная навигация состава; прежний список сохранён');return end
   if not more then a.commit(self.entry.key,self.names);self.entrySaved=true;self.status=self.entry.name..': сохранено '..#self.names end
   self.response={id=id,button=nextRow~=nil and 1 or 0,row=nextRow or -1,nextStage=more and 'members'or 'advance'};stage('response',500);return false
  end
 end
 return self
end
return M

    end
