-- X-TOOLS | Project and integration: Casual_Alvarez | Module: far_chat.lua
-- Original third-party credits, where present, are retained below.
-- sp_plus ChatBox: native text overlay, original message/nickname colours, no window.
local M={}
function M.new(a,p,save)
    local u8=a.require('encoding').UTF8;local bit=a.require('bit')
    local self={rows={},offset=0,moving=false,width=200,height=20}
    local font,size
    local function release()if font then a.renderReleaseFont(font);font=nil end end
    function self:clear()self.rows={};self.offset=0 end
    function self:stop()self.moving=false;self.placing=false;release()end
    function self:add(id,color,text)
        local rgba=tonumber(color)or -1
        local msgColor=bit.bor(bit.lshift(bit.band(bit.rshift(rgba,8),255),16),bit.lshift(bit.band(bit.rshift(rgba,16),255),8),bit.band(bit.rshift(rgba,24),255))
        local nickColor=bit.band(a.sampGetPlayerColor(id),0xFFFFFF)
        local line=string.format('{E4E4E4}[%s] {%06X}%s{D4D4D4}({EEEEEE}%d{D4D4D4}): {%06X}%s',a.os.date('%H:%M:%S'),nickColor,a.sampGetPlayerNickname(id),id,msgColor,u8:decode(text))
        self.rows[#self.rows+1]=line;if #self.rows>500 then table.remove(self.rows,1)end
        if self.offset>0 then self.offset=math.min(self.offset+1,math.max(0,#self.rows-p.lines))end
    end
    function self:draw(preview,px,py)
        if not preview and not p.enabled then self:stop();return end
        if not font or size~=p.font then release();size=p.font;font=a.renderCreateFont('Verdana',size,5,true)end
        if not font then return end
        local sw,sh=a.getScreenResolution();local lineHeight=a.renderGetFontDrawHeight(font)
        local count=math.max(1,math.min(p.lines,math.floor((sh-40)/math.max(1,lineHeight))-1))
        local ox,oy=p.x,p.y
        if not preview then p.x=math.max(0,math.min(p.x,sw-120));p.y=math.max(0,math.min(p.y,sh-(count+1)*lineHeight))end
        if preview then p.x,p.y=px,py end
        local interactive=not preview and (a.sampIsChatInputActive()or a.sampIsDialogActive()or self.moving)
        if interactive then
            local x,y=a.getCursorPos()
            if not self.placing and a.wasKeyPressed(2) and (self.moving or x>=p.x and x<=p.x+self.width and y>=p.y and y<=p.y+self.height)then self.moving=not self.moving;if not self.moving then save()end end
            if self.moving then
                p.x=math.max(0,math.min(x,sw-120));p.y=math.max(0,math.min(y,sh-(count+1)*lineHeight))
                if not self.placing and a.wasKeyPressed(1)then self.moving=false;save()end
            end
            if a.wasKeyPressed(33)then self.offset=math.min(math.max(0,#self.rows-count),self.offset+count)end
            if a.wasKeyPressed(34)then self.offset=math.max(0,self.offset-count)end
        end
        self.width=120;local y=p.y
        local function draw(text)
            a.renderFontDrawText(font,text,p.x,y,0xFFE4D8CC);y=y+lineHeight
            self.width=math.max(self.width,math.min(sw-p.x,a.renderGetFontDrawTextLength(font,text)))
        end
        draw(u8:decode(self.placing and 'Дальний чат · Enter — сохранить' or self.moving and 'Дальний чат · ЛКМ — сохранить' or 'Дальний чат'))
        local last=#self.rows-self.offset
        for i=math.max(1,last-count+1),last do draw(self.rows[i])end
        self.height=y-p.y
        if preview then
            if #self.rows==0 then draw(u8:decode("[12:00:00] Player_Name[123]: Пример сообщения"))end
            p.x,p.y=ox,oy
        end
    end
    return self
end
return M

    end
    sources["fastconnect.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: fastconnect.lua
-- Original third-party credits, where present, are retained below.
-- Fast_connect.cs: write uint16 zero at samp.dll + 0x2D3C45.
-- Verified against the supplied CLEO bytecode and the user's 0.3.7 DLL.
local M={}
function M.check(read,base)
    if not base or base==0 or read(base,2)~=0x5A4D then return false end
    local pe=read(base+60,4)
    if pe<64 or pe>4096 or read(base+pe,4)~=0x4550 then return false end
    if read(base+pe+8,4)~=0x5542F47A or read(base+pe+40,4)~=0x31DF13 or read(base+pe+80,4)~=0x330000 then return false end
    local address=base+0x2D3C45
    local value=read(address,2)
    return read(address-1,1)==0x3D and (value==3000 or value==0) and read(address+2,2)==0 and read(address+4,1)==0x9C
end
function M.start(api)
    local state={stopped=false}
    api.lua_thread.create(function()
        while not state.stopped do
            local base=api.getModuleHandle('samp.dll')
            if base and base~=0 then
                local ok,supported=pcall(M.check,function(a,n) return api.readMemory(a,n,false) end,base)
                if ok and supported then
                    local address=base+0x2D3C45
                    if api.readMemory(address,2,false)==3000 then
                        state.address=address;api.writeMemory(address,2,0,true)
                    end
                end
            end
            api.wait(0)
        end
    end)
    function state:stop()
        self.stopped=true
        if self.address and api.readMemory(self.address,2,false)==0 then api.writeMemory(self.address,2,3000,true) end
    end
    return state
end
return M

    end
    sources["flight_geometry.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: flight_geometry.lua
-- Original third-party credits, where present, are retained below.
local M={}
local function finite(n)return type(n)=='number' and n==n and math.abs(n)<1e8 end
function M.cameraHeading(api)
    if type(api.convertScreenCoordsToWorld3D)~='function' or type(api.getActiveCameraCoordinates)~='function' then return end
    local w,h=api.getScreenResolution()
    local x,y=api.convertScreenCoordsToWorld3D(w/2,h/2,100)
    local cx,cy=api.getActiveCameraCoordinates()
    if not (finite(x)and finite(y)and finite(cx)and finite(cy))then return end
    local dx,dy=x-cx,y-cy
    if dx*dx+dy*dy<0.001 then return end
    return math.deg(math.atan2(-dx,dy))%360
end
function M.standingZ(api,x,y,z)
    if not(finite(x)and finite(y)and finite(z))then return z end
    local ground
    if type(api.processLineOfSight)=='function' then
        -- Only the nearby floor; ignore the rider and the broom object.
        local hit,p=api.processLineOfSight(x,y,z+1.5,x,y,z-3,true,false,false,true,false,false,false)
        if hit and p and p.pos then ground=p.pos[3]end
    elseif type(api.getGroundZFor3dCoord)=='function' then
        ground=api.getGroundZFor3dCoord(x,y,z+1.5)
    end
    if finite(ground)and ground<=z+1.5 and ground>=z-3 then return math.max(z,ground+1.05)end
    return z
end
return M

    end
    sources["function_key_patch.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: function_key_patch.lua
-- Original third-party credits, where present, are retained below.
local M={}
local profiles={
 [0x31DF13]={{0x713F2,{0xE8,0x59,0x60,0xFF,0xFF},{0x90,0x90,0x90,0x90,0x90}},
    {0x797E,{0x73},{0}},{0x71369,{0x74},{0}}},
 [0xCC4D0]={{0x752E2,{0xE8,0xD9,0x60,0xFF,0xFF},{0x90,0x90,0x90,0x90,0x90}},
    {0x79A4,{0x73},{0}},{0x75259,{0x74},{0}}}
}
function M.new(api,notice)
    local self={owned={},failed=false}
    local function matches(base,offset,bytes)
        for i,v in ipairs(bytes)do if api.readMemory(base+offset+i-1,1,true)~=v then return false end end
        return true
    end
    local function write(base,offset,bytes)
        for i,v in ipairs(bytes)do api.writeMemory(base+offset+i-1,1,v,true)end
    end
    function self:stop()
        for i=#self.owned,1,-1 do
            local p=self.owned[i]
            if matches(self.base,p[1],p[3]) then write(self.base,p[1],p[2]);table.remove(self.owned,i)
            elseif matches(self.base,p[1],p[2]) then table.remove(self.owned,i)
            else error('F1/F4/F5: patch changed by another module') end
        end
        self.failed=false
    end
    function self:update(enabled)
        if not enabled then if #self.owned>0 then self:stop()end;self.failed=false;return end
        if self.failed or #self.owned>0 then return end
        local base=api.sampGetBase();if not base or base==0 then return end
        local pe=api.readMemory(base+0x3C,4,true)
        local valid=api.readMemory(base,2,true)==0x5A4D and pe>=0x40 and pe<=0x1000
        valid=valid and api.readMemory(base+pe,4,true)==0x4550
        local patches=valid and profiles[api.readMemory(base+pe+0x28,4,true)]
        valid=valid and patches~=nil
        for _,p in ipairs(patches or {})do valid=valid and matches(base,p[1],p[2])end
        if not valid then self.failed=true;notice('Блокировка F1/F4/F5: версия SA-MP или код клавиш не поддерживается.');return end
        self.base=base
        for _,p in ipairs(patches)do
            self.owned[#self.owned+1]=p
            write(base,p[1],p[3])
        end
    end
    return self
end
return M

    end
    sources["goodgame_event.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: goodgame_event.lua
-- Original third-party credits, where present, are retained below.
-- Only server announcements, never quoted report/chat text.
local M={}
function M.parse(text)
    text=tostring(text or ''):gsub('{%x%x%x%x%x%x}',''):gsub('^%[%d%d:%d%d:%d%d%]%s*','')
    local nick,id=text:match('^Гос%. новости:%s*([%w_]+)%[(%d+)%]')
    if id then return 'news',tonumber(id),nick end
    local prefix,tail=text:match('^(.-) сменил имя на%s+(.+)$')
    if not prefix then prefix,tail=text:match('^(.-) сменила имя на%s+(.+)$')end
    if not prefix then return end
    prefix=prefix:gsub('^Игрок%s+','')
    local old,number=prefix:match('^([%w_]+)%[(%d+)%]$')
    if not old then old=prefix:match('^([%w_]+)$')end
    local name=tail:match('^([%w_]+)[%.!]?%s*$')
    if old and name then return 'nickname',tonumber(number),name end
end
return M

    end
    sources["help.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: help.lua
-- Original third-party credits, where present, are retained below.
-- User-facing guide. The in-game reference and USER_GUIDE.md share this source.
local Help = {}
Help.sections = {
    {id='start',title='Начало работы',page='home',intro={
        'Выберите нужную задачу в левом меню. Рабочие действия и настройки находятся в одном разделе; общие права, данные и обновление — в «Системе».',
        'В справке ID означает текущий номер игрока на сервере, ник — имя аккаунта. Заменяйте параметры своими значениями. Квадратные скобки обозначают необязательный параметр; сами скобки вводить не нужно.'
    },topics={
        {'Уведомления о переключении','При изменении переключателя в меню внизу экрана появляется плашка: зелёная — включено, янтарная — выключено. Уведомления плавно исчезают через 3 секунды и не захватывают курсор. Также показываются изменения GodMode, WallHack, AirBreak, метлы, невидимости и переключения HUD слежки горячими клавишами.'},
        {'Выключение X-Tools','Кнопка питания под логотипом останавливает функции, HUD и автоматические команды. Повторное нажатие включает их с сохранёнными настройками. /xt и клавиша меню остаются доступны. Отменённые очереди автоматически не продолжаются.'},
        {'Часовой пояс','Главная → Настройки (значок ползунков) → Основные → Часовой пояс. Введите разницу времени ПК с МСК: +2 для опережения, -6 для отставания. Общая служба приводит локальное время модулей к МСК. Unix-время, длительности, Google Auth и расписание в UTC не сдвигаются.'},
        {'Заставка входа','До подтверждения авторизации сверху отображается X-TOOLS LOADING… с подписью by Casual Alvarez. Заставка не перехватывает клавиатуру и мышь, после входа плавно исчезает.'},
        {'Скиллы на оружие','Основные инструменты → Скиллы на оружие, с 4 уровня. /askill ник или номер аккаунта показывает 11 базовых и 11 продвинутых навыков. «Проверить» загружает только ваши навыки и разрешает установить отдельное значение 0–100, заполнить недостающие навыки до 100 или обнулить все ненулевые. /setskill меняет только собственные навыки; в меню нет ввода чужого аккаунта. Диалог, запрошенный кнопкой, автоматически считывается и закрывается. Команды отправляются по очереди с интервалом 0,8 секунды. По завершении выполняется повторная проверка. Строка «Сила» не является оружейным навыком.'},
        {'Первый запуск','В левом меню выберите нужный модуль и его вкладку «Настройки». Горячие клавиши основы находятся в Основные инструменты → Настройки → Клавиши. Разовые действия выполняются кнопками или командами.'},
        {'Перед отправкой','Проверьте подтверждённый уровень в «Системе», затем игрока, срок и причину. Игровые функции требуют подтверждённых прав. Исключения — автоввод пароля и /reconn: они доступны до авторизации администратора. Сообщение об отправке означает передачу запроса; результат зависит от ответа сервера.'},
        {'Настройки первого запуска','Проверка обновлений при запуске включена, дублирование входов и выходов в чат выключено. При подтверждении актуальной версии появляется уведомление. При обновлении ваши сохранённые настройки сохраняются.'}
    },commands={
        {'/xt','Открыть или закрыть главное окно X-Tools.'},
        {'/at','Показать напоминание, что меню открывается через /xt.'},
        {'/athelp','Открыть этот справочник.'},
        {'/atinput','Записать диагностику курсора и блокировки ввода в moonloader.log.','После команды закройте чат; запись выполняется несколько раз с интервалом.'},
        {'/atmodules','Показать в чате состояние всех частей X-Tools.','Статус загрузки не заменяет галочку включения функции в настройках.'}
    }},
    {id='tools',title='Инструменты',page='core',intro={
        'Телепортация, мероприятия, временное лидерство и серверная погода находятся в «Основные инструменты → Функции». Доступность действий зависит от уровня администратора.',
        'Локальная погода и время меняются только у вас. Их переключатели находятся в настройках; серверная погода меняется отдельно в инструментах.'
    },topics={
        {'Мероприятия','Выберите мероприятие, заполните его параметры и проверьте текст в предпросмотре. Для сообщения об окончании укажите победителя. Объявление отправляется кнопкой; раздел доступен с 4 уровня.'},
        
        {'Дальний чат и TAB Жидкое стекло','Дальний чат выводит компактные строки с цветами ников и сообщений, включая шёпот в стриме. Откройте чат или диалог, нажмите ПКМ по дальнему чату, переместите и подтвердите ЛКМ. PageUp/PageDown листают историю. TAB Жидкое стекло заменяет прежний TAB: карточки игроков с ID, ником, уровнем и пингом, поиск, плавная прокрутка и выбор положения. ПКМ — копирование ника, двойной щелчок — стандартное действие сервера. При включённой опции удержание TAB дольше 0,7 секунды закрывает таблицу после отпускания.'},
        
        {'Красивое небо · BeautifulSky','Основные инструменты → Настройки → Игровые функции → Красивое небо → Настройки. Качество, облака, звёзды, луна, метеоры, скорость облаков, размер луны и интервал метеоров. Предпросмотр и обзор суток меняют только небо; кнопка возврата включает следование игровому времени и погоде. Команды не нужны. Отключение возвращает обычное небо.'},
        {'Дальность прорисовки','В игровых функциях включите дальность прорисовки и введите справа число от 0 до 3600. По умолчанию 1200. Выключение восстанавливает прежние параметры игры.'},
        {'Коррекция текста','Основные инструменты → Настройки → Чат. После включения доступны режим (до отправки, подсказка, копирование), автозаглавная буква с точкой и подсказка при входе. Клавиши исправления ввода, возврата исходного текста и применения подсказки назначаются под кнопкой «Настройки» рядом с переключателем коррекции. Текст проверяется через Яндекс Спеллер; команды авторизации не передаются сервису.'},
        {'Ускорение транспорта и ClickWarp','Включаются в игровых функциях. Ускорение из sh.cs действует при удержании Shift + W за рулём; бинд переназначается. Для ClickWarp назначьте клавишу выбора точки, начните слежку и подтвердите маркер ЛКМ; Esc отменяет. Смена наблюдаемого игрока также отменяет перенос.'},
        {'AirBreak','Игровые функции → AirBreak. Ctrl+2 — включение и выключение, Ctrl+3 — выключение; Num 1/2/3 — скорость. WASD — движение, Q/E — высота пешком и в машине, стрелки вверх/вниз — также высота транспорта. Поворот следует за мышью; его можно отключить в настройках. Стрелки влево/вправо добавляют поворот. Пешком повторяется Swim_Tread; выключение снимает анимацию.'},
        {'Безопасная выдача','/nakaz ID/Ник — тестовый помощник: выберите игрока или члена семьи, нарушение, вид наказания и срок. Сначала включён тест без отправки. Семейная выдача добавляет семью в причину и сообщение /msg; доступна с 4 уровня. Сам помощник доступен с 2 уровня, команды — по вашим правам.'},
        {'Телепортация','Сохранённые точки, возврат позиции, маркер и /tpm доступны с 1 уровня. AdminZone (/az), /tr и /getcar требуют 3 уровень. ClickWarp в слежке также доступен с 3 уровня.'},
        {'Метла','Основные инструменты → Настройки → Игровые функции → Метла. Назначьте клавишу включения в настройках метлы. W/S меняют наклон, A/D — направление, Space ускоряет, Shift тормозит. Метла работает пешком вне слежки. Повторное нажатие выключает её; при включении и выходе проверяется ближайшая поверхность, чтобы персонаж не оставался в земле.'},
        {'HP, броня и подписи','Основные инструменты → Настройки → Игровые функции: свои подписи и полоски. Стили: «Минимализм», «Тактический», «Мягкий», «Сердце и щит». В последнем здоровье обозначено розовым сердцем, броня — голубым щитом; при HP не больше 25 цвет становится ярче. Стиль сохраняется, существующий выбор после обновления не меняется.'},
        {'Скелеты и семейная подсветка','В игровых функциях выберите вид подсветки костей: силуэт, контур, классические кости, кости и суставы, неон, пунктир, двойные линии или силуэт с костями. Там же задаётся приоритет общей или семейной подсветки, чтобы они не накладывались. Общая подсветка доступна с 1 уровня, семейная — с 4.'},
        {'Стенка серверных зон','Основные инструменты → Настройки → Игровые функции → Стенка активного квадрата капта. С 1 уровня. Доступны 10 стилей: сетка, контур, горизонтальные полосы, вертикальные лучи, диагональная сетка, ромбы, пунктир, двойной контур, лазерная решётка и пульсирующая сетка. Настраиваются высота, размер ячейки, дальность и цвет. Стенка и контроль работают только для зон, которым сервер включил мигание с видимым цветом — активного квадрата капта. Постоянные и невидимые служебные территории исключены. После остановки мигания или скрытия зоны стенка и контроль отключаются. Дальность стенки не ограничивает контроль игроков в прорисовке. Предупреждения о входе и выходе включаются отдельно и работают даже при выключенной стенке; по умолчанию оба выключены. Отслеживаются другие игроки в прорисовке: первое появление и исчезновение не считаются пересечением. Для подавления дрожания требуется пройти границу на 0,75 метра и подтвердить положение двумя проверками с интервалом 250 мс. Сообщение содержит ник, ID игрока и номер зоны. По умолчанию выключена. В интерьерах скрывается, физических препятствий не создаёт. Зоны принимаются при подключении: после перезагрузки скрипта внутри игры может потребоваться переподключение. Удалённые сервером зоны сразу исключаются из следующей отрисовки.'},
        {'Обезглавливание при смерти','Основные инструменты → Настройки → Игровые функции → Эффект обезглавливания при смерти. С 1 уровня; по умолчанию выключено. У умерших игроков в прорисовке, включая своего персонажа, скрывается голова и на 4 секунды добавляется фонтан крови. Причина смерти не учитывается; здоровье и задачи анимации не изменяются. Эффект виден только локально. При отключении и возрождении изменённые поля восстанавливаются, если модель персонажа прежняя. Поддерживается GTA SA 1.0 US Compact/Hoodlum; на несовместимой версии функция не включается.'},
        {'Панель состояния игровых функций','Рядом с переключателем «Показывать состояние игровых функций» доступен выбор стиля панели: классический, плашки, неон, тактический, индикаторы и вертикальная панель. Выбор сохраняется. Новые варианты показывают те же состояния GodMode, WallHack, AirBreak и Invisible; ID и координаты зависят от соответствующих настроек. Панель остаётся в правой нижней части экрана; горизонтальные варианты переносят элементы, если места по ширине не хватает.'},
        {'Оформление и анимация чата','Основные инструменты → Настройки → Чат. Общий переключатель и четыре независимых эффекта: плавное появление, выезд снизу, затухание после 7 секунд без новых сообщений и тёмная подложка. По умолчанию модуль выключен. Эффекты можно сочетать. При открытии ввода или просмотре истории используется стандартный чат с привычным копированием строк. Поддерживаются SA-MP 0.3.7 R1 и R3-1. При отключении возвращается стандартное отображение.'},
        {'Копирование строки чата','В «Основные инструменты → Настройки → Чат» включите копирование. Откройте чат, наведите курсор на нужную строку и нажмите ПКМ. Строка копируется без цветовых кодов, с корректной кириллицей.'},
        {'Временное лидерство','Назначение временного лидера доступно с 4 уровня. Автоматическое назначение при входе и после зарплаты включается в основных настройках.'}
    },commands={
        {'/checkw','Проверить слово или предложение через Яндекс Спеллер.','Работает при включённой коррекции текста: /checkw текст.'},
        {'/tpm','Открыть общую страницу телепортации.','Внизу — «Интерьеры и площадки для мероприятий». Интерьеры используют мир 555, открытые площадки — мир 0. Доступно с 1 уровня; перед переносом в интерьер выйдите из транспорта.'},
        {'/lego','Открыть поиск LEGO при включённой замене команды.','Основные инструменты → Настройки → Игровые функции → Заменять /lego автоматически. /lego с названием работает как обычная команда.'},
        {'/tr ID','Переместить игрока на ближайшую дорогу.','Нужно право /gethere. Игрок должен быть в зоне прорисовки; администратор — вне интерьера. Нельзя выбрать себя.'},
        {'/getcar ID_транспорта','Переместить к себе транспорт без водителя.','Транспорт должен быть в зоне прорисовки. ID транспорта и ID модели — разные значения.'},
        {'/clearhospital ID [ID…]','Последовательно запросить перемещение указанных игроков к себе.','Между запросами — 1 секунда. Перед каждым запросом проверяется, что ID по-прежнему принадлежит тому же игроку.'},
        {'/clearhospital stop','Остановить оставшиеся перемещения.'},
        {'/rskin ID_скина радиус','Выдать один временный скин игрокам в указанном радиусе.','С 4 уровня. Скины: 1–311, кроме 74; радиус: 3–80 метров. Повторная команда во время выдачи останавливает её.'},
        {'/rskins ID_скина_1 ID_скина_2 радиус','Поочерёдно выдавать два временных скина игрокам рядом.','С 4 уровня. Те же ограничения, что у /rskin. Повторная команда останавливает выдачу.'},
        {'/carsp ряды машин_в_ряду модель цвет_1 цвет_2','Создать транспорт рядами.','С 4 уровня. Модель: 400–611; цвета: 0–255. Повторная /carsp останавливает создание.'},
        {'/apay ID сумма','Передать деньги игроку несколькими платежами.','Игрок должен находиться рядом. Повторная /apay останавливает передачу.'},
        {'/findd ID_организации','Собрать сведения об онлайне организации и показать результат.','С 4 уровня. ID организации: 1–13. Обрабатываются страницы списка; число людей в заголовке может меняться.'},
        {'/afindd ID_организации','Собрать сведения об онлайне организации и отправить отчёт в /a.','С 4 уровня. ID организации: 1–13.'},
        {'/guns','Запросить выдачу оружия себе.','Нужны серверные права на выдачу оружия.'},
        {'/reconn','Переподключиться к текущему серверу.','Доступно без авторизации администратора. Текущие автоматические очереди при разрыве соединения отменяются.'}
    }},
    {id='rephelp',title='Биндер',page='rephelp',intro={
        'Редактируемые команды ответов из RepHelp. Включите модуль, выберите команду, измените текст и сохраните. «Новая команда» добавляет шаблон. В поле «Команда запуска» укажите, например, /gg. Каждая строка редактируется в отдельном поле; + добавляет строку, × удаляет. Слева — список команд, справа — редактор. Вызов: /имя ID.',
        'Одна строка — серверная команда или обычный ответ через /ans. Подстановки: {id}, {time}, {date}; время учитывает общую настройку часового пояса. Новые команды и изменения сохраняются.'
    },topics={{'Исходные команды','gg, gt, mpjail, tir, rm, pg, ych, nak, oft, zb, tra, liv, vch. /mpjail выполняет /jail на 20 минут и /unjail. Перед использованием проверьте шаблон.'}},commands={}},
    {id='reminders',title='Напоминание игрокам в msg',page='reminders',intro={
        'Кнопка «Создать новый набор» добавляет ваш набор: введите название, нажмите «Создать» и заполните текст. Название и текст сохраняются после перезапуска. Выберите набор: защита аккаунта, репорт, мошенники, технические работы или выборы. Проверьте текст и нажмите «Отправить набор». В поле «Режим / радиус» задайте 0 — стандартное сообщение всем, 1 — важное всем или одно число от 20 до 300 — радиус видимости. Например: /msg 200 текст. Интервал — не менее трёх секунд. Требуется 4 уровень.',
        
    },commands={}},
    {id='autoreply',title='Автоответ',page='autoreply',settings='autoreply',intro={
        'Отдельные выключатели пожеланий на гос. новости и смену nickname работают независимо от правил обычного автоответа. Текст пожелания редактируется; повторные новости одного автора ограничены интервалом 90 секунд. Используются общие настройки задержки и защиты после AFK.',
        'Автоматические ответы на обращения по правилам из AutoSalamReport. Выберите правило слева: доступны создание, редактирование и удаление. Для нового профиля система выключена; прежние настройки COMBO импортируются один раз.'
    },topics={
        {'Правила','Ключи через запятую; частичное или точное совпадение без учёта регистра и пунктуации. До пяти случайных ответов. Подстановки: %id%, %text%, %time%, %date%. Для каждого правила можно включить свою задержку ответа или действия от 0 до 300 секунд; иначе применяется общая задержка.'},
        {'Помощь по репорту','В разделе «Автоответ» включается предложение помощи по просьбам и жалобам. По умолчанию Q+E включает /sp: для просьбы о помощи — за автором репорта, для жалобы с ID — за указанным игроком. На принятие даётся 5 секунд; срок меняется от 1 до 60 секунд, клавиши тоже настраиваются. После истечения появляется сообщение «Запрос устарел». В «Ключевые слова репортов» можно добавить свои слова отдельно для помощи и жалоб, затем сохранить.'},
        {'Настройки','Задержки ответа и после возврата в игру, интервалы по игроку и тексту, фильтр цвета, смещение времени и отладка. Ответ отменяется при отключении или смене игрока на ID.'}
    },commands={}},
    {id='punishments',title='Автовыдача',page='aegis',settings='aegis',intro={
        'В модуле «Автовыдача» проверяются запросы, их цель, срок и причина. Обработка сообщений и постоянные параметры находятся на вкладке «Настройки».',
        'Очередь из текстового файла находится в самостоятельном разделе. Её запуск и отметки результатов описаны в теме «Очередь из файла».'
    },topics={
        {'Обработка запросов','В «Автовыдача → Настройки» включите обработку сообщений из /a. Там же настраиваются ручные команды, уведомления игроку, звук и диагностика. Выключение обработки снимает ожидающий подтверждения запрос; уже поставленная очередь не очищается.'},
        {'Проверка перед баном','Перед /ban, /offban и /sban выполняется /baninfo. При действующем бане первая попытка останавливается: показываются автор и оставшиеся дни. Повторите команду на тот же ник в течение 2 минут; для запроса из админ-чата повтор должен прийти от того же администратора и снова подтверждается обычной клавишей автовыдачи. Автор запроса получает две строки в /a с информацией о бане и просьбой повторить запрос. При повторе сведения проверяются заново, оставшийся срок складывается с новым. Если осталось больше 29 дней, сначала отправляется /unban (требуется 4 уровень), затем повторный /baninfo должен подтвердить снятие. Без ответа или при смене игрока по ID новый бан не отправляется. Суммарный срок не обрезается до 30; допустимость срока определяет сервер.'},
        {'Защищённый список','В модуле «Автовыдача» нажмите «Перечитать списки», чтобы перечитать сохранённые сведения об администраторах и лидерах из чекера. Защита запрещает ban/warn в том числе при ручном вводе команды.'},
        {'Подтверждение и уровни','Запросы из /a принимаются с 3 уровня. Delete или кнопка «Выдать» подтверждает запрос, End отменяет; клавиши можно изменить. Отдельной выдачи без подтверждения нет. С 2 уровня доступны настройки обработки ручных наказаний: переключение онлайн/офлайн и уведомление игроку.'},
        {'Уровни наказаний','Jail, mute и kick — со 2 уровня; warn, ban, skick, offjail и offmute — с 3; sban, offwarn, offban и unban — с 4. Итоговая команда проверяется повторно, в том числе после переключения онлайн/офлайн. Настройка подписи запрашивающего администратора доступна с 3 уровня.'},
        {'Запрос /tr через автовыдачу','После подтверждения выполняется последовательность: /sp за целью → 5 секунд → /tr → /slap без дополнительной задержки → 3 секунды → выход из слежки. Это отдельный сценарий от опции сопровождения ручного /tr.'},
        {'Команды банд','GJ выдаёт jail со 2 уровня, GW/GB — warn/ban с 3. При недостаточных правах отправляется просьба через /a. При первом запуске команды /gw, /gb и /gj выключены. Включите их общей галочкой в «Гетто → Настройки». Выбранное состояние сохраняется после перезапуска. Перед отправкой проверьте игрока и срок наказания.'}
    },commands={
        {'/gw ID','Выдать предупреждение за нарушение правил капта.','Включите команды в «Гетто → Настройки». Игрок должен быть онлайн. Если цвет банды распознан, её тег добавляется к причине.'},
        {'/gj ID минуты [причина]','Тюрьма с тегом банды.','1 уровень: просьба через /a; со 2 уровня: самостоятельная выдача. По умолчанию причина — нарушение правил капта.'},
        {'/gb ID дни','Блокировка за читы: просьба или выдача по уровню.','Включите команды в «Гетто → Настройки». Дни — положительное целое число; игрок должен быть онлайн. Если цвет банды распознан, её тег добавляется к причине.'},
        {'/2warns ID причина','Последовательно выдать два предупреждения.','С 3 уровня. Причина обязательна.'},
        {'/mban ID_1 ID_2 [ID_3] [ID_4] дни причина','Запросить блокировку от двух до четырёх игроков.','С 4 уровня. Между запусками — не менее 60 секунд.'},
        {'/warnlast причина','Запросить офлайн-предупреждение последнему игроку из слежки.','Доступно с 4 уровня.'},
        {'/banlast дни причина','Запросить офлайн-блокировку последнему игроку из слежки.','Доступно с 4 уровня.'},
        {'/jaillast минуты причина','Запросить офлайн-заключение последнему игроку из слежки.','Доступно с 3 уровня.'},
        {'/mutelast минуты причина','Запросить офлайн-ограничение чата последнему игроку из слежки.','Доступно с 3 уровня.'},
    }},
    {id='checker',title='Чекер',page='adm',settings='adm',intro={
        'Чекер показывает администраторов, лидеров и друзей. Откройте «Чекер». Отображение списков, положение панели, шрифт и автоматическое получение данных настраиваются в «Чекер → Настройки».',
        'Все функции X-Tools, включая чекер, работают на разрешённых адресах: Advance RolePlay Blue (blue.adv-rp.com / 185.169.134.239), Red (185.169.134.237) и Test (185.169.134.195), порт 7777. Список задаётся в коде; на остальных адресах программа останавливается.'
    },topics={
        {'Управление записями','Выберите список администраторов, лидеров или друзей. Используйте поиск, форму добавления и кнопки редактирования или удаления. Для администратора задаётся уровень, для лидера — фракция.'},
        {'Состояние и локальные списки','В рабочем разделе раскройте «Состояние чекера», чтобы посмотреть переключатели, положение панели, шрифт и количество записей. «Перечитать списки» загружает сохранённые записи администраторов, лидеров и друзей; запросов к серверу эта кнопка не отправляет.'},
        {'Получение списков с сервера','В «Чекер → Настройки» включите «Получать списки с сервера», затем нажмите «Обновить списки». Автоматическое получение данных включается отдельно. Это обновление содержимого чекера, а версия X-Tools проверяется в общей системе.'},
        {'Отсутствие в /admins','Сохранённого администратора можно автоматически удалить по отсутствию в /admins только если в начале и конце обработки ответа он подключён под тем же ником и ID, а его игровой уровень в TAB больше 1. При уровне 0/1, ошибке чтения, отключении или авторизации во время получения списка запись и защита сохраняются. Закреплённые записи и исключения по административным уровням по-прежнему не удаляются таким способом.'},
        {'Чистый онлайн лидеров','С 3 уровня в чекере доступна вкладка «Чистый онлайн». Выберите фракции и запустите проверку: по никам лидеров отправляются /get, из ответов берётся время в игре минус AFK за сегодня и вчера. Для отправки отчёта в Discord укажите webhook в этом разделе.'}
    }},
    {id='lookup',title='Проверка игрока',page='lookup',settings='lookup',intro={
        'Проверка игрока собирает профиль аккаунта, IP, связанные аккаунты, историю ников, авторизации и блокировки.',
        'Введите ник или номер аккаунта и нажмите «Проверить». Откроется подробное досье: профиль, статистика, блокировки, сравнение IP, связанные аккаунты, авторизации и наказания. Для продолжения сбора после профиля включите автосбор в настройках.'
    },topics={
        {'Уровень доступа','/cadm, /reg, /offreg, /get и связанные проверки IP доступны с 3 уровня. /offst, история ников, история наказаний и /ilog — с 1. /admget и /iplog требуют 5 уровень. Авторизации показываются только на 5 уровне. Окончательное разрешение команды проверяет сервер.'},
        {'Личное дело','Все сведения находятся в одном большом окне с общей прокруткой: профиль, фракция и имущество, регистрационные IP, баны, связанные аккаунты и история. Кнопки аккаунта расположены прямо в его строке: копирование, профиль, регистрационные данные, полная проверка, уровень/фракция, баны и /sban с подтверждением. Подробности открываются в этом же окне; «Вернуться к личному делу» возвращает исходного игрока и место в списке. Полная проверка открывает новое досье выбранного аккаунта. На узком окне сведения и действия располагаются карточками.'},
        {'История и сохранение','История ников запрашивается автоматически после остальных данных проверки и показывается внизу личного дела целиком. Кнопка позволяет обновить её повторно. Авторизации и наказания также доступны в общей прокрутке. Верхние кнопки копируют досье, сохраняют TXT или отправляют сводку в /a.'},
        {'Очередь запросов','Проверку можно остановить кнопкой. Ручной ввод команды проверки отменяет оставшийся автосбор. Запросы /offst ждут завершения семейного запроса, чтобы не перепутать ответы.'},
        {'Связанные аккаунты','Разделы всегда раскрыты. «Регистрации с IP · /ip» и «Входы с IP · /lip» можно обновить отдельно от досье. Над списками находятся «Проверить всё», «Уровни и фракции» и «Действующие баны»; счётчики показывают проверенные аккаунты, ожидающие запросы и найденные блокировки. Проверки одной записи доступны в её строке и не прокручивают окно. Действующие баны выделяются красным, администратор, срок и причина остаются видны.'},
        
    },commands={
        {'/cadm','Открыть проверку игрока.'},
        {'/get ник_или_номер_аккаунта','Запросить серверную статистику аккаунта.','С 3 уровня. Для сбора досье через интерфейс используйте /cget.'},
        {'/offst ник_или_номер_аккаунта','Запросить офлайн-статистику аккаунта.','С 1 уровня. Запрос также используется семейными функциями; X-Tools согласует очереди, чтобы не смешивать ответы.'},
        {'/admget ник_или_номер_аккаунта','Запросить расширенные сведения аккаунта.','С 5 уровня.'},
        {'/iplog ник_или_номер_аккаунта','Запросить историю входов аккаунта.','С 5 уровня.'},
        {'/cget ник_или_номер_аккаунта','Запустить полную проверку аккаунта.'},
        {'/cas ID','Запустить полную проверку игрока онлайн.'},
        {'/reg ID','Запросить регистрационные данные игрока онлайн.','С 3 уровня. Открывается отдельное окно регистрации без общего окна проверки игрока.'},
        {'/offreg ник_или_номер_аккаунта','Запросить регистрационные данные аккаунта независимо от онлайна.',''},
        {'/cip IP','Запросить сведения об указанном IPv4-адресе.'},
        {'/clip IP','Запросить связанные с IPv4-адресом аккаунты.'},
        {'/namestore ник_или_ID','Запросить историю ников.','С 1 уровня. Открывается только история ников. Числовой ID заменяется ником, если этот игрок подключён.'},
        {'/ilog ID','Показать последние административные действия над игроком.','С 1 уровня.'},
        {'/iskill ID','Показать навыки владения оружием у игрока.'}
    }},
    {id='observation',title='Режим слежки',page='menu',settings='menu',intro={
        'Откройте «Режим слежки» в левом меню. Здесь собраны панели наблюдения, кнопки действий, клавиши цели, направление взгляда и график пинга. Траектории выстрелов имеют отдельный модуль, а контроль аптечек находится в «Гетто» и «Семьях».',
        'Траектория показывает данные выстрела, полученные от игры. Подозрение на сбив аптечки требует проверки; предупреждение выдаётся только вручную.'
    },topics={
        {'Панели наблюдения','В «Режим слежки» включите замену серверного меню наблюдения. Кнопки действий можно добавлять, редактировать, удалять и менять местами; панель бывает горизонтальной и вертикальной. Цель берётся из текущей слежки. Предпросмотр не отправляет игровые команды.'},
        {'Общий редактор HUD','Нажмите «Настроить отображаемое» в разделе «Режим слежки». Появятся примеры доступных панелей в их рабочем стиле, без дублей действующих панелей. Перетаскивайте их ЛКМ; Enter сохраняет позиции и возвращает в меню. Положения сохраняются после перезапуска.'},
        {'Права на действия','Слежка и просмотр информации — с 1 уровня; SPAWN/RESPAWN — со 2; FREEZE, GETHERE, GOTO, SKICK и перенос из воды — с 3; HP — с 4. Пользовательская кнопка не обходит ограничения команды.'},
        {'Контроль аптечки','Включите контроль в модуле «Гетто» либо «Семьи»; одновременно активен один режим. По умолчанию Q+E запрашивает слежку за последним подозреваемым. После подтверждения цели сервером H позволяет вручную выдать предупреждение в течение 10 секунд. Клавиши не работают при открытом меню или вводе текста.'},
        {'Горячие клавиши слежки','Основные клавиши смены цели настраиваются в «Горячих клавишах». Переключатели клавиш контроля аптечки и помощника каптов находятся в настройках соответствующих функций.'}
    },commands={
        {'/menumove','Перемещать открытые панели наблюдения за заголовки.','Повторная команда завершает перемещение и сохраняет позиции.','/movemenu'},
        {'/btrack','Открыть настройки траекторий выстрелов.'},
        {'/klist','Открыть список убийств текущего капта, который ведёт основа.'},
        {'/rk ID','Проверить, встречался ли игрок в списке погибших текущего капта.'}
    }},
    {id='capture',title='Капты',page='capture',settings='capture',intro={
        'В модуле «Гетто» собираются фраги, наказания и онлайн банд во время капта. Сначала включите функции гетто в заголовке раздела; затем выберите текущий захват, онлайн или восстановление.',
        'Discord по умолчанию выключен. Чтобы отправлять отчёты, включите отправку в настройках и сохраните webhook нужного канала.'
    },topics={
        {'Поздний вход','Если капт уже идёт, выберите «Начать сбор после старта». Этот режим собирает доступную статистику без автоматических Discord-логов капта.'},
        {'Восстановление','При отключении сохраняется состояние незавершённого капта. После входа откройте восстановление и выберите сохранение. Удаление сохранения также прекращает текущий сбор.'},
        {'Никнеймы и скелеты','Свои подписи, полоски и подсветка костей настраиваются в «Основные инструменты → Настройки → Игровые функции». Их включение не требует включать «Гетто». Для функций с патчами требуется поддерживаемая версия клиента.'},
        {'Информер попаданий','В настройках боевого информера доступны история попаданий, счётчик урона и отдельные ТОП-10 по урону и фрагам. Урон оружием, отличным от Deagle и M4, выделяется красным. Сброс выполняется кнопкой; положение панелей можно сохранить в общем редакторе HUD.'}
    },commands={
        {'/getfrags [me | a | discord]','Показать онлайн банд в личном чате, отправить в /a или Discord.','Без аргумента используется me — результат виден только локально.'},
        {'/getfrags top','Показать текущий рейтинг по фрагам.','Доступно во время активного капта.'},
        {'/getfrags solo ID','Показать фраги выбранного игрока.','Нужны активный капт и игрок онлайн.'},
        {'/captassist','Начать сбор после старта капта.'},
        {'/captfinish [итог]','Завершить активный или восстановленный капт с указанным итогом.'},
        {'/captstatus','Показать локальную сводку состояния капта.'},
        {'/captresume','Восстановить незавершённый капт из сохранения.'},
        {'/captdrop','Удалить сохранение незавершённого капта и прекратить текущий сбор.'},
        {'/lastcapt','Запросить отправку последнего отчёта в Discord.','Это отправка отчёта, а не только его просмотр.'},
        {'/captscan66','Включить сбор исключений из списка игроков.','С 4 уровня. После команды откройте серверный список игроков — диалог 66.'}
    }},
    {id='families',title='Семьи',page='familia',settings='familia',intro={
        'Работа с семьями включает сведения о семье игрока и семейные наказания. Для автоматического отображения включите функцию в настройках.',
        'Все семейные команды требуют включённого модуля. Jail доступен со 2 уровня, warn/ban — с 3; офлайн-jail — с 3, офлайн-warn/ban — с 4. При недостаточных правах отправляется запрос через /a. Уведомление семье через /msg — с 4 уровня.'
    },topics={
        {'Реестр семей','В «Семьи → Реестр семей» добавьте названия и выберите цвета. Проверка составов доступна с 4 уровня. Для каждой семьи скрипт выходит из временной семьи командой /tempfamily без параметров, вступает в выбранную семью, ждёт подтверждение, открывает /family → «Участники семьи» и собирает все страницы через «Далее». После последней страницы сохраняет состав; после последней семьи снова выходит через /tempfamily. Текущий этап и ошибки отображаются в разделе. При неполном ответе прежний состав сохраняется.'},
        {'Текущая семья','Проверка текущей семьи не меняет членство: состав сохраняется в запись «Неизвестная семья». Для подсветки персонажей включите семейную подсветку и выберите цвет и вид. Приоритет относительно общей подсветки задаётся в настройках костей.'},
        {'Подозрение на рванку','Экспериментальный переключатель: Основные инструменты → Настройки → Игровые функции, по умолчанию выключен. Анализирует последовательности синхронизации пешком и транспорта: минимум 4 аномальных горизонтальных перемещения и 2 разворота за 1,8 секунды. Одиночный рывок и прямолинейный разгон не вызывают предупреждение. Паузы между пакетами и пинг выше 350 мс сбрасывают наблюдение. Повтор — не чаще раза в 5 секунд на игрока. Для незанятого транспорта указаны ID машины и отправитель синхронизации, который не обязательно виновник. Это только повод проверить ситуацию, а не доказательство чита; возможны ложные срабатывания и пропуски.'},
        {'Запрещённое оружие','В «Семьи» есть отдельный переключатель предупреждений о Rifle (33) и Sniper Rifle (34). Проверяются оружие в руках игроков в зоне прорисовки и события выстрелов. В сообщении указаны ник, ID и оружие; повторы ограничены одним сообщением на игрока в 5 секунд. По умолчанию выключено.'},
        {'Игроки в маске','В разделе «Семьи» можно включить предупреждения о находящихся в зоне прорисовки игроках в маске. Каждые 5 секунд выводятся их ники и ID. Используется существующее определение маски по исходному цвету ника, в том числе при включённой замене цвета. После выхода игрока из зоны прорисовки или снятия маски сообщения о нём прекращаются. По умолчанию выключено.'},
        {'Уведомление о наказании','С 4 уровня в настройках семей можно выбрать /msg 0, /msg 1 или /msg 300. Канал сохраняется.'}
    },commands={
        {'/fama ID_получателя ID_или_ник','Отправить получателю ответ /ans о семье выбранного игрока.','Получатель и цель по ID должны быть онлайн. Ник можно проверить офлайн. В настройках семей отдельно включается ответ на вопросы о семье из репорта.'},
        {'/fj ник_или_ID минуты причина','Запросить заключение с указанием семьи.','По нику офлайн используется /offjail; если игрок найден онлайн — /jail с его ID.'},
        {'/fw ник_или_ID причина','Запросить предупреждение с указанием семьи.','По нику офлайн используется /offwarn; если игрок онлайн — /warn.'},
        {'/fb ник_или_ID дни причина','Запросить блокировку с указанием семьи.','По нику офлайн используется /offban; если игрок онлайн — /ban.'}
    }},
    {id='events',title='Входы и выходы',page='joinquit',settings='joinquit',intro={
        'Откройте «Входы и выходы». Раздел хранит журнал событий игроков. В настройках отдельно выбираются события, фильтры фракций и вид журнала на экране.',
        'Для входов и выходов используются отдельные столбцы галочек. Кнопки над таблицей включают или выключают все фракции. Галочки в строке «Выбрать все» действуют на отдельный столбец. Длинный журнал разделён на страницы.'
    }},
    {id='queue',title='Очередь из файла',page='queue',intro={
        'С 4 уровня откройте «Очередь из файла». Создайте пустой шаблон, внесите свои команды и перечитайте файл. Запуск выполняется вручную.',
        'Рабочий файл — moonloader/X-TOOL/data/command_queue.txt. Прежний command_queue.txt рядом со скриптом, либо offban_commands.txt, копируется сюда при первом запуске. После переноса редактируйте файл в общей папке. Одна команда с / на строку; комментарии начинаются с # или //. Допустимы UTF-8 и CP1251, до 144 байт CP1251 на команду.'
    },topics={
        {'Редактор и интервал','Файл редактируется в игре и внешним редактором. При внешнем изменении сохранение отменяется. Интервал — 1–300 секунд. Пока открыт редактор, сначала сохраните или закройте его, затем запускайте очередь.'},
        {'Подтверждение результата','Совпадения ника в чате недостаточно: проверяются действие, цель и администратор. При таймауте записывается отсутствие подтверждения, а не успех.'},
        {'Интервал и остановка','На ответ отводится до 22 секунды, затем выдерживается пауза заданный интервал. Остановка отменяет оставшиеся строки. Уже переданный запрос на наказание может завершиться.'},
        {'Отметки в файле','Строка с итоговой отметкой [результат] повторно не отправляется. Отметка сохраняется до передачи команды и означает попытку, а не доказанное исполнение. Сверяйте результат с сервером.'},
        {'Продолжение после сбоя','После переподключения продолжение выполняется вручную. Если файл изменился в редакторе во время работы, очередь останавливается. Перед записью сохраняется копия с окончанием .casualat.bak.'}
    },commands={
    }},
    {id='settings',title='Настройки и клавиши',page='core',settings='keys',intro={
        'Откройте модуль и его вкладку «Настройки». Постоянные функции включаются галочками, изменения сохраняются сразу, если рядом нет отдельной кнопки сохранения. Общие права, хранение данных и обновление находятся в «Системе».'
    },topics={
        {'Оформление','Цвет, шрифт, фон и масштаб выбираются в настройках оформления. Размер окна меняется перетаскиванием границы. Кнопка внизу бокового меню сворачивает его. Размер и положение окна сохраняются.'},
        
        
        {'Fast Connect','Работает автоматически с самого запуска X-Tools без переключателя. Патч применяется только при совпадении проверенной версии и байтов samp.dll.'},
        {'После /tr','Основные инструменты → Настройки → Основные: опция «После /tr: подбросить игрока и обновить слежку». После перемещения отправляются /slap ID и /sp ID с интервалом 350 мс. При отключении или смене игрока очередь отменяется.'},
        {'Конфликты клавиш','Нажмите сочетание, затем новую клавишу. Escape отменяет ввод. Если сочетание занято, перенос назначения требует отдельного нажатия; ошибка сохранения оставляет прежние клавиши.'},
        {'Временная семья','С 4 уровня: Основные инструменты → Функции → Лидерство и семья. Введите название и нажмите «Назначить». Последний выбор и история сохраняются. Автовступление возвращает в выбранную семью после подтверждённого сервером выхода из временной семьи; во время проверки реестра оно приостанавливается. Автоматический режим можно выключить.'},
        {'Локальная погода и время','Основные инструменты → Функции → Локальные время и погода. Снятие галочки возвращает серверное значение.'},
        {'Режим стримера','Основные настройки: скрывает IP в чате и интерфейсе. Данные сохраняются для правильной обработки запросов.'},
        {'Основные','Здесь находятся временный скин, координаты, собственный ID, панель состояния и автоввод пароля. Для временного скина и автоматического лидерства нужен 4 уровень. График пинга, клавиши и взгляд наблюдаемого игрока перенесены в «Режим слежки».'},
        {'Статистика наказаний','Основные инструменты → Функции → Статистика. Помимо счётчиков доступен журнал выданных вами наказаний с временем, игроком, видом наказания и причиной.'},
        {'Горячие клавиши','Выберите действие, нажмите назначение и затем нужную клавишу или сочетание. Esc отменяет захват, Backspace снимает назначение. Можно использовать Ctrl, Alt и Shift.'},
        {'Игровые функции','В настройках чата доступно общение в слежке через /n: обычный текст перенаправляется только во время наблюдения. Акробатический прыжок (Matrix Jump) увеличивает горизонтальную скорость в 1,69 раза и подбрасывает персонажа с вращением. Для него и сальто назад нужны отдельные бинды: без назначенной клавиши трюки не запускаются. В командах при старте можно добавлять и удалять строки. Рыбий глаз: переключатель и угол справа 30–150°, по умолчанию 101°. Невидимость: бинд /inv в горячих клавишах, индикатор INVISIBLE с 1 уровня обновляется по подтверждениям сервера. Настройки GodMode, WallHack, информации о транспорте, дальних 3D-подписей, собственных подписей, скелетов и панелей наблюдения. Их доступность зависит от сохранённых ограничений основы и сервера.'},
        {'Чат','Перенос длинных сообщений, телефон при входе, ID рядом с ником и уведомления античита.'},
        {'Банды','GJ выдаёт jail со 2 уровня, GW/GB — warn/ban с 3. При недостаточных правах отправляется просьба через /a. При первом запуске команды /gw, /gb и /gj выключены. Общая галочка включает все три команды. Состояние сохраняется; выключенные команды не отправляют наказания.'},
        {'Профиль на главной','Аватар выбирается по текущей стандартной модели персонажа. Для нестандартных моделей и заменённых текстур отдельного портрета в комплекте может не быть.'}
    }},
    {id='online',title='Чистый онлайн',page='core',settings='online',intro={
        'Основные инструменты → Настройки → Основные → Чистый онлайн. Сбор доступен со 2 уровня, просмотр истории, цели и импорт — с 1. Служба времени /c 60 сообщает время в игре и AFK. X-Tools сохраняет разницу за сегодня и вчера по дате сервера. Повторный ответ обновляет день без двойного учёта.',
        'История разделена по серверу и нику. Неделя начинается в понедельник; при смене периода история сохраняется. Суммы и рекорды относятся только к записанным дням. Данные за пропущенные дни автоматически недоступны.',
        'Автопроверка выключена по умолчанию. В настройках включаются учёт, автозапрос, личная сводка и уведомления о целях. Цели задаются в минутах. Собственные запросы имеют таймаут 30 секунд; вручную открытый диалог не скрывается.'
    },commands={}},
    {id='schedule',title='Расписание мероприятий',page='schedule',intro={
        'На главной показано ближайшее событие каждой группы и время до начала по МСК (UTC+3). Часовой пояс Windows не влияет на расчёт; системные дата и время должны быть верными.',
        'Нажмите «Настроить расписание», выберите событие и измените время ЧЧ:ММ, название, группу или галочку показа. Можно добавить свои события и удалить ненужные. Все события ежедневные; совпадающее время допустимо. Для применения нажмите «Сохранить».',
        'В начальном расписании 32 события: очки за онлайн, новые /tasks, семейные кейсы, обычные и экстремальные гонки, казаки-разбойники и квадрат. Правки хранятся в X-TOOL/settings/schedule.ini. «Отменить правки» возвращает сохранённое расписание; восстановление начального меняет только черновик до сохранения.'
    },commands={}},
    {id='system',title='Система X-Tools',settings='system',intro={
        'Здесь собраны общие права администратора, данные и обновление всей программы. Состояние доступно в «Система».'
    },topics={
        {'Подтверждение прав','Для меню и игровых функций требуется подтверждённый сервером уровень администратора не ниже 1. Автоввод пароля и /reconn работают до подтверждения. Ограничения проверяются при запуске действий и отправке команд, в том числе из биндера и пользовательских кнопок. Окончательное разрешение проверяет сервер.'},
        {'После смены сессии','При переподключении, смене аккаунта или роли старое подтверждение сбрасывается; незавершённые действия отменяются. Уровень не сохраняется в конфиге. После загрузки X-Tools также может запросить /admins для подтверждения прав текущей сессии. Если подтверждение не получено, дождитесь ответа сервера или повторите вход в аккаунт.'},
        {'Одна папка данных','Все пользовательские файлы находятся в moonloader/X-TOOL. В settings — параметры, в data — статистика, списки и досье, в cache — временные данные, в logs — журналы. Для резервной копии сохраните всю папку.'},
        {'Перенос прежних настроек','При первом запуске старые файлы копируются в общую папку. Уже существующий файл X-Tools имеет приоритет. Старые файлы не изменяются; после переноса редактируйте новые. Копия импорта имеет окончание .imported.bak, предыдущая версия при сохранении — .bak.'},
        {'Обновление программы','Основной файл — X-TOOL.lua. Обновления загружаются из GitHub ameskrillex/X-TOOLS: проверяются код и ресурсы, перед установкой сохраняется резервная копия. Фоновая проверка при запуске только уведомляет; установка выполняется командой /update или отдельной кнопкой с перезагрузкой скрипта. При первом запуске проверка включена. В «Системе» также доступны проверка библиотек и возврат предыдущей версии. После публикации манифест иногда появляется с задержкой из-за кэша GitHub.'}
    },commands={
        {'/update','Проверить и установить новую версию X-Tools.','Настройки сохраняются, создаётся резервная копия; после установки скрипт перезапускается.'},
        {'/casualupdate','Проверить новую версию и открыть систему обновлений.','Установка выполняется отдельной кнопкой или командой /update. Проверка при запуске только уведомляет.'}
    }},
    {id='troubleshooting',title='Если что-то не работает',intro={},topics={
        {'Раздел недоступен','Проверьте минимальный уровень, включение раздела и /atmodules. Ошибки загрузки записываются в moonloader.log. Для первой установки распакуйте архив целиком: X-TOOL.lua, установщик библиотек и ресурсы из комплекта. Собственный Lua-код из старой папки lib/admintools больше не используется.'},
        {'Команда уже зарегистрирована','Проверьте, не загружается ли одновременно самостоятельная версия интегрированного скрипта. Одинаковые команды не должны принадлежать двум скриптам.'},
        {'Нет ответа на запрос','Проверьте соединение, права администратора и сообщения сервера. При ограничении частоты запросов дождитесь паузы. Повторная отправка наказания требует проверки предыдущего результата.'},
        {'Discord не отправляет','Проверьте галочку отправки и webhook в настройках каптов. Нужны effil, LuaSec, LuaSocket и LTN12. При ошибке TLS проверьте дату Windows и наличие файла сертификатов из архива.'},
        {'Не сохраняются настройки','Откройте «Система» и проверьте путь и ошибки хранения. Нужны доступ на запись к moonloader/X-TOOL и свободное место. Подробности — в moonloader.log; перед восстановлением сохраните копию папки.'},
        {'Не работают горячие клавиши','Закройте чат, диалог сервера, паузу и окно X-Tools. Проверьте назначение в Основные инструменты → Настройки → Клавиши. Esc отменяет ввод сочетания, Backspace снимает назначение. При конфликте выберите другое сочетание или явно перенесите его: у перечисленных действий назначение будет снято. Для предупреждения за аптечку требуется подтверждённая цель слежки.'},
        {'Как сообщить об ошибке','Сохраните фрагмент moonloader.log с ошибкой, версию SA-MP и короткую последовательность действий. Перед передачей удалите из материалов пароли и webhook.'}
    }},
    {id='about',title='О X-Tools',settings='system',intro={
        'X-Tools — рабочее пространство администратора. Файл программы — X-TOOL.lua. Данные — X-TOOL, ресурсы — resource/X-TOOL. Старые данные из config/CasualTool копируются автоматически без удаления исходной папки.',
        'Автор: Casual Alvarez',
        'В выпуске один X-TOOL.lua со всеми функциями. При первом запуске он скачивает недостающие ресурсы и библиотеки. При ошибке подготовки используйте /xtsetup. Текущая версия, проверка и установка доступны в настройках системы X-Tools.'
    },topics={
        {'Что входит в сборку','Инструменты администратора, наказания, чекер, проверка аккаунтов, наблюдение, капты, семьи, журнал входов и выходов, общие настройки и справка.'},
        {'Данные и настройки','Пользовательские файлы собраны в moonloader/X-TOOL. При первом запуске прежние настройки копируются сюда; старые скрипты отдельно запускать не нужно.'}
    }}
}

-- Examples are inert reference text: they are never sent by the help view.
local examples={
    ['/tr ID']='/tr 42', ['/getcar ID_транспорта']='/getcar 120',
    ['/clearhospital ID [ID…]']='/clearhospital 42 57',
    ['/rskin ID_скина радиус']='/rskin 20 15',
    ['/rskins ID_скина_1 ID_скина_2 радиус']='/rskins 20 21 15',
    ['/carsp ряды машин_в_ряду модель цвет_1 цвет_2']='/carsp 2 3 411 1 1',
    ['/apay ID сумма']='/apay 42 1000', ['/findd ID_организации']='/findd 3',
    ['/afindd ID_организации']='/afindd 3', ['/gw ID']='/gw 42', ['/gb ID дни']='/gb 42 30',
    ['/2warns ID причина']='/2warns 42 Причина по правилам сервера',
    ['/mban ID_1 ID_2 [ID_3] [ID_4] дни причина']='/mban 42 57 30 Причина по правилам сервера',
    ['/warnlast причина']='/warnlast Причина по правилам сервера',
    ['/banlast дни причина']='/banlast 3 Причина по правилам сервера',
    ['/jaillast минуты причина']='/jaillast 60 Причина по правилам сервера',
    ['/mutelast минуты причина']='/mutelast 30 Причина по правилам сервера',
    ['/cget ник_или_номер_аккаунта']='/cget Player_Name', ['/cas ID']='/cas 42', ['/reg ID']='/reg 42',
    ['/offreg ник_или_номер_аккаунта']='/offreg Player_Name',
    ['/cip IP']='/cip 192.0.2.1', ['/clip IP']='/clip 192.0.2.1',
    ['/namestore ник_или_ID']='/namestore Player_Name', ['/ilog ID']='/ilog 42', ['/iskill ID']='/iskill 42',
    ['/rk ID']='/rk 42', ['/getfrags [me | a | discord]']='/getfrags me',
    ['/getfrags solo ID']='/getfrags solo 42', ['/captfinish [итог]']='/captfinish Победа',
    ['/fama ID_получателя ID_или_ник']='/fama 42 57',
    ['/fj ник_или_ID минуты причина']='/fj Player_Name 60 Причина по правилам сервера',
    ['/fw ник_или_ID причина']='/fw Player_Name Причина по правилам сервера',
    ['/fb ник_или_ID дни причина']='/fb Player_Name 3 Причина по правилам сервера',
}
local parameterLabels={
    ['ID']='ID — номер игрока онлайн', ['ID_1']='ID_1, ID_2 — обязательные игроки; ID_3, ID_4 — необязательные',
    ['ID_транспорта']='ID_транспорта — номер транспорта, не модель',
    ['ID_скина']='ID_скина — номер скина', ['ID_скина_1']='ID_скина_1, ID_скина_2 — номера двух скинов',
    ['радиус']='радиус — расстояние в метрах', ['ряды']='ряды — количество рядов',
    ['машин_в_ряду']='машин_в_ряду — количество машин в каждом ряду', ['модель']='модель — ID модели транспорта',
    ['цвет_1']='цвет_1, цвет_2 — номера цветов', ['сумма']='сумма — общая сумма платежей',
    ['ID_организации']='ID_организации — номер организации', ['дни']='дни — срок в днях',
    ['минуты']='минуты — срок в минутах', ['причина']='причина — текст основания наказания',
    ['ник_или_номер_аккаунта']='ник_или_номер_аккаунта — имя либо постоянный номер аккаунта',
    ['IP']='IP — IPv4-адрес', ['ник_или_ID']='ник_или_ID — имя аккаунта либо ID игрока онлайн',
    ['итог']='итог — необязательное описание результата капта',
    ['ID_получателя']='ID_получателя — кому отправить ответ', ['ID_игрока']='ID_игрока — чью семью проверить',
}
function Help.commandDetails(syntax)
    local labels={}
    local parameters=syntax:match('^/%S+%s+(.+)$') or ''
    if parameters=='[me | a | discord]' then labels[1]='me — только вам; a — в админ-чат; discord — в Discord'
    else
        for token in parameters:gmatch('[^%s%[%]]+') do
            if parameterLabels[token] then labels[#labels+1]=parameterLabels[token] end
        end
    end
    return table.concat(labels,'; '),examples[syntax]
end

local upper='АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ'
local lower='абвгдеёжзийклмнопрстуфхцчшщъыьэюя'
local case={}
do
    local pos=1
    for char in upper:gmatch('[\194-\244][\128-\191]+') do case[char]=lower:sub(pos,pos+1); pos=pos+2 end
end
function Help.fold(text)
    return tostring(text or ''):lower():gsub('[\194-\244][\128-\191]+',case):gsub('ё','е')
end
function Help.section(id)
    for index,section in ipairs(Help.sections) do if section.id==id then return section,index end end
    return Help.sections[1],1
end
function Help.entries(id,query)
    query=Help.fold(query):match('^%s*(.-)%s*$')
    local found={}
    for _,section in ipairs(Help.sections) do
        if query~='' or section.id==id then
            local function append(title,body,note,aliases,command)
                local text=Help.fold(table.concat({section.title,title,body,note or '',aliases or ''},' '))
                local match=true
                for term in query:gmatch('%S+') do if not text:find(term,1,true) then match=false; break end end
                if match then
                    local parameters,example
                    if command then parameters,example=Help.commandDetails(title) end
                    found[#found+1]={title=title,body=body,note=note,aliases=aliases,section=section.title,
                        sectionId=section.id,command=command,parameters=parameters,example=example}
                end
            end
            if query~='' then for _,body in ipairs(section.intro or {}) do append(section.title,body) end end
            for _,topic in ipairs(section.topics or {}) do append(topic[1],topic[2]) end
            for _,command in ipairs(section.commands or {}) do append(command[1],command[2],command[3],command[4],true) end
        end
    end
    return found
end

function Help.draw(rt)
    return rt:service('help_ui.lua').draw(rt,Help)
end

return Help

    end
    sources["help_ui.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: help_ui.lua
-- Original third-party credits, where present, are retained below.
-- One pinned toolbar and one article scroll surface; topics are a sibling list.
local View={}

function View.draw(rt,help)
    local g=rt.imgui
    local ui=rt:service('ui_components.lua')
    local scale=tonumber(rt.preferences.data.main.scale) or 1
    local spacing=8*scale
    local width=math.max(1,g.GetContentRegionAvailWidth())
    local wide=width>=760*scale
    local lineHeight=g.CalcTextSize('M').y
    local section,index=help.section(rt.helpSection or 'start')
    rt.helpSection=section.id
    rt.helpSearch=rt.helpSearch or g.ImBuffer('',128)

    local function text(value,limit)
        local allowed=math.max(1,math.min(limit or 720*scale,g.GetContentRegionAvailWidth()-4*scale))
        g.TextWrapped((ui.wrap(g,value,allowed)))
    end
    local function selectTopic(item)
        section=item;rt.helpSection=item.id;rt.helpPage=1
        rt.helpSearch.v='';rt.helpIntro=nil;rt.helpResetScroll=true
    end
    local function accent(value)
        g.PushStyleColor(g.Col.Text,rt.theme.color(g,rt.theme.palette.accent))
        text(value);g.PopStyleColor()
    end
    local function button(label,id)
        local available=math.max(1,g.GetContentRegionAvailWidth())
        local wrapped,lines=ui.wrap(g,label,math.max(1,available-16*scale))
        return g.Button(wrapped..'##'..id,g.ImVec2(math.min(available,g.CalcTextSize(wrapped).x+16*scale),
            math.max(32*scale,lines*lineHeight+8*scale)))
    end

    -- Search and selection stay outside every scrolling child.
    g.Text('Найти команду или подсказку')
    local hadQuery=rt.helpSearch.v:match('^%s*(.-)%s*$')~=''
    local clearWidth=g.CalcTextSize('Очистить').x+16*scale
    g.PushItemWidth(math.max(1,width-(hadQuery and clearWidth+spacing or 0)))
    if g.InputText('##help_search',rt.helpSearch) then rt.helpPage=1;rt.helpResetScroll=true end
    g.PopItemWidth()
    local query=rt.helpSearch.v:match('^%s*(.-)%s*$')
    if hadQuery then
        g.SameLine(0,spacing)
        if button('Очистить','help_clear') then
            rt.helpSearch.v='';query='';rt.helpPage=1;rt.helpResetScroll=true
        end
    end
    if not wide then
        local labels={};for _,item in ipairs(help.sections) do labels[#labels+1]=item.title end
        local choice=g.ImInt(index-1)
        g.Text('Тема справки')
        g.PushItemWidth(width)
        if g.Combo('##help_category',choice,table.concat(labels,'\0')..'\0\0') then
            selectTopic(help.sections[math.max(1,math.min(#help.sections,choice.v+1))]);query=''
        end
        g.PopItemWidth()
    end
    g.Spacing();g.Separator();g.Spacing()

    local navigationWidth=wide and math.min(224*scale,width*0.28) or 0
    local contentHeight=math.max(1,g.GetContentRegionAvail().y)
    if wide then
        -- Independent vertical list, never nested within the article.
        g.BeginChild('help_topics',g.ImVec2(navigationWidth,contentHeight),false)
        for _,item in ipairs(help.sections) do
            local label,lines=ui.wrap(g,item.title,math.max(1,g.GetContentRegionAvailWidth()-16*scale))
            if g.Selectable(label..'##help_topic_'..item.id,item.id==section.id,0,
                g.ImVec2(math.max(1,g.GetContentRegionAvailWidth()-4*scale),math.max(32*scale,lines*lineHeight+8*scale))) then
                selectTopic(item);query=''
            end
        end
        g.EndChild();g.SameLine(0,spacing)
    end

    -- Group keeps toolbar, article, and pager within one bounded column.
    g.BeginGroup()
    local articleWidth=math.max(1,width-navigationWidth-(wide and spacing or 0))
    local startY=g.GetCursorPosY()
    if wide and query=='' then accent(section.title) end
    local actions={}
    if query=='' then
        local showIntro=rt.helpIntro
        if showIntro==nil then showIntro=wide or section.id=='about' end
        local hasIntro=#(section.intro or {})>0
        if hasIntro and section.id~='about' then
            actions[#actions+1]={showIntro and 'Свернуть описание' or 'О разделе','help_intro',function()
                rt.helpIntro=not showIntro
            end}
        end
        if section.page then
            actions[#actions+1]={wide and 'Открыть раздел' or 'Открыть','help_open',function() rt:open(section.page) end}
        end
        if section.settings then
            actions[#actions+1]={wide and 'Настройки раздела' or 'Настройки','help_settings',function() rt:openSettings(section.settings) end}
        end
    end

    local function drawActions()
        local used=0
        for _,action in ipairs(actions) do
            local measured=math.min(articleWidth,g.CalcTextSize(action[1]).x+16*scale)
            if used>0 and used+spacing+measured<=articleWidth then
                g.SameLine(0,spacing);used=used+spacing
            else used=0 end
            if button(action[1],action[2]) then action[3]() end
            used=used+measured
        end
    end

    local rows=help.entries(section.id,query)
    local pages=math.max(1,math.ceil(#rows/5))
    rt.helpPage=math.max(1,math.min(pages,rt.helpPage or 1))
    -- On short windows navigation links move into the article instead of
    -- consuming its last readable lines. Search, topic and pager stay pinned.
    local flowWidth,actionRows=0,0
    for _,action in ipairs(actions) do
        local measured=math.min(articleWidth,g.CalcTextSize(action[1]).x+16*scale)
        if flowWidth==0 or flowWidth+spacing+measured>articleWidth then actionRows=actionRows+1;flowWidth=measured
        else flowWidth=flowWidth+spacing+measured end
    end
    local availableForActions=contentHeight-(g.GetCursorPosY()-startY)-120*scale-(pages>1 and 44*scale or 0)-spacing*2
    local actionsInArticle=actionRows*40*scale>availableForActions
    if not actionsInArticle then drawActions() end
    if query~='' then text('Найдено во всей справке: '..#rows) end
    -- The pager is a fixed part of the header and reserves its own height.
    if pages>1 then
        if button('Назад','help_prev') then rt.helpPage=math.max(1,rt.helpPage-1);rt.helpResetScroll=true end
        g.SameLine(0,spacing);g.Text(rt.helpPage..' / '..pages);g.SameLine(0,spacing)
        if button('Далее','help_next') then rt.helpPage=math.min(pages,rt.helpPage+1);rt.helpResetScroll=true end
    end
    g.Spacing()
    local consumed=g.GetCursorPosY()-startY
    local articleHeight=math.max(1,contentHeight-consumed-spacing)
    g.BeginChild('help_article_'..section.id,g.ImVec2(articleWidth,articleHeight),false)
    if rt.helpResetScroll then g.SetScrollY(0);rt.helpResetScroll=false end
    if actionsInArticle then drawActions();g.Spacing();g.Separator();g.Spacing() end
    if query=='' then
        local showIntro=rt.helpIntro
        if showIntro==nil then showIntro=wide or section.id=='about' end
        if showIntro then
            for _,body in ipairs(section.intro or {}) do text(body);g.Spacing() end
            if #(section.intro or {})>0 then g.Separator();g.Spacing() end
        end
        if section.id=='about' then text('Версия: '..tostring(rt.host.version or 'локальная сборка'));g.Spacing() end
    end
    if #rows==0 then
        text(query~='' and 'Ничего не найдено. Попробуйте название функции или команду без параметров.'
            or 'Вся информация по этой теме приведена выше.')
    end
    for i=(rt.helpPage-1)*5+1,math.min(rt.helpPage*5,#rows) do
        local row=rows[i]
        accent(row.title)
        if query~='' then text('Тема: '..row.section) end
        text(row.body)
        if row.parameters and row.parameters~='' then text('Параметры: '..row.parameters) end
        if row.note and row.note~='' then text('Условия: '..row.note) end
        if row.aliases and row.aliases~='' then text('Также: '..row.aliases) end
        if row.example then text('Пример: '..row.example) end
        g.Spacing();g.Separator();g.Spacing()
    end
    g.EndChild()
    g.EndGroup()
end

return View

    end
    sources["hud_panels.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: hud_panels.lua
-- Original third-party credits, where present, are retained below.
-- Shared movable HUD panels; one ImGui context, persisted screen-bounded positions.
local M={};M.__index=M
function M.new(g,api,save) return setmetatable({g=g,api=api,save=save},M) end
function M:move(id) self.edit=self.edit==id and nil or id;self.follow=false end
function M:reset() self.edit=nil;self.follow=false;self.placing=false end
function M:window(id,title,p,width,height,body,transparent)
    local g,a=self.g,self.api
    if self.placing and self.edit==id then height=height+30 end
    local sw,sh=a.getScreenResolution()
    width=math.max(160,math.min(width,sw-24));height=math.max(80,math.min(height,sh-40))
    p.x=math.max(0,math.min(tonumber(p.x) or 30,sw-width));p.y=math.max(0,math.min(tonumber(p.y) or 160,sh-height))
    local editing=self.edit==id
    if editing and self.follow then
        local mouse=g.GetMousePos();p.x=math.max(0,math.min(mouse.x,sw-width));p.y=math.max(0,math.min(mouse.y,sh-height))
    end
    g.SetNextWindowPos(g.ImVec2(p.x,p.y),g.Cond.Always)
    g.SetNextWindowSize(g.ImVec2(width,height),g.Cond.Always)
    local f=g.WindowFlags
    local flags=(self.noTitle and f.NoTitleBar or 0)+f.NoCollapse+f.NoResize+(f.NoSavedSettings or 0)+f.NoMove
    local cursor=self.interactive or editing
    if not cursor then flags=flags+(f.NoInputs or 0) end
    if transparent then
        g.PushStyleColor(g.Col.WindowBg,g.ImVec4(0,0,0,0))
        g.PushStyleColor(g.Col.Border,g.ImVec4(0,0,0,0))
    end
    local opened=g.Begin(title..'###xt_hud_'..id,nil,flags)
    local ok,err=true,nil
    if opened then
        ok,err=pcall(body,g)
        if not self.placing and cursor and (not self.contextActions or editing) and g.IsWindowHovered() and g.IsMouseClicked(1) then self.edit=id;self.follow=not self.follow end
        if self.edit==id then
            g.TextWrapped(self.placing and 'Переместите мышь · Enter — сохранить.' or 'ПКМ — перемещать; ЛКМ — сохранить.')
            if not self.placing and g.IsMouseClicked(0) then self.edit=nil;self.follow=false;self.save() end
        end
    end
    g.End()
    if transparent then g.PopStyleColor(2) end
    if not ok then error(err) end
end
return M

    end
    sources["key_overlay.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: key_overlay.lua
-- Original third-party credits, where present, are retained below.
local M={}
function M.draw(g,row,color)
    local bit=require('bit');local p=g.GetCursorScreenPos();local d=g.GetWindowDrawList()
    local function held(mask)return bit.band(row.bits,mask)~=0 end
    local keys={{'W',36,0,30,row.vehicle and held(8)or not row.vehicle and row.y<0},{'A',0,36,30,row.x<0},
        {'S',36,36,30,row.vehicle and held(32)or not row.vehicle and row.y>0},{'D',72,36,30,row.x>0}}
    local extra=row.vehicle and {
        {'Ctrl',122,0,64,held(1)},{'Alt',192,0,64,held(4)},{'Space',122,36,134,held(128)},
        {'Up',262,0,38,row.y<0},{'Down',262,36,38,row.y>0},{'H',306,0,30,held(2)},
        {'F',342,0,30,held(16)},{'Q',306,36,30,held(256)},{'E',342,36,30,held(64)}}or {
        {'Shift',122,0,74,held(8)},{'Alt',202,0,54,held(1024)},{'Space',122,36,134,held(32)},
        {'C',262,0,30,held(2)},{'F',298,0,30,held(16)},{'RM',262,36,30,held(4)},{'LM',298,36,30,held(128)}}
    for _,k in ipairs(extra)do keys[#keys+1]=k end
    for _,k in ipairs(keys)do
        local a=g.ImVec2(p.x+k[2],p.y+k[3]);local b=g.ImVec2(a.x+k[4],a.y+30)
        d:AddRect(a,b,k[5] and color or 0xBFFFFFFF,3,15,k[5] and 2 or 1)
        local size=g.CalcTextSize(k[1]);d:AddText(g.ImVec2(a.x+(k[4]-size.x)/2,a.y+(30-size.y)/2),k[5] and color or 0xFFFFFFFF,k[1])
    end
    g.Dummy(g.ImVec2(row.vehicle and 372 or 328,66))
end
return M

    end
    sources["keybinds.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: keybinds.lua
-- Original third-party credits, where present, are retained below.
-- Shared bindings and their editor. Edits are committed only after conflict review.
local Keys={}
Keys.__index=Keys

local function binding(data)
    data=data or {}
    return {key=tonumber(data.key) or 0,ctrl=data.ctrl==true,alt=data.alt==true,
        shift=data.shift==true,second=tonumber(data.second) or 0,third=tonumber(data.third) or 0,originalVersion=tonumber(data.originalVersion) or 0}
end

-- A longer chord takes priority over every strict subset.
local function extends(short,long)
    if not short or not long or short.key==0 or long.key==0 then return false end
    local a,b={},{}
    for _,k in ipairs({short.key,short.second or 0,short.third or 0})do if k>0 then a[k]=true end end
    for _,k in ipairs({long.key,long.second or 0,long.third or 0})do if k>0 then b[k]=true end end
    for flag,key in pairs({ctrl=17,alt=18,shift=16})do
        if short[flag]then a[key]=true end
        if long[flag]then b[key]=true end
    end
    local extra=false
    for k in pairs(a)do if not b[k]then return false end end
    for k in pairs(b)do if not a[k]then extra=true end end
    return extra
end

-- Legacy MoonImGui does not wrap long words. Never split a UTF-8 code point.
local function wrap(g,text,width)
    local lines,line={},''
    width=math.max(1,width)
    for paragraph in (tostring(text)..'\n'):gmatch('(.-)\n') do
        line=''
        for word in paragraph:gmatch('%S+') do
            local nextLine=line=='' and word or line..' '..word
            if g.CalcTextSize(nextLine).x<=width then line=nextLine
            else
                if line~='' then lines[#lines+1]=line;line='' end
                for char in word:gmatch('[%z\1-\127\194-\244][\128-\191]*') do
                    if line~='' and g.CalcTextSize(line..char).x>width then lines[#lines+1]=line;line='' end
                    line=line..char
                end
            end
        end
        lines[#lines+1]=line
    end
    return table.concat(lines,'\n'),#lines*(tonumber(g.CalcTextSize('M').y) or 16)
end

function Keys.new(api,storage)
    local path=storage:path('settings','keybinds.ini')
    return setmetatable({api=api,storage=storage,path=path,data=storage:loadIni({},path),items={},order={}},Keys)
end

function Keys:register(id,label,defaults,changed,active)
    if self.items[id] then return self.items[id] end
    local originals={matrix_jump={key=32,shift=true},back_flip={key=32,second=67},
        clickwarp={key=4},observer_chat={key=116}}
    defaults=originals[id] or defaults
    local data=binding(self.data[id] or defaults)
    if originals[id] and data.originalVersion<1 then
        if data.key==0 then data=binding(defaults) end
        data.originalVersion=1
        self.data[id]=data
        self.storage:saveIni(self.data,self.path)
    end
    if id=='report_assist' and data.key==74 and data.alt and not data.ctrl and not data.shift and data.second==0 and data.third==0 then
        data=binding(defaults)
        self.data[id]=data;self.storage:saveIni(self.data,self.path)
    end
    self.data[id]=data
    local item={id=id,label=label,changed=changed,active=active,defaults=defaults}
    self.items[id]=item;self.order[#self.order+1]=item
    if changed then changed(data) end
    return item
end

function Keys:format(data)
    local b=binding(data)
    if b.key==0 then return 'Не назначена' end
    local function keyName(key)
        local known={[1]='Mouse 1',[2]='Mouse 2',[4]='Mouse 3',[5]='Mouse 4',[6]='Mouse 5',
            [16]='Shift',[17]='Ctrl',[18]='Alt',[8]='Backspace',[9]='Tab',[13]='Enter',[19]='Pause',[27]='Esc',[32]='Space',[33]='Page Up',[34]='Page Down',
            [35]='End',[36]='Home',[37]='Left',[38]='Up',[39]='Right',[40]='Down',
            [45]='Insert',[46]='Delete',[188]=',',[190]='.',[192]='~'}
        if known[key] then return known[key] end
        if key>=112 and key<=135 then return 'F'..(key-111) end
        if key>=48 and key<=90 then return string.char(key) end
        local vk=self.api.require('vkeys')
        if vk.id_to_name then
            local ok,value=pcall(vk.id_to_name,key)
            if ok and type(value)=='string' then return value:gsub('^VK_','') end
        end
        return tostring(key)
    end
    return (b.ctrl and 'Ctrl + ' or '')..(b.alt and 'Alt + ' or '')..(b.shift and 'Shift + ' or '')
        ..keyName(b.key)..(b.second>0 and ' + '..keyName(b.second) or '')..(b.third>0 and ' + '..keyName(b.third) or '')
end

function Keys:name(id) return self:format(self.data[id]) end

function Keys:rawDown(id)
    local b=self.data[id];local a=self.api
    if not b or b.key==0 or b.key==9 or b.second==9 or b.third==9 or self:captureActive() then return false end
    return a.isKeyDown(b.key) and (b.second==0 or a.isKeyDown(b.second))
        and ((b.third or 0)==0 or a.isKeyDown(b.third))
        and (not b.ctrl or a.isKeyDown(0x11)) and (not b.alt or a.isKeyDown(0x12)) and (not b.shift or a.isKeyDown(0x10))
end

-- Held actions share chord priority, and cannot reactivate as a chord is released.
function Keys:down(id)
    local item=self.items[id]
    if not item then return false end
    if not self:rawDown(id) then item.heldChordUsed=false;return false end
    for other in pairs(self.items)do
        if other~=id and extends(self.data[id],self.data[other]) and self:rawDown(other)then
            item.heldChordUsed=true
        end
    end
    return not item.heldChordUsed
end

function Keys:pressed(id)
    local item=self.items[id];if not item then return false end
    if self:captureActive()then item.down=false;item.chordUsed=false;return false end
    local down=self:rawDown(id)
    if down then
        for other,shortItem in pairs(self.items)do
            if extends(self.data[other],self.data[id])then shortItem.chordUsed=true end
        end
    end
    local hasLonger,used=false,false
    for other in pairs(self.items)do
        if other~=id and extends(self.data[id],self.data[other])then
            hasLonger=true
            if self:rawDown(other)then used=true end
        end
    end
    if hasLonger then
        if used then item.chordUsed=true end
        local fire=not down and item.down and not item.chordUsed
        item.down=down
        if not down then item.chordUsed=false end
        return fire==true
    end
    local pressed=down and not item.down;item.down=down;return pressed
end

function Keys:cancelCapture()
    self.capture=nil;self.pending=nil;self.captureError=nil;self.captureHeld={};self.captureOrder={};self.captureCandidate=nil
end

local modifiers={[16]=16,[160]=16,[161]=16,[17]=17,[162]=17,[163]=17,[18]=18,[164]=18,[165]=18}
function Keys:captureActive()
    return self.capture~=nil or (self.suppressUntil or 0)>(self.api.getGameTimer and self.api.getGameTimer()or 0)
end
function Keys:captureEvent(key,down)
    if not self.capture or self.pending then return end
    key=modifiers[key]or key
    self.captureHeld=self.captureHeld or {};self.captureOrder=self.captureOrder or {}
    if key==27 then if down then self:cancelCapture()end;return end
    if key==8 then if down then self.captureCandidate=binding()end;return end
    if down then
        if not self.captureHeld[key]then self.captureOrder[#self.captureOrder+1]=key end
        self.captureHeld[key]=true
    elseif self.captureHeld[key]then
        local primary={};local mods={}
        for _,k in ipairs(self.captureOrder)do
            if modifiers[k]then mods[k]=true else primary[#primary+1]=k end
        end
        local data={key=primary[1]or key,second=primary[2]or 0,third=primary[3]or 0,
            ctrl=mods[17]and key~=17 or #primary>0 and mods[17],
            alt=mods[18]and key~=18 or #primary>0 and mods[18],
            shift=mods[16]and key~=16 or #primary>0 and mods[16]}
        self.captureHeld[key]=nil
        if #primary>3 then self.captureError='Можно назначить до трёх клавиш и модификаторы.';self.captureOrder={};self.captureHeld={}
        else self.captureCandidate=binding(data)end
    end
end

function Keys:conflicts(id,data)
    data=binding(data)
    local found={}
    if data.key==0 then return found end
    for _,item in ipairs(self.order) do
        local other=self.data[item.id]
        -- Current runtime allows extra held modifiers. M and Ctrl+M can fire
        -- together, as can Q and Q+E; warn even for a currently inactive module.
        if item.id~=id and other and other.key>0 and not extends(data,other) and not extends(other,data) and
            (data.key==other.key or data.second>0 and data.second==other.key
                or other.second>0 and (data.key==other.second or data.second==other.second)
                or (data.third or 0)>0 and (data.third==other.key or data.third==other.second or data.third==other.third)
                or (other.third or 0)>0 and (data.key==other.third or data.second==other.third)
                or data.key==16 and other.shift or data.key==17 and other.ctrl or data.key==18 and other.alt
                or other.key==16 and data.shift or other.key==17 and data.ctrl or other.key==18 and data.alt) then
            found[#found+1]=item
        end
    end
    return found
end

local function reserved(data) return data.key==9 or data.second==9 or data.third==9 end

function Keys:commit(id,data,replace)
    if reserved(data) then self.captureError="Tab используется таблицей игроков и не может быть переназначен.";return false end
    if not self.items[id] then return false end
    local nextData={}
    for key,value in pairs(self.data) do nextData[key]=binding(value) end
    local changed={id}
    if replace then
        for _,item in ipairs(self:conflicts(id,data)) do
            nextData[item.id]=binding({originalVersion=self.data[item.id].originalVersion});changed[#changed+1]=item.id
        end
    end
    nextData[id]=binding(data)
    nextData[id].originalVersion=tonumber(self.data[id].originalVersion) or 0
    local ok,err=self.storage:saveIni(nextData,self.path)
    if not ok then
        self.captureError='Не удалось сохранить назначение. Проверьте доступ к папке настроек.'
        return false,err
    end
    self.data=nextData
    for _,key in ipairs(changed) do
        local item=self.items[key]
        if item and item.changed then item.changed(self.data[key]) end
    end
    self.suppressUntil=(self.api.getGameTimer and self.api.getGameTimer()or 0)+300
    self:cancelCapture()
    return true
end

function Keys:request(id,data)
    data=binding(data)
    if reserved(data) then self.captureError="Tab используется таблицей игроков и не может быть переназначен.";return false end
    local conflicts=self:conflicts(id,data)
    if #conflicts>0 then
        self.pending={id=id,data=data};self.capture=id
        return false
    end
    return self:commit(id,data)
end

function Keys:drawCapture(g,id)
    if self.capture~=id then return end
    local width=math.max(1,g.GetContentRegionAvailWidth())
    local function text(value) g.TextWrapped((wrap(g,value,width))) end
    local function action(value,suffix)
        local padding=g.GetStyle().FramePadding
        local label,height=wrap(g,value,math.max(1,width-padding.x*2))
        local scale=(tonumber(g.CalcTextSize('M').y) or 16)/16
        return g.Button(label..'##'..suffix,g.ImVec2(math.min(width,g.CalcTextSize(label).x+padding.x*2),
            math.max(32*scale,height+padding.y*2)))
    end
    if self.api.isKeyJustPressed(27) then self:cancelCapture();return end
    -- Handle the cancel click before polling mouse buttons for a new binding.
    if action('Отмена','bind_cancel_'..id) then self:cancelCapture();return end
    if self.pending then
        local conflicts=self:conflicts(id,self.pending.data)
        local labels={};for _,item in ipairs(conflicts) do labels[#labels+1]='«'..item.label..'»' end
        text('Сочетание '..self:format(self.pending.data)..' пересекается с: '..table.concat(labels,', ')..'.')
        text('Перенос снимет назначения у перечисленных действий, в том числе в выключенных модулях.')
        if action('Перенести назначение','bind_replace_'..id) then
            local data=self.pending.data;self:commit(id,data,true)
        end
        if self.capture and action('Выбрать другое','bind_retry_'..id) then self.pending=nil;self.captureError=nil end
    else
        text('Зажмите до трёх клавиш и отпустите. Можно назначить отдельно Shift / Ctrl / Alt. Esc — отмена, Backspace — убрать назначение.')
        if self.captureCandidate then local value=self.captureCandidate;self.captureCandidate=nil;self:request(id,value);return end
        self.capturePoll=self.capturePoll or {}
        for key=1,255 do
            if key~=3 and key~=7 and key<160 then
                local down=self.api.isKeyDown(key)==true
                if down and not self.capturePoll[key]then self:captureEvent(key,true)
                elseif not down and self.capturePoll[key]then self:captureEvent(key,false)
                elseif not down and self.api.isKeyJustPressed(key)then self:captureEvent(key,true);self:captureEvent(key,false)end
                self.capturePoll[key]=down
            end
        end
        if self.captureCandidate then local value=self.captureCandidate;self.captureCandidate=nil;self:request(id,value)end
    end
    if self.captureError then text(self.captureError) end
end

function Keys:draw(g,id,columnWidth)
    local item=self.items[id];if not item then return end
    -- Module facades scale legacy absolute dimensions. This shared editor already
    -- measures the active font, so draw through the same raw renderer only once.
    self.gui=self.gui or self.api.require('imgui')
    g=self.gui or g
    local width=math.max(1,g.GetContentRegionAvailWidth())
    local lineHeight=tonumber(g.CalcTextSize('M').y) or 16
    local scale=lineHeight/16
    local gap=8*scale
    local padding=g.GetStyle().FramePadding
    local startX,startY=g.GetCursorPosX(),g.GetCursorPosY()
    local stacked=width<280*scale
    local keyWidth=stacked and width or math.min(columnWidth or 166*scale,width*0.46)
    local keyText=self.capture==id and (self.pending and 'Конфликт сочетания' or 'Ожидание клавиши…') or self:name(id)
    local label,keyHeight=wrap(g,keyText,math.max(1,keyWidth-padding.x*2))
    local description,descriptionHeight=wrap(g,item.label,stacked and width or math.max(1,width-keyWidth-gap))
    local buttonHeight=math.max(32*scale,keyHeight+padding.y*2)
    local rowHeight=stacked and buttonHeight+gap+descriptionHeight or math.max(buttonHeight,descriptionHeight)
    local clicked=g.Button(label..'##bind_'..id,g.ImVec2(keyWidth,buttonHeight))
    if stacked then g.SetCursorPos(g.ImVec2(startX,startY+buttonHeight+gap))
    else g.SetCursorPos(g.ImVec2(startX+keyWidth+gap,startY+math.max(0,(buttonHeight-descriptionHeight)/2))) end
    g.TextWrapped(description)
    g.SetCursorPos(g.ImVec2(startX,startY+rowHeight))
    g.Dummy(g.ImVec2(0,4*scale))
    if clicked then
        self:cancelCapture();self.capture=id;self.capturePoll={}
        for key=1,255 do self.capturePoll[key]=self.api.isKeyDown(key)==true end
        -- The click that opens capture must not bind Mouse 1 on the same frame.
    else self:drawCapture(g,id) end
end

function Keys:drawAll(g)
    g.TextWrapped('Нажмите сочетание слева от действия, чтобы изменить его. Изменения сохраняются сразу.')
    g.Spacing()
    local scale=(tonumber(g.CalcTextSize('M').y) or 16)/16
    local width=150*scale
    for _,item in ipairs(self.order) do width=math.max(width,g.CalcTextSize(self:name(item.id)).x+24*scale) end
    width=math.min(width,210*scale)
    local columns=g.GetContentRegionAvailWidth()>=620*scale
    if columns then g.Columns(2,'shared_keybind_editor',false) end
    for _,item in ipairs(self.order) do
        self:draw(g,item.id,width)
        if columns then g.NextColumn() end
    end
    if columns then g.Columns(1) end
end

return Keys

    end
    sources["label_filter.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: label_filter.lua
-- Original third-party credits, where present, are retained below.
-- Preserve server label properties so disabling the filter restores native labels.
local M={}
function M.new(a,storage,enabled)
 local path=storage:path('settings','3d-labels.ini')
 local cfg=storage:loadIni({types={players=true,vehicles=true,houses=true,business=true,entrances=true,other=true}},path)
 local self={rows={},expanded=false};local previous=nil
 local u8=a.require('encoding').UTF8
 self.types={{'players','Надписи игроков'},{'vehicles','Транспорт'},{'houses','Дома'},{'business','Бизнесы'},{'entrances','Входы и выходы'},{'other','Прочие надписи'}}
 local function attached(id)return tonumber(id)and tonumber(id)>=0 and tonumber(id)~=65535 end
 function self:kind(r)
  if attached(r[7])then return 'players' end
  if attached(r[8])then return 'vehicles' end
  local text=tostring(u8(r[1])):gsub('{%x%x%x%x%x%x}',''):lower()
  for _,v in ipairs({{'houses',{'Дом','дом','Квартира','квартира'}},{'business',{'Бизнес','бизнес','Магазин','магазин'}},{'entrances',{'Вход','вход','Выход','выход','Нажмите','нажмите'}}})do
   for _,word in ipairs(v[2])do if text:find(word,1,true)then return v[1]end end
  end
  return 'other'
 end
 function self:remember(id,color,pos,distance,los,pid,vid,text)
  self.rows[id]={text,color,pos.x,pos.y,pos.z,distance,pid,vid,los}
  if enabled() then return {id,color,pos,cfg.types[self:kind(self.rows[id])] and 3000 or 0,false,pid,vid,text}end
 end
 function self:apply(active)
  if type(a.sampIs3dTextDefined)~='function' or type(a.sampCreate3dTextEx)~='function'then return end
  for id,r in pairs(self.rows)do
   if a.sampIs3dTextDefined(id)then
    a.sampDestroy3dText(id)
    a.sampCreate3dTextEx(id,r[1],r[2],r[3],r[4],r[5],active and(cfg.types[self:kind(r)]and 3000 or 0)or r[6],not active and r[9] or false,r[7],r[8])
   end
  end
 end
 function self:sync(force)
  local active=enabled()
  if not force and previous==active then return end
  if type(a.sampGet3dTextInfoById)=='function' then
   for id=0,2047 do
    if not self.rows[id]and a.sampIs3dTextDefined(id)then
     local t,c,x,y,z,d,los,pid,vid=a.sampGet3dTextInfoById(id)
     self.rows[id]={t,c,x,y,z,d,pid,vid,los}
    end
   end
  end
  self:apply(active);previous=active
 end
 function self:draw(g)
  if g.Button('Настройки 3D-текста')then self.expanded=not self.expanded end
  if not self.expanded then return end
  g.TextWrapped('Выберите надписи для расширенного показа. Прочие — текст, который не удалось распознать.')
  for _,v in ipairs(self.types)do
   local count=0;for _,r in pairs(self.rows)do if self:kind(r)==v[1]then count=count+1 end end
   local b=g.ImBool(cfg.types[v[1]]~=false)
   if g.Checkbox(v[2]..' ('..count..')',b)then cfg.types[v[1]]=b.v;storage:saveIni(cfg,path);self:sync(true)end
  end
 end
 function self:clear()self.rows={};previous=nil end
 function self:stop()self:apply(false);self:clear()end
 return self
end
return M

    end
    sources["layout.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: layout.lua
-- Original third-party credits, where present, are retained below.
-- Shared compact forms. Separators must not reset legacy Columns' row origin.
local Layout = {}
function Layout.separator(g)
    local count=tonumber((g.GetColumnsCount())) or 1
    if count<=1 then return g.Separator() end
    local start=g.GetCursorScreenPos()
    local width=math.max(1,g.GetContentRegionAvailWidth())
    local color=g.GetColorU32(g.GetStyle().Colors[g.Col.Border])
    g.GetWindowDrawList():AddLine(start,g.ImVec2(start.x+width,start.y),color,1)
    g.Dummy(g.ImVec2(0,1))
end
function Layout.new(g)
    local form={}
    function form.heading(title)
        g.TextDisabled(title)
        g.Spacing()
    end
    function form.begin(id,minimum)
        local width=g.GetContentRegionAvailWidth()
        local scale=math.max(1,g.CalcTextSize('M').y/16)
        local columns=width>=(minimum or 680)*scale
        if columns then g.Columns(2,id,false);g.SetColumnWidth(0,width*0.5) end
        g.PushItemWidth(math.min(160,math.max(100,g.GetContentRegionAvailWidth()*0.34)))
        return columns
    end
    function form.next(columns)
        g.PopItemWidth()
        if columns then g.NextColumn() else g.Spacing();g.Separator();g.Spacing() end
        g.PushItemWidth(math.min(160,math.max(100,g.GetContentRegionAvailWidth()*0.34)))
    end
    function form.finish(columns)
        g.PopItemWidth()
        if columns then g.Columns(1) end
    end
    function form.pair(id,left,right,minimum)
        local columns=form.begin(id,minimum)
        left(); form.next(columns); right(); form.finish(columns)
    end
    return form
end
return Layout

    end
    sources["leader_online.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: leader_online.lua
-- Original third-party credits, where present, are retained below.
local M={}
local function clean(s)return (s or ''):gsub('{%x%x%x%x%x%x}','')end
function M.parse(title,body,nick)
    if clean(title):lower()~=nick:lower() then return end
    body=clean(body)
    local function minutes(label)
        local h,m=body:match(label..':%s*(%d+)%s*ч%s+(%d+)%s*мин')
        if h then return tonumber(h)*60+tonumber(m)end
    end
    local a,b,c,d=minutes('В игре сегодня'),minutes('В игре вчера'),minutes('AFK сегодня'),minutes('AFK вчера')
    if not a or not b or not c or not d then return nil,'В /get нет всех полей онлайна' end
    if c>a or d>b then return nil,'AFK превышает время в игре' end
    return {today=a-c,yesterday=b-d}
end
function M.new(a,i,g,leaders)
    local path=i.storage:path('settings','leader-online.ini')
    local cfg=i.storage:loadIni({main={webhook=''},factions={}},path)
    local input=g.ImBuffer(cfg.main.webhook,512)
    local self={status='Выберите фракции для проверки.',rows={}}
    local queue,index,pending,worker,nextAt,report
    local reportOffset=1
    local function save()i.storage:saveIni(cfg,path)end
    local function fmt(n)return string.format('%d ч %02d мин',math.floor(n/60),n%60)end
    function self:stop()queue=nil;pending=nil;self.status='Проверка остановлена.' end
    function self:busy()return queue~=nil end
    function self:dialog(id,style,title,body)
        if not pending or id~=0 or style~=0 then return end
        if clean(title):lower()~=pending.nick:lower()then return end
        local result,err=M.parse(title,body,pending.nick)
        self.rows[#self.rows+1]={nick=pending.nick,org=pending.org,result=result,error=err}
        pending=nil;index=index+1;nextAt=a.getGameTimer()+1200
        return false
    end
    local function sendReport()
        local fields={}
        for rowIndex=reportOffset,math.min(#self.rows,reportOffset+24)do
            local row=self.rows[rowIndex]
            local value=row.error or ('Чистый онлайн за '..report.today..': **'..fmt(row.result.today)..'**\nЧистый онлайн за '..report.yesterday..': **'..fmt(row.result.yesterday)..'**')
            fields[#fields+1]={name=row.org..' — '..row.nick,value=value,inline=false}
        end
        local payload=a.encodeJson({allowed_mentions={parse={}},embeds={{title='Чистый онлайн лидеров',color=12162559,fields=fields}}})
        local ok,result=pcall(function()
            return a.require('effil').thread(function(url,data,code,ca)
                return assert(loadstring(code))().request('POST',url,{['Content-Type']='application/json',['Content-Length']=tostring(#data)},data,ca)
            end)(report.webhook,payload,i.workerCode('discord_transport.lua'),i.base..'/assets/cacert.pem')
        end)
        if ok then worker=result;self.status='Отправка в Discord…' else self.status='Не удалось запустить отправку в Discord.' end
    end
    function self:update()
        if worker then
            local status=worker:status()
            if status=='completed' then
                local ok,code=worker:get();worker=nil
                if ok and code>=200 and code<300 then
                    reportOffset=reportOffset+25
                    if reportOffset<=#self.rows then sendReport()else self.status='Отчёт отправлен в Discord.'end
                else self.status='Discord не принял отчёт (возможна частичная отправка).' end
            elseif status=='error' or status=='canceled' then worker=nil;self.status='Ошибка отправки в Discord.'end
        end
        if not queue then return end
        if not i.access:can(3) or a.sampGetGamestate()~=3 then self:stop();return end
        if pending then
            if a.getGameTimer()>pending.untilAt then
                self.rows[#self.rows+1]={nick=pending.nick,org=pending.org,error='Нет ответа /get'}
                pending=nil;index=index+1;nextAt=a.getGameTimer()+1200
            end
            return
        end
        if a.getGameTimer()<(nextAt or 0) then return end
        if index>#queue then queue=nil;sendReport();return end
        if i.queryBusy('get') or a.sampIsDialogActive()then return end
        pending=queue[index];pending.untilAt=a.getGameTimer()+15000
        a.sampSendChat('/get '..pending.nick)
        self.status='Проверка '..index..'/'..#queue..': '..pending.nick
    end
    function self:draw()
        if not i.access:can(3)then g.TextWrapped('Доступно с 3 уровня администратора.');return end
        g.TextWrapped('Чистый онлайн = время в игре минус AFK. Даты — по времени сервера.')
        g.InputText('Вебхук Discord##leader_online',input)
        if g.Button('Сохранить вебхук##leader_online')then cfg.main.webhook=input.v;save()end
        local list=leaders();local seen={}
        for _,row in ipairs(list)do
            if not seen[row.org]then
                seen[row.org]=true
                local value=g.ImBool(cfg.factions[row.org]==true)
                if g.Checkbox(row.org..'##leader_online',value)then cfg.factions[row.org]=value.v;save()end
            end
        end
        if #list==0 then g.TextWrapped('Обновите список лидеров через /leaders.')end
        if not queue and not worker and g.Button('Проверить чистый онлайн')then
            local url=input.v:match('^%s*(.-)%s*$')
            if not url:match('^https://discord%.com/api/webhooks/%d+/[%w_%-]+$') then self.status='Введите вебхук Discord.'
            elseif not i.access:can(3)then self.status='Нужен 3 уровень администратора.'
            else
                local selected,unique={},{}
                for _,row in ipairs(list)do if cfg.factions[row.org] and not unique[row.nick:lower()] and row.nick:match('^[%w_]+$')then selected[#selected+1]=row;unique[row.nick:lower()]=true end end
                if #selected==0 then self.status='Нет лидеров выбранных фракций.'

                else
                    cfg.main.webhook=url;save();queue=selected;index=1;self.rows={};nextAt=0;reportOffset=1
                    local now=a.os.time();report={webhook=url,today=a.os.date('!%d.%m.%Y',now+10800),yesterday=a.os.date('!%d.%m.%Y',now+10800-86400)}
                end
            end
        end
        if queue and g.Button('Остановить проверку')then self:stop()end
        g.TextWrapped(self.status)
        for _,row in ipairs(self.rows)do g.TextWrapped(row.org..' — '..row.nick..': '..(row.error or fmt(row.result.today)..' / '..fmt(row.result.yesterday)))end
    end
    return self
end
return M

    end
    sources["legends_server.lua"] = function()
-- Strict endpoint match: no server-name spoofing or hostname fallback.
local M={}
function M.allowed(api)
    if not api.isSampAvailable()or api.sampGetGamestate()~=3 then return false end
    local ip,port=api.sampGetCurrentServerAddress()
    return ip=='185.169.134.239' and tonumber(port)==7777
end
return M

    end
    sources["loading_card.lua"] = function()
-- X-TOOLS | Casual_Alvarez | Shared themed loading and update artwork.
local M={}
function M.draw(rt,x,y,w,h,title,subtitle,alpha,busy)
 local g=rt.imgui;local d=g.GetWindowDrawList();local p=rt.theme.palette
 local function v(dx,dy)return g.ImVec2(x+dx,y+dy)end
 local function c(hex,a)local value=rt.theme.color(g,hex);value.w=(alpha or 1)*(a or 1);return g.GetColorU32(value)end
 rt.art=rt.art or rt:service('art.lua').new(g,rt.base,rt.api)
 local art=rt.art:get('loading-frame')
 if art then d:AddImage(art.texture,v(0,0),v(w,h),g.ImVec2(0,0),g.ImVec2(1,1),c(p.accent))
 else d:AddRectFilled(v(0,0),v(w,h),c(p.bg),12);d:AddRect(v(0,0),v(w,h),c(p.accent),12)end
 local size=math.min(72,h*.52);local left=24
 local logo=rt.art:get(rt:service('appearance.lua').asset('logo',rt.preferences.data.main.logoStyle))
 if logo and w>=330 then d:AddImage(logo.texture,v(22,(h-size)/2),v(22+size,(h+size)/2),g.ImVec2(0,0),g.ImVec2(1,1),c(0xFFFFFF));left=34+size end
 local width=w-left-28
 local function line(text,dy,hex)
  if g.CalcTextSize(text).x>width then
   repeat text=text:gsub('[%z\1-\127\194-\244][\128-\191]*$','')until text==''or g.CalcTextSize(text..'…').x<=width
   text=text..'…'
  end
  d:AddText(v(left,dy),c(hex),text)
 end
 line(title,h*.27,p.text);line(subtitle,h*.49,p.accent)
 local by='by Casual Alvarez';line(by,h*.67,p.muted)
 local barY=h*.85
 d:AddRectFilled(v(left,barY),v(w-28,barY+2),c(p.track),1)
 if busy then
  local length=math.min(42,width*.25);local phase=(rt.api.getGameTimer()%1800)/1800
  local dx=(width-length)*(.5-.5*math.cos(phase*math.pi*2))
  d:AddRectFilled(v(left+dx,barY),v(left+dx+length,barY+2),c(p.accent),1)
 else d:AddRectFilled(v(left,barY),v(w-28,barY+2),c(p.accent),1)end
end
return M

    end
    sources["modules/adm.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/adm.lua
-- Original third-party credits, where present, are retained below.
-- CasualAT module. Author: Casual Alvarez. Original source: integration/sources.
require("lib.sampfuncs")
require("lib.moonloader")

local storage = integration.storage
local encoding = require("encoding")
local sampev = require("lib.samp.events")
local bit = require("bit")
local has_ffi, ffi = pcall(require, "ffi")
local winmm = nil
local imgui = nil

if has_ffi then
    pcall(function()
        ffi.cdef[[
            int PlaySoundA(const char *pszSound, void *hmod, unsigned int fdwSound);
        ]]
    end)

    local ok_winmm, loaded_winmm = pcall(ffi.load, "winmm")
    if ok_winmm then
        winmm = loaded_winmm
    end
end

encoding.default = "CP1251"
u8 = encoding.UTF8

local function cp1251_to_utf8(str)
    return tostring(u8(str or ""))
end

local function utf8_to_cp1251(str)
    return u8:decode(tostring(str or ""))
end

local OLD_ROOT = getWorkingDirectory()
local BASE_DIR = storage:directory('data')
local CHECKER_DIR = storage:directory('data', 'checker')
local CONFIG_PATH = storage:path('settings', 'checker.ini', {OLD_ROOT .. '/config/ADM/config.ini'})
local NOTIFY_SOUND_FILE = storage:path('cache', 'checker/join_notify.wav', {OLD_ROOT .. '/ADM/checker/join_notify.wav'})
for _,name in ipairs({'admins', 'leaders', 'friends'}) do
    storage:path('data', 'checker/' .. name .. '.txt', {
        OLD_ROOT .. '/ADM/checker/' .. name .. '.txt', OLD_ROOT .. '/ADM/checker/' .. name,
        OLD_ROOT .. '/AdminTools/checker/' .. name .. '.txt'})
end
local function is_target_server()
    return integration.serverSupports('adm')
end

local function unload_on_wrong_server()
    integration.message('Чекер недоступен на этом сервере. Условия поддержки: Справка > Чекер.')
    integration.disable()
end

local defaults = {
    checker = {
        leaders_checker_status = true,
        friends_checker_status = true,
        admins_checker_status = true,
        source_updates_enabled = true,
        admin_checker_auto_update = true,
        notify_hidden_leader_events = false,
        notify_admin_events = true,
        notify_leader_events = true,
        notify_friend_events = true,
        friend_notify_mode = "all",
        sound_notify_enabled = false,
        sound_notify_admins = false,
        sound_notify_leaders = false,
        sound_notify_friends = false
    },
    overlay = {
        font = "Arial",
        font_size = 8,
        xpos = 5,
        ypos = 183,
        admin_show_level = true,
        admin_show_role = false,
        show_background = true,
        show_numbering = true,
        show_ids = true,
        hidden_leader_orgs = ""
    }
}

local FONT_OPTIONS = {
    "Arial",
    "Tahoma",
    "Verdana",
    "Trebuchet MS",
    "Calibri",
    "Segoe UI",
    "Consolas",
    "Lucida Console",
    "Times New Roman",
    "Georgia",
    "Cambria",
    "Courier New",
    "Franklin Gothic Medium",
    "Book Antiqua",
    "Palatino Linotype",
    "Garamond",
    "Impact",
    "MS Sans Serif"
}

local APP_TITLE = "X-Tools · Чекер"
local APP_AUTHOR = "Casual Alvarez"

local config = nil
local font = nil
local last_sync = 0
local imgui_loaded = false
local overlay_drag_active = false
local overlay_drag_saved = false
local overlay_drag_offset_x = 0
local overlay_drag_offset_y = 0
local overlay_drag_bounds = { x = 0, y = 0, w = 260, h = 18, active = false }
local admin_refresh_active = false
local admin_refresh_seen_nicks = {}
local admin_refresh_eligible = {}
local admin_refresh_last_line_at = 0
local list_refresh_in_progress = false
local auto_close_refresh_dialogs = false

local admins_nick, admins_lvl, admins_id, admins_role, admins_notify, admins_locked, admins_sound_notify = {}, {}, {}, {}, {}, {}, {}
local leaders_nick, leaders_org, leaders_org_name, leaders_id, leaders_notify, leaders_sound_notify = {}, {}, {}, {}, {}, {}
local friends_nick, friends_id, friends_best, friends_notify, friends_sound_notify = {}, {}, {}, {}, {}
local overlay_move_mode = nil
local selected_admin = nil
local selected_leader = nil
local selected_friend = nil
local gui_page = nil
local admin_name_buffer = nil
local admin_level_buffer = nil
local admin_role_buffer = nil
local leader_name_buffer = nil
local leader_org_buffer = nil
local friend_name_buffer = nil
local friend_best_toggle = nil
local selected_font_index = nil
local font_size_value = nil
local position_x_value, position_y_value = nil, nil
local save_config = nil
local remove_admin = nil
local sync_online_ids = nil
local ensure_default_admins = nil

local function message(text)
    sampAddChatMessage(utf8_to_cp1251("{D9A657}[X-Tools] {E8E8E8}" .. tostring(text or "")), -1)
end

local function trim(value)
    if value == nil then
        return nil
    end

    return (value:gsub("^%s+", ""):gsub("%s+$", ""))
end

local function same_name(left, right)
    if left == nil or right == nil then
        return false
    end

    return string.lower(left) == string.lower(right)
end

local function split_pipe_fields(text)
    local fields = {}
    text = tostring(text or "")

    while true do
        local separator = string.find(text, "|", 1, true)
        if separator == nil then
            table.insert(fields, text)
            break
        end

        table.insert(fields, string.sub(text, 1, separator - 1))
        text = string.sub(text, separator + 1)
    end

    return fields
end

local function flag_to_bool(value, default_value)
    if value == nil or value == "" then
        return default_value ~= false
    end

    value = string.lower(trim(tostring(value)) or "")
    return not (value == "0" or value == "false" or value == "off" or value == "no")
end

local function bool_to_flag(value)
    return value == true and "1" or "0"
end

local function clean_list_field(value)
    return tostring(value or ""):gsub("|", "/")
end

local function normalize_admin_level(level)
    if level == nil then
        return "-1"
    end

    level = string.upper(trim(tostring(level)) or "-1")

    if level == "S1" or level == "S2" or level == "S3" then
        return level
    end

    local numeric = tonumber(level)
    if numeric ~= nil then
        return tostring(math.floor(numeric))
    end

    if level == "S" then
        return "S1"
    end

    return "-1"
end

local function admin_level_sort_rank(level)
    level = normalize_admin_level(level)

    if level == "7" then
        return 9
    elseif level == "6" then
        return 8
    elseif level == "5" then
        return 7
    elseif level == "4" then
        return 6
    elseif level == "3" then
        return 5
    elseif level == "2" then
        return 4
    elseif level == "1" then
        return 3
    elseif level == "S3" then
        return 2
    elseif level == "S2" then
        return 1
    elseif level == "S1" then
        return 0
    end

    return -1
end

local function admin_level_text(level)
    level = normalize_admin_level(level)

    if level == "-1" then
        return "?"
    end

    return level
end

local admin_role_title

local function get_admin_role_title(index, level)
    local custom_role = ""

    if index ~= nil then
        custom_role = trim(admins_role[index] or "") or ""
    end

    if custom_role ~= "" then
        return custom_role
    end

    return admin_role_title(level)
end

local function is_youtube_level(level)
    level = normalize_admin_level(level)
    return level == "S1" or level == "S2" or level == "S3"
end

local function format_display_nickname(nickname)
    return tostring(nickname or ""):gsub("_", " ")
end

local function youtube_level_hex(level)
    level = normalize_admin_level(level)

    if level == "S1" then
        return "FF6A6A"
    elseif level == "S2" then
        return "FF3F3F"
    elseif level == "S3" then
        return "FF1010"
    end

    return "FF3F3F"
end

local function format_youtube_nickname(nickname, level)
    local color = youtube_level_hex(level)
    local first_name, last_name = string.match(tostring(nickname or ""), "^([^_]+)_(.+)$")
    if first_name == nil or last_name == nil then
        return "{" .. color .. "}" .. format_display_nickname(nickname)
    end

    return string.format("{%s}%s {FFFFFF}%s", color, first_name, last_name)
end

local function build_admin_suffix(index, level)
    local parts = {}

    if config.overlay.admin_show_level then
        table.insert(parts, admin_level_text(level))
    end

    if config.overlay.admin_show_role then
        table.insert(parts, get_admin_role_title(index, level))
    end

    if #parts == 0 then
        return ""
    end

    return " [" .. table.concat(parts, " | ") .. "]"
end

local function leader_org_fallback_name(org_id)
    org_id = tonumber(org_id) or -1

    if org_id == 1 then
        return "Правительство"
    elseif org_id == 2 then
        return "МВД"
    elseif org_id == 3 then
        return "МО"
    elseif org_id == 4 then
        return "МЗ"
    elseif org_id == 5 then
        return "СМИ"
    elseif org_id >= 6 and org_id <= 10 then
        return "Банда"
    elseif org_id >= 11 and org_id <= 13 then
        return "Мафия"
    end

    return "Организация"
end

local function normalize_leader_org_title(org_title, org_id)
    local normalized = trim(tostring(org_title or ""))
    if normalized == nil or normalized == "" then
        return leader_org_fallback_name(org_id)
    end

    return normalized
end

local function normalize_leader_org_key(org_title)
    return string.lower(trim(tostring(org_title or "")) or "")
end

local function is_valid_leader_row(nickname, organization)
    nickname = trim(tostring(nickname or ""))
    organization = trim(tostring(organization or ""))

    if nickname == "" or organization == "" then
        return false
    end

    local lower_nickname = string.lower(nickname)
    local lower_org = string.lower(organization)

    if nickname == "Имя" or organization == "Организация" then
        return false
    end

    if string.find(lower_nickname, "id:", 1, true) or string.find(lower_nickname, "id ", 1, true) then
        return false
    end

    if string.find(nickname, "/", 1, true) or string.find(nickname, "|", 1, true) then
        return false
    end

    if string.find(lower_org, "организация", 1, true) and string.find(lower_nickname, "имя", 1, true) then
        return false
    end

    return true
end

local function encode_hidden_org(value)
    return (value:gsub('%%','%%25'):gsub('|','%%7C'))
end
local function decode_hidden_org(value)
    return (value:gsub('%%7[Cc]','|'):gsub('%%25','%%'))
end
local function parse_hidden_leader_orgs()
    local hidden = {}

    for org_title in string.gmatch(tostring(config.overlay.hidden_leader_orgs or ""), "([^|]+)") do
        local key = normalize_leader_org_key(decode_hidden_org(org_title))
        if key ~= "" then
            hidden[key] = true
        end
    end

    return hidden
end

local function is_leader_org_visible(org_title)
    local key = normalize_leader_org_key(org_title)
    if key == "" then
        return true
    end

    return not parse_hidden_leader_orgs()[key]
end

local function should_notify_leader_org(org_title)
    if is_leader_org_visible(org_title) then
        return true
    end

    return config ~= nil and config.checker ~= nil and config.checker.notify_hidden_leader_events == true
end

local function is_best_friend(index)
    return friends_best[index] == true
end

local function should_notify_admin(index)
    if config ~= nil and config.checker ~= nil and config.checker.notify_admin_events ~= true then
        return false
    end

    return admins_notify[index] ~= false
end

local function should_notify_leader(index)
    if config ~= nil and config.checker ~= nil and config.checker.notify_leader_events ~= true then
        return false
    end

    if leaders_notify[index] == false then
        return false
    end

    local org_title = normalize_leader_org_title(leaders_org_name[index], leaders_org[index])
    return should_notify_leader_org(org_title)
end

local function should_notify_friend(index)
    if config ~= nil and config.checker ~= nil and config.checker.notify_friend_events ~= true then
        return false
    end

    if friends_notify[index] == false then
        return false
    end

    if config ~= nil and config.checker ~= nil and config.checker.friend_notify_mode == "best" then
        return is_best_friend(index)
    end

    return true
end

local function should_sound_notify_admin(index)
    return admins_sound_notify[index] == true
end

local function should_sound_notify_leader(index)
    if leaders_sound_notify[index] ~= true then
        return false
    end

    local org_title = normalize_leader_org_title(leaders_org_name[index], leaders_org[index])
    return should_notify_leader_org(org_title)
end

local function should_sound_notify_friend(index)
    if friends_sound_notify[index] ~= true then
        return false
    end

    if config ~= nil and config.checker ~= nil and config.checker.friend_notify_mode == "best" then
        return is_best_friend(index)
    end

    return true
end

local function set_leader_org_visible(org_title, visible)
    local hidden = parse_hidden_leader_orgs()
    local key = normalize_leader_org_key(org_title)

    if key == "" then
        return
    end

    if visible then
        hidden[key] = nil
    else
        hidden[key] = true
    end

    local values = {}
    for _, value in ipairs(leaders_org_name) do
        local current_key = normalize_leader_org_key(value)
        if current_key ~= "" and hidden[current_key] then
            table.insert(values, encode_hidden_org(value))
            hidden[current_key] = nil
        end
    end

    -- Preserve hidden entries absent from the current online leader list.
    for remaining in pairs(hidden) do table.insert(values, encode_hidden_org(remaining)) end

    table.sort(values, function(left, right)
        return string.lower(left) < string.lower(right)
    end)

    config.overlay.hidden_leader_orgs = table.concat(values, "|")
    save_config()
end

local function collect_leader_org_options()
    local unique = {}
    local result = {}

    for index = 1, #leaders_nick do
        local org_title = normalize_leader_org_title(leaders_org_name[index], leaders_org[index])
        local key = normalize_leader_org_key(org_title)
        if key ~= "" and not unique[key] then
            unique[key] = true
            table.insert(result, org_title)
        end
    end

    table.sort(result, function(left, right)
        return string.lower(left) < string.lower(right)
    end)

    return result
end

local function set_all_leader_orgs_visible(visible)
    local options = collect_leader_org_options()
    local hidden = {}

    if not visible then
        for _, org_title in ipairs(options) do
            local key = normalize_leader_org_key(org_title)
            if key ~= "" then
                hidden[key] = org_title
            end
        end
    end

    local values = {}
    for _, org_title in ipairs(options) do
        local key = normalize_leader_org_key(org_title)
        if key ~= "" and hidden[key] then
            table.insert(values, encode_hidden_org(hidden[key]))
        end
    end

    table.sort(values, function(left, right)
        return string.lower(left) < string.lower(right)
    end)

    config.overlay.hidden_leader_orgs = table.concat(values, "|")
    save_config()
end

local function invert_leader_org_visibility()
    local options = collect_leader_org_options()

    for _, org_title in ipairs(options) do
        set_leader_org_visible(org_title, not is_leader_org_visible(org_title))
    end
end

local function close_current_dialog_safely()
    if sampCloseCurrentDialogWithButton ~= nil then
        sampCloseCurrentDialogWithButton(0)
    elseif sampCloseCurrentDialog ~= nil then
        sampCloseCurrentDialog()
    end
end

local function send_chat_command(command)
    if sampProcessChatInput ~= nil then
        sampProcessChatInput(utf8_to_cp1251(command))
    else
        sampSendChat(utf8_to_cp1251(command))
    end
end

local function refresh_server_lists()
    if list_refresh_in_progress then
        message("Обновление списков уже запущено.")
        return
    end

    if config == nil or config.checker == nil or config.checker.source_updates_enabled == false then
        message("Обновление списков с сервера выключено. Включение: Настройки → Чекер.")
        return
    end

    if not isSampAvailable() or sampGetGamestate() ~= 3 then
        message("Серверные списки можно обновить только в игре.")
        return
    end

    list_refresh_in_progress = true
    auto_close_refresh_dialogs = true
    message("Обновляю списки через /leaders, /admins и /adms...")

    lua_thread.create(function()
        send_chat_command("/leaders")
        wait(800)
        close_current_dialog_safely()

        send_chat_command("/admins")
        wait(1400)

        send_chat_command("/adms")
        wait(800)
        close_current_dialog_safely()

        wait(400)
        sync_online_ids()
        auto_close_refresh_dialogs = false
        list_refresh_in_progress = false
        message("Запрос обновления списков завершён.")
    end)
end

local function authenticated_online_admin(index)
    local id=tonumber(admins_id[index])
    if not id or id<0 or type(sampGetPlayerScore)~='function' then return false end
    local ok,eligible=pcall(function()
        if not sampIsPlayerConnected(id) then return false end
        local nickname=cp1251_to_utf8(sampGetPlayerNickname(id))
        if not same_name(nickname,admins_nick[index]) then return false end
        local score=tonumber(sampGetPlayerScore(id))
        return score~=nil and score==score and score<math.huge and score>1
    end)
    return ok and eligible==true
end

local function start_admin_refresh()
    admin_refresh_active = true
    admin_refresh_seen_nicks = {}
    admin_refresh_eligible = {}
    -- A player who logs in while the response is arriving was not necessarily
    -- eligible to appear in this /admins snapshot. Recheck the same ID below.
    for index,nickname in ipairs(admins_nick) do
        if authenticated_online_admin(index) then
            admin_refresh_eligible[string.lower(nickname)]=admins_id[index]
        end
    end
    admin_refresh_last_line_at = os.clock()
end

local function skip_admin_removal_on_refresh(level)
    level = normalize_admin_level(level)
    return level == "5" or level == "6" or level == "7" or level == "S1"
end

local function finalize_admin_refresh()
    if not admin_refresh_active then
        return
    end

    if config ~= nil and config.checker ~= nil and config.checker.source_updates_enabled == false then
        admin_refresh_active = false
        admin_refresh_seen_nicks = {}
        admin_refresh_eligible = {}
        admin_refresh_last_line_at = 0
        return
    end

    for index = #admins_nick, 1, -1 do
        if admin_refresh_eligible[string.lower(admins_nick[index])]==admins_id[index]
            and authenticated_online_admin(index)
            and not admin_refresh_seen_nicks[string.lower(admins_nick[index])]
            and admins_locked[index] ~= true
            and not skip_admin_removal_on_refresh(admins_lvl[index]) then
            local removed_name = admins_nick[index]
            remove_admin(removed_name)
            message(string.format("%s удалён из чекера.\nЕго нет в /admins; игрок на сервере, игровой уровень выше 1.", format_display_nickname(removed_name)))
        end
    end

    admin_refresh_active = false
    admin_refresh_seen_nicks = {}
    admin_refresh_eligible = {}
    admin_refresh_last_line_at = 0
end

local function sort_admins_by_level()
    local rows = {}

    for index = 1, #admins_nick do
        table.insert(rows, {
            nick = admins_nick[index],
            lvl = normalize_admin_level(admins_lvl[index]),
            id = tonumber(admins_id[index]) or -1,
            role = admins_role[index] or "",
            notify = admins_notify[index] ~= false,
            locked = admins_locked[index] == true,
            sound = admins_sound_notify[index] == true
        })
    end

    table.sort(rows, function(left, right)
        local left_rank = admin_level_sort_rank(left.lvl)
        local right_rank = admin_level_sort_rank(right.lvl)

        if left_rank ~= right_rank then
            return left_rank > right_rank
        end

        return string.lower(left.nick) < string.lower(right.nick)
    end)

    admins_nick, admins_lvl, admins_id, admins_role, admins_notify, admins_locked, admins_sound_notify = {}, {}, {}, {}, {}, {}, {}

    for _, row in ipairs(rows) do
        table.insert(admins_nick, row.nick)
        table.insert(admins_lvl, row.lvl)
        table.insert(admins_id, row.id)
        table.insert(admins_role, row.role)
        table.insert(admins_notify, row.notify)
        table.insert(admins_locked, row.locked)
        table.insert(admins_sound_notify, row.sound)
    end
end

local function set_buffer(buffer, value)
    if buffer ~= nil then
        buffer.v = tostring(value or "")
    end
end

local function find_font_index(font_name)
    local target = string.lower(tostring(font_name or ""))

    for index, name in ipairs(FONT_OPTIONS) do
        if string.lower(name) == target then
            return index
        end
    end

    return 1
end

