                draw_line(line, x, y, line_color)
            end
        end
    end

    if count == 0 then
        y = y + line_height
        draw_line("Администраторов в сети нет", x, y, 0x64FFFFFF)
    end

    return y
end

local directory_views = {}
local function draw_directory_list(kind, names, selection, label_for, select_record)
    local view = directory_views[kind]
    if not view then
        view = {search = imgui.ImBuffer(128), page = 1}
        directory_views[kind] = view
    end
    imgui.TextColored(integration.color(integration.palette.accent), 'Игроки · ' .. #names)
    imgui.PushItemWidth(-1)
    imgui.TextDisabled('Поиск по нику')
    if imgui.InputText('##directory_search_' .. kind, view.search) then view.page = 1 end
    imgui.PopItemWidth()
    local matching = {}
    local query = trim(view.search.v):lower():gsub('_', ' ')
    for index, nickname in ipairs(names) do
        if query == '' or tostring(nickname):lower():gsub('_', ' '):find(query, 1, true) then matching[#matching + 1] = index end
    end
    local page_size = 8
    local pages = math.max(1, math.ceil(#matching / page_size))
    view.page = math.max(1, math.min(view.page, pages))
    if imgui.Button('Добавить игрока##' .. kind .. '_add_new', imgui.ImVec2(imgui.GetContentRegionAvailWidth(), 34)) then select_record(-1) end
    imgui.Spacing()
    if pages > 1 then
        if imgui.Button('<##directory_prev_' .. kind, imgui.ImVec2(36, 32)) then view.page = math.max(1, view.page - 1) end
        imgui.SameLine();imgui.Text(view.page .. ' / ' .. pages);imgui.SameLine()
        if imgui.Button('>##directory_next_' .. kind, imgui.ImVec2(36, 32)) then view.page = math.min(pages, view.page + 1) end
        imgui.Spacing()
    end
    local scale=integration.preferences.data.main.scale or 1
    local width=math.max(1,imgui.GetContentRegionAvailWidth())
    local detailWidth=math.min(width*.40,(kind=='admin' and 70 or 128)*scale)
    local nameWidth=math.max(1,width-detailWidth-34*scale)
    local draw=imgui.GetWindowDrawList();local palette=integration.palette
    local function color(key)return imgui.GetColorU32(integration.color(palette[key]))end
    local function background(height,key)
        local pos=imgui.GetCursorScreenPos()
        draw:AddRectFilled(pos,imgui.ImVec2(pos.x+width,pos.y+height),color(key),0)
        draw:AddLine(imgui.ImVec2(pos.x,pos.y+height),imgui.ImVec2(pos.x+width,pos.y+height),color('border'),1)
        draw:AddLine(imgui.ImVec2(pos.x+width-detailWidth,pos.y),imgui.ImVec2(pos.x+width-detailWidth,pos.y+height),color('border'),1)
        return pos
    end
    local x,y=imgui.GetCursorPosX(),imgui.GetCursorPosY()
    local headerHeight=32*scale
    background(headerHeight,'button')
    imgui.SetCursorPosX(x+12*scale);imgui.SetCursorPosY(y+7*scale);imgui.TextDisabled('Игрок')
    imgui.SetCursorPosX(x+width-detailWidth+8*scale);imgui.SetCursorPosY(y+7*scale)
    imgui.TextDisabled(kind=='admin' and 'Уровень' or kind=='leader' and 'Фракция' or 'Группа')
    imgui.SetCursorPosX(x);imgui.SetCursorPosY(y+headerHeight)
    if #matching==0 then
        background(42*scale,'surface')
        imgui.SetCursorPosX(x+10*scale);imgui.SetCursorPosY(y+headerHeight+10*scale)
        imgui.TextDisabled(query=='' and 'Список пока пуст' or 'Ничего не найдено')
        imgui.SetCursorPosX(x);imgui.SetCursorPosY(y+headerHeight+42*scale)
    end
    for position=(view.page-1)*page_size+1,math.min(view.page*page_size,#matching)do
        local index=matching[position]
        local nickname=format_display_nickname(names[index])
        local detail=kind=='admin' and admin_level_text(admins_lvl[index])
            or kind=='leader' and normalize_leader_org_title(leaders_org_name[index],leaders_org[index])
            or (friends_best[index] and 'Лучший' or 'Друг')
        local ids=kind=='admin' and admins_id or kind=='leader' and leaders_id or friends_id
        local online=(tonumber(ids[index])or -1)>=0
        local wrap=integration.service('ui_components.lua').wrap
        nickname=wrap(imgui,nickname,nameWidth)
        detail=wrap(imgui,detail,math.max(1,detailWidth-16*scale))
        local height=math.max(42*scale,math.max(imgui.CalcTextSize(nickname).y,imgui.CalcTextSize(detail).y)+18*scale)
        local rowX,rowY=imgui.GetCursorPosX(),imgui.GetCursorPosY()
        local selected=selection.v==index-1
        local pos=background(height,selected and 'selection' or position%2==0 and 'sidebar' or 'surface')
        if imgui.Selectable('##directory_record_'..kind..'_'..names[index],selected,0,imgui.ImVec2(width,height))then select_record(index-1)end
        if imgui.IsItemHovered()then imgui.SetTooltip(online and 'В сети' or 'Не в сети')end
        if selected then draw:AddRectFilled(pos,imgui.ImVec2(pos.x+3*scale,pos.y+height),color('accent'),0)end
        draw:AddCircleFilled(imgui.ImVec2(pos.x+12*scale,pos.y+height*.5),3*scale,color(online and 'green' or 'muted'),12)
        imgui.SetCursorPosX(rowX+23*scale);imgui.SetCursorPosY(rowY+9*scale)
        imgui.TextUnformatted(nickname)
        imgui.SetCursorPosX(rowX+width-detailWidth+8*scale);imgui.SetCursorPosY(rowY+9*scale)
        imgui.TextColored(integration.color(palette.accent),detail)
        imgui.SetCursorPosX(rowX);imgui.SetCursorPosY(rowY+height)
    end

end

draw_admin_editor = function()
    local available = imgui.GetContentRegionAvail()
    local side_by_side = available.x >= 680
    if side_by_side then
        imgui.Columns(2, 'admins_directory_columns', false)
        imgui.SetColumnWidth(0, math.min(370, available.x * 0.44))
    end
    draw_directory_list('admin', admins_nick, selected_admin, admin_list_label, select_admin)
    if side_by_side then imgui.NextColumn() else imgui.Spacing(); imgui.Separator(); imgui.Spacing() end
    imgui.PushItemWidth(math.min(460, imgui.GetContentRegionAvailWidth()))
    imgui.TextColored(integration.color(integration.palette.accent), "Карточка игрока")
    imgui.Separator()

    if selected_admin.v >= 0 and admins_nick[selected_admin.v + 1] ~= nil then
        local idx = selected_admin.v + 1
        imgui.TextWrapped("Ник: " .. format_display_nickname(admins_nick[idx]))
        imgui.Text("Уровень: " .. admin_level_text(admins_lvl[idx]))
        imgui.TextWrapped("Должность: " .. get_admin_role_title(idx, admins_lvl[idx]))
        imgui.Text((tonumber(admins_id[idx]) or -1) ~= -1 and "Статус: в сети" or "Статус: не в сети")
        imgui.TextDisabled("Параметры записи: Настройки → Чекер.")
        imgui.Separator()
    else
        imgui.Text("Выберите запись в списке.")
        imgui.Separator()
    end

    imgui.Text("Ник или ID игрока онлайн")
    imgui.InputText("##admin_name", admin_name_buffer)
    imgui.Text("Уровень")
    imgui.InputText("##admin_level", admin_level_buffer)
    imgui.Text("Должность")
    imgui.InputText("##admin_role", admin_role_buffer)
    imgui.Spacing()

    if imgui.Button("Сохранить", imgui.ImVec2(math.min(180, imgui.GetContentRegionAvailWidth()), 32)) then
        local nickname, player_id = resolve_name_and_id(trim(admin_name_buffer.v))

        if nickname and nickname ~= "" then
            upsert_admin(nickname, admin_level_buffer.v, player_id, admin_role_buffer.v)
            sync_online_ids()
            local sorted_index = find_index_by_name(admins_nick, nickname)

            if sorted_index ~= nil then
                select_admin(sorted_index - 1)
            end
        end
    end

    if imgui.GetContentRegionAvailWidth() >= 380 then imgui.SameLine() end
    if imgui.Button("Удалить", imgui.ImVec2(math.min(180, imgui.GetContentRegionAvailWidth()), 32)) then
        if selected_admin.v >= 0 and admins_nick[selected_admin.v + 1] ~= nil then
            remove_admin(admins_nick[selected_admin.v + 1])
            sync_online_ids()
            select_admin(-1)
        end
    end

    imgui.PopItemWidth()
    if side_by_side then imgui.Columns(1) end
end

