        if imgui.Button('Следующий##signature_paged', imgui.ImVec2(132, 30)) then
            ui.signature_mode[0] = ui.signature_mode[0] + 1
            if ui.signature_mode[0] > #SIGNATURE_VARIANT_LABELS then ui.signature_mode[0] = 1 end
        end
