    local function draw_keys()
        integration.keys:draw(imgui,'punish_confirm')
        integration.keys:draw(imgui,'punish_cancel')
    end

    AEGIS_ACTIVE_SETTINGS_PAGE = AEGIS_ACTIVE_SETTINGS_PAGE or 1
    AEGIS_SETTINGS_PAGES = {'Обработка', 'Команды', 'Уведомление', 'Клавиши'}
    integration.drawSettings = function()
        if not integration.access:can(2) then imgui.TextWrapped('Обработка ручных наказаний доступна с 2 уровня.');return end
        if not integration.access:can(3) then
            section('Ручная выдача наказаний')
            imgui.TextWrapped('Сложение срока работает при ручной выдаче. Приём запросов из /a и их подтверждение доступны с 3 уровня.')
            toggle('Выбирать команду по статусу игрока', ui.auto_switch_online_offline, 'switch_online')
            toggle('Уведомлять о форуме через /ans', ui.pre_punish_notice_enabled, 'ans_notice')
            for index=1,3 do
                local buffer=ui['forum_notice_line_'..index]
                imgui.InputText('##manual_notice_'..index,buffer,ffi.sizeof(buffer))
            end
            if imgui.Button('Сохранить##manual_settings') then
                SETTINGS.auto_switch_online_offline=ui.auto_switch_online_offline[0]
                SETTINGS.pre_punish_notice_enabled=ui.pre_punish_notice_enabled[0]
                for index=1,3 do SETTINGS['forum_notice_line_'..index]=get_imgui_buffer_text(ui['forum_notice_line_'..index]) end
                save_settings_file()
                message('Настройки сохранены.',true)
            end
            return
        end
        if command_editor.window[0] then draw_command_editor(); return end
        editor_group = nil
        local width = imgui.GetContentRegionAvail().x
        local per_row = width < 280 and 1 or (width < 640 and 2 or 4)
        local tab_width = math.min(150, math.max(80, (width - (per_row - 1) * 8) / per_row))
        for index, title in ipairs(AEGIS_SETTINGS_PAGES) do
            if (index - 1) % per_row ~= 0 then imgui.SameLine() end
            local selected = AEGIS_ACTIVE_SETTINGS_PAGE == index
            if selected then imgui.PushStyleColor(imgui.Col.Button, integration.color(integration.palette.selection)) end
            if imgui.Button(title .. '##page_' .. index, imgui.ImVec2(tab_width, 30)) then
                AEGIS_ACTIVE_SETTINGS_PAGE = index
                imgui.SetScrollY(0)
            end
            if selected then imgui.PopStyleColor(1) end
        end
        if AEGIS_ACTIVE_SETTINGS_PAGE == 1 then draw_toggles(width)
        elseif AEGIS_ACTIVE_SETTINGS_PAGE == 2 then draw_commands()
        elseif AEGIS_ACTIVE_SETTINGS_PAGE == 3 then draw_notice()
        else draw_keys() end
        imgui.Spacing()
        imgui.Separator()
        imgui.Spacing()
        if imgui.Button('Сохранить##paged', imgui.ImVec2(130, 30)) then
            apply_ui_to_settings()
            save_settings_file()
            message('Настройки сохранены.', true)
        end
        imgui.SameLine()
        if imgui.Button('Сбросить##paged', imgui.ImVec2(150, 30)) then
            copy_defaults()
            sanitize_settings()
            save_settings_file()
            sync_ui_from_settings()
            message('Настройки по умолчанию восстановлены.', true)
        end
    end

    integration.status = function()
        return {enabled = SETTINGS.enabled, pending = state.pending_request ~= nil, queued = #state.outgoing_queue}
    end

    integration.draw = function()
        if not integration.access:can(3) then imgui.TextWrapped('Автовыдача доступна с 3 уровня администратора.');return end
        local width = imgui.GetContentRegionAvailWidth()
        local columns = width >= 680
        if columns then
            imgui.Columns(2, 'punishment_overview', false)
            imgui.SetColumnWidth(0, width * 0.60)
        end
        section('Активный запрос')
        if state.pending_request then
            local request = state.pending_request
            local expires = math.max(0, math.floor(SETTINGS.request_timeout - (os.clock() - request.created_at)))
            local command = build_issued_command(request)
            meta('Администратор', request.admin_name .. '[' .. tostring(request.admin_id) .. ']')
            meta('Игрок', request.target_label or '—')
            imgui.TextWrapped(request.command_text)
            if command ~= request.command_text then meta('Итоговая команда', command) end
            imgui.Spacing()
            imgui.TextDisabled('До отмены: ' .. expires .. ' сек.')
            if imgui.Button('Выдать', imgui.ImVec2(120, 32)) then handle_confirm() end
            imgui.SameLine()
            if imgui.Button('Отменить', imgui.ImVec2(120, 32)) then handle_cancel() end
        else
            imgui.TextDisabled('Новых запросов нет')
            imgui.TextWrapped('Новый запрос из /a появится здесь с игроком, автором и командой.')
        end
        section('Состояние')
        imgui.TextColored(integration.color(SETTINGS.enabled and integration.palette.green or integration.palette.muted),
            SETTINGS.enabled and 'Обработка запросов включена' or 'Обработка запросов выключена')
        imgui.TextWrapped(state.status_line ~= '' and state.status_line or 'Готово к работе.')
        meta('Команд в очереди', #state.outgoing_queue)
        if columns then imgui.NextColumn() end
        section('Защищённые игроки')
        local snapshot=integration.protectedLists and integration.protectedLists(false)
        local admins,leaders,unique={},{},{}
        if snapshot then
            for _,name in ipairs(snapshot.admins) do admins[lower(name)]=true;unique[lower(name)]=true end
            for _,name in ipairs(snapshot.leaders) do leaders[lower(name)]=true;unique[lower(name)]=true end
        end
        local function count(set) local n=0;for _ in pairs(set) do n=n+1 end;return n end
        meta('Администраторы',snapshot and count(admins) or state.known_admin_only_count)
        meta('Лидеры',snapshot and count(leaders) or state.known_leader_count)
        meta('Уникальных ников',snapshot and count(unique) or state.known_admin_count)
        imgui.TextWrapped(SETTINGS.block_known_admin_targets and 'Защита включена' or 'Ban и warn защищены всегда. Защита от остальных наказаний выключена.')
        
        if imgui.Button('Перечитать списки') then refresh_protected_list() end
        if imgui.Button('Настроить списки в чекере') then integration.openSettings('adm') end
        imgui.Spacing()
        section('Шаблоны команд')
        meta('С уведомлением о форуме', count_command_group(state.forum_notice_commands))
        meta('Без уведомления', count_command_group(state.no_notice_commands))
        meta('Из админ-чата', count_command_group(state.admin_chat_commands))
        meta('С отчётом', count_command_group(state.report_commands))
        imgui.TextWrapped('Числа выше — количество шаблонов в группах, не игроков и не выданных наказаний.')
        imgui.Spacing()
        if imgui.Button('Открыть справку', imgui.ImVec2(168, 30)) then integration.openHelp('punishments') end
        imgui.Spacing()
        imgui.TextWrapped('Шаблоны, уведомления и клавиши — во вкладке «Настройки».')
        if columns then imgui.Columns(1) end
    end

end

integration.matchPunishment=function(command,text,expectedTarget)
    local kind,target=command:match('^/(%S+)%s+(%S+)')
    if not kind then return false end
    kind=kind:lower()
    local verbs={offban='забанил',ban='забанил',jail='посадил',offjail='посадил',mute='затычку',offmute='затычку',warn='предупреждение',offwarn='предупреждение',kick='кикнул'}
    if not verbs[kind] or not text:find(verbs[kind],1,true) then return false end
    local id=tonumber(target)
    local nick=expectedTarget or (id and sampIsPlayerConnected(id) and sampGetPlayerNickname(id) or target)
    local issuer= parse_punishment_info_for_request(text,{kind="/"..kind,target_name=nick,target_id=id,target_label=nick})
    local _,localName=get_local_identity()
    return issuer~=nil and localName~=nil and lower(issuer)==lower(localName)
end

if ui then
	setup_aegis_ui()
end

function integration.start()
	while not isSampAvailable() do
		wait(100)
	end

	math.randomseed(os.time() + math.floor(os.clock() * 1000))
	math.random()
	math.random()

	ensure_files()
	load_settings_file()
    integration.keys:register('punish_confirm','Автовыдача: подтвердить',{key=SETTINGS.confirm_key},function(bind) SETTINGS.confirm_key=bind.key end)
    integration.keys:register('punish_cancel','Автовыдача: отменить',{key=SETTINGS.cancel_key},function(bind) SETTINGS.cancel_key=bind.key end)
	load_known_admins()
	sync_ui_from_settings()

	debug_message(string.format("Старт скрипта. admin_chat_color=%d, debug=%s, ans=%s", SETTINGS.admin_chat_color, tostring(SETTINGS.debug_enabled), tostring(SETTINGS.pre_punish_notice_enabled)), true)

	while true do
		wait(0)
		process_pending()
		safe_draw_pending_request_overlay()
	end
end

function integration.stop()
	do
		release_request_overlay_fonts()
	end
end

function sampev.onServerMessage(color, text)
	text = cp1251_to_utf8(text)

	local is_candidate = is_debug_candidate(color, text)

	if is_candidate then
		debug_message(string.format("Входящее сообщение: color=%d, text=%s", color, text), true)
	end

	if is_user_afk_protected() then
		if not state.afk_guard_active then
			state.afk_guard_active = true
			clear_afk_sensitive_contexts()
		end
		return
	end

	if is_afk_exit_suppressed() then
		if is_candidate then
			debug_message("Игнор: сообщение пропущено во время защиты после выхода из AFK.", true)
		end
		return
	end

	if state.awaiting_punishment_guard_context ~= nil then
		local queued_issuer_name = parse_punishment_info_for_request(text, state.awaiting_punishment_guard_context)

		if queued_issuer_name ~= nil then
			finalize_queued_punished(state.awaiting_punishment_guard_context, queued_issuer_name)
			return
		end
	end

	if handle_existing_term_stack(text) then
		return
	end

	if handle_online_offline_switch_hint(text) then
		return
	end

	if state.awaiting_database_lookup_context ~= nil and text:find("Такого игрока нет в базе данных", 1, true) ~= nil then
		local admin_name = trim(tostring(state.awaiting_database_lookup_context.admin_name or ""))

		if admin_name ~= "" then
			enqueue_admin_chat_status(string.format("%s, такого игрока нет в базе данных.", admin_name), "offline-db-miss")
			message(string.format("Отправлено в /a: %s, такого игрока нет в базе данных.", admin_name), true)
		end

		state.awaiting_database_lookup_context = nil
		return
	end

	if state.pending_request ~= nil then
		local issuer_name = parse_punishment_info_for_request(text, state.pending_request)

		if issuer_name ~= nil then
			finalize_pending_punished(state.pending_request, issuer_name, string.format("Ожидающая команда снята: игрок %s уже наказан администратором %s.", get_request_target_display_name(state.pending_request), issuer_name))
			return
		end
	end

	if should_cancel_on_server_activity(color, text) then
		debug_message("Сработала автоотмена по активности цели.", true)
		cancel_pending("Запрос отменён: сервер сообщил о действиях с этим игроком.", "Запрос отменён: сервер сообщил о действиях с этим игроком.")
		return
	end

	if not SETTINGS.enabled then
		if is_candidate then
			debug_message("Игнор: функция выключена.", true)
		end
		return
	end

	if state.pending_request ~= nil then
		if is_candidate then
			debug_message("Игнор: уже есть ожидающая команда.", true)
		end
		return
	end

	if color ~= SETTINGS.admin_chat_color then
		if is_candidate then
			debug_message(string.format("Игнор: цвет %d не совпадает с настройкой %d.", color, SETTINGS.admin_chat_color), true)
		end
		return
	end

	if isGamePaused() or isPauseMenuActive() then
		debug_message("Игнор: игра на паузе или открыто меню паузы.", true)
		return
	end

	if text:find("]: /", 1, true) == nil then
		debug_message("Игнор: в сообщении нет фрагмента ']: /'.", true)
		return
	end

	local admin_name, admin_id, command_text = text:match("%[A%]%s*(.-)%[(%d+)%]%s*:%s*(/.*)")

	if not admin_name or not admin_id or not command_text then
		debug_message("Игнор: не удалось распознать ник, ID или команду.", true)
		return
	end

	command_text = trim(command_text)
	debug_message(string.format("Парсер строки: admin=%s, id=%s, command=%s", admin_name, admin_id, command_text), true)

	local command_name = get_command_name_from_text(command_text)

	if not is_reactive_command(command_name) then
		debug_message("Игнор: команда не входит в группу отслеживания админ-чата: " .. tostring(command_name or command_text), true)
		return
	end

	local request = parse_admin_chat_request(admin_name, admin_id, command_text)

	if request == false then
		debug_message("Команда распознана, но цель не в сети: " .. command_text, true)
		message(string.format("Запрос %s[%s] пропущен: игрок с указанным ID не в сети.", admin_name, admin_id), true)
		append_log(string.format("Команда из админ-чата от %s[%s] проигнорирована: указанный ID не в сети: %s", admin_name, admin_id, command_text))
		append_request_log("IGNORED", {
			admin_name = admin_name,
			admin_id = tonumber(admin_id),
			command_text = command_text,
			target_label = "-",
			target_name = "-"
		}, "указанный ID не в сети", nil)
		return
	end

	if request == nil then
		debug_message("Игнор: команда не поддерживается парсером: " .. command_text, true)
		return
	end

	if not is_reactive_command(request.kind) then
		debug_message("Игнор: команда не входит в список реакций: " .. request.kind, true)
		return
	end

	if is_user_afk_protected() then
		debug_message("Игнор: запрос из админ-чата пропущен из-за AFK защиты.", false)
		return
	end

	if is_afk_exit_suppressed() then
		debug_message("Игнор: запрос из админ-чата пропущен во время защиты после выхода из AFK.", false)
		return
	end

	debug_message("Команда успешно распознана и передаётся в захват.", true)
	capture_request(request)
end

function sampev.onSendCommand(command)
	touch_user_activity()

	if state.bypass_outgoing_hook > 0 then
		return
	end

	local command_text = trim(cp1251_to_utf8(command or ""))

	if command_text == "" then
		return
	end

	local command_name = get_command_name_from_text(command_text)

	if command_name == nil then
		return
	end

	if not is_manual_command_tracked(command_name) then
		return
	end

	local request = parse_manual_outgoing_request(command_text)

	if request == nil then
		if is_forum_notice_command(command_name) and SETTINGS.pre_punish_notice_enabled then
			debug_message("Ручная команда из списка реакций не была обработана: цель не определилась как онлайн: " .. command_text, true)
		end
		return
	end

	local local_switch = build_local_online_switch_result(request, request.command_text)

	if local_switch ~= nil then
		state.awaiting_online_offline_switch_context = nil
		debug_message("Ручная команда локально автопереключена: " .. request.command_text .. " -> " .. local_switch.command_text, true)
		message(string.format("Команда изменена по статусу игрока: %s → %s", request.command_text, local_switch.command_text), true)
		append_log(string.format("Ручная команда локально автопереключена: %s -> %s", request.command_text, local_switch.command_text))
		queue_pre_punish_bundle(local_switch.request, local_switch.command_text, "manual-local-online-switch")

		if should_send_pre_punish_notice(local_switch.request) then
			message(string.format("Перед наказанием %s будут отправлены уведомления /ans.", local_switch.request.target_label or ("ID " .. tostring(local_switch.request.target_id or "?"))), true)
		end

		return false
	end


	if is_forum_notice_command(command_name) and SETTINGS.pre_punish_notice_enabled then
		debug_message("Перехвачена ручная команда: " .. request.command_text, true)

		if not is_request_target_online(request) then
			if SETTINGS.auto_switch_online_offline == true then
				local switch_context = build_online_offline_switch_context(request, request.command_text, nil)

				if switch_context ~= nil then
					state.awaiting_online_offline_switch_context = switch_context
					append_log(string.format("Ручная команда поставлена на автопереключение: %s", request.command_text))
				end
			end

			debug_message("Ручная команда из группы форум-уведомлений пропущена без /ans: цель не в онлайне: " .. command_text, true)
			return
		end

		queue_pre_punish_bundle(request, request.command_text, "manual-command")
		message(string.format("Перед наказанием %s будут отправлены уведомления /ans.", request.target_label or ("ID " .. tostring(request.target_id or "?"))), true)
		return false
	end

	if SETTINGS.auto_switch_online_offline == true then
		local switch_context = build_online_offline_switch_context(request, request.command_text, nil)

		if switch_context ~= nil then
			state.awaiting_online_offline_switch_context = switch_context
			append_log(string.format("Ручная команда поставлена на автопереключение: %s", request.command_text))
		end
	end

	local stack_term_context = get_stackable_term_context(request, request.command_text, nil)

	if stack_term_context ~= nil then
		state.awaiting_stack_term_context = stack_term_context
	end

	debug_message("Отслеживается ручная команда без очереди: " .. request.command_text, false)
end

function sampev.onPlayerQuit(playerId, reason)
	local request = state.pending_request

	if request == nil or request.target_id == nil or not is_online_punish_command(request.kind) then
		return
	end

	if tonumber(request.target_id) ~= tonumber(playerId) then
		return
	end

	debug_message(string.format("Игрок %s[%d] вышел из игры во время ожидания команды.", request.target_name or "?", request.target_id), true)
	finalize_pending_target_left(request, string.format("Ожидающая команда снята: игрок %s[%d] вышел из игры.", request.target_name or "?", request.target_id))
end

-- A reconnect invalidates pending requests, targets and delayed commands.
integration.onDisconnect = function()
    clear_afk_sensitive_contexts()
    state.next_outgoing_at = 0
    state.bypass_outgoing_hook = 0
end

    end
    sources["modules/airbreak.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/airbreak.lua
-- Original third-party credits, where present, are retained below.
-- AirBreak controls reconstructed from AirBreak (2).cs; no camera resets or helper actors.
local g=require('imgui')
local cfg,path=integration.storage:loadIni({main={mode=2,enabled=true,mouse_turn=true}},integration.storage:path('settings','airbreak.ini')),integration.storage:path('settings','airbreak.ini')
local geometry=integration.service('flight_geometry.lua')
local mouseOffset=0
local active,ped,car,heading,speed,vertical,last=false,nil,nil,0,0,0,nil
local animationOwned=false
local function keepAnimation()
    if not car and ped and doesCharExist(ped) and not isCharPlayingAnim(ped,'Swim_Tread')then
        taskPlayAnimNonInterruptable(ped,'Swim_Tread','PED',4.1,true,false,false,false,-1)
        animationOwned=true
    end
end
-- Exact entity position: ped teleports clear animations; vehicle teleports
-- apply a placement offset that accumulates if fed back every frame.
local function movePreservingAnimation(x,y,z)
    local address
    if car then address=getCarPointer(car)else address=getCharPointer(ped)end
    if not address or address==0 then return false end
    local matrix=readMemory(address+0x14,4,false)
    if not matrix or matrix==0 then return false end
    for index,value in ipairs({x,y,z})do
        writeMemory(matrix+0x30+(index-1)*4,4,representFloatAsInt(value),false)
    end
    return true
end
local profiles={{0.1,5,0.01,1,1,0},{2,30,0.2,3,30,0.3},{50,200,1,50,50,0}}
local function stop()
    active=false
    if car and doesVehicleExist(car) then freezeCarPosition(car,false);setCarCollision(car,true) end
    if not car and ped and doesCharExist(ped) then
        freezeCharPosition(ped,false);setCharCollision(ped,true)
        if animationOwned and isCharPlayingAnim(ped,'Swim_Tread')then clearCharTasks(ped)end
    end
    animationOwned=false
    car=nil;ped=nil;last=nil
end
integration.stop=stop;integration.onDisconnect=stop;integration.onAccessChanged=stop;integration.isActive=function()return active end
integration.keys:register('airbreak','AirBreak: включить / выключить',{key=50,ctrl=true})
integration.keys:register('airbreak_stop','AirBreak: выключить',{key=51,ctrl=true})
local saved=integration.keys.data.airbreak
if saved and saved.key==188 and not saved.ctrl and not saved.alt and not saved.shift and saved.second==0 then
    saved.key=50;saved.ctrl=true;integration.storage:saveIni(integration.keys.data,integration.keys.path)
end
local function usable()
    return sampGetGamestate()==3 and doesCharExist(PLAYER_PED) and not isCharDead(PLAYER_PED) and not integration.observation()
end
local function start()
    if active then stop();return end
    if cfg.main.enabled~=true then return end
    if not usable() or not integration.access:require(1,integration.message) then return end
    integration.claimFlight()
    ped=PLAYER_PED;heading=getCharHeading(ped);speed=0;vertical=0;last=getGameTimer()
    if isCharInAnyCar(ped) then
        car=storeCarCharIsInNoSave(ped)
        if not car or not doesVehicleExist(car) then ped=nil;car=nil;return end
        heading=getCarHeading(car);freezeCarPosition(car,true);setCarCollision(car,false)
    else freezeCharPosition(ped,true);setCharCollision(ped,false) end
    mouseOffset=0
    active=true
end
integration.update=function()
    local toggle=integration.keys:pressed('airbreak');local exit=integration.keys:pressed('airbreak_stop')
    local input=not integration.windowOpen() and isGameWindowForeground() and not isPauseMenuActive() and not sampIsChatInputActive() and not sampIsDialogActive() and not sampIsCursorActive()
    if input and exit then stop();return end
    if input and toggle then start() end
    if not active then return end
    if not usable() or ped~=PLAYER_PED or (car and (not doesVehicleExist(car) or not isCharInCar(ped,car))) or (not car and isCharInAnyCar(ped)) then stop();return end
    local now=getGameTimer();local dt=math.min(3,math.max(0,(now-(last or now))/16.6667));last=now
    if not input then keepAnimation();return end
    for mode,key in ipairs({97,98,99})do if isKeyDown(key)then cfg.main.mode=mode end end
    local mode=math.floor(math.max(1,math.min(3,tonumber(cfg.main.mode)or 2)));local p=profiles[mode]
    if car then p=mode==3 and {8,20,3,8,40,3}or {1,11,0.1,mode==1 and 0.5 or 1,11,0.1}end
    local forward=(isKeyDown(87)and 1 or 0)-(isKeyDown(83)and 1 or 0)
    local side=(isKeyDown(68)and 1 or 0)-(isKeyDown(65)and 1 or 0)
    local up=((isKeyDown(81)or(car and isKeyDown(38)))and 1 or 0)-((isKeyDown(69)or(car and isKeyDown(40)))and 1 or 0)
    speed=(forward~=0 or side~=0)and math.min(p[2],math.max(p[1],speed)+p[3]*dt)or p[1]
    vertical=up~=0 and math.min(p[5],math.max(p[4],vertical)+p[6]*dt)or p[4]
    local turn=((isKeyDown(37)and 1 or 0)-(isKeyDown(39)and 1 or 0))*4*dt
    local camera=cfg.main.mouse_turn and geometry.cameraHeading(_G)
    if camera then mouseOffset=(mouseOffset+turn)%360;heading=(camera+mouseOffset)%360
    else heading=(heading+turn)%360 end
    local x,y,z;if car then x,y,z=getCarCoordinates(car)else x,y,z=getCharCoordinates(ped)end
    local a=math.rad(heading)
    x=x+(-math.sin(a)*forward+math.cos(a)*side)*speed*dt
    y=y+(math.cos(a)*forward+math.sin(a)*side)*speed*dt
    local climb=up*vertical
    if not car and mode==1 then climb=up>0 and 1.5 or (up<0 and -0.5 or 0)
    elseif not car and mode==3 then climb=up>0 and 11 or (up<0 and -39 or 0)end
    z=z+climb*dt
    if not car and isKeyDown(40) then z=getGroundZFor3dCoord(x,y,z)+1 end
    if car then
        setCarHeading(car,heading)
        if forward~=0 or side~=0 or up~=0 then
            if not movePreservingAnimation(x,y,z)then stop();return end
        end
    else
        setCharHeading(ped,heading)
        if forward~=0 or side~=0 or up~=0 or isKeyDown(40)then
            if not movePreservingAnimation(x,y,z)then stop();return end
        end
    end
    keepAnimation()
end
local settingsExpanded=false
integration.drawSettings=function()
    local value=g.ImBool(cfg.main.enabled==true)
    if g.Checkbox('AirBreak',value)then
        cfg.main.enabled=value.v
        integration.storage:saveIni(cfg,path)
        if not value.v then stop()end
    end
    g.SameLine()
    if g.Button('Настройки##airbreak_settings') then settingsExpanded=not settingsExpanded end
    if not settingsExpanded then return end
    g.TextDisabled('AirBreak '..(active and 'работает' or 'не запущен'))
    integration.keys:draw(g,'airbreak');integration.keys:draw(g,'airbreak_stop')
    local mode=g.ImInt((tonumber(cfg.main.mode)or 2)-1)
    if g.Combo('Скорость##airbreak',mode,{'Медленно','Обычно','Быстро'})then cfg.main.mode=mode.v+1;integration.storage:saveIni(cfg,path)end
    local mouse=g.ImBool(cfg.main.mouse_turn==true)
    if g.Checkbox('Поворачивать за мышью##airbreak_mouse',mouse)then cfg.main.mouse_turn=mouse.v;mouseOffset=0;integration.storage:saveIni(cfg,path)end
    g.TextWrapped('WASD — движение; Q/E — вверх/вниз пешком и в машине; ↑/↓ — также высота транспорта; мышь — направление; ←/→ — поворот. Num 1/2/3 — скорость. ↓ пешком — опуститься на землю.')
    
end

    end
    sources["modules/autoreply.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/autoreply.lua
-- Original third-party credits, where present, are retained below.
-- AutoSalamReport from COMBO by Casual Alvarez. Only automatic replies are imported.
local g=require('imgui')
local events=require('lib.samp.events')
local u8=require('encoding').UTF8
local settings=integration.service('combo_settings.lua')
local defaults={main={enabled=false,afk_protect=true,return_delay=15,reply_delay=2,id_cooldown=5,
    message_cooldown=15,time_shift_minutes=0,debug=false,strict_color_filter=true,strict_color=1724645631},
    row1={name='Спасибо',words='спс,спасибо,thx,thank,благодарю',match_mode='contains',enabled=true,
        answer1='/ans %id% Приятной игры на Advance RP =)',answer2='/ans %id% Удачной игры =)'},
    row2={name='Приветствие',words='привет,hello,здравствуйте,здрасте,добрый день,добрый вечер,здарова,дарова,прив,салам',
        match_mode='contains',enabled=true,answer1='/ans %id% Добрый день, приятной игры =)'}}
defaults.main.goodgame_news=false;defaults.main.goodgame_nickname=false
defaults.main.goodgame_text='Приятной игры на Advance RP =)'
local cfg,path=settings.load(integration,'autoreply',defaults)
local wishes={}
local greeting=g.ImBuffer(cfg.main.goodgame_text,512)
local selected,editor=1,nil
local generation,ids,messages=0,{},{}
local inactive,returned,lastClean=false,-100000,0
local function now() return getGameTimer()/1000 end
local function ruleDelay(rule)
    return settings.limit(rule.delay_seconds,settings.limit(cfg.main.reply_delay,2,0,300),0,300)
end
local function active() return isGameWindowForeground() and not isPauseMenuActive() and not isGamePaused() end
local function ready()
    local time=now()
    if not active() then inactive=true;return false end
    if inactive then inactive=false;returned=time end
    return cfg.main.afk_protect==false or time-returned>=settings.limit(cfg.main.return_delay,15,0,600)
end
local function save() generation=generation+1;integration.storage:saveIni(cfg,path) end
local function normalized(text)
    text=text:gsub('{%x%x%x%x%x%x}',''):lower()
    local upper,lower='АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ','абвгдеёжзийклмнопрстуфхцчшщъыьэюя'
    for i=1,#upper,2 do text=text:gsub(upper:sub(i,i+1),lower:sub(i,i+1)) end
    return text:gsub('[%p%c]',' '):gsub('%s+',' '):match('^%s*(.-)%s*$')
end
local function matches(rule,text)
    for word in tostring(rule.words or ''):gmatch('[^,]+') do
        word=normalized(word)
        if word~='' and ((rule.match_mode=='exact' and word==text) or (rule.match_mode~='exact' and text:find(word,1,true))) then return true end
    end
    return false
end
function events.onServerMessage(color,text)
    local kind,target,nick=integration.service('goodgame_event.lua').parse(u8(text))
    if kind and cfg.main['goodgame_'..kind]==true and integration.access:can(1) and ready()then
        if not target then
            for id=0,math.min(1003,sampGetMaxPlayerId(false))do
                if sampIsPlayerConnected(id) and sampGetPlayerNickname(id)==nick then target=id;break end
            end
        end
        local found,selfID=sampGetPlayerIdByCharHandle(PLAYER_PED)
        if target and sampIsPlayerConnected(target) and not(found and target==selfID)then
            local key=kind..':'..target..':'..nick
            local time=now()
            if not wishes[key]or time-wishes[key]>90 then
                local message=tostring(cfg.main.goodgame_text)
                local command=u8:decode('/ans '..target..' '..message)
                if message:find('%S') and not message:find('[%z\1-\31]') and #command<=144 then
                    wishes[key]=time;local token=generation
                    lua_thread.create(function()
                        wait(math.max(500,1000*settings.limit(cfg.main.reply_delay,2,0,300)))
                        if token~=generation or not cfg.main['goodgame_'..kind] or not integration.access:can(1) or not ready()then return end
                        if sampGetGamestate()==3 and sampIsPlayerConnected(target) and sampGetPlayerNickname(target)==nick then sampSendChat(command)end
                    end)
                end
            end
        end
        return
    end
    if cfg.main.enabled~=true or not integration.access:can(1) or not ready() then return end
    if cfg.main.strict_color_filter~=false and color~=tonumber(cfg.main.strict_color) then return end
    local id,question=integration.service('report_reader.lua').parse(u8(text))
    if not id or not sampIsPlayerConnected(id) then return end
    local found,localID=sampGetPlayerIdByCharHandle(PLAYER_PED);if found and localID==id then return end
    question=question:gsub('{%x%x%x%x%x%x}','')
    local norm=normalized(question);if norm=='' then return end
    local time=now()
    for i=1,100 do local rule=cfg['row'..i]
        if rule and not rule.deleted and rule.enabled~=false and matches(rule,norm) then
            local key=id..'|'..i..'|'..norm
            if ids[id] and time-ids[id]<settings.limit(cfg.main.id_cooldown,5,0,3600) then return end
            if messages[key] and time-messages[key]<settings.limit(cfg.main.message_cooldown,15,0,3600) then return end
            local answers={};for n=1,5 do local answer=tostring(rule['answer'..n] or '')
                if answer:find('%S') then answers[#answers+1]=answer end
            end
            if #answers==0 then return end
            local template=answers[math.random(#answers)]
            local timestamp=os.time()+60*settings.limit(cfg.main.time_shift_minutes,0,-1440,1440)
            local values={id=tostring(id),text=question,time=os.date('%H:%M',timestamp),date=os.date('%d.%m.%Y',timestamp)}
            local command=template:gsub('%%(%w+)%%',function(name)return values[name] or '%'..name..'%' end)
            local encoded=u8:decode(command)
            if command:find('[%z\1-\31]') or #encoded>144 then return end
            ids[id],messages[key]=time,time
            local token=generation;local nick=sampGetPlayerNickname(id)
            local delay=ruleDelay(rule)
            lua_thread.create(function()
                if delay>0 then wait(1000*delay)end
                if token~=generation or cfg.main.enabled~=true or sampGetGamestate()~=3 or not integration.access:can(1) or not ready() then return end
                if not sampIsPlayerConnected(id) or sampGetPlayerNickname(id)~=nick then return end
                sampSendChat(encoded)
                if cfg.main.debug then integration.message('Автоответ: сработало правило '..tostring(rule.name or i)..' для ID '..id) end
            end)
            return
        end
    end
end
integration.update=function()
    ready()
    if now()-lastClean>60 then
        lastClean=now()
        for key,time in pairs(messages) do if now()-time>3600 then messages[key]=nil end end
        for key,time in pairs(ids) do if now()-time>3600 then ids[key]=nil end end
        for key,time in pairs(wishes)do if now()-time>3600 then wishes[key]=nil end end
    end
end
integration.onDisconnect=function() generation=generation+1;ids={};messages={};wishes={};inactive=true end
local function beginEditor(index)
    selected=index;local row=cfg['row'..index] or {}
    editor={name=g.ImBuffer(tostring(row.name or 'Новое правило'),256),words=g.ImBuffer(tostring(row.words or ''),4096),
        mode=g.ImInt(row.match_mode=='exact' and 1 or 0),enabled=g.ImBool(row.enabled~=false),
        ownDelay=g.ImBool(row.delay_seconds~=nil),delay=g.ImInt(ruleDelay(row)),answers={}}
    for i=1,5 do editor.answers[i]=g.ImBuffer(tostring(row['answer'..i] or ''),1024) end
end
integration.draw=function()
    g.Text('Пожелания приятной игры')
    if settings.toggle(g,'Желать приятной игры на гос. новости',cfg.main,'goodgame_news')then save()end
    if settings.toggle(g,'Желать приятной игры на смену nickname',cfg.main,'goodgame_nickname')then save()end
    g.PushItemWidth(360)
    if g.InputText('Текст пожелания',greeting)then cfg.main.goodgame_text=greeting.v;save()end
    g.PopItemWidth();g.Separator()
    if settings.toggle(g,'Использовать автоответ',cfg.main,'enabled') then save() end
    local columns=integration.layout.begin('autoreply_rules',700)
    g.Text('Правила')
    for i=1,100 do local row=cfg['row'..i]
        if row and not row.deleted and g.Selectable((row.enabled~=false and '[ВКЛ] ' or '[ВЫКЛ] ')..tostring(row.name or i)..'##reply_rule_'..i,selected==i) then selected=i;editor=nil end
    end
    if g.Button('Создать##reply') then for i=1,100 do if not cfg['row'..i] or cfg['row'..i].deleted then beginEditor(i);break end end end
    g.SameLine();if g.Button('Редактировать##reply') then beginEditor(selected) end
    if g.Button('Удалить##reply') then cfg['row'..selected]={deleted=true,enabled=false};editor=nil;save() end
    integration.layout.next(columns)
    local ui=integration.service('dossier_ui.lua').new(g,integration)
    if editor then
        g.PushItemWidth(-1)
        g.Text('Название');g.InputText('##reply_name',editor.name)
        g.Checkbox('Правило включено',editor.enabled)
        g.Text('Ключи через запятую');g.InputText('##reply_words',editor.words)
        g.Combo('Совпадение',editor.mode,'Частичное\0Точное\0\0')
        g.Checkbox('Своя задержка ответа или действия',editor.ownDelay)
        if editor.ownDelay.v then
            g.SliderInt('Задержка, сек.##reply_rule_delay',editor.delay,0,300)
            g.TextWrapped('0 — сразу. Задержка действует на любой ответ или команду этого правила.')
        else g.TextWrapped('Используется общая задержка: '..ruleDelay({})..' сек.')end
        for i=1,5 do g.Text('Ответ '..i);g.InputText('##reply_answer_'..i,editor.answers[i]) end
        g.PopItemWidth()
        if g.Button('Сохранить правило##reply') then
            local row={name=editor.name.v,words=editor.words.v,enabled=editor.enabled.v,match_mode=editor.mode.v==1 and 'exact' or 'contains'}
            if editor.ownDelay.v then row.delay_seconds=settings.limit(editor.delay.v,2,0,300)end
            for i=1,5 do row['answer'..i]=editor.answers[i].v end
            cfg['row'..selected]=row;save();editor=nil
        end
    else
        local row=cfg['row'..selected]
        if row and not row.deleted then
            local pos=ui.cursor();local width=g.GetContentRegionAvailWidth();local inner=math.max(1,width-32)
            local title=tostring(row.name or 'Без названия')
            local titleH=ui.measure(title,inner,20,true)
            local state=row.enabled~=false and 'Включено' or 'Выключено'
            local stateH=ui.measure(state,inner,13)
            local height=titleH+stateH+38
            ui.rect(pos.x,pos.y,width,height,integration.palette.surface,8,.98)
            ui.rect(pos.x,pos.y+12,3,height-24,'accent',1)
            ui.text(pos.x+16,pos.y+14,inner,title,'normal',20,true)
            ui.text(pos.x+16,pos.y+titleH+20,inner,state,row.enabled~=false and 'accent'or 'muted',13)
            ui.finish(pos.x,pos.y,width,height)
            local words={}
            for word in tostring(row.words or ''):gmatch('[^,]+')do
                word=word:match('^%s*(.-)%s*$');if word~=''then words[#words+1]=word end
            end
            ui.table('reply_conditions','КОГДА СРАБАТЫВАЕТ',{{label='Параметр',weight=.34},{label='Значение',weight=.66}},{
                {'Ключевые слова',#words>0 and table.concat(words,' · ')or 'Не заданы'},
                {'Совпадение',row.match_mode=='exact'and 'Точное'or 'Частичное'},
                {'Задержка',ruleDelay(row)..' сек. · '..(row.delay_seconds==nil and 'общая'or 'для этого правила')}
            })
            local answers={}
            for i=1,5 do local answer=row['answer'..i]
                if answer and answer~=''then answers[#answers+1]={{text=string.format('%02d',i),tone='accent'},answer}end
            end
            ui.table('reply_answers','ВАРИАНТЫ ОТВЕТА',{{label='№',weight=.15},{label='Сообщение или команда',weight=.85}},answers,'Ответы пока не заданы.')
            g.TextWrapped('При срабатывании выбирается один случайный ответ из заполненных вариантов.')
        else g.TextWrapped('Создайте правило или выберите его в списке.') end
    end
    g.Spacing()
    if g.CollapsingHeader('Подстановки и правила поиска##reply_reference')then
        ui.table('reply_tokens','ПОДСТАНОВКИ',{{label='Код',weight=.3},{label='Заменяется на',weight=.7}},{
            {{text='%id%',tone='accent'},'ID игрока'},{{text='%text%',tone='accent'},'Текст обращения'},
            {{text='%time%',tone='accent'},'Время'},{{text='%date%',tone='accent'},'Дата'}
        })
        g.TextWrapped('При поиске ключевых слов регистр и пунктуация не учитываются.')
    end
    integration.layout.finish(columns)
end
integration.drawSettings=function()
    local changed=false
    for _,item in ipairs({{'Использовать автоответ','enabled'},{'Защита после возврата в игру','afk_protect'},
        {'Режим отладки','debug'},{'Строгая фильтрация по цвету','strict_color_filter'}}) do changed=settings.toggle(g,item[1],cfg.main,item[2]) or changed end
    g.PushItemWidth(180)
    for _,item in ipairs({{'Задержка после возврата, сек.','return_delay',15,0,600},{'Задержка ответа, сек.','reply_delay',2,0,300},
        {'Интервал по ID, сек.','id_cooldown',5,0,3600},{'Интервал по тексту, сек.','message_cooldown',15,0,3600},
        {'Смещение времени, мин.','time_shift_minutes',0,-1440,1440},{'Цвет строгого режима','strict_color',1724645631,-2147483648,2147483647}}) do
        changed=settings.integer(g,item[1],cfg.main,item[2],item[3],item[4],item[5]) or changed
    end
    g.PopItemWidth();if changed then save() end
    
end

    end
    sources["modules/autostart.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/autostart.lua
-- Original third-party credits, where present, are retained below.
-- AutoStart from COMBO by Casual Alvarez, on the shared scheduler and storage.
local g=require('imgui')
local settings=integration.service('combo_settings.lua')
local defaults={main={enabled=true,debug=false,initial_delay_ms=1000,retry_on_reconnect=true}}
local cfg,path=settings.load(integration,'autostart',defaults)
local MAX_ROWS=100
local function normalizeRows()
    local rows={}
    if cfg.main.row_count==nil then
        -- Migrate the old fixed 20 slots, keeping disabled commands and their order.
        for i=1,MAX_ROWS do
            local row=cfg['row'..i]
            if type(row)=='table' and (tostring(row.command or ''):match('%S') or row.enabled==true) then rows[#rows+1]=row end
        end
    else
        for i=1,math.floor(settings.limit(cfg.main.row_count,0,0,MAX_ROWS)) do
            rows[#rows+1]=cfg['row'..i] or {enabled=false,mode='auto',delay_ms=500,command=''}
        end
    end
    for i=1,MAX_ROWS do cfg['row'..i]=rows[i] end
    cfg.main.row_count=#rows
end
normalizeRows()
integration.storage:saveIni(cfg,path)
local buffers={};local generation,running,ranSession,ranEver=0,false,false,false
local status='Ожидание первого появления в игре.'
local function save() integration.storage:saveIni(cfg,path) end
local function active()
    return sampGetGamestate()==3 and integration.access:can(1) and isGameWindowForeground() and not isPauseMenuActive()
end
-- Keep the current row inside the coroutine while the game is inactive.
-- Delays count active time only; cancellation invalidates the saved position.
local function delayActive(ms,token)
    local remaining=ms
    while token==generation do
        if cfg.main.enabled~=true then return false end
        if not active() or not sampIsLocalPlayerSpawned() then
            status='Приостановлено: ожидание возвращения в игру.'
            wait(100)
        elseif remaining<=0 then return true
        else
            local step=math.min(100,remaining)
            wait(step)
            if active() then remaining=remaining-step end
        end
    end
    return false
end
local function cancelRun()
    generation=generation+1;running=false;ranSession=true
end
local function run()
    if running or cfg.main.enabled~=true or not active() then return end
    running=true;ranSession=false;ranEver=true
    local token=generation;local rows={}
    for i=1,cfg.main.row_count do local source=cfg['row'..i];if source and source.enabled then
        rows[#rows+1]={command=tostring(source.command or ''),mode=source.mode,delay=settings.limit(source.delay_ms,500,0,60000),index=i}
    end end
    lua_thread.create(function()
        if not delayActive(settings.limit(cfg.main.initial_delay_ms,1000,0,60000),token) then return end
        for _,row in ipairs(rows) do
            if token~=generation then return end
            if not delayActive(row.delay,token) then return end
            local command=row.command:match('^%s*(.-)%s*$')
            local encoded=require('encoding').UTF8:decode(command)
            if command~='' and not command:find('[%z\1-\31]') and #encoded<=144 then
                status='Выполняется строка '..row.index
                if row.mode=='server' or (row.mode~='local' and command:sub(1,1)~='/') then sampSendChat(encoded)
                else sampProcessChatInput(encoded) end
                if cfg.main.debug then integration.message('AutoStart: выполнена строка '..row.index) end
            end
        end
        if token==generation then running=false;ranSession=true;status='Команды при старте выполнены.' end
    end)
end
integration.update=function()
    if not ranSession and (not ranEver or cfg.main.retry_on_reconnect~=false) and sampIsLocalPlayerSpawned() and active() then run() end
end
integration.onAccessChanged=function() if running then cancelRun();status='Запуск отменён: права изменились.' end end
integration.onDisconnect=function() generation=generation+1;running=false;ranSession=false;status='Ожидание нового входа.' end
local events=require('lib.samp.events')
events.onConnectionClosed=integration.onDisconnect
events.onConnectionLost=integration.onDisconnect
events.onConnectionRequestAccepted=integration.onDisconnect
integration.draw=function()
    local changed=settings.toggle(g,'Использовать команды при старте',cfg.main,'enabled')
    changed=settings.toggle(g,'Повторять после переподключения',cfg.main,'retry_on_reconnect') or changed
    changed=settings.toggle(g,'Режим отладки',cfg.main,'debug') or changed
    g.PushItemWidth(140)
    changed=settings.integer(g,'Стартовая задержка, мс',cfg.main,'initial_delay_ms',1000,0,60000) or changed
    g.PopItemWidth()
    if changed then cancelRun();save() end
    g.TextWrapped(status)
    if g.Button('Сохранить##autostart') then save() end
    g.SameLine();if g.Button('Перезагрузить##autostart') then cfg=integration.storage:loadIni(defaults,path);normalizeRows();buffers={};cancelRun() end
    g.SameLine();if g.Button('Запустить##autostart') then save();run() end
    g.SameLine();if g.Button('Остановить##autostart') then cancelRun();status='Остановлено.' end
    g.Separator()
    
    if g.Button('Добавить команду##autostart_add') and cfg.main.row_count<MAX_ROWS then
        cfg.main.row_count=cfg.main.row_count+1
        cfg['row'..cfg.main.row_count]={enabled=true,mode='auto',delay_ms=500,command=''}
        cancelRun();save()
    end
    if cfg.main.row_count==0 then g.TextDisabled('Команд пока нет. Добавьте первую строку.') end
    for i=1,cfg.main.row_count do
        local row=cfg['row'..i]
        buffers[i]=buffers[i] or g.ImBuffer(tostring(row.command or ''),512)
        local width=math.min(620,g.GetContentRegionAvail().x)
        g.Separator()
        local dirty=settings.toggle(g,string.format('%02d.##autostart_enabled_%d',i,i),row,'enabled')
        g.SameLine();g.PushItemWidth(118)
        local mode=g.ImInt(row.mode=='local' and 1 or row.mode=='server' and 2 or 0)
        if g.Combo('##autostart_mode_'..i,mode,'Авто\0Локальная\0Серверная\0\0') then row.mode=({'auto','local','server'})[mode.v+1];dirty=true end
        g.PopItemWidth()
        if width>=490 then g.SameLine() end
        g.Text('Задержка');g.SameLine();g.PushItemWidth(88)
        dirty=settings.integer(g,'##autostart_delay_'..i,row,'delay_ms',500,0,60000) or dirty
        g.PopItemWidth();g.SameLine();g.Text('мс')
        if width>=490 then g.SameLine() end
        if g.Button('Удалить##autostart_remove_'..i) then
            for j=i,cfg.main.row_count-1 do cfg['row'..j]=cfg['row'..(j+1)] end
            cfg['row'..cfg.main.row_count]=nil;cfg.main.row_count=cfg.main.row_count-1
            buffers={};cancelRun();save();break
        end
        g.PushItemWidth(math.max(80,width))
        if g.InputText('##autostart_command_'..i,buffers[i]) then row.command=buffers[i].v;dirty=true end
        g.PopItemWidth()
        if dirty then cancelRun();save() end
    end
end


    end
    sources["modules/beautifulsky.lua"] = function()
-- BeautifulSky 1.1, integrated into X-Tools by Casual_Alvarez.
-- Native rendering is retained; commands are replaced by embedded settings.
local g=require 'imgui'
local memory=require 'memory'
local model=integration.service('beautifulsky/model.lua')
local presets=integration.service('beautifulsky/presets.lua')
local storage=integration.storage
local path=storage:path('settings','beautifulsky.ini')
local defaults={preset='none',enabled=true,quality='medium',stars=true,moon=true,meteors=true,
    clouds=true,moonSize=1.25,meteorInterval=13,cloudSpeed=1}
local existed=storage:exists(path)
local cfg=storage:loadIni({main=defaults},path)
local config=cfg.main
if presets.index(config.preset)==0 then config.preset='none'end
if not existed then
    local raw=storage:read(getWorkingDirectory()..'/config/BeautifulSky.json')
    if raw then
        local ok,old=pcall(decodeJson,raw)
        if ok and type(old)=='table'then
            for key,value in pairs(defaults)do if type(old[key])==type(value)then config[key]=old[key]end end
        end
    end
end
for _,key in ipairs({'enabled','stars','moon','meteors','clouds'})do config[key]=config[key]==true end
if config.quality~='low'and config.quality~='medium'and config.quality~='high'then config.quality='medium'end
for key,limits in pairs({moonSize={.4,2.5},meteorInterval={5,120},cloudSpeed={.1,5}})do
    config[key]=model.clamp(model.finite(config[key])and config[key]or defaults[key],limits[1],limits[2])
end
local function save()storage:saveIni(cfg,path)end
if not existed then save()end
local renderer,snapshot

local ready,lost,attempted=false,false,false
local seconds,phase=0,0
local preview,demo,lastClock,errorMessage
local expanded=false
local previewHour,previewWeather=g.ImFloat(0),g.ImInt(0)
local status='Ожидание входа в игру.'
local function release()
    ready=false
    -- Native close restores the game call sites before releasing DirectX resources.

    if renderer then renderer:close();renderer=nil end
    snapshot=nil;lastClock=nil;attempted=false;lost=false
end
integration.stop=release
integration.onDisconnect=function()release();preview=nil;demo=nil end
local function initialize()
    attempted=true
    local ok,err=xpcall(function()
        local Native=integration.service('beautifulsky/native.lua')
        renderer=Native.new(getD3DDevicePtr(),integration.base..'/beautifulsky')
    end,debug.traceback)
    if not ok then
        release();attempted=true
        status='Небо не запущено: несовместимая версия игры, другой мод неба или ошибка DirectX. Подробности в moonloader.log.'
        print('[X-Tools / BeautifulSky] '..tostring(err))
        return false
    end
    status='Небо активно.'
    return true
end
integration.update=function()
    if not config.enabled then if renderer then release()end;return end
    if renderer and renderer:error()~=0 then errorMessage='Native error '..renderer:error()end
    if errorMessage then
        print('[X-Tools / BeautifulSky] '..errorMessage);errorMessage=nil
        release();attempted=true;status='Отрисовка остановлена после ошибки. Можно повторить запуск.'
    end
    if sampGetGamestate()~=3 or not isPlayerPlaying(PLAYER_HANDLE)then return end
    if not renderer then if attempted or lost or not initialize()then return end end
    local now=getGameTimer()/1000
    local dt=lastClock and model.clamp(now-lastClock,0,.1)or 0
    lastClock=now
    if not isPauseMenuActive()then seconds=seconds+dt end
    local hour,minute=getTimeOfDay()
    local old,new=memory.getint16(0xC81320),memory.getint16(0xC8131C)
    local blend=memory.getfloat(0xC8130C)
    hour=hour+minute/60
    if preview then hour=preview.hour;old=preview.weather;new=old;blend=0 end
    if demo then hour=((seconds-demo)/5)%24;old=0;new=0;blend=0 end
    snapshot=model.sample(hour,old,new,blend)
    if not preview and not demo then
        local rain=model.clamp(memory.getfloat(0xC81324))
        local fog=model.clamp(memory.getfloat(0xC81300))
        snapshot.stars=snapshot.stars*(1-rain)*(1-fog)
        snapshot.sun=snapshot.sun*(1-rain*.9)*(1-fog*.8)
    end
    snapshot=presets.apply(snapshot,config.preset)
    if not isPauseMenuActive()then phase=phase+dt*.007*snapshot.wind*config.cloudSpeed end
    ready=not lost and not isPauseMenuActive() and integration.featureAllowed()
    renderer:update(snapshot,config,seconds,phase,ready)
end
integration.onD3DDeviceLost=function()
    lost=true;ready=false
    if renderer then renderer:lost()end
end
integration.onD3DDeviceReset=function()
    if renderer then
        local ok,err=pcall(renderer.reset,renderer)
        if not ok then errorMessage=tostring(err);return end
    end
    lost=false;lastClock=nil
end
local function toggle(label,key)
    local ref=g.ImBool(config[key])
    if g.Checkbox(label,ref)then config[key]=ref.v;save();return true end
end
local function enable()
    config.enabled=true;attempted=false;save()
end
integration.drawPresets=function()
    g.Separator();g.Text('Авторская погода')
    g.TextWrapped('Локальные стили неба BeautifulSky. Не меняют погоду и время сервера. Выбор сохраняется.')
    for _,preset in ipairs(presets.items)do
        local active=config.preset==preset.id
        if g.Button((active and '• 'or '')..preset.name..'##sky_preset_'..preset.id,g.ImVec2(g.GetContentRegionAvailWidth(),0))then
            config.preset=preset.id;preview=nil;demo=nil;enable()
        end
        g.TextWrapped(preset.description)
    end
    if not config.enabled then g.TextWrapped('BeautifulSky выключен. Выберите пресет, чтобы включить.')end
    g.TextWrapped(status)
end
integration.drawSettings=function()
    if toggle('Красивое небо · BeautifulSky','enabled')then
        if not config.enabled then release();preview=nil;demo=nil else attempted=false end
    end
    g.SameLine()
    if g.Button('Настройки##beautifulsky')then expanded=not expanded end
    if not expanded then return end
    g.Separator()
    g.TextWrapped('Живое небо: облака, звёзды, луна и метеоры. По умолчанию следует игровому времени и погоде.')
    g.TextDisabled(config.enabled and status or 'Выключено · используется обычное небо игры.')
    g.Text('Качество')
    for _,item in ipairs({{'low','Низкое'},{'medium','Среднее'},{'high','Высокое'}})do
        g.SameLine()
        if g.Button((config.quality==item[1]and '• 'or '')..item[2]..'##sky_quality_'..item[1])then
            config.quality=item[1];save()
        end
    end
    toggle('Облака##sky_clouds','clouds');toggle('Звёзды##sky_stars','stars')
    toggle('Луна##sky_moon','moon');toggle('Метеоры##sky_meteors','meteors')
    g.PushItemWidth(140)
    for _,item in ipairs({{'Скорость облаков','cloudSpeed',.1,5},{'Размер луны','moonSize',.4,2.5},{'Интервал метеоров, сек.','meteorInterval',5,120}})do
        local ref=g.ImFloat(config[item[2]])
        if g.InputFloat(item[1]..'##sky_'..item[2],ref,0,0,2)then config[item[2]]=model.clamp(ref.v,item[3],item[4]);save()end
    end
    g.PopItemWidth()
    integration.drawPresets()
    g.PushItemWidth(140)
    g.Separator();g.Text('Предпросмотр неба')
    g.TextWrapped('Меняет только вид неба. Время и погода сервера остаются прежними. Режим сбрасывается при переподключении.')
    g.InputFloat('Час: 0–23,99##sky_hour',previewHour,0,0,2)
    g.InputInt('Погода: 0–45##sky_weather',previewWeather,0,0)
    g.PopItemWidth()
    if g.Button('Показать##sky_preview')then
        previewHour.v=model.clamp(previewHour.v,0,23.99);previewWeather.v=model.clamp(previewWeather.v,0,45)
        config.preset='none';preview={hour=previewHour.v,weather=previewWeather.v};demo=nil;enable()
    end
    g.SameLine();if g.Button('Обзор суток · 2 минуты##sky_demo')then config.preset='none';demo=seconds;preview=nil;enable()end
    if g.Button('Вернуть игровое небо##sky_auto')then config.preset='none';preview=nil;demo=nil;save()end
    g.SameLine();if g.Button('Повторить запуск##sky_retry')then release();enable()end
    g.TextDisabled(demo and 'Режим: обзор суток' or preview and 'Режим: предпросмотр' or 'Режим: игровое время и погода')
    g.Separator()
end

    end
    sources["modules/broom.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/broom.lua
-- Original third-party credits, where present, are retained below.
-- Flight and broom geometry reconstructed from Метла.cs; combat/effect branches omitted by request.
local g=require('imgui')
local path=integration.storage:path('settings','broom.ini')
local cfg=integration.storage:loadIni({main={scale=1.5,enabled=true}},path)
local active,loading,ped=false,false,nil
local geometry=integration.service('flight_geometry.lua')
local modelOwned=false
local objects={};local requested,last,heading,pitch,speed=0,0,0,-52.5,0
local function stop()
    local wasActive=active
    active=false;loading=false
    for _,object in ipairs(objects)do if doesObjectExist(object)then deleteObject(object)end end
    objects={}
    if wasActive and ped and doesCharExist(ped)then
        local x,y,z=getCharCoordinates(ped)
        clearCharTasks(ped);setCharVelocity(ped,0,0,0);setCharRotation(ped,0,0,getCharHeading(ped))
        if ped==PLAYER_PED and sampGetGamestate()==3 and not isCharDead(ped)and not isCharInAnyCar(ped)and not integration.observation()then
            local safeZ=geometry.standingZ(_G,x,y,z)
            -- Clearing the sitting task can lower the ped as well.
            local _,_,after=getCharCoordinates(ped)
            if safeZ>z+0.01 or after<z-0.01 then setCharCoordinates(ped,x,y,safeZ)end
        end
    end
    ped=nil
    if modelOwned then markModelAsNoLongerNeeded(2712);modelOwned=false end
end
integration.stop=stop;integration.onDisconnect=stop;integration.onAccessChanged=stop;integration.isActive=function()return active or loading end
integration.keys:register('broom','Метла: включить / выключить',{key=0})
local function valid()return sampGetGamestate()==3 and doesCharExist(PLAYER_PED) and not isCharDead(PLAYER_PED)and not isCharInAnyCar(PLAYER_PED)and not integration.observation()end
local function start()
    if active or loading then stop();return end
    if cfg.main.enabled~=true then return end
    if not integration.access:require(1,integration.message)then return end
    if not valid()then integration.message('Метла доступна пешком, вне слежки.');return end
    integration.claimFlight();ped=PLAYER_PED;heading=getCharHeading(ped);pitch=-52.5;speed=0
    requestModel(2712);modelOwned=true;loading=true;requested=getGameTimer()
end
integration.update=function()
    local toggle=integration.keys:pressed('broom')
    local input=not integration.windowOpen()and isGameWindowForeground()and not isPauseMenuActive()and not sampIsChatInputActive()and not sampIsDialogActive()and not sampIsCursorActive()
    if toggle and input then start()end
    if not active and not loading then return end
    if not valid()or ped~=PLAYER_PED then stop();return end
    if loading then
        if not hasModelLoaded(2712)then if getGameTimer()-requested>5000 then stop();integration.message('Не удалось загрузить модель метлы.')end;return end
        local x,y,z=getCharCoordinates(ped)
        local safeZ=geometry.standingZ(_G,x,y,z)
        if safeZ>z+0.01 then setCharCoordinates(ped,x,y,safeZ);z=safeZ end
        for index,pose in ipairs({{-0.1,0.5,0.15,5,-30,-90}})do
            local object=createObject(2712,x,y,z-25)
            if not object or object==0 or not doesObjectExist(object)then stop();integration.message('Не удалось создать метлу.');return end
            objects[#objects+1]=object
            setObjectCollision(object,false)
            setObjectScale(object,(tonumber(cfg.main.scale)or 1.5))
            attachObjectToChar(object,ped,unpack(pose))
        end
        taskPlayAnimNonInterruptable(ped,'CAR_SIT_PRO','PED',4,true,false,false,false,-1)
        setCharRotation(ped,pitch,0,heading)
        setCharVelocity(ped,0,0,0);loading=false;active=true;last=getGameTimer();return
    end
    local now=getGameTimer();local dt=math.min(0.05,math.max(0,(now-last)/1000));last=now
    if not isCharPlayingAnim(ped,'CAR_SIT_PRO')then
        taskPlayAnimNonInterruptable(ped,'CAR_SIT_PRO','PED',4,true,false,false,false,-1)
    end
    if not input then setCharVelocity(ped,0,0,0);return end
    heading=heading+((isKeyDown(65)and 1 or 0)-(isKeyDown(68)and 1 or 0))*90*dt
    pitch=math.max(-89,math.min(25,pitch+((isKeyDown(83)and 1 or 0)-(isKeyDown(87)and 1 or 0))*60*dt))
    speed=math.max(0,math.min(50,speed+((isKeyDown(32)and 1 or 0)-(isKeyDown(16)and 1 or 0))*20*dt))
    setCharHeading(ped,heading);setCharRotation(ped,pitch,0,heading)
    local x,y,z=getCharCoordinates(ped)
    -- Match the original character tilt and its local flight vector.
    local tilt,angle=math.rad(pitch),math.rad(heading)
    local forward=speed*(0.5*math.cos(tilt)-0.75*math.sin(tilt))
    local vx,vy=-math.sin(angle)*forward,math.cos(angle)*forward
    local vertical=speed*(0.5*math.sin(tilt)+0.75*math.cos(tilt))
    local aheadX,aheadY,aheadZ=x+vx*0.04,y+vy*0.04,z+vertical*0.04
    local ground=getGroundZFor3dCoord(aheadX,aheadY,aheadZ)
    -- Original terrain guard and gravity compensation, without combat branches.
    local vz=math.max(vertical,(ground-aheadZ+1.25)*8)+0.8
    setCharVelocity(ped,vx,vy,vz)
end
local settingsExpanded=false
integration.drawSettings=function()
    local value=g.ImBool(cfg.main.enabled==true)
    if g.Checkbox('Метла',value)then
        cfg.main.enabled=value.v
        integration.storage:saveIni(cfg,path)
        if not value.v then stop()end
    end
    g.SameLine()
    if g.Button('Настройки##broom_settings') then settingsExpanded=not settingsExpanded end
    if not settingsExpanded then return end
    g.TextDisabled('Метла '..((active or loading) and 'работает' or 'не запущен'))
    integration.keys:draw(g,'broom')
    local size=g.ImFloat(tonumber(cfg.main.scale)or 1.5)
    if g.SliderFloat('Размер метлы',size,1,2)then
        cfg.main.scale=size.v;integration.storage:saveIni(cfg,path)
        for index,object in ipairs(objects)do if doesObjectExist(object)then setObjectScale(object,size.v)end end
    end
    g.TextWrapped('W/S — наклон, A/D — поворот, Space — разгон, Shift — торможение. Камера свободная.')
end

    end
    sources["modules/bullet.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/bullet.lua
-- Original third-party credits, where present, are retained below.
-- CasualTool trajectory overlay, rebuilt from BulletTrack's recovered source.
-- Read-only sync observers; bounded storage and MoonLoader's projection API.
local imgui = require 'imgui'
local events = require 'lib.samp.events'
local storage = integration.storage
local bit = require 'bit'
local CONFIG = storage:path('settings', 'trajectories.ini', {getWorkingDirectory() .. '/config/BulletTrack/Settings.ini'})
local defaults = {
    Active=true, Time=5, MaxLines=50, Thickness=1, PolygonActive=true,
    PolygonSize=4, PolygonType=50, PolygonTurn=0, ColorClist=true,
    TransparencyClist=255, ColorPed=1828657947, ColorPedAFK=1828657947,
    ColorCar=-8466176, ColorObjectStatic=-1, ColorObjectDinamic=-1
}
local function clone(source)
    local target={}; for key,value in pairs(source) do target[key]=value end; return target
end
local settings = storage:loadIni({Main={enabled=true},Me=clone(defaults),Other=clone(defaults)},CONFIG) or {}
local function finite(value)
    return type(value)=='number' and value==value and math.abs(value)<math.huge
end
local function integer(value, fallback, minimum, maximum)
    value=tonumber(value)
    if not finite(value) then value=fallback end
    return math.max(minimum,math.min(maximum,math.floor(value)))
end
local limits = {Time={1,40},MaxLines={1,100},Thickness={1,10},PolygonSize={1,50},
    PolygonType={3,50},PolygonTurn={0,360},TransparencyClist={0,255}}
local function boolean(value,fallback)
    if value==nil then return fallback end
    return value==true or value==1 or value=='true' or value=='1'
end
settings.Main=type(settings.Main)=='table' and settings.Main or {enabled=true}
settings.Main.enabled=boolean(settings.Main.enabled,true)
for _,section in ipairs({'Me','Other'}) do
    local group=type(settings[section])=='table' and settings[section] or {}
    settings[section]=group
    for key,value in pairs(defaults) do
        if type(value)=='boolean' then
            group[key]=boolean(group[key],value)
        elseif limits[key] then
            group[key]=integer(group[key],value,limits[key][1],limits[key][2])
        else group[key]=integer(group[key],value,-2147483648,4294967295) end
    end
end
local rings={Me={next=0},Other={next=0}}
local selected='Other'
local last_time=0
local save_error=false
local function clear() rings={Me={next=0},Other={next=0}} end
local function save()
    save_error=not storage:saveIni(settings,CONFIG)
end
local function coordinates(point)
    if not point then return end
    local x,y,z=tonumber(point.x),tonumber(point.y),tonumber(point.z)
    if not (finite(x) and finite(y) and finite(z)) then return end
    if math.abs(x)>100000 or math.abs(y)>100000 or math.abs(z)>100000 then return end
    return {x=x,y=y,z=z}
end
local function shot_color(group,shooter,packet)
    if group.ColorClist and shooter and sampIsPlayerConnected(shooter) then
        return bit.bor(bit.band(sampGetPlayerColor(shooter),0xFFFFFF),bit.lshift(group.TransparencyClist,24))
    end
    local kind=packet.targetType
    if kind==1 then
        local id=tonumber(packet.targetId)
        return id and sampIsPlayerConnected(id) and sampIsPlayerPaused(id) and group.ColorPedAFK or group.ColorPed
    elseif kind==2 then return group.ColorCar
    elseif kind==3 or kind==4 then return group.ColorObjectDinamic end
    return group.ColorObjectStatic
end
local function capture(section,shooter,packet)
    local group=settings[section]
    if not settings.Main.enabled or not group.Active or not isSampAvailable() or sampGetGamestate()~=3 then return end
    if not packet or not finite(packet.targetType) or packet.targetType<0 or packet.targetType>4 then return end
    local origin,target=coordinates(packet.origin),coordinates(packet.target)
    if not origin or not target then return end
    if origin.x==target.x and origin.y==target.y and origin.z==target.z then return end
    local ring=rings[section]
    ring.next=ring.next%group.MaxLines+1
    ring[ring.next]={origin=origin,target=target,expires=getGameTimer()+group.Time*1000,
        color=shot_color(group,shooter,packet),shooter=shooter}
end
function events.onSendBulletSync(packet)
    local found,id=sampGetPlayerIdByCharHandle(PLAYER_PED)
    capture('Me',found and id or nil,packet)
end
function events.onBulletSync(id,packet)
    if not sampIsPlayerConnected(id) then return end
    capture('Other',id,packet)
end
function events.onPlayerQuit(id)
    for _,ring in pairs(rings) do
        for i=1,100 do if ring[i] and ring[i].shooter==id then ring[i]=nil end end
    end
end
local function project(point)
    local visible,x,y,depth=convert3DCoordsToScreenEx(point.x,point.y,point.z,true,false)
    if visible and finite(x) and finite(y) and finite(depth) and depth>1 then return x,y end
end
local function render()
    local now=getGameTimer()
    if now<last_time then clear() end
    last_time=now
    if not settings.Main.enabled or not isSampAvailable() or sampGetGamestate()~=3 then return end
    if isPauseMenuActive() or integration.windowOpen() then return end
    if type(convert3DCoordsToScreenEx)~='function' or type(renderDrawLine)~='function' then return end
    for _,section in ipairs({'Me','Other'}) do
        local group,ring=settings[section],rings[section]
        for i=1,group.MaxLines do
            local shot=ring[i]
            if shot and (shot.expires<=now or not group.Active) then ring[i]=nil; shot=nil end
            if shot then
                local ox,oy=project(shot.origin)
                local tx,ty=project(shot.target)
                if ox and tx then
                    renderDrawLine(ox,oy,tx,ty,group.Thickness,shot.color)
                    if group.PolygonActive then
                        renderDrawPolygon(tx,ty,group.PolygonSize,group.PolygonSize,group.PolygonType,group.PolygonTurn,shot.color)
                    end
                end
            end
        end
    end
end
local function checkbox(label,group,key)
    local ref=imgui.ImBool(group[key])
    if imgui.Checkbox(label,ref) then group[key]=ref.v; clear(); save() end
end
local function slider(label,group,key)
    local ref=imgui.ImInt(group[key])
    local title,id=label:match('^(.-)(##.*)$')
    imgui.TextWrapped(title or label)
    imgui.PushItemWidth(-1)
    local changed=imgui.SliderInt(id or ('##'..key),ref,limits[key][1],limits[key][2])
    imgui.PopItemWidth()
    if changed then
        group[key]=integer(ref.v,defaults[key],limits[key][1],limits[key][2])
        if key=='MaxLines' then clear() end
        save()
    end
end
local function color_editor(label,group,key)
    local color=group[key]
    local r,g,b,a=bit.band(bit.rshift(color,16),255),bit.band(bit.rshift(color,8),255),
        bit.band(color,255),bit.band(bit.rshift(color,24),255)
    local ref=imgui.ImFloat4(imgui.ImColor(r,g,b,a):GetFloat4())
    local title,id=label:match('^(.-)(##.*)$')
    imgui.TextWrapped(title or label)
    imgui.PushItemWidth(-1)
    local changed=imgui.ColorEdit4(id or ('##'..key),ref)
    imgui.PopItemWidth()
    if changed then
        local values={}
        for i=1,4 do values[i]=integer(ref.v[i]*255,255,0,255) end
        group[key]=bit.bor(bit.lshift(values[4],24),bit.lshift(values[1],16),bit.lshift(values[2],8),values[3])
        save()
    end
end
integration.drawSettings=function()
    checkbox('Показывать траектории пуль##bullet_enabled',settings.Main,'enabled')
    
    imgui.Separator()
    if imgui.Button('Другие игроки##bullet_other') then selected='Other' end
    imgui.SameLine()
    if imgui.Button('Мои выстрелы##bullet_me') then selected='Me' end
    local group=settings[selected]
    imgui.Separator()
    checkbox('Показывать выбранные выстрелы##bullet_group',group,'Active')
    local columns=integration.layout.begin('bullet_appearance',680)
    integration.layout.heading('Линии и маркеры')
    slider('Время отображения, сек.##bullet_time',group,'Time')
    slider('Максимум линий##bullet_count',group,'MaxLines')
    slider('Толщина линии##bullet_thickness',group,'Thickness')
    if imgui.CollapsingHeader('Маркеры траекторий##bullet_markers') then
        checkbox('Рисовать маркер на конце линии##bullet_marker',group,'PolygonActive')
        slider('Размер маркера##bullet_size',group,'PolygonSize')
        slider('Число сторон##bullet_sides',group,'PolygonType')
        slider('Поворот, градусы##bullet_rotation',group,'PolygonTurn')
    end
    integration.layout.next(columns)
    integration.layout.heading('Цвета')
    checkbox('Использовать цвет стрелявшего игрока##bullet_clist',group,'ColorClist')
    slider('Непрозрачность цвета игрока##bullet_alpha',group,'TransparencyClist')
    if not group.ColorClist then
        color_editor('Попадание в игрока##bullet_ped',group,'ColorPed')
        color_editor('Попадание в игрока AFK##bullet_afk',group,'ColorPedAFK')
        color_editor('Транспорт##bullet_car',group,'ColorCar')
        color_editor('Окружение или промах##bullet_static',group,'ColorObjectStatic')
        color_editor('Объект##bullet_dynamic',group,'ColorObjectDinamic')
    end
    integration.layout.finish(columns)
    if save_error then imgui.TextWrapped('Не удалось сохранить настройки траекторий. Проверьте доступ к папке настроек MoonLoader.') end
end
integration.draw=function()
    integration.drawSettings()
    integration.drawHitHistory()
    if type(convert3DCoordsToScreenEx)~='function' then imgui.TextWrapped('Эта версия MoonLoader не поддерживает отображение траекторий. Обновите MoonLoader.') end
    if imgui.Button('Очистить траектории##bullet_clear') then clear() end
    if imgui.GetContentRegionAvailWidth() >= 460 then imgui.SameLine() end
    if imgui.Button('Справка##bullet_help') then integration.openHelp('tools') end
end
integration.onDisconnect=clear
sampRegisterChatCommand('btrack',function() integration.openSettings('bullet') end)
function integration.onD3DPresent() render() end

    end
    sources["modules/capture.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/capture.lua
-- Original third-party credits, where present, are retained below.
-- Capture statistics, recovery and Discord tools integrated into CasualTool.
require "lib.moonloader"
require "lib.sampfuncs"

local sampev   = require("lib.samp.events")
