function APP.isCustomNametagsEnabled()
    if BOOLS.customNametagsBool ~= nil then
        return BOOLS.customNametagsBool.v == true
    end
    return CFG.main.custom_nametags_enabled == true
end

function APP.isSkeletalEnabled()
    if BOOLS.skeletalBool ~= nil then
        return BOOLS.skeletalBool.v == true
    end
    return CFG.main.skeletal_enabled == true
end

function APP.shouldModifyLongRangeLabel(text, attachedPlayerId, attachedVehicleId)
    if not APP.isLongRangeLabelsEnabled() then
        return false
    end
    if not text or text == "" then
        return false
    end
    if not CONST.LONG_RANGE_LABEL_ONLY_ATTACHED then
        return true
    end
    return tonumber(attachedPlayerId) ~= CONST.INVALID_PLAYER_ID or tonumber(attachedVehicleId) ~= CONST.INVALID_VEHICLE_ID
end

function APP.rebuildLongRangeLabel(id, color, position, distance, testLOS, attachedPlayerId, attachedVehicleId, text)
    if APP.shouldModifyLongRangeLabel(text, attachedPlayerId, attachedVehicleId) then
        return {
            id,
            color,
            position,
            CONST.LONG_RANGE_LABEL_DISTANCE,
            not CONST.LONG_RANGE_LABEL_FORCE_WALLHACK and testLOS,
            attachedPlayerId,
            attachedVehicleId,
            text
        }
    end
end

function APP.recreateCustomNametagFont()
    local state = DATA.customNametags
    if state.font ~= nil then
        renderReleaseFont(state.font)
        state.font = nil
    end

    state.font = renderCreateFont(
        CONST.CUSTOM_NAMETAGS_FONT_NAME,
        CONST.CUSTOM_NAMETAGS_FONT_SIZE,
        CONST.CUSTOM_NAMETAGS_FONT_FLAGS,
        CONST.CUSTOM_NAMETAGS_FONT_CHARSET
    )
end

function APP.getCustomNametagServerSettingsPtr()
    if not isSampAvailable() then
        return nil
    end

    local ptr = sampGetServerSettingsPtr()
    if ptr == nil or ptr == 0 then
        return nil
    end

    return ptr
end

function APP.cacheOriginalCustomNametagSettings()
    local state = DATA.customNametags
    if state.originalSettings ~= nil then
        return
    end

    local ptr = APP.getCustomNametagServerSettingsPtr()
    if ptr == nil then
        return
    end

    state.originalSettings = {
        draw_distance = APP.memory.getfloat(ptr + CONST.CUSTOM_NAMETAGS_SERVER_OFFSETS.draw_distance, true),
        wallhack = APP.memory.getint8(ptr + CONST.CUSTOM_NAMETAGS_SERVER_OFFSETS.wallhack, true),
        show_nametags = APP.memory.getint8(ptr + CONST.CUSTOM_NAMETAGS_SERVER_OFFSETS.show_nametags, true)
    }
end

function APP.applyCustomNametagSettings()
    local ptr = APP.getCustomNametagServerSettingsPtr()
    if ptr == nil then
        return
    end

    APP.cacheOriginalCustomNametagSettings()
    APP.memory.setint8(ptr + CONST.CUSTOM_NAMETAGS_SERVER_OFFSETS.show_nametags, 1, true)
end

function APP.restoreCustomNametagSettings()
    local ptr = APP.getCustomNametagServerSettingsPtr()
    local original = DATA.customNametags.originalSettings
    if ptr == nil or original == nil then
        return
    end

    APP.memory.setint8(ptr + CONST.CUSTOM_NAMETAGS_SERVER_OFFSETS.show_nametags, original.show_nametags, true)
end

function APP.patchCustomNametagRel32Call(callAddr, newTargetAddr)
    local oldProtect = APP.ffi.new("unsigned long[1]")
    if APP.ffi.C.VirtualProtect(APP.ffi.cast("void*", callAddr), 5, CONST.CUSTOM_NAMETAGS_PAGE_EXECUTE_READWRITE, oldProtect) == 0 then return false end
    APP.ffi.cast("int32_t*", callAddr + 1)[0] = newTargetAddr - (callAddr + 5)
    if APP.ffi.C.VirtualProtect(APP.ffi.cast("void*", callAddr), 5, oldProtect[0], oldProtect) == 0 then
        print("[X-Tools] Cannot restore native page protection")
    end
    return true
end

function APP.installCustomNametagRenderHook()
    local state = DATA.customNametags
    if state.renderNickHookInstalled then
        return true
    end

    local samp = getModuleHandle("samp.dll")
    if samp == 0 then
        return false
    end

    state.renderNickCallAddr = samp + CONST.CUSTOM_NAMETAGS_RENDER_NICK_HOOK_OFFSET
    if APP.ffi.cast("uint8_t*", state.renderNickCallAddr)[0] ~= 0xE8 then
        return false
    end

    state.renderNickOriginalRel = APP.ffi.cast("int32_t*", state.renderNickCallAddr + 1)[0]
    -- Native cdecl stub: if (buf) *buf=0; return 0. No Lua callback can
    -- remain reachable after the VM unloads, even if unpatching is denied.
    local code = "\x8B\x44\x24\x04\x85\xC0\x74\x03\xC6\x00\x00\x31\xC0\xC3"
    local stub = APP.ffi.C.VirtualAlloc(nil, #code, 0x3000, 0x04)
    if stub == nil then return false end
    APP.ffi.copy(stub, code, #code)
    local protection = APP.ffi.new("unsigned long[1]")
    if APP.ffi.C.VirtualProtect(stub, #code, 0x20, protection) == 0
        or APP.ffi.C.FlushInstructionCache(APP.ffi.C.GetCurrentProcess(), stub, #code) == 0 then
        APP.ffi.C.VirtualFree(stub, 0, 0x8000);return false
    end
    state.renderNickStub = stub
    local patched = APP.patchCustomNametagRel32Call(
        state.renderNickCallAddr,
        tonumber(APP.ffi.cast("intptr_t", state.renderNickStub))
    )

    if not patched then
        APP.ffi.C.VirtualFree(state.renderNickStub, 0, 0x8000)
        state.renderNickStub=nil;return false
    end
    state.renderNickPatchedRel=APP.ffi.cast("int32_t*",state.renderNickCallAddr+1)[0]
    state.renderNickHookInstalled = true
    return true
end

function APP.removeCustomNametagRenderHook()
    local state = DATA.customNametags
    if not state.renderNickHookInstalled or state.renderNickCallAddr == nil or state.renderNickOriginalRel == nil then
        return
    end

    -- Do not overwrite another module's hook, nor free a possibly chained stub.
    local currentRel=APP.ffi.cast("int32_t*",state.renderNickCallAddr+1)[0]
    if APP.ffi.cast("uint8_t*",state.renderNickCallAddr)[0]~=0xE8
        or (currentRel~=state.renderNickPatchedRel and currentRel~=state.renderNickOriginalRel) then
        return false
    end
    -- The bytes may already be restored after a failed instruction-cache flush.
    if currentRel==state.renderNickPatchedRel then
    local oldProtect = APP.ffi.new("unsigned long[1]")
    if APP.ffi.C.VirtualProtect(APP.ffi.cast("void*", state.renderNickCallAddr), 5, CONST.CUSTOM_NAMETAGS_PAGE_EXECUTE_READWRITE, oldProtect) == 0 then return false end
    APP.ffi.cast("int32_t*", state.renderNickCallAddr + 1)[0] = state.renderNickOriginalRel
    if APP.ffi.C.VirtualProtect(APP.ffi.cast("void*", state.renderNickCallAddr), 5, oldProtect[0], oldProtect) == 0 then
        print("[X-Tools] Cannot restore native page protection")
    end
    end
    if APP.ffi.C.FlushInstructionCache(APP.ffi.C.GetCurrentProcess(), APP.ffi.cast("void*",state.renderNickCallAddr),5)==0 then
        -- Retain the native stub if stale instructions may still reference it.
        return false
    end
    state.renderNickHookInstalled = false
    if state.renderNickStub~=nil then APP.ffi.C.VirtualFree(state.renderNickStub,0,0x8000);state.renderNickStub=nil end
    return true
end

function APP.installCustomNametagHealthBarPatch()
    local state = DATA.customNametags
    if state.drawHealthBarPatchInstalled then
        return true
    end

    local samp = getModuleHandle("samp.dll")
    if samp == 0 then
        return false
    end

    state.drawHealthBarAddr = samp + CONST.CUSTOM_NAMETAGS_DRAW_HEALTH_BAR_OFFSET
    state.drawHealthBarOriginalByte = APP.ffi.cast("uint8_t*", state.drawHealthBarAddr)[0]

    local oldProtect = APP.ffi.new("unsigned long[1]")
    if APP.ffi.C.VirtualProtect(APP.ffi.cast("void*", state.drawHealthBarAddr), 1, CONST.CUSTOM_NAMETAGS_PAGE_EXECUTE_READWRITE, oldProtect) == 0 then return false end
    APP.ffi.cast("uint8_t*", state.drawHealthBarAddr)[0] = 0xC3
    if APP.ffi.C.VirtualProtect(APP.ffi.cast("void*", state.drawHealthBarAddr), 1, oldProtect[0], oldProtect) == 0 then
        print("[X-Tools] Cannot restore native page protection")
    end

    state.drawHealthBarPatchInstalled = true
    return true
end

function APP.removeCustomNametagHealthBarPatch()
    local state = DATA.customNametags
    if not state.drawHealthBarPatchInstalled or state.drawHealthBarAddr == nil or state.drawHealthBarOriginalByte == nil then
        return
    end
    local current=APP.ffi.cast("uint8_t*",state.drawHealthBarAddr)[0]
    if current~=0xC3 and current~=state.drawHealthBarOriginalByte then return false end
    if current==0xC3 then
    local oldProtect = APP.ffi.new("unsigned long[1]")
    if APP.ffi.C.VirtualProtect(APP.ffi.cast("void*", state.drawHealthBarAddr), 1, CONST.CUSTOM_NAMETAGS_PAGE_EXECUTE_READWRITE, oldProtect) == 0 then return false end
    APP.ffi.cast("uint8_t*", state.drawHealthBarAddr)[0] = state.drawHealthBarOriginalByte
    if APP.ffi.C.VirtualProtect(APP.ffi.cast("void*", state.drawHealthBarAddr), 1, oldProtect[0], oldProtect) == 0 then
        print("[X-Tools] Cannot restore native page protection")
    end
    end
    if APP.ffi.C.FlushInstructionCache(APP.ffi.C.GetCurrentProcess(),APP.ffi.cast("void*",state.drawHealthBarAddr),1)==0 then return false end
    state.drawHealthBarPatchInstalled = false
    return true
end

function APP.ensureCustomNametagRuntimePatches()
    local state = DATA.customNametags
    local now = os.clock() * 1000
    if now - (tonumber(state.lastPatchTime) or 0) < CONST.CUSTOM_NAMETAGS_UPDATE_PATCH_DELAY then
        return
    end

    APP.applyCustomNametagSettings()
    APP.installCustomNametagRenderHook()
    APP.installCustomNametagHealthBarPatch()
    state.lastPatchTime = now
end

function APP.getCustomNametagPlayerWorldPosition(playerId)
    local result, ped = sampGetCharHandleBySampPlayerId(playerId)
    if result and doesCharExist(ped) then
        local zOffset = isCharInAnyCar(ped) and 1.02 or 0.82
        local x, y, z = getOffsetFromCharInWorldCoords(ped, 0.0, 0.0, zOffset)
        return true, x, y, z, ped
    end

    local streamed, x, y, z = sampGetStreamedOutPlayerPos(playerId)
    if streamed then
        return true, x, y, z + 0.82, nil
    end

    return false, nil, nil, nil, nil
end

function APP.getCustomNametagColor(playerId)
    local originalColor = integration.nametagColor(sampGetPlayerColor(playerId))
    originalColor = bit.bor(bit.band(originalColor, 0x00FFFFFF), 0xFF000000)
    if originalColor == 0xFFFFFFFF or originalColor == 0xFF000000 then
        return CONST.CUSTOM_NAMETAGS_TEXT_DEFAULT_COLOR
    end
    return originalColor
end

function APP.drawCustomNametagShadowedText(text, posX, posY, color)
    local font = DATA.customNametags.font
    if font == nil then
        return
    end

    local textCp1251 = utf8_to_cp1251(text)
    renderFontDrawText(font, textCp1251, posX + 1, posY + 1, 0xD0000000)
    renderFontDrawText(font, textCp1251, posX, posY, color)
end

-- Minimal floating bars: rounded ends, subtle track, no enclosing panel.
APP.nametagStylePath=integration.storage:path('settings','nametag-style.ini')
APP.nametagStyle=integration.storage:loadIni({main={style=3}},APP.nametagStylePath)
APP.vitalBars=integration.service('vital_bars.lua')
function APP.getNametagStyle()
    local value=tonumber(APP.nametagStyle.main.style)
    return (value==1 or value==2 or value==3) and value or 0
end
function APP.drawNametagPill(x,y,width,height,color)
    local radius=height/2
    for row=0,height-1 do
        local dy=math.abs(row+0.5-radius)
        local inset=math.floor(radius-math.sqrt(math.max(0,radius*radius-dy*dy)))
        renderDrawBox(x+inset,y+row,math.max(0,width-inset*2),1,color)
    end
end
function APP.drawMinimalNametagBar(x,y,width,height,value,color)
    local ratio=APP.clampNumber(tonumber(value) or 0,0,100)/100
    local fill=math.floor(width*ratio)
    local style=APP.getNametagStyle()
    if style==1 then
        renderDrawBox(x,y,width,height,0xDA292B30)
        if fill>0 then renderDrawBox(x,y,fill,height,color)end
        return
    elseif style==2 then
        APP.drawNametagPill(x+1,y+2,width,height,0x70000000)
        APP.drawNametagPill(x,y,width,height,0xD033343D)
        if fill>0 then APP.drawNametagPill(x,y,fill,height,color)end
        return
    end
    for row=0,height-1 do
        local inset=(row==0 or row==height-1) and 2 or 0
        renderDrawBox(x+inset,y+row,width-inset*2,1,0xD02C2D34)
        local length=math.max(0,fill-inset*2)
        if length>0 then renderDrawBox(x+inset,y+row,length,1,color)end
    end
end
function APP.drawCustomHpBar(x,y,width,health)
    if APP.getNametagStyle()==3 then APP.vitalBars.draw(renderDrawBox,x,y,width,6,health,false);return end
    APP.drawMinimalNametagBar(x,y,width,6,health,0xFFF36868)
end
function APP.drawCustomArmorBar(x,y,width,armor)
    if APP.getNametagStyle()==3 then APP.vitalBars.draw(renderDrawBox,x,y,width,5,armor,true);return end
    APP.drawMinimalNametagBar(x,y,width,5,armor,0xFF7DBDF6)
end

APP.nametagLayout=integration.service('nametag_layout.lua')
function APP.renderSingleCustomNametag(playerId, myX, myY, myZ)
    local ok, x, y, z, ped = APP.getCustomNametagPlayerWorldPosition(playerId)
    if not ok then
        return
    end
    if ped ~= nil and not isCharOnScreen(ped) then
        return
    end

    local distance = getDistanceBetweenCoords3d(myX, myY, myZ, x, y, z)
    if distance > CONST.CUSTOM_NAMETAGS_MAX_DISTANCE then
        return
    end

    if not integration.wallhackActive() then
        if distance > 35 then return end
        local cx,cy,cz=getActiveCameraCoordinates()
        if not isLineOfSightClear(cx,cy,cz,x,y,z,true,false,false,false,true)then return end
    end

    local screenX, screenY = convert3DCoordsToScreen(x, y, z)
    if screenX == nil or screenY == nil then
        return
    end

    local nick = sampGetPlayerNickname(playerId)
    if not nick or nick == "" then
        return
    end

    local font = DATA.customNametags.font
    if font == nil then return end
    local name=cp1251_to_utf8(nick)
    local style=APP.getNametagStyle()
    local idText=string.format(style==2 and '  %d  ' or '  |  %d',tonumber(playerId) or 0)
    local nameWidth=renderGetFontDrawTextLength(font,nick)
    local textWidth=nameWidth+renderGetFontDrawTextLength(font,idText)
    local textHeight=renderGetFontDrawHeight(font)
    local health=tonumber(sampGetPlayerHealth(playerId)) or 0
    local armor=tonumber(sampGetPlayerArmor(playerId)) or 0
    local showArmor=CONST.CUSTOM_NAMETAGS_ARMOR_BAR_ENABLED and armor>0
    local healthText=tostring(math.floor(math.max(0,health)))
    local armorText=tostring(math.floor(math.max(0,armor)))
    local numberWidth=math.max(renderGetFontDrawTextLength(font,healthText),renderGetFontDrawTextLength(font,armorText))
    local barWidth=math.max(90,math.min(150,textWidth-numberWidth-8))
    local totalWidth=barWidth+8+numberWidth
    local rowHeight=math.max(style==3 and 19 or 12,textHeight+2)
    local textY=screenY-textHeight-5-rowHeight*(showArmor and 2 or 1)
    local drawX=screenX-textWidth/2
    local barX=screenX-totalWidth/2
    local _,screenHeight=getScreenResolution()
    local left=math.min(drawX,barX)-8
    local blockHeight=textHeight+11+rowHeight*(showArmor and 2 or 1)
    -- Only separate occupants of the same car. Nearby pedestrians must keep
    -- their labels anchored to their actual screen positions.
    if ped and isCharInAnyCar(ped) then
        local vehicle=storeCarCharIsInNoSave(ped)
        local groups=DATA.customNametags.occupied
        if groups and vehicle then
            groups[vehicle]=groups[vehicle] or {}
            local placed=APP.nametagLayout.place(groups[vehicle],left,textY-6,math.max(textWidth,totalWidth)+16,blockHeight,screenHeight)
            if not placed then return end
            textY=placed+6
        end
    end
    local hpY=textY+textHeight+5
    if style==1 then
        local left=math.min(drawX,barX)-8
        local width=math.max(textWidth,totalWidth)+16
        renderDrawBox(left,textY-6,width,textHeight+11+rowHeight*(showArmor and 2 or 1),0xB0181920)
    elseif style==2 then
        APP.drawNametagPill(drawX+nameWidth+2,textY-1,math.max(16,textWidth-nameWidth-2),math.ceil(textHeight+2),0xD96C5298)
    end
    APP.drawCustomNametagShadowedText(name,drawX,textY,APP.getCustomNametagColor(playerId))
    APP.drawCustomNametagShadowedText(idText,drawX+nameWidth,textY,0xFFADB0BC)
    if CONST.CUSTOM_NAMETAGS_HP_BAR_ENABLED then
        APP.drawCustomHpBar(barX,hpY+(rowHeight-6)/2,barWidth,health)
        APP.drawCustomNametagShadowedText(healthText,barX+barWidth+8,hpY,0xFFF3F1F6)
    end
    if showArmor then
        local armorY=hpY+rowHeight
        APP.drawCustomArmorBar(barX,armorY+(rowHeight-5)/2,barWidth,armor)
        APP.drawCustomNametagShadowedText(armorText,barX+barWidth+8,armorY,0xFFF3F1F6)
    end
end

function APP.renderCustomNametagsFrame()
    -- The update coroutine keeps running while GTA is minimized. Do not enqueue
    -- MoonLoader draw primitives when the game is not rendering visible frames.
    if not isSafeGameRenderState() then return end
    if not APP.isCustomNametagsEnabled() then
        return
    end
    if sampGetGamestate() ~= 3 or not sampIsLocalPlayerSpawned() then
        return
    end

    APP.ensureCustomNametagRuntimePatches()

    if DATA.customNametags.font == nil then
        APP.recreateCustomNametagFont()
    end
    if DATA.customNametags.font == nil then
        return
    end

    local _, myId = sampGetPlayerIdByCharHandle(PLAYER_PED)
    local myX, myY, myZ = getCharCoordinates(PLAYER_PED)
    local maxPlayerId = sampGetMaxPlayerId(false)
    DATA.customNametags.occupied={}

    for playerId = 0, maxPlayerId do
        if playerId ~= myId and sampIsPlayerConnected(playerId) then
            APP.renderSingleCustomNametag(playerId, myX, myY, myZ)
        end
    end
end

function APP.setCustomNametagsState(enabled, silent)
    local state = DATA.customNametags
    enabled = enabled == true
    if enabled then
        local supported, reason = APP.checkNativeSupport('nametags')
        if not supported then APP.rejectNativeFeature('nametags', reason); enabled = false end
    end
    if state.active == enabled and (enabled or not state.renderNickHookInstalled and not state.drawHealthBarPatchInstalled) then
        return
    end

    state.active = enabled
    state.lastPatchTime = 0

    if enabled then
        if state.font == nil then
            APP.recreateCustomNametagFont()
        end
        APP.cacheOriginalCustomNametagSettings()
        APP.applyCustomNametagSettings()
        APP.installCustomNametagRenderHook()
        APP.installCustomNametagHealthBarPatch()
        if not silent then
            chatSuccess("Собственные подписи игроков включены.")
        end
    else
        APP.removeCustomNametagHealthBarPatch()
        if APP.removeCustomNametagRenderHook()==false then
            -- VirtualAlloc memory survives Lua unload; Windows reclaims it at process exit.
            print("[X-Tools] Nametag hook could not be restored; native stub retained until game exit")
        end
        APP.restoreCustomNametagSettings()
        if state.font ~= nil then
            renderReleaseFont(state.font)
            state.font = nil
        end
        if not silent then
            chatInfo("Собственные подписи игроков выключены.")
        end
    end
end

function APP.syncCustomNametagsState(silent)
    APP.setCustomNametagsState(APP.isCustomNametagsEnabled() and sampGetGamestate() == 3, silent)
end

function APP.shutdownCustomNametags()
    APP.setCustomNametagsState(false, true)
end

function APP.getSkeletalBoneCoordinates(boneId, charHandle)
    local pedPtr = getCharPointer(charHandle)
    local vec = APP.ffi.new("float[3]")
    APP.getBonePositionFn(APP.ffi.cast("void*", pedPtr), vec, boneId, true)
    return vec[0], vec[1], vec[2]
end

