integration.onDisconnect = function()
    persistActiveCaptureState()
    saveLastCaptureSnapshot()
    APP.session = APP.session + 1
    for id, worker in pairs(THREADS.active) do pcall(function() worker:cancel() end); THREADS.active[id] = nil end
    APP.shutdownSkeletal()
    APP.shutdownCustomNametags()
    DATA.customNametags.originalSettings = nil
    DATA.pendingDeathEvents = {}
    DATA.streaks = {}
    DATA.playerNamesById = {}
    DATA.onlinePlayersById = {}
    DATA.playerColorsById = {}
    DATA.playerColorSourceById = {}
    DATA.onlineStatsCollectActive = false
    DATA.onlineStatsCollectCallbacks = {}
    DATA.onlineStatsStabilized = false
    DATA.onlineWarmupUntil = os.clock() + CONST.ONLINE_INITIAL_WARMUP_SECONDS
    DATA.onlineSnapshotRefreshAt = 0
    DATA.deferredCaptureAutoSend = nil
    DATA.discordPendingRequests = 0
    DATA.discordSequenceWorkers = 0
    DATA.captureDiscordClosed = false
    DATA.overlayTestActive = false
    DATA.overlayTestEntries = {}
    resetDialog66WhiteScan()
    resetFollowPrompt()
    resetCapture()
    restoreRecoveryInfo()
end

integration.suspend = integration.onDisconnect

-- Compact read-only state for dashboard/diagnostics and offline regression tests.
integration.status = function()
    return {active = STATE.capture.active, frags = STATE.capture.total, punishments = #STATE.capture.punishes,
        discordEnabled = CFG.main.discord_enabled,
        recovery = DATA.recoveryFileInfo ~= nil, generation = APP.session}
end

function APP.checkNativeSupport(feature)
    APP.nativeGuard = APP.nativeGuard or integration.service('capture_native.lua')
    local read = function(address, length) return APP.ffi.string(APP.ffi.cast('const char*', address), length) end
    local supported,reason,profile=APP.nativeGuard.check(read, getModuleHandle('samp.dll'), getModuleHandle('gta_sa.exe'), feature, DATA.customNametags)
    if supported and profile then
        CONST.CUSTOM_NAMETAGS_RENDER_NICK_HOOK_OFFSET=profile.nick
        CONST.CUSTOM_NAMETAGS_DRAW_HEALTH_BAR_OFFSET=profile.health
    end
    return supported,reason
end

function APP.rejectNativeFeature(feature, reason)
    if feature == 'nametags' then
        CFG.main.custom_nametags_enabled = false
        if BOOLS.customNametagsBool then BOOLS.customNametagsBool.v = false end
    else
        CFG.main.skeletal_enabled = false
        if BOOLS.skeletalBool then BOOLS.skeletalBool.v = false end
    end
    saveConfig()
    chatError(tostring(reason) .. '. Функция выключена.')
end

