integration.layoutItems=function()
 local out={}
 for _,entry in ipairs({{'captureOverlay','Участники капта'},{'captureTopOverlay','Мини-топ капта'}})do
  local prefix=entry[1]
  if INTS[prefix..'XBuffer']then
   out[#out+1]={name=entry[2],x=INTS[prefix..'XBuffer'].v,y=INTS[prefix..'YBuffer'].v,w=prefix=='captureOverlay' and (tonumber(INTS.captureOverlayWidthBuffer.v)or 420)+100 or 300,h=150,preview=function(x,y)
    if not ensureOverlayFonts()then return end
    drawOverlayText(DATA.overlayTitleFont,prefix=='captureOverlay'and 'Участники капта в онлайне:'or 'Топ фрагов капта:',x,y,0xFFF7F7F7)
    for i=1,3 do drawOverlayRenderLine(DATA.overlayLineFont,i,{nick='Player_Name',id=120+i,kills=4-i},x,y+18+(i-1)*16)end
   end,set=function(x,y)
    INTS[prefix..'XBuffer'].v=x;INTS[prefix..'YBuffer'].v=y;saveConfig()
   end}
  end
 end
 return out
end

-- Reuse the verified native bone API without enabling the skeletal overlay.
integration.familyBones=function(ped)
 if not doesCharExist(ped)or not isCharOnScreen(ped)then return end
 local supported=APP.checkNativeSupport('skeletal');if not supported then return end
 local points={}
 for _,id in ipairs({1,2,3,4,5,22,23,24,32,33,34,41,42,43,51,52,53})do
  local x,y,z=APP.getSkeletalBoneCoordinates(id,ped)
  if not isPointOnScreen(x,y,z,0.1)then return end
  local sx,sy=convert3DCoordsToScreen(x,y,z)
  if not sx or not sy or sx~=sx or sy~=sy then return end
  points[id]={x=sx,y=sy}
 end
 return points
end

function APP.skeletonVisual()
 if not APP.boneVisual then
  APP.boneVisual=integration.storage:loadIni({main={style=2,priority=0}},integration.storage:path('settings','skeleton-visual.ini'))
 end
 return APP.boneVisual.main
end
function APP.saveSkeletonVisual()
 integration.storage:saveIni(APP.boneVisual,integration.storage:path('settings','skeleton-visual.ini'))
end
integration.hudActive=function()
 return integration.featureAllowed('core')and APP.isSkeletalEnabled()and not integration.layoutEditing()and sampGetGamestate()==3 and not isPauseMenuActive()and not isKeyDown(VK_F8)and isGameWindowForeground(),false,false
end
integration.generalHighlight=function()return integration.hudActive(),APP.skeletonVisual().priority end
integration.drawHud=function()
 if not integration.hudActive()then return end
 local visual=APP.skeletonVisual();local renderer=integration.service('family_highlight.lua')
 local sw,sh=getScreenResolution()
 renderer.frame(imgui,sw,sh,function(draw)
  for id=0,sampGetMaxPlayerId(false)do
   if sampIsPlayerConnected(id)then
    local family=integration.familyHighlight(sampGetPlayerNickname(id))
    if not family or visual.priority==1 then
     local ok,ped=sampGetCharHandleBySampPlayerId(id)
     local points=ok and integration.familyBones(ped)
     if points then
      local color=sampGetPlayerColor(id)
      local abgr=bit.bor(bit.lshift(visual.style==0 and 85 or 220,24),bit.lshift(bit.band(color,255),16),bit.band(color,0xFF00),bit.band(bit.rshift(color,16),255))
      renderer.draw(imgui,points,abgr,visual.style,draw)
     end
    end
   end
  end
 end,'##xt_skeleton_highlight')
end

    end
    sources["modules/casual.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/casual.lua
-- Original third-party credits, where present, are retained below.
-- Private, local quit-on-connect preference. Never sends commands to other clients.
local events=require('lib.samp.events');local u8=require('encoding').UTF8
local allowed={casual_alvarez=true,ombre_leather=true}
local dialogId=28641
local path=integration.storage:path('settings','casual.ini')
local cfg=integration.storage:loadIni({casual_alvarez={target='',enabled=false},ombre_leather={target='',enabled=false}},path)
local owner,previous,pending,rows=nil,{},nil,nil
local nextPoll=0
local function account()
    if sampGetGamestate()~=3 then return end
    local found,id=sampGetPlayerIdByCharHandle(PLAYER_PED)
    if not found then return end
    local nick=tostring(sampGetPlayerNickname(id)):lower()
    if allowed[nick]then return nick end
end
local function snapshot()
    local result={}
    for id=0,math.min(1004,sampGetMaxPlayerId(false))do
        if sampIsPlayerConnected(id)then result[id]=tostring(sampGetPlayerNickname(id)):lower()end
    end
    return result
end
local function baseline(who)owner=who;previous=snapshot();pending=nil;nextPoll=0 end
local function reset()owner=nil;previous={};pending=nil;rows=nil;nextPoll=0 end
local function open()
    local who=account();if not who then return end
    local names=(integration.protectedLists(true)or {}).admins or {}
    local unique={};rows={}
    for _,name in ipairs(names)do
        local key=tostring(name):lower()
        if key~=who and not unique[key]then unique[key]=true;rows[#rows+1]=name end
    end
    table.sort(rows)
    local setting=cfg[who]
    local title='Casual — '..(setting.enabled and ('ожидание '..setting.target)or 'выключено')
    local body='Выключить автоматический выход'
    for _,name in ipairs(rows)do body=body..'\n'..name end
    sampShowDialog(dialogId,u8:decode(title),u8:decode(body),u8:decode('Выбрать'),u8:decode('Закрыть'),2)
end
sampRegisterChatCommand('casual',open)
function events.onSendDialogResponse(id,button,index)
    if id~=dialogId or not rows then return end
    local list=rows;rows=nil;local who=account()
    if who and button==1 then
        if index==0 then cfg[who].enabled=false
        elseif list[index]then cfg[who].target=list[index];cfg[who].enabled=true
        else return false end
        integration.storage:saveIni(cfg,path);baseline(who)
        integration.message(cfg[who].enabled and ('Автовыход включён: '..cfg[who].target..'. Ожидается новое подключение и игровой уровень выше 1. Выключить: /casual.')or 'Автовыход выключен.')
    end
    return false
end
function events.onPlayerJoin(id,color,npc,nick)
    local who=account();if not who or not cfg[who].enabled then return end
    if who~=owner then baseline(who)end
    if not npc and tostring(nick):lower()==cfg[who].target:lower()then pending={id=id,nick=tostring(nick):lower()}end
end
function events.onPlayerQuit(id)
    previous[id]=nil
    if pending and pending.id==id then pending=nil end
end
integration.update=function()
    local who=account();if not who then reset();return end
    if owner~=who then baseline(who)end
    local setting=cfg[who]
    if not setting.enabled then pending=nil;return end
    local now=getGameTimer();if now<nextPoll then return end;nextPoll=now+250
    local current=snapshot();local target=setting.target:lower()
    for id,nick in pairs(current)do
        if nick==target and previous[id]~=nick then pending={id=id,nick=nick}end
    end
    previous=current
    if not pending then return end
    local id=pending.id
    if current[id]~=pending.nick then pending=nil;return end
    local score=tonumber(sampGetPlayerScore(id))
    if score and score==score and score<math.huge and score>1
        and account()==who and sampIsPlayerConnected(id)
        and tostring(sampGetPlayerNickname(id)):lower()==target then
        pending=nil
        -- One-shot disarm before /q, including when another script intercepts it.
        setting.enabled=false;integration.storage:saveIni(cfg,path)
        sampProcessChatInput('/q')
    end
end
integration.stop=reset;integration.onDisconnect=reset;integration.onAccessChanged=reset

    end
    sources["modules/chat_appearance.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/chat_appearance.lua
-- Original third-party credits, where present, are retained below.
-- CChat layout: BlastHackNet/SAMP-API master, src/0.3.7-R1/CChat.h (also R3-1).
-- Only the display mode is borrowed; native history and input are never replaced.
local g=require('imgui');local bit=require('bit')
local path=integration.storage:path('settings','chat-appearance.ini')
local cfg=integration.storage:loadIni({main={enabled=false,appear=true,slide=false,fade=false,background=false}},path)
local c=cfg.main
for _,key in ipairs({'enabled','appear','slide','fade','background'})do c[key]=c[key]==true end
local animation=integration.service('chat_animation.lua').new()
local owned,original,font,fontHeight,layout,failed,skipUntil,cachedLines,cacheKey
local renderedRows={}
local function restore()
    if owned then
        local ptr=sampGetChatInfoPtr()
        if ptr==owned and readMemory(ptr+8,4,true)==0 then writeMemory(ptr+8,4,original,true)end
        owned,original=nil,nil
    end
    layout=nil;renderedRows={}
end
local function stop()
    restore()
    if font then renderReleaseFont(font);font=nil end
    animation=integration.service('chat_animation.lua').new()
    cachedLines,cacheKey=nil,nil
end
local function compatible()
    if type(sampGetChatInfoPtr)~='function' or type(writeMemory)~='function' then return false end
    local base=sampGetBase();if not base or base==0 then return false end
    if readMemory(base,2,true)~=0x5A4D then return false end
    local pe=readMemory(base+0x3C,4,true);if pe<64 or pe>4096 then return false end
    local entry=readMemory(base+pe+0x28,4,true)
    return entry==0x31DF13 or entry==0xCC4D0
end
local function update()
    if not c.enabled or not (c.appear or c.slide or c.fade or c.background) or failed or not integration.access:can(1) or sampGetGamestate()~=3 then restore();return end
    if not compatible()then restore();return end
    local now=getGameTimer()
    if not integration.preferences.data.main.blockF1F4 and wasKeyPressed(118)then restore();skipUntil=now+500;return end -- Let native F7 cycle its own mode.
    if (skipUntil and now<skipUntil)or sampIsDialogActive()or isPauseMenuActive()or not isGameWindowForeground()
        or isKeyDown(33)or isKeyDown(34) then restore();return end
    local ptr=sampGetChatInfoPtr();if not ptr or ptr==0 then restore();return end
    if owned and owned~=ptr then owned,original=nil,nil end
    local page=readMemory(ptr,4,true);local mode=readMemory(ptr+8,4,true)
    local bottom=readMemory(ptr+302,4,true);local scroll=readMemory(ptr+25566,4,true)
    local height=readMemory(ptr+25570,4,true)+1
    local sw,sh=getScreenResolution()
    if page<1 or page>100 or height<5 or height>100 or bottom<page*height or bottom>sh or scroll~=100-page then restore();return end
    if owned and mode~=0 then owned,original=nil,nil end
    if not owned and mode==0 then layout=nil;return end
    if not font or fontHeight~=height then
        if font then renderReleaseFont(font);font=nil end
        font=renderCreateFont('Arial',math.max(8,math.floor(height*.65)),5,true);fontHeight=height
        if not font then restore();return end
    end
    local rows={};local timestamps=readMemory(ptr+12,1,true)~=0
    for i=scroll,scroll+page-1 do
        local text,prefix=sampGetChatString(i)
        text=tostring(text or '');prefix=tostring(prefix or '')
        local entry=ptr+306+i*252
        local stamp=readMemory(entry,4,true)
        local textColor=readMemory(entry+244,4,true);local prefixColor=readMemory(entry+248,4,true)
        if text~=''then
            local time=timestamps and ('['..os.date('%H:%M:%S',stamp)..'] ')or ''
            rows[#rows+1]={key=table.concat({stamp,prefix,text,textColor,prefixColor},'|'),
                copyText=(prefix~=''and prefix..' 'or '')..text,
                text=time..(prefix~=''and string.format('{%06X}%s ',bit.band(prefixColor,0xFFFFFF),prefix)or '')
                    ..string.format('{%06X}',bit.band(textColor,0xFFFFFF))..text,color=textColor}
        end
    end
    animation:update(rows,now)
    layout={x=35,bottom=bottom,height=height,width=math.max(100,math.min(sw-70,1000))}
    if not owned then original=mode;owned=ptr;writeMemory(ptr+8,4,0,true)end
end
local function draw()
    if not layout or not owned or not font then return end
    renderedRows={}
    local typing=sampIsChatInputActive()
    if typing then animation.lastActivity=getGameTimer()end
    local options=typing and {}or c
    local now=getGameTimer();local lineHeight=math.max(layout.height,renderGetFontDrawHeight(font))
    local keys={tostring(layout.width),tostring(font)}
    for _,row in ipairs(animation.rows)do keys[#keys+1]=row.key end
    local key=table.concat(keys,'\n')
    local lines=cachedLines
    if cacheKey~=key then
    lines={}
    -- CP1251 native chat bytes, preserving embedded color changes when wrapping.
    for _,row in ipairs(animation.rows)do
        local line,active='',string.format('{%06X}',bit.band(row.color,0xFFFFFF))
        local pos=1
        while pos<=#row.text do
            local token=row.text:sub(pos,pos+7)
            if token:match('^{%x%x%x%x%x%x}$')then active=token;line=line..token;pos=pos+8
            else
                local ch=row.text:sub(pos,pos)
                if renderGetFontDrawTextLength(font,line..ch)>layout.width then lines[#lines+1]={text=line,row=row};line=active end
                line=line..ch;pos=pos+1
            end
        end
        lines[#lines+1]={text=line,row=row}
    end
    cachedLines,cacheKey=lines,key
    end
    local count=math.min(#lines,math.max(1,math.floor((layout.bottom-20)/lineHeight)))
    local top=layout.bottom-count*lineHeight
    local newest=animation.rows[#animation.rows]
    local opacity=newest and select(1,animation:frame(newest,now,{fade=c.fade and not typing}))or 1
    if c.background and count>0 then renderDrawBox(layout.x-8,top-5,layout.width+16,count*lineHeight+10,bit.bor(bit.lshift(math.floor(145*opacity),24),0x12101B))end
    for i=#lines-count+1,#lines do
        local line=lines[i];local alpha=animation:frame(line.row,now,options)
        local _,slide=animation:frame(newest or line.row,now,options)
        local a=math.floor(255*alpha)
        local y=top+(i-(#lines-count+1))*lineHeight+slide*lineHeight*.65
        renderedRows[#renderedRows+1]={x=layout.x,y=y,width=math.min(layout.width,renderGetFontDrawTextLength(font,line.text)),height=lineHeight,text=line.row.copyText}
        local x,pos,rgb=layout.x,1,bit.band(line.row.color,0xFFFFFF)
        while pos<=#line.text do
            local first,last,tag=line.text:find('{(%x%x%x%x%x%x)}',pos)
            local part=line.text:sub(pos,first and first-1 or #line.text)
            if part~=''then
                renderFontDrawText(font,part,x,y,bit.bor(bit.lshift(a,24),rgb))
                x=x+renderGetFontDrawTextLength(font,part)
            end
            if not first then break end
            rgb=tonumber(tag,16);pos=last+1
        end
    end
end
local function guarded(fn)
    local ok,err=pcall(fn)
    if not ok then stop();failed=true;print('[X-Tools Chat ERROR] '..tostring(err));integration.message('Анимация чата отключена из-за ошибки. Стандартный чат восстановлен. Подробности: moonloader.log.')end
end
integration.update=function()guarded(update)end
integration.onD3DPresent=function()guarded(draw)end
integration.stop=stop
integration.onDisconnect=function()stop();failed=nil end
integration.onAccessChanged=stop
integration.chatHit=function(x,y)
    if not owned or not layout then return false end
    for _,row in ipairs(renderedRows)do
        if x>=row.x and x<=row.x+row.width and y>=row.y and y<row.y+row.height then return true,row end
    end
    return true
end
integration.nativeVisible=function()if owned then return original~=0 end end
integration.onWindowMessage=function(msg,key)
    if c.enabled and not integration.preferences.data.main.blockF1F4 and msg==0x100 and key==118 then restore();skipUntil=getGameTimer()+500 end
end
integration.drawSettings=function()
    local enabled=g.ImBool(c.enabled)
    if g.Checkbox('Оформление и анимация чата',enabled)then
        c.enabled=enabled.v;failed=nil
        if c.enabled and not compatible()then c.enabled=false;integration.message('Оформление чата поддерживает SA-MP 0.3.7 R1 и R3-1.')end
        if not c.enabled then stop()end
        integration.storage:saveIni(cfg,path)
    end
    if not c.enabled then return end
    for _,item in ipairs({{'appear','Плавное появление сообщений'},{'slide','Выезд сообщений снизу'},{'fade','Затухание без активности'},{'background','Тёмная подложка чата'}})do
        local value=g.ImBool(c[item[1]])
        if g.Checkbox(item[2],value)then c[item[1]]=value.v;integration.storage:saveIni(cfg,path)end
    end
    g.TextWrapped('Эффекты можно сочетать. При вводе оформление сохраняется, а затухание приостанавливается. При просмотре истории используется стандартный чат. Затухание начинается через 7 секунд без новых сообщений.')
end

    end
    sources["modules/chat_copy.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/chat_copy.lua
-- Original third-party credits, where present, are retained below.
-- Read-only CChat layout: BlastHackNet/SAMP-API, CChat.h (R1 and R3-1).
local g=require('imgui')
local path=integration.storage:path('settings','chat-copy.ini')
local cfg=integration.storage:loadIni({main={enabled=false}},path)
local font,version,noticeUntil
local function stop()if font then renderReleaseFont(font);font=nil end end
integration.stop=stop
integration.onDisconnect=function()stop();version=nil end
integration.drawSettings=function()
 local b=g.ImBool(cfg.main.enabled)
 if g.Checkbox('Копировать строки чата по ПКМ',b)then cfg.main.enabled=b.v;integration.storage:saveIni(cfg,path);if not b.v then stop()end end
 if cfg.main.enabled then g.TextWrapped('Откройте чат, наведите на строку и нажмите правую кнопку мыши.')end
end
local function supported()
 if version~=nil then return version end
 if type(sampGetChatInfoPtr)~='function'or type(readMemory)~='function'then return false end
 local base=sampGetBase();if not base or base==0 then return false end
 local pe=readMemory(base+0x3C,4,true)
 if readMemory(base,2,true)~=0x5A4D or pe<64 or pe>4096 then version=false;return false end
 local entry=readMemory(base+pe+0x28,4,true)
 version=entry==0x31DF13 or entry==0xCC4D0
 return version
end
integration.onD3DPresent=function()
 if not cfg.main.enabled or not sampIsChatInputActive()or sampIsDialogActive()or isPauseMenuActive()or not isGameWindowForeground()or sampGetGamestate()~=3 then return end
 if not supported()then return end
 local ptr=sampGetChatInfoPtr();if not ptr or ptr==0 then return end
 local page=readMemory(ptr,4,true)
 local mode=readMemory(ptr+8,4,true)
 local bottom=readMemory(ptr+302,4,true)
 local scroll=readMemory(ptr+25566,4,true)
 local height=readMemory(ptr+25570,4,true)+1
 local sw,sh=getScreenResolution()
 local x,y=getCursorPos()
 local styled,hit=integration.styledChatHit(x,y)
 if styled and not hit then return end
 if not styled and (mode==0 or page<1 or page>100 or height<5 or height>100 or bottom>sh or scroll>100-page)then return end
 local top=bottom-page*height
 local value,boxX,boxY,boxHeight
 if styled then
  value=hit.text;boxX,boxY,boxHeight=hit.x,hit.y,hit.height
 else
 if x<35 or x>math.min(sw-30,1000)or y<top or y>=bottom then return end
 local row=math.floor((y-top)/height)
 local index=scroll+row
 if index<0 or index>99 then return end
 local text,prefix=sampGetChatString(index)
 text=tostring(text or ''):gsub('{%x%x%x%x%x%x}','')
 prefix=tostring(prefix or ''):gsub('{%x%x%x%x%x%x}','')
 if text==''then return end
 value=(prefix~=''and(prefix..' ')or'')..text
 boxX,boxY,boxHeight=35,top+row*height,height
 end
 value=tostring(value or ''):gsub('{%x%x%x%x%x%x}','')
 if value==''then return end
 if not font then font=renderCreateFont('Verdana',9,5,true)end
 if not font then return end
 local width=math.min(sw-35,math.max(100,renderGetFontDrawTextLength(font,value)+30))
 if x>boxX+width then return end
 renderDrawBox(boxX,boxY,styled and hit.width or width,boxHeight,0x304B3282)
 local copied=false
 if wasKeyPressed(2)then copied=integration.service('clipboard_unicode.lua').copy(value,1251);if copied then noticeUntil=getGameTimer()+1200 end end
 local hint=noticeUntil and getGameTimer()<noticeUntil and 'Скопировано' or 'ПКМ — копировать строку'
 renderFontDrawText(font,require('encoding').UTF8:decode(hint),math.min(x+15,sw-220),math.min(y+height,sh-25),0xFFB995FF)
end

    end
    sources["modules/clickwarp.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/clickwarp.lua
-- Original third-party credits, where present, are retained below.
-- Selected click-warp behaviour, shared input ownership.
local g=require('imgui')
local settings=integration.service('combo_settings.lua')
local cfg,path=settings.load(integration,'clickwarp',{main={enabled=false}})
local packets=integration.service('sync_packets.lua').new(_G)
local selecting,target,point,marker=false,nil,nil,nil
local function removeMarker()if marker then removeUser3dMarker(marker);marker=nil end end
local function cancel()
    selecting=false;target=nil;point=nil;removeMarker();integration.refreshInput()
end
local function start()
    if selecting then cancel();return end
    if not cfg.main.enabled or not integration.access:require(3,integration.message)then return end
    local player=integration.observation()
    if not player then integration.message('ClickWarp: сначала начните слежку за игроком.');return end
    target={id=player.id,nickname=player.nickname};selecting=true;integration.refreshInput()
end
integration.keys:register('clickwarp','ClickWarp — выбрать точку в слежке',{key=4,second=0})
integration.keys:register('clickwarp_apply','ClickWarp — переместить игрока',{key=1,second=0})
integration.begin=start
integration.ownsMarkerInput=function()return integration.access:can(3) and integration.observation()~=nil end
integration.onDisconnect=cancel
integration.stop=cancel
integration.onAccessChanged=cancel
integration.reconcilePointer=function(windowVisible)
    local observed=selecting and integration.observation()
    if selecting and (windowVisible or not observed or observed.id~=target.id or observed.nickname~=target.nickname) then
        selecting=false;target=nil;point=nil;removeMarker()
    end
end
integration.hudActive=function()return selecting,selecting,false end
integration.update=function()
    local toggle=integration.keys:pressed('clickwarp')
    local apply=integration.keys:pressed('clickwarp_apply')
    local input=not integration.windowOpen() and isGameWindowForeground() and not isPauseMenuActive() and not sampIsChatInputActive() and not sampIsDialogActive()
    if selecting and (not input or not cfg.main.enabled or sampGetGamestate()~=3 or not integration.access:can(3))then cancel();return end
    if toggle and input and integration.observation()~=nil and sampGetGamestate()==3 and (selecting or not sampIsCursorActive())then start() end
    if not selecting then return end
    if isKeyDown(27)then cancel();return end
    local observed=integration.observation()
    if not observed or observed.id~=target.id or observed.nickname~=target.nickname
        or not sampIsPlayerConnected(target.id) or sampGetPlayerNickname(target.id)~=target.nickname then cancel();return end
    local sx,sy=getCursorPos();local sw,sh=getScreenResolution()
    point=nil;removeMarker()
    if sx<0 or sy<0 or sx>=sw or sy>=sh then return end
    local x,y,z=convertScreenCoordsToWorld3D(sx,sy,700)
    local cx,cy,cz=getActiveCameraCoordinates()
    local hit,p=processLineOfSight(cx,cy,cz,x,y,z,true,true,false,true,false,false,false)
    if not hit or not p or p.entity==0 then return end
    local n=p.normal;x=p.pos[1]-n[1]*0.1;y=p.pos[2]-n[2]*0.1;z=p.pos[3]-n[3]*0.1
    local ground,q=processLineOfSight(x,y,z+(n[3]>=0.5 and 1 or 300),x,y,z-0.3,true,true,false,true,false,false,false)
    if not ground or not q then return end
    point={q.pos[1],q.pos[2],q.pos[3]+1.2}
    marker=createUser3dMarker(point[1],point[2],point[3]+0.1,4)
    if apply then
        -- One snapshot; player sync is not suppressed during normal server spectating.
        if packets.onfoot(point[1],point[2],point[3]) then sampSendChat('/gethere '..target.id..' 1')end
        cancel()
    end
end
local settingsExpanded=false
integration.drawSettings=function()
    if not integration.access:can(3) then g.TextDisabled('ClickWarp доступен с 3 уровня');return end
    if settings.toggle(g,'ClickWarp — перенос игрока мышью в слежке',cfg.main,'enabled')then
        if not cfg.main.enabled then cancel()end;integration.storage:saveIni(cfg,path)
    end
    g.SameLine()
    if g.Button('Настройки##clickwarp_settings')then settingsExpanded=not settingsExpanded end
    if not settingsExpanded then return end
    integration.keys:draw(g,'clickwarp');integration.keys:draw(g,'clickwarp_apply')
    g.TextWrapped('В слежке включите выбор точки назначенной клавишей. Маркер показывает место переноса; подтверждение — ЛКМ по умолчанию. Esc отменяет. Колёсико включает выбор точки; повторное нажатие отменяет. ЛКМ переносит игрока и убирает метку.')
end

    end
    sources["modules/correction.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/correction.lua
-- Original third-party credits, where present, are retained below.
-- CorrectionWords, using Yandex Speller; no background check while disabled.
local g=require('imgui');local u8=require('encoding').UTF8;local events=require('lib.samp.events')
local settings=integration.service('combo_settings.lua')
integration.keys:register('correction_apply','Коррекция: применить подсказку',{key=113})
integration.keys:register('correction_input','Коррекция: исправить ввод',{key=88,ctrl=true})
integration.keys:register('correction_undo','Коррекция: вернуть исходный текст',{key=90,ctrl=true})
local settingsExpanded=false
local cfg,path=settings.load(integration,'correction',{main={enabled=false,mode=2,hint=true,auto_upper_and_point=true}})
local generation,serial=0,0;local pending,undo=nil,nil;local sending=false;local hintShown=false
local function save()integration.storage:saveIni(cfg,path)end
integration.onDisconnect=function()generation=generation+1;serial=serial+1;pending=nil;undo=nil;hintShown=false end
integration.stop=integration.onDisconnect
local channels={b=true,n=true,a=true,ad=true,s=true,w=true,r=true,f=true,me=true,["do"]=true,todo=true}
local function split(raw)
    if raw:sub(1,1)~='/'then return '',raw end
    local cmd,rest=raw:match('^/(%w+)%s+(.+)$');if not cmd then return end
    if channels[cmd:lower()]then return '/'..cmd..' ',rest end
    if cmd:lower()=='ans'then local id,text=rest:match('^(%d+)%s+(.+)$');if id then return '/ans '..id..' ',text end end
end
local function prepare(text)
    if not cfg.main.auto_upper_and_point then return text end
    local first=text:byte(1);if not first then return text end
    local upper=first>=224 and first<=255 and string.char(first-32)or first==184 and string.char(168)or text:sub(1,1):upper()
    text=upper..text:sub(2);if not text:find('[.!?:]$')then text=text..'.'end;return text
end
local function replaceWords(text,words)
    local suggestions={};local done={}
    for _,entry in ipairs(words)do
        if type(entry)=='table' and type(entry.word)=='string' and type(entry.s)=='table'and type(entry.s[1])=='string'then
            local wrong,right=u8:decode(entry.word),u8:decode(entry.s[1])
            if wrong~=''and not done[wrong]then
                text=text:gsub(wrong:gsub('([^%w])','%%%1'),function()return right end)
                suggestions[#suggestions+1]=right;done[wrong]=true
            end
        end
    end
    return text,table.concat(suggestions,', ')
end
local activeRequest
local nextRequestAt,noticeAt=0,0
local function notice(text)
    if os.time()>=noticeAt then integration.message(text);noticeAt=os.time()+5 end
end
local function pollRequest()
    local job=activeRequest
    if not job then return end
    if job.completed then
        activeRequest=nil
        local file=io.open(job.path,'rb')
        local body
        if file then body=file:read(32769);file:close() end
        os.remove(job.path)
        if job.expired or os.time()>=job.deadline or job.token~=generation or not cfg.main.enabled or job.latestOnly and job.ticket~=serial then return end
        if not body or #body>32768 or not body:match('^%s*%[') then notice('Коррекция недоступна. Исходный текст оставлен в поле ввода.');return end
        local valid,data=pcall(decodeJson,body)
        if not valid or type(data)~='table' or #data>256 then notice('Коррекция: неверный ответ сервиса. Исходный текст сохранён.');return end
        job.done(replaceWords(job.text,data))
    elseif os.time()>=job.deadline and not job.expired then
        job.expired=true
        -- Keep the slot until native completion: a timeout must not spawn more downloads.
        notice('Коррекция не ответила вовремя. Новые проверки приостановлены; исходный текст сохранён.')
    end
end
local function request(text,done,latestOnly)
    serial=serial+1
    if activeRequest or os.time()<nextRequestAt then
        notice('Коррекция: предыдущая проверка ещё выполняется. Исходный текст сохранён.');return false
    end
    if #text>512 then notice('Коррекция: текст слишком длинный для проверки.');return false end
    local url='https://speller.yandex.net/services/spellservice.json/checkText?text='..tostring(u8(text)):gsub('([^%w%-_%.~])',function(c)return string.format('%%%02X',c:byte())end)
    local job={token=generation,ticket=serial,text=text,done=done,latestOnly=latestOnly,deadline=os.time()+10}
    job.path=integration.storage:path('cache','speller-'..os.time()..'-'..getGameTimer()..'-'..math.random(1,1000000000)..'.tmp')
    activeRequest=job;nextRequestAt=os.time()+1
    local ok,result=pcall(downloadUrlToFile,url,job.path,function(_,status)
        if status==6 or status==58 then job.completed=true end
    end)
    if not ok or result==false then
        activeRequest=nil;os.remove(job.path)
        notice('Коррекция: не удалось начать проверку. Исходный текст сохранён.');return false
    end
    return true
end
local function send(text)
    if #text>144 or text:find('[%z\1-\31]')then integration.message('Исправленный текст слишком длинный или содержит управляющие символы.');return end
    sending=true;sampSendChat(text);sending=false
end
local function check(raw,input,display)
    local prefix,text=split(raw);if not text or text==''then return end
    local original=raw;text=prepare(text)
    local mode=cfg.main.mode
    local started=request(text,function(corrected,suggestions)
        if input then
            if sampIsChatInputActive()and sampGetChatInputText()==original then undo=original;sampSetChatInputText(prefix..corrected)end
        elseif display then integration.message(tostring(u8(prefix..corrected)))
        elseif mode==1 then send(prefix..corrected)
        elseif suggestions~=''then pending={text=suggestions,prefix=prefix,mode=mode};integration.message('Найдены ошибки: '..tostring(u8(suggestions))..'. '..integration.keys:name('correction_apply')..' — '..(mode==3 and 'копировать.'or 'отправить исправление.'))end
    end,input or (mode~=1 and not display))
    if mode==1 and not input and not display then sampSetChatInputText(original);return false end
end
function events.onSendChat(text)
    if cfg.main.enabled and not sending and not integration.commandOwner()then return check(text)end
end
function events.onSendCommand(text)
    if cfg.main.enabled and not sending and not integration.commandOwner()then return check(text)end
end
integration.update=function()
    pollRequest()
    if integration.keys:captureActive() or integration.windowOpen() or not cfg.main.enabled or sampGetGamestate()~=3 then return end
    if not isGameWindowForeground()or isPauseMenuActive()or sampIsDialogActive()then return end
    if sampIsChatInputActive()then
        if integration.keys:pressed('correction_input')then check(sampGetChatInputText(),true)end
        if integration.keys:pressed('correction_undo')and undo then serial=serial+1;sampSetChatInputText(undo);undo=nil end
    elseif integration.keys:pressed('correction_apply')and pending then
        if pending.mode==3 then setClipboardText(pending.text)else send(pending.prefix..'Кхе.. '..pending.text..'.')end;pending=nil
    end
end
integration.start=function()
    sampRegisterChatCommand('checkw',function(text)if cfg.main.enabled then check(text,false,true)end end)
end
integration.drawSettings=function()
    local enabled=g.ImBool(cfg.main.enabled)
    if g.Checkbox('Коррекция текста',enabled)then cfg.main.enabled=enabled.v;integration.onDisconnect();save()end
    g.SameLine()
    if g.Button('Настройки##correction_settings') then settingsExpanded=not settingsExpanded end
    if not settingsExpanded then return end
    
    integration.keys:draw(g,'correction_input')
    integration.keys:draw(g,'correction_undo')
    integration.keys:draw(g,'correction_apply')
    local mode=g.ImInt(math.max(0,math.min(2,cfg.main.mode-1)));g.PushItemWidth(310)
    if g.Combo('Режим коррекции',mode,'Исправить до отправки\0Подсказка после отправки\0Копировать исправления\0\0')then cfg.main.mode=mode.v+1;integration.onDisconnect();save()end
    g.PopItemWidth()
    if settings.toggle(g,'Заглавная буква и точка',cfg.main,'auto_upper_and_point')then save()end
end

    end
    sources["modules/crimelegends.lua"] = function()
-- CrimeLegends 1.6.0 integrated from the installed source; local factories, no package.preload changes.
local factories,cache={},{}
local nativeRequire=require
local function require(name)
    if not factories[name]then return nativeRequire(name)end
    if cache[name]==nil then cache[name]=factories[name]()end
    return cache[name]
end
local gate=integration.service('legends_server.lua')
local function isBlue()return gate.allowed(_G)end
integration.isBlue=isBlue

factories['crimelegends.text']=function(...)
-- The source stays readable UTF-8; MoonLoader's chat and DxFont expect Windows-1251.
local Text={}
function Text.game(value)
    return (value:gsub('[\194-\244][\128-\191]+',function(sequence)
        local first,second=sequence:byte(1,2)
        local code=(first-192)*64+(second-128)
        if #sequence==2 and code>=0x410 and code<=0x44F then return string.char(code-0x350) end
        if code==0x401 then return string.char(0xA8) end
        if code==0x451 then return string.char(0xB8) end
        return '?'
    end))
end

-- Chat has a short byte limit. Split on spaces, never truncate a role or alias.
function Text.chunks(value, limit)
    local lines, line={},''
    for word in value:gmatch('%S+') do
        if #line>0 and #line+#word+1>limit then lines[#lines+1]=line;line='' end
        while #word>limit do
            if #line>0 then lines[#lines+1]=line;line='' end
            lines[#lines+1]=word:sub(1,limit);word=word:sub(limit+1)
        end
        line=line=='' and word or line..' '..word
    end
    if line~='' then lines[#lines+1]=line end
    return lines
end
return Text

end

