factories['crimelegends.sites']=function(...)
-- Coordinates copied from the installed X-TOOLS teleport menu, 2026-09-22.
-- Headings and row offsets below are our staging, not X-TOOLS teleport data.
local Sites={
    {id='GROVE STREET',key='grove',title='Grove Street',x=2494.3,y=-1694.1,z=23.7,heading=0},
    {id='BALLAS',key='ballas',title='The Ballas',x=2010.3,y=-1135.9,z=25,heading=0},
    {id='VAGOS',key='vagos',title='Los Santos Vagos',x=2766.1,y=-1177.9,z=69.4,heading=0},
    {id='RIFA',key='rifa',title='The Rifa',x=2745,y=-1925.2,z=21.6,heading=0},
    {id='AZTECAS',key='aztecas',title='Varios Los Aztecas',x=2188.8,y=-1820.6,z=18.9,heading=0},
    {id='LA COSA NOSTRA',key='lcn',title='La Cosa Nostra',x=1491,y=2773.9,z=16,heading=0},
    {id='YAKUZA',key='yakuza',title='Yakuza',x=2597,y=1913.1,z=28.3,heading=0},
    {id='RUSSIAN MAFIA',key='rm',title='Русская мафия',x=989.2,y=1733.3,z=10.8,heading=0},
    -- /az sends /inter 82 and /setvw 777. 82 is a SERVER preset, not a GTA
    -- interior ID: use the player's actual active interior after the transition.
    {id='ADMINZONE',key='az',title='AdminZone (/az)',x=-773.6,y=498.1,z=1376.6,heading=0,admin=true},
}
function Sites.find(query)
    query=(query or ''):lower()
    for _,site in ipairs(Sites) do
        if site.key==query or site.id:lower()==query then return site end
    end
end
function Sites.context(x,y,z,interior)
    local az=Sites.find('az')
    if (x-az.x)^2+(y-az.y)^2<120^2 and math.abs(z-az.z)<30 then return 'ADMINZONE' end
    return interior==0 and 'OUTSIDE' or 'OTHER'
end
return Sites

end

