factories['crimelegends.activities']=function(...)
-- Two asynchronously loaded animation blocks. Only owned, settled peds are used.
local Activities={};Activities.__index=Activities
local clips={
    {block='GANGS',name='prtial_gngtlkA'},
    {block='DEALER',name='DEALER_IDLE_01'},
    {block='GANGS',name='prtial_gngtlkB'},
    {block='DEALER',name='DEALER_IDLE_02'},
    {block='GANGS',name='prtial_gngtlkC'},
    {block='DEALER',name='DEALER_IDLE'},
}
function Activities.new(api) return setmetatable({api=api,blocks={},actors={}},Activities) end
function Activities:clear()
    for name,block in pairs(self.blocks) do if block.requested then self.api.release(name) end end
    self.blocks={};self.actors={}
end
function Activities:update(now,owned)
    local wanted,alive={},{}
    for _,ped in pairs(owned) do
        if ped.settled and self.api.exists(ped.handle) then
            local id=ped.entry.person.id
            local clip=clips[(id-1)%#clips+1]
            wanted[clip.block]=true;alive[ped.handle]=true
            if not self.actors[ped.handle] then
                self.actors[ped.handle]={clip=clip,checkAt=now+.15+(id%7)*.17}
            end
        end
    end
    for handle in pairs(self.actors) do if not alive[handle] then self.actors[handle]=nil end end
    for name,block in pairs(self.blocks) do
        if not wanted[name] then
            if block.requested then self.api.release(name) end
            self.blocks[name]=nil
        end
    end
    for name in pairs(wanted) do
        local block=self.blocks[name] or {retry=0}
        self.blocks[name]=block
        if not block.requested and now>=block.retry then
            self.api.request(name);block.requested=true;block.started=now
        end
        block.loaded=block.requested and self.api.loaded(name)
        if block.requested and not block.loaded and now-block.started>=8 then
            self.api.release(name);block.requested=false;block.retry=now+30
        end
    end
    for handle,actor in pairs(self.actors) do
        local clip=actor.clip
        if self.blocks[clip.block].loaded and now>=actor.checkAt then
            if not self.api.playing(handle,clip.name) then self.api.play(handle,clip.name,clip.block) end
            actor.checkAt=now+2.5
        end
    end
end
return Activities

end

factories['crimelegends.visibility']=function(...)
-- Distant rendering for owned NPCs on verified GTA SA 1.0 US layouts.
-- Replace only an instance's stock distance-culling callback with GTA's own
-- default renderer. No Lua callbacks, code hooks, shared models or global LOD writes.
local Visibility={};Visibility.__index=Visibility
local PED_RENDER,DEFAULT_RENDER=0x7335B0,0x7491C0
local signatures={
    {0x7328A0,'8b44240885c07505b8c091740085c08b4c2404894148'},
    {PED_RENDER,'56578b7c240c8b773c8b4604'},
    {DEFAULT_RENDER,'568b7424088b466c85c0750f'},
}
local function pointer(value)
    return type(value)=='number' and value>=0x10000 and value<0x7FFF0000 and value%4==0
end

function Visibility.accessibleRegion(addr,size,base,regionSize,state,protect,write)
    if type(addr)~='number' or addr<0x10000 or size<=0 or addr+size>=0x7FFF0000 or state~=0x1000 then return false end
    if math.floor(protect/256)%2==1 then return false end -- PAGE_GUARD
    local kind=protect%256
    local permitted=kind==4 or kind==8 or kind==0x40 or kind==0x80
    if not write then permitted=permitted or kind==2 or kind==0x20 end
    return permitted and addr>=base and addr+size<=base+regionSize
end

function Visibility.nativeDependencies(api,ffi,memory)
    api=api or _G
    for _,name in ipairs({'getCharPointer','getModuleProcAddress','doesCharExist'}) do
        assert(type(api[name])=='function','Missing MoonLoader API: '..name)
    end
    ffi=ffi or require 'ffi'
    memory=memory or require 'memory'
    assert(ffi.sizeof('void *')==4,'Win32 required')
    -- MoonLoader takes a module NAME here, unlike Windows GetProcAddress.
    local address=api.getModuleProcAddress('kernel32.dll','VirtualQuery')
    assert(address and address~=0,'Cannot resolve kernel32.dll!VirtualQuery')
    -- Native Windows function pointer, never a callback into Lua/JIT.
    local query=ffi.cast('uint32_t (__stdcall *)(const void *, void *, uint32_t)',address)
    local info=ffi.new('uint32_t[7]') -- MEMORY_BASIC_INFORMATION for Win32, 28 bytes.
    local function accessible(addr,size,write)
        if type(addr)~='number' or addr<0x10000 or addr+size>=0x7FFF0000 then return false end
        if query(ffi.cast('const void *',addr),info,28)~=28 then return false end
        return Visibility.accessibleRegion(addr,size,tonumber(info[0]),tonumber(info[3]),
            tonumber(info[4]),tonumber(info[5]),write)
    end
    return {memory=memory,exists=api.doesCharExist,pedPointer=api.getCharPointer,player=api.PLAYER_PED,
        accessible=accessible}
end

function Visibility.new(deps)
    local self=setmetatable({records={},supported=false,patched=0,reason='native API unavailable',nextCheck=0},Visibility)
    if not deps then
        local ok,result=pcall(Visibility.nativeDependencies)
        if not ok or not result then self.reason='native initialization: '..tostring(result);return self end
        deps=result
    end
    self.deps=deps
    if type(deps.accessible)~='function' then self.reason='memory guard unavailable';return self end
    local ok,matched=pcall(function()
        for _,signature in ipairs(signatures) do
            assert(deps.accessible(signature[1],#signature[2]/2,false),('Unreadable signature at 0x%X'):format(signature[1]))
            for index=1,#signature[2],2 do
                local addr=signature[1]+(index-1)/2
                local expected=tonumber(signature[2]:sub(index,index+1),16)
                local actual=deps.memory.getuint8(addr)
                assert(actual==expected,('Renderer mismatch at 0x%X: expected %02X, got %02X'):format(addr,expected,actual))
            end
        end
        return true
    end)
    self.supported=ok and matched
    self.reason=self.supported and 'verified native renderer' or tostring(matched)
    return self
end

function Visibility:collect(handle)
    local d=self.deps
    if handle==d.player or not d.exists(handle) then return nil end
    local read=d.memory.getuint32
    local ped=d.pedPointer(handle)
    if not pointer(ped) or not d.accessible(ped,0x1C,false) then return nil end
    local clump=read(ped+0x18)
    if not pointer(clump) or not d.accessible(clump,0x10,false) or d.memory.getuint8(clump)~=2 then return nil end
    local head=clump+8
    local link,previous=read(head),head
    local atoms,seen={},{}
    while link~=head do
        if #atoms>=32 or not pointer(link) or seen[link] then return nil end
        seen[link]=true
        local atomic=link-0x40
        if not pointer(atomic) or not d.accessible(atomic,0x70,false)
            or d.memory.getuint8(atomic)~=1 or read(atomic+0x3C)~=clump or read(link+4)~=previous then return nil end
        atoms[#atoms+1]={pointer=atomic,callback=read(atomic+0x48)}
        previous,link=link,read(link)
    end
    if read(head+4)~=previous or #atoms==0 then return nil end
    return {ped=ped,clump=clump,atoms=atoms}
end

function Visibility:release(handle)
    local record=self.records[handle]
    if not record then return end
    self.records[handle]=nil
    if record.counted then self.patched=self.patched-1 end
    local ok,current=pcall(self.collect,self,handle)
    if not ok or not current or current.ped~=record.ped or current.clump~=record.clump then return end
    local present={}
    for _,atom in ipairs(current.atoms) do present[atom.pointer]=atom.callback end
    for _,atom in ipairs(record.atoms) do
        if present[atom.pointer]==DEFAULT_RENDER and self.deps.accessible(atom.pointer+0x48,4,true) then
            pcall(self.deps.memory.setuint32,atom.pointer+0x48,atom.callback,false)
        end
    end
end

function Visibility:apply(handle)
    if not self.supported then return false end
    local ok,current=pcall(self.collect,self,handle)
    if not ok or not current then self:release(handle);return false end
    local record=self.records[handle]
    if record then
        local same=current.ped==record.ped and current.clump==record.clump and #current.atoms==#record.atoms
        for index,atom in ipairs(current.atoms) do
            same=same and record.atoms[index] and atom.pointer==record.atoms[index].pointer and atom.callback==DEFAULT_RENDER
        end
        if same then return true end
        self:release(handle)
        ok,current=pcall(self.collect,self,handle)
        if not ok or not current then return false end
    end
    -- The entire clump must still use stock callbacks. A custom render mod wins.
    for _,atom in ipairs(current.atoms) do
        if atom.callback~=PED_RENDER or not self.deps.accessible(atom.pointer+0x48,4,true) then return false end
    end
    self.records[handle]=current
    local success=pcall(function()
        for _,atom in ipairs(current.atoms) do
            self.deps.memory.setuint32(atom.pointer+0x48,DEFAULT_RENDER,false)
            assert(self.deps.memory.getuint32(atom.pointer+0x48)==DEFAULT_RENDER,'Callback write failed')
        end
    end)
    if not success then self:release(handle);return false end
    self.patched=self.patched+1;current.counted=true
    return true
end

function Visibility:clear()
    local handles={}
    for handle in pairs(self.records) do handles[#handles+1]=handle end
    for _,handle in ipairs(handles) do self:release(handle) end
end

function Visibility:update(now,owned)
    if not self.supported or now<self.nextCheck then return end
    self.nextCheck=now+.75
    local live={}
    for _,ped in pairs(owned) do live[ped.handle]=true;self:apply(ped.handle) end
    local stale={}
    for handle in pairs(self.records) do if not live[handle] then stale[#stale+1]=handle end end
    for _,handle in ipairs(stale) do self:release(handle) end
end
return Visibility

end

factories['crimelegends.scene']=function(...)
-- Pure layout and bounded streaming. No game globals and no network access.
local Scene = {}
local catalog=require 'crimelegends.catalog'
local Sites=require 'crimelegends.sites'
local adminRows=require 'crimelegends.admin_rows'
Scene.__index = Scene
Scene.defaultAnchor = Sites.find('grove')
Scene.groups = {
    {id='AZTECAS', title='LOS AZTECAS', subtitle='ЛЕГЕНДЫ ГЕТТО', x=-13, y=12, color=0x61DCF1},
    {id='GROVE STREET', title='GROVE STREET', subtitle='ЛЕГЕНДЫ ГЕТТО', x=13, y=12, color=0x7EDA85},
    {id='RIFA', title='THE RIFA', subtitle='ЛЕГЕНДЫ ГЕТТО', x=-13, y=34, color=0x70ADFA},
    {id='BALLAS', title='THE BALLAS', subtitle='ЛЕГЕНДЫ ГЕТТО', x=13, y=34, color=0xC99AFA},
    {id='VAGOS', title='LOS SANTOS VAGOS', subtitle='ЛЕГЕНДЫ ГЕТТО', x=-13, y=56, color=0xF7D76E},
    {id='gang_admins', title='СЛЕДЯЩИЕ ЗА ГЕТТО', subtitle='АДМИНИСТРАЦИЯ', x=13, y=56, color=0xE6BD72},
    {id='RUSSIAN MAFIA', title='RUSSIAN MAFIA', subtitle='ЛЕГЕНДЫ МАФИЙ', x=-13, y=78, color=0xCCB7EF},
    {id='LA COSA NOSTRA', title='LA COSA NOSTRA', subtitle='ЛЕГЕНДЫ МАФИЙ', x=13, y=78, color=0xE8C795},
    {id='YAKUZA', title='YAKUZA', subtitle='ЛЕГЕНДЫ МАФИЙ', x=-13, y=100, color=0xEB9396},
    {id='mafia_admins', title='СЛЕДЯЩИЕ ЗА МАФИЯМИ', subtitle='АДМИНИСТРАЦИЯ', x=13, y=100, color=0xE6BD72},
}

function Scene.finite(value)
    return type(value)=='number' and value==value and math.abs(value)<math.huge
end

function Scene.validAnchor(anchor)
    if type(anchor)~='table' then return false end
    for _,key in ipairs({'x','y','z','heading'}) do
        if not Scene.finite(anchor[key]) then return false end
    end
    return math.abs(anchor.x)<6000 and math.abs(anchor.y)<6000 and anchor.z>-80 and anchor.z<1500
end

function Scene.world(anchor, right, forward)
    local angle=math.rad(anchor.heading)
    return anchor.x+right*math.cos(angle)-forward*math.sin(angle),
           anchor.y+right*math.sin(angle)+forward*math.cos(angle), anchor.z
end

function Scene.headingTowards(x,y,targetX,targetY)
    -- GTA heading 0 faces +Y, heading 90 faces -X.
    return math.deg(math.atan2(x-targetX,targetY-y))%360
end

function Scene.layout(roster, anchor)
    local entries,signs,buckets,definitions={},{},{},{}
    local cast={}
    for _,definition in ipairs(Scene.groups) do definitions[#definitions+1]=definition end
    for _,definition in ipairs(catalog.sections) do definitions[#definitions+1]=definition end
    for _,person in ipairs(roster) do
        for _,slot in ipairs(person.placements) do
            local avatar={}
            for key,value in pairs(person) do avatar[key]=value end
            for key,value in pairs(slot) do if key~='id' then avatar[key]=value end end
            avatar.placementId=slot.id
            cast[#cast+1]=avatar
            buckets[slot.section]=buckets[slot.section] or {}
            table.insert(buckets[slot.section],avatar)
        end
    end
    local placed={}
    local customHeights={3,3,3,3}
    for _,definition in ipairs(definitions) do
        local people=buckets[definition.id] or {}
        if #people>0 then
            local faction=Sites.find(definition.id)
            local site=anchor or faction or Sites.find('az')
            local right,forward=0,3
            if anchor then
                local heights=customHeights
                local lane=1
                for i=2,#heights do if heights[i]<heights[lane] then lane=i end end
                right=(lane-(#heights+1)/2)*10
                forward=heights[lane]
                heights[lane]=forward+math.ceil(#people/6)*2.4+1.5
            end
            local planned=not anchor and not faction and assert(adminRows[definition.id]) or nil
            local row,column,consumed=0,0,0
            for slot,person in ipairs(people) do
                local rowPlan=planned and planned[row+1]
                local capacity=rowPlan and rowPlan.capacity or 6
                local rowCount=math.min(capacity,#people-consumed)
                local x,y,z
                if rowPlan then
                    x,y,z=rowPlan.x+(column-(rowCount-1)/2)*1.25,rowPlan.y,rowPlan.z
                else
                    x,y,z=Scene.world(site,right+(column-(rowCount-1)/2)*1.25,forward+row*2.4)
                end
                local heading=(site.heading+180+(column%2==0 and 24 or -24))%360
                local radians=math.rad(heading)
                placed[person.placementId]={id=person.placementId,person=person,x=x,y=y,z=z,
                    lookX=x-math.sin(radians),lookY=y+math.cos(radians),heading=heading,
                    section=definition.id,site=anchor and 'CUSTOM' or site.id,
                    context=not anchor and site.admin and 'ADMINZONE' or 'OUTSIDE',row=row,column=column}
                column=column+1
                if column>=capacity then row=row+1;column=0;consumed=consumed+capacity end
            end
            local x,y,z=Scene.world(site,right,forward-1)
            if planned then x,y,z=planned[1].x,planned[1].y-1,planned[1].z end
            signs[#signs+1]={title=definition.title,count=#people,x=x,y=y,z=z+1.8,
                color=definition.color,site=anchor and 'CUSTOM' or site.id}
        end
    end
    for _,person in ipairs(cast) do entries[#entries+1]=assert(placed[person.placementId],'Unassigned role') end
    return entries,signs
end

function Scene.new(roster, api, anchor)
    local self=setmetatable({roster=roster,api=api,owned={},retry={},pending=nil,
        limit=40,radius=450,count=0,failed=0},Scene)
    self:setAnchor(anchor)
    return self
end

function Scene:clear()
    for id,entry in pairs(self.owned) do
        self.api.remove(entry.handle)
        self.owned[id]=nil
    end
    if self.pending then self.api.release(self.pending.model) end
    self.pending=nil
    self.count=0
end

function Scene:setAnchor(anchor)
    assert(anchor==nil or Scene.validAnchor(anchor),'Invalid scene position')
    self:clear()
    self.custom=anchor and {x=anchor.x,y=anchor.y,z=anchor.z,heading=anchor.heading%360} or nil
    self.anchor=self.custom or Scene.defaultAnchor
    self.entries,self.signs=Scene.layout(self.roster,self.custom)
    self.retry={}
end

function Scene:nearest(x,y,z)
    local nearest,distance
    for _,entry in ipairs(self.entries) do
        local squared=(entry.x-x)^2+(entry.y-y)^2+(entry.z-z)^2
        if not distance or squared<distance then nearest,distance=entry,squared end
    end
    return nearest,math.sqrt(distance)
end

function Scene:find(query)
    query=query:lower():gsub('_',' ')
    local found,exact={},{}
    for _,entry in ipairs(self.entries) do
        if entry.person.search:gsub('_',' '):find(query,1,true) then found[#found+1]=entry end
        if entry.person.nick:lower():gsub('_',' ')==query then exact[#exact+1]=entry end
    end
    return #exact>0 and exact or found
end

function Scene:update(now, x,y,z, capacity, context)
    context=context or Sites.context(x,y,z,0)
    local candidates={}
    for _,entry in ipairs(self.entries) do
        local id=entry.id
        local owned=self.owned[id]
        if owned and not self.api.exists(owned.handle) then
            self.owned[id]=nil;owned=nil
        end
        local distance=math.sqrt((entry.x-x)^2+(entry.y-y)^2+(entry.z-z)^2)
        if entry.context==context and distance<self.radius+(owned and 30 or 0) then
            candidates[#candidates+1]={entry=entry,rank=distance-(owned and 3 or 0)}
        end
    end
    table.sort(candidates,function(a,b)
        if a.rank==b.rank then return a.entry.id<b.entry.id end
        return a.rank<b.rank
    end)
    local wanted={}
    local budget=math.max(0,math.min(self.limit,math.floor(capacity or self.limit)))
    for index=1,math.min(budget,#candidates) do wanted[candidates[index].entry.id]=true end
    self.count=0
    for id,owned in pairs(self.owned) do
        if not wanted[id] then self.api.remove(owned.handle);self.owned[id]=nil
        else
            self.count=self.count+1
            if not owned.settled and now-owned.created>=1 then
                owned.settled=self.api.settle(owned.handle,owned.entry)~=false
                if not owned.settled and now-owned.created>5 then
                    self.api.remove(owned.handle);self.owned[id]=nil
                    self.count=self.count-1;self.retry[id]=now+30
                    self.failed=self.failed+1
                end
            end
        end
    end
    if self.pending then
        local pending=self.pending
        if not wanted[pending.entry.id] or now-pending.started>=8 then
            self.api.release(pending.model)
            if wanted[pending.entry.id] then
                self.retry[pending.entry.id]=now+30
                self.failed=self.failed+1
            end
            self.pending=nil
        end
    end
    if not self.pending then
        for _,candidate in ipairs(candidates) do
            local entry=candidate.entry
            local id=entry.id
            if wanted[id] and not self.owned[id] and now>=(self.retry[id] or 0) then
                self.pending={entry=entry,model=entry.person.skin,started=now}
                self.api.request(entry.person.skin)
                break
            end
        end
    end
    local pending=self.pending
    if pending and self.api.loaded(pending.model) then
        local handle=self.api.spawn(pending.entry)
        -- Release only the streaming request; a live ped retains its model reference.
        self.api.release(pending.model)
        self.pending=nil
        if handle then
            self.owned[pending.entry.id]={handle=handle,entry=pending.entry,created=now,settled=false}
            self.count=self.count+1
        else
            self.retry[pending.entry.id]=now+5
            self.failed=self.failed+1
        end
    end
end

return Scene

end

factories['crimelegends.labels']=function(...)
-- Subtle world labels. No panel, cursor, hotkeys, or changes to the game HUD.
local Text=require 'crimelegends.text'
local Labels={}
Labels.__index=Labels
local function alpha(rgb,opacity)
    return math.floor(math.max(0,math.min(1,opacity))*255)*0x1000000+rgb
end
local function intersects(a,b)
    return a.x<b.x+b.w+5 and a.x+a.w+5>b.x and a.y<b.y+b.h+4 and a.y+a.h+4>b.y
end

function Labels.new()
    return setmetatable({fonts={},fontState={},cache={},width=0,height=0,lost=false,
        range=60,maxNames=24,lastFrame={names={},detailCount=0,signCount=0,fontsReady=false}},Labels)
end

function Labels:close()
    for _,font in pairs(self.fonts) do renderReleaseFont(font) end
    self.fonts={};self.fontState={};self.cache={};self.width=0;self.height=0
end

function Labels:createFont(name,points,bold)
    local size=math.max(8,math.min(16,math.floor(points+.5)))
    self.fonts[name]=renderCreateFont('Tahoma',size,bold and 5 or 4,204)
    self.fontState[name]={size=size,height=math.ceil(size*1.5)}
end

function Labels:prepareFonts()
    local ready=true
    for name,state in pairs(self.fontState) do
        -- Metrics may remain zero until the font is actually drawn. They are
        -- informational only: waiting for them before drawing deadlocks labels.
        local actual=renderGetFontDrawHeight(self.fonts[name])
        local valid=type(actual)=='number' and actual==actual and actual>0 and actual<200
        state.measured=valid and actual or 0
        if valid then state.height=actual else ready=false end
    end
    return ready
end

function Labels:fontHeight(name) return self.fontState[name].height end

function Labels:resize(width,height)
    if self.width==width and self.height==height then return end
    self:close()
    self.width,self.height=width,height
    self.scale=math.max(.95,math.min(1.35,height/1080))
    self:createFont('name',10*self.scale,false)
    self:createFont('title',11*self.scale,true)
end

function Labels:measure(fontName,text)
    local key=fontName..':'..text
    if not self.cache[key] then
        local encoded=Text.game(text)
        local width=renderGetFontDrawTextLength(self.fonts[fontName],encoded)
        if type(width)=='number' and width==width and width>0 and width<10000 then
            self.cache[key]={text=encoded,width=width}
            return self.cache[key]
        end
        -- Temporary layout estimate; do not cache unloaded glyph metrics.
        return {text=encoded,width=#encoded*self:fontHeight(fontName)*.52}
    end
    return self.cache[key]
end

function Labels:center(fontName,text,x,y,color,opacity)
    local measured=self:measure(fontName,text)
    renderFontDrawText(self.fonts[fontName],measured.text,x-measured.width/2,y,alpha(color,opacity))
end

function Labels:freeRectangle(rect,occupied)
    if rect.x<8 or rect.x+rect.w>self.width-8 or rect.y<8 or rect.y+rect.h>self.height-8 then return false end
    for _,other in ipairs(occupied) do if intersects(rect,other) then return false end end
    return true
end

function Labels:draw(scene,player,details,focusedId)
    if self.lost then return end
    local width,height=getScreenResolution()
    self:resize(width,height)
    local frame={names={},detailCount=0,signCount=0,fontsReady=self:prepareFonts()}
    self.lastFrame=frame
    local cameraX,cameraY,cameraZ=getActiveCameraCoordinates()
    local scale=self.scale
    -- Reserve the normal chat, weapon HUD and radar areas.
    local occupied={
        {x=0,y=0,w=width*.52,h=height*.30},
        {x=width*.76,y=0,w=width*.24,h=height*.24},
        {x=0,y=height*.76,w=width*.23,h=height*.24},
        {x=0,y=height*.94,w=width,h=height*.06},
    }
    local candidates={}
    for _,owned in pairs(scene.owned) do
        if doesCharExist(owned.handle) and isCharOnScreen(owned.handle) then
            local x,y,z=getCharCoordinates(owned.handle)
            local distance=math.sqrt((x-player.x)^2+(y-player.y)^2+(z-player.z)^2)
            if distance<self.range and isLineOfSightClear(cameraX,cameraY,cameraZ,x,y,z+.65,true,true,false,true,false) then
                local visible,sx,sy=convert3DCoordsToScreenEx(x,y,z+1.02,true,true)
                if visible then candidates[#candidates+1]={entry=owned.entry,x=sx,y=sy,distance=distance} end
            end
        end
    end
    table.sort(candidates,function(a,b)
        if a.distance==b.distance then return a.entry.person.id<b.entry.person.id end
        return a.distance<b.distance
    end)
    frame.candidates=#candidates
    for _,candidate in ipairs(candidates) do
        if #frame.names>=self.maxNames then break end
        local person=candidate.entry.person
        local fontName='name'
        local nameHeight=self:fontHeight(fontName)
        local nickname=person.nick or person.name
        local textWidth=self:measure(fontName,nickname).width
        local blockHeight=nameHeight+5*scale
        local rect={x=candidate.x-textWidth/2-4*scale,y=candidate.y-blockHeight,
            w=textWidth+8*scale,h=blockHeight}
        if self:freeRectangle(rect,occupied) then
            occupied[#occupied+1]=rect
            local opacity=math.min(1,(self.range-candidate.distance)/15)
            local x,y=candidate.x,rect.y
            self:center(fontName,nickname,x,y,person.color,opacity)
            frame.names[#frame.names+1]={id=person.id,rect=rect}
        end
    end
    if details then
        local nearest,range
        for _,sign in ipairs(scene.signs) do
            local distance=math.sqrt((sign.x-player.x)^2+(sign.y-player.y)^2+(sign.z-player.z)^2)
            if sign.count>0 and distance<14 and (not range or distance<range) then nearest,range=sign,distance end
        end
        if nearest then
            local sign=nearest
            if isLineOfSightClear(cameraX,cameraY,cameraZ,sign.x,sign.y,sign.z,true,true,false,true,false) then
                local visible,x,y=convert3DCoordsToScreenEx(sign.x,sign.y,sign.z,true,true)
                if visible then
                    local h=self:fontHeight('title')
                    local w=self:measure('title',sign.title).width
                    local rect={x=x-w/2-8,y=y,w=w+16,h=h+5*scale}
                    if self:freeRectangle(rect,occupied) then
                        self:center('title',sign.title,x,y,sign.color,.65*math.min(1,(14-range)/5))
                        frame.signCount=1
                    end
                end
            end
        end
    end
    self.lastFrame=frame
end

return Labels

end

factories['crimelegends.diagnostics']=function(...)
-- Two bounded local files. Preserve the preceding session across a game restart.
-- Write and close each entry so a native crash does not lose the last checkpoint.
local Diagnostics={}
Diagnostics.__index=Diagnostics
local LIMIT=128*1024

function Diagnostics.new(path)
    local self=setmetatable({path=path,size=0,disabled=false},Diagnostics)
    local ok=pcall(function()
        local previous=io.open(path,'rb')
        if previous then
            local data=previous:read(LIMIT);previous:close()
            if data and #data>0 then
                local backup=io.open(path..'.previous','wb')
                if backup then backup:write(data);backup:close() end
            end
        end
        local file=io.open(path,'wb')
        if file then file:close() else self.disabled=true end
    end)
    if not ok then self.disabled=true end
    return self
end

function Diagnostics:write(message)
    if self.disabled then return end
    local line=message:sub(1,1023)..'\n'
    local ok=pcall(function()
        -- Keep the latest checkpoints even during long sessions.
        local rotate=self.size+#line>LIMIT
        local file=io.open(self.path,rotate and 'wb' or 'ab')
        if not file then self.disabled=true;return end
        file:write(line);file:close()
        self.size=(rotate and 0 or self.size)+#line
    end)
    if not ok then self.disabled=true end
end

return Diagnostics

end


local Scene=require 'crimelegends.scene'
local Sites=require 'crimelegends.sites'
local Activities=require 'crimelegends.activities'
local Visibility=require 'crimelegends.visibility'
local Labels=require 'crimelegends.labels'
local Diagnostics=require 'crimelegends.diagnostics'
local roster=require 'crimelegends.roster'
local scene,diagnostics,activities,visibility,labels
local lastInterior,lastContext,readySince
local stopped=false
local clock,nextUpdate=0,0

local function trace(message)
    if diagnostics then diagnostics:write(('[%.2f] %s'):format(clock,message)) end
end

local function playerReady()
    return isBlue() and integration.featureAllowed() and isSampAvailable() and sampGetGamestate()==3 and sampIsLocalPlayerSpawned()
        and doesCharExist(PLAYER_PED) and not isCharDead(PLAYER_PED)
        and isPlayerPlaying(PLAYER_HANDLE)
end

local function groundAt(entry)
    requestCollision(entry.x,entry.y)
    -- Include collision of server objects and interior floors; an outdoor height
    -- query alone may return zero inside AdminZone. Never spawn on a missed ray.
    local depth=entry.context=='ADMINZONE' and 8 or 18
    local hit,point=processLineOfSight(entry.x,entry.y,entry.z+2,
        entry.x,entry.y,entry.z-depth,true,false,false,true,false,false,false,false)
    if not hit or not point or not point.pos then return nil end
    local floor=point.pos[3]
    if not Scene.finite(floor) or floor<entry.z-depth or floor>entry.z+2 then return nil end
    if point.normal and point.normal[3] and point.normal[3]<.65 then return nil end
    -- Reject pillars, low ceilings and walls crossing the standing footprint.
    if not isLineOfSightClear(entry.x,entry.y,floor+.15,entry.x,entry.y,floor+2.05,true,false,false,true,false)
        or not isLineOfSightClear(entry.x-.38,entry.y,floor+.9,entry.x+.38,entry.y,floor+.9,true,false,false,true,false)
        or not isLineOfSightClear(entry.x,entry.y-.38,floor+.9,entry.x,entry.y+.38,floor+.9,true,false,false,true,false) then return nil end
    return floor
end

local api={}
function api.exists(handle) return doesCharExist(handle) end
function api.remove(handle)
    if visibility then visibility:release(handle) end
    if handle~=PLAYER_PED and doesCharExist(handle) then
        trace('remove begin '..handle)
        deleteChar(handle)
        trace('remove ok '..handle)
    end
end
function api.request(model) requestModel(model) end
function api.loaded(model) return hasModelLoaded(model) end
function api.release(model) markModelAsNoLongerNeeded(model) end
function api.spawn(entry)
    trace(('spawn begin id=%d skin=%d xyz=%.1f,%.1f,%.1f'):format(
        entry.person.id,entry.person.skin,entry.x,entry.y,entry.z))
    local floor=groundAt(entry)
    if not floor then trace('spawn deferred: ground not loaded');return nil end
    trace('createChar begin')
    local ped=createChar(entry.person.pedType or 4,entry.person.skin,entry.x,entry.y,floor+.05)
    if not ped or ped==PLAYER_PED or not doesCharExist(ped) then return nil end
    trace('createChar ok '..ped)
    -- If any setup call fails, the new handle must not escape the owned set.
    local ok,err=pcall(function()
        setCharInterior(ped,getActiveInterior())
        setCharCollision(ped,true)
        setCharHeading(ped,entry.heading)
        setCharHealth(ped,100)
        setCharProofs(ped,true,true,true,true,true)
        setCharNeverTargetted(ped,true)
        setCharDrownsInWater(ped,false)
        taskStandStill(ped,-1)
        if visibility then visibility:apply(ped) end
    end)
    if not ok then api.remove(ped);error(err) end
    entry.floor=floor
    trace('spawn ok '..ped)
    return ped
end
function api.settle(ped,entry)
    -- Let GTA finish placing the feet. Keep physical collision and animated joints.
    local _,_,height=getCharCoordinates(ped)
    if isCharWaitingForWorldCollision(ped) or math.abs(height-entry.floor)>1.8 then return false end
    trace('settle begin '..ped)
    taskStandStill(ped,-1)
    setCharHeading(ped,entry.heading)
    freezeCharPosition(ped,false)
    setCharCollision(ped,true)
    setCharKindaStayInSamePlace(ped,true)
    trace('settle ok '..ped)
    return true
end

local function clearScene()
    if scene then scene:clear() end
    if activities then activities:clear() end
    if visibility then visibility:clear() end
end

local function stop()
    if stopped then return end
    stopped=true
    trace('cleanup begin')
    clearScene()
    if labels then labels:close() end
    trace('cleanup ok')
end

integration.start=function()
    while not playerReady() do wait(250)end
    diagnostics=Diagnostics.new(integration.storage:path('logs','crimelegends.log'))
    trace('CrimeLegends 1.6.0; models and nicknames; no commands; all roles; preload 450; ped limit 40')
    visibility=Visibility.new()
    scene=Scene.new(roster,api)
    labels=Labels.new()
    scene.radius=450
    trace('visibility: '..visibility.reason)
    activities=Activities.new({exists=doesCharExist,request=requestAnimation,loaded=hasAnimationLoaded,
        release=removeAnimation,playing=isCharPlayingAnim,
        play=function(ped,name,block)
            taskPlayAnimNonInterruptable(ped,name,block,4,true,true,true,false,-1)
        end})
    trace('scene initialized: '..#roster..' identities, '..#scene.entries..' role placements')
    local previousTimer=getGameTimer()/1000
    while not stopped do
        wait(0)
        local timer=getGameTimer()/1000
        clock=clock+math.max(0,math.min(.2,timer-previousTimer));previousTimer=timer
        if not playerReady() then
            if scene.count>0 or scene.pending then clearScene() end
            lastInterior=nil;lastContext=nil;readySince=nil
        elseif not isPauseMenuActive() then
            local x,y,z=getCharCoordinates(PLAYER_PED)
            local interior=getActiveInterior()
            local context=Sites.context(x,y,z,interior)
            if lastInterior~=interior or lastContext~=context then
                clearScene();readySince=nil;nextUpdate=0
                lastInterior=interior;lastContext=context
            end
            readySince=readySince or clock
            if clock-readySince>=1.5 then
                local ok,err=xpcall(function()
                    if clock>=nextUpdate then
                        -- Keep at least 30 of GTA's standard 140 ped slots free.
                        local ownLiving=0
                        for _,owned in pairs(scene.owned) do
                            if doesCharExist(owned.handle) then ownLiving=ownLiving+1 end
                        end
                        local outside=math.max(0,#getAllChars()-ownLiving)
                        scene:update(clock,x,y,z,math.max(0,110-outside),context)
                        activities:update(clock,scene.owned)
                        visibility:update(clock,scene.owned)
                        nextUpdate=clock+.1
                    end
                    labels:draw(scene,{x=x,y=y,z=z},false,nil)
                end,debug.traceback)
                if not ok then
                    trace('runtime error: '..tostring(err))
                    stop()
                end
            end
        end
    end
end

integration.onD3DDeviceLost=function() if labels then labels.lost=true end end
integration.onD3DDeviceReset=function() if labels then labels.lost=false end end
integration.stop=stop
integration.suspend=function()clearScene();readySince=nil;lastContext=nil;lastInterior=nil end
integration.onDisconnect=integration.suspend

local directory
integration.directory=function()
    if not isBlue()then return {}end
    if not directory then
        directory=Scene.layout(roster)
        local metadata={}
        for _,section in ipairs(require('crimelegends.catalog').sections)do metadata[section.id]=section end
        for _,entry in ipairs(directory)do
            local section=metadata[entry.section]
            local admin=section or entry.section=='gang_admins' or entry.section=='mafia_admins'
            entry.role=admin and 'Администрация' or 'Лидеры'
            entry.faction=section and section.faction or (entry.section=='gang_admins' and 'ГЕТТО' or entry.section=='mafia_admins' and 'МАФИИ' or entry.section)
            entry.badge=section and section.badge or entry.person.badge
        end
    end
    return directory
end

    end
