-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/death_effect.lua
-- Original third-party credits, where present, are retained below.
local g=require('imgui');local ffi=require('ffi');local bit=require('bit')
local path=integration.storage:path('settings','death-effect.ini')
local cfg=integration.storage:loadIni({main={enabled=false}},path)
local nativeBone
local api=setmetatable({}, {__index=_G})
local animation=integration.service('death_animation.lua').new(ffi,bit)
api.startDeathAnimation=function(ped,clump)
    if isCharInAnyCar(ped)or isCharInWater(ped)then return end
    return animation.start(clump)
end
api.releaseDeathAnimation=function(clump,token)animation.release(clump,token)end
api.headPosition=function(ped,ptr)
    -- CPed::GetBonePosition, BONE_NECK (4); follows the animated neck.
    local bone=readMemory(ptr+0x490,4,false)
    if not bone or bone<0x10000 or bone>=0x80000000 then return end
    nativeBone=nativeBone or ffi.cast('void (__thiscall*)(void*, float*, int, bool)',0x5E4280)
    local out=ffi.new('float[3]')
    nativeBone(ffi.cast('void*',ptr),out,4,true)
    return tonumber(out[0]),tonumber(out[1]),tonumber(out[2])
end
local effect=integration.service('death_effect.lua').new(api,bit)
local checked,supported=false,false
local nextTick=0
local function compatible()
    if not checked then checked=true;supported=effect:compatible()end
    return supported
end
local function stop()effect:stop();nextTick=0 end
integration.update=function()
    if not cfg.main.enabled or not integration.access:can(1) or sampGetGamestate()~=3 then stop();return end
    if not compatible()then return end
    local now=getGameTimer();if now<nextTick then return end;nextTick=now+60
    local peds={};local seen={}
    local function add(ped)if ped and ped~=0 and not seen[ped]and doesCharExist(ped)then seen[ped]=true;peds[#peds+1]=ped end end
    add(PLAYER_PED)
    for id=0,math.min(1004,sampGetMaxPlayerId(false))do
        if sampIsPlayerConnected(id)then local found,ped=sampGetCharHandleBySampPlayerId(id);if found then add(ped)end end
    end
    effect:update(peds,now)
end
integration.drawSettings=function()
    local value=g.ImBool(cfg.main.enabled)
    if g.Checkbox('Эффект обезглавливания при смерти',value)then
        cfg.main.enabled=value.v
        if value.v and not compatible()then cfg.main.enabled=false;integration.message('Эффект недоступен: требуется совместимая GTA SA 1.0 US.')end
        if not cfg.main.enabled then stop()end
        integration.storage:saveIni(cfg,path)
    end
    if cfg.main.enabled then g.TextWrapped('При смерти на суше проигрывается замедленная анимация обезглавливания; кровь идёт из шеи 4 секунды. В машине и воде сохраняется штатная поза. Эффект виден только вам; здоровье и причина смерти не меняются.')end
end
integration.stop=stop;integration.onDisconnect=stop;integration.onAccessChanged=stop

    end
