-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/display_layout.lua
-- Original third-party credits, where present, are retained below.
-- One editor for all registered free-position HUD elements. Previews never
-- enable gameplay features or send commands. Positions use each owner's saver.
local g=require('imgui')
local rows=nil
local generation=0
integration.openEditor=function()
 generation=generation+1
 rows=integration.collectLayoutItems()
 integration.setLayoutEditing(true)
 integration.beginPlacement(function()
  for _,r in ipairs(rows or {})do r.set(r.x,r.y)end
  rows=nil;integration.setLayoutEditing(false)
 end)
end
integration.stop=function()rows=nil;integration.setLayoutEditing(false)end
integration.hudActive=function()return rows~=nil,rows~=nil,false end
integration.drawHud=function()
 if not rows then return end
 local sw,sh=getScreenResolution()
 for i,r in ipairs(rows)do
  local width=math.min(r.w or 280,sw-20);local height=math.min(r.h or 110,sh-20)
  r.x=math.max(0,math.min(r.x or 30,sw-width));r.y=math.max(0,math.min(r.y or 100,sh-height))
  if r.preview then r.preview(r.x,r.y)end
  g.SetNextWindowPos(g.ImVec2(r.x,r.y),g.Cond.Always)
  g.SetNextWindowSize(g.ImVec2(width,height),g.Cond.Always)
  g.PushStyleColor(g.Col.WindowBg,g.ImVec4(0,0,0,0))
  g.PushStyleVar(g.StyleVar.WindowPadding,g.ImVec2(0,0))
  g.Begin('##layout_drag_'..generation..'_'..i,nil,g.WindowFlags.NoTitleBar+g.WindowFlags.NoResize+g.WindowFlags.NoCollapse+g.WindowFlags.NoSavedSettings+g.WindowFlags.NoMove+g.WindowFlags.NoScrollbar)
  g.InvisibleButton('##drag',g.ImVec2(width,height))
  local hover=g.IsItemHovered();local active=g.IsItemActive()
  local mouse=g.GetMousePos()
  if active then
   if not r.drag then r.drag={mx=mouse.x,my=mouse.y,x=r.x,y=r.y}end
   r.x=math.max(0,math.min(r.drag.x+mouse.x-r.drag.mx,sw-width))
   r.y=math.max(0,math.min(r.drag.y+mouse.y-r.drag.my,sh-height))
  else r.drag=nil end
  if hover or active then
   local d=g.GetWindowDrawList();local pos=g.GetWindowPos()
   d:AddRect(pos,g.ImVec2(pos.x+width,pos.y+height),0xFFB995FF,2)
   if hover and not active then g.SetTooltip(r.name..' · удерживайте ЛКМ для перемещения')end
  end
  g.End();g.PopStyleVar();g.PopStyleColor()
 end
end

    end
