-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/environment.lua
-- Original third-party credits, where present, are retained below.
-- Local weather/time from setWeather&Time; no version-specific memory patch.
local imgui, sampev = require 'imgui', require 'samp.events'
local storage = integration.storage
local CONFIG = storage:path('settings', 'environment.ini', {getWorkingDirectory() .. '/config/CasualAT_environment.ini'})
local cfg = storage:loadIni({environment={time_enabled=false,weather_enabled=false,hour=12,weather=0}}, CONFIG) or {}
cfg.environment=type(cfg.environment)=='table' and cfg.environment or {}
local settings = cfg.environment
local function bounded(value, maximum, fallback)
    value=tonumber(value)
    if not value or value~=value or value<0 or value>maximum then return fallback end
    return math.floor(value)
end
settings.hour=bounded(settings.hour,23,12)
settings.weather=bounded(settings.weather,45,0)
settings.time_enabled=settings.time_enabled==true
settings.weather_enabled=settings.weather_enabled==true
local serverHour,serverMinute,serverWeather,timeApplied,weatherApplied
local function save() storage:saveIni(cfg,CONFIG) end
local function connected() return isSampAvailable() and sampGetGamestate()==3 end
local function restoreTime()
    if timeApplied and serverHour then setTimeOfDay(serverHour,serverMinute or 0) end
    timeApplied=false
end
local function restoreWeather()
    if weatherApplied then
        if serverWeather then forceWeatherNow(serverWeather)
        elseif type(releaseWeather)=='function' then releaseWeather() end
    end
    weatherApplied=false
end
local function apply()
    if not connected() then return end
    if settings.time_enabled then
        if not timeApplied and type(getTimeOfDay)=='function' then
            serverHour,serverMinute=getTimeOfDay()
        end
        setTimeOfDay(settings.hour,0); timeApplied=true
    elseif timeApplied then restoreTime() end
    if settings.weather_enabled then
        if not weatherApplied then forceWeatherNow(settings.weather) end
        weatherApplied=true
    elseif weatherApplied then restoreWeather() end
end

function sampev.onInitGame(playerId,hostName,world,vehicleModels,vehicleFriendlyFire)
    if type(world)~='table' then return end
    serverHour,serverMinute,serverWeather=world.worldTime,0,world.worldWeather
    timeApplied,weatherApplied=settings.time_enabled,settings.weather_enabled
    if not timeApplied and not weatherApplied then return end
    local patched={}; for key,value in pairs(world) do patched[key]=value end
    if timeApplied then patched.worldTime=settings.hour end
    if weatherApplied then patched.worldWeather=settings.weather end
    return {playerId,hostName,patched,vehicleModels,vehicleFriendlyFire}
end
function sampev.onSetPlayerTime(hour,minute)
    serverHour,serverMinute=hour,minute
    if settings.time_enabled then return {settings.hour,0} end
end
function sampev.onSetWorldTime(hour)
    serverHour,serverMinute=hour,0
    if settings.time_enabled then return {settings.hour} end
end
function sampev.onSetWeather(weather)
    serverWeather=weather
    if settings.weather_enabled then return {settings.weather} end
end
local function command(kind,arg)
    arg=tostring(arg or ''):match('^%s*(.-)%s*$'):lower()
    local enabled=kind=='time' and 'time_enabled' or 'weather_enabled'
    local key=kind=='time' and 'hour' or 'weather'
    local maximum=kind=='time' and 23 or 45
    if arg=='' or arg=='off' then
        settings[enabled]=false
        if kind=='time' then restoreTime() else restoreWeather() end
    elseif arg:match('^%d+$') and tonumber(arg)<=maximum then
        settings[key],settings[enabled]=tonumber(arg),true
        if kind=='weather' then weatherApplied=false end
        apply()
    else
        integration.message((kind=='time' and '/st' or '/sw')..' 0–'..maximum..'. Без аргумента или с off — вернуть серверное значение.')
        return
    end
    save()
end
function integration.start()
    while true do
        apply()
        wait(settings.time_enabled and connected() and 0 or 250)
    end
end
integration.drawSettings=function()
    imgui.Text('Локальное время и погода')
    imgui.TextWrapped('Выберите время и погоду для своей игры. Чтобы изменить погоду на сервере, откройте «Инструменты» → «Погода».')
    imgui.Spacing()
    local time=imgui.ImBool(settings.time_enabled)
    if imgui.Checkbox('Зафиксировать время суток',time) then settings.time_enabled=time.v; apply(); save() end
    local hour=imgui.ImInt(settings.hour)
    imgui.PushItemWidth(150)
    if imgui.InputInt('Час суток: 0–23',hour) then settings.hour=bounded(hour.v,23,settings.hour); apply(); save() end
    imgui.PopItemWidth(); imgui.Spacing()
    local weather=imgui.ImBool(settings.weather_enabled)
    if imgui.Checkbox('Зафиксировать погоду',weather) then settings.weather_enabled=weather.v; apply(); save() end
    local id=imgui.ImInt(settings.weather)
    imgui.PushItemWidth(150)
    if imgui.InputInt('ID погоды: 0–45',id) then settings.weather=bounded(id.v,45,settings.weather); weatherApplied=false; apply(); save() end
    imgui.PopItemWidth(); imgui.Spacing()
    imgui.TextWrapped('Снимите галочку, чтобы вернуть серверное значение. Изменения сохраняются автоматически.')
    imgui.Separator()
    integration.drawSkySettings()
end
integration.draw=integration.drawSettings
integration.onDisconnect=function()
    restoreTime(); restoreWeather()
    serverHour,serverMinute,serverWeather=nil,nil,nil
end
function integration.stop() restoreTime(); restoreWeather() end

integration.setLocalValue=command

    end
