local function punishmentChannel()
    local n=tonumber(punishment.main.channel)
    return (n==0 or n==1 or n==300) and n or 300
end
local replyExists=integration.storage:exists(replyPath)
local replies=integration.storage:loadIni({main={enabled=false,delay=2,cooldown=15,color=1724645631,return_delay=15}},replyPath)
if not replyExists then
    local old=integration.storage:loadIni({main={}},integration.storage:path('settings','autoreply.ini'))
    replies.main.enabled=old.main.family_answers==true
    replies.main.delay=tonumber(old.main.reply_delay) or 2
    replies.main.cooldown=tonumber(old.main.message_cooldown) or 15
    replies.main.return_delay=old.main.afk_protect==false and 0 or tonumber(old.main.return_delay) or 15
    replies.main.color=tonumber(old.main.strict_color) or 1724645631
    integration.storage:saveIni(replies,replyPath)
end
local keywordParser=integration.service('family_question.lua')
local keywordPath=integration.storage:path('settings','family-keywords.ini')
local keywordConfig=integration.storage:loadIni({main={count=-1},words={}},keywordPath)
local keywords,keywordBuffers={},{}
if tonumber(keywordConfig.main.count)==-1 then
    for i,word in ipairs(keywordParser.defaults)do keywords[i]=word end
else
    for i=1,math.min(100,math.max(0,tonumber(keywordConfig.main.count)or 0))do
        keywords[i]=tostring(keywordConfig.words['word'..i]or '')
    end
end
local replyGeneration,replyRecent,replyAway,replyReturned=0,{},false,-100000
local function replyReady()
    local time=getGameTimer()/1000
    if not isGameWindowForeground() or isPauseMenuActive() or isGamePaused() then replyAway=true;return false end
    if replyAway then replyAway=false;replyReturned=time end
    return time-replyReturned>=replies.main.return_delay
end

local function now() return getGameTimer() / 1000 end
local function trim(s) return (s or ''):match('^%s*(.-)%s*$') end
local function clean(s) return trim((s or ''):gsub('{%x+}', '')) end
-- Server statistics may uppercase account names; SA-MP nicknames are ASCII.
-- Keep the original spelling for commands and player-ID ownership checks.
local function sameAccountName(a, b)
    if not a or not b then return false end
    a, b = clean(a), clean(b)
    return a ~= '' and b ~= '' and a:lower() == b:lower()
end
local function say(s) sampAddChatMessage(u8:decode('{F4C542}[X-Tools]{FFFFFF} ' .. s), -1) end
local function syncAccess()
    local revision = integration.access:revision()
    if revision ~= accessRevision then
        accessRevision = revision
        generation = generation + 1
        queue, family = {}, nil
        if pending then pending.cancelled = true end
    end
end
local function send(s)
    internal = true
    local result=sampSendChat(u8:decode(s))
    internal = false
    return result
end
local function nickname(id)
    if id and id >= 0 and id <= 1003 and sampIsPlayerConnected(id) then
        return tostring(u8(sampGetPlayerNickname(id)))
    end
end
local function enqueue(job)
    syncAccess()
    if not integration.access:require(1, say) then return end
    if #queue >= 10 then say('Очередь запросов заполнена. Команду можно повторить после её освобождения.'); return end
    job.accessRevision = accessRevision
    queue[#queue + 1] = job
    return true
end
local function observe(id)
    watching = true
    if target == id then return end
    target, family = id, nil
    if not enabled or not integration.access:can(1) then return end
    -- Drop obsolete overlay requests, preserve all punishments.
    for i = #queue, 1, -1 do
        if queue[i].kind == 'view' then table.remove(queue, i) end
    end
    local name = nickname(id)
    if name then enqueue({kind = 'view', id = id, name = name}) end
end
local function punish(kind, raw)
    if not enabled then say('Работа с семьями выключена. Включение: Настройки → Семьи или /familia.'); return end
    if not integration.access:require(1, say) then return end
    local args = trim(tostring(u8(raw)))
    local subject, amount, reason
    if kind == 'warn' then subject, reason = args:match('^(%S+)%s+(.+)$')
    else subject, amount, reason = args:match('^(%S+)%s+(%d+)%s+(.+)$') end
    local id=subject and subject:match('^%d+$') and tonumber(subject)or nil
    if not subject or not reason or trim(reason) == '' or (kind ~= 'warn' and tonumber(amount) < 1) then
        say(kind == 'warn' and 'Использование: /fw ID/Ник причина' or
            (kind == 'jail' and 'Использование: /fj ID/Ник минуты причина' or 'Использование: /fb ID/Ник дни причина'))
        return
    end
    local name=id and nickname(id)or subject
    if id and not nickname(id)then say('Игрок с указанным ID не в сети. Введите ник.');return end
    if not id and (not name:match('^[%w_%.]+$')or #name>24 or #name<3)then say('Укажите корректный ник игрока.');return end
    if (kind=='ban'or kind=='warn')and integration.isKnownAdmin(name)then
        say('Наказание отменено: игрок — администратор или лидер из чекера.');return
    end
    enqueue({kind = kind, id = id, byName=id==nil, name = name, amount = amount, reason = trim(reason)})
end
local function answerFamily(recipient, subject, guard, delay)
    if not enabled or not integration.featureAllowed() then return false end
    recipient=tonumber(recipient)
    subject=integration.service('family_question.lua').target(subject)
    if not subject then return false end
    local recipientName=nickname(recipient)
    if not recipientName then return false end
    local id=subject:match('^%d+$') and tonumber(subject) or nil
    local name=id and nickname(id) or subject
    if id and not name then return false end
    return enqueue({kind='answer',id=id,name=name,recipient=recipient,recipientName=recipientName,guard=guard,notBefore=now()+math.max(0,tonumber(delay) or 0)})==true
end
local function validAnswer(job)
    return (not job.id or nickname(job.id)==job.name)
        and nickname(job.recipient)==job.recipientName and (not job.guard or job.guard())
end
local function fama(raw)
    local recipient,subject=trim(tostring(u8(raw))):match('^(%d+)%s+(.+)$')
    if not recipient or not answerFamily(recipient,subject) then
        say('Использование: /fama ID_получателя ID_игрока или Ник_Игрока. Получатель и игрок по ID должны быть в сети.')
    end
end
integration.queueSafePunishment=function(plan)
    syncAccess()
    if not enabled or not integration.featureAllowed()or not plan or plan.mode~='family' then return false end
    if not ({jail=true,mute=true,warn=true,ban=true,kick=true,skick=true,spawn=true})[plan.kind]then return false end
    return enqueue({kind=plan.kind,id=plan.target.id,byName=plan.target.id==nil,name=plan.target.name,
        amount=plan.amount and tostring(plan.amount),reason=plan.reason,strictFamily=true,requestOnly=plan.requestOnly==true})==true
end
integration.answerFamily=answerFamily
local function finish(job, value)
    syncAccess()
    if job.cancelled or job.accessRevision ~= accessRevision then return end
    if not integration.access:require(1, say) then return end
    if job.kind == 'answer' then
        if not validAnswer(job) then
            say('Ответ отменён: игрок или получатель вышел либо сменил ник.'); return
        end
        local displayFamily = trim(value:gsub('[%[%]]', ''))
        local noFamily = {['Нет'] = true, ['нет'] = true, ['НЕТ'] = true,
            ['-'] = true, ['—'] = true, ['Не состоит'] = true, ['не состоит'] = true,
            ['Не состоит в семье'] = true, ['не состоит в семье'] = true,
            ['Отсутствует'] = true, ['отсутствует'] = true}
        local message = '/ans ' .. job.recipient .. ' Игрок ' .. job.name:gsub('_', ' ') ..
            (noFamily[displayFamily] and ' не состоит в семье.' or ' состоит в семье ' .. displayFamily .. '.')
        if #u8:decode(message) > 144 then say('Ответ отменён: сообщение превышает ограничение чата (144 байта).'); return end
        send(message)
        return
    end
    if not enabled then return end
    if job.kind == 'view' then
        if watching and target == job.id and nickname(job.id) == job.name then family = value end
        return
    end
    if not job.byName and nickname(job.id) ~= job.name then say('Наказание отменено: игрок вышел или ID занят другим игроком.'); return end
    if (job.kind=='ban'or job.kind=='warn')and integration.isKnownAdmin(job.name)then
        say('Наказание отменено: игрок — администратор или лидер из чекера.');return
    end
    local targetId=job.id
    if job.byName then
        targetId=nil
        for candidate=0,sampGetMaxPlayerId(false)do
            local name=nickname(candidate)
            if name and name:lower()==job.name:lower()then targetId=candidate;break end
        end
    end
    local adminLevel = integration.adminLevel()
    if not adminLevel or adminLevel < 1 then say('Наказание отменено: уровень администратора не подтверждён.'); return end
    if job.strictFamily then
        local f=trim(value:gsub('[%[%]]',''))
        if f==''or f=='-'or f=='—'or f:lower()=='none'or f=='Нет'or f=='нет'or f=='НЕТ'or f=='Отсутствует'or f=='отсутствует'or f:find('Не состоит',1,true)or f:find('не состоит',1,true)then
            say('Выдача отменена: у игрока нет семьи. Выберите режим «Игрок».');return
        end
        if not targetId and not ({jail=true,mute=true,warn=true,ban=true})[job.kind]then
            say('Выдача отменена: игрок вышел, офлайн-команды для этого наказания нет.');return
        end
    end
    local punishment='/'..(targetId and job.kind or 'off'..job.kind)
    local requestOnly = not integration.access:can(integration.commandMinimum(punishment))
    if job.strictFamily then requestOnly=requestOnly or job.requestOnly or not integration.access:can(integration.commandMinimum('/msg'))end
    local reason = job.reason .. (requestOnly and ' (' .. value .. ')' or ' [' .. value .. ']')
    local command = '/' .. (targetId and job.kind or 'off'..job.kind) .. ' ' .. tostring(targetId or job.name) .. ' ' .. (job.amount and job.amount .. ' ' or '') .. reason
    if job.kind=='spawn' then command='/spawn '..tostring(targetId)end
    local displayName = job.name:gsub('_', ' ')
    local displayFamily = value:gsub('[%[%]]', '')
    local description = 'Член семьи ' .. displayFamily .. ' ' .. displayName
    if job.kind == 'jail' then description = description .. ' отправлен в тюрьму'
    elseif job.kind == 'ban' then description = description .. ' заблокирован'
    elseif job.kind=='mute' then description=description..' получил мут'
    elseif job.kind=='kick'or job.kind=='skick'then description=description..' исключён с сервера'
    elseif job.kind=='spawn'then description=description..' отправлен на спавн'
    else description = description .. ' получил предупреждение' end
    local message = '/msg ' .. punishmentChannel() .. ' ' .. description .. '. Причина: ' .. job.reason
    if requestOnly then
        command = '/a ' .. command
        message = (job.strictFamily or job.kind == 'jail') and '/a /msg ' .. punishmentChannel() .. ' ' .. description .. '. Причина: ' .. job.reason or nil
    end
    -- SA-MP command payload must fit without silently truncating the family.
    if #u8:decode(command) > 144 or (message and #u8:decode(message) > 144) then
        say('Наказание отменено: команда или уведомление превышает 144 байта. Нужна более короткая причина.'); return
    end
    local issuedGeneration = generation
    if send(command)==false then return end
    wait(650)
    syncAccess()
    if message and enabled and generation == issuedGeneration and integration.access:can(job.strictFamily and requestOnly and 1 or 4) then send(message) end
end

local function toggle()
    enabled = not enabled
    generation = generation + 1
    family = nil
    for i = #queue, 1, -1 do
        if queue[i].kind ~= 'answer' then table.remove(queue, i) end
    end
    -- Drain an already sent /offst, but never execute its cancelled punishment.
    if pending and pending.kind ~= 'answer' then pending.cancelled = true end
    if enabled and watching and target then
        local id = target
        target = nil
        observe(id)
    end
    say(enabled and 'Работа с семьями включена.' or 'Работа с семьями выключена.')
end

function events.onShowDialog(id, style, title, b1, b2, text)
    syncAccess()
    if not pending or pending.result or id ~= 0 or style ~= 0 then return end
    if clean(tostring(u8(title))) ~= 'Оффлайн статистика игрока' then return end
    local name, found
    for line in tostring(u8(text)):gmatch('[^\r\n]+') do
        local key, value = clean(line):match('^([^:]+):%s*(.*)$')
        if key == 'Имя' then name = trim(value) end
        if key == 'Семья' then found = trim(value) end
    end
    if not sameAccountName(name, pending.name) then return end
    pending.result = {family = found and found~='' and found or (pending.kind=='answer' and 'Нет' or nil)}
    -- Close only our matched response, from the main coroutine.
    return false
end
function events.onTogglePlayerSpectating(state)
    watching = state == true or state == 1
    if not watching then
        target, family, header = nil, nil, nil
        for i = #queue, 1, -1 do if queue[i].kind == 'view' then table.remove(queue, i) end end
    end
end
function events.onSpectatePlayer(id) observe(id) end
function events.onSpectateVehicle()
    if header and now() - header.time < 3 then observe(header.id)
    else watching, target, family = true, nil, nil end
end
function events.onServerMessage(color, text)
    syncAccess()
    local line = clean(tostring(u8(text)))
    if replies.main.enabled and enabled and integration.access:can(1) and color==replies.main.color and replyReady() then
        local recipient,question=integration.service('report_reader.lua').parse(tostring(u8(text)))
        local subject=question and keywordParser.parse(question,keywords)
        local found,selfID=sampGetPlayerIdByCharHandle(PLAYER_PED)
        local key=recipient and subject and (recipient..'|'..subject:lower())
        if key and (not found or recipient~=selfID) and (not replyRecent[key] or now()-replyRecent[key]>=replies.main.cooldown) then
            local token=replyGeneration
            local guard=function()return token==replyGeneration and replies.main.enabled and enabled and replyReady() end
            if answerFamily(recipient,subject,guard,replies.main.delay) then replyRecent[key]=now() end
        end
    end

    local name, id = line:match('^%[SP%]%s+([^%[%]]+)%[(%d+)%]%s*|')
    id = tonumber(id)
    if id and sameAccountName(nickname(id), name) then
        header = {id = id, time = now()}
        observe(id)
    end
end
function events.onInitGame()
    enabled = integration.featureAllowed()
    accessRevision = integration.access:revision()
    generation = generation + 1
    queue, pending, target, family, header = {}, nil, nil, nil, nil
    watching, nextRequest = false, 0
    replyGeneration=replyGeneration+1;replyRecent={};replyAway=true
end
events.onConnectionLost = events.onInitGame
events.onConnectionClosed = events.onInitGame
function events.onSendCommand(command)
    if internal then return end
    if pending and command:lower():match('^/offst%s') then
        say('Статистика уже запрошена. Следующий запрос доступен после получения ответа.'); return false
    end
end
function events.onPlayerQuit(id)
    if target == id then target, family = nil, nil end
    if header and header.id == id then header = nil end
end
local function drawFamily()
    if not enabled or not watching or not family then return end
    -- Native GTA SA font 3 (Pricedown), with black outline, centered at the top.
    local label = u8:decode(family):gsub('~', '')
    useRenderCommands(true)
    setGxtEntry('FAMHUD', label)
    setTextProportional(true)
    setTextJustify(false)
    setTextWrapx(640.0)
    setTextFont(3)
    setTextScale(0.7, 1.5)
    setTextColour(244, 197, 66, 255)
    setTextEdge(2, 0, 0, 0, 255)
    setTextCentre(true)
    displayText(320.0, 25.0, 'FAMHUD')
end
function integration.start()
    repeat wait(100) until isSampAvailable()
    sampRegisterChatCommand('fama', fama)
    sampRegisterChatCommand('fj', function(a) punish('jail', a) end)
    sampRegisterChatCommand('fw', function(a) punish('warn', a) end)
    sampRegisterChatCommand('fb', function(a) punish('ban', a) end)
    lua_thread.create(function()
        while true do wait(0); if isSampAvailable() then drawFamily() end end
    end)
    while true do
        wait(0)
        syncAccess()
        replyReady()
        for k,t in pairs(replyRecent) do if now()-t>3600 then replyRecent[k]=nil end end
        if not isSampAvailable() then
            enabled = integration.featureAllowed()
            generation = generation + 1
            queue, pending, target, family, header = {}, nil, nil, nil, nil
            watching, nextRequest = false, 0
        elseif pending then
            if pending.result then
                local job = pending
                pending = nil
                sampSendDialogResponse(0, 0, 0, '')
                nextRequest = now() + GAP
                if not job.cancelled and enabled then
                    if job.result.family then finish(job, job.result.family)
                    else say('Запрос отменён: в статистике ' .. job.name .. ' нет сведений о семье.') end
                end
            elseif now() - pending.started > TIMEOUT then
                if not pending.cancelled then say('Запрос отменён: статистика ' .. pending.name .. ' не получена за 8 секунд.') end
                pending, nextRequest = nil, now() + GAP
            end
        elseif #queue > 0 and now() >= nextRequest and now()>=(queue[1].notBefore or 0) and not sampIsDialogActive() and not integration.queryBusy('offst') then
            local job = table.remove(queue, 1)
            if job.accessRevision == accessRevision and integration.access:can(1)
                and enabled and (job.kind=='answer' and validAnswer(job) or job.kind~='answer' and (job.byName or nickname(job.id)==job.name)) then
                pending = job
                job.started = now()
                send('/offst ' .. job.name)
            elseif job.kind ~= 'view' then say('Запрос отменён: игрок вышел, сменил ник или функция выключена.') end
        end
    end
end

integration.onDisconnect = events.onInitGame
integration.queryPending = function(kind) return kind=='offst' and pending~=nil end
integration.draw = function()
    local imgui = require('imgui')
    local columns = integration.layout.begin('families_summary', 680)
    integration.layout.heading('В наблюдении')
    local name = target and nickname(target)
    imgui.TextWrapped(name and (name .. ' [' .. target .. ']') or 'Игрок не выбран')
    imgui.TextWrapped(family and ('Семья: ' .. family) or
        (pending and 'Получаем сведения о семье…' or 'Семья появится при наблюдении за игроком.'))
    if #queue > 0 then imgui.Text('Запросов в очереди: ' .. #queue) end
    integration.layout.next(columns)
    local ui=integration.service('dossier_ui.lua').new(imgui,integration)
    ui.table('family_commands','СЕМЕЙНЫЕ КОМАНДЫ',{
        {label='Команда',weight=.28},{label='Назначение',weight=.72}
    },{
        {{text='/fj',tone='accent'},'Заключить в тюрьму'},
        {{text='/fw',tone='accent'},'Выдать предупреждение'},
        {{text='/fb',tone='accent'},'Заблокировать аккаунт'},
        {{text='/fama',tone='accent'},'Сообщить игроку название семьи'}
    })
    local pos=ui.cursor()
    local width=imgui.GetContentRegionAvailWidth()
    local inner=math.max(1,width-28)
    local notes={
        {'ID или ник','Для наказания укажите ID или ник игрока. Офлайн-команда выбирается автоматически.'},
        {'Семья в причине','Название семьи добавляется к причине наказания автоматически.'}
    }
    local height=24
    for _,note in ipairs(notes)do height=height+ui.measure(note[1],inner,13,true)+4+ui.measure(note[2],inner,13)+12 end
    ui.rect(pos.x,pos.y,width,height,integration.palette.surface,8,.96)
    ui.rect(pos.x,pos.y+12,3,height-24,'accent',1)
    local y=pos.y+12
    for _,note in ipairs(notes)do
        y=y+ui.text(pos.x+14,y,inner,note[1],'accent',13,true)+4
        y=y+ui.text(pos.x+14,y,inner,note[2],'muted',13)+12
    end
    ui.finish(pos.x,pos.y,width,height)
    if imgui.Button('Синтаксис и примеры##familia_help',imgui.ImVec2(width,0)) then integration.openHelp('families') end
    integration.layout.finish(columns)
end

integration.drawSettings = function()
    local imgui = require('imgui')
    imgui.TextWrapped('Общий переключатель включает название семьи в наблюдении и семейные команды. Параметры контроля аптечек — ниже.')
    if integration.access:can(4) then
    local channels={0,1,300}
    local selected=imgui.ImInt(punishmentChannel()==0 and 0 or punishmentChannel()==1 and 1 or 2)
    if imgui.Combo('Сообщения о наказаниях членов семьи',selected,'/msg 0\0/msg 1\0/msg 300\0\0')then
        punishment.main.channel=channels[selected.v+1] or 300
        integration.storage:saveIni(punishment,punishmentPath)
    end
    end
    local opts=integration.service('combo_settings.lua')
    local changed=opts.toggle(imgui,'Отвечать на вопросы о семье',replies.main,'enabled')
    
    imgui.PushItemWidth(130)
    changed=opts.integer(imgui,'Задержка ответа, сек.',replies.main,'delay',2,0,300) or changed
    changed=opts.integer(imgui,'Интервал повтора, сек.',replies.main,'cooldown',15,1,3600) or changed
    changed=opts.integer(imgui,'Задержка после AFK, сек.',replies.main,'return_delay',15,0,600) or changed
    imgui.PopItemWidth()
    imgui.Separator()
    imgui.Text('Ключевые слова и фразы')
    imgui.TextWrapped('Вопрос: ID или ник, затем одна из фраз ниже. Например: 57 фама. Регистр не важен. Пустой список отключает распознавание вопросов.')
    local keywordsChanged=false
    for i,word in ipairs(keywords)do
        keywordBuffers[i]=keywordBuffers[i]or imgui.ImBuffer(word,256)
        imgui.PushItemWidth(math.max(80,imgui.GetContentRegionAvailWidth()-110))
        if imgui.InputText('##family_keyword_'..i,keywordBuffers[i])then keywords[i]=keywordBuffers[i].v;keywordsChanged=true end
        imgui.PopItemWidth();imgui.SameLine()
        if imgui.Button('Удалить##family_keyword_delete_'..i)then
            table.remove(keywords,i);keywordBuffers={};keywordsChanged=true;break
        end
    end
    if #keywords<100 and imgui.Button('Добавить фразу##family_keyword_add')then
        keywords[#keywords+1]='';keywordsChanged=true
    end
    if keywordsChanged then
        local data={main={count=#keywords},words={}}
        for i,word in ipairs(keywords)do data.words['word'..i]=word end
        integration.storage:saveIni(data,keywordPath)
        replyGeneration=replyGeneration+1;replyRecent={}
    end
    if changed then replyGeneration=replyGeneration+1;integration.storage:saveIni(replies,replyPath) end
end

integration.setEnabled=function(value) if enabled~=value then toggle() end end

    end
    sources["modules/family_mask_warning.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/family_mask_warning.lua
-- Original third-party credits, where present, are retained below.
local g=require('imgui');local u8=require('encoding').UTF8
local path=integration.storage:path('settings','family-mask-warning.ini')
local cfg=integration.storage:loadIni({main={enabled=false}},path)
local nextScan=0
integration.update=function()
    if not cfg.main.enabled or not integration.access:can(1) or sampGetGamestate()~=3 then return end
    local now=getGameTimer();if now<nextScan then return end
    nextScan=now+5000
    local maxId=sampGetMaxPlayerId(false)
    for id=0,maxId do
        if sampIsPlayerConnected(id) then
            local found,ped=sampGetCharHandleBySampPlayerId(id)
            if found and ped and ped~=0 and ped~=PLAYER_PED and doesCharExist(ped) then
                local color=integration.originalPlayerColor(id,sampGetPlayerColor(id))
                if integration.isMaskColor(color) then
                    integration.message('Внимание! В зоне прорисовки '..tostring(u8(sampGetPlayerNickname(id)))..'['..id..'] в маске.')
                end
            end
        end
    end
end
integration.draw=function()
    local enabled=g.ImBool(cfg.main.enabled)
    if g.Checkbox('Предупреждать об игроках в маске каждые 5 секунд',enabled) then
        cfg.main.enabled=enabled.v;nextScan=0;integration.storage:saveIni(cfg,path)
    end
end
integration.stop=function()nextScan=0 end
integration.onDisconnect=integration.stop
integration.onAccessChanged=integration.stop

    end
    sources["modules/family_registry.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/family_registry.lua
-- Original third-party credits, where present, are retained below.
local g=require('imgui')
local u8=require('encoding').UTF8
local bit=require('bit')
local events=require('lib.samp.events')
local path=integration.storage:path('data','family-registry.ini')
local cfg=integration.storage:loadIni({main={count=0,enabled=true,style=0}},path)
local input=g.ImBuffer('',128)
local lookup={}
local function save()integration.storage:saveIni(cfg,path)end
local function rebuild()
 lookup={}
 for i=1,cfg.main.count do
  local e=cfg['family'..i]
  if e then for nick in tostring(e.members or ''):gmatch('[^|]+')do
   local old=lookup[nick:lower()]
   if not old or (tonumber(e.updated)or 0)>(tonumber(old.updated)or 0)then lookup[nick:lower()]=e end
  end end
 end
end
rebuild()
local scan=integration.service('family_roster.lua').new({
 now=getGameTimer,
 ready=function()return integration.featureAllowed()and integration.access:can(4)and sampGetGamestate()==3 end,
 dialogOpen=function()return sampIsDialogActive()end,
 send=function(s)return sampSendChat(u8:decode(s))end,
 respond=function(id,b,row)return sampSendDialogResponse(id,b,row,'')end,
 commit=function(key,names)
  if key=='current_unknown'then
   local found
   for i=1,cfg.main.count do if cfg['family'..i].unknown==true then found='family'..i;break end end
   if not found then cfg.main.count=cfg.main.count+1;found='family'..cfg.main.count;cfg[found]={name='Неизвестная семья',unknown=true,color=0xFFB995FF}end
   key=found
  end
  if cfg[key]then cfg[key].members=table.concat(names,'|');cfg[key].updated=os.time();save();rebuild()end
 end
})
integration.busy=function()return scan.active end
integration.queryPending=function()return scan.active end
integration.update=function()scan:tick()end
integration.stop=function()scan:cancel('Проверка прервана',true)end
integration.onDisconnect=integration.stop
function events.onServerMessage(color,text)
 if not scan.active then return end
 local line=integration.service('family_roster.lua').clean(u8(text))
 local nick,id,name=line:match('^%[A%]%s+([%w_]+)%[(%d+)%]%s+на время вступил в семью "([^"]+)"')
 local ok,localId=sampGetPlayerIdByCharHandle(PLAYER_PED)
 if ok and tonumber(id)==localId and nick==sampGetPlayerNickname(localId)then scan:joined(name)end
end
function events.onShowDialog(id,style,title,b1,b2,body)
 return scan:dialog(id,style,u8(title),u8(b1),u8(b2),u8(body))
end
function events.onSendCommand(command)
 if not scan.active or integration.commandOwner()=='family_registry'then return end
 local cmd=tostring(command):lower():match('^/([%w_]+)')
 if cmd=='family'or cmd=='tempfamily'then
  integration.message('Сначала остановите проверку реестра семей.');return false
 end
end
integration.startScan=function()
   if integration.queryBusy('family')then integration.message('Дождитесь завершения текущего запроса.')
   else
    local entries={};for i=1,cfg.main.count do if cfg['family'..i].unknown~=true then entries[#entries+1]={key='family'..i,name=cfg['family'..i].name}end end
    if not scan:start(entries)then integration.message('Добавьте семьи в реестр и войдите в игру.')end
   end
end
integration.scanCurrent=function()
 if integration.queryBusy('family')then integration.message('Дождитесь завершения текущего запроса.');return end
 if not scan:start({{key='current_unknown',name='Неизвестная семья'}},true)then integration.message('Войдите в игру и включите раздел семей.')end
end
integration.draw=function()
 g.Text('Реестр семей')
 if not integration.access:can(4)then g.TextDisabled('Проверка составов доступна с 4 уровня');return end
 g.InputText('Название семьи##registry_name',input)
 if g.Button('Добавить семью')and not scan.active then
  local name=tostring(input.v):match('^%s*(.-)%s*$');local exists=false
  for i=1,cfg.main.count do if cfg['family'..i].name:lower()==name:lower()then exists=true end end
  if name~=''and not name:find('[%z\1-\31]')and #u8:decode('/tempfamily '..name)<=144 and not exists and cfg.main.count<100 then
   cfg.main.count=cfg.main.count+1;cfg['family'..cfg.main.count]={name=name,color=0xFFB995FF,members='',updated=0};input.v='';save()
  end
 end
 local enabled=g.ImBool(cfg.main.enabled)
 if g.Checkbox('Подсвечивать персонажей семей',enabled)then cfg.main.enabled=enabled.v;save()end
 local style=g.ImInt(cfg.main.style)
 if g.Combo('Вид подсветки',style,{'Силуэт','Контур'},2)then cfg.main.style=style.v;save()end
 if not scan.active then
  if g.Button('Проверить составы всех семей')then
   integration.startScan()
  end
  if g.Button('Проверить текущую семью')then integration.scanCurrent()end
 else if g.Button(scan.currentOnly and 'Остановить проверку'or 'Остановить и выйти из временной семьи')then scan:cancel()end end
 g.TextWrapped(scan:progress())
 for i=1,cfg.main.count do
  local key='family'..i;local e=cfg[key]
  if g.CollapsingHeader(e.name..'##registry_'..i)then
   local color=tonumber(e.color)or 0xFFB995FF
   local ref=g.ImFloat4(g.ImColor(bit.band(bit.rshift(color,16),255),bit.band(bit.rshift(color,8),255),bit.band(color,255),255):GetFloat4())
   if g.ColorEdit4('Цвет##family_'..i,ref)then
    e.color=bit.bor(0xFF000000,bit.lshift(math.floor(ref.v[1]*255),16),bit.lshift(math.floor(ref.v[2]*255),8),math.floor(ref.v[3]*255));save()
   end
   local members={};for name in tostring(e.members):gmatch('[^|]+')do members[#members+1]=name end
   g.Text('Участников: '..#members)
   g.Text('Обновлено: '..((tonumber(e.updated)or 0)>0 and os.date('%d.%m.%Y %H:%M',e.updated)or 'ещё не проверено'))
   if g.Button('Удалить##registry_'..i)and not scan.active then
    for j=i,cfg.main.count-1 do cfg['family'..j]=cfg['family'..(j+1)]end
    cfg['family'..cfg.main.count]=nil;cfg.main.count=cfg.main.count-1;save();rebuild();break
   end
   for _,name in ipairs(members)do g.Text(name)end
  end
 end
end
integration.memberColor=function(nick)
 if not cfg.main.enabled then return end
 local e=lookup[tostring(nick):lower()]
 return e and tonumber(e.color),cfg.main.style
end

integration.hudActive=function()return cfg.main.enabled and integration.featureAllowed()and not integration.layoutEditing(),false,false end
integration.drawHud=function()
 if not integration.hudActive()or sampGetGamestate()~=3 or not isGameWindowForeground()or isPauseMenuActive()then return end
 local general,priority=integration.generalHighlight()
 if general and priority==1 then return end
 local render=integration.service('family_highlight.lua')
 local sw,sh=getScreenResolution()
 render.frame(g,sw,sh,function(drawList)
 for id=0,sampGetMaxPlayerId(false)do
  if sampIsPlayerConnected(id)then
   local color,style=integration.memberColor(sampGetPlayerNickname(id))
   if color then
    local ok,ped=sampGetCharHandleBySampPlayerId(id)
    if ok and doesCharExist(ped)then
     local points=integration.familyBones(ped)
     if points then
      local r=bit.band(bit.rshift(color,16),255);local green=bit.band(bit.rshift(color,8),255);local b=bit.band(color,255)
      local abgr=bit.bor(bit.lshift(style==0 and 85 or 220,24),bit.lshift(b,16),bit.lshift(green,8),r)
      render.draw(g,points,abgr,style,drawList)
     end
    end
   end
  end
 end
 end)
end

    end
