-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/family_weapon_warning.lua
-- Original third-party credits, where present, are retained below.
local g=require('imgui');local u8=require('encoding').UTF8
local events=require('lib.samp.events')
local path=integration.storage:path('settings','family-weapon-warning.ini')
local cfg=integration.storage:loadIni({main={enabled=false}},path)
local names={[33]='Rifle',[34]='Sniper Rifle'}
local recent,nextScan={},0
local function enabled()
    return cfg.main.enabled and integration.preferences.data.main.families
        and integration.access:can(1) and sampGetGamestate()==3
end
local function streamed(id)
    if not sampIsPlayerConnected(id) then return end
    local found,ped=sampGetCharHandleBySampPlayerId(id)
    if found and ped and ped~=0 and ped~=PLAYER_PED and doesCharExist(ped) then return ped end
end
local function warn(id,weapon,shot)
    weapon=tonumber(weapon)
    if not names[weapon] or not streamed(id) then return end
    local nick=sampGetPlayerNickname(id);local now=getGameTimer();local old=recent[id]
    if old and old.nick==nick and now>=old.time and now-old.time<5000 then return end
    recent[id]={nick=nick,time=now}
    integration.message('Внимание! В зоне прорисовки '..tostring(u8(nick))..'['..id..'] '..
        (shot and 'выстрелил из запрещённого оружия: ' or 'держит запрещённое оружие: ')..names[weapon]..'.')
end
function events.onBulletSync(id,data)
    if enabled() and type(data)=='table' then warn(id,data.weaponId,true) end
end
function events.onPlayerQuit(id)recent[id]=nil end
integration.update=function()
    if not enabled() then return end
    local now=getGameTimer();if now<nextScan then return end;nextScan=now+200
    for id in pairs(recent)do if not streamed(id)then recent[id]=nil end end
    for id=0,sampGetMaxPlayerId(false)do
        local ped=streamed(id)
        if ped then warn(id,getCurrentCharWeapon(ped),false) end
    end
end
integration.draw=function()
    local value=g.ImBool(cfg.main.enabled)
    if g.Checkbox('Предупреждать о Rifle / Sniper Rifle каждые 5 секунд',value)then
        cfg.main.enabled=value.v;recent={};nextScan=0;integration.storage:saveIni(cfg,path)
    end
end
integration.stop=function()recent={};nextScan=0 end
integration.onDisconnect=integration.stop;integration.onAccessChanged=integration.stop

    end
