-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/fisheye.lua
-- Original third-party credits, where present, are retained below.
-- Adapted from FishEyeEffect; no separate command or render loop.
local applied=false
local function restore()
    if applied then cameraSetLerpFov(70.0,70.0,1000,1);applied=false end
end
integration.update=function()
    local p=integration.preferences.data.main
    if not p.fishEye or sampGetGamestate()~=3 or not doesCharExist(PLAYER_PED) then restore();return end
    -- Keep the source's normal sniper aiming view.
    if isCurrentCharWeapon(PLAYER_PED,34) and isKeyDown(2) then restore();return end
    cameraSetLerpFov(p.fishEyeAngle,p.fishEyeAngle,1000,1)
    applied=true
end
integration.onDisconnect=restore
integration.stop=restore
integration.drawSettings=function()
    local g=require('imgui')
    local p=integration.preferences.data.main
    local enabled=g.ImBool(p.fishEye)
    if g.Checkbox('Рыбий глаз',enabled) then p.fishEye=enabled.v;integration.preferences:save();if not p.fishEye then restore() end end
    g.SameLine();g.PushItemWidth(85)
    local angle=g.ImInt(p.fishEyeAngle)
    if g.InputInt('##fish_eye_angle',angle,0,0) then p.fishEyeAngle=angle.v;integration.preferences:save() end
    g.PopItemWidth();g.SameLine();g.Text('°')
end

