-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/fogdist.lua
-- Original third-party credits, where present, are retained below.
-- FogDist: reversible patches, applied only while enabled.
local g=require('imgui')
local memory=require('memory')
local cfg,path=integration.service('combo_settings.lua').load(integration,'fogdist',{main={enabled=false,distance=1200}})
local original=nil
local function restore()
    if not original then return end
    for address,value in pairs(original.bytes)do if memory.getuint8(address)==0xEB then memory.setuint8(address,value,true)end end
    memory.setfloat(0xB7C4F0,original.distance,false);original=nil
end
integration.stop=restore;integration.onDisconnect=restore
integration.update=function()
    if not cfg.main.enabled or sampGetGamestate()~=3 then restore();return end
    if not original then
        local bytes={};for _,address in ipairs({0x5609FF,0x561344})do
            local value=memory.getuint8(address)
            if value~=0xEB and (value<0x70 or value>0x7F)then
                cfg.main.enabled=false;integration.message('Дальность прорисовки: версия кода игры не поддерживается.');return
            end
            bytes[address]=value
        end
        original={bytes=bytes,distance=memory.getfloat(0xB7C4F0)}
        for address in pairs(bytes)do memory.setuint8(address,0xEB,true)end
    end
    memory.setfloat(0xB7C4F0,math.max(0,math.min(3600,tonumber(cfg.main.distance)or 1200)),false)
end
integration.drawSettings=function()
    local enabled=g.ImBool(cfg.main.enabled)
    if g.Checkbox('Дальность прорисовки',enabled)then cfg.main.enabled=enabled.v;if not enabled.v then restore()end;integration.storage:saveIni(cfg,path)end
    g.SameLine();g.PushItemWidth(100);local distance=g.ImInt(cfg.main.distance)
    if g.InputInt('##fog_distance',distance,0,0)then cfg.main.distance=math.max(0,math.min(3600,distance.v));integration.storage:saveIni(cfg,path)end
    g.PopItemWidth();g.SameLine();g.Text('м')
end

    end
    sources["modules/gang.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/gang.lua
-- Original third-party credits, where present, are retained below.
-- CasualAT module. Author: Casual Alvarez. Original source: integration/sources.
require "lib.moonloader"
require "lib.sampfuncs"

local encoding = require "encoding"
local bit = require "bit"
local imgui = require "imgui"
local storage = integration.storage
local CONFIG = storage:path('settings', 'gangs.ini')
local preferences = storage:loadIni({features={enabled=false}}, CONFIG)

encoding.default = "CP1251"
local u8 = encoding.UTF8

local PREFIX = "{F4C542}[X-Tools]{FFFFFF} "

local GANG_BY_COLOR = {
    [-3407617] = "BALLAS",
    [-16738048] = "GROVE",
    [-13056] = "VAGOS",
    [-10066177] = "RIFA",
    [-16724737] = "AZTEC"
}

local function utf8_to_cp1251(text)
    return u8:decode(tostring(text or ""))
end

local function trim(text)
    return tostring(text or ""):match("^%s*(.-)%s*$")
end

local function msg(text, color)
    sampAddChatMessage(utf8_to_cp1251(PREFIX .. text), color or -1)
end

local function feature_enabled()
    if preferences.features.enabled then return true end
    msg('Команды /gw, /gb и /gj выключены. Включите их: Настройки → Банды.', 0xAAAAAA)
    return false
end

local function process_command(command_utf8)
    if not integration.access:require(1, msg) then return false end
    local request = not integration.access:can(integration.commandMinimum(command_utf8))
    local outgoing = (request and '/a ' or '') .. command_utf8
    local ok, result = pcall(sampProcessChatInput, utf8_to_cp1251(outgoing))
    if not ok or result == false then return false end
    msg((request and 'Запрос отправлен: ' or 'Команда отправлена: ') .. outgoing, 0x99FF99)
    return true
end

local function get_player_gang(player_id)
    if not sampIsPlayerConnected(player_id) then
        return nil, "Игрок с указанным ID не в сети."
    end

    local ok, color = pcall(sampGetPlayerColor, player_id)
    if not ok or not color then
        return nil, "Не удалось определить банду по цвету ника."
    end

    return GANG_BY_COLOR[bit.tobit(color)]
end

local function build_warn_command(player_id)
    local gang, err = get_player_gang(player_id)
    if err then
        return nil, err
    end

    if gang then
        return string.format("/warn %d Нарушение правил /capture [%s]", player_id, gang)
    end

    return string.format("/warn %d Нарушение правил /capture", player_id)
end

local function build_ban_command(player_id, days)
    local gang, err = get_player_gang(player_id)
    if err then
        return nil, err
    end

    if gang then
        return string.format("/ban %d %d Использование читов [%s]", player_id, days, gang)
    end

    return string.format("/ban %d %d Использование читов", player_id, days)
end

local function handle_gw_command(params)
    if not feature_enabled() then return end
    local player_id = tonumber(trim(params):match("^(%d+)$"))
    if not player_id then
        msg("Предупреждение за нарушение правил капта: /gw ID", 0xAAAAAA)
        return
    end

    local command, err = build_warn_command(player_id)
    if not command then
        msg(err, 0xFF6666)
        return
    end

    process_command(command)
end

local function handle_gb_command(params)
    if not feature_enabled() then return end
    local player_id, days = trim(params):match("^(%d+)%s+(%d+)$")
    player_id = tonumber(player_id)
    days = tonumber(days)

    if not player_id or not days or days < 1 then
        msg("Блокировка за использование читов: /gb ID дни (не менее 1 дня).", 0xAAAAAA)
        return
    end

    local command, err = build_ban_command(player_id, days)
    if not command then
        msg(err, 0xFF6666)
        return
    end

    process_command(command)
end

local function handle_gj_command(params)
    if not feature_enabled() then return end
    local id,minutes,reason=trim(u8(params or '')):match('^(%d+)%s+(%d+)%s*(.*)$')
    id,minutes=tonumber(id),tonumber(minutes)
    if not id or not minutes or minutes<1 then
        msg('Использование: /gj ID минуты [причина]');return
    end
    local gang,err=get_player_gang(id)
    if err then msg(err);return end
    reason=trim(reason)
    if reason=='' then reason='Нарушение правил /capture' end
    local command=string.format('/jail %d %d %s%s',id,minutes,reason,gang and (' ['..gang..']') or '')
    if #utf8_to_cp1251(command)>141 then msg('Причина слишком длинная.');return end
    process_command(command)
end

integration.drawSettings = function()
    local value = imgui.ImBool(preferences.features.enabled)
    if imgui.Checkbox('Включить работу с бандами##gang_enabled', value) then
        preferences.features.enabled = value.v
        assert(storage:saveIni(preferences, CONFIG))
    end
    imgui.TextWrapped('Разрешить команды /gw, /gb и /gj для наказаний на каптах. Изменение сохраняется автоматически.')
    imgui.TextWrapped('Jail — со 2 уровня, warn и ban — с 3. Если прав недостаточно, отправляется просьба через /a.')
    imgui.TextWrapped('/gj ID минуты [причина] — тюрьма; по умолчанию нарушение правил капта.')
    imgui.Spacing()
    imgui.TextWrapped('/gw ID — предупреждение за нарушение правил капта.')
    imgui.TextWrapped('/gb ID дни — блокировка за использование читов.')
    imgui.TextWrapped('Если банда определена по цвету ника, её название добавляется к причине наказания.')
end

integration.status = function()
    return {enabled=preferences.features.enabled}
end

function integration.start()
    repeat
        wait(100)
    until isSampAvailable()

    sampRegisterChatCommand("gw", handle_gw_command)
    sampRegisterChatCommand("gb", handle_gb_command)
    sampRegisterChatCommand("gj", handle_gj_command)


    while true do
        wait(0)
    end
end

    end
    sources["modules/glass_scoreboard.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/glass_scoreboard.lua
-- Original third-party credits, where present, are retained below.
-- Glass Scoreboard: shared-context port, replaces the old ADM-Tab renderer.
local g=require('imgui');local u8=require('encoding').UTF8;local bit=require('bit')
local path=integration.storage:path('settings','glass-scoreboard.ini')
local legacy=integration.storage:loadIni({main={enabled=false}},integration.storage:path('settings','adm-tab.ini'))
local cfg=integration.storage:loadIni({main={enabled=legacy.main.enabled,hold=true,scroll=true,pos=2}},path)
local visible,alpha,pressedAt=false,0,nil
local searchFocused=false
local players,selected={},nil
local search=g.ImBuffer('',128);local lastRefresh=-10000;local targetScroll=nil
local function save()integration.storage:saveIni(cfg,path)end
local function allowed()return sampGetGamestate()==3 and isGameWindowForeground()and not isPauseMenuActive()and not sampIsChatInputActive()and not sampIsDialogActive()end
local function refresh()
    players={};local ok,me=sampGetPlayerIdByCharHandle(PLAYER_PED)
    for id=0,1003 do
        if (ok and id==me) or sampIsPlayerConnected(id)then players[#players+1]={id=id,name=tostring(u8(sampGetPlayerNickname(id))),score=sampGetPlayerScore(id),ping=sampGetPlayerPing(id),color=sampGetPlayerColor(id),self=ok and id==me}end
    end
    table.sort(players,function(a,b)if a.self~=b.self then return a.self end;return a.id<b.id end)
    lastRefresh=getGameTimer()
end
local function open(value)
    visible=value and cfg.main.enabled
    if visible then integration.closeWindow();refresh();sampToggleScoreboard(false)end
    integration.refreshInput()
end
integration.onDisconnect=function()visible=false;alpha=0;searchFocused=false;pressedAt=nil;players={};selected=nil;targetScroll=nil end
integration.stop=integration.onDisconnect
integration.onWindowMessage=function(msg,key,lp)
    if not cfg.main.enabled or not allowed()then return end
    if key==27 and visible and (msg==0x100 or msg==0x101)then consumeWindowMessage(true,false);if msg==0x101 then open(false)end;return end
    if key==9 and not integration.keys:captureActive() and (msg==0x100 or msg==0x101)then
        consumeWindowMessage(true,false)
        if msg==0x100 and bit.band(tonumber(lp)or 0,0x40000000)==0 then pressedAt=getGameTimer();open(not visible)
        elseif msg==0x101 then if cfg.main.hold and pressedAt and getGameTimer()-pressedAt>=700 then open(false)end;pressedAt=nil end
    end
end
integration.update=function()
    if not allowed()then if visible then open(false)end;return end
    if visible then sampToggleScoreboard(false);if getGameTimer()-lastRefresh>1000 then refresh()end end
end
integration.hudActive=function()return cfg.main.enabled and allowed()and not integration.windowOpen() and (visible or alpha>0.001),visible,searchFocused end
local lastFrame=nil
integration.drawHud=function()
    if not integration.hudActive()then return end
    local time=getGameTimer();local dt=lastFrame and math.min(0.1,(time-lastFrame)/1000)or 0.016;lastFrame=time
    alpha=math.max(0,math.min(1,alpha+(visible and 1 or -1)*dt/0.25))
    local sw,sh=getScreenResolution();local scale=math.max(0.8,math.min(1.15,sh/900))
    local width=math.min(600,sh*0.60,sw-32);local x=cfg.main.pos==1 and 20 or cfg.main.pos==3 and sw-width-20 or (sw-width)/2
    local rowHeight=46*scale;local font=integration.fontFace(sh>=900 and 18 or 14,false)
    local function color(rgb,a)return bit.bor(bit.band(rgb,0xFFFFFF),bit.lshift(math.floor(255*alpha*(a or 1)),24))end
    g.SetNextWindowPos(g.ImVec2(x,0),g.Cond.Always);g.SetNextWindowSize(g.ImVec2(width,sh),g.Cond.Always)
    g.PushStyleVar(g.StyleVar.Alpha,alpha);g.PushStyleVar(g.StyleVar.WindowRounding,0)
    g.PushStyleColor(g.Col.WindowBg,g.ImVec4(0.04,0.05,0.06,0.32))
    g.PushStyleColor(g.Col.ChildWindowBg,g.ImVec4(0,0,0,0))
    g.PushStyleColor(g.Col.FrameBg,g.ImVec4(0,0,0,0))
    local flags=g.WindowFlags.NoTitleBar+g.WindowFlags.NoResize+g.WindowFlags.NoMove+g.WindowFlags.NoCollapse+g.WindowFlags.NoSavedSettings
    if not visible then flags=flags+g.WindowFlags.NoInputs end
    g.Begin('TAB Жидкое стекло###xt_glass_scoreboard',g.ImBool(true),flags)
    if font then g.PushFont(font)end
    local draw=g.GetWindowDrawList();local origin=g.GetCursorScreenPos();local w=width-28
    draw:PushClipRect(g.ImVec2(0,0),g.ImVec2(sw,sh),false)
    draw:AddRectFilledMultiColor(g.ImVec2(x-90*scale,0),g.ImVec2(x,sh),0,color(0x000000,0.32),color(0x000000,0.32),0)
    draw:AddRectFilledMultiColor(g.ImVec2(x+width,0),g.ImVec2(x+width+90*scale,sh),color(0x000000,0.32),0,0,color(0x000000,0.32))
    draw:PopClipRect()
    local online=#players..' в сети';local onlineSize=g.CalcTextSize(online)
    draw:AddText(origin,color(0xCCCCCC),os.date('%H:%M:%S'))
    draw:AddText(g.ImVec2(origin.x+w-onlineSize.x,origin.y),color(0xCCCCCC),online)
    g.Dummy(g.ImVec2(w,24*scale))
    local server=tostring(u8(sampGetCurrentServerName()));local serverSize=g.CalcTextSize(server);local p=g.GetCursorScreenPos()
    draw:AddText(g.ImVec2(p.x+math.max(0,(w-serverSize.x)/2),p.y),color(0xFFFFFF),server)
    g.Dummy(g.ImVec2(w,38*scale))
    p=g.GetCursorScreenPos()
    local nameX=52*scale;local scoreX=w*0.67;local pingX=w-12*scale
    draw:AddText(g.ImVec2(p.x+12*scale,p.y),color(0xDDDDDD),'ID')
    draw:AddText(g.ImVec2(p.x+nameX,p.y),color(0xDDDDDD),'ИМЯ')
    draw:AddText(g.ImVec2(p.x+scoreX-25*scale,p.y),color(0xDDDDDD),'УРОВЕНЬ')
    local pingHeader=g.CalcTextSize('ЗАДЕРЖКА')
    draw:AddText(g.ImVec2(p.x+pingX-pingHeader.x,p.y),color(0xDDDDDD),'ЗАДЕРЖКА')
    g.Dummy(g.ImVec2(w,24*scale))
    local searchPos=g.GetCursorScreenPos()
    g.PushItemWidth(w)
    if g.InputText('##glass_search',search)then targetScroll=0 end
    searchFocused=g.IsItemActive()==true
    if search.v=='' and not searchFocused then local q=searchPos;draw:AddText(g.ImVec2(q.x+4,q.y+3),color(0xDDDDDD),'Найти игрока')end
    g.PopItemWidth();g.Separator()
    if not integration.windowOpen()then g.CaptureKeyboardFromApp(searchFocused)end
    g.BeginChild('##glass_players',g.ImVec2(w,math.max(80,sh-142*scale)),false,cfg.main.scroll and g.WindowFlags.NoScrollWithMouse or 0)
    if cfg.main.scroll then
        local wheel=tonumber(g.GetIO().MouseWheel)or 0
        if targetScroll==nil then targetScroll=g.GetScrollY()end
        if g.IsWindowHovered()and wheel~=0 then targetScroll=math.max(0,math.min(g.GetScrollMaxY(),targetScroll-wheel*rowHeight*2))end
        g.SetScrollY(g.GetScrollY()+(targetScroll-g.GetScrollY())*math.min(1,dt*14))
    end
    local query=search.v:lower()
    for _,row in ipairs(players)do
        if query==''or row.name:lower():find(query,1,true)or tostring(row.id)==query then
            local pos=g.GetCursorScreenPos();local rw=w-12;local d=g.GetWindowDrawList()
            g.InvisibleButton('##glass_player_'..row.id,g.ImVec2(rw,rowHeight))
            local hover=g.IsItemHovered();local current=(row.self or sampIsPlayerConnected(row.id))and tostring(u8(sampGetPlayerNickname(row.id)))==row.name
            if current and hover and g.IsMouseDoubleClicked(0)then sampSendClickPlayer(row.id,0);open(false)
            elseif current and g.IsItemClicked(0)then if selected==row.id then selected=nil else selected=row.id end end
            d:AddRectFilled(pos,g.ImVec2(pos.x+rw,pos.y+rowHeight-4),color(0x999999,hover and 0.35 or 0.13),4)
            if selected==row.id then d:AddRect(pos,g.ImVec2(pos.x+rw,pos.y+rowHeight-4),color(0xFFFFFF,0.5),4,15,1)end
            local textY=pos.y+(rowHeight-g.GetFontSize())/2-2
            d:AddText(g.ImVec2(pos.x+12*scale,textY),color(0xFFFFFF),tostring(row.id))
            local dot=bit.bor(bit.lshift(bit.band(row.color,255),16),bit.band(row.color,0xFF00),bit.band(bit.rshift(row.color,16),255))
            d:AddCircleFilled(g.ImVec2(pos.x+nameX-9*scale,textY+g.GetFontSize()/2),3*scale,color(dot))
            d:AddText(g.ImVec2(pos.x+nameX,textY),color(current and 0xFFFFFF or 0x999999),row.name)
            d:AddText(g.ImVec2(pos.x+scoreX,textY),color(0xFFFFFF),tostring(row.score))
            local ping=tostring(row.ping);local size=g.CalcTextSize(ping)
            d:AddText(g.ImVec2(pos.x+pingX-12-size.x,textY),color(0xFFFFFF),ping)
            if g.BeginPopupContextItem('##glass_actions_'..row.id)then
                g.TextWrapped(row.name..' ['..row.id..']')
                if g.Button('Скопировать ник##glass_'..row.id)then setClipboardText(u8:decode(row.name));g.CloseCurrentPopup()end
                if g.Button('Закрыть##glass_popup_'..row.id)then g.CloseCurrentPopup()end
                g.EndPopup()
            end
        end
    end
    g.EndChild()
    if font then g.PopFont()end
    g.End();g.PopStyleColor(3);g.PopStyleVar(2)
end
local settingsExpanded=false
integration.drawSettings=function()
    local enabled=g.ImBool(cfg.main.enabled)
    if g.Checkbox('TAB Жидкое стекло',enabled)then cfg.main.enabled=enabled.v;save();if not enabled.v then integration.onDisconnect()end end
    g.SameLine()
    if g.Button('Настройки##glass_settings')then settingsExpanded=not settingsExpanded end
    if not settingsExpanded then return end
    local helper=integration.service('combo_settings.lua')
    if helper.toggle(g,'Плавная прокрутка##glass',cfg.main,'scroll')then targetScroll=nil;save()end
    if helper.toggle(g,'Закрывать при отпускании TAB после удержания##glass',cfg.main,'hold')then save()end
    local pos=g.ImInt(math.max(0,math.min(2,cfg.main.pos-1)));g.PushItemWidth(220)
    if g.Combo('Положение##glass',pos,'Слева\0По центру\0Справа\0\0')then cfg.main.pos=pos.v+1;save()end
    g.PopItemWidth()
end

    end
