-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/hospital.lua
-- Original third-party credits, where present, are retained below.
-- CasualAT module. Author: Casual Alvarez. Original source: integration/sources.
require 'lib.moonloader'

local encoding = require 'encoding'

encoding.default = 'CP1251'
u8 = encoding.UTF8

local TELEPORT_DELAY_MS = 1000
local MAX_PLAYER_ID = 999
local BRAND_HEX = 'FF6666'
local BRAND_PREFIX = string.format('{%s}[X-Tools]{FFFFFF}: ', BRAND_HEX)
local LOAD_PREFIX = BRAND_PREFIX

local queue_token = 0

local function cp1251_to_utf8(str)
    return tostring(u8(str or ''))
end

local function utf8_to_cp1251(str)
    return u8:decode(tostring(str or ''))
end

local function chat(text, color)
    if isSampAvailable() then
        sampAddChatMessage(utf8_to_cp1251(text), color or 0xFFFFFF)
    end
end

local function brand_chat(text)
    chat(BRAND_PREFIX .. text, 0xFFFFFF)
end

local function load_chat(text)
    chat(LOAD_PREFIX .. text, 0xFFFFFF)
end

local function parse_ids(raw_args)
    local ids = {}
    local invalid = {}

    for token in tostring(raw_args or ''):gmatch('%S+') do
        local id = tonumber(token)

        if id ~= nil and id >= 0 and id <= MAX_PLAYER_ID and id % 1 == 0 then
            ids[#ids + 1] = id
        else
            invalid[#invalid + 1] = token
        end
    end

    return ids, invalid
end

local function cancel_queue(show_message)
    queue_token = queue_token + 1

    if show_message then
        brand_chat('Очередь телепортации остановлена.')
    end
end

local function run_queue(ids)
    if not integration.access:require(3, brand_chat) then return end
    queue_token = queue_token + 1
    local my_token = queue_token
    local accessRevision = integration.access:revision()
    local names = {}
    for _, id in ipairs(ids) do
        if sampIsPlayerConnected(id) then names[id] = sampGetPlayerNickname(id) end
    end

    lua_thread.create(function()
        for index, id in ipairs(ids) do
            if my_token ~= queue_token or accessRevision ~= integration.access:revision() or not integration.access:can(3) then
                return
            end

            if names[id] and sampIsPlayerConnected(id) and sampGetPlayerNickname(id) == names[id] then
                sampSendChat(utf8_to_cp1251(string.format('/gethere %d', id)))
                brand_chat(string.format('Команда /gethere %d отправлена (%d из %d).', id, index, #ids))
            else
                brand_chat(string.format('ID %d пропущен: игрок вышел или этот ID занят другим игроком.', id))
            end

            if index < #ids then
                wait(TELEPORT_DELAY_MS)
            end
        end

        if my_token == queue_token then
            brand_chat(string.format('Очередь завершена. Проверено ID: %d.', #ids))
        end
    end)
end

local function handle_clearhospital_command(raw_args)
    local args = tostring(raw_args or ''):match('^%s*(.-)%s*$') or ''

    if args == '' then
        brand_chat('Телепортация к себе: /clearhospital ID [ID...]')
        brand_chat('Остановить очередь: /clearhospital stop')
        return
    end

    if args:lower() == 'stop' then
        cancel_queue(true)
        return
    end

    local ids, invalid = parse_ids(args)

    if #ids == 0 then
        brand_chat('Нужен хотя бы один целый ID от 0 до 999.')
        return
    end

    if #invalid > 0 then
        brand_chat(string.format('Некорректные ID пропущены: %s', table.concat(invalid, ', ')))
    end

    if not integration.access:require(3, brand_chat) then return end

    if #ids == 1 then
        cancel_queue(false)
        if not sampIsPlayerConnected(ids[1]) then brand_chat('Игрок не в сети.'); return end
        sampSendChat(utf8_to_cp1251(string.format('/gethere %d', ids[1])))
        brand_chat(string.format('Команда /gethere %d отправлена.', ids[1]))
        return
    end

    cancel_queue(false)
    brand_chat(string.format('Очередь телепортации запущена. Игроков: %d; интервал: %d сек.', #ids, TELEPORT_DELAY_MS / 1000))
    run_queue(ids)
end

function integration.start()
    repeat
        wait(100)
    until isSampAvailable()

    sampRegisterChatCommand('clearhospital', handle_clearhospital_command)

end

integration.onDisconnect = function() cancel_queue(false) end

    end
    sources["modules/invisible.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/invisible.lua
-- Original third-party credits, where present, are retained below.
-- Levels 1-2: Bart4 spectator-sync invisibility. Level 3+: server /inv.
local events=require('lib.samp.events')
local u8=require('encoding').UTF8
local packets=integration.service('sync_packets.lua').new(_G)
local active,startupDone,spectating=false,false,false
local nextPacket=0
integration.keys:register('invisible','Невидимость — /inv (1–2: Bart4)',{key=0,second=0})
local function localMode()
    local level=integration.access:level();return level==1 or level==2
end
local function localRunning()
    return active and localMode() and not spectating and sampGetGamestate()==3
        and sampIsLocalPlayerSpawned() and not isCharInAnyCar(PLAYER_PED)
end
local function toggleLocal()
    active=not active;nextPacket=0
    if not active and not spectating and sampIsLocalPlayerSpawned() and not isCharInAnyCar(PLAYER_PED) then packets.onfoot() end
end
function events.onSendCommand(command)
    if tostring(command):lower():match('^%s*/inv%s*$') then
        if localMode() then toggleLocal();return false end

    end
end
function events.onServerMessage(_,text)
    if not integration.access:can(1) then return end
    local message=u8(text):gsub('{%x%x%x%x%x%x}','')
    local nick,id,action=message:match('^%[A%]%s+([%w_]+)%[(%d+)%]%s+(.+)$')
    local ok,myId=sampGetPlayerIdByCharHandle(PLAYER_PED)
    if not ok or tonumber(id)~=myId or nick~=sampGetPlayerNickname(myId) then return end
    action=action:gsub('[%.!]%s*$','')
    if action=='вошел в режим невидимки' or action=='вошёл в режим невидимки' then active=true
    elseif action=='вышел из режима невидимки' then active=false end
end
function events.onSendPlayerSync()if localRunning()then return false end end
function events.onTogglePlayerSpectating(value)spectating=value==true;nextPacket=0 end
local function reset() active=false;startupDone=false;spectating=false;nextPacket=0 end
events.onConnectionClosed=reset
events.onConnectionLost=reset
events.onConnectionRequestAccepted=reset
integration.onDisconnect=reset
integration.stop=function()
    local restore=active and localMode() and not spectating
    reset()
    if restore and sampGetGamestate()==3 and sampIsLocalPlayerSpawned() and not isCharInAnyCar(PLAYER_PED)then packets.onfoot()end
end
integration.isActive=function()return active end
local function activate()if localMode()then toggleLocal()else sampSendChat('/inv')end end
integration.update=function()
    if not startupDone and sampGetGamestate()==3 and sampIsLocalPlayerSpawned() and integration.access:can(1) then
        startupDone=true
        if integration.preferences.data.main.invisibleOnStart and not active then activate() end
    end
    local pressed=integration.keys:pressed('invisible')
    if pressed and integration.access:can(1) and sampGetGamestate()==3 and isGameWindowForeground() and not isPauseMenuActive()
        and not sampIsChatInputActive() and not sampIsDialogActive() and not sampIsCursorActive() then
        activate()
    end
    if localRunning() and getGameTimer()>=nextPacket then
        packets.spectator(getCharCoordinates(PLAYER_PED));nextPacket=getGameTimer()+50
    end
end

    end
    sources["modules/joinquit.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/joinquit.lua
-- Original third-party credits, where present, are retained below.
-- CasualAT module. Author: Casual Alvarez. Original source: integration/sources.
require "lib.moonloader"
local sampev = require "lib.samp.events"
local encoding = require "encoding"
local imgui = require "imgui"
local bit = require "bit"

encoding.default = "CP1251"
local u8 = encoding.UTF8

local storage = integration.storage
local CONFIG_DIR = storage:directory('settings')
local CONFIG_PATH = storage:path('settings', 'events.lua', {getWorkingDirectory() .. '/config/joinandquit_settings.lua'})

local settings_window_state = imgui.ImBool(false)

local confirmed_players = {}
local pending_joins = {}
local visible_players = {}
local last_stream_time = {}
local event_log = {}

local hud_font = nil
local last_update_time = 0

local update_interval_ms = 500
local min_score = 1
local join_timeout_seconds = 15
local startup_grace_seconds = 10
local vision_memory_seconds = 10
local max_log_hard_limit = 200

local tracking_enabled = false
local startup_time = 0

local faction_list = {

    { key = "ballas",   color = 0xFFCC00FF, name = "BALLAS" },

    { key = "grove",    color = 0xFF009900, name = "GROVE" },

    { key = "vagos",    color = 0xFFFFCD00, name = "VAGOS" },

    { key = "rifa",     color = 0xFF6666FF, name = "RIFA" },

    { key = "aztecas",  color = 0xFF00CCFF, name = "AZTEC" },



    { key = "rm",       color = 0xFF007575, name = "RM" },

    { key = "yak",      color = 0xFFBB0000, name = "YZ" },

    { key = "lcn",      color = 0xFF993366, name = "LCN" },



    { key = "mask",     color = 0x00222222, name = "MASK" },



    { key = "bomj",     color = 0x11FFFFFF, name = "UNINV" },

    { key = "mvd",      color = 0xFF0000FF, name = "MVD" },

    { key = "mo",       color = 0xFF996633, name = "ARMY" },

    { key = "pa",       color = 0xFFCCFF00, name = "GOV" },

    { key = "health",   color = 0xFFFF6666, name = "PRMD" },

    { key = "media",    color = 0xFFFF6600, name = "MEDIA" },



    { key = "unknown",  color = -1,         name = "UNKNWN" }

}



local faction_by_color = {

    [0xFFCC00FF] = { key = "ballas",  name = "BALLAS" },

    [0xFF009900] = { key = "grove",   name = "GROVE" },

    [0xFFFFCD00] = { key = "vagos",   name = "VAGOS" },

    [0xFF6666FF] = { key = "rifa",    name = "RIFA" },

    [0xFF00CCFF] = { key = "aztecas", name = "AZTEC" },



    [0xFF007575] = { key = "rm",      name = "RM" },

    [0xFFBB0000] = { key = "yak",     name = "YZ" },

    [0xFF993366] = { key = "lcn",     name = "LCN" },



    [0x00222222] = { key = "mask",    name = "MASK" },



    [0x11FFFFFF] = { key = "bomj",    name = "UNINV" },

    [0xFF0000FF] = { key = "mvd",     name = "MVD" },

    [0xFF996633] = { key = "mo",      name = "ARMY" },

    [0xFFCCFF00] = { key = "pa",      name = "GOV" },

    [0xFFFF6666] = { key = "health",  name = "PRMD" },

    [0xFFFF6600] = { key = "media",   name = "MEDIA" }

}



local settings = {
    ui = {
        visible = true,
        show_hud_log = true,
        duplicate_to_chat = false,
        show_timestamp = true,

        log_x = 30,
        log_y = 300,
        log_max_lines = 10,
        log_alpha = 1.00,
        font_size = 9
    },
    global = {
        connects_enabled = true,
        disconnects_enabled = true
    },
    connects = {},
    disconnects = {}
}

local function msg(text, color)
    sampAddChatMessage(u8:decode(text), color or -1)
end

local function ensureConfigDir()
    if not doesDirectoryExist(CONFIG_DIR) then
        createDirectory(CONFIG_DIR)
    end
end

local function serializeValue(v, indent)
    indent = indent or 0
    local pad = string.rep("    ", indent)
    local nextPad = string.rep("    ", indent + 1)

    if type(v) == "table" then
        local out = "{\n"
        for k, val in pairs(v) do
            local key
            if type(k) == "string" and k:match("^[_%a][_%w]*$") then
                key = k
            else
                key = "[" .. string.format("%q", tostring(k)) .. "]"
            end
            out = out .. nextPad .. key .. " = " .. serializeValue(val, indent + 1) .. ",\n"
        end
        out = out .. pad .. "}"
        return out
    elseif type(v) == "string" then
        return string.format("%q", v)
    elseif type(v) == "number" or type(v) == "boolean" then
        return tostring(v)
    end

    return "nil"
end

local function makeDefaultSettings()
    local s = {
        ui = {
            visible = true,
            show_hud_log = true,
            duplicate_to_chat = false,
            show_timestamp = true,

            log_x = 30,
            log_y = 300,
            log_max_lines = 10,
            log_alpha = 1.00,
            font_size = 9
        },
        global = {
            connects_enabled = true,
            disconnects_enabled = true
        },
        connects = {},
        disconnects = {}
    }

    for _, faction in ipairs(faction_list) do
        s.connects[faction.key] = true
        s.disconnects[faction.key] = true
    end

    return s
end

local function saveSettings()
    ensureConfigDir()

    local f = io.open(CONFIG_PATH, "w")
    if not f then
        msg("{B4A2FF}[X-Tools]{FFFFFF} Не удалось сохранить настройки входов и выходов. Проверьте доступ к X-TOOL/settings.")
        return
    end

    f:write("return ")
    f:write(serializeValue(settings))
    assert(f:close())
end

local function loadSettings()
    ensureConfigDir()

    local data = storage:loadTable(CONFIG_PATH)
    if data then
        settings = data
    else
        settings = makeDefaultSettings()
        saveSettings()
    end

    settings.ui = settings.ui or {}
    settings.global = settings.global or {}
    settings.connects = settings.connects or {}
    settings.disconnects = settings.disconnects or {}

    if settings.ui.visible == nil then settings.ui.visible = true end
    if settings.ui.show_hud_log == nil then settings.ui.show_hud_log = true end
    if settings.ui.duplicate_to_chat == nil then settings.ui.duplicate_to_chat = false end
    if settings.ui.show_timestamp == nil then settings.ui.show_timestamp = true end
    if settings.ui.log_x == nil then settings.ui.log_x = 30 end
    if settings.ui.log_y == nil then settings.ui.log_y = 300 end
    if settings.ui.log_max_lines == nil then settings.ui.log_max_lines = 10 end
    if settings.ui.log_alpha == nil then settings.ui.log_alpha = 1.00 end
    if settings.ui.font_size == nil then settings.ui.font_size = 9 end

    if settings.global.connects_enabled == nil then settings.global.connects_enabled = true end
    if settings.global.disconnects_enabled == nil then settings.global.disconnects_enabled = true end

    for _, faction in ipairs(faction_list) do
        if settings.connects[faction.key] == nil then
            settings.connects[faction.key] = true
        end
        if settings.disconnects[faction.key] == nil then
            settings.disconnects[faction.key] = true
        end
    end

    settings_window_state.v = settings.ui.visible
end

local function recreateHudFont()
    if hud_font and renderReleaseFont then
        pcall(renderReleaseFont, hud_font)
    end
    hud_font = renderCreateFont("Arial", settings.ui.font_size, 5)
end

local function colorToChatHex(color)
    local rgb = color % 0x1000000
    return string.format("%06X", rgb)
end

local function getQuitReasonText(reason)
    if reason == 0 then
        return "timeout/crash", "FFAA00"
    elseif reason == 1 then
        return "left", "AAAAAA"
    elseif reason == 2 then
        return "kick/ban", "FF4444"
    end
    return "reason:" .. tostring(reason), "FFFFFF"
end

local function isPlayerConfirmed(playerId)
    if not sampIsPlayerConnected(playerId) then
        return false
    end

    local ok_name, name = pcall(sampGetPlayerNickname, playerId)
    if not ok_name or not name or name == "" then
        return false
    end

    local ok_score, score = pcall(sampGetPlayerScore, playerId)
    if not ok_score or score == nil then
        return false
    end

    return score >= min_score
end

local function isRecentlyVisible(playerId)
    if visible_players[playerId] then
        return true
    end

    local t = last_stream_time[playerId]
    if t and (os.clock() - t <= vision_memory_seconds) then
        return true
    end

    return false
end

local function getFactionInfo(playerId)
    local ok, color = pcall(sampGetPlayerColor, playerId)
    if not ok or not color then
        return "unknown", "UNKNWN", "FFFFFF"
    end

    color=integration.originalPlayerColor(playerId,color)
    if integration.isMaskColor(color) then return 'mask','MASK',colorToChatHex(integration.maskColor()) end
    local faction = faction_by_color[color]
    if faction then
        return faction.key, faction.name, colorToChatHex(color)
    end

    return "unknown", "UNKNWN", "FFFFFF"
end

local function shouldTrack(mode, factionKey)
    if mode == "connects" then
        return settings.global.connects_enabled and settings.connects[factionKey] == true
    elseif mode == "disconnects" then
        return settings.global.disconnects_enabled and settings.disconnects[factionKey] == true
    end
    return true
end

local function setAll(mode, value)
    if mode == "connects" then
        for _, faction in ipairs(faction_list) do
            settings.connects[faction.key] = value
        end
    elseif mode == "disconnects" then
        for _, faction in ipairs(faction_list) do
            settings.disconnects[faction.key] = value
        end
    end
    saveSettings()
end

local function boolRef(value)
    return imgui.ImBool(value)
end

local function intRef(value)
    return imgui.ImInt(value)
end

local function floatRef(value)
    return imgui.ImFloat(value)
end

local function addEventLog(entry)
    table.insert(event_log, entry)

    while #event_log > max_log_hard_limit do
        table.remove(event_log, 1)
    end

    if settings.ui.duplicate_to_chat and entry.chat then
        msg(entry.chat)
    end
end

local function markExistingPlayersAsKnown()
    for playerId = 0, 1003 do
        if isPlayerConfirmed(playerId) then
            confirmed_players[playerId] = true
            pending_joins[playerId] = nil
        end
    end
end

local function refreshConfirmedPlayers()
    for playerId = 0, 1003 do
        if isPlayerConfirmed(playerId) then
            confirmed_players[playerId] = true
        end
    end
end

local function cleanupDisconnectedPlayers()
    for playerId, _ in pairs(confirmed_players) do
        if not sampIsPlayerConnected(playerId) then
            confirmed_players[playerId] = nil
        end
    end
end

local function processPendingJoins()
    local now = os.clock()

    for playerId, joinTime in pairs(pending_joins) do
        if not sampIsPlayerConnected(playerId) then
            pending_joins[playerId] = nil

        elseif isPlayerConfirmed(playerId) then
            local was_confirmed = confirmed_players[playerId] == true

            if tracking_enabled and not was_confirmed then
                local name = "Unknown"
                pcall(function()
                    name = sampGetPlayerNickname(playerId)
                end)

                local faction_key, faction_name, faction_hex = getFactionInfo(playerId)

                if shouldTrack("connects", faction_key) then
                    local chat_text = string.format(
                        "{%s}%s{%s}[%d] {FFFFFF}from {%s}%s{FFFFFF} just {228B22}connected",
                        faction_hex,
                        name,
                        faction_hex,
                        playerId,
                        faction_hex,
                        faction_name
                    )

                    addEventLog({
                        kind = "connect",
                        time = os.date("%H:%M:%S"),
                        chat = chat_text,
                        name = name,
                        playerId = playerId,
                        faction = faction_name,
                        faction_color = faction_hex
                    })
                end
            end

            confirmed_players[playerId] = true
            pending_joins[playerId] = nil

        elseif now - joinTime > join_timeout_seconds then
            pending_joins[playerId] = nil
        end
    end
end

local function hexToArgb(hex, alpha)
    hex = tostring(hex or "FFFFFF"):gsub("#", "")
    local rgb = tonumber(hex, 16) or 0xFFFFFF
    alpha = alpha or 255
    return bit.bor(bit.lshift(alpha, 24), rgb)
end

local function getTextWidth(text)
    if renderGetFontDrawTextLength then
        return renderGetFontDrawTextLength(hud_font, text)
    end
    return #tostring(text) * (settings.ui.font_size * 0.60)
end

local function drawHudChunk(text, x, y, color, shadow_color)
    text = u8:decode(text)
    renderFontDrawText(hud_font, text, x + 1, y + 1, shadow_color)
    renderFontDrawText(hud_font, text, x, y, color)
    return getTextWidth(text)
end

local movingLog=false
local function drawHudLog(preview)
    if integration.layoutEditing() and not preview then return end
    if not isGameWindowForeground() or isPauseMenuActive() or sampGetGamestate()~=3 then return end
    if not preview and not settings.ui.show_hud_log and not movingLog then
        return
    end

    if not hud_font then
        return
    end

    local start_index = math.max(1, #event_log - settings.ui.log_max_lines + 1)
    local base_x = settings.ui.log_x
    if movingLog then renderFontDrawText(hud_font, "Enter - save", base_x, settings.ui.log_y, -1)end
    local y = settings.ui.log_y+(movingLog and settings.ui.font_size+5 or 0)
    local line_h = settings.ui.font_size + 5

    local alpha = math.floor(math.max(0.0, math.min(1.0, settings.ui.log_alpha)) * 255)
    local white = hexToArgb("FFFFFF", alpha)
    local green = hexToArgb("22CC22", alpha)
    local red = hexToArgb("FF4444", alpha)
    local shadow = hexToArgb("000000", math.floor(alpha * 0.70))

    for i = start_index, #event_log do
        local entry = event_log[i]
        local x = base_x

        if settings.ui.show_timestamp then
            x = x + drawHudChunk("[" .. (entry.time or "--:--:--") .. "] ", x, y, white, shadow)
        end

        local faction_color = hexToArgb(entry.faction_color or "FFFFFF", alpha)
        x = x + drawHudChunk(entry.name or "Unknown", x, y, faction_color, shadow)
        x = x + drawHudChunk("[" .. tostring(entry.playerId or -1) .. "] ", x, y, faction_color, shadow)

        x = x + drawHudChunk(entry.faction or "UNKNWN", x, y, faction_color, shadow)
        x = x + drawHudChunk(" ", x, y, white, shadow)

        if entry.kind == "connect" then
            x = x + drawHudChunk("connected", x, y, green, shadow)
        elseif entry.kind == "disconnect" then
            x = x + drawHudChunk("discon ", x, y, red, shadow)

            local reason_color = hexToArgb(entry.reason_color or "FFFFFF", alpha)
            x = x + drawHudChunk(entry.reason or "unknown", x, y, reason_color, shadow)
            x = x + drawHudChunk(" ", x, y, white, shadow)

            local stream_color = hexToArgb(entry.stream_color or "FFFFFF", alpha)
            x = x + drawHudChunk(entry.stream or "off stream", x, y, stream_color, shadow)
        else
            x = x + drawHudChunk("event", x, y, white, shadow)
        end

        y = y + line_h
    end
end

function integration.start()
    while not isSampAvailable() do
        wait(100)
    end

    loadSettings()
    recreateHudFont()
    imgui.Process = settings_window_state.v

    wait(1000)
    startup_time = os.clock()
    last_update_time = os.clock()


    while true do
        imgui.Process = settings_window_state.v

        local now = os.clock()

        if not tracking_enabled then
            markExistingPlayersAsKnown()

            if now - startup_time >= startup_grace_seconds then
                tracking_enabled = true
                pending_joins = {}
            end
        else
            if (now - last_update_time) * 1000 >= update_interval_ms then
                processPendingJoins()
                refreshConfirmedPlayers()
                cleanupDisconnectedPlayers()
                last_update_time = now
            end
        end

        drawHudLog()
        wait(0)
    end
end

function sampev.onPlayerJoin(playerId, color, isNpc)
    if isNpc then
        return
    end

    if not tracking_enabled then
        return
    end

    if confirmed_players[playerId] then
        return
    end

    pending_joins[playerId] = os.clock()
end

function sampev.onPlayerQuit(playerId, reason)
    if confirmed_players[playerId] then
        local name = "Unknown"
        pcall(function()
            name = sampGetPlayerNickname(playerId)
        end)

        local stream_text, stream_hex
        if isRecentlyVisible(playerId) then
            stream_text = "in stream"
            stream_hex = "FF0000"
        else
            stream_text = "off stream"
            stream_hex = "228B22"
        end

        local faction_key, faction_name, faction_hex = getFactionInfo(playerId)
        local reason_text, reason_hex = getQuitReasonText(reason)

        if shouldTrack("disconnects", faction_key) then
            local chat_text = string.format(
                "{%s}%s{%s}[%d] {FFFFFF}from {%s}%s{FFFFFF} just {FF0000}discon{FFFFFF} by {%s}%s{FFFFFF} | %s",
                faction_hex,
                name,
                faction_hex,
                playerId,
                faction_hex,
                faction_name,
                reason_hex,
                reason_text,
                stream_text
            )

            addEventLog({
                kind = "disconnect",
                time = os.date("%H:%M:%S"),
                chat = chat_text,
                name = name,
                playerId = playerId,
                faction = faction_name,
                faction_color = faction_hex,
                reason = reason_text,
                reason_color = reason_hex,
                stream = stream_text,
                stream_color = stream_hex
            })
        end
    end

    confirmed_players[playerId] = nil
    pending_joins[playerId] = nil
    visible_players[playerId] = nil
    last_stream_time[playerId] = nil
end

function sampev.onPlayerStreamIn(playerId)
    visible_players[playerId] = true
    last_stream_time[playerId] = os.clock()
end

function sampev.onPlayerStreamOut(playerId)
    visible_players[playerId] = nil
    last_stream_time[playerId] = os.clock()
end

local settings_page = 1
local journal_page = 1

integration.drawSettings = function()
