            saveSettings()
        end
    end

    integration.layout.next(event_columns)
    integration.layout.heading('Журнал на экране')
    do
        local v = boolRef(settings.ui.show_hud_log)
        if imgui.Checkbox("Показывать журнал на экране", v) then
            settings.ui.show_hud_log = v.v
            saveSettings()
        end
    end

    do
        local v = boolRef(settings.ui.show_timestamp)
        if imgui.Checkbox("Показывать время события", v) then
            settings.ui.show_timestamp = v.v
            saveSettings()
        end
    end
    integration.layout.finish(event_columns)
    imgui.Spacing()
    imgui.TextWrapped('Фракции выбираются на соседней вкладке. Изменения применяются к новым событиям.')
    elseif settings_page == 3 then
    imgui.Separator()
    local columns = integration.layout.begin('event_log_appearance', 740)
    integration.layout.heading('Расположение журнала')
    if imgui.Button('Переместить журнал##joinquit')then
        movingLog=true
        integration.beginPlacement(function()movingLog=false;saveSettings()end,function()
            local x,y=getCursorPos();local sw,sh=getScreenResolution()
            settings.ui.log_x=math.max(0,math.min(x,sw-100));settings.ui.log_y=math.max(0,math.min(y,sh-40))
        end)
    end

    do
        local v = intRef(settings.ui.log_x)
        if imgui.SliderInt("X##logx", v, 0, sw) then
            settings.ui.log_x = v.v
            saveSettings()
        end
    end

    do
        local v = intRef(settings.ui.log_y)
        if imgui.SliderInt("Y##logy", v, 0, sh) then
            settings.ui.log_y = v.v
            saveSettings()
        end
    end

    integration.layout.next(columns)
    integration.layout.heading('Внешний вид')
    do
        local v = intRef(settings.ui.log_max_lines)
        if imgui.SliderInt("Количество строк##loglines", v, 3, 20) then
            settings.ui.log_max_lines = v.v
            saveSettings()
        end
    end

    do
        local v = intRef(settings.ui.font_size)
        if imgui.SliderInt("Размер шрифта##fontsize", v, 7, 16) then
            settings.ui.font_size = v.v
            recreateHudFont()
            saveSettings()
        end
    end

    do
        local v = floatRef(settings.ui.log_alpha)
        if imgui.SliderFloat("Непрозрачность##logalpha", v, 0.20, 1.00) then
            settings.ui.log_alpha = v.v
            saveSettings()
        end
    end

    integration.layout.finish(columns)
    imgui.Spacing()
    if imgui.Button("Очистить журнал") then
        event_log = {}
    end
    if imgui.GetContentRegionAvailWidth() >= 360 then imgui.SameLine() end
    if imgui.Button("Сбросить позицию") then
        settings.ui.log_x = 30
        settings.ui.log_y = 300
        saveSettings()
