local IPWHO_DB_PATH = storage:path('cache', 'lookup/ipwho_cache.sqlite3', {OLD_FOLDER .. '/ipwho_cache.sqlite3'})
local IPWHO_CACHE_PATH = storage:path('cache', 'lookup/ipwho_cache.txt', {OLD_FOLDER .. '/ipwho_cache.txt'})
IP_ACCOUNT_INDEX_PATH = storage:path('data', 'players/ip_accounts.txt', {OLD_FOLDER .. '/ip_accounts.txt'})

local DEFAULT_CONFIG = {
    main = {
        auto_collect = true,
    }
}

local SUPPORTED_COMMANDS = {
