    baninfo = "/baninfo",
    offst = "/offst",
    ip = "/ip",
    lip = "/lip",
    log = "/log",
    iplog = "/iplog",
}

local THEME = {
    gold = integration.color(integration.palette.accent), accent = integration.color(integration.palette.accent),
    text = integration.color(integration.palette.text), muted = integration.color(integration.palette.muted),
    good = imgui.ImVec4(0.36, 0.84, 0.68, 1),
    alert = imgui.ImVec4(1, 0.49, 0.55, 1),
}

local main_window_state = imgui.new.bool(false)
local auto_collect_state = imgui.new.bool(true)
local ip_preview_window_state = imgui.new.bool(false)
local lip_preview_window_state = imgui.new.bool(false)
local ipwhois_preview_window_state = imgui.new.bool(false)
ip_accounts_window_state = imgui.new.bool(false)
local account_preview_window_state = imgui.new.bool(false)
registration_preview_window_state = imgui.new.bool(false)
history_window_state = imgui.new.bool(false)
local standalone_history=false
local standalone_registration=false
local standalone_ip,standalone_lip=false,false
local query_input = imgui.new.char[64]()

local session = nil
local View
local account_preview = nil
registration_preview = nil
local pending_queries = {}
local active_query = nil
local command_context = nil
local internal_command_guard = nil
local last_query_action_at = 0.0
was_main_window_open = false
force_next_query_immediately = false
flood_cooldown_until = 0.0
main_window_minimized = false
main_window_restore_width = 1180
main_window_restore_height = 780
main_window_restore_requested = false
batch_retry_trackers = {
    offst = {},
    ban = {},
}

local clipboard_notice = {
    text = "",
    expires = 0.0,
}

local server_notice = {
    text = "",
    tone = "muted",
    expires = 0.0,
}

local ipwho_cache = {}
ipwho_cache_loaded = false
ip_account_links = {}
ip_account_links_loaded = false
ip_accounts_preview = nil
history_preview = nil
history_collect = nil
history_focus_requested = false
ban_lookup_cache = ban_lookup_cache or {}
offst_lookup_cache = offst_lookup_cache or {}
local config = nil
local sql_env = nil
local sql_conn = nil
local sql_ready = false
local sql_unavailable = false
local is_ip
local extract_account_target_from_text
local draw_account_actions_inline
local chat
local clear_pending_queries
local complete_query
local upsert_ip_section
local get_active_query_role
local set_status
local clear_server_notice
local set_server_notice
local should_wrap_profile_ip_actions
local new_session
local ensure_session
local remember_raw_dialog
local remember_raw_dialog_for
local save_config
local accessRevision = integration.access:revision()
local function syncAccess()
    local revision = integration.access:revision()
    if accessRevision ~= revision then
        accessRevision = revision
        if integration.onDisconnect then integration.onDisconnect('Права или сессия изменились. Проверка остановлена.') end
    end
end

local function trim(value)
    local text = tostring(value or "")
    text = (text:gsub("^%s+", ""))
    text = (text:gsub("%s+$", ""))
    return text
end

local function lower_text(value)
    local text = tostring(value or ''):lower()
    local upper, lower = 'АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ', 'абвгдеёжзийклмнопрстуфхцчшщъыьэюя'
    for index = 1, #upper, 2 do text = text:gsub(upper:sub(index, index + 1), lower:sub(index, index + 1)) end
    return text
end

function get_query_timeout(kind, meta)
    local clean_meta = meta or {}
    if trim(kind) == "offst" then
        if trim(clean_meta.role or "") == "offst_batch" then
            return 3.8
        end
        return OFFST_QUERY_TIMEOUT
    end
    return QUERY_TIMEOUT
end

local function strip_color_tags(value)
    return trim((tostring(value or "")):gsub("{[%x][%x][%x][%x][%x][%x]}", ""))
end

local function get_admin_level_text()
    local level = integration.adminLevel()
    return level ~= nil and tostring(level) or 'не подтверждён'
end

local function get_admin_access_hint()
    local level = integration.adminLevel()
    if level == nil then return 'Уровень администратора не подтверждён сервером' end
    if not integration.access:can(3) then return 'Основные сведения доступны. IP и расширенная проверка — с 3 уровня.' end
    if not integration.access:can(5) then return 'Для 3–4-го уровня: без /admget и /iplog' end
    return 'Все запросы доступны'
end

local function query_level(kind)
    return ({offst=1,names=1,history=1,log=1,admget=5,iplog=5})[kind] or 3
end
local function is_command_allowed_for_admin(kind)
    return integration.access:can(query_level(kind))
end

local function ensure_script_access()
    syncAccess()
    return integration.access:require(1, function(reason) chat(reason, 0xE57373) end)
end

local function message_reports_empty_result(message)
    local clean = lower_text(strip_color_tags(cp1251_to_utf8(message or "")))
    if clean == "" then
        return false
    end

    return clean:find("ничего не найдено", 1, true) ~= nil
        or clean:find("записей не найдено", 1, true) ~= nil
        or clean:find("список пуст", 1, true) ~= nil
        or clean:find("нет данных", 1, true) ~= nil
        or clean:find("данных об успешных авторизациях нет", 1, true) ~= nil
        or clean:find("не найден в банлисте", 1, true) ~= nil
        or (clean:find("игрок с таким ником", 1, true) ~= nil and clean:find("не найден", 1, true) ~= nil)
end

message_reports_flood = function(message)
    local clean = lower_text(strip_color_tags(cp1251_to_utf8(message or "")))
    clean = trim(clean:gsub("ё", "е"))
    if clean == "" then
        return false
    end

    return clean:find("не флудите", 1, true) ~= nil
        or clean:find("не флуди", 1, true) ~= nil
        or clean:find("флуд", 1, true) ~= nil
        or clean:find("слишком часто", 1, true) ~= nil
end

handle_flood_message = function(message)
    if not active_query or not message_reports_flood(message) then
        return false
    end

    local flood_delay = 5.0
    local kind = trim(active_query.kind or "")
    local value = trim(active_query.value or "")
    local display_command = (KIND_LABELS[kind] or ("/" .. tostring(kind or "")))
    if value ~= "" then
        display_command = display_command .. " " .. value
    end
    if kind == "" or value == "" then
        active_query = nil
        command_context = nil
        internal_command_guard = nil
        flood_cooldown_until = math.max(tonumber(flood_cooldown_until or 0) or 0, os.clock() + flood_delay)
        last_query_action_at = flood_cooldown_until
        force_next_query_immediately = false
        return true
    end

    local retry_meta = {}
    for key, meta_value in pairs(active_query.meta or {}) do
        retry_meta[key] = meta_value
    end

    local retry_count = tonumber(retry_meta.retry_count or 0) or 0
    local max_retries = 3

    active_query = nil
    command_context = nil
    internal_command_guard = nil

    if retry_count < max_retries then
        retry_meta.retry_count = retry_count + 1
        table.insert(pending_queries, {
            kind = kind,
            value = value,
            meta = retry_meta,
        })
        flood_cooldown_until = math.max(tonumber(flood_cooldown_until or 0) or 0, os.clock() + flood_delay)
        last_query_action_at = flood_cooldown_until
        force_next_query_immediately = false
        set_status(("Сервер ограничил запросы. Повтор %s: %d из %d"):format(display_command, retry_meta.retry_count, max_retries))
        set_server_notice(("Пауза %.1f с перед повтором: %s"):format(flood_delay, display_command), "muted", 6.0)
    else
        flood_cooldown_until = math.max(tonumber(flood_cooldown_until or 0) or 0, os.clock() + flood_delay)
        last_query_action_at = flood_cooldown_until
        force_next_query_immediately = false
        local current = ensure_session()
        table.insert(current.errors, 1, {
            text = ("Запрос пропущен после повторных попыток: %s"):format(display_command),
            tone = "alert",
        })
        while #current.errors > 4 do
            table.remove(current.errors)
        end
        current.status = ("Запрос пропущен после повторных попыток: %s"):format(display_command)
        current.updated_at = os.time()
        set_server_notice(("Запрос пропущен после повторных попыток: %s"):format(display_command), "alert", 8.0)
    end

    return true
end

local function handle_empty_result_message(message)
    if not active_query or not message_reports_empty_result(message) then
        return false
    end

    local clean_message = strip_color_tags(cp1251_to_utf8(message or ""))
    local kind = trim(active_query.kind or "")
    local role = get_active_query_role()
    set_server_notice(clean_message, "muted", 10.0)
    if kind == "ip" or kind == "lip" then
        upsert_ip_section(kind, {
            title = trim(active_query.value or ""),
            text = "Нет данных",
        })
        return true
    end

    local current = role == "account_preview" and account_preview
        or role == "registration_preview" and registration_preview
        or ensure_session()
    if role == "account_preview" and not current then
        current = new_session(trim(active_query.value or ""))
        account_preview = current
    elseif role == "registration_preview" and not current then
        current = new_session(trim(active_query.value or ""))
        registration_preview = current
    end
    if kind == "get" or kind == "admget" then
        current.updated_at = os.time()
        current.status = "Аккаунт не найден"
        table.insert(current.errors, 1, {
            text = clean_message,
            tone = "alert",
        })
        while #current.errors > 4 do
            table.remove(current.errors)
        end
        if role == "account_preview" then
            remember_raw_dialog_for(current, kind, trim(current.target or active_query.value), clean_message)
            account_preview_window_state[0] = true
        elseif role == "registration_preview" then
            remember_raw_dialog_for(current, kind, trim(current.target or active_query.value), clean_message)
            registration_preview_window_state[0] = true
        else
            remember_raw_dialog(kind, trim(current.target or active_query.value), clean_message)
            main_window_state[0] = true
        end
        clear_pending_queries()
        complete_query(kind)
        return true
    end
    if kind == "iplog" then
        current.auth_rows = {}
        current.auth_entries = {}
        current.updated_at = os.time()
        current.status = "История входов обновлена"
        if role == "account_preview" then
            remember_raw_dialog_for(current, "iplog", trim(current.nick or current.target or active_query.value), clean_message)
            account_preview_window_state[0] = true
        else
            remember_raw_dialog("iplog", trim(current.nick or current.target or active_query.value), clean_message)
            main_window_state[0] = true
        end
        complete_query("iplog")
        return true
    end

    if kind == "log" then
        current.punish_rows = {}
        current.updated_at = os.time()
        current.status = "История наказаний обновлена"
        if role == "account_preview" then
            remember_raw_dialog_for(current, "log", trim(current.nick or current.target or active_query.value), clean_message)
            account_preview_window_state[0] = true
        else
            remember_raw_dialog("log", trim(current.nick or current.target or active_query.value), clean_message)
            main_window_state[0] = true
        end
        complete_query("log")
        return true
    end

    if kind == "offst" then
        local requested_target = trim(active_query.value or "")
        if role == "offst_batch" then
            if requested_target ~= "" then
                set_account_offst_lookup(requested_target, {
                    message = clean_message,
                })
            end
            complete_query("offst")
            return true
        end

        current.offst_rows = {
            {
                key = "empty",
                label = "OFFST",
                value = "Нет данных /offst",
                text = "Нет данных /offst",
                tone = "muted",
            }
        }
        current.updated_at = os.time()
        current.status = "Статистика аккаунта обновлена"
        if role == "account_preview" then
            remember_raw_dialog_for(current, "offst", trim(current.nick or current.target or active_query.value), clean_message)
            account_preview_window_state[0] = true
        else
            remember_raw_dialog("offst", trim(current.nick or current.target or active_query.value), clean_message)
            main_window_state[0] = true
        end
        complete_query("offst")
        return true
    end

    if kind == "baninfo" then
        local requested_target = trim(active_query.value or "")
        if role == "ban_check" then
            if requested_target ~= "" then
                set_account_ban_lookup(requested_target, false, {
                    message = clean_message,
                })
            end
            complete_query("baninfo")
            return true
        end

        current.ban_rows = {
            {
                key = "empty",
                label = "BANINFO",
                value = "Нет данных /baninfo",
                text = "Нет данных /baninfo",
                tone = "muted",
            }
        }
        current.updated_at = os.time()
        current.status = "Данные о блокировках обновлены"
        if trim(current.nick or "") ~= "" then
            set_account_ban_lookup(current.nick, false, {
                message = clean_message,
            })
        elseif trim(current.target or "") ~= "" then
            set_account_ban_lookup(current.target, false, {
                message = clean_message,
            })
        elseif requested_target ~= "" then
            set_account_ban_lookup(requested_target, false, {
                message = clean_message,
            })
        end
        if role == "account_preview" then
            remember_raw_dialog_for(current, "baninfo", trim(current.nick or current.target or active_query.value), clean_message)
            account_preview_window_state[0] = true
        else
            remember_raw_dialog("baninfo", trim(current.nick or current.target or active_query.value), clean_message)
            main_window_state[0] = true
        end
        complete_query("baninfo")
        return true
    end

    return false
end

local function get_auto_collect_label()
    if not integration.access:can(3) then return 'Автосбор только доступных сведений; IP — с 3 уровня' end
    if not integration.access:can(5) then return 'Автосбор /offst /baninfo /ip /lip /log' end
    return 'Автосбор /admget /offst /baninfo /ip /lip /log /iplog'
end

local function ensure_directory(path)
    if not doesDirectoryExist(path) then
        createDirectory(path)
    end
end

local function touch_file(path)
    ensure_directory(SCRIPT_FOLDER)
    local file = io.open(path, "a")
    if not file then
        return false
    end
    file:close()
    return true
end

local function parse_bool(value, fallback)
    if value == nil then
        return fallback
    end

    local text = trim(value):lower()
    if text == "true" or text == "1" or text == "yes" or text == "on" then
        return true
    end
    if text == "false" or text == "0" or text == "no" or text == "off" then
        return false
    end
    return fallback
end

local function load_config()
    ensure_directory(SCRIPT_FOLDER)
    config = {
        main = {
            auto_collect = DEFAULT_CONFIG.main.auto_collect,
        }
    }

    local file = io.open(CONFIG_PATH, "r")
    if file then
        local content = file:read("*a")
        file:close()

        for line in tostring(content or ""):gmatch("[^\r\n]+") do
            local key, value = line:match("^%s*([%w_]+)%s*=%s*(.-)%s*$")
            if key == "auto_collect" then
                config.main.auto_collect = parse_bool(value, DEFAULT_CONFIG.main.auto_collect)
            end
        end
    end

    auto_collect_state[0] = config.main.auto_collect == true
    save_config()
end

save_config = function()
    if not config then
        load_config()
        return
    end
    ensure_directory(SCRIPT_FOLDER)
    config.main.auto_collect = auto_collect_state[0] and true or false
    local file, err = io.open(CONFIG_PATH, "w")
    if not file then
        return
    end

    file:write("[main]\n")
    file:write(("auto_collect=%s\n"):format(config.main.auto_collect and "true" or "false"))
    assert(file:close())
end

local function sql_escape(value)
    return tostring(value or ""):gsub("'", "''")
end

local function bool_to_sql(value)
    return value and 1 or 0
end

local function close_sql_cursor(cursor)
    if cursor and type(cursor) ~= "number" and cursor.close then
        pcall(function()
            cursor:close()
        end)
    end
end

local function ensure_ipwho_db()
    if sql_unavailable then
        return false
    end

    if sql_ready and sql_conn then
        return true
    end

    if not has_luasql or not luasql then
        sql_unavailable = true
        return false
    end

    ensure_directory(SCRIPT_FOLDER)

    local ok_env, env_or_err = pcall(luasql.sqlite3)
    if not ok_env or not env_or_err then
        sql_unavailable = true
        return false
    end

    local ok_conn, conn_or_err = pcall(function()
        return env_or_err:connect(IPWHO_DB_PATH)
    end)
    if not ok_conn or not conn_or_err then
        pcall(function()
            env_or_err:close()
        end)
        sql_unavailable = true
        return false
    end

    sql_env = env_or_err
    sql_conn = conn_or_err

    local create_query = [[
        CREATE TABLE IF NOT EXISTS ipwho_cache (
            ip TEXT PRIMARY KEY,
            success INTEGER NOT NULL DEFAULT 1,
            country TEXT,
            country_code TEXT,
            continent TEXT,
            region TEXT,
            city TEXT,
            postal TEXT,
            latitude TEXT,
            longitude TEXT,
            isp TEXT,
            org TEXT,
            domain TEXT,
            asn TEXT,
            connection_type TEXT,
            timezone_id TEXT,
            timezone_time TEXT,
            message TEXT,
            raw_json TEXT,
            fetched_at INTEGER NOT NULL DEFAULT 0
        )
    ]]

    local create_links_query = [[
        CREATE TABLE IF NOT EXISTS ip_account_links (
            ip TEXT NOT NULL,
            account_key TEXT NOT NULL,
            account_label TEXT NOT NULL,
            updated_at INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY (ip, account_key)
        )
    ]]

    local ok_create = pcall(function()
        sql_conn:execute(create_query)
        sql_conn:execute(create_links_query)
    end)
    if not ok_create then
        pcall(function()
            sql_conn:close()
        end)
        pcall(function()
            sql_env:close()
        end)
        sql_conn = nil
        sql_env = nil
        sql_unavailable = true
        return false
    end

    sql_ready = true
    return true
end

local function ensure_storage_artifacts()
    ensure_directory(SCRIPT_FOLDER)
    touch_file(IPWHO_CACHE_PATH)
    touch_file(IP_ACCOUNT_INDEX_PATH)

    if has_luasql and luasql then
        ensure_ipwho_db()
    end
end

local function read_ipwho_db_row(ip)
    local clean_ip = trim(ip)
    if clean_ip == "" or not ensure_ipwho_db() then
        return nil
    end

    local cursor = nil
    local ok_query, query_error = pcall(function()
        cursor = sql_conn:execute(("SELECT * FROM ipwho_cache WHERE ip = '%s' LIMIT 1"):format(sql_escape(clean_ip)))
    end)
    if not ok_query or not cursor then
        close_sql_cursor(cursor)
        return nil
    end

    local row = nil
    local ok_fetch = pcall(function()
        row = cursor:fetch({}, "a")
    end)
    close_sql_cursor(cursor)
    if not ok_fetch or not row then
        return nil
    end

    return {
        success = tostring(row.success or "1") == "1",
        ip = clean_ip,
        country = trim(row.country or ""),
        country_code = trim(row.country_code or ""),
        continent = trim(row.continent or ""),
        region = trim(row.region or ""),
        city = trim(row.city or ""),
        postal = trim(row.postal or ""),
        latitude = trim(row.latitude or ""),
        longitude = trim(row.longitude or ""),
        isp = trim(row.isp or ""),
        org = trim(row.org or ""),
        domain = trim(row.domain or ""),
        asn = trim(row.asn or ""),
        connection_type = trim(row.connection_type or ""),
        timezone_id = trim(row.timezone_id or ""),
        timezone_time = trim(row.timezone_time or ""),
        message = trim(row.message or ""),
        raw_json = tostring(row.raw_json or ""),
        fetched_at = tonumber(row.fetched_at or 0) or 0,
        source = "sql",
    }
end

local function write_ipwho_db_row(info, raw_json)
    if not info or not is_ip(info.ip) or not ensure_ipwho_db() then
        return false
    end

    local query = ([[
        INSERT OR REPLACE INTO ipwho_cache (
            ip, success, country, country_code, continent, region, city, postal,
            latitude, longitude, isp, org, domain, asn, connection_type,
            timezone_id, timezone_time, message, raw_json, fetched_at
        ) VALUES (
            '%s', %d, '%s', '%s', '%s', '%s', '%s', '%s',
            '%s', '%s', '%s', '%s', '%s', '%s', '%s',
            '%s', '%s', '%s', '%s', %d
        )
    ]]):format(
        sql_escape(info.ip or ""),
        bool_to_sql(info.success ~= false),
        sql_escape(info.country or ""),
        sql_escape(info.country_code or ""),
        sql_escape(info.continent or ""),
        sql_escape(info.region or ""),
        sql_escape(info.city or ""),
        sql_escape(info.postal or ""),
        sql_escape(info.latitude or ""),
        sql_escape(info.longitude or ""),
        sql_escape(info.isp or ""),
        sql_escape(info.org or ""),
        sql_escape(info.domain or ""),
        sql_escape(info.asn or ""),
        sql_escape(info.connection_type or ""),
        sql_escape(info.timezone_id or ""),
        sql_escape(info.timezone_time or ""),
        sql_escape(info.message or ""),
        sql_escape(raw_json or info.raw_json or ""),
        tonumber(info.fetched_at or os.time()) or os.time()
    )

    local ok_exec = pcall(function()
        sql_conn:execute(query)
    end)
    return ok_exec
end

local function clear_ipwho_db()
    if not ensure_ipwho_db() then
        return
    end

    pcall(function()
        sql_conn:execute("DELETE FROM ipwho_cache")
    end)
end

function encode_cache_field(value)
    local text = tostring(value or "")
    text = text:gsub("\\", "\\\\")
    text = text:gsub("\t", "\\t")
    text = text:gsub("\r", "\\r")
    text = text:gsub("\n", "\\n")
    return text
end

function decode_cache_field(value)
    local text = tostring(value or "")
    local result = {}
    local index = 1

    while index <= #text do
        local char = text:sub(index, index)
        if char == "\\" and index < #text then
            local next_char = text:sub(index + 1, index + 1)
            if next_char == "t" then
                table.insert(result, "\t")
                index = index + 2
            elseif next_char == "r" then
                table.insert(result, "\r")
                index = index + 2
            elseif next_char == "n" then
                table.insert(result, "\n")
                index = index + 2
            elseif next_char == "\\" then
                table.insert(result, "\\")
                index = index + 2
            else
                table.insert(result, next_char)
                index = index + 2
            end
        else
            table.insert(result, char)
            index = index + 1
        end
    end

    return table.concat(result)
end

function split_cache_line(line)
    local fields = {}
    for field in (tostring(line or "") .. "\t"):gmatch("(.-)\t") do
        table.insert(fields, decode_cache_field(field))
    end
    return fields
end

function build_file_cache_row(info)
    return table.concat({
        encode_cache_field(info.ip or ""),
        encode_cache_field(info.success ~= false and "1" or "0"),
        encode_cache_field(info.country or ""),
        encode_cache_field(info.country_code or ""),
        encode_cache_field(info.continent or ""),
        encode_cache_field(info.region or ""),
        encode_cache_field(info.city or ""),
        encode_cache_field(info.postal or ""),
        encode_cache_field(info.latitude or ""),
        encode_cache_field(info.longitude or ""),
        encode_cache_field(info.isp or ""),
        encode_cache_field(info.org or ""),
        encode_cache_field(info.domain or ""),
        encode_cache_field(info.asn or ""),
        encode_cache_field(info.connection_type or ""),
        encode_cache_field(info.timezone_id or ""),
        encode_cache_field(info.timezone_time or ""),
        encode_cache_field(info.message or ""),
        encode_cache_field(tostring(tonumber(info.fetched_at or 0) or 0)),
    }, "\t")
end

function parse_file_cache_row(line)
    local fields = split_cache_line(line)
    local ip = trim(fields[1] or "")
    if not is_ip(ip) then
        return nil
    end

    return {
        ip = ip,
        success = tostring(fields[2] or "1") ~= "0",
        country = trim(fields[3] or ""),
        country_code = trim(fields[4] or ""),
        continent = trim(fields[5] or ""),
        region = trim(fields[6] or ""),
        city = trim(fields[7] or ""),
        postal = trim(fields[8] or ""),
        latitude = trim(fields[9] or ""),
        longitude = trim(fields[10] or ""),
        isp = trim(fields[11] or ""),
        org = trim(fields[12] or ""),
        domain = trim(fields[13] or ""),
        asn = trim(fields[14] or ""),
        connection_type = trim(fields[15] or ""),
        timezone_id = trim(fields[16] or ""),
        timezone_time = trim(fields[17] or ""),
        message = trim(fields[18] or ""),
        fetched_at = tonumber(fields[19] or 0) or 0,
        source = "file",
    }
end

function save_ipwho_file_cache()
    ensure_directory(SCRIPT_FOLDER)

    local keys = {}
    for ip, info in pairs(ipwho_cache or {}) do
        if is_ip(ip) and info and info.success ~= false then
            table.insert(keys, ip)
        end
    end
    table.sort(keys)

    local file = io.open(IPWHO_CACHE_PATH, "w")
    if not file then
        return false
    end

    for _, ip in ipairs(keys) do
        file:write(build_file_cache_row(ipwho_cache[ip]))
        file:write("\n")
    end

    return file:close()
end

function ensure_ipwho_file_cache_loaded()
    if ipwho_cache_loaded then
        return
    end
    ipwho_cache_loaded = true

    local file = io.open(IPWHO_CACHE_PATH, "r")
    if not file then
        return
    end

    for line in file:lines() do
        local info = parse_file_cache_row(line)
        if info and is_ip(info.ip) and not ipwho_cache[info.ip] then
            ipwho_cache[info.ip] = info
        end
    end
    file:close()
end

function clear_ipwho_file_cache()
    ipwho_cache_loaded = true
    pcall(os.remove, IPWHO_CACHE_PATH)
end

function ensure_ip_account_links_loaded()
    if ip_account_links_loaded then
        return
    end
    ip_account_links_loaded = true

    if ensure_ipwho_db() then
        local cursor = nil
        local ok_query = pcall(function()
            cursor = sql_conn:execute("SELECT ip, account_key, account_label FROM ip_account_links ORDER BY ip, account_label")
        end)

        if ok_query and cursor then
            while true do
                local row = nil
                local ok_fetch = pcall(function()
                    row = cursor:fetch({}, "a")
                end)
                if not ok_fetch or not row then
                    break
                end

                local ip = trim(row.ip or "")
                local account_label = trim(row.account_label or "")
                local account_key = trim(row.account_key or "")
                if is_ip(ip) and account_label ~= "" then
                    if account_key == "" then
                        account_key = normalize_identity(account_label)
                    end
                    if account_key ~= "" then
                        ip_account_links[ip] = ip_account_links[ip] or {}
                        ip_account_links[ip][account_key] = account_label
                    end
                end
            end

            close_sql_cursor(cursor)
            -- Merge the durable text index too; SQLite may contain only older entries.
        else
            close_sql_cursor(cursor)
        end
    end

    local file = io.open(IP_ACCOUNT_INDEX_PATH, "r")
    if not file then
        return
    end

    for line in file:lines() do
        local fields = split_cache_line(line)
        local ip = trim(fields[1] or "")
        local account_label = trim(fields[2] or "")
        local account_key = normalize_identity(account_label)
        if is_ip(ip) and account_label ~= "" and account_key ~= "" then
            ip_account_links[ip] = ip_account_links[ip] or {}
            ip_account_links[ip][account_key] = account_label
        end
    end

    file:close()

    if next(ip_account_links) ~= nil and ensure_ipwho_db() then
        save_ip_account_links()
    end
end

function save_ip_account_links()
    ensure_directory(SCRIPT_FOLDER)
    ensure_ip_account_links_loaded()

    local ip_keys = {}
    for ip, accounts in pairs(ip_account_links or {}) do
        if is_ip(ip) and next(accounts or {}) ~= nil then
            table.insert(ip_keys, ip)
        end
    end
    table.sort(ip_keys)

    local lines={}
    for _,ip in ipairs(ip_keys) do
        local labels={}
        for _,label in pairs(ip_account_links[ip]) do labels[#labels+1]=label end
        table.sort(labels)
        for _,label in ipairs(labels) do
            lines[#lines+1]=encode_cache_field(ip)..'\t'..encode_cache_field(label)..'\n'
        end
    end
    -- The common writer verifies bytes and atomically replaces with rollback.
    -- SQLite is a legacy import source, never the sole copy of new observations.
    return storage:write(IP_ACCOUNT_INDEX_PATH,table.concat(lines))

end

function clear_ip_account_links()
    ip_account_links = {}
    ip_account_links_loaded = true
    if ensure_ipwho_db() then
        pcall(function()
            sql_conn:execute("DELETE FROM ip_account_links")
        end)
    end
    pcall(os.remove, IP_ACCOUNT_INDEX_PATH)
end

function register_ip_account_link(ip, account_label)
    local clean_ip = trim(ip)
    local clean_label = trim(strip_color_tags(account_label))
    local account_key = normalize_identity(clean_label)
    if not is_ip(clean_ip) or clean_label == "" or account_key == "" or tonumber(clean_label) then
        return false
    end

    ensure_ip_account_links_loaded()
    ip_account_links[clean_ip] = ip_account_links[clean_ip] or {}
    if ip_account_links[clean_ip][account_key] == clean_label then
        return false
    end

    local previous=ip_account_links[clean_ip][account_key]
    ip_account_links[clean_ip][account_key] = clean_label
    local saved=save_ip_account_links()
    if not saved then ip_account_links[clean_ip][account_key]=previous end
    return saved and true or false
end

function register_ip_links_for_current(current)
    if not current then
        return
    end

    local account_label = trim(current.nick or "")
    if account_label == "" then
        account_label = trim(current.target or "")
    end
    if account_label == "" then
        account_label = trim(current.account or "")
    end
    if account_label == "" then
        return
    end

    if is_ip(current.reg_ip or "") then
        register_ip_account_link(current.reg_ip, account_label)
    end
    if is_ip(current.last_ip or "") then
        register_ip_account_link(current.last_ip, account_label)
    end
end

function get_ip_account_labels(ip)
    local clean_ip = trim(ip)
    if not is_ip(clean_ip) then
        return {}
    end

    ensure_ip_account_links_loaded()

    local labels = {}
    for _, account_label in pairs(ip_account_links[clean_ip] or {}) do
        if trim(account_label) ~= "" then
            table.insert(labels, account_label)
        end
    end
    table.sort(labels, function(a, b)
        return normalize_identity(a) < normalize_identity(b)
    end)
    return labels
end

function open_ip_accounts_preview(ip)
    local clean_ip = trim(ip)
    if not is_ip(clean_ip) then
        return false
    end

    ip_accounts_preview = {
        ip = clean_ip,
        accounts = get_ip_account_labels(clean_ip),
        updated_at = os.time(),
    }
    ip_accounts_window_state[0] = true
end

local function get_cached_ipwhois(ip)
    local clean_ip = trim(ip)
    if not is_ip(clean_ip) then
        return nil
    end

    ensure_ipwho_file_cache_loaded()

    if ipwho_cache[clean_ip] then
        local cached = ipwho_cache[clean_ip]
        if cached.success == false and not cached.pending and cached.retry_at and os.clock() >= cached.retry_at then
            ipwho_cache[clean_ip] = nil
            return nil
        end
        return cached
    end

    local db_row = read_ipwho_db_row(clean_ip)
    if db_row then
        ipwho_cache[clean_ip] = db_row
        save_ipwho_file_cache()
        return db_row
    end

    return nil
end

local function sanitize_filename(value)
    local clean = trim(value)
    if clean == "" then
        clean = "account"
    end
    clean = clean:gsub('[\\/:*?"<>|]', "_")
    clean = clean:gsub("%s+", "_")
    clean = clean:gsub("_+", "_")
    clean = clean:gsub("^_+", "")
    clean = clean:gsub("_+$", "")
    if clean == "" then
        clean = "account"
    end
    return clean
end

local function utf8_chars(value)
    return tostring(value or ""):gmatch("[%z\1-\127\194-\244][\128-\191]*")
end

local function utf8_length(value)
    local count = 0
    for _ in utf8_chars(value) do
        count = count + 1
    end
    return count
end

local function utf8_sub(value, max_chars)
    local result = {}
    local count = 0
    local limit = tonumber(max_chars) or 0
    if limit <= 0 then
        return ""
    end

    for char in utf8_chars(value) do
        count = count + 1
        if count > limit then
            break
        end
        table.insert(result, char)
    end

    return table.concat(result)
end

local function shorten_text(text, limit)
    local value = trim(text)
    local max_len = tonumber(limit) or 72
    if utf8_length(value) <= max_len then
        return value
    end
    return utf8_sub(value, math.max(1, max_len - 3)) .. "..."
end

is_ip = function(value)
    local clean = trim(value)
    if not clean:match('^%d+%.%d+%.%d+%.%d+$') then return false end
    for part in clean:gmatch('%d+') do if #part > 3 or tonumber(part) > 255 then return false end end
    return true
end

local function split_lines(text)
    local result = {}
    local normalized = tostring(text or ""):gsub("\r\n", "\n"):gsub("\r", "\n")
    for line in normalized:gmatch("[^\n]+") do
        local clean = strip_color_tags(line)
        if clean ~= "" then
            table.insert(result, clean)
        end
    end
    return result
end

local function explode_line(line)
    local result = {}
    local has_pipe = false
    for part in tostring(line or ""):gmatch("[^|]+") do
        local clean = strip_color_tags(part)
        if clean ~= "" then
            has_pipe = true
            table.insert(result, clean)
        end
    end
    if not has_pipe then
        local clean = strip_color_tags(line)
        if clean ~= "" then
            table.insert(result, clean)
        end
    end
    return result
end

function looks_like_history_dialog(title)
    local clean_title = trim(strip_color_tags(title or ""))
    return clean_title:find("Прошлые имена", 1, true) == 1
        or clean_title:find("прошлые имена", 1, true) == 1
end

function extract_history_target(title)
    local clean_title = trim(strip_color_tags(title or ""))
    return trim(
        clean_title:match("^Прошлые имена%s+(.+)$")
        or clean_title:match("^прошлые имена%s+(.+)$")
        or ""
    )
end

function begin_history_preview(target)
    local clean_target = trim(strip_color_tags(target or ""))
    history_preview = {
        target = clean_target,
        title = clean_target ~= "" and ("История ников: %s"):format(clean_target) or "История ников",
        rows = {},
        pages = 0,
        status = "Жду данные истории ников.",
        updated_at = os.time(),
        loading = true,
        started_at = os.clock(),
    }
    history_collect = {
        target = normalize_identity(clean_target),
        seen = {},
        pages = {},
    }
    history_window_state[0] = true
    history_focus_requested = true
    return history_preview
end

function parse_history_dialog_rows(text)
    local rows = {}

    for _, raw_line in ipairs(split_lines(text)) do
        local line = trim(strip_color_tags(raw_line or "")):gsub("\t", "|")
        if line ~= "" and line:find('[^|%s]') then
            local parts = {}
            for part in line:gmatch("[^|]+") do
                local clean = trim(part)
                if clean ~= "" then
                    table.insert(parts, clean)
                end
            end

            local entry_text = nil
            local date_text = ""
            local nick_text = ""
            local history_id = (parts[1] or ''):match("^%d+$") or (parts[1] or ''):match("^[Ii][Dd]:?%s*(%d+)$")
            if #parts >= 3 and history_id then
                date_text = trim(parts[2])
                nick_text = trim(parts[3])
                if nick_text ~= "" and date_text:find("Имя", 1, true) == nil and date_text:find("имя", 1, true) == nil then
                    entry_text = ("%s | %s"):format(date_text, nick_text)
                end
            elseif #parts >= 2 then
                date_text = trim(parts[1])
                nick_text = trim(parts[2])
                if date_text:match("^[Дд]о%s+") and nick_text ~= "" then
                    entry_text = ("%s | %s"):format(date_text, nick_text)
                end
            end

            if not entry_text then
                if line:find("Прошлые имена", 1, true) == nil
                    and line:find("прошлые имена", 1, true) == nil
                    and line:find("ID", 1, true) ~= 1
                    and line:find("Id", 1, true) ~= 1
                    and line:find("Имя", 1, true) == nil
                    and line:find("имя", 1, true) == nil then
                    entry_text = line
                end
            end

            if entry_text and trim(entry_text) ~= "" then
                table.insert(rows, {
                    date = date_text or "",
                    nick = nick_text or "",
                    text = entry_text,
                    tone = "normal",
                })
            end
        end
    end

    return rows
end

function history_dialog_has_next(button1)
    local label = trim(strip_color_tags(button1 or ""))
    return label:find(">>", 1, true) ~= nil
end

function append_history_dialog_rows(target, rows)
    local clean_target = trim(strip_color_tags(target or ""))
    local normalized_target = normalize_identity(clean_target)

    if not history_preview or not history_collect or history_collect.target ~= normalized_target then
        begin_history_preview(clean_target)
    end

    for _, row in ipairs(rows or {}) do
        local row_text = trim(row.text or "")
        local row_key = normalize_identity(("%s|%s|%s"):format(trim(row.date or ""), trim(row.nick or ""), row_text))
        if row_text ~= "" and row_key ~= "" and not history_collect.seen[row_key] then
            history_collect.seen[row_key] = true
            table.insert(history_preview.rows, {
                date = trim(row.date or ""),
                nick = trim(row.nick or ""),
                text = row_text,
                tone = row.tone or "normal",
            })
        end
    end

    history_preview.pages = tonumber(history_preview.pages or 0) + 1
    history_preview.updated_at = os.time()
    history_window_state[0] = true
    history_focus_requested = true
end

function request_nick_history(target)
    if not ensure_script_access() then return false end
    local clean_target = trim(strip_color_tags(target or ""))
    if clean_target == "" then
        chat("Укажите ник или ID игрока: /namestore <ник или ID>.", 0xE57373)
        return false
    end

    local request_target = clean_target
    local player_id = tonumber(clean_target)
    if player_id ~= nil then
        player_id = math.floor(player_id)
        if player_id >= 0 and player_id <= 1004 and sampIsPlayerConnected(player_id) then
            local nickname = strip_color_tags(cp1251_to_utf8(sampGetPlayerNickname(player_id) or ""))
            if nickname ~= "" then
                request_target = nickname
            end
        end
    end

    local preview = begin_history_preview(request_target)
    if session and (normalize_identity(session.nick)==normalize_identity(request_target)or normalize_identity(session.target)==normalize_identity(request_target))then session.history_auto=false end
    preview.status = ("Запрос истории ников: %s…"):format(clean_target)
    sampSendChat(utf8_to_cp1251("/history " .. request_target))
    set_server_notice(("Запрос: /history %s"):format(clean_target), "muted", 6.0)
    return true
end

function handle_history_dialog(dialog)
    local target = extract_history_target(dialog.title)
    local page_key = normalize_identity((dialog.title or "") .. "|" .. (dialog.text or "") .. "|" .. (dialog.button1 or ""))

    if history_collect and history_collect.pages and page_key ~= "" and history_collect.pages[page_key] then
        history_preview.loading = false
        history_preview.status = ("Собрано записей: %d"):format(#(history_preview.rows or {}))
        return false
    end

    if history_collect and history_collect.pages and page_key ~= "" then
        history_collect.pages[page_key] = true
    end

    append_history_dialog_rows(target, parse_history_dialog_rows(dialog.text))

    local has_next = history_dialog_has_next(dialog.button1 or "") and history_preview.pages < 50
    history_preview.loading = has_next
    if has_next then
        history_preview.status = ("Загружено страниц истории: %d"):format(tonumber(history_preview.pages or 0))
        sampSendDialogResponse(dialog.id, 1, 0, "")
    else
        history_preview.status = ("Собрано записей: %d"):format(#(history_preview.rows or {}))
    end

    return false
end

local function set_buffer_text(buffer, text)
    ffi.fill(buffer, ffi.sizeof(buffer), 0)
    local value = tostring(text or "")
    ffi.copy(buffer, value, math.min(#value, ffi.sizeof(buffer) - 1))
end

local function get_buffer_text(buffer)
    return ffi.string(buffer)
end

local function format_command(kind, value)
    local clean = trim(value)
    if clean == "" then
        return "/" .. tostring(kind or "")
    end
    return ("/%s %s"):format(tostring(kind or ""), clean)
end

local function format_time(timestamp)
    if not timestamp or tonumber(timestamp) == nil or tonumber(timestamp) <= 0 then
        return "-"
    end
    return os.date("%d.%m.%Y %H:%M:%S", tonumber(timestamp))
end

chat = function(text, color)
    sampAddChatMessage(utf8_to_cp1251(("%s %s"):format(SCRIPT_TAG, tostring(text or ""))), color or 0xF2C14E)
end

local function push_notice(text)
    clipboard_notice.text = trim(text)
    clipboard_notice.expires = os.clock() + 2.5
end

local function copy_to_clipboard(text, notice_text)
    local value = trim(text)
    if value == "" then
        return
    end
    local ok = false
    if type(setClipboardText) == 'function' then
        local called, result = pcall(setClipboardText, utf8_to_cp1251(value))
        ok = called and result ~= false
    end
    if not ok then
        set_server_notice('Не удалось скопировать данные в буфер обмена.', 'alert', 5.0)
        return
    end
    push_notice(trim(notice_text) ~= "" and notice_text or value)
end

new_session = function(seed_target)
    return {
        created_at = os.time(),
        updated_at = os.time(),
        source = "",
        source_query = "",
        get_only_mode = false,
        target = trim(seed_target or ""),
        nick = "",
        account = "",
        reg_ip = "",
        last_ip = "",
        level = "",
        registration_date = "",
        last_activity = "",
        account_sources = {
            get = false,
            admget = false,
        },
        status = "Ожидание данных",
        profile_rows = {},
        offst_rows = {},
        ban_rows = {},
        note_rows = {},
        ip_sections = {},
        ip_order = {},
        ip_by_slot = {},
        lip_by_slot = {},
        ip_preview = nil,
        lip_preview = nil,
        ipwhois_preview = nil,
        geo_compare_rows = {},
        geo_saved_rows = {},
        geo_saved_accounts_count = 0,
        geo_saved_open = false,
        auth_rows = {},
        auth_entries = {},
        punish_rows = {},
        errors = {},
        requested = {},
        raw_dialogs = {},
    }
end

ensure_session = function(seed_target)
    if not session then
        session = new_session(seed_target)
    elseif trim(seed_target or "") ~= "" and session.target == "" then
        session.target = trim(seed_target)
    end
    return session
end

clear_pending_queries = function()
    pending_queries = {}
    active_query = nil
    internal_command_guard = nil
    last_query_action_at = os.clock()
    force_next_query_immediately = false
    flood_cooldown_until = 0.0
    batch_retry_trackers = {
        offst = {},
        ban = {},
    }
end

function stop_all_checks(reason)
    clear_pending_queries()
    command_context = nil
    if history_preview then history_preview.loading = false end
    history_collect = nil
    if session then
        session.history_auto=false
        session.status = trim(reason or "Проверка остановлена")
        session.updated_at = os.time()
    end
    set_server_notice(trim(reason or "Проверка остановлена"), "muted", 4.0)
end

set_status = function(text)
    local current = ensure_session()
    current.status = trim(text)
    current.updated_at = os.time()
end

local function push_error(text)
    local current = ensure_session()
    table.insert(current.errors, 1, {
        text = trim(text),
        tone = "alert",
    })
    while #current.errors > 4 do
        table.remove(current.errors)
    end
    current.status = trim(text)
    current.updated_at = os.time()
end

clear_server_notice = function()
    server_notice.text = ""
    server_notice.tone = "muted"
    server_notice.expires = 0.0
end

set_server_notice = function(text, tone, ttl)
    server_notice.text = trim(text)
    server_notice.tone = trim(tone) ~= "" and trim(tone) or "muted"
    server_notice.expires = os.clock() + (tonumber(ttl) or 8.0)
end

remember_raw_dialog = function(kind, title, text)
    local current = ensure_session()
    table.insert(current.raw_dialogs, 1, {
        kind = kind,
        title = trim(title),
        text = tostring(text or ""),
    })
    while #current.raw_dialogs > 8 do
        table.remove(current.raw_dialogs)
    end
end

remember_raw_dialog_for = function(current, kind, title, text)
    if not current then
        return
    end
    current.raw_dialogs = current.raw_dialogs or {}
    table.insert(current.raw_dialogs, 1, {
        kind = kind,
        title = trim(title),
        text = tostring(text or ""),
    })
    while #current.raw_dialogs > 8 do
        table.remove(current.raw_dialogs)
    end
end

local function merge_slot_label(first, second)
    local left = trim(first)
    local right = trim(second)
    if left == "" then
        return right
    end
    if right == "" or left == right then
        return left
    end
    if left:find(right, 1, true) or right:find(left, 1, true) then
        return left
    end
    return left .. " / " .. right
end

local function tone_for_raw_line(text)
    local line = trim(text)
    if line == "" then
        return "muted"
    end
    if line:find("^Нет") or line:find("^Не ") or line:find("нет$") or line:find(": Нет$") then
        return "alert"
    end
    return "normal"
end

local function tone_for_profile_row(label, value, raw_line)
    local clean_label = trim(label)
    local clean_value = trim(value)
    local full = trim(raw_line)
    if full:find("^Нет") or full:find("^Не ") or clean_value == "Нет" then
        return "alert"
    end
    if clean_value == "-1" or clean_value == "0" then
        return "muted"
    end
    if clean_label:find("IP") or clean_label:find("Email") or clean_label:find("Телефон") or clean_label:find("Google Auth") then
        return "accent"
    end
    return "normal"
end

local function row_text_color(tone)
    if tone == "accent" then
        return THEME.gold
    end
    if tone == "good" then
        return THEME.good
    end
    if tone == "alert" then
        return THEME.alert
    end
    if tone == "muted" then
        return THEME.muted
    end
    return THEME.text
end

local function parse_generic_rows(text, skip_first_header)
    local result = {}
    local lines = split_lines(text)
    for index, line in ipairs(lines) do
        if not (skip_first_header and index == 1) then
            local cells = {}
            for cell in line:gmatch("[^\t]+") do
                local clean = trim(cell)
                if clean ~= "" then
                    table.insert(cells, clean)
                end
            end
            local rendered = #cells > 1 and table.concat(cells, " | ") or line
            table.insert(result, {
                text = rendered,
                tone = tone_for_raw_line(rendered),
            })
        end
    end
    return result
end

local function parse_iplog_entries(text)
    local entries = {}
    for _, line in ipairs(split_lines(text)) do
        local clean = trim(line)
        if clean ~= "" and not clean:find("Дата и время") and not clean:find("IP адрес") then
            local columns = {}
            for cell in clean:gmatch("[^\t]+") do
                local prepared = trim(cell)
                if prepared ~= "" then
                    table.insert(columns, prepared)
                end
            end

            local date_value = ""
            local time_value = ""
            local ip_value = ""
            local raw_value = clean

            if #columns >= 3 and columns[1]:match("^%d%d%.%d%d%.%d%d%d%d$") then
                date_value = columns[1]
                time_value = trim((columns[2] or ""):gsub("^в%s+", ""))
                ip_value = trim(columns[3] or "")
            elseif #columns >= 2 then
                local left = columns[1]
                local right = columns[2]
                local parsed_date, parsed_time = left:match("^(%d%d%.%d%d%.%d%d%d%d)%s+в%s+(%d%d:%d%d:?%d?%d?)$")
                if not parsed_date then
                    parsed_date, parsed_time = left:match("^(%d%d%.%d%d%.%d%d%d%d)%s+(%d%d:%d%d:?%d?%d?)$")
                end
                date_value = trim(parsed_date or "")
                time_value = trim(parsed_time or "")
                ip_value = trim(right or "")
            else
                local parsed_date, parsed_time, parsed_ip = clean:match("^(%d%d%.%d%d%.%d%d%d%d)%s+в%s+(%d%d:%d%d:?%d?%d?)%s+([%d%.]+)$")
                date_value = trim(parsed_date or "")
                time_value = trim(parsed_time or "")
                ip_value = trim(parsed_ip or "")
            end

            if date_value ~= "" or time_value ~= "" or ip_value ~= "" or raw_value ~= "" then
                local full_parts = {}
                if date_value ~= "" then table.insert(full_parts, date_value) end
                if time_value ~= "" then table.insert(full_parts, time_value) end
                if ip_value ~= "" then table.insert(full_parts, ip_value) end
                table.insert(entries, {
                    date = date_value,
                    time = time_value,
                    ip = ip_value,
                    ip_hits = 0,
                    raw_text = raw_value,
                    full_text = #full_parts > 0 and table.concat(full_parts, " | ") or raw_value,
                })
            end
        end
    end

    local hits_by_ip = {}
    for _, entry in ipairs(entries) do
        local clean_ip = trim(entry.ip or "")
        if clean_ip ~= "" then
            hits_by_ip[clean_ip] = (hits_by_ip[clean_ip] or 0) + 1
        end
    end

    for _, entry in ipairs(entries) do
        local clean_ip = trim(entry.ip or "")
        if clean_ip ~= "" then
            entry.ip_hits = hits_by_ip[clean_ip] or 0
        end
    end

    return entries
end

local function decode_json_text(raw)
    if not raw or raw == "" then
        return nil
    end
    if has_dkjson and dkjson then
        local ok, result = pcall(dkjson.decode, raw)
        if ok then
            return result
        end
    end
    if has_cjson and cjson and cjson.decode then
        local ok, result = pcall(cjson.decode, raw)
        if ok then
            return result
        end
    end
    return nil
end

local lookup_ipwhois
local pending_geo = {}
local geo_changed = false
local lookup_generation = 0
local geo_serial = 0
