local function store_geo_response(clean_ip, raw)
    local decoded = decode_json_text(raw)
    if type(decoded) ~= 'table' then decoded = nil end
    local result = nil

    if decoded then
        if decoded.success == false then
            result = {
                success = false,
                ip = clean_ip,
                message = trim(decoded.message or "ipwho.is вернул ошибку"),
                source = "network",
                fetched_at = os.time(),
            }
        else
            local connection = type(decoded.connection) == 'table' and decoded.connection or {}
            local timezone = type(decoded.timezone) == 'table' and decoded.timezone or {}
            result = {
                success = true,
                ip = clean_ip,
                country = trim(decoded.country or ""),
                country_code = trim(decoded.country_code or ""),
                continent = trim(decoded.continent or ""),
                region = trim(decoded.region or ""),
                city = trim(decoded.city or ""),
                postal = trim(decoded.postal or ""),
                latitude = trim(tostring(decoded.latitude or "")),
                longitude = trim(tostring(decoded.longitude or "")),
                isp = trim(connection.isp or decoded.isp or ""),
                org = trim(connection.org or ""),
                domain = trim(connection.domain or ""),
                asn = trim(tostring(connection.asn or "")),
                connection_type = trim(connection.type or ""),
                timezone_id = trim(timezone.id or ""),
                timezone_time = trim(timezone.current_time or ""),
                raw_json = raw,
                source = "network",
                fetched_at = os.time(),
            }
        end
    else
        local country = trim(raw:match('\"country\"%s*:%s*\"([^\"]*)\"') or "")
        local region = trim(raw:match('\"region\"%s*:%s*\"([^\"]*)\"') or "")
        local city = trim(raw:match('\"city\"%s*:%s*\"([^\"]*)\"') or "")
        local isp = trim(raw:match('\"isp\"%s*:%s*\"([^\"]*)\"') or "")
        if country ~= "" or region ~= "" or city ~= "" or isp ~= "" then
            result = {
                success = true,
                ip = clean_ip,
                country = country,
                country_code = "",
                continent = "",
                region = region,
                city = city,
                isp = isp,
                org = "",
                domain = "",
                asn = "",
                connection_type = "",
                timezone_id = "",
                timezone_time = "",
                latitude = "",
                longitude = "",
                postal = "",
                raw_json = raw,
                source = "network",
                fetched_at = os.time(),
            }
        else
            result = {
                success = false,
                ip = clean_ip,
                message = "Не удалось прочитать ответ ipwho.is",
                source = "network",
                fetched_at = os.time(),
            }
        end
    end

    if result.success and trim(result.country or '') == '' and trim(result.region or '') == '' and trim(result.city or '') == '' then
        result.success, result.message = false, 'В ответе ipwho.is нет географических данных'
    end
    if result.success == false then result.retry_at = os.clock() + 60 end
    ipwho_cache[clean_ip] = result
    if result and result.success ~= false then
        write_ipwho_db_row(result, raw)
        save_ipwho_file_cache()
    end
    geo_changed = true
    return result
end

lookup_ipwhois = function(ip, force_refresh)
    if not integration.access:can(3) then return nil end
    local clean_ip = trim(ip)
    if not is_ip(clean_ip) then return nil end
    ensure_ipwho_file_cache_loaded()
    if not force_refresh then
        local cached = get_cached_ipwhois(clean_ip)
        if cached then return cached end
    end
    if pending_geo[clean_ip] then return ipwho_cache[clean_ip] end
    local state = {generation = lookup_generation, started = os.clock()}
    pending_geo[clean_ip] = state
    local pending = {success = false, pending = true, ip = clean_ip, message = "Загрузка геоданных…"}
    ipwho_cache[clean_ip] = pending
    geo_serial = geo_serial + 1
    local path = SCRIPT_FOLDER .. "\\geo_" .. clean_ip:gsub("%.", "_") .. '_' .. geo_serial .. ".json.tmp"
    state.path = path
    local function finish(success, reason)
        if pending_geo[clean_ip] ~= state then os.remove(path); return end
        pending_geo[clean_ip] = nil
        local raw
        if success then
            local file = io.open(path, "rb")
            if file then raw = file:read("*a"); file:close() end
        end
        os.remove(path)
        if state.generation ~= lookup_generation then return end
        if raw and #raw > 0 and #raw < 1024 * 1024 then
            store_geo_response(clean_ip, raw)
        else
            ipwho_cache[clean_ip] = {success = false, ip = clean_ip,
                message = reason or 'Загрузчик не сохранил ответ ipwho.is; повторите загрузку',
                source = 'network', retry_at = os.clock() + 60}
            geo_changed = true
        end
    end
    state.finish = finish
    -- Native MoonLoader downloader keeps TLS/network work outside the render thread.
    local ok = pcall(downloadUrlToFile, IPWHO_ENDPOINT:format(clean_ip), path, function(_, status)
        -- 6 = STATUS_ENDDOWNLOADDATA; 58 = STATUSEX_ENDDOWNLOAD.
        if pending_geo[clean_ip] ~= state then os.remove(path); return end
        -- Wait for the completed download, then read on the next main update.
        if tonumber(status) == 58 then state.completed = true end
    end)
    if not ok then finish(false, 'Не удалось запустить HTTPS-загрузку ipwho.is') end
    return ipwho_cache[clean_ip]
end

