local function format_geo_summary(info)
    if not info then return 'Геоданные ещё не запрошены' end
    if info.pending then return 'Загрузка геоданных…' end
    if info.success == false then return 'Не загружено: ' .. trim(info.message or 'ошибка ipwho.is') end

    local parts = {}
    if trim(info.country or "") ~= "" then table.insert(parts, trim(info.country)) end
    if trim(info.region or "") ~= "" then table.insert(parts, trim(info.region)) end
    if trim(info.city or "") ~= "" then table.insert(parts, trim(info.city)) end

    if #parts == 0 then
        return "Нет данных"
    end
    return table.concat(parts, ", ")
end

local function parse_coordinate(value)
    local text = trim(value)
    if text == "" then
        return nil
    end
    text = text:gsub(",", ".")
    return tonumber(text)
end

local function calculate_geo_distance_km(left_info, right_info)
    if not left_info or not right_info then
        return nil
    end
    if left_info.success == false or right_info.success == false then
        return nil
    end

    local lat1 = parse_coordinate(left_info.latitude)
    local lon1 = parse_coordinate(left_info.longitude)
    local lat2 = parse_coordinate(right_info.latitude)
    local lon2 = parse_coordinate(right_info.longitude)
    if not lat1 or not lon1 or not lat2 or not lon2 then
        return nil
    end

    lat1 = math.rad(lat1)
    lon1 = math.rad(lon1)
    lat2 = math.rad(lat2)
    lon2 = math.rad(lon2)

    local delta_lat = lat2 - lat1
    local delta_lon = lon2 - lon1
    local sin_lat = math.sin(delta_lat * 0.5)
    local sin_lon = math.sin(delta_lon * 0.5)
    local a = sin_lat * sin_lat + math.cos(lat1) * math.cos(lat2) * sin_lon * sin_lon
    local c = 2 * math.asin(math.min(1, math.sqrt(a)))
    return 6371 * c
end

local function format_distance_km(distance)
    if not distance then
        return ""
    end

    if distance < 10 then
        local text = ("%.1f км"):format(distance)
        text = (text:gsub("%.0 км$", " км"))
        return text
    end

    return ("%d км"):format(math.floor(distance + 0.5))
end

local build_geo_compare_rows

build_geo_compare_rows = function(current)
    current.geo_compare_rows = {}
    current.geo_saved_rows = {}
    current.geo_saved_accounts_count = 0

    local reg_ip = trim(current.reg_ip or "")
    local last_ip = trim(current.last_ip or "")
    if reg_ip == "" and last_ip == "" then
        return
    end

    local reg_info = reg_ip ~= "" and lookup_ipwhois(reg_ip) or nil
    local last_info = last_ip ~= "" and lookup_ipwhois(last_ip) or nil

    local reg_geo = format_geo_summary(reg_info)
    local last_geo = format_geo_summary(last_info)
    local reg_isp = reg_info and reg_info.success ~= false and trim(reg_info.isp or "") or ""
    local last_isp = last_info and last_info.success ~= false and trim(last_info.isp or "") or ""
    local geo_distance = calculate_geo_distance_km(reg_info, last_info)
    local saved_seen_accounts = {}

    local function append_saved_accounts_rows(ip, title)
        local labels = get_ip_account_labels(ip)
        if #labels == 0 then
            return
        end

        for _, account_label in ipairs(labels) do
            local account_key = normalize_identity(account_label)
            if account_key ~= "" and not saved_seen_accounts[account_key] then
                saved_seen_accounts[account_key] = true
                current.geo_saved_accounts_count = current.geo_saved_accounts_count + 1
            end
        end

        table.insert(current.geo_saved_rows, {
            text = ("%s (%d):"):format(title, #labels),
            tone = "muted",
        })

        local chunk = {}
        for index, account_label in ipairs(labels) do
            table.insert(chunk, account_label)
            if #chunk >= 3 or index == #labels then
                table.insert(current.geo_saved_rows, {
                    text = "  " .. table.concat(chunk, ", "),
                    tone = "normal",
                })
                chunk = {}
            end
        end
    end

    table.insert(current.geo_compare_rows, {
        text = ("Регистрация: %s"):format(reg_ip ~= "" and reg_ip or "-"),
        tone = "accent",
    })
    table.insert(current.geo_compare_rows, {
        text = ("Страна, город: %s"):format(reg_geo),
        tone = reg_geo == "Нет данных" and "muted" or "normal",
    })
    if reg_ip ~= "" then
        append_saved_accounts_rows(reg_ip, "В базе по IP регистрации")
    end

    table.insert(current.geo_compare_rows, {
        text = ("Последний вход: %s"):format(last_ip ~= "" and last_ip or "-"),
        tone = "accent",
    })
    table.insert(current.geo_compare_rows, {
        text = ("Страна, город: %s"):format(last_geo),
        tone = last_geo == "Нет данных" and "muted" or "normal",
    })
    if last_ip ~= "" and last_ip ~= reg_ip then
        append_saved_accounts_rows(last_ip, "В базе по последнему IP")
    end

    if reg_isp ~= "" or last_isp ~= "" then
        local provider_text = ""
        if reg_isp ~= "" and reg_isp == last_isp then
            provider_text = ("Провайдер: %s"):format(reg_isp)
        else
            provider_text = ("Провайдеры: %s -> %s"):format(reg_isp ~= "" and reg_isp or "-", last_isp ~= "" and last_isp or "-")
        end
        table.insert(current.geo_compare_rows, {
            text = provider_text,
            tone = "normal",
        })
    end

    if geo_distance then
        table.insert(current.geo_compare_rows, {
            text = ("Расстояние между локациями IP: %s"):format(format_distance_km(geo_distance)),
            tone = geo_distance > 150 and "accent" or "muted",
        })
    end

    if reg_ip ~= "" and last_ip ~= "" then
        local difference = "IP совпадают"
        local tone = "good"
        if reg_ip ~= last_ip then
            tone = "alert"
            if reg_geo ~= "Нет данных" and last_geo ~= "Нет данных" then
                if reg_geo == last_geo then
                    difference = "IP разные, но геопозиция совпадает"
                    tone = "muted"
                else
                    difference = "Разница: регистрация и последний вход из разных мест"
                end
            else
                difference = "Разница: IP регистрации и последнего входа различаются"
            end
        end

        table.insert(current.geo_compare_rows, {
            text = difference,
            tone = tone,
        })
    end
end

local resolve_section_title

local function remember_command_panel(current, kind, slot_key, section)
    if kind == "ip" then
        if slot_key == "preview" then
            current.ip_preview = section
            ip_preview_window_state[0] = true
        else
            current.ip_by_slot[slot_key ~= "" and slot_key or section.ip] = section
        end
        return
    end

    if kind == "lip" then
        if slot_key == "preview" then
            current.lip_preview = section
            lip_preview_window_state[0] = true
        else
            current.lip_by_slot[slot_key ~= "" and slot_key or section.ip] = section
        end
    end
end

local function collect_ordered_sections(sections)
    local ordered = {}
    local extra = {}
    local seen = {}
    local preferred = { "shared", "reg", "last" }

    for _, key in ipairs(preferred) do
        if sections and sections[key] then
            table.insert(ordered, sections[key])
            seen[key] = true
        end
    end

    if sections then
        for key, section in pairs(sections) do
            if not seen[key] and section then
                table.insert(extra, section)
            end
        end
    end

    table.sort(extra, function(left, right)
        local left_time = tonumber(left and left.updated_at or 0) or 0
        local right_time = tonumber(right and right.updated_at or 0) or 0
        if left_time ~= right_time then
            return left_time > right_time
        end
        return trim(left and left.title or "") < trim(right and right.title or "")
    end)

    for _, section in ipairs(extra) do
        table.insert(ordered, section)
    end

    return ordered
end

local function canonicalize_label(label)
    local clean = trim(label)
    local aliases={['Посл. актив.']='last_activity',['Последний вход']='last_activity',
        ['Наличные']='money',['Деньги']='money',['Биз']='business',['Бизнес']='business',
        ['Доп. банковские счета']='bank_accounts',['Партия']='party',
        ['Ник пригл.']='inviter',['Ник пригласившего']='inviter',
        ['Водный и воздушный транспорт']='special_transport'}
    if aliases[clean]then return aliases[clean]end
    if clean == "ID" then
        return "id"
    end
    if clean:find("Номер аккаунта") or clean:find("№ аккаунта") then
        return "account"
    end
    if clean:find("Уровень") then
        return "level"
    end
    if clean:find("IP адрес %(регис") then
        return "reg_ip"
    end
    if clean:find("IP адрес %(послед") then
        return "last_ip"
    end
    if clean:find("Дата регистрации") then
        return "registration_date"
    end
    if clean:find("Послед") and clean:find("актив") then
        return "last_activity"
    end
    if clean:find("В игре сегодня") then
        return "game_today"
    end
    if clean:find("В игре вчера") then
        return "game_yesterday"
    end
    if clean:find("AFK сегодня") then
        return "afk_today"
    end
    if clean:find("AFK вчера") then
        return "afk_yesterday"
    end
    if clean:find("Чистый сегодня") then
        return "clean_today"
    end
    if clean:find("Чистый вчера") then
        return "clean_yesterday"
    end
    if clean:find("Email") then
        return "email"
    end
    if clean:find("Телефон") then
        return "phone"
    end
    if clean:find("Google Auth") then
        return "google_auth"
    end
    return clean
end

local function apply_profile_field(current, label, value)
    local key = canonicalize_label(label)
    local clean = trim(value)
    if key == "account" and clean ~= "" then
        current.account = clean
    elseif key == "level" and clean ~= "" then
        current.level = clean
    elseif key == "reg_ip" and is_ip(clean) then
        current.reg_ip = clean
    elseif key == "last_ip" and is_ip(clean) then
        current.last_ip = clean
    elseif key == "registration_date" and clean ~= "" then
        current.registration_date = clean
    elseif key == "last_activity" and clean ~= "" then
        current.last_activity = clean
    elseif key == "game_today" then
        current.game_today = clean
    elseif key == "game_yesterday" then
        current.game_yesterday = clean
    elseif key == "afk_today" then
        current.afk_today = clean
    elseif key == "afk_yesterday" then
        current.afk_yesterday = clean
    end
end

normalize_identity = function(value)
    return strip_color_tags(trim(value or "")):lower()
end

local function account_session_matches(current, source_query, title)
    if not current then
        return false
    end

    local probes = {
        normalize_identity(source_query),
        normalize_identity(title),
    }

    local known = {
        normalize_identity(current.target),
        normalize_identity(current.source_query),
        normalize_identity(current.nick),
        normalize_identity(current.account),
    }

    for _, probe in ipairs(probes) do
        if probe ~= "" then
            for _, own in ipairs(known) do
                if own ~= "" and own == probe then
                    return true
                end
            end
        end
    end

    return false
end

local function upsert_profile_row(current, label, value, rendered, tone)
    local canonical = canonicalize_label(label)
    local names={last_activity='Последняя активность',money='Наличные',business='Бизнес',inviter='Ник пригласившего'}
    if names[canonical]then label=names[canonical];rendered=label..': '..value end
    local row = {
        key = canonical,
        label = label,
        value = value,
        text = rendered,
        tone = tone,
    }

    for index, existing in ipairs(current.profile_rows or {}) do
        if trim(existing.key or "") == canonical or trim(existing.label or "") == trim(label) then
            current.profile_rows[index] = row
            return
        end
    end

    table.insert(current.profile_rows, row)
end

local function parse_playtime_minutes(value)
    local clean = trim(strip_color_tags(value or ""))
    if clean == "" or clean:find("%d") == nil then
        return nil
    end

    local hours = tonumber(clean:match("(%d+)%s*ч")) or 0
    local minutes = tonumber(clean:match("(%d+)%s*мин")) or 0
    return math.max(0, hours * 60 + minutes)
end

local function format_playtime_minutes(total_minutes)
    local value = math.max(0, tonumber(total_minutes) or 0)
    local hours = math.floor(value / 60)
    local minutes = value % 60
    return ("%d ч %d мин"):format(hours, minutes)
end

local function find_profile_row_index(current, wanted_key)
    for index, row in ipairs(current.profile_rows or {}) do
        if trim(row.key or "") == trim(wanted_key or "") then
            return index
        end
    end
    return nil
end

local function remove_profile_row_by_key(current, wanted_key)
    local index = find_profile_row_index(current, wanted_key)
    if index then
        table.remove(current.profile_rows, index)
    end
end

local function refresh_clean_activity_rows(current)
    if not current then
        return
    end

    remove_profile_row_by_key(current, "game_today")
    remove_profile_row_by_key(current, "game_yesterday")
    remove_profile_row_by_key(current, "afk_today")
    remove_profile_row_by_key(current, "afk_yesterday")

    local function sync_row(target_key, label, game_value, afk_value, after_key)
        local game_minutes = parse_playtime_minutes(game_value)
        local afk_minutes = parse_playtime_minutes(afk_value)
        if game_minutes == nil or afk_minutes == nil then
            remove_profile_row_by_key(current, target_key)
            return
        end

        local clean_minutes = math.max(0, game_minutes - afk_minutes)
        local clean_value = format_playtime_minutes(clean_minutes)
        local row = {
            key = target_key,
            label = label,
            value = clean_value,
            text = ("%s: %s"):format(label, clean_value),
            tone = clean_minutes > 0 and "normal" or "muted",
        }

        remove_profile_row_by_key(current, target_key)

        local insert_index = find_profile_row_index(current, after_key)
        if insert_index then
            table.insert(current.profile_rows, insert_index + 1, row)
        else
            table.insert(current.profile_rows, row)
        end
    end

    sync_row("clean_today", "Чистый сегодня", current.game_today, current.afk_today, "afk_today")
    sync_row("clean_yesterday", "Чистый вчера", current.game_yesterday, current.afk_yesterday, "afk_yesterday")
end

local function append_unique_note_row(current, text, tone)
    local clean = trim(text)
    if clean == "" then
        return
    end

    for _, row in ipairs(current.note_rows or {}) do
        if trim(row.text or "") == clean then
            return
        end
    end

    table.insert(current.note_rows, {
        text = clean,
        tone = tone,
    })
end

local function mark_account_source(current, source_kind)
    current.account_sources = current.account_sources or {
        get = false,
        admget = false,
    }

    if source_kind == "get" then
        current.account_sources.get = true
    elseif source_kind == "admget" then
        current.account_sources.admget = true
    end

    if current.account_sources.get and current.account_sources.admget then
        current.source = "get"
    elseif current.account_sources.admget then
        current.source = "get"
    elseif current.account_sources.get then
        current.source = "get"
    elseif source_kind ~= "" then
        current.source = source_kind
    end
end

local function enqueue_query(kind, value, meta)
    local current = ensure_session()
    local clean = trim(value)
    if clean == "" then
        return
    end
    if not is_command_allowed_for_admin(kind) then
        return
    end

    local key = ("%s|%s"):format(kind, clean)
    if current.requested[key] then
        return
    end

    current.requested[key] = true
    table.insert(pending_queries, {
        kind = kind,
        value = clean,
        meta = meta or {},
    })
end

local function send_query_now(kind, value, meta)
    if integration.queryBusy and integration.queryBusy(kind) then
        table.insert(pending_queries, 1, {kind = kind, value = value, meta = meta or {}})
        set_status('Ожидание ответа на запрос из другого раздела')
        return false
    end
    syncAccess()
    if not is_command_allowed_for_admin(kind) then
        local _, reason = integration.access:require(query_level(kind))
        set_status(reason)
        return false
    end

    local command = format_command(kind, value)
    local clean_meta = meta or {}
    local sent_at = os.clock()
    local timeout = get_query_timeout(kind, clean_meta)
    active_query = {
        kind = kind,
        value = trim(value),
        meta = clean_meta,
        sent_at = sent_at,
        timeout = timeout,
    }
    command_context = {
        kind = kind,
        value = trim(value),
        meta = clean_meta,
        created_at = sent_at,
        timeout = math.max(timeout + 8.0, CONTEXT_TIMEOUT),
    }
    internal_command_guard = command:lower()
    last_query_action_at = active_query.sent_at
    force_next_query_immediately = false
    sampSendChat(utf8_to_cp1251(command))
    set_status(("Отправлено %s"):format(command))
    set_server_notice(("Запрос: %s"):format(command), "muted", 6.0)
end

local build_full_collection_queue

local function start_lookup(kind, raw_target, options)
    if not ensure_script_access() then
        main_window_state[0] = true
        return
    end

    options = options or {}
    if kind=='get' and not integration.access:can(3) then kind='offst' end
    local target = strip_color_tags(raw_target)
    if target == "" then
        chat("Введите ник или номер аккаунта в поле проверки.", 0xE57373)
        return
    end

    session = new_session(target)
    session.history_auto=true
    history_preview=nil;history_collect=nil;standalone_history=false
    session.source = kind
    session.source_query = target
    session.get_only_mode = options.get_only == true
    if View then View.beginLookup() end
    set_buffer_text(query_input, target)
    main_window_minimized = false
    main_window_state[0] = true
    clear_server_notice()
    pending_queries = {}
    active_query = nil
    command_context = nil
    send_query_now(kind, target, { initial = true })
end

request_registration_lookup = function(raw_target)
    if not integration.access:can(3) then return end
    if not ensure_script_access() then
        registration_preview_window_state[0] = true
        return
    end

    local target = strip_color_tags(raw_target)
    if target == "" then
        chat("Введите ник или номер аккаунта.", 0xE57373)
        return
    end

    registration_preview = new_session(target)
    registration_preview.source = "get"
    registration_preview.source_query = target
    registration_preview.get_only_mode = true
    registration_preview.status = "Загрузка данных аккаунта…"
    main_window_minimized = false
    registration_preview_window_state[0] = true
    clear_server_notice()
    pending_queries = {}
    active_query = nil
    command_context = nil
    send_query_now("get", target, { role = "registration_preview", initial = true })
end


local function maybe_get_context()
    if not command_context then
        return nil
    end
    local timeout = tonumber(command_context.timeout) or CONTEXT_TIMEOUT
    if os.clock() - command_context.created_at > timeout then
        command_context = nil
        return nil
    end
    return command_context
end

get_active_query_role = function()
    if active_query and active_query.meta and trim(active_query.meta.role or "") ~= "" then
        return trim(active_query.meta.role or "")
    end

    local context = maybe_get_context()
    if context and context.meta and trim(context.meta.role or "") ~= "" then
        return trim(context.meta.role or "")
    end

    return ""
end

complete_query = function(kind)
    if active_query then
        if active_query.kind == kind then
            active_query = nil
        elseif kind == "account" and (active_query.kind == "get" or active_query.kind == "admget") then
            active_query = nil
        end
    end

    local context = maybe_get_context()
    if context then
        if context.kind == kind then
            command_context = nil
        elseif kind == "account" and (context.kind == "get" or context.kind == "admget") then
            command_context = nil
        end
    end

    internal_command_guard = nil
    last_query_action_at = os.clock()
    force_next_query_immediately = false
end

local function looks_like_account_dialog(text)
    local body = tostring(text or "")
    return body:find("Номер аккаунта") ~= nil
        or body:find("№ аккаунта") ~= nil
        or body:find("IP адрес %(регис") ~= nil
        or body:find("IP адрес %(послед") ~= nil
        or body:find("Баны:") ~= nil
        or body:find("Предупр") ~= nil
end

local function looks_like_iplog_dialog(title, text)
    local clean_title = trim(title)
    local body = tostring(text or "")
    return clean_title:find("^Авторизации%s+") ~= nil
        or (body:find("Дата и время") ~= nil and body:find("IP адрес") ~= nil)
end

local function looks_like_offst_dialog(title, text)
    local clean_title = trim(title)
    local body = tostring(text or "")
    return clean_title:find("Оффлайн статистика", 1, true) ~= nil
        or (
            body:find("Очки опыта") ~= nil
            and body:find("Advance Credits") ~= nil
            and (
                body:find("Организация") ~= nil
                or body:find("Проживание") ~= nil
                or body:find("Игровой статус") ~= nil
            )
        )
end

function looks_like_baninfo_dialog(title, text)
    local clean_title = trim(title)
    local body = tostring(text or "")
    return body:find("Ник забаненного") ~= nil
        and body:find("Ник администратора") ~= nil
        and body:find("Дней до конца бана") ~= nil
        and (
            body:find("Причина") ~= nil
            or body:find("IP во время бана") ~= nil
            or clean_title ~= ""
        )
end

local function detect_dialog_kind(dialog)
    local context = active_query or maybe_get_context()
    if not context then
        return nil
    end

    -- These dialogs belong to authentication, capture roster and checker.
    -- A pending /log must not consume an unrelated server window.
    if dialog.id == 1 or dialog.id == 66 or dialog.id == 424 then return nil end

    if context.kind == "offst" and looks_like_offst_dialog(dialog.title, dialog.text) then
        local requested = trim(context.value or '')
        if requested ~= '' and not tonumber(requested) then
            for _, line in ipairs(split_lines(dialog.text)) do
                for _, part in ipairs(explode_line(line)) do
                    local name = trim(part:match('^Имя:%s*(.+)$') or '')
                    if name ~= '' and normalize_identity(name) ~= normalize_identity(requested) then return nil end
                end
            end
        end
        return "offst"
    end

    if context.kind == "baninfo" and looks_like_baninfo_dialog(dialog.title, dialog.text) then
        return "baninfo"
    end

    if looks_like_account_dialog(dialog.text) then
        if context.kind == "get" or context.kind == "admget" then
            return context.kind
        end
        return nil
    end

    if context.kind == "iplog" and looks_like_iplog_dialog(dialog.title, dialog.text) then
        return "iplog"
    end

    if context.kind == "ip" and is_ip(dialog.title) then
        return "ip"
    end
    if context.kind == "lip" and is_ip(dialog.title) then
        return "lip"
    end
    if context.kind == "log" then
        if looks_like_offst_dialog(dialog.title, dialog.text) or looks_like_iplog_dialog(dialog.title, dialog.text) then return nil end
        return "log"
    end

    return nil
end

local parse_account_dialog

upsert_ip_section = function(kind, dialog)
    local current = ensure_session()
    local ip = trim(dialog.title)
    local key = ("%s|%s"):format(kind, ip)
    local slot = ""
    local slot_key = ""

    if active_query and active_query.kind == kind and active_query.meta then
        slot = trim(active_query.meta.slot or "")
        slot_key = trim(active_query.meta.slot_key or "")
    end

    if slot_key == "" then
        if trim(current.reg_ip or "") ~= "" and trim(current.last_ip or "") ~= "" and current.reg_ip == current.last_ip and current.reg_ip == ip then
            slot_key = "shared"
        elseif trim(current.reg_ip or "") == ip then
            slot_key = "reg"
        elseif trim(current.last_ip or "") == ip then
            slot_key = "last"
        end
    end

    local preview_only = (kind == "lip" or kind == "ip") and slot_key == "preview"
    local store_in_main = not preview_only

    if store_in_main and current.ip_sections[key] == nil then
        current.ip_sections[key] = {
            kind = kind,
            ip = ip,
            slot = slot,
            slot_key = slot_key,
            title = "",
            rows = {},
            updated_at = os.time(),
        }
        table.insert(current.ip_order, key)
    end

    local section = store_in_main and current.ip_sections[key] or {
        kind = kind,
        ip = ip,
        slot = slot,
        slot_key = slot_key,
        title = "",
        rows = {},
        updated_at = os.time(),
    }
    section.slot = merge_slot_label(section.slot, slot)
    section.slot_key = slot_key ~= "" and slot_key or section.slot_key
    section.updated_at = os.time()
    section.rows = parse_generic_rows(dialog.text, false)
    section.title = resolve_section_title(kind, section.slot_key or slot_key, ip)

    for _, row in ipairs(section.rows or {}) do
        local account_target = trim(row and (row.account or row.nick) or "")
            if account_target == "" then account_target = extract_account_target_from_text(row and row.text or "") end
        if account_target ~= "" then
            if register_ip_account_link(ip, account_target) then geo_changed = true end
        end
    end

    if #section.rows == 0 then
        table.insert(section.rows, {
            text = "Нет данных",
            tone = "muted",
        })
    end

    remember_command_panel(current, kind, section.slot_key or slot_key, section)
    if not preview_only then
        remember_raw_dialog(kind, dialog.title, dialog.text)
    end
    current.updated_at = os.time()
    current.status = ("%s обновлен"):format(KIND_LABELS[kind] or ("/" .. kind))
    if not preview_only then
        main_window_state[0] = true
    end
    complete_query(kind)
end

local function parse_iplog_dialog(dialog)
    local current = ensure_session()
    local target = strip_color_tags(dialog.title:match("^Авторизации%s+(.+)$") or "")
    if trim(target or "") ~= "" and current.nick == "" then
        current.nick = trim(target)
    end
    if current.target == "" and trim(target or "") ~= "" then
        current.target = trim(target)
        set_buffer_text(query_input, current.target)
    end

    local entries = parse_iplog_entries(dialog.text)
    local rows = {}
    for _, entry in ipairs(entries) do
        table.insert(rows, {
            text = entry.full_text,
            tone = "normal",
        })
    end

    if #rows == 0 then
        rows = parse_generic_rows(dialog.text, false)
        if #rows > 0 and rows[1].text:find("Дата и время") and rows[1].text:find("IP адрес") then
            table.remove(rows, 1)
        end
    end

    local account_label = trim(current.nick or "")
    if account_label == "" then
        account_label = trim(current.target or "")
    end
    for _, entry in ipairs(entries or {}) do
        if account_label ~= "" and is_ip(entry.ip or "") then
            if register_ip_account_link(entry.ip, account_label) then geo_changed = true end
        end
    end

    current.auth_rows = rows
    current.auth_entries = entries
    current.updated_at = os.time()
    current.status = "История входов обновлена"
    remember_raw_dialog("iplog", dialog.title, dialog.text)
    main_window_state[0] = true
    complete_query("iplog")
end

local function parse_log_dialog(dialog)
    local current = ensure_session()
    local rows = parse_generic_rows(dialog.text, false)
    current.punish_rows = rows
    current.updated_at = os.time()
    current.status = "История наказаний обновлена"
    remember_raw_dialog("log", dialog.title, dialog.text)
    main_window_state[0] = true
    complete_query("log")
end

function parse_baninfo_dialog(dialog)
    local role = get_active_query_role()
    local requested_target = trim(active_query and active_query.value or "")
    local current = nil
    if role == "account_preview" then
        current = account_preview
    elseif role ~= "ban_check" then
        current = ensure_session()
    end
    if role == "account_preview" and not current then
        local seed = active_query and trim(active_query.value or "") or ""
        current = new_session(seed)
        account_preview = current
    end

    local parsed_rows = {}

    local banned_nick = ""
    local banned_ip = ""
    local ban_reason = ""
    local ban_admin = ""
    local ban_days = ""

    for _, line in ipairs(split_lines(dialog.text)) do
        for _, part in ipairs(explode_line(line)) do
            local label, value = part:match("^(.-):%s*(.+)$")
            if label and value then
                local clean_label = trim(label)
                local clean_value = trim(value)
                local tone = tone_for_raw_line(("%s: %s"):format(clean_label, clean_value))
                if clean_label == "Дней до конца бана" or clean_label == "IP во время бана" then
                    tone = "accent"
                elseif clean_label == "Причина" then
                    tone = "alert"
                end

                table.insert(parsed_rows, {
                    key = clean_label,
                    label = clean_label,
                    value = clean_value,
                    text = ("%s: %s"):format(clean_label, clean_value),
                    tone = tone,
                })

                if clean_label == "Номер аккаунта" and current and current.account == "" then
                    current.account = clean_value
                elseif clean_label == "Ник забаненного" then
                    banned_nick = clean_value
                elseif clean_label == "Ник администратора" then
                    ban_admin = clean_value
                elseif clean_label == "Дней до конца бана" then
                    ban_days = clean_value
                elseif clean_label == "Причина" then
                    ban_reason = clean_value
                elseif clean_label == "IP во время бана" then
                    banned_ip = clean_value
                end
            end
        end
    end

    if banned_nick ~= "" and current then
        if current.nick == "" then
            current.nick = banned_nick
        end
        if current.target == "" then
            current.target = banned_nick
        end
    end

    if is_ip(banned_ip) and banned_nick ~= "" then
        register_ip_account_link(banned_ip, banned_nick)
    end

    if banned_nick ~= "" then
        set_account_ban_lookup(banned_nick, true, {
            reason = ban_reason,
            admin = ban_admin,
            days_left = ban_days,
            ip = banned_ip,
            raw = dialog.text,
        })
    end
    if requested_target ~= "" and normalize_identity(requested_target) ~= normalize_identity(banned_nick) then
        set_account_ban_lookup(requested_target, true, {
            nickname = banned_nick,
            reason = ban_reason,
            admin = ban_admin,
            days_left = ban_days,
            ip = banned_ip,
            raw = dialog.text,
        })
    end

    if role == "ban_check" then
        complete_query("baninfo")
        return
    end

    current.ban_rows = parsed_rows

    if #current.ban_rows == 0 then
        table.insert(current.ban_rows, {
            key = "empty",
            label = "BANINFO",
            value = "Нет данных /baninfo",
            text = "Нет данных /baninfo",
            tone = "muted",
        })
    end

    current.updated_at = os.time()
    current.status = "Данные о блокировках обновлены"
    if role == "account_preview" then
        remember_raw_dialog_for(current, "baninfo", dialog.title, dialog.text)
        account_preview_window_state[0] = true
    else
        remember_raw_dialog("baninfo", dialog.title, dialog.text)
        main_window_state[0] = true
    end
    complete_query("baninfo")
end

local function canonicalize_offst_label(label)
    local clean = strip_color_tags(trim(label or ""))
    if clean == "" then
        return nil
    end

    local mapping = {
        ["Очки опыта"] = "Опыт",
        ["Номер телефона"] = "Номер телефона",
        ["На счету телефона"] = "Баланс телефона",
        ["Законопослушность"] = "Законопослушность",
        ["Уровень розыска"] = "Розыск",
        ["Уровень улучшений"] = "Улучшения",
        ["Сила"] = "Сила",
        ["Наркотики"] = "Наркотики",
        ["Патроны"] = "Патроны",
        ["Металл"] = "Металл",
        ["Маски"] = "Маски",
        ["Аптечки"] = "Аптечки",
        ["advance credits"] = "Advance Credits",
        ["Advance Credits"] = "Advance Credits",
        ["Пол"] = "Пол",
        ["Замужем за"] = "Брак",
        ["Женат на"] = "Брак",
        ["Семья"] = "Семья",
        ["Организация"] = "Организация",
        ["Подразделение"] = "Подразделение",
        ["Должность"] = "Должность",
        ["Ранг"] = "Ранг",
        ["Работа"] = "Работа",
        ["Проживание"] = "Проживание",
        ["Бизнес"] = "Бизнес",
        ["Земельный участок"] = "Земельный участок",
        ["Игровой статус"] = "Игровой статус",
    }

    return mapping[clean] or mapping[clean:lower()]
end

local function tone_for_offst_row(label, value)
    local clean_label = trim(label or "")
    local clean_value = trim(value or "")
    if clean_value == "" then
        return "muted"
    end
    if clean_value == "Нет" or clean_value == "-1" or clean_value == "0" then
        return "muted"
    end
    if clean_label == "Организация" or clean_label == "Должность" or clean_label == "Ранг" or clean_label == "Advance Credits" then
        return "accent"
    end
    if clean_label == "Розыск" and clean_value ~= "0" then
        return "alert"
    end
    return "normal"
end

local function upsert_offst_row(current, label, value)
    local key = trim(label or "")
    local clean_value = trim(value or "")
    if key == "" or clean_value == "" then
        return
    end

    local row = {
        key = key,
        label = key,
        value = clean_value,
        text = ("%s: %s"):format(key, clean_value),
        tone = tone_for_offst_row(key, clean_value),
    }

    for index, existing in ipairs(current.offst_rows or {}) do
        if trim(existing.key or "") == key then
            current.offst_rows[index] = row
            return
        end
    end

    table.insert(current.offst_rows, row)
end

local function parse_offst_dialog(dialog)
    local role = get_active_query_role()
    local query_context = active_query or maybe_get_context()
    local requested_target = trim(query_context and query_context.value or "")
    local current = nil
    if role == "account_preview" then
        current = account_preview
    elseif role ~= "offst_batch" then
        current = ensure_session()
    end
    if role == "account_preview" and not current then
        local seed = active_query and trim(active_query.value or "") or ""
        current = new_session(seed)
        account_preview = current
    end

    local brief_nick = requested_target
    local brief_level = ""
    local brief_org = ""

    if role ~= "offst_batch" then
        current.offst_rows = {}
    end

    for _, line in ipairs(split_lines(dialog.text)) do
        for _, part in ipairs(explode_line(line)) do
            local label, value = part:match("^(.-):%s*(.+)$")
            if label and value then
                local clean_label = strip_color_tags(trim(label or ""))
                local clean_value = trim(value or "")
                if clean_label == "ID" then
                    local inline_name = trim(strip_color_tags(
                        clean_value:match("|%s*Имя:%s*(.+)$")
                        or clean_value:match("Имя:%s*(.+)$")
                        or ""
                    ))
                    if inline_name ~= "" then
                        brief_nick = inline_name
                    end
                elseif clean_label == "Имя" then
                    brief_nick = clean_value
                elseif clean_label == "Уровень" then
                    brief_level = clean_value
                elseif canonicalize_offst_label(clean_label) == "Организация" then
                    brief_org = clean_value
                end

                if role ~= "offst_batch" then
                    local display_label = canonicalize_offst_label(label)
                    if display_label then
                        upsert_offst_row(current, display_label, value)
                    end
                end
            end
        end
    end

    if trim(brief_nick) ~= "" or trim(requested_target) ~= "" then
        set_account_offst_lookup(trim(requested_target) ~= "" and requested_target or brief_nick, {
            nickname = brief_nick,
            level = brief_level,
            organization = brief_org,
            raw = dialog.text,
        })
    end

    if role == "offst_batch" then
        complete_query("offst")
        return
    end

    if #current.offst_rows == 0 then
        table.insert(current.offst_rows, {
            key = "empty",
            label = "OFFST",
            value = "Нет данных /offst",
            text = "Нет данных /offst",
            tone = "muted",
        })
    end

    current.updated_at = os.time()
    current.status = "Статистика аккаунта обновлена"
    if role == "account_preview" then
        remember_raw_dialog_for(current, "offst", dialog.title, dialog.text)
        account_preview_window_state[0] = true
    else
        remember_raw_dialog("offst", dialog.title, dialog.text)
        main_window_state[0] = true
    end
    complete_query("offst")
end

local function compose_session_dump(current)
    if not current then
        return "Нет данных."
    end

    local lines = {
        "X-Tools · Проверка игрока",
        ("Цель: %s"):format(current.target ~= "" and current.target or "-"),
        ("Ник: %s"):format(current.nick ~= "" and current.nick or "-"),
        ("Аккаунт: %s"):format(current.account ~= "" and current.account or "-"),
        ("Обновлено: %s"):format(format_time(current.updated_at)),
        "",
        "[Профиль]",
    }

    if #current.profile_rows == 0 and #current.note_rows == 0 then
        table.insert(lines, "Нет данных")
    else
        for _, row in ipairs(current.profile_rows) do
            table.insert(lines, row.text)
        end
        for _, row in ipairs(current.note_rows) do
            table.insert(lines, row.text)
        end
    end

    table.insert(lines, "")
    table.insert(lines, "[Сравнение IP и геоданных]")
    if #current.geo_compare_rows == 0 then
        table.insert(lines, "Нет данных")
    else
        for _, row in ipairs(current.geo_compare_rows) do
            table.insert(lines, row.text)
        end
    end

    table.insert(lines, "")
    table.insert(lines, "[Статистика аккаунта]")
    if #current.offst_rows == 0 then
        table.insert(lines, "Нет данных")
    else
        for _, row in ipairs(current.offst_rows) do
            table.insert(lines, row.text)
        end
    end

    table.insert(lines, "")
    table.insert(lines, "[Блокировки]")
    if #current.ban_rows == 0 then
        table.insert(lines, "Нет данных")
    else
        for _, row in ipairs(current.ban_rows) do
            table.insert(lines, row.text)
        end
    end

    table.insert(lines, "")
    table.insert(lines, "[IP и связанные аккаунты]")
    if #current.ip_order == 0 then
        table.insert(lines, "Нет данных")
    else
        for _, key in ipairs(current.ip_order) do
            local section = current.ip_sections[key]
            if section then
                table.insert(lines, section.title)
                for _, row in ipairs(section.rows or {}) do
                    table.insert(lines, "  " .. row.text)
                end
            end
        end
    end

    table.insert(lines, "")
    table.insert(lines, "[Авторизации]")
    if #current.auth_rows == 0 then
        table.insert(lines, "Нет данных")
    else
        for _, row in ipairs(current.auth_rows) do
            table.insert(lines, row.text)
        end
    end

    table.insert(lines, "")
    table.insert(lines, "[Наказания]")
    if #current.punish_rows == 0 then
        table.insert(lines, "Нет данных")
    else
        for _, row in ipairs(current.punish_rows) do
            table.insert(lines, row.text)
        end
    end

    if current.lip_preview and current.lip_preview.rows and #current.lip_preview.rows > 0 then
        table.insert(lines, "")
        table.insert(lines, "[Просмотр связанных аккаунтов]")
        table.insert(lines, current.lip_preview.title or "Связанные аккаунты")
        for _, row in ipairs(current.lip_preview.rows) do
            table.insert(lines, row.text)
        end
    end

    return table.concat(lines, "\n")
end

function get_offst_value(current, wanted_key)
    local target_key = trim(wanted_key or "")
    if target_key == "" or not current or not current.offst_rows then
        return ""
    end

    for _, row in ipairs(current.offst_rows) do
        local row_key = trim(row.key or row.label or "")
        if row_key == target_key then
            return trim(strip_color_tags(row.value or ""))
        end
    end

    return ""
end

function build_admin_chat_lines(current)
    if not current then
        return nil, "Сначала выполните проверку аккаунта."
    end

    local nick = trim(strip_color_tags(current.nick or ""))
    local account = trim(strip_color_tags(current.account or ""))
    local level = trim(strip_color_tags(current.level or ""))
    local organization = get_offst_value(current, "Организация")
    local reg_ip = trim(current.reg_ip or "")
    local last_ip = trim(current.last_ip or "")

    if nick == "" then nick = "Неизвестно" end
    if account == "" then account = "-" end
    if level == "" then level = "-" end
    if organization == "" then organization = "Нет" end

    local reg_info = is_ip(reg_ip) and lookup_ipwhois(reg_ip) or nil
    local last_info = is_ip(last_ip) and lookup_ipwhois(last_ip) or nil

    local reg_geo = format_geo_summary(reg_info)
    local last_geo = format_geo_summary(last_info)
    local reg_isp = reg_info and reg_info.success ~= false and trim(reg_info.isp or "") or ""
    local last_isp = last_info and last_info.success ~= false and trim(last_info.isp or "") or ""
    local geo_distance = calculate_geo_distance_km(reg_info, last_info)

    local provider_text = "-"
    if reg_isp ~= "" and reg_isp == last_isp then
        provider_text = shorten_text(reg_isp, 42)
    elseif reg_isp ~= "" or last_isp ~= "" then
        provider_text = ("%s -> %s"):format(
            shorten_text(reg_isp ~= "" and reg_isp or "-", 20),
            shorten_text(last_isp ~= "" and last_isp or "-", 20)
        )
    end

    local result_text = "IP совпадают"
    if reg_ip ~= "" and last_ip ~= "" and reg_ip ~= last_ip then
        if reg_geo ~= "Нет данных" and last_geo ~= "Нет данных" then
            if reg_geo == last_geo then
                result_text = "геопозиция совпадает"
            else
                result_text = "разные места входа"
            end
        else
            result_text = "IP различаются"
        end
    elseif reg_ip == "" or last_ip == "" then
        result_text = "часть данных отсутствует"
    end

    return {
        ("[CADM] Ник: %s | Акк: %s | LVL: %s | Фракция: %s"):format(
            nick,
            account,
            level,
            shorten_text(organization, 36)
        ),
        ("[CADM] Регистрация: %s | %s"):format(reg_ip ~= "" and reg_ip or "-", reg_geo),
        ("[CADM] Последний вход: %s | %s"):format(last_ip ~= "" and last_ip or "-", last_geo),
        ("[CADM] Провайдер: %s | Дистанция: %s | %s"):format(
            provider_text,
            geo_distance and format_distance_km(geo_distance) or "-",
            result_text
        ),
    }
end

function send_admin_chat_summary(current)
    local lines, err = build_admin_chat_lines(current)
    if not lines or #lines == 0 then
        chat(err or "Нет данных для отправки в админ-чат.", 0xE57373)
        return false
    end

    local function sender()
        for index, line in ipairs(lines) do
            sampSendChat(utf8_to_cp1251("/a " .. tostring(line or "")))
            if index < #lines then
                wait(350)
            end
        end
    end

    if type(lua_thread) == "table" and type(lua_thread.create) == "function" then
        lua_thread.create(sender)
    else
        sender()
    end

    set_server_notice(("Сводка в /a: строк %d"):format(#lines), "good", 5.0)
    return true
end

local function collect_unique_session_ips(current)
    local seen = {}
    local ordered = {}

    local function remember(ip)
        local clean_ip = trim(ip)
        if is_ip(clean_ip) and not seen[clean_ip] then
            seen[clean_ip] = true
            table.insert(ordered, clean_ip)
        end
    end

    if not current then
        return ordered
    end

    remember(current.reg_ip)
    remember(current.last_ip)

    for _, entry in ipairs(current.auth_entries or {}) do
        remember(entry.ip)
    end

    for _, section in pairs(current.ip_by_slot or {}) do
        remember(section and section.ip or "")
    end
    for _, section in pairs(current.lip_by_slot or {}) do
        remember(section and section.ip or "")
    end
    for _, section in pairs(current.ip_sections or {}) do
        remember(section and section.ip or "")
    end

    if current.ip_preview then
        remember(current.ip_preview.ip)
    end
    if current.lip_preview then
        remember(current.lip_preview.ip)
    end
    if current.ipwhois_preview then
        remember(current.ipwhois_preview.ip)
    end

    return ordered
end

local function collect_session_sections_by_kind(current, kind)
    if not current then
        return {}
    end

    local sections = {}
    for _, key in ipairs(current.ip_order or {}) do
        local section = current.ip_sections and current.ip_sections[key] or nil
        if section and section.kind == kind then
            sections[#sections + 1] = section
        end
    end

    return sections
end

local function compose_ipwhois_dump(ip, info)
    local rows = build_ipwhois_rows(ip, info)
    local lines = {
        ("[Геоданные IP] %s"):format(trim(ip) ~= "" and trim(ip) or "-"),
    }

    for _, row in ipairs(rows or {}) do
        table.insert(lines, row.text)
    end

    return table.concat(lines, "\n")
end

local function compose_full_dossier_dump(current)
    if not current then
        return "Нет данных."
    end

    local lines = {
        compose_session_dump(current),
        "",
        "[Геоданные всех IP]",
    }

    local ips = collect_unique_session_ips(current)
    if #ips == 0 then
        table.insert(lines, "Нет IP-адресов для проверки геоданных")
    else
        for _, ip in ipairs(ips) do
            table.insert(lines, compose_ipwhois_dump(ip, lookup_ipwhois(ip)))
            table.insert(lines, "")
        end
    end

    if current.raw_dialogs and #current.raw_dialogs > 0 then
        table.insert(lines, "[Ответы сервера]")
        for _, dialog in ipairs(current.raw_dialogs) do
            table.insert(lines, ("Команда: %s"):format(KIND_LABELS[dialog.kind] or tostring(dialog.kind or "-")))
            table.insert(lines, ("Заголовок: %s"):format(trim(dialog.title or "")))
            table.insert(lines, tostring(dialog.text or ""))
            table.insert(lines, "")
        end
    end

    return table.concat(lines, "\n")
end

local function export_session_dossier(current)
    if not current then
        return nil, "Нет данных для досье"
    end

    ensure_directory(SCRIPT_FOLDER)
    ensure_directory(DOSSIER_FOLDER)

    local base_name = sanitize_filename(current.nick ~= "" and current.nick or current.target)
    local timestamp = os.date("%Y-%m-%d_%H-%M-%S")
    local file_path = ("%s\\%s_%s.txt"):format(DOSSIER_FOLDER, base_name, timestamp)
    local file, err = io.open(file_path, "w")
    if not file then
        return nil, err or "Не удалось создать файл"
    end

    local written, writeError = file:write(compose_full_dossier_dump(current))
    local closed, closeError = file:close()
    if not written or not closed then return nil, writeError or closeError or "Не удалось сохранить досье" end
    return file_path
end


local function enqueue_priority_query(kind, value, meta)
    if not is_command_allowed_for_admin(kind) then return end
    local clean = strip_color_tags(value)
    if clean == "" then
        return
    end
    table.insert(pending_queries, 1, {
        kind = kind,
        value = clean,
        meta = meta or {},
    })
    if active_query == nil then
        last_query_action_at = 0
    end
end

