resolve_section_title = function(kind, slot_key, ip)
    local prefix = KIND_LABELS[kind] or ("/" .. tostring(kind or ""))
    return ("%s • %s"):format(prefix, trim(ip) ~= "" and trim(ip) or "-")
end

build_full_collection_queue = function(current)
    if not current then
        return
    end

    current.requested = {}
    pending_queries = {}
    active_query = nil
    last_query_action_at = os.clock()
    force_next_query_immediately = false
    current.account_sources = current.account_sources or {
        get = false,
        admget = false,
    }

    local admget_target = trim(current.source_query) ~= "" and trim(current.source_query)
        or (trim(current.nick) ~= "" and trim(current.nick) or trim(current.account))
    local name_target = trim(current.nick) ~= "" and trim(current.nick)
        or (trim(current.account) ~= "" and trim(current.account) or trim(current.source_query))
    local reg_ip = trim(current.reg_ip)
    local last_ip = trim(current.last_ip)

    if integration.access:can(5) and admget_target ~= "" and current.account_sources.admget ~= true then
        enqueue_query("admget", admget_target, { role = "extended_profile" })
    end

    if reg_ip ~= "" and reg_ip == last_ip then
        enqueue_query("ip", reg_ip, { slot_key = "shared" })
        enqueue_query("lip", reg_ip, { slot_key = "shared" })
    else
        if reg_ip ~= "" then
            enqueue_query("ip", reg_ip, { slot_key = "reg" })
            enqueue_query("lip", reg_ip, { slot_key = "reg" })
        end
        if last_ip ~= "" then
            enqueue_query("ip", last_ip, { slot_key = "last" })
            enqueue_query("lip", last_ip, { slot_key = "last" })
        end
    end

    if name_target ~= "" then
        if integration.access:can(5) then
            enqueue_query("iplog", name_target, { role = "authorizations" })
        end
        enqueue_query("log", name_target, { role = "punishments" })
        enqueue_query("offst", name_target, { role = "offline_stats" })
        enqueue_query("baninfo", admget_target ~= "" and admget_target or name_target, { role = "baninfo" })
    end

    if #pending_queries > 0 then
        set_status(("Сбор связанных данных: в очереди %d"):format(#pending_queries))
    else
        set_status("Профиль обновлён")
    end
end

local function fill_account_summary_target(current, source_kind, dialog, source_query)
    local title = strip_color_tags(dialog.title)

    current.updated_at = os.time()
    if trim(source_query) ~= "" then
        current.source_query = trim(source_query)
    end
    if trim(title) ~= "" then
        current.nick = title
    end
    if current.target == "" then
        current.target = trim(title) ~= "" and title or trim(source_query)
    end
    mark_account_source(current, source_kind)

    for _, line in ipairs(split_lines(dialog.text)) do
        for _, part in ipairs(explode_line(line)) do
            local label, value = part:match("^(.-):%s*(.*)$")
            if not label then
                local notes={['Доп. банк. счетов нет']={'Доп. банковские счета','Нет'},
                    ['Не состоит в партии']={'Партия','Не состоит'},
                    ['Нет водного и воздушного транспорта']={'Водный и воздушный транспорт','Нет'}}
                local known=notes[trim(part)]
                if known then label,value=known[1],known[2]end
            end
            if label and trim(label)~='' and value then
                local clean_label = trim(label)
                local clean_value = trim(value)
                local display_value=clean_value~=''and clean_value or '—'
                local rendered = ("%s: %s"):format(clean_label, display_value)
                upsert_profile_row(
                    current,
                    clean_label,
                    display_value,
                    rendered,
                    tone_for_profile_row(clean_label, clean_value, rendered)
                )
                apply_profile_field(current, clean_label, clean_value)
            else
                append_unique_note_row(current, trim(part), tone_for_raw_line(part))
            end
        end
    end

    if current.target == "" then
        current.target = current.account ~= "" and current.account or title
    end
    if current.nick == "" then
        current.nick = current.target
    end
    if current.source_query == "" then
        current.source_query = current.target
    end

    refresh_clean_activity_rows(current)
    register_ip_links_for_current(current)
    build_geo_compare_rows(current)
    table.insert(current.raw_dialogs, 1, {
        kind = source_kind,
        title = trim(dialog.title),
        text = tostring(dialog.text or ""),
    })
    while #current.raw_dialogs > 8 do
        table.remove(current.raw_dialogs)
    end
end

parse_account_dialog = function(kind, dialog)
    local source_kind = (kind == "admget") and "admget" or ((kind == "get") and "get" or "account")
    local source_query = ""
    if active_query and (active_query.kind == "get" or active_query.kind == "admget") then
        source_query = active_query.value
    else
        local context = maybe_get_context()
        if context and (context.kind == "get" or context.kind == "admget") then
            source_query = context.value
        end
    end

    local title = strip_color_tags(dialog.title)
    local seed = trim(source_query) ~= "" and trim(source_query) or title
    local preview_role = get_active_query_role()

    if preview_role == "account_preview" then
        local preview = account_session_matches(account_preview, source_query, title) and account_preview or new_session(seed)
        preview.source = "get"
        fill_account_summary_target(preview, source_kind, dialog, source_query)
        account_preview = preview
        account_preview_window_state[0] = true
        complete_query("account")
        return
    end

    if preview_role == "registration_preview" then
        local preview = account_session_matches(registration_preview, source_query, title) and registration_preview or new_session(seed)
        preview.source = "get"
        preview.get_only_mode = true
        fill_account_summary_target(preview, source_kind, dialog, source_query)
        registration_preview = preview
        registration_preview_window_state[0] = true
        complete_query("account")
        return
    end

    local merge_into_current = source_kind == "admget" and account_session_matches(session, source_query, title)
    local current = merge_into_current and ensure_session(seed) or new_session(seed)

    if not merge_into_current then
        if account_session_matches(session, source_query, title) then
            current.history_auto = session.history_auto
        end
        session = current
    end

    set_buffer_text(query_input, current.target)
    fill_account_summary_target(current, source_kind, dialog, source_query)
    main_window_state[0] = true
    complete_query("account")

    if current.get_only_mode then
        set_status("Профиль /get получен")
    elseif auto_collect_state[0] then
        build_full_collection_queue(current)
    else
        set_status("Профиль получен")
    end
end

local function extract_ip_from_text(text)
    return trim((tostring(text or "")):match("(%d+%.%d+%.%d+%.%d+)") or "")
end

extract_account_target_from_text = function(text)
    local clean = strip_color_tags(text)
    if clean == "" or is_ip(clean) then
        return ""
    end
    if clean:find("[%[%]|:]") or clean:find("^Нет") or clean:find("^Ошибка") or clean:find("^IP%s") or clean:find("^GEO%s") then
        return ""
    end
    if clean:find("%s") then
        return ""
    end
    if clean:match("^[%w_%-]+$") then
        return clean
    end
    return ""
end

function get_account_ban_lookup(target)
    local clean_target = trim(strip_color_tags(target or ""))
    local cache_key = normalize_identity(clean_target)
    if cache_key == "" then
        return nil
    end
    return ban_lookup_cache[cache_key]
end

function set_account_ban_lookup(target, is_banned, details)
    local clean_target = trim(strip_color_tags(target or ""))
    local cache_key = normalize_identity(clean_target)
    if cache_key == "" then
        return nil
    end

    local payload = details or {}
    ban_lookup_cache[cache_key] = {
        target = clean_target,
        nickname = trim(payload.nickname or ""),
        is_banned = is_banned and true or false,
        pending = false,
        checked_at = os.time(),
        reason = trim(payload.reason or ""),
        admin = trim(payload.admin or ""),
        days_left = trim(payload.days_left or ""),
        ip = trim(payload.ip or ""),
        message = trim(payload.message or ""),
        raw = trim(payload.raw or ""),
    }
    return ban_lookup_cache[cache_key]
end

function mark_account_ban_lookup_pending(target)
    local clean_target = trim(strip_color_tags(target or ""))
    local cache_key = normalize_identity(clean_target)
    if cache_key == "" then
        return nil
    end

    local existing = ban_lookup_cache[cache_key] or {
        target = clean_target,
    }
    existing.target = clean_target
    existing.pending = true
    ban_lookup_cache[cache_key] = existing
    return existing
end

function collect_section_account_targets(sections)
    local targets = {}
    local seen = {}

    for _, section in ipairs(collect_ordered_sections(sections) or {}) do
        for _, row in ipairs(section.rows or {}) do
            local account_target = trim(row and (row.account or row.nick) or "")
            if account_target == "" then account_target = extract_account_target_from_text(row and row.text or "") end
            local cache_key = normalize_identity(account_target)
            if cache_key ~= "" and not seen[cache_key] then
                seen[cache_key] = true
                table.insert(targets, account_target)
            end
        end
    end

    return targets
end

function summarize_account_ban_checks(targets)
    local summary = {
        total = 0,
        checked = 0,
        pending = 0,
        banned = 0,
    }

    for _, target in ipairs(targets or {}) do
        summary.total = summary.total + 1
        local entry = get_account_ban_lookup(target)
        if entry then
            if entry.pending then
                summary.pending = summary.pending + 1
            else
                summary.checked = summary.checked + 1
                if entry.is_banned then
                    summary.banned = summary.banned + 1
                end
            end
        end
    end

    return summary
end

reset_requested_query_flag = function(kind, value)
    local clean_kind = trim(kind or "")
    local clean_value = trim(value or "")
    if clean_kind == "" or clean_value == "" then
        return
    end

    local current = ensure_session()
    current.requested[("%s|%s"):format(clean_kind, clean_value)] = nil
end

filter_pending_batch_queries = function(kind, value, role)
    local clean_kind = trim(kind or "")
    local clean_value = trim(value or "")
    local clean_role = trim(role or "")
    if clean_kind == "" or clean_value == "" or #pending_queries == 0 then
        return
    end

    local filtered = {}
    for _, query in ipairs(pending_queries) do
        local query_role = trim(((query.meta or {}).role) or "")
        if trim(query.kind or "") == clean_kind
            and trim(query.value or "") == clean_value
            and (clean_role == "" or query_role == clean_role) then
        else
            table.insert(filtered, query)
        end
    end
    pending_queries = filtered
end

is_same_active_batch_query = function(kind, value, role)
    if not active_query then
        return false
    end

    local active_role = trim(((active_query.meta or {}).role) or "")
    return trim(active_query.kind or "") == trim(kind or "")
        and trim(active_query.value or "") == trim(value or "")
        and active_role == trim(role or "")
end

register_batch_retry_tracker = function(bucket, source_label, targets)
    local clean_bucket = trim(bucket or "")
    local clean_source = trim(source_label or "")
    if clean_bucket == "" or clean_source == "" then
        return
    end

    local unique_targets = {}
    local seen = {}
    for _, target in ipairs(targets or {}) do
        local clean_target = trim(strip_color_tags(target or ""))
        local cache_key = normalize_identity(clean_target)
        if cache_key ~= "" and not seen[cache_key] then
            seen[cache_key] = true
            table.insert(unique_targets, clean_target)
        end
    end

    batch_retry_trackers[clean_bucket] = batch_retry_trackers[clean_bucket] or {}
    batch_retry_trackers[clean_bucket][clean_source] = {
        source = clean_source,
        targets = unique_targets,
        attempts = 0,
        max_attempts = 1,
    }
end

retry_missing_batch_checks = function()
    if active_query or #pending_queries > 0 then
        return false
    end

    local queued = 0

    for source, tracker in pairs(batch_retry_trackers.offst or {}) do
        local missing = {}
        for _, target in ipairs(tracker.targets or {}) do
            local entry = get_account_offst_lookup(target)
            if not offst_lookup_has_result(entry) then
                table.insert(missing, target)
            end
        end

        if #missing > 0 and (tonumber(tracker.attempts or 0) or 0) < (tonumber(tracker.max_attempts or 1) or 1) then
            tracker.attempts = (tonumber(tracker.attempts or 0) or 0) + 1
            for _, target in ipairs(missing) do
                reset_requested_query_flag("offst", target)
                filter_pending_batch_queries("offst", target, "offst_batch")
                mark_account_offst_lookup_pending(target)
                enqueue_query("offst", target, {
                    role = "offst_batch",
                    source = source,
                    retry_count = 0,
                    final_pass = tracker.attempts,
                })
                queued = queued + 1
            end
            set_server_notice(("Повторная проверка статистики: аккаунтов %d"):format(#missing), "muted", 6.0)
            set_status(("Повторный запрос статистики: аккаунтов %d"):format(#missing))
            return true
        end

        if #missing == 0 or (tonumber(tracker.attempts or 0) or 0) >= (tonumber(tracker.max_attempts or 1) or 1) then
            batch_retry_trackers.offst[source] = nil
        end
    end

    for source, tracker in pairs(batch_retry_trackers.ban or {}) do
        local missing = {}
        for _, target in ipairs(tracker.targets or {}) do
            local entry = get_account_ban_lookup(target)
            if not entry or entry.pending then
                table.insert(missing, target)
            end
        end

        if #missing > 0 and (tonumber(tracker.attempts or 0) or 0) < (tonumber(tracker.max_attempts or 1) or 1) then
            tracker.attempts = (tonumber(tracker.attempts or 0) or 0) + 1
            for _, target in ipairs(missing) do
                reset_requested_query_flag("baninfo", target)
                filter_pending_batch_queries("baninfo", target, "ban_check")
                mark_account_ban_lookup_pending(target)
                enqueue_query("baninfo", target, {
                    role = "ban_check",
                    source = source,
                    retry_count = 0,
                    final_pass = tracker.attempts,
                })
                queued = queued + 1
            end
            set_server_notice(("Повторная проверка блокировок: аккаунтов %d"):format(#missing), "muted", 6.0)
            set_status(("Повторный запрос блокировок: аккаунтов %d"):format(#missing))
            return true
        end

        if #missing == 0 or (tonumber(tracker.attempts or 0) or 0) >= (tonumber(tracker.max_attempts or 1) or 1) then
            batch_retry_trackers.ban[source] = nil
        end
    end

    return queued > 0
end

function request_baninfo_for_accounts(targets, source_label, force_refresh)
    if not ensure_script_access() then
        return 0
    end

    register_batch_retry_tracker("ban", source_label, targets)

    local queued = 0
    local role = "ban_check"
    for _, target in ipairs(targets or {}) do
        local clean_target = trim(strip_color_tags(target or ""))
        if clean_target ~= "" then
            if force_refresh then
                reset_requested_query_flag("baninfo", clean_target)
                filter_pending_batch_queries("baninfo", clean_target, role)
            end
            local entry = get_account_ban_lookup(clean_target)
            if force_refresh or not (entry and entry.pending) then
                if is_same_active_batch_query("baninfo", clean_target, role) then
                    mark_account_ban_lookup_pending(clean_target)
                else
                mark_account_ban_lookup_pending(clean_target)
                enqueue_query("baninfo", clean_target, {
                    role = role,
                    source = trim(source_label or ""),
                })
                queued = queued + 1
                end
            end
        end
    end

    if queued > 0 then
        set_status(("Проверка блокировок: в очереди %d"):format(queued))
        set_server_notice(("Очередь /baninfo: %d"):format(queued), "muted", 6.0)
    elseif #(targets or {}) == 0 then
        set_server_notice("Нет аккаунтов для проверки блокировок.", "muted", 6.0)
    else
        set_server_notice("Эти аккаунты уже проверяются.", "muted", 6.0)
    end

    return queued
end

function get_account_offst_lookup(target)
    local clean_target = trim(strip_color_tags(target or ""))
    local cache_key = normalize_identity(clean_target)
    if cache_key == "" then
        return nil
    end
    local entry = offst_lookup_cache[cache_key]
    if entry and entry.pending then
        local pending_since = tonumber(entry.pending_since) or 0
        if pending_since > 0 and os.clock() - pending_since >= math.max(OFFST_QUERY_TIMEOUT + 6.0, 18.0) then
            entry.pending = false
            entry.pending_since = nil
            if trim(entry.message or "") == "" then
                entry.message = "Время ожидания /offst истекло"
            end
            offst_lookup_cache[cache_key] = entry
        end
    end
    return entry
end

function set_account_offst_lookup(target, details)
    local clean_target = trim(strip_color_tags(target or ""))
    local cache_key = normalize_identity(clean_target)
    if cache_key == "" then
        return nil
    end

    local payload = details or {}
    offst_lookup_cache[cache_key] = {
        target = clean_target,
        nickname = trim(payload.nickname or ""),
        pending = false,
        pending_since = nil,
        checked_at = os.time(),
        level = trim(payload.level or ""),
        organization = trim(payload.organization or ""),
        raw = trim(payload.raw or ""),
        message = trim(payload.message or ""),
    }
    return offst_lookup_cache[cache_key]
end

offst_lookup_has_result = function(entry)
    if not entry or entry.pending then
        return false
    end

    return trim(entry.level or "") ~= ""
        or trim(entry.organization or "") ~= ""
        or trim(entry.raw or "") ~= ""
end

function mark_account_offst_lookup_pending(target)
    local clean_target = trim(strip_color_tags(target or ""))
    local cache_key = normalize_identity(clean_target)
    if cache_key == "" then
        return nil
    end

    local existing = offst_lookup_cache[cache_key] or {
        target = clean_target,
    }
    existing.target = clean_target
    existing.pending = true
    existing.pending_since = os.clock()
    offst_lookup_cache[cache_key] = existing
    return existing
end

function collect_row_account_targets(rows)
    local targets = {}
    local seen = {}

    for _, row in ipairs(rows or {}) do
        local account_target = trim(row and (row.account or row.nick) or "")
            if account_target == "" then account_target = extract_account_target_from_text(row and row.text or "") end
        local cache_key = normalize_identity(account_target)
        if cache_key ~= "" and not seen[cache_key] then
            seen[cache_key] = true
            table.insert(targets, account_target)
        end
    end

    return targets
end

function summarize_account_offst_checks(targets)
    local summary = {
        total = 0,
        checked = 0,
        pending = 0,
    }

    for _, target in ipairs(targets or {}) do
        summary.total = summary.total + 1
        local entry = get_account_offst_lookup(target)
        if entry then
            if entry.pending then
                summary.pending = summary.pending + 1
            elseif offst_lookup_has_result(entry) then
                summary.checked = summary.checked + 1
            end
        end
    end

    return summary
end

function request_offst_for_accounts(targets, source_label, force_refresh)
    if not ensure_script_access() then
        return 0
    end

    register_batch_retry_tracker("offst", source_label, targets)

    local queued = 0
    local role = "offst_batch"
    for _, target in ipairs(targets or {}) do
        local clean_target = trim(strip_color_tags(target or ""))
        if clean_target ~= "" then
            if force_refresh then
                reset_requested_query_flag("offst", clean_target)
                filter_pending_batch_queries("offst", clean_target, role)
            end
            local entry = get_account_offst_lookup(clean_target)
            if force_refresh or not (entry and entry.pending) then
                if is_same_active_batch_query("offst", clean_target, role) then
                    mark_account_offst_lookup_pending(clean_target)
                else
                mark_account_offst_lookup_pending(clean_target)
                enqueue_query("offst", clean_target, {
                    role = role,
                    source = trim(source_label or ""),
                })
                queued = queued + 1
                end
            end
        end
    end

    if queued > 0 then
        set_status(("Проверка статистики: в очереди %d"):format(queued))
        set_server_notice(("Очередь /offst: %d"):format(queued), "muted", 6.0)
    elseif #(targets or {}) == 0 then
        set_server_notice("Нет аккаунтов для проверки статистики.", "muted", 6.0)
    else
        set_server_notice("Статистика этих аккаунтов уже запрошена.", "muted", 6.0)
    end

    return queued
end

local function format_account_offst_brief(target)
    local entry = get_account_offst_lookup(target)
    if not entry then
        return ""
    end
    if entry.pending then
        return " [статистика загружается…]"
    end

    local parts = {}
    local level = trim(entry.level or "")
    local organization = trim(entry.organization or "")
    if level ~= "" then
        table.insert(parts, "ур. " .. level)
    end
    if organization ~= "" and organization ~= "Нет" and organization ~= "-" then
        table.insert(parts, shorten_text(organization, 22))
    elseif level ~= "" then
        table.insert(parts, "без фракции")
    end

    if #parts == 0 then
        return ""
    end

    return " [" .. table.concat(parts, " | ") .. "]"
end

