function get_online_player_id_for_account(account_label)
    local normalized = normalize_identity(account_label)
    if normalized == "" then
        return nil
    end

    local local_found, local_player_id = sampGetPlayerIdByCharHandle(PLAYER_PED)
    if local_found and local_player_id ~= nil then
        local local_nickname = strip_color_tags(cp1251_to_utf8(sampGetPlayerNickname(local_player_id) or ""))
        if normalize_identity(local_nickname) == normalized then
            return local_player_id
        end
    end

    for player_id = 0, 1003 do
        if (not local_player_id or player_id ~= local_player_id) and sampIsPlayerConnected(player_id) then
            local nickname = strip_color_tags(cp1251_to_utf8(sampGetPlayerNickname(player_id) or ""))
            if normalize_identity(nickname) == normalized then
                return player_id
            end
        end
    end

    return nil
end


local function pump_query_queue()
    local now = os.clock()

    if active_query and now - active_query.sent_at >= (tonumber(active_query.timeout) or QUERY_TIMEOUT) then
        local expired_kind = active_query.kind
        local expired_value = trim(active_query.value or "")
        local expired_role = get_active_query_role()
        if expired_kind == "offst" and expired_role == "offst_batch" and expired_value ~= "" then
            set_account_offst_lookup(expired_value, {
                message = "Нет ответа /offst",
            })
        end
        push_error(("Нет ответа на %s"):format(format_command(active_query.kind, active_query.value)))
        active_query = nil
        internal_command_guard = nil
        last_query_action_at = now
        force_next_query_immediately = false
    end

    if active_query ~= nil then
        return
    end

    if now < (tonumber(flood_cooldown_until or 0) or 0) then
        return
    end

    if #pending_queries == 0 then
        if retry_missing_batch_checks() then
            return
        end
        if session and session.history_auto and now-last_query_action_at>=QUERY_DELAY and not (history_preview and history_preview.loading)then
            local target=trim(session.nick or '')
            if target==''then target=trim(session.target or '')end
            -- Account numbers are not player IDs; wait for the profile to resolve a nickname.
            if target~='' and not tonumber(target)then
                session.history_auto=false;standalone_history=false
                request_nick_history(target)
            end
        end
        return
    end

    if not force_next_query_immediately and now - last_query_action_at < QUERY_DELAY then
        return
    end

    if pending_queries[1] and integration.queryBusy and integration.queryBusy(pending_queries[1].kind) then
        return
    end
    local next_query = table.remove(pending_queries, 1)
    if next_query then
        force_next_query_immediately = false
        send_query_now(next_query.kind, next_query.value, next_query.meta)
    end
end

local function register_commands()
    local function register(name, callback)
        sampRegisterChatCommand(name, function(params)
            if name=='namestore' then standalone_history=true
            elseif name=='reg' or name=='offreg' then standalone_registration=true
            elseif name=='cip' then standalone_ip=true
            elseif name=='clip' then standalone_lip=true
            else integration.open('lookup') end
            callback(params)
        end)
    end
    register("cadm", function() end)

    register("cget", function(params)
        start_lookup("get", cp1251_to_utf8(params or ""))
    end)

    register("reg", function(params)
        local target = cp1251_to_utf8(params or "")
        local clean_target = trim(strip_color_tags(target))
        if clean_target == "" then
            chat("Использование: /reg <ID игрока>", 0xE0C36A)
            return
        end

        local player_id = tonumber(clean_target)
        if player_id == nil then
            chat("/reg работает только по числовому ID игрока.", 0xE0C36A)
            return
        end

        player_id = math.floor(player_id)
        if not sampIsPlayerConnected(player_id) then
            chat(("Игрок с ID %d сейчас не в игре."):format(player_id), 0xE57373)
            return
        end

        local nickname = strip_color_tags(cp1251_to_utf8(sampGetPlayerNickname(player_id) or ""))
        if nickname == "" then
            chat(("Не удалось получить ник игрока с ID %d."):format(player_id), 0xE57373)
            return
        end

        request_registration_lookup(nickname)
    end)

    register("offreg", function(params)
        local target = trim(strip_color_tags(cp1251_to_utf8(params or "")))
        if target == "" then
            chat("Использование: /offreg <ник или номер аккаунта>", 0xE0C36A)
            return
        end

        request_registration_lookup(target)
    end)

    register("namestore", function(params)
        request_nick_history(cp1251_to_utf8(params or ""))
    end)

    register("cip", function(params)
        local target = trim(strip_color_tags(cp1251_to_utf8(params or "")))
        if target == "" then
            chat("Использование: /cip <IP-адрес>", 0xE0C36A)
            return
        end
        if not is_ip(target) then
            chat("Введите корректный IPv4-адрес: /cip <IP-адрес>.", 0xE57373)
            return
        end

        request_ip_preview(target)
    end)

    register("clip", function(params)
        local target = trim(strip_color_tags(cp1251_to_utf8(params or "")))
        if target == "" then
            chat("Использование: /clip <IP-адрес>", 0xE0C36A)
            return
        end
        if not is_ip(target) then
            chat("Введите корректный IPv4-адрес: /clip <IP-адрес>.", 0xE57373)
            return
        end

        request_lip_preview(target)
    end)

    register("cas", function(params)
        local target = cp1251_to_utf8(params or "")
        local clean_target = trim(strip_color_tags(target))
        if clean_target == "" then
            chat("Использование: /cas <ID игрока>", 0xE0C36A)
            return
        end
        local player_id = tonumber(clean_target)
        if player_id == nil then
            chat("/cas принимает ID игрока. Для ника или номера аккаунта используйте /cget.", 0xE0C36A)
            return
        end
        player_id = math.floor(player_id)
        if not sampIsPlayerConnected(player_id) then
            chat(("Игрок с ID %d сейчас не в игре."):format(player_id), 0xE57373)
            return
        end

        local nickname = strip_color_tags(cp1251_to_utf8(sampGetPlayerNickname(player_id) or ""))
        if nickname == "" then
            chat(("Не удалось получить ник игрока с ID %d."):format(player_id), 0xE57373)
            return
        end

        start_lookup("get", nickname)
    end)
end


function sampev.onSendCommand(command)
    local owner = integration.commandOwner and integration.commandOwner()
    if owner and owner ~= 'lookup' then return end
    local raw = strip_color_tags(cp1251_to_utf8(command or ""))
    if raw == "" then
        return
    end

    local normalized = raw:lower()
    if internal_command_guard and normalized == internal_command_guard then
        internal_command_guard = nil
        return
    end

    local kind, value = raw:match("^/?([^%s]+)%s*(.*)$")
    kind = kind and kind:lower() or ""
    value = strip_color_tags(value)

    if not SUPPORTED_COMMANDS[kind] then
        return
    end

    stop_all_checks("Проверка остановлена ручной командой")

    return
end

function sampev.onServerMessage(color, text)
    syncAccess()
    if message_reports_flood(text or "") and (active_query ~= nil or #pending_queries > 0 or command_context ~= nil or main_window_state[0] or main_window_minimized) then
        if handle_flood_message(text or "") then
            return false
        end
        flood_cooldown_until = math.max(tonumber(flood_cooldown_until or 0) or 0, os.clock() + 5.0)
        last_query_action_at = flood_cooldown_until
        force_next_query_immediately = false
        set_server_notice(strip_color_tags(cp1251_to_utf8(text or "")), "muted", 6.0)
        return false
    end
    if handle_flood_message(text or "") then
        return false
    end
    if handle_empty_result_message(text or "") then
        return false
    end
end

function sampev.onShowDialog(dialog_id, style, title, button1, button2, text)
    syncAccess()
    if not integration.access:can(1) then return end
    local dialog = {
        id = tonumber(dialog_id) or 0,
        style = tonumber(style) or 0,
        title = strip_color_tags(cp1251_to_utf8(title or "")),
        button1 = cp1251_to_utf8(button1 or ""),
        button2 = cp1251_to_utf8(button2 or ""),
        text = cp1251_to_utf8(text or ""),
    }

    if looks_like_history_dialog(dialog.title) and history_preview and history_preview.loading then
        return handle_history_dialog(dialog)
    end

    local kind = detect_dialog_kind(dialog)
    if not kind or not is_command_allowed_for_admin(kind) then
        return
    end

    if kind == "get" or kind == "admget" or kind == "account" then
        parse_account_dialog(kind, dialog)
        return false
    end

    if kind == "iplog" then
        parse_iplog_dialog(dialog)
        return false
    end

    if kind == "ip" or kind == "lip" then
        upsert_ip_section(kind, dialog)
        return false
    end

    if kind == "log" then
        parse_log_dialog(dialog)
        return false
    end

    if kind == "baninfo" then
        parse_baninfo_dialog(dialog)
        return false
    end

    if kind == "offst" then
        parse_offst_dialog(dialog)
        return false
    end

    if kind == "ip_related" then
        upsert_ip_section("ip", dialog)
        return false
    end
end

function integration.start()
    repeat
        wait(200)
    until isSampAvailable()

    load_config()
    ensure_storage_artifacts()
    register_commands()

    while true do
        wait(0)
        if integration.update then integration.update() end
        pump_query_queue()
    end
end

-- All controls are drawn inside CasualTool. Only the host owns windows/scrolling.
View = {page = 'profile', pages = {}, selected = nil, preview = 'ip',
    filter = imgui.new.char[96](), target = nil, confirmBan = nil}

function View.selectPage(page)
    View.page, View.selected, View.selectedId, View.confirmBan = page, nil, nil, nil
    set_buffer_text(View.filter, '')
end

function View.beginLookup()
    View.selectPage('profile')
    View.detailReturn=nil
    View.pendingScroll=0
    View.pages, View.target, View.inlinePreview = {}, nil, false
    for _, state in ipairs({ip_preview_window_state, lip_preview_window_state, ipwhois_preview_window_state,
        ip_accounts_window_state, account_preview_window_state, registration_preview_window_state, history_window_state}) do
        state[0] = false
    end
    integration.open('lookup')
end

function View.button(label, action, same)
    local width = imgui.CalcTextSize(label:match('^(.-)##') or label).x + 30
    if not same then
        View.rowMax = imgui.GetContentRegionAvail().x
        View.rowWidth = width
    elseif (View.rowWidth or 0) + width + 10 <= (View.rowMax or 0) then
        imgui.SameLine(); View.rowWidth = View.rowWidth + width + 10
    else
        View.rowWidth = width
    end
    if imgui.Button(label) then action() end
end

function View.append(rows, title, values)
    if not values or #values == 0 then return end
    rows[#rows + 1] = {text = title, tone = 'accent', heading = true}
    for _, row in ipairs(values) do rows[#rows + 1] = row end
end

function View.profileRows(current)
    local rows = {}
    if current then
        View.append(rows, 'Аккаунт', current.profile_rows)
        View.append(rows, 'Примечания', current.note_rows)
        View.append(rows, 'Статистика аккаунта', current.offst_rows)
        View.append(rows, 'Блокировки', current.ban_rows)
        View.append(rows, 'Сравнение IP', current.geo_compare_rows)
        View.append(rows, 'Сохранённые связи аккаунтов', current.geo_saved_rows)
        View.append(rows, 'Ошибки запроса', current.errors)
    end
    return rows
end

function View.currentRows()
    if View.page == 'profile' then return View.profileRows(session) end
    if View.page == 'history' then return history_preview and history_preview.rows or {} end
    if View.page == 'auth' then return session and session.auth_rows or {} end
    if View.page == 'punish' then return session and session.punish_rows or {} end
    local rows = {}
    if View.page == 'ips' and session then
        for _, kind in ipairs({'ip', 'lip'}) do
            for _, section in ipairs(collect_session_sections_by_kind(session, kind)) do
                rows[#rows + 1] = {text = section.title or kind, ip = section.ip, tone = 'accent'}
                for _, row in ipairs(section.rows or {}) do rows[#rows + 1] = row end
            end
        end
    elseif View.page == 'details' then
        if View.preview == 'account' then return View.profileRows(account_preview)
        elseif View.preview == 'registration' then return View.profileRows(registration_preview)
        elseif View.preview == 'accounts' then
            for _, nick in ipairs(get_ip_account_labels(View.target or '')) do
                rows[#rows + 1] = {text = nick, account = nick}
            end
        else
            local preview = session and session[View.preview .. '_preview']
            if preview then
                rows[#rows + 1] = {text = preview.title or preview.ip, ip = preview.ip, tone = 'accent'}
                for _, row in ipairs(preview.rows or {}) do rows[#rows + 1] = row end
            end
        end
    elseif View.page == 'raw' and session then
        for _, dialog in ipairs(session.raw_dialogs or {}) do
            rows[#rows + 1] = {text = (dialog.kind or '') .. ': ' .. (dialog.title or ''), heading = true, tone = 'accent'}
            for _, line in ipairs(split_lines(dialog.text)) do rows[#rows + 1] = {text = line} end
        end
    end
    return rows
end

function View.openPreview(kind, target)
    local returnScroll=View.detailReturn or imgui.GetScrollY()
    View.selectPage('details')
    View.detailReturn=returnScroll
    View.inlinePreview=true
    View.pendingScroll=0
    View.preview, View.target = kind, target
    if kind == 'ip' then request_ip_preview(target)
    elseif kind == 'lip' then request_lip_preview(target)
    elseif kind == 'ipwhois' then request_ipwhois_preview(target, false)
    elseif kind == 'account' then request_account_preview(target)
    elseif kind == 'registration' then request_registration_lookup(target) end
end

function View.actions(row)
    if not row or row.heading then return end
    imgui.Separator()
    imgui.TextWrapped(tostring(row.text or ''))
    View.button('Копировать строку##lookup_copy_row', function() copy_to_clipboard(row.text) end)
    local ip = trim(row.ip or extract_ip_from_text(row.text))
    if ip ~= '' then
        View.button('/ip##lookup_ip', function() View.openPreview('ip', ip) end, true)
        View.button('/lip##lookup_lip', function() View.openPreview('lip', ip) end, true)
        View.button('Геоданные##lookup_geo', function() View.openPreview('ipwhois', ip) end, true)
        View.button('Связанные аккаунты##lookup_links', function() View.openPreview('accounts', ip) end, true)
        if not row.account and not row.nick then return end
    end
    local account = trim(row.account or row.nick or extract_account_target_from_text(row.text))
    if account == '' then return end
    imgui.TextDisabled(account .. format_account_offst_brief(account))
    View.button('Регистрационные данные##lookup_registration', function() View.openPreview('registration', account) end)
    View.button('Открыть профиль##lookup_account', function() View.openPreview('account', account) end)
    View.button('Проверить аккаунт##lookup_collect', function() start_lookup('get', account); View.selectPage('profile') end, true)
    View.button('Проверить блокировки##lookup_ban', function() request_baninfo_for_accounts({account}, 'Выбранный аккаунт', true) end, true)
    View.button('Запросить статистику##lookup_offst', function() request_offst_for_accounts({account}, 'Выбранный аккаунт', true) end, true)
    local online = get_online_player_id_for_account(account)
    if online then imgui.TextColored(THEME.good, 'В игре: ID ' .. online) end
    View.button('/sban · 30 дней##lookup_sban', function() View.confirmBan = account end)
    if View.confirmBan == account then
        imgui.TextWrapped('Заблокировать ' .. account .. ' на 30 дней с причиной «До выяснений.»?')
        View.button('Заблокировать на 30 дней##lookup_confirm_sban', function() send_sban_for_account(account); View.confirmBan = nil end)
        View.button('Отменить##lookup_cancel_sban', function() View.confirmBan = nil end, true)
    end
end

function View.rows(rows)
    imgui.Text('Фильтр результатов')
    imgui.PushItemWidth(math.min(360, imgui.GetContentRegionAvail().x - 20))
    if imgui.InputText('##lookup_filter', View.filter, ffi.sizeof(View.filter)) then
        View.pages[View.page], View.selected = 1, nil
    end
    imgui.PopItemWidth()
    local query, filtered = lower_text(get_buffer_text(View.filter)), {}
    for _, row in ipairs(rows) do
        if query == '' or lower_text(row.text):find(query, 1, true) then filtered[#filtered + 1] = row end
    end
    local total = math.max(1, math.ceil(#filtered / 12))
    local page = math.min(total, math.max(1, View.pages[View.page] or 1))
    View.pages[View.page] = page
    View.button('<##lookup_prev', function() View.pages[View.page] = math.max(1, page - 1); View.selected = nil end)
    imgui.SameLine(); imgui.Text(('Страница %d / %d · строк: %d'):format(page, total, #filtered))
    View.button('>##lookup_next', function() View.pages[View.page] = math.min(total, page + 1); View.selected = nil end, true)
    imgui.Separator()
    if #filtered == 0 then imgui.TextDisabled('Нет результатов. Выполните проверку или измените фильтр.') end
    for index = (page - 1) * 12 + 1, math.min(page * 12, #filtered) do
        local row = filtered[index]
        View.readableRow('lookup_row_' .. index, row)
    end
end

-- A dossier is a structured page, not a paginated dump of unrelated rows.
-- Cards remain in the host's scroll flow; their text is never truncated.
function View.heading(title, count)
    imgui.Spacing()
    imgui.PushStyleColor(imgui.Col.Text,THEME.accent)
    imgui.TextWrapped(title .. (count and (' · ' .. count) or ''))
    imgui.PopStyleColor()
    imgui.Separator()
end

function View.readableRow(id, row)
    local text = tostring(row.text or '')
    if text == '' then return end
    local account=trim(row.account or row.nick or '')
    if account=='' and not row.heading and not row.ip then account=extract_account_target_from_text(text)end
    local tone=row.tone or 'normal'
    if account~='' and not id:find('_ban_',1,true)then
        text=text..format_account_offst_brief(account)
        local ban=get_account_ban_lookup(account)
        if ban and ban.is_banned and not ban.pending then tone='alert' end
    end
    local selectionKey = id .. '\0' .. text
    imgui.PushID(id)
    imgui.PushStyleColor(imgui.Col.Text, row_text_color(tone))
    imgui.TextWrapped(text)
    imgui.PopStyleColor()
    if not row.heading then
        if imgui.IsItemClicked(0) then View.selected, View.selectedId = row, selectionKey; View.confirmBan = nil end
        if imgui.IsItemHovered() then imgui.SetTooltip('Нажмите: копирование и действия с аккаунтом или IP') end
        if View.selected and View.selectedId == selectionKey then
            View.selected = row
            View.actions(row)
        end
    end
    imgui.PopID()
end

function View.accountChecks(targets, id)
    if #targets == 0 then return end
    local canStats=is_command_allowed_for_admin('offst');local canBans=is_command_allowed_for_admin('baninfo')
    if canStats and canBans then
        View.button('Проверить всё##lookup_all_'..id,function()
            request_offst_for_accounts(targets,id,true);request_baninfo_for_accounts(targets,id,true)
        end)
    end
    if is_command_allowed_for_admin('offst') then
        View.button('Уровни и фракции##lookup_stats_' .. id, function()
            request_offst_for_accounts(targets, id, true)
        end,canStats and canBans)
    end
    if is_command_allowed_for_admin('baninfo') then
        View.button('Действующие баны##lookup_bans_' .. id, function()
            request_baninfo_for_accounts(targets, id, true)
        end,canStats)
        local state = summarize_account_ban_checks(targets)
        local stats,waiting=0,0
        for _,target in ipairs(targets)do local entry=get_account_offst_lookup(target)
            if entry and entry.pending then waiting=waiting+1 elseif offst_lookup_has_result(entry)then stats=stats+1 end
        end
        imgui.TextWrapped(('Уровни и фракции: %d/%d · ожидают: %d   |   Баны: %d/%d · ожидают: %d · найдено: %d'):format(stats,#targets,waiting,state.checked,state.total,state.pending,state.banned))
    end
end

function View.ui()
    if not View.caseUi then
        View.caseArt=integration.service('art.lua').new(imgui,integration.base,_G)
        View.caseUi=integration.service('dossier_ui.lua').new(imgui,integration,function(name)return View.caseArt:get(name)end)
    end
    return View.caseUi
end

function View.pick(row,id)
    View.selected,View.selectedId,View.confirmBan=row,id,nil
    View.selectionReturn=imgui.GetScrollY()
    View.pendingScroll=0
end

function View.cardRows(id,title,rows,empty,x,y,w)
    return View.ui().rows(id,title,rows,empty,function(row)View.pick(row,id)end,x,y,w)
end

function View.rowActions(account,id,origin)
    local key=id..'_'..account;local actions={}
    local function add(suffix,label,tip,click,tone)
        actions[#actions+1]={id='lookup_row_'..key..'_'..suffix,label=label,tooltip=tip,click=click,tone=tone}
    end
    add('copy','Копия','Копировать исходную строку аккаунта',function()copy_to_clipboard(origin.text or account)end)
    add('profile','Профиль','Открыть профиль; возврат сохранит место в списке',function()View.openPreview('account',account)end)
    add('registration','Рег. данные','Открыть регистрационные данные аккаунта',function()View.openPreview('registration',account)end)
    add('collect','Полная проверка','Открыть новое личное дело этого аккаунта',function()start_lookup('get',account)end)
    add('stats','Ур. / фракция','Запросить уровень и фракцию только этого аккаунта',function()request_offst_for_accounts({account},key,true)end)
    add('ban','Баны','Проверить действующую блокировку только этого аккаунта',function()request_baninfo_for_accounts({account},key,true)end)
    if is_command_allowed_for_admin('sban')then
        if View.confirmBan==key then
            add('confirm','Подтвердить бан','/sban '..account..' 30 До выяснений.',function()View.confirmBan=nil;send_sban_for_account(account)end,'alert')
            add('cancel','Отмена','Отменить блокировку',function()View.confirmBan=nil end)
        else
            add('sban','/sban · 30 дн.','Показать подтверждение блокировки на 30 дней',function()View.confirmBan=key end,'alert')
        end
    end
    if origin.ip and is_ip(origin.ip)then
        add('ip','/ip','Аккаунты, зарегистрированные с этого IP',function()View.openPreview('ip',origin.ip)end)
        add('lip','/lip','Аккаунты, входившие с этого IP',function()View.openPreview('lip',origin.ip)end)
        add('geo','Геоданные','Открыть геоданные IP',function()View.openPreview('ipwhois',origin.ip)end)
        add('links','Связи','Сохранённые аккаунты по этому IP',function()View.openPreview('accounts',origin.ip)end)
    end
    return {actions=actions,note=View.confirmBan==key and ('Бан '..account..' на 30 дней. Причина: «До выяснений.»')or nil}
end

function View.accountTable(targets,id,title,sourceRows,includeIp)
    local rows={}
    for _,target in ipairs(includeIp and sourceRows or targets)do
        local account=type(target)=='table' and target.account or target
        local stat=get_account_offst_lookup(account)
        local ban=get_account_ban_lookup(account)
        local banText,tone='Не проверено','muted'
        if ban then
            if ban.pending then banText='Проверяется…'
            elseif ban.is_banned then
                banText='Действующий бан · '..(ban.days_left~='' and ban.days_left..' дн.' or 'срок не указан')..
                    '\nАдминистратор: '..(ban.admin~='' and ban.admin or 'не указан')..
                    '\nПричина: '..(ban.reason~='' and ban.reason or 'не указана');tone='alert'
            else
                banText=ban.message~='' and ban.message or 'Действующих банов нет';tone='good'
                if lower_text(banText):find('не найден в банлисте',1,true)then banText='Действующих банов нет'end
            end
        end
        local origin=type(target)=='table' and target or nil
        for _,row in ipairs(origin and {} or sourceRows or {})do
            if normalize_identity(row.account or row.nick or extract_account_target_from_text(row.text or ''))==normalize_identity(account)then origin=row;break end
        end
        origin=origin or {text=account,account=account}
        local function choose()View.openPreview('account',account)end
        local cells={
            {text=includeIp and account or origin.text or account,tone=ban and ban.is_banned and not ban.pending and 'alert' or 'accent',click=choose},
            {text=stat and (stat.pending and '…' or stat.level~='' and stat.level or '—')or '—'},
            {text=stat and (stat.pending and 'Проверяется…'or stat.organization~='' and stat.organization or stat.message~='' and stat.message or 'Не получена')or 'Не проверена'},
            {text=banText,tone=tone},
            View.rowActions(account,id..(origin.ip or ''),origin)}
        if includeIp then table.insert(cells,2,{text=origin.ip or '—',tone='accent',click=function()View.openPreview('ip',origin.ip)end})end
        rows[#rows+1]=cells
    end
    local columns={{label='Аккаунт',weight=1.1},{label='Ур.',weight=.32},{label='Фракция',weight=.8},{label='Блокировка',weight=1.3},{label='Действия с аккаунтом',weight=3.4,actions=true}}
    if includeIp then table.insert(columns,2,{label='IP адрес',weight=.9})end
    View.ui().table(id,title,columns,rows,'Аккаунты не найдены.')
end

function View.logTable(id,title,source,empty)
    local rows={}
    for index,row in ipairs(source or {})do
        local origin=row
        rows[#rows+1]={tostring(index),{text=row.text,tone=row.tone,click=function()View.pick(origin,id..index)end}}
    end
    View.ui().table(id,title,{{label='№',weight=.2},{label='Запись',weight=4}},rows,empty)
end

function View.authTable(current)
    local rows,other={},{}
    for index,entry in ipairs(current.auth_entries or {})do
        local date,time,ip=trim(entry.date or ''),trim(entry.time or ''),trim(entry.ip or '')
        if date~='' or time~='' or ip~=''then
            rows[#rows+1]={tostring(index),date~='' and date or '—',time~='' and time or '—',
                {text=ip~='' and ip or '—',tone='accent',click=is_ip(ip)and function()View.openPreview('ip',ip)end or nil}}
        else other[#other+1]={text=entry.raw_text or entry.full_text or '',tone='muted'}end
    end
    View.ui().table('dossier_auth','06 / Авторизации',{{label='№',weight=.25},{label='Дата',weight=1},{label='Время',weight=.7},{label='IP',weight=1.5}},rows,'История входов ещё не получена.')
    if #(current.auth_entries or {})==0 then other=current.auth_rows or {}end
    if #other>0 then View.cardRows('auth_other','Дополнительные сведения об авторизациях',other,'')end
end

function View.commandCard(current,kind)
    local title=kind=='ip' and 'Регистрации с IP · /ip' or 'Входы с IP · /lip'
    local sections=collect_session_sections_by_kind(current,kind)
    local targets=collect_section_account_targets(sections)
    View.heading(title,#targets)
    View.button('Обновить /'..kind..'##lookup_links_refresh_'..kind,function()
        local ips,seen={},{}
        local function add(ip,slot)if is_ip(ip or '')and not seen[ip]then ips[#ips+1]={ip=ip,slot=slot};seen[ip]=true end end
        add(current.reg_ip,current.reg_ip==current.last_ip and 'shared'or 'reg');add(current.last_ip,'last')
        for _,section in ipairs(sections)do add(section.ip,section.slot_key)end
        for _,item in ipairs(ips)do
            local waiting=active_query and active_query.kind==kind and active_query.value==item.ip
            for _,query in ipairs(pending_queries)do if query.kind==kind and query.value==item.ip then waiting=true end end
            if not waiting then reset_requested_query_flag(kind,item.ip);enqueue_query(kind,item.ip,{slot_key=item.slot})end
        end
        if #ips==0 then set_server_notice('Сначала получите IP из профиля игрока.','muted',5)end
    end)
    View.accountChecks(targets,kind)
    if #sections==0 then View.cardRows('empty_'..kind,title,{},'Ответ /'..kind..' пока не получен.');return end
    for index,section in ipairs(sections)do
        local rows=section.rows or {}
        View.accountTable(collect_row_account_targets(rows),kind..index,section.title or section.ip or title,rows)
        -- Keep non-account notices from the server visible as well.
        local notices={}
        for _,row in ipairs(rows)do if #collect_row_account_targets({row})==0 then notices[#notices+1]=row end end
        if #notices>0 then View.cardRows(kind..'_notes'..index,'Ответ сервера',notices,'')end
    end
end

function View.geoTable(current,x,y,w)
    local rows={};local u=View.ui()
    local reg,last=current.reg_ip or '',current.last_ip or ''
    local a,b=ipwho_cache[reg],ipwho_cache[last]
    local function geo(info,key,ip)
        if ip==''then return 'Не получен IP'end
        if pending_geo[ip] or info and info.pending then return key=='country' and 'Загрузка геоданных…'or '—'end
        if not info then return 'Не загружено'end
        if info.success==false then return key=='country' and ('Не загружено: '..(info.message or 'ошибка запроса'))or '—'end
        return trim(info[key]or '')~='' and tostring(info[key])or 'Не указано'
    end
    local function ipCell(ip)
        return {text=ip~='' and ip or 'Не получен',tone='accent',click=ip~='' and function()View.pick({text=ip,ip=ip},'geo')end or nil}
    end
    rows[1]={'IP адрес',ipCell(reg),ipCell(last)}
    for _,spec in ipairs({{'Страна','country'},{'Регион','region'},{'Город','city'},{'Провайдер','isp'}})do
        rows[#rows+1]={spec[1],geo(a,spec[2],reg),geo(b,spec[2],last)}
    end
    local pos=u.cursor();x,y,w=x or pos.x,y or pos.y,w or imgui.GetContentRegionAvailWidth()
    local height=u.table('case_geo','03 / Регистрационные данные · IP и география',{{label='Данные',weight=.8},{label='Регистрация',weight=1.1},{label='Последний вход',weight=1.1}},rows,'Ожидание IP из профиля…',x,y,w)
    if is_ip(reg)or is_ip(last)then
        local label='Обновить геоданные IP';local bh=math.max(32*u.scale(),u.measure(label,w-44,14)+16*u.scale())
        imgui.SetCursorPos(imgui.ImVec2(x+12,y+height+8))
        if imgui.Button(label..'##lookup_retry_geo',imgui.ImVec2(w-24,bh))then
            local seenIp={};for _,ip in ipairs({reg,last})do
                if is_ip(ip)and not seenIp[ip]then lookup_ipwhois(ip,true);seenIp[ip]=true end
            end;geo_changed=true
        end
        if imgui.IsItemHovered()then imgui.SetTooltip('Страна, город и провайдер определяются по IP через ipwho.is. Данные /get и /admget эта кнопка не обновляет.')end
        height=height+bh+16;u.finish(x,y,w,height)
    end
    return height
end

function View.bans(current)
    local rows=current.ban_rows or {}
    if imgui.GetContentRegionAvailWidth()<1000*View.ui().scale() or #rows<2 or #rows>6 then
        return View.cardRows('dossier_bans','04 / Проверка блокировок · BANINFO',rows,'Блокировка ещё не проверена.')
    end
    local columns,values={},{}
    for index,row in ipairs(rows)do
        columns[index]={label=row.label or 'Сведения',weight=row.label=='Причина' and 1.6 or 1}
        local source=row
        values[index]={text=row.value or row.text,tone=row.tone,click=function()View.pick(source,'ban')end}
    end
    View.ui().table('dossier_bans','04 / Проверка блокировок · BANINFO',columns,{values},'')
end

function View.dossier(current,complete)
    local u=View.ui()
    if not current then
        u.banner('Проверка игрока','Введите ник или номер аккаунта выше.','Данные появятся после ответа сервера.')
        return
    end
    local name=trim(current.nick or '')~='' and current.nick or current.target or 'Аккаунт'
    local meta=('Аккаунт № %s  ·  Уровень: %s  ·  %s'):format(current.account~='' and current.account or '—',current.level~='' and current.level or '—',format_time(current.updated_at))
    u.banner(name,meta,current.status or 'Ожидание данных')
    if not integration.access:can(3)then
        View.cardRows('basic_profile','01 / Основные сведения · OFFST',current.offst_rows,'Ожидание /offst…')
        imgui.TextDisabled('IP и расширенные сведения доступны с 3 уровня.');return
    end
    -- Keep server sources separate: identical labels may describe different data.
    local profile,stats={},{}
    for _,row in ipairs(current.profile_rows or {})do
        local key=lower_text(row.label or row.text or '')
        local repeatedIp=row.value and (row.value==current.reg_ip or row.value==current.last_ip) and key:find('ip',1,true)
        if not repeatedIp then profile[#profile+1]=row end
    end
    for _,row in ipairs(current.offst_rows or {})do stats[#stats+1]=row end
    for _,row in ipairs(current.note_rows or {})do
        profile[#profile+1]={label='Дополнительно',value=row.text,text=row.text,tone=row.tone}
    end
    local start=u.cursor();local width=imgui.GetContentRegionAvailWidth();local gap=12
    local wide=width>=1000*u.scale();local pair=not wide and width>=680*u.scale()
    local firstW=wide and (width-gap*2)*.30 or pair and (width-gap)*.5 or width
    local secondW=wide and (width-gap*2)*.30 or firstW
    local h1=u.rows('case_profile','01 / Профиль аккаунта · GET / ADMGET',profile,'Ожидание ответа /get или /admget…',function(row)View.pick(row,'profile')end,start.x,start.y,firstW)
    local h2=u.rows('case_stats','02 / Статистика игрока · OFFST',stats,'Статистика ещё не получена.',function(row)View.pick(row,'stats')end,
        (wide or pair)and start.x+firstW+gap or start.x,(wide or pair)and start.y or start.y+h1+gap,secondW)
    local bottom=start.y+((wide or pair)and math.max(h1,h2)or h1+gap+h2)
    local comparison={}
    for _,row in ipairs(current.geo_compare_rows or {})do
        local t=row.text or ''
        if t:find('Расстояние',1,true) or t:find('Разница:',1,true) or t:find('IP совпадают',1,true) or t:find('IP разные',1,true)then comparison[#comparison+1]=row end
    end
    local regGeo,lastGeo=ipwho_cache[current.reg_ip or ''],ipwho_cache[current.last_ip or '']
    if current.reg_ip~='' and current.last_ip~='' and current.reg_ip~=current.last_ip and
        (not regGeo or not lastGeo or regGeo.success==false or lastGeo.success==false)then
        comparison={{text='IP различаются; геоданные ещё не получены.',tone='muted'}}
    end
    if wide then
        local thirdX=start.x+firstW+secondW+gap*2;local thirdW=width-firstW-secondW-gap*2
        local h3=View.geoTable(current,thirdX,start.y,thirdW)
        if #comparison>0 then h3=h3+gap+View.cardRows('dossier_geo','Сравнение IP',comparison,'',thirdX,start.y+h3+gap,thirdW)end
        bottom=math.max(bottom,start.y+h3)
        u.finish(start.x,start.y,width,bottom-start.y)
    else
        u.finish(start.x,start.y,width,bottom-start.y)
        View.geoTable(current)
        if #comparison>0 then View.cardRows('dossier_geo','Сравнение IP',comparison,'')end
    end
    View.bans(current)
    if #(current.errors or {})>0 then View.cardRows('dossier_errors','Ошибки и таймауты',current.errors,'')end
    if not complete then return end
    View.heading('05 / Связанные аккаунты')
    imgui.TextWrapped('Проверки всех аккаунтов — над списком. Действия с одним аккаунтом — в его строке.')
    View.commandCard(current,'ip');View.commandCard(current,'lip')
    local saved,seenAccounts={},{}
    for _,ip in ipairs({current.reg_ip or '',current.last_ip or ''})do
        for _,account in ipairs(get_ip_account_labels(ip))do
            local key=normalize_identity(account)..'@'..ip
            if not seenAccounts[key]then saved[#saved+1]={text=account..' — '..ip,account=account,ip=ip};seenAccounts[key]=true end
        end
    end
    View.heading('История совпадений по IP',#saved)
    View.accountChecks(collect_row_account_targets(saved),'saved')
    View.accountTable({},'saved','Сохранённые связи аккаунтов',saved,true)
    imgui.TextDisabled('Совпадение IP не доказывает общего владельца.')
    if integration.access:can(5)then View.authTable(current)end
    View.logTable('dossier_punish','07 / Наказания',current.punish_rows,'История наказаний ещё не получена.')
    View.button('Обновить историю ников##lookup_history',function()
        request_nick_history(name);standalone_history=false
    end)
    local historyRows={};local historyStatus=current.history_auto and 'История загрузится автоматически после текущих запросов.' or 'Нет загруженной истории. Можно повторить запрос.'
    if history_preview and normalize_identity(history_preview.target)==normalize_identity(name)then
        historyStatus=history_preview.status or 'Записей нет.'
        for index,row in ipairs(history_preview.rows or {})do historyRows[#historyRows+1]={tostring(index),row.date,{text=row.nick~='' and row.nick or row.text,tone=row.tone}}end
    end
    u.table('case_history','08 / История ников',{{label='№',weight=.2},{label='Дата изменения',weight=1},{label='Никнейм',weight=2}},historyRows,historyStatus)
end

function integration.draw()
    if not config then imgui.TextDisabled('Ожидание подключения к серверу…');return end
    if View.pendingScroll then imgui.SetScrollY(View.pendingScroll);View.pendingScroll=nil end
    local width=imgui.GetContentRegionAvailWidth();local busy=active_query~=nil or #pending_queries>0
    local buttonW=imgui.CalcTextSize('Проверить').x+28
    imgui.TextDisabled('Ник или номер аккаунта')
    imgui.PushItemWidth(math.max(80,width-buttonW-12))
    imgui.InputText('##lookup_target',query_input,ffi.sizeof(query_input));imgui.PopItemWidth();imgui.SameLine()
    if imgui.Button('Проверить##lookup_start',imgui.ImVec2(buttonW,32))then start_lookup('get',get_buffer_text(query_input));View.selectPage('profile')end
    if busy then
        View.button('Остановить##lookup_stop',function()stop_all_checks('Проверка остановлена')end)
        imgui.SameLine();imgui.TextDisabled(('В очереди: %d · %s'):format(#pending_queries,active_query and 'Получение /'..active_query.kind or 'Подготовка запроса'))
    end
    if server_notice.expires>os.clock()then imgui.TextWrapped(server_notice.text)end
    if clipboard_notice.expires>os.clock()then imgui.TextColored(THEME.good,'Скопировано в буфер обмена')end
    if not integration.access:can(3)then View.page='profile' end
    View.button('Обновить##lookup_refresh',function()start_lookup('get',session and (session.source_query or session.target)or get_buffer_text(query_input));View.selectPage('profile')end)
    View.button('Копировать досье##lookup_copy',function()copy_to_clipboard(compose_full_dossier_dump(session))end,true)
    View.button('Сохранить в TXT##lookup_export',function()
        local path,err=export_session_dossier(session);set_server_notice(path and 'Сохранено: '..path or err or 'Нет данных',path and 'good' or 'alert',6)
    end,true)
    View.button('Сводка в /a##lookup_share',function()send_admin_chat_summary(session)end,true)
    View.button('Очистить результаты##lookup_reset',function()stop_all_checks();session=nil;account_preview=nil;registration_preview=nil;View.selectPage('profile')end,true)
    View.button('Как проверить игрока##lookup_help',function()integration.openHelp('lookup')end,true)
    View.button('Свернуть окно##lookup_compact_minimize',function()main_window_minimized=true end,true)
    if View.selected then
        View.heading('Действия с выбранной записью')
        View.actions(View.selected)
        View.button('Вернуться к записи##lookup_close_selection',function()
            View.selected=nil;View.confirmBan=nil;View.pendingScroll=View.selectionReturn or 0
        end)
    end
    if View.page=='details' then
        View.button('Вернуться к личному делу##lookup_back',function()
            View.selectPage('profile');View.pendingScroll=View.detailReturn or 0;View.detailReturn=nil
        end)
        if View.preview=='account' or View.preview=='registration'then
            View.dossier(View.preview=='account' and account_preview or registration_preview,false)
        else
            if View.preview=='ipwhois' and View.target then View.button('Обновить геоданные##lookup_geo_refresh',function()request_ipwhois_preview(View.target,true)end)end
            View.cardRows('case_detail','Подробные сведения',View.currentRows(),'Ожидание ответа сервера…')
        end
    else
        View.dossier(session,true)

    end
end

-- Use one scroll flow at every size; standalone command windows keep their own renderers below.
local render_compact_dossier = integration.draw

function integration.drawSettings()
    if not config then imgui.TextDisabled('Ожидание подключения к серверу…'); return end
    if imgui.Checkbox('Собирать связанные данные при проверке игрока##lookup_auto', auto_collect_state) then
        save_config()
        if not auto_collect_state[0] then stop_all_checks('Автосбор выключен') end
    end
    imgui.TextWrapped('Автосбор отправляет только доступные вашему уровню запросы. Основные сведения — с 1 уровня, IP и связанные аккаунты — с 3, /admget — с 5. Отключение отменяет текущую очередь запросов.')
    
    
    View.button('Справка по проверке игрока##lookup_settings_help', function() integration.openHelp('lookup') end)
end

function integration.update()
    syncAccess()
    for ip, state in pairs(pending_geo) do
        if state.completed then state.finish(true)
        elseif os.clock() - state.started > 12 then state.finish(false, 'ipwho.is не ответил за 12 секунд') end
    end
    if geo_changed then
        geo_changed = false
        for _, current in pairs({session = session, account = account_preview, registration = registration_preview}) do
            build_geo_compare_rows(current)
            if current.ipwhois_preview then
                local preview = current.ipwhois_preview
                preview.info = ipwho_cache[preview.ip]
                preview.rows = build_ipwhois_rows(preview.ip, preview.info)
            end
        end
    end
    if history_preview and history_preview.loading and os.clock() - (history_preview.started_at or 0) > 20 then
        history_preview.loading = false; history_preview.status = 'История: время ожидания истекло'
    end
end

function integration.onDisconnect(reason)
    accessRevision = integration.access:revision()
    lookup_generation = lookup_generation + 1
    stop_all_checks(reason or 'Соединение прервано')
    history_collect, history_preview = nil, nil
    session, account_preview, registration_preview = nil, nil, nil
    for ip, state in pairs(pending_geo) do os.remove(state.path); ipwho_cache[ip] = nil end
    pending_geo = {}
    View.selected, View.confirmBan = nil, nil
end

function integration.stop()
    integration.onDisconnect()
    if View.caseArt then View.caseArt:shutdown();View.caseArt,View.caseUi=nil,nil end
    if sql_conn then pcall(function() sql_conn:close() end); sql_conn = nil end
    if sql_env then pcall(function() sql_env:close() end); sql_env = nil end
end

function integration.lookupState()
    return {page = View.page, target = session and session.target, queued = #pending_queries,
        active = active_query and active_query.kind, autoCollect = auto_collect_state[0],
        profileRows = session and #session.profile_rows or 0, historyRows = history_preview and #history_preview.rows or 0}
end

-- Share ownership with modules that use the same native server response.
function integration.queryPending(kind)
    return kind == 'offst' and active_query ~= nil and active_query.kind == kind
end


