    imgui.PopItemWidth()

    imgui.SameLine()
    push_primary_button_colors()
    if imgui.Button("Пробив", imgui.ImVec2(probe_button_width, 24)) then
        start_lookup("get", get_buffer_text(query_input))
    end
    imgui.PopStyleColor(3)

    if server_notice.expires > os.clock() and trim(server_notice.text) ~= "" then
        imgui.SameLine()
        imgui.TextColored(row_text_color(server_notice.tone), shorten_text(server_notice.text, 78))
    end

    push_secondary_button_colors()
    if imgui.Button("Обновить", imgui.ImVec2(92, 24)) then
