function draw_wrapped_copyable_row(id, text, tone, compact)
    local value = trim(text)
    if value == "" then
        value = "-"
    end

    imgui.PushIDStr(tostring(id))
    imgui.PushStyleColor(imgui.Col.Text, row_text_color(tone or "normal"))
    imgui.TextWrapped(value)
    imgui.PopStyleColor(1)

    if imgui.IsItemClicked() then
        copy_to_clipboard(value)
    end
    if imgui.IsItemHovered() then
        imgui.BeginTooltip()
        imgui.Text("ЛКМ - скопировать строку")
        imgui.EndTooltip()
    end

    if not compact then
        imgui.Spacing()
    end
    imgui.PopID()
end

