        return
    end

    local accounts = get_ip_account_labels(clean_ip)
    if #accounts == 0 then
        imgui.TextDisabled("Этот IP еще не встречался в локальной базе аккаунтов.")
        return
    end

    imgui.TextColored(THEME.muted, ("Этот IP встречался у %d людей"):format(#accounts))
    imgui.SameLine()
    if draw_action_chip(("%s_accounts_btn"):format(id_prefix), "Люди", "accent", "Показать список аккаунтов по этому IP") then
        open_ip_accounts_preview(clean_ip)
    end
end

function render_ip_accounts_window()
    if not ip_accounts_window_state[0] then
        return
    end

    local preview = ip_accounts_preview
    imgui.SetNextWindowSize(imgui.ImVec2(360, 320), imgui.Cond.FirstUseEver)
    imgui.Begin("X-Tools — Аккаунты по IP###CasualTool — Аккаунты по IP", ip_accounts_window_state, imgui.WindowFlags.NoCollapse)

    if preview and is_ip(preview.ip or "") then
        imgui.TextColored(THEME.gold, "Аккаунты по IP")
        imgui.SameLine()
        draw_copy_chip("ip_accounts_ip_copy", preview.ip, preview.ip, "accent", "Скопировать IP")
        imgui.TextColored(THEME.muted, ("IP: %s"):format(preview.ip))
        local online_count = 0
        for _, account_label in ipairs(preview.accounts or {}) do
            if get_online_player_id_for_account(account_label) ~= nil then
                online_count = online_count + 1
            end
        end
        imgui.TextColored(THEME.muted, ("Найдено людей: %d"):format(#(preview.accounts or {})))
        if online_count > 0 then
            imgui.TextColored(THEME.good, ("Онлайн: %d"):format(online_count))
        end
        imgui.Separator()
        if preview.accounts and #preview.accounts > 0 then
            for index, account_label in ipairs(preview.accounts) do
                local row_id = ("ip_accounts_%d"):format(index)
                local online_id = get_online_player_id_for_account(account_label)
                local display_label = online_id and ("%s (ID: %d)"):format(account_label, online_id) or account_label
                local ban_entry = get_account_ban_lookup(account_label)
                local row_tone = online_id and "good" or "normal"
                if ban_entry and ban_entry.is_banned then
                    row_tone = "alert"
                end
                draw_clickable_text_row(row_id, display_label, row_tone)
                draw_account_actions_inline(row_id, account_label)
            end
        else
            imgui.TextDisabled("Нет связанных аккаунтов")
        end
    else
        imgui.TextDisabled("Нет данных по IP.")
    end

    imgui.End()
end

function render_history_window()
    if not history_window_state[0] then return end
    if history_focus_requested then
        imgui.SetNextWindowFocus();history_focus_requested=false
    end
    local preview=history_preview
    local sw,sh=getScreenResolution()
    imgui.SetNextWindowSize(imgui.ImVec2(math.min(700,sw-40),math.min(680,sh-80)),imgui.Cond.FirstUseEver)
    imgui.Begin("X-Tools — Личное дело · История ников###CasualTool — История ников",history_window_state,imgui.WindowFlags.NoCollapse)
    local u=View.ui()
    if preview then
        local target=trim(preview.target or '')
        local status=preview.status or (preview.loading and 'Собираю страницы истории…' or ('Собрано записей: '..tostring(#(preview.rows or {}))))
        local updated=preview.updated_at and ('Обновлено: '..format_time(preview.updated_at))or 'Обновление ещё не завершено'
        u.banner(target~=''and target or 'Игрок не указан','История ников · '..updated,status)
        View.button('Копировать',function()copy_to_clipboard(compose_rows_dump(preview.rows or {}),'История ников')end)
        if target~=''then View.button('Обновить /namestore',function()request_nick_history(target)end,true)end
        imgui.Spacing()
        imgui.TextDisabled('ЛКМ по дате или никнейму — скопировать значение.')
        local rows={}
        for index,row in ipairs(preview.rows or {})do
            local date=trim(row.date or '')
            local nick=trim(row.nick or '')
            local value=nick~=''and nick or (row.text or '—')
            rows[#rows+1]={tostring(index),{text=date~=''and date or '—',tone='muted',click=function()copy_to_clipboard(date~=''and date or value)end},
                {text=value,tone=row.tone or 'normal',click=function()copy_to_clipboard(value)end}}
        end
        u.table('history_dossier','01 / Хронология переименований',{{label='№',weight=.25},{label='Дата',weight=1},{label='Никнейм',weight=2}},rows,
            preview.loading and 'Собираю страницы истории…'or 'История ников пуста.')
    else
        u.banner('История ников','Приложение к личному делу','Данные ещё не получены')
        imgui.TextDisabled('Запросите историю командой /namestore [ник].')
    end
    imgui.End()
end

function render_account_preview_window()
    if not account_preview_window_state[0] then
        return
    end

    local preview = account_preview
    imgui.SetNextWindowSize(imgui.ImVec2(620, 620), imgui.Cond.FirstUseEver)
    imgui.Begin("X-Tools — Профиль аккаунта###CasualTool — Профиль аккаунта", account_preview_window_state, imgui.WindowFlags.NoCollapse)

    if preview then
        imgui.TextColored(THEME.gold, preview.nick ~= "" and preview.nick or "Неизвестный аккаунт")
        if preview.account ~= "" then
            imgui.SameLine()
            imgui.TextDisabled("№ " .. preview.account)
        end
        imgui.TextColored(THEME.muted, "Обновлено: " .. format_time(preview.updated_at))
        imgui.Separator()

        push_secondary_button_colors()
        if imgui.Button("Lookup", imgui.ImVec2(82, 22)) then
            lookup_account_in_main(preview.target ~= "" and preview.target or preview.nick)
        end
        imgui.PopStyleColor(3)

        imgui.SameLine()
        push_secondary_button_colors()
        if imgui.Button("Обновить", imgui.ImVec2(96, 22)) then
            request_account_preview(preview.nick ~= "" and preview.nick or preview.target)
        end
        imgui.PopStyleColor(3)

        imgui.SameLine()
        push_secondary_button_colors()
        if imgui.Button("Копировать", imgui.ImVec2(100, 22)) then
            copy_to_clipboard(compose_session_dump(preview), "Сводка профиля")
        end
        imgui.PopStyleColor(3)

        imgui.Spacing()
        local preview_available = imgui.GetContentRegionAvail()
        local section_gap = 8
        local preview_geo_pref = estimate_card_height_by_rows(
            count_list_rows(preview and preview.geo_compare_rows or nil),
            1,
            120,
            math.max(140, math.floor(preview_available.y * 0.36)),
            66,
            20,
            8
        )
        local preview_heights = distribute_vertical_heights(preview_available.y, section_gap, {
            {
                min = 280,
                preferred = estimate_summary_card_height(preview, preview_available.y),
                grow = true,
            },
            {
                min = 120,
                preferred = preview_geo_pref,
            },
        })
        local summary_height = preview_heights[1] or math.max(300, preview_available.y - section_gap - preview_geo_pref)
        local geo_height = preview_heights[2] or preview_geo_pref
        if imgui.BeginChild("account_preview_summary", imgui.ImVec2(0, summary_height), true) then
            draw_section_header("Профиль", "")

            local content = imgui.GetContentRegionAvail()
            local gap = 8
            local left_width, right_width = calc_summary_split_widths(preview, content.x)

            if imgui.BeginChild("account_preview_profile_left", imgui.ImVec2(left_width, 0), false) then
                draw_rows("account_preview_profile_rows", preview.profile_rows, "Нет данных профиля")
                if #preview.note_rows > 0 then
                    imgui.Spacing()
                    draw_rows("account_preview_notes", preview.note_rows, "")
                end
                if #preview.errors > 0 then
                    draw_section_header("Ошибки / таймауты", "")
                    draw_rows("account_preview_errors", preview.errors, "")
                end
            end
            imgui.EndChild()

            imgui.SameLine(0, gap)
            if imgui.BeginChild("account_preview_profile_right", imgui.ImVec2(right_width, 0), false) then
                if should_show_baninfo_summary(preview) then
                    local right_available = imgui.GetContentRegionAvail()
                    local split_heights = distribute_vertical_heights(right_available.y, gap, {
                        {
                            min = 170,
                            preferred = math.max(200, math.floor(right_available.y * 0.66)),
                            grow = true,
                        },
                        {
                            min = 110,
                            preferred = math.max(118, math.floor(right_available.y * 0.34)),
                        },
                    })
                    render_offst_summary_card(preview, 0, split_heights[1] or 0)
                    imgui.Dummy(imgui.ImVec2(0, gap))
                    render_baninfo_summary_card(preview, 0, split_heights[2] or 0, "account_preview_baninfo_rows")
                else
                    render_offst_summary_card(preview, 0, 0)
                end
            end
            imgui.EndChild()
        end
        imgui.EndChild()

        imgui.Spacing()
        render_geo_compare_card(preview, 0, geo_height)
    else
        imgui.TextDisabled("Нажми Профиль рядом с нужным аккаунтом.")
    end

    imgui.End()
end

