settings.positions = settings.positions or {}
settings.features = settings.features or {enabled=true}
enabled = settings.features.enabled

function cp1251_to_utf8(str)
    return tostring(u8(str or ''))
end

function utf8_to_cp1251(str)
    return u8:decode(tostring(str or ''))
end

local function chat(text, color)
    if isSampAvailable() then
        sampAddChatMessage(utf8_to_cp1251(PREFIX .. tostring(text or '')), color or 0xFFFFFF)
    end
end

local function send_chat(text)
    local value = tostring(text or '')
    if value ~= '' then
        sampSendChat(utf8_to_cp1251(value))
    end
end

local function process_input(text)
    local value = tostring(text or '')
    if value ~= '' then
        sampProcessChatInput(utf8_to_cp1251(value))
    end
end

local function load_fonts()
    if fonts_ready then return end
    for _,size in ipairs({12,13,14,16,18,20,22,24}) do
        fonts[size]=integration.fontFace(size,false)
        bold_fonts[size]=integration.fontFace(size,true)
    end
    fonts_ready=fonts[14]~=nil
end

function imgui.BeforeDrawFrame()
    load_fonts()
end

local function push_font(size, bold)
    local font = (bold and bold_fonts[size]) or fonts[size] or fonts[14]
    if font then
        imgui.PushFont(font)
        return true
    end
    return false
end

local function pop_font(pushed)
    if pushed then
        imgui.PopFont()
    end
end

local function normalize_text(value)
    local text = tostring(value or '')
    if text == '' then
        return ''
    end
    return cp1251_to_utf8(text)
end

-- Server menu labels may use color codes, padding or spaced-out lettering.
-- Normalize labels only; keep each original server row index intact.
local function menu_key(value)
    local text=tostring(value or ''):match('^[^%z]*') or ''
    return text:gsub('{%x+}',''):gsub('~.-~',''):gsub('[%s_%-]',''):lower()
end

local function try_api(name, ...)
    local fn = _G[name]
    if type(fn) ~= 'function' then return nil end
    local ok, a, b, c = pcall(fn, ...)
    if ok then return a, b, c end
end

local function finite_number(value)
    local number = tonumber(value)
    if number and number == number and math.abs(number) < math.huge then return number end
end

local function field(data, key)
    local ok, value = pcall(function() return data[key] end)
    if ok then return value end
end

local function as_boolean(value)
    if value == true or value == 1 then return true end
    if value == false or value == 0 then return false end
end

local function format_number(value, decimals)
    local number = finite_number(value)
    if number == nil then return '-' end
    return string.format('%.' .. tostring(decimals or 0) .. 'f', number)
end

local function trim_text(value)
    return tostring(value or ''):gsub('{%x%x%x%x%x%x%x%x}', ''):gsub('{%x%x%x%x%x%x}', ''):match('^%s*(.-)%s*$')
end

local function parse_sp_message(message)
    local clean = trim_text(message)
    local nickname, id, rest = clean:match('^%[SP%]%s+([^%[%]]+)%[(%d+)%]%s*|%s*(.*)$')
    id = tonumber(id)
    if not id or id > 1003 then return nil end
    local segments = {}
    for part in (rest .. '|'):gmatch('(.-)|') do segments[#segments + 1] = trim_text(part) end
    if not segments[1] or not segments[1]:match('^PING%s+%d+$')
        or not segments[2] or not segments[2]:match('^IP%s+') then return nil end
    local raw_client = segments[3]
    if raw_client and raw_client:match('^Выход:') then raw_client = nil
    elseif not segments[4] or not segments[4]:match('^Выход:') then return nil end
    return { id = id, nickname = trim_text(nickname), raw_client = raw_client,
        ping = tonumber(segments[1]:match('%d+$')) }
end

local function sync_speed(data)
    local speed = field(data, 'moveSpeed')
    if speed == nil then return nil end
    local x, y, z = finite_number(field(speed, 'x')), finite_number(field(speed, 'y')), finite_number(field(speed, 'z'))
    if not x or not y or not z then return nil end
    return math.sqrt(x * x + y * y + z * z) * SERVER_SYNC_SPEED_SCALE
end

local function extract_menu_items(columns)
    local items = {}
    if type(columns) ~= 'table' or type(columns[1]) ~= 'table' or type(columns[1].text) ~= 'table' then
        return items
    end

    for index, raw in ipairs(columns[1].text) do
        items[#items + 1] = {
            row = index - 1,
            label = normalize_text(raw)
        }
    end

    return items
end

