local function try_get_samp_vehicle_handle(vehicle_id)
    if not sampGetCarHandleBySampVehicleId then
        return nil
    end

    local ok, a, b = pcall(sampGetCarHandleBySampVehicleId, vehicle_id)
    if not ok then
        return nil
    end

    if type(a) == 'boolean' then
        return a and b or nil
    end

    return a
end

local function resolve_player_by_vehicle(vehicle_id)
    local vehicle_handle = try_get_samp_vehicle_handle(vehicle_id)
    if not vehicle_handle then
        return -1
    end

    -- A vehicle RPC alone does not identify which occupant is being observed.
    -- Use the actual driver only as fallback; a later [SP] header identifies
    -- the intended player explicitly, including a passenger.
    if try_api('doesVehicleExist', vehicle_handle) ~= true then return -1 end
    local driver = try_api('getDriverOfCar', vehicle_handle)
    if driver and try_api('doesCharExist', driver) == true then
        local found, id = try_api('sampGetPlayerIdByCharHandle', driver)
        if found and id and sampIsPlayerConnected(id) then return id end
    end
    return -1
end

local function format_elapsed_time(seconds)
    seconds = math.max(0, math.floor(tonumber(seconds) or 0))
    local minutes = math.floor(seconds / 60)
    local remainder = seconds % 60
    return string.format('%02d:%02d', minutes, remainder)
end

local function get_client_label(raw_client)
    raw_client = trim_text(raw_client)
    if raw_client == 'PC Launcher' then
        return 'Advance Launcher'
    end
    if raw_client == 'Mobile' then
        return 'Mobile'
    end
    if raw_client == '' then return 'SAMP' end
    return raw_client
end

local function get_target_id()
    if spectate_target_id >= 0 then
        return spectate_target_id
    end
    if spectate_state and spectate_vehicle_id >= 0 then
        local resolved_id = resolve_player_by_vehicle(spectate_vehicle_id)
        if resolved_id >= 0 then
            spectate_target_id = resolved_id
            return resolved_id
        end
    end
    if manual_target_id.v and manual_target_id.v >= 0 then
        return manual_target_id.v
    end
    return -1
end

local function update_observation_clock()
    local observed=get_target_id()
    local nick=observed>=0 and try_api('sampGetPlayerNickname',observed) or ''
    if spectate_state and observed>=0 and nick and nick~='' then
        if not noticeTarget or noticeTarget.id~=observed or noticeTarget.nick~=nick then
            noticeStreamToken=noticeStreamToken+1
            noticeTarget={id=observed,nick=nick,lost=false}
        end
    end
    if observed~=timed_target or nick~=timed_nickname then
        timed_target,timed_nickname,menu_open_clock=observed,nick,os.time()
    end
end

local function find_connected_id(direction, base_id)
    direction = direction or 1
    local start_id = tonumber(base_id)
    if start_id == nil then
        start_id = get_target_id()
    end
    if start_id < 0 then
        start_id = direction > 0 and -1 or 1000
    end

    for step = 1, 1000 do
        local candidate = (start_id + direction * step) % 1000
        if sampIsPlayerConnected(candidate) then
            return candidate
        end
    end

    return -1
end

local function reset_pending_spectate()
    pending_spectate_direction = 0
    pending_spectate_attempts = 0
    pending_spectate_last_id = -1
end

local function try_spectate_candidate(base_id, direction)
    local next_id = find_connected_id(direction, base_id)
    if next_id < 0 then
        reset_pending_spectate()
        chat('Нет доступных игроков для переключения слежки.', 0xAAAAFF)
        return false
    end

    pending_spectate_last_id = next_id
    pending_spectate_attempts = pending_spectate_attempts + 1
    manual_target_id.v = next_id
    queue_chat_lines({
        string.format('/sp %d', next_id)
    }, 50)
    return true
end

local function spectate_next_id(direction)
    if preview then return end
    direction = direction or 1
    pending_spectate_direction = direction
    pending_spectate_attempts = 0
    if not try_spectate_candidate(get_target_id(), direction) then
        return
    end
end

queue_chat_lines = function(lines, delay_ms)
    local token = queue_generation
    local target = get_target_id()
    local name = sampIsPlayerConnected(target) and sampGetPlayerNickname(target) or nil
    delay_ms = tonumber(delay_ms) or 250
    lua_thread.create(function()
        for index, line in ipairs(lines or {}) do
            if index > 1 then
                wait(delay_ms)
            end
            if token ~= queue_generation or not name or not sampIsPlayerConnected(target) or sampGetPlayerNickname(target) ~= name then return end
            send_chat(line)
        end
    end)
end

local function ensure_config_dir()
    storage:directory('settings')
end

local function get_screen_size()
    local ok, x, y = pcall(getScreenResolution)
    if ok and tonumber(x) and tonumber(y) then
        return tonumber(x), tonumber(y)
    end
    return 1920, 1080
end

local function clamp_window_position(x, y, width, height)
    local screen_x, screen_y = get_screen_size()
    local margin = math.min(16, math.max(0, (screen_x - width) / 2), math.max(0, (screen_y - height) / 2))
    local max_x = math.max(margin, screen_x - width - margin)
    local max_y = math.max(margin, screen_y - height - margin)
    x = math.max(margin, math.min(tonumber(x) or margin, max_x))
    y = math.max(margin, math.min(tonumber(y) or margin, max_y))
    return x, y
end

local function calculate_layout(screen_x, screen_y, action_count, has_vehicle, has_status)
    local columns=actionConfig.main.horizontal and math.max(1,math.min(action_count,math.floor((screen_x-48)/144))) or 1
    local height = 48 + math.ceil(action_count/columns) * 34
    local scale = math.max(0.1, math.min(1, (screen_x - 32) / 384, (screen_y - 32) / math.max(464, height)))
    local info_height = (has_vehicle and 432 or 300) + (has_status and 32 or 0)
    return { scale = scale, info_width = 224 * scale, info_height = info_height * scale,
        has_vehicle = has_vehicle == true, status_y = has_vehicle and 429 or 297,
        columns=columns, buttons_width = (8+136*columns) * scale, buttons_height = height * scale,
        count = action_count, action_top = 40, row_step = 34, button_height = 30 }
end

local function windows_overlap(info_pos, buttons_pos, layout)
    local gap = 16 * layout.scale
    return info_pos.x < buttons_pos.x + layout.buttons_width + gap and
        info_pos.x + layout.info_width + gap > buttons_pos.x and
        info_pos.y < buttons_pos.y + layout.buttons_height + gap and
        info_pos.y + layout.info_height + gap > buttons_pos.y
end

local function position_windows(layout)
    local sx, sy = get_screen_size()
    local function restore(pos, prefix, default_x, default_y)
        if pos.x == nil or pos.y == nil then
            local x, y = tonumber(settings.positions[prefix .. '_x']), tonumber(settings.positions[prefix .. '_y'])
            if x and y and (x ~= 0 or y ~= 0) then pos.x, pos.y = x, y
            else pos.x, pos.y = default_x, default_y end
        end
    end
    restore(buttons_window_pos, 'buttons', sx - layout.buttons_width - 16, (sy - layout.buttons_height) / 2)
    restore(info_window_pos, 'info', buttons_window_pos.x - layout.info_width - 16 * layout.scale,
        sy - layout.info_height - 96 * layout.scale)
    buttons_window_pos.x, buttons_window_pos.y = clamp_window_position(buttons_window_pos.x, buttons_window_pos.y, layout.buttons_width, layout.buttons_height)
    info_window_pos.x, info_window_pos.y = clamp_window_position(info_window_pos.x, info_window_pos.y, layout.info_width, layout.info_height)
    if windows_overlap(info_window_pos, buttons_window_pos, layout) then
        -- Preserve the independently saved heights. Only resolve the collision.
        local left = buttons_window_pos.x - layout.info_width - 16 * layout.scale
        if left < 16 then
            buttons_window_pos.x = sx - layout.buttons_width - 16
            left = buttons_window_pos.x - layout.info_width - 16 * layout.scale
        end
        info_window_pos.x = math.max(16, left)
    end
end

local function move_window_position(kind, delta, layout)
    local pos = kind == 'info' and info_window_pos or buttons_window_pos
    local width = kind == 'info' and layout.info_width or layout.buttons_width
    local height = kind == 'info' and layout.info_height or layout.buttons_height
    local x, y = clamp_window_position(pos.x + delta.x, pos.y + delta.y, width, height)
    local function allowed(px, py)
        local candidate = {x = px, y = py}
        if kind == 'info' then return not windows_overlap(candidate, buttons_window_pos, layout) end
        return not windows_overlap(info_window_pos, candidate, layout)
    end
    -- Drag each window independently; slide along an edge instead of pushing its neighbour.
    if allowed(x, y) then pos.x, pos.y = x, y
    elseif allowed(x, pos.y) then pos.x = x
    elseif allowed(pos.x, y) then pos.y = y end
end

local function save_positions()
    ensure_config_dir()
    local sx, sy = get_screen_size()
    local info = collect_target_info()
    position_windows(calculate_layout(sx, sy, 16, info.has_vehicle, info.status ~= ''))
    settings.positions.layout_version = 3
    settings.positions.buttons_x = math.floor(buttons_window_pos.x)
    settings.positions.buttons_y = math.floor(buttons_window_pos.y)
    settings.positions.info_x = math.floor(info_window_pos.x)
    settings.positions.info_y = math.floor(info_window_pos.y)
    settings.positions.dirty=nil
    storage:saveIni(settings, CONFIG_PATH)
end

local function input_blocked()
    return integration.windowOpen() or isPauseMenuActive() or (isSampAvailable() and (
        sampIsChatInputActive() or sampIsDialogActive() or sampIsScoreboardOpen()
    ))
end

local function menu_keys_down()
    if type(isKeyDown) ~= 'function' then return false end
    for _, key in ipairs({VK_UP, VK_DOWN, 0x57, 0x53, VK_LEFT, VK_RIGHT, VK_SPACE, VK_RETURN, VK_ESCAPE}) do
        if isKeyDown(key) then return true end
    end
    return false
end

local function release_input_capture()
    integration.refreshInput()
end

local function apply_imgui_runtime_flags()
    -- Mouse input belongs to the game, except while moving the windows.
    -- Arrow keys and Space are handled separately by handle_keyboard().
    local mouse_enabled = menu_active and move_mode and not input_blocked()
    imgui.LockPlayer = false
    imgui.ShowCursor = mouse_enabled
    imgui.DisableInput = not mouse_enabled
end

local function close_custom_menu()
    menu_active = false
    move_mode = false
    imgui.Process = false
    current_menu = nil
    apply_imgui_runtime_flags()
    release_input_capture()
end

local function open_custom_menu()
    menu_active = true
    move_mode = false
    keyboard_ready = not menu_keys_down()
    imgui.Process = true
    selected_action_index = 1
    local sx, sy = get_screen_size()
    local info = collect_target_info()
    position_windows(calculate_layout(sx, sy, 16, info.has_vehicle, info.status ~= ''))
    if tonumber(settings.positions.layout_version) ~= 3 then save_positions() end
    apply_imgui_runtime_flags()
    release_input_capture()
end

local function send_menu_select(row)
    if preview then chat("Это предпросмотр. Действия доступны во время слежки."); return end
    row = tonumber(row)
    if row == nil then
        return
    end

    if sampSendMenuSelect then
        sampSendMenuSelect(row)
        return
    end

    local bs = raknetNewBitStream()
    raknetBitStreamWriteInt8(bs, row)
    raknetSendRpc(132, bs)
    raknetDeleteBitStream(bs)
end

local function run_server_menu_action(name)
    local minimum=({skick=3,freeze=3,hp=4,gethere=3,['goto']=3,spawn=2,respawn=2,pull_from_water=3})[name] or 1
    if not integration.access:require(minimum,integration.message) then return end
    local row = find_menu_row(name)
    if row == nil then
        local labels={}
        for _,item in ipairs(current_menu and current_menu.items or {}) do
            labels[#labels+1]=tostring(item.row)..'='..tostring(item.label):gsub('%z',''):sub(1,64)
        end
        local detail=table.concat(labels,' | ')
        if current_menu and current_menu.failedRows~=detail then
            current_menu.failedRows=detail
            print('[X-TOOLS MENU] id='..tostring(current_menu.id)..' rows='..detail)
        end
        chat('Пункт серверного меню не найден: ' .. tostring(name), 0xAAAAFF)
        return
    end
    release_input_capture()
    send_menu_select(row)
    if not spectate_state then close_custom_menu() end
    release_input_capture()
end

local function do_custom_action(action)
    if preview then
        if action == 'close' or action == 'spoff' then close_custom_menu()
        else chat('Это предпросмотр. Действия доступны во время слежки.') end
        return
    end
    if action == 'close' then
        release_input_capture()
        send_menu_select(0)
        close_custom_menu()
        return
    end

    if action == 'spoff' then
        release_input_capture()
        process_input('/sp')
        close_custom_menu()
        return
    end

    local required=({hp=4,freeze=3,pull_from_water=3,gethere=3,['goto']=3,spawn=2,respawn=2})[action]
    if required and not integration.access:require(required,integration.message) then return end
    local target_id = get_target_id()
    if target_id < 0 then
        chat('Начните слежку за игроком, чтобы выбрать цель панели.', 0xAAAAFF)
        return
    end

    local target_in_car = false
    local streamed, ped = sampGetCharHandleBySampPlayerId(target_id)
    if streamed and ped and doesCharExist(ped) then
        target_in_car = isCharInAnyCar(ped)
    end

    if action == 'skillz' then
        if not sampIsPlayerConnected(target_id) then return end
        local nickname=sampGetPlayerNickname(target_id)
        if type(nickname)~='string' or not nickname:match('^[%w_]+$') then return end
        release_input_capture()
        process_input('/askill '..nickname)
    elseif action == 'freeze' then
        release_input_capture()
        process_input(string.format('/freeze %d', target_id))
    elseif action == 'pull_from_water' then
        release_input_capture()
        process_input(string.format('/tr %d', target_id))
    elseif action == 'gethere' then
        release_input_capture()
        process_input(target_in_car and string.format('/gethere %d 1', target_id) or string.format('/gethere %d', target_id))
    elseif action == 'hp' then
        release_input_capture()
        process_input(string.format('/hp %d 100', target_id))
    elseif action == 'spawn' then
        release_input_capture()
        process_input(string.format('/spawn %d', target_id))
    elseif action == 'respawn' then
        release_input_capture()
        process_input(string.format('/spawn %d 1', target_id))
    elseif action == 'getip' then
        release_input_capture()
        process_input(string.format('/getip %d', target_id))
    elseif action == 'you_here' then
        release_input_capture()
        queue_chat_lines({
            string.format('/ans %d Вы тут? Дайте ответ.', target_id),
            string.format('/ans %d Вы тут? Дайте ответ.', target_id),
            string.format('/ans %d Вы тут? Дайте ответ.', target_id)
        }, 250)
    elseif action == 'goto' then
        release_input_capture()
        queue_chat_lines({
            '/sp',
            string.format('/goto %d', target_id)
        }, 300)
        close_custom_menu()
    end

    release_input_capture()
end

local function remember_menu(menu_id, menu_title, x, y, two_columns, columns, rows, menu_enabled)
    current_menu = {
        id = tonumber(menu_id) or 0,
        title = normalize_text(menu_title),
        x = tonumber(x) or 548,
        y = tonumber(y) or 157,
        two_columns = two_columns and true or false,
        menu_enabled = menu_enabled and true or false,
        items = extract_menu_items(columns)
    }
    server_menus[current_menu.id] = current_menu
end

local function valid_vehicle_id(id)
    id = tonumber(id)
    if id and id >= 0 and id <= 1999 then return id end
end

local function get_vehicle_data(id)
    id = valid_vehicle_id(id)
    if not id then return nil end
    vehicle_data[id] = vehicle_data[id] or {}
    return vehicle_data[id]
end

local function remember_player_sync(id, mode, vehicle_id, data, health_key, weapon_key)
    id = tonumber(id)
    if not id or id < 0 or id > 1003 then return end
    local weapon = finite_number(field(data, weapon_key))
    player_sync[id] = {
        received_at = os.time(), mode = mode, vehicle_id = valid_vehicle_id(vehicle_id),
        health = finite_number(field(data, health_key)), armor = finite_number(field(data, 'armor')),
        weapon = weapon and (weapon % 64) or nil, speed = sync_speed(data)
    }
end

function sampev.onPlayerSync(id, data)
    remember_player_sync(id, 'foot', nil, data, 'health', 'weapon')
end

function sampev.onVehicleSync(id, vehicle_id, data)
    remember_player_sync(id, 'driver', vehicle_id, data, 'playerHealth', 'currentWeapon')
    local car = get_vehicle_data(vehicle_id)
    if car then
        -- Vehicle data is shared with passengers; player HP/weapon stays under id.
        car.health = finite_number(field(data, 'vehicleHealth'))
        car.health_at = os.time()
        car.speed = sync_speed(data)
        car.speed_at = os.time()
    end
end

function sampev.onPassengerSync(id, data)
    remember_player_sync(id, 'passenger', field(data, 'vehicleId'), data, 'health', 'currentWeapon')
end

function sampev.onPlayerStreamIn(id)
    if noticeTarget and noticeTarget.id==id then noticeStreamToken=noticeStreamToken+1;noticeTarget.lost=false end
    -- Getters can return default HP=100 until the first sync after stream-in.
    player_sync[id] = nil
end

function sampev.onPlayerStreamOut(id)
    player_sync[id] = nil
    local target=noticeTarget
    if spectate_state and target and target.id==id and not target.lost then
        noticeStreamToken=noticeStreamToken+1
        local token=noticeStreamToken
        lua_thread.create(function()
            wait(700)
            if token==noticeStreamToken and spectate_state and noticeTarget==target and sampIsPlayerConnected(id)then
                target.lost=true
                chat('Игрок '..cp1251_to_utf8(target.nick)..'['..id..'] пропал из видимости.')
            end
        end)
    end
end

function sampev.onPlayerJoin(id)
    player_sync[id], spectate_client_info[id] = nil, nil
end

function sampev.onPlayerQuit(id)
    if noticeTarget and noticeTarget.id==id then
        chat('Подозреваемый '..cp1251_to_utf8(noticeTarget.nick)..'['..id..'] вышел из игры.')
        noticeTarget=nil;noticeStreamToken=noticeStreamToken+1
    end
    player_sync[id], spectate_client_info[id] = nil, nil
    if pending_sp_target and pending_sp_target.id == id then pending_sp_target = nil end
    if spectate_target_id == id then
        spectate_target_id, spectate_vehicle_id = -1, -1
        -- Losing the target does not end server spectating; keep EXIT available.
        if not spectate_state then close_custom_menu() end
    end
    if manual_target_id.v == id then manual_target_id.v = -1 end
end

function sampev.onVehicleStreamIn(id, data)
    id = valid_vehicle_id(id)
    if not id then return end
    vehicle_data[id] = { model = finite_number(field(data, 'type')),
        health = finite_number(field(data, 'health')), health_at = os.time() }
end

function sampev.onVehicleStreamOut(id)
    vehicle_data[id] = nil
end

function sampev.onSetVehicleParamsEx(id, params)
    local car = get_vehicle_data(id)
    if car then car.engine = as_boolean(field(params, 'engine')) end
end

function sampev.onSetVehicleHealth(id, health)
    local car = get_vehicle_data(id)
    if car then car.health, car.health_at = finite_number(health), os.time() end
end

local function reset_server_data()
    timed_target,timed_nickname=nil,nil
    queue_generation = queue_generation + 1
    server_menus = {}
    player_sync, vehicle_data, spectate_client_info = {}, {}, {}
    pending_sp_target = nil
    noticeTarget=nil;noticeStreamToken=noticeStreamToken+1
    spectate_state, spectate_target_id, spectate_vehicle_id = false, -1, -1
    manual_target_id.v = -1
    reset_pending_spectate()
    close_custom_menu()
end

sampev.onConnectionClosed = reset_server_data
sampev.onConnectionLost = reset_server_data
sampev.onGamemodeRestart = reset_server_data

function sampev.onInitMenu(menu_id, menu_title, x, y, two_columns, columns, rows, menu_enabled)
    -- Cache server rows even while replacement is disabled. SHOWMENU may reuse
    -- an initialized ID after closing the panel or enabling the setting.
    local active = current_menu
    remember_menu(menu_id, menu_title, x, y, two_columns, columns, rows, menu_enabled)
    if menu_active and active and active.id~=tonumber(menu_id) then current_menu = active end
end

local function is_observation_menu(menu)
    local labels = {}
    for _, item in ipairs(menu.items) do labels[menu_key(item.label)] = true end
    return labels.stat and labels.update and labels.slap and labels.mute
        and labels.weap and labels.skick and labels.info
end

function sampev.onShowMenu(menu_id)
    if not enabled then return end
    local menu = server_menus[tonumber(menu_id)]
    if not menu and integration.serverMenuDefinition then
        local definition=integration.serverMenuDefinition(menu_id)
        if definition then
            remember_menu(unpack(definition,1,definition.n))
            menu=server_menus[tonumber(menu_id)]
        end
    end
    -- Unknown menus remain native; never fabricate server row numbers.
    if not menu or #menu.items == 0 then return end
    if not spectate_state and not pending_sp_target and not is_observation_menu(menu) then return end
    -- A native panel can still be visible from before the Lua reload.
    -- Hide it locally before opening its replacement; no server command is sent.
    if integration.hideServerMenu and not integration.hideServerMenu(tonumber(menu_id)) then return end
    current_menu = menu
    preview = false
    open_custom_menu()
    return false
end

function sampev.onHideMenu(menu_id)
    if current_menu and current_menu.id == tonumber(menu_id) and not spectate_state then close_custom_menu() end
    return true
end

function sampev.onSendChat(text)
    if not integration.preferences.data.main.spectateChatN or not spectate_state then return end
    text=tostring(text or '')
    if text:match('^%s*/') or not text:match('%S') then return end
    sampSendChat('/n ' .. text)
    return false
end

function sampev.onTogglePlayerSpectating(state)
    spectate_state = state and true or false
    if not spectate_state then
        if noticeTarget then
            chat('Вы вышли из слежки за игроком '..cp1251_to_utf8(noticeTarget.nick)..'['..noticeTarget.id..'].')
        end
        noticeTarget=nil;noticeStreamToken=noticeStreamToken+1
        timed_target,timed_nickname=nil,nil
        pending_sp_target = nil
        spectate_target_id = -1
        spectate_vehicle_id = -1
        if pending_spectate_direction == 0 then
            pending_spectate_last_id = -1
        end
        if menu_active then
            close_custom_menu()
        end
    end
end

function sampev.onSpectatePlayer(player_id)
    spectate_state = true
    spectate_target_id = tonumber(player_id) or -1
    spectate_vehicle_id = -1
    pending_sp_target = nil
    update_observation_clock()
    reset_pending_spectate()
    integration.releaseSpectateInput()
end

function sampev.onSpectateVehicle(vehicle_id)
    spectate_state = true
    spectate_target_id = -1
    -- In the actual logs [SP] names the target BEFORE this vehicle RPC.
    -- Consume that header, otherwise a passenger would be replaced by the driver.
    if pending_sp_target and os.time() - pending_sp_target.received_at <= SYNC_MAX_AGE then
        spectate_target_id = pending_sp_target.id
    end
    pending_sp_target = nil
    spectate_vehicle_id = tonumber(vehicle_id) or -1
    update_observation_clock()
    reset_pending_spectate()
    integration.releaseSpectateInput()
end

function sampev.onShowDialog(dialog_id, style, title, button1, button2, text)
    return true
end

function sampev.onServerMessage(color, text)
    local message = cp1251_to_utf8(text)
    local sp = parse_sp_message(message)
    if sp then
        spectate_client_info[sp.id] = { nickname = sp.nickname, label = get_client_label(sp.raw_client) }
        pending_sp_target = { id = sp.id, received_at = os.time() }
        if spectate_state and spectate_vehicle_id >= 0 then
            -- The [SP] header explicitly names the observed occupant.
            spectate_target_id = sp.id
        end
    end

    if pending_spectate_direction ~= 0 then
        local lower_message = string.lower(message)
        if string.find(lower_message, 'игрока с таким id нет', 1, true)
            or string.find(lower_message, 'не авторизован', 1, true) then
            if pending_spectate_attempts >= 1000 then
                reset_pending_spectate()
                chat('Не удалось найти доступную цель для слежки.', 0xAAAAFF)
                return true
            end

            if try_spectate_candidate(pending_spectate_last_id, pending_spectate_direction) then
                return false
            end
        end
    end

    return true
end

find_menu_row = function(name)
    local target = menu_key(name)
    local items = current_menu and current_menu.items or {}
    for _, item in ipairs(items) do
        if menu_key(item.label) == target then
            return item.row
        end
    end
    return nil
end

local function build_action_list()
    local actions = {
        { label = 'EXIT', danger = true, run = function() do_custom_action('spoff') end },
        { label = 'UPDATE', run = function() run_server_menu_action('update') end },
        { label = 'STATS', run = function() run_server_menu_action('stat') end },
        { label = 'SKILLZ', run = function() do_custom_action('skillz') end },
        { label = 'WEAP', run = function() run_server_menu_action('weap') end },
        { label = 'SLAP', run = function() run_server_menu_action('slap') end },
        { label = 'FREEZE', run = function() do_custom_action('freeze') end },
        { label = 'HP', run = function() do_custom_action('hp') end },
        { label = 'ИЗ ВОДЫ', run = function() do_custom_action('pull_from_water') end },
        { label = 'GETHERE', run = function() do_custom_action('gethere') end },
        { label = 'SPAWN', run = function() do_custom_action('spawn') end },
        { label = 'RESPAWN', run = function() do_custom_action('respawn') end },
        { label = 'Вы тут?', run = function() do_custom_action('you_here') end },
        { label = 'GOTO', run = function() do_custom_action('goto') end },
        { label = 'SKICK', danger = true, run = function() run_server_menu_action('skick') end },
        { label = 'EXIT', danger = true, run = function() do_custom_action('spoff') end }
    }
    local minimum={HP=4,FREEZE=3,['ИЗ ВОДЫ']=3,GETHERE=3,GOTO=3,SKICK=3,SPAWN=2,RESPAWN=2}
    if actionConfig.main.count<0 then
        actionConfig.main.count=#actions
        for i,action in ipairs(actions)do actionConfig['row'..i]={label=action.label,builtin=action.label}end
    end
    local catalog={};for _,action in ipairs(actions)do catalog[action.label]=action end
    local configured={}
    for i=1,math.min(40,actionConfig.main.count)do
        local row=actionConfig['row'..i]
        if row then
            local original=catalog[row.builtin]
            if original then configured[#configured+1]={label=original.label,title=row.label,run=original.run,danger=original.danger}
            elseif row.command and row.command~=''then
                local command=row.command
                configured[#configured+1]={label=row.label,run=function()
                    if preview or not spectate_state then return end
                    local id=get_target_id();if id<0 or not sampIsPlayerConnected(id)then return end
                    send_chat(command:gsub('{id}',tostring(id)))
                end}
            end
        end
    end
    local available={}
    for _,action in ipairs(configured) do
        if integration.access:can(minimum[action.label] or 1) then available[#available+1]=action end
    end
    selected_action_index=math.max(1,math.min(#available,selected_action_index))
    return available
end


collect_target_info = function()
    local player_id = get_target_id()
    local info = {
        id = player_id,
        nick = 'Нет цели',
        health = '-',
        armor = '-',
        level = '-',
        ping = '-',
        afk = '-',
        speed = '-',
        client = 'Нет данных',
        has_vehicle = false,
        vehicle = 'Нет данных',
        vehicle_health = '-',
        vehicle_engine = '-',
        weapon = '-',
        status = ''
    }

    if player_id < 0 or try_api('sampIsPlayerConnected', player_id) ~= true then
        return info
    end

    info.nick = cp1251_to_utf8(try_api('sampGetPlayerNickname', player_id) or '')
    -- Advance RP exposes player level through the scoreboard score.
    info.level = format_number(try_api('sampGetPlayerScore', player_id))
    info.ping = format_number(try_api('sampGetPlayerPing', player_id))
    local client = spectate_client_info[player_id]
    if client and client.nickname == info.nick then info.client = client.label end

    local streamed, ped = try_api('sampGetCharHandleBySampPlayerId', player_id)
    if streamed ~= true or not ped or try_api('doesCharExist', ped) ~= true then
        info.vehicle = 'Вне зоны прорисовки'
        info.status = 'Игрок вне зоны прорисовки. Данные пока недоступны.'
        return info
    end

    local paused = as_boolean(try_api('sampIsPlayerPaused', player_id))
    if paused ~= nil then info.afk = paused and 'Да' or 'Нет' end
    local sync = player_sync[player_id]
    local fresh = sync and (os.time() - sync.received_at <= SYNC_MAX_AGE)
    local usable = sync and (fresh or paused == true)
    if usable then
        info.health = format_number(sync.health)
        info.armor = format_number(sync.armor)
        info.weapon = get_weapon_name(sync.weapon)
        if not fresh then info.status = 'Последние данные перед паузой игрока.' end
    else
        info.status = sync and 'Данные игрока ещё не обновились.' or 'Ожидание данных игрока.'
    end

    local in_car = as_boolean(try_api('isCharInAnyCar', ped))
    if in_car == false then
        info.vehicle = 'Нет транспорта'
        if fresh then
            local speed = sync.mode == 'foot' and sync.speed or nil
            if speed == nil then
                local local_speed = finite_number(try_api('getCharSpeed', ped))
                if local_speed then speed = local_speed * SERVER_LOCAL_SPEED_SCALE end
            end
            if speed then info.speed = format_number(speed) .. ' км/ч' end
        end
        return info
    end
    if in_car ~= true then return info end

    local vehicle = try_api('storeCarCharIsInNoSave', ped)
    if not vehicle or try_api('doesVehicleExist', vehicle) ~= true then return info end
    -- A current, existing vehicle is required; an old sync vehicle ID is not enough.
    info.has_vehicle = true
    local found, vehicle_id = try_api('sampGetVehicleIdByCarHandle', vehicle)
    vehicle_id = found == true and valid_vehicle_id(vehicle_id) or nil
    if not vehicle_id and fresh and sync.vehicle_id
        and try_get_samp_vehicle_handle(sync.vehicle_id) == vehicle then vehicle_id = sync.vehicle_id end
    local car = vehicle_id and vehicle_data[vehicle_id] or nil
    local model = finite_number(try_api('getCarModel', vehicle))
    local vehicle_name = model and try_api('getNameOfVehicleModel', model) or nil
    info.vehicle = string.format('%s [ID: %s; модель: %s]',
        vehicle_name and cp1251_to_utf8(vehicle_name) or 'Транспорт',
        vehicle_id or '-', model or '-')

    local health = car and car.health_at and os.time() - car.health_at <= SYNC_MAX_AGE and car.health or nil
    if health == nil then health = finite_number(try_api('getCarHealth', vehicle)) end
    info.vehicle_health = format_number(health, 1)
    local engine = car and car.engine
    if engine == nil then engine = as_boolean(try_api('isCarEngineOn', vehicle)) end
    if engine ~= nil then info.vehicle_engine = engine and 'Вкл.' or 'Выкл.' end
    local speed = car and car.speed_at and os.time() - car.speed_at <= SYNC_MAX_AGE and car.speed or nil
    if speed == nil and fresh and sync.vehicle_id == vehicle_id then speed = sync.speed end
    if speed == nil then
        local local_speed = finite_number(try_api('getCarSpeed', vehicle))
        if local_speed then speed = local_speed * SERVER_LOCAL_SPEED_SCALE end
    end
    if speed then info.speed = format_number(speed) .. ' км/ч' end
    return info
end

local palette = integration.palette

local function color_vec(hex, alpha)
    return imgui.ImVec4(math.floor(hex / 65536) % 256 / 255,
        math.floor(hex / 256) % 256 / 255, hex % 256 / 255, alpha or 1)
end

local function packed_color(hex)
    return imgui.ColorConvertFloat4ToU32(color_vec(hex))
end

local function fit_text(value, max_width)
    local text = tostring(value or '-')
    if imgui.CalcTextSize(text).x <= max_width then return text end
    while #text > 0 and imgui.CalcTextSize(text .. '...').x > max_width do
        local index = #text
        while index > 1 and text:byte(index) >= 128 and text:byte(index) < 192 do index = index - 1 end
        text = text:sub(1, index - 1)
    end
    return imgui.CalcTextSize('...').x <= max_width and (text .. '...') or ''
end

local function push_theme(scale)
    imgui.PushStyleVar(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))
    imgui.PushStyleVar(imgui.StyleVar.WindowRounding, 14 * scale)
    imgui.PushStyleVar(imgui.StyleVar.ItemSpacing, imgui.ImVec2(0, 0))
    imgui.PushStyleColor(imgui.Col.WindowBg, color_vec(palette.bg))
    imgui.PushStyleColor(imgui.Col.Border, color_vec(palette.border))
    imgui.PushStyleColor(imgui.Col.Text, color_vec(palette.text))
end

local function pop_theme()
    imgui.PopStyleColor(3)
    imgui.PopStyleVar(3)
end

local function begin_panel(kind, pos, width, height, layout)
    local scale = layout.scale
    push_theme(scale)
    imgui.SetNextWindowPos(imgui.ImVec2(pos.x, pos.y), imgui.Cond.Always)
    imgui.SetNextWindowSize(imgui.ImVec2(width, height), imgui.Cond.Always)
    local flags = imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize +
        imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoScrollbar +
        imgui.WindowFlags.NoScrollWithMouse + imgui.WindowFlags.NoSavedSettings +
        imgui.WindowFlags.NoFocusOnAppearing + imgui.WindowFlags.NoMove +
        ((imgui.DisableInput or integration.layoutEditing()) and imgui.WindowFlags.NoInputs or 0)
    imgui.Begin('##server_menu_' .. kind, nil, flags)
    imgui.SetWindowFontScale(scale)
    if not integration.layoutEditing() and settings.positions.dirty and not imgui.IsMouseDragging(0) then save_positions() end
    local origin = imgui.GetWindowPos()
    local draw = imgui.GetWindowDrawList()
    local ui = {}
    local function point(x, y) return imgui.ImVec2(origin.x + x * scale, origin.y + y * scale) end
    function ui.rect(x, y, w, h, color, radius)
        draw:AddRectFilled(point(x, y), point(x + w, y + h), packed_color(color), (radius or 0) * scale, -1)
    end
    function ui.outline(x, y, w, h, color, radius)
        draw:AddRect(point(x, y), point(x + w, y + h), packed_color(color), (radius or 0) * scale, -1, scale)
    end
    function ui.line(x1, y1, x2, y2, color, thickness)
        draw:AddLine(point(x1, y1), point(x2, y2), packed_color(color), (thickness or 1) * scale)
    end
    function ui.text(x, y, value, size, color, max_width, bold, align)
        local pushed = push_font(size, bold)
        local clipped = fit_text(value, max_width * scale)
        local measured = imgui.CalcTextSize(clipped).x / scale
        if align == 'right' then x = x + max_width - measured
        elseif align == 'center' then x = x + (max_width - measured) / 2 end
        imgui.SetCursorPos(imgui.ImVec2(x * scale, y * scale))
        imgui.TextColored(color_vec(color or palette.text), clipped)
        pop_font(pushed)
    end
    function ui.hit(id, x, y, w, h)
        imgui.SetCursorPos(imgui.ImVec2(x * scale, y * scale))
        local pressed = imgui.InvisibleButton(id, imgui.ImVec2(w * scale, h * scale))
        return pressed, not imgui.DisableInput and imgui.IsItemHovered()
    end
    if move_mode then
        ui.hit('##move_' .. kind, 8, 6, width / scale - 16, 22)
        if not imgui.DisableInput and imgui.IsItemActive() and imgui.IsMouseDragging(0) then
            move_window_position(kind, imgui.GetIO().MouseDelta, layout)
            settings.positions.dirty=true
        end
    end
    return ui
end

local function end_panel()
    imgui.End()
    pop_theme()
end

local function draw_info_window(info, layout)
    local ui = begin_panel('info', info_window_pos, layout.info_width, layout.info_height, layout)
    local text, rect = ui.text, ui.rect
    text(12, 14, move_mode and 'ПЕРЕМЕЩЕНИЕ' or 'НАБЛЮДЕНИЕ', 13, palette.accent, 140, true)
    update_observation_clock()
    text(158, 14, format_elapsed_time(os.time() - menu_open_clock), 14, palette.muted, 54, false, 'right')
    text(12, 35, info.nick, 18, palette.text, 200, true)
    text(12, 61, info.client, 14, palette.muted, 200)
    text(12, 88, 'ID ' .. tostring(info.id), 13, palette.muted, 112)
    local pause_color = info.afk == 'Да' and palette.amber or (info.afk == 'Нет' and palette.green or palette.muted)
    rect(132, 83, 80, 22, palette.surface, 6)
    text(136, 87, info.afk == 'Да' and 'Пауза' or (info.afk == 'Нет' and 'В игре' or 'Нет данных'), 13, pause_color, 72, false, 'center')

    local function metric(x, label, value, accent)
        rect(x, 116, 96, 68, palette.surface, 9)
        text(x + 10, 125, label, 13, palette.muted, 76)
        text(x + 10, 143, value, 24, palette.text, 76, true)
        rect(x + 10, 173, 76, 3, palette.track, 1)
        local amount = finite_number(value)
        if amount and amount > 0 then rect(x + 10, 173, math.min(100, amount) * 0.76, 3, accent, 1) end
    end
    metric(12, 'Здоровье', info.health, palette.green)
    metric(116, 'Броня', info.armor, palette.accent)
    local function row(y, label, value, color)
        text(12, y, label, 14, palette.muted, 72)
        text(90, y - 1, value, 16, color or palette.text, 122, false, 'right')
    end
    row(198, 'Скорость', info.speed)
    row(222, 'Уровень', info.level)
    row(246, 'Пинг', info.ping)
    row(270, 'Оружие', info.weapon)
    if layout.has_vehicle then
        ui.line(12, 298, 212, 298, palette.border)
        text(12, 310, 'ТРАНСПОРТ', 13, palette.muted, 200, true)
        local vehicle_name, vehicle_meta = tostring(info.vehicle or '-'):match('^(.-)%s*%[(.-)%]%s*$')
        text(12, 330, vehicle_name or info.vehicle, 16, palette.text, 200)
        text(12, 352, vehicle_meta or '', 13, palette.muted, 200)
        row(379, 'Прочность', info.vehicle_health)
        row(403, 'Двигатель', info.vehicle_engine, info.vehicle_engine == 'Вкл.' and palette.green or palette.muted)
    end
    -- Reserve two wrapped status lines so the narrow window keeps useful explanations.
    local first, second = '', ''
    local pushed = push_font(13)
    for word in tostring(info.status or ''):gmatch('%S+') do
        local candidate = first == '' and word or (first .. ' ' .. word)
        if second == '' and (first == '' or imgui.CalcTextSize(candidate).x <= 200 * layout.scale) then
            first = candidate
        else second = second == '' and word or (second .. ' ' .. word) end
    end
    pop_font(pushed)
    if first ~= '' then text(12, layout.status_y, first, 13, palette.amber, 200) end
    if second ~= '' then text(12, layout.status_y + 16, second, 13, palette.amber, 200) end
    end_panel()
end

local function draw_buttons_window(actions, layout)
    local ui = begin_panel('buttons', buttons_window_pos, layout.buttons_width, layout.buttons_height, layout)
    local text, rect = ui.text, ui.rect
    text(8, 14, move_mode and 'ПЕРЕМЕЩЕНИЕ' or 'ДЕЙСТВИЯ', 13, palette.accent, 128, true)
    for index, action in ipairs(actions) do
        local x, y = 8+((index-1)%layout.columns)*136, layout.action_top + math.floor((index - 1)/layout.columns) * layout.row_step
        local selected = index == selected_action_index
        local pressed, hovered = ui.hit('##action_' .. index, x, y, 128, layout.button_height)
        rect(x, y, 128, layout.button_height, selected and palette.selection or (hovered and palette.hover or palette.button), 6)
        if selected then
            ui.outline(x, y, 128, layout.button_height, palette.accent, 6)
            rect(x, y + 8, 3, layout.button_height - 16, palette.accent, 1)
        end
        text(x + 8, y + (layout.button_height - 16) / 2, action.title or action.label, 16,
            action.danger and palette.danger or palette.text, 112, selected, 'center')
        if pressed and not integration.layoutEditing() then selected_action_index = index; action.run() end
    end
    end_panel()
end

local function draw_panel(info, actions)
    local sx, sy = get_screen_size()
    local layout = calculate_layout(sx, sy, #actions, info.has_vehicle, info.status ~= '')
    position_windows(layout)
    draw_info_window(info, layout)
    draw_buttons_window(actions, layout)
end


local function handle_keyboard(actions)
    if integration.layoutEditing()then return end
    if not menu_active then
        return
    end

    if move_mode or input_blocked() then
        keyboard_ready = false
        return
    end

    -- A key used to close chat/dialogs must be released before menu control resumes.
    if not keyboard_ready then
        keyboard_ready = not menu_keys_down()
        return
    end

    local count = #actions
    if count == 0 then
        return
    end

    local function run_selected_action()
        local action = actions[selected_action_index]
        if action and action.run then
            action.run()
            release_input_capture()
        end
    end

    if integration.keys:pressed('observation_up') or integration.keys:pressed('observation_up_ws') then
        selected_action_index = selected_action_index - 1
        if selected_action_index < 1 then
            selected_action_index = count
        end
    end

    if integration.keys:pressed('observation_down') or integration.keys:pressed('observation_down_ws') then
        selected_action_index = selected_action_index + 1
        if selected_action_index > count then
            selected_action_index = 1
        end
    end

    if integration.keys:pressed('observation_confirm') or integration.keys:pressed('observation_confirm_alt') then
        run_selected_action()
        return
    end

    if integration.keys:pressed('observation_left') then
        spectate_next_id(-1)
    end

    if integration.keys:pressed('observation_right') then
        spectate_next_id(1)
    end

    if integration.keys:pressed('observation_close') then
        do_custom_action('close')
    end
end

function imgui.OnDrawFrame()
    if integration.windowOpen() then return end
    if not menu_active or not current_menu then
        imgui.Process = false
        return
    end

    local info = collect_target_info()
    local actions = build_action_list()
    imgui.Process = true
    draw_panel(info, actions)
end

local function preview_panels()
    preview = true
