local function reset_panel_positions()
    close_custom_menu()
    buttons_window_pos = { x = nil, y = nil }
    info_window_pos = { x = nil, y = nil }
    settings.positions = {}
    local sx, sy = get_screen_size()
    local info = collect_target_info()
    position_windows(calculate_layout(sx, sy, 16, info.has_vehicle, info.status ~= ''))
    save_positions()
    chat('Расположение панелей сброшено. Курсор освобождён.')
end

function integration.start()
    while not isSampAvailable() do
        wait(100)
    end

    local function toggle_menu_move_mode()
        if not menu_active then
            chat('Сначала начните слежку или откройте предпросмотр в настройках наблюдения.', 0xAAAAFF)
            return
        end

        move_mode = not move_mode
        keyboard_ready = false
        apply_imgui_runtime_flags()
        if not move_mode then
            release_input_capture()
            save_positions()
        end
        chat(move_mode and 'Перетащите панели за заголовки. /menumove — сохранить расположение.' or 'Расположение панелей сохранено.')
    end

    sampRegisterChatCommand('menumove', toggle_menu_move_mode)

    sampRegisterChatCommand('movemenu', function()
        toggle_menu_move_mode()
    end)

    local restoreUntil=getGameTimer()+10000
    local restoreAt=0
    while true do
        wait(0)
        if restoreUntil and getGameTimer()>restoreUntil then restoreUntil=nil end
        if restoreUntil and enabled and not menu_active and getGameTimer()>=restoreAt then
            restoreAt=getGameTimer()+500
            local definition=integration.serverMenuDefinition()
            if definition then
                local candidate={items=extract_menu_items(definition[6])}
                if is_observation_menu(candidate) then
                    remember_menu(unpack(definition,1,definition.n))
                    if definition.observedType==1 then sampev.onSpectatePlayer(definition.observedId)
                    elseif definition.observedType==2 then sampev.onSpectateVehicle(definition.observedId) end
                    sampev.onShowMenu(definition[1])
                    restoreUntil=nil
                end
            end
        elseif menu_active then restoreUntil=nil end

        apply_imgui_runtime_flags()

        if menu_active then
            handle_keyboard(build_action_list())
        end
    end
end

