local function action_move_button(id, direction, available)
    -- Draw the arrow ourselves: not every selected interface font has ↑ and ↓.
    local size = math.max(22, imgui.CalcTextSize('A').y + 8)
    local pos = imgui.GetCursorScreenPos()
    local clicked = imgui.Button('##' .. id, imgui.ImVec2(size, size))
    local draw = imgui.GetWindowDrawList()
    local tint = packed_color(available and palette.text or palette.muted)
    local x, y = pos.x + size / 2, pos.y + size / 2
    local tip, tail = y + direction * size * .23, y - direction * size * .23
    draw:AddLine(imgui.ImVec2(x, tail), imgui.ImVec2(x, tip), tint, 1.6)
    draw:AddLine(imgui.ImVec2(x - size * .18, y), imgui.ImVec2(x, tip), tint, 1.6)
    draw:AddLine(imgui.ImVec2(x + size * .18, y), imgui.ImVec2(x, tip), tint, 1.6)
    if imgui.IsItemHovered() then
        imgui.BeginTooltip()
        imgui.Text(direction < 0 and 'Переместить выше' or 'Переместить ниже')
        imgui.EndTooltip()
    end
    return clicked and available
end

integration.drawSettings = function()
    local active = imgui.ImBool(enabled)
    if imgui.Checkbox('Заменять серверное меню наблюдения', active) then
        enabled = active.v
        settings.features.enabled = enabled
        save_positions()
        if not enabled then close_custom_menu() end
    end
    local horizontal=imgui.ImBool(actionConfig.main.horizontal)
    if imgui.Checkbox('Горизонтальная панель действий',horizontal)then actionConfig.main.horizontal=horizontal.v;saveActions()end
    build_action_list()
    if imgui.CollapsingHeader('Редактор кнопок «Действия»')then
        for i=1,actionConfig.main.count do
            local row=actionConfig['row'..i]
            imgui.PushID('action_edit_'..i)
            imgui.Text(row.label);imgui.SameLine()
            if action_move_button('move_up',-1,i>1) then actionConfig['row'..i],actionConfig['row'..(i-1)]=actionConfig['row'..(i-1)],row;saveActions()end
            imgui.SameLine()
            if action_move_button('move_down',1,i<actionConfig.main.count) then actionConfig['row'..i],actionConfig['row'..(i+1)]=actionConfig['row'..(i+1)],row;saveActions()end
            imgui.SameLine()
            if imgui.SmallButton('Удалить')then
                for j=i,actionConfig.main.count-1 do actionConfig['row'..j]=actionConfig['row'..(j+1)]end
                actionConfig['row'..actionConfig.main.count]=nil;actionConfig.main.count=actionConfig.main.count-1;saveActions()
                imgui.PopID();break
            end
            imgui.PopID()
        end
        imgui.InputText('Название кнопки',actionLabel)
        imgui.InputText('Команда · {id} — игрок',actionCommand)
        if imgui.Button('Добавить кнопку')then
            local command=actionCommand.v
            if actionLabel.v~='' and command:match('^/[%w_]+')and not command:find('[%z\1-\31]')and #utf8_to_cp1251(command)<=130 and actionConfig.main.count<40 then
                actionConfig.main.count=actionConfig.main.count+1
                actionConfig['row'..actionConfig.main.count]={label=actionLabel.v,command=command};saveActions()
                actionLabel.v='';actionCommand.v=''
            end
        end
        if imgui.Button('Вернуть стандартные кнопки')then actionConfig.main.count=-1;build_action_list();saveActions()end
    end
    imgui.Spacing()
    imgui.TextWrapped('В предпросмотре можно настроить расположение панелей без игровых действий. /menumove — начать перемещение и сохранить позиции.')
    if imgui.Button('Предпросмотр панелей', imgui.ImVec2(220, 36)) then
        preview_panels()
        move_mode=true;apply_imgui_runtime_flags()
        integration.beginPlacement(function()save_positions();close_custom_menu()end)
    end
    if imgui.GetContentRegionAvailWidth() >= 430 then imgui.SameLine() end
    if imgui.Button('Сбросить позиции', imgui.ImVec2(180, 36)) then reset_panel_positions() end
end

