integration.observation=function()
    if not spectate_state then return end
    local id=get_target_id()
    if not id or id<0 or not sampIsPlayerConnected(id) then return end
    local nick=sampGetPlayerNickname(id)
    local client=spectate_client_info[id]
    return {id=id,nickname=nick,mobile=client and client.nickname==nick and client.label=='Mobile' or false}
end

integration.layoutItems=function()
    local sx,sy=get_screen_size()
    local actions=build_action_list()
    local layout=calculate_layout(sx,sy,#actions,false,false)
    position_windows(layout)
    local function preview(kind,x,y)
        local pos=kind=='info' and info_window_pos or buttons_window_pos
        local ox,oy=pos.x,pos.y;pos.x,pos.y=x,y
        if kind=='info' then
            draw_info_window({nick='Player_Name',client='PC',id=123,afk='Нет',health='100',armor='50',speed='0',level='25',ping='45',weapon='Deagle',status=''},layout)
        else draw_buttons_window(actions,layout)end
        pos.x,pos.y=ox,oy
    end
    return {
        {name='Наблюдение · Информация',x=info_window_pos.x,y=info_window_pos.y,w=layout.info_width,h=layout.info_height,preview=function(x,y)preview('info',x,y)end,set=function(x,y)info_window_pos.x=x;info_window_pos.y=y;save_positions()end},
        {name='Наблюдение · Действия',x=buttons_window_pos.x,y=buttons_window_pos.y,w=layout.buttons_width,h=layout.buttons_height,preview=function(x,y)preview('buttons',x,y)end,set=function(x,y)buttons_window_pos.x=x;buttons_window_pos.y=y;save_positions()end}
    }
end

    end
    sources["modules/movement.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/movement.lua
-- Original third-party credits, where present, are retained below.
-- Lua ports of AntiBH (AIR), MatrixJump and BackF; see integration/CLEO_PORTS.md.
local events=require('lib.samp.events')
local bit=require('bit')
local steps=integration.service('stunt_steps.lua')
local generation,busy,owned=0,false,nil
local cjMovement=integration.service('cj_movement.lua').new(_G)
local keyPatch=integration.service('function_key_patch.lua').new(_G,integration.message)
integration.keys:register('matrix_jump','Акробатический прыжок',{key=32,shift=true,second=0})
integration.keys:register('back_flip','Сальто назад',{key=32,second=67})
local function clean()
    if owned and doesCharExist(owned.ped) and getCharPointer(owned.ped)==owned.pointer then
        setCharRotation(owned.ped,0,0,owned.heading)
        if not owned.proof then
            local address=owned.pointer+0x42
            writeMemory(address,1,bit.band(readMemory(address,1,false),0xEF),false)
        end
    end
    owned=nil;busy=false
end
local function cancel() generation=generation+1;clean() end
local function available()
    return sampGetGamestate()==3 and doesCharExist(PLAYER_PED) and not isCharDead(PLAYER_PED)
        and not isCharInAnyCar(PLAYER_PED) and not isPauseMenuActive() and isGameWindowForeground()
        and not sampIsChatInputActive() and not sampIsDialogActive() and not sampIsCursorActive()
end
local function run(kind)
    busy=true;local token=generation;local ped=PLAYER_PED;local pointer=getCharPointer(ped)
    local heading=getCharHeading(ped)
    local flags=readMemory(pointer+0x42,1,false)
    owned={ped=ped,pointer=pointer,heading=heading,proof=bit.band(flags,0x10)~=0}
    -- CPhysical collision-proof bit only; keep the other protection flags intact.
    writeMemory(pointer+0x42,1,bit.bor(flags,0x10),false)
    setCharRotation(ped,0,0,heading)
    local x,y=getCharVelocity(ped)
    if kind=='matrix' then x,y=x*1.3*1.3,y*1.3*1.3 end
    setCharVelocity(ped,x,y,10)
    taskPlayAnimNonInterruptable(ped,kind=='matrix' and 'FALL_FALL' or 'FALL_SKYDIVE','PED',3,false,false,false,false,kind=='matrix' and 440 or 410)
    lua_thread.create(function()
        for _,step in ipairs(steps[kind]) do
            if step[1]>0 then wait(step[1]) end
            if token~=generation then return end
            if not integration.preferences.data.main[kind=='matrix' and 'matrixJump' or 'backFlip'] or not available() or PLAYER_PED~=ped or getCharPointer(ped)~=pointer then clean();return end
            setCharRotation(ped,step[2],0,heading)
        end
        if token==generation then
            clean()
            if kind=='backflip' then busy=true;wait(600);if token==generation then busy=false end end
        end
    end)
end
function events.onSendPlayerSync(data)
    if integration.preferences.data.main.antiBH and tonumber(data.keysData)==40 then data.keysData=32 end
end
integration.update=function()
    local prefs=integration.preferences.data.main
    keyPatch:update(prefs.blockF1F4==true)
    cjMovement:update(prefs.cjMovement==true)
    local matrixPressed=integration.keys:pressed('matrix_jump')
    local backPressed=integration.keys:pressed('back_flip')
    if busy or integration.flightActive() or (not prefs.matrixJump and not prefs.backFlip) or not available() then return end
    if isCharPlayingAnim(PLAYER_PED,'CLIMB_JUMP') then return end
    if prefs.matrixJump and matrixPressed then run('matrix')
    elseif prefs.backFlip and backPressed then run('backflip') end
end
integration.onDisconnect=function()cancel();cjMovement:stop()end
integration.stop=function()cancel();keyPatch:stop();cjMovement:stop()end
integration.prepareReload=function()keyPatch:stop();cjMovement:stop()end
local settingsExpanded={}
integration.drawSettings=function()
    local g=require('imgui')
    for _,item in ipairs({{'cjMovement','Походка и бег CJ'},{'blockF1F4','Блокировать F1, F4, F5 и F7'},{'antiBH','Баннихоп (AntiBH)'},{'matrixJump','Акробатический прыжок'},{'backFlip','Сальто назад'}}) do
        local value=g.ImBool(integration.preferences.data.main[item[1]])
        if g.Checkbox(item[2],value) then integration.preferences.data.main[item[1]]=value.v;integration.preferences:save();cancel() end
        if item[1]=='matrixJump' or item[1]=='backFlip' then
            g.SameLine()
            if g.Button('Настройки##movement_'..item[1]) then settingsExpanded[item[1]]=not settingsExpanded[item[1]] end
        end
        if settingsExpanded[item[1]] then
        if item[1]=='matrixJump' then
            
            integration.keys:draw(g,'matrix_jump')
        elseif item[1]=='backFlip' then
            
            integration.keys:draw(g,'back_flip')
        end
        g.TextWrapped('Без назначенной клавиши трюк не запускается.')
        end
    end
end

-- Assigned keys replace the source combinations; an unassigned binding keeps them.

    end
    sources["modules/nakaz.lua"] = function()
-- X-TOOLS | Casual_Alvarez | Experimental, review-first punishment assistant.
local g=require('imgui')
local u8=require('encoding').UTF8
local catalog=integration.service('punishment_catalog.lua')
local favoritesPath=integration.storage:path('settings','nakaz-favorites.ini')
local favoritesConfig=integration.storage:loadIni({main={only=false},favorites={}},favoritesPath)
local favorites=favoritesConfig.favorites
local function saveFavorites()integration.storage:saveIni(favoritesConfig,favoritesPath)end
local opened=g.ImBool(false)
local search,reason=g.ImBuffer('',256),g.ImBuffer('',256)
local category=g.ImInt(0)
local term=g.ImInt(0)
local testMode,ack,unknownAck=g.ImBool(true),g.ImBool(false),g.ImBool(false)
local state={step=1,page=1}
local art=integration.service('art.lua').new(g,integration.base,_G)
local ui=integration.service('dossier_ui.lua').new(g,integration)
local function selfId()local ok,id=sampGetPlayerIdByCharHandle(PLAYER_PED);return ok and id or -1 end
local model=integration.service('punishment_assistant.lua').new({
 connected=sampIsPlayerConnected,nickname=sampGetPlayerNickname,maxId=function()return sampGetMaxPlayerId(false)end,
 localId=selfId,localName=function()local id=selfId();return id>=0 and sampGetPlayerNickname(id)or ''end,
 protected=integration.isKnownAdmin,allowed=function(command)return integration.access:can(integration.commandMinimum(command))end,
 familyEnabled=integration.familyFeaturesEnabled,bytes=function(text)return #u8:decode(text)end
},catalog)
local function close()opened.v=false;state={step=1,page=1};ack.v=false end
local function open(raw)
 if not integration.access:require(1,integration.message)then return end
 local target,err=model:target(u8(raw or ''))
 if not target then integration.message('/nakaz ID/Ник — '..err);return end
 state={step=1,page=1,target=target,identity=integration.access.identity,revision=integration.access:revision(),focus=true}
 search.v='';category.v=0;reason.v='';term.v=0;ack.v=false;unknownAck.v=false;testMode.v=true
 opened.v=true
end
sampRegisterChatCommand('nakaz',open)
local function rowCard(id,title,subtitle,selected,ruleId)
 local p=ui.cursor();local w=g.GetContentRegionAvailWidth();local actionW=ruleId and 44 or 0;local inner=math.max(1,w-28-actionW)
 local titleH=ui.measure(title,inner,16,true);local metaH=ui.measure(subtitle,inner,12)
 local h=titleH+metaH+29
 g.SetCursorPos(p);local pressed=g.InvisibleButton(id,g.ImVec2(w-actionW,h));local hovered=g.IsItemHovered()
 ui.rect(p.x,p.y,w,h,selected and integration.palette.selection or hovered and integration.palette.hover or integration.palette.surface,8,.97)
 if selected then ui.rect(p.x,p.y+10,3,h-20,'accent',1)end
 ui.text(p.x+14,p.y+10,inner,title,selected and 'accent'or 'normal',16,true)
 ui.text(p.x+14,p.y+15+titleH,inner,subtitle,'muted',12)
 if ruleId then
  g.SetCursorPos(g.ImVec2(p.x+w-actionW,p.y))
  if g.InvisibleButton('nakaz_favorite_'..ruleId,g.ImVec2(actionW,h))then
   favorites[ruleId]=favorites[ruleId]~=true;saveFavorites()
  end
  local starHover=g.IsItemHovered()
  local origin=g.GetWindowPos()
  local cx=origin.x+p.x+w-actionW/2-g.GetScrollX()
  local cy=origin.y+p.y+h/2-g.GetScrollY()
  local color=ui.color(favorites[ruleId]==true and 'accent' or starHover and 'normal' or 'muted')
  local points={};local radius=10*ui.scale()
  for i=0,9 do
   local angle=-math.pi/2+i*math.pi/5;local r=i%2==0 and radius or radius*.44
   points[i+1]=g.ImVec2(cx+math.cos(angle)*r,cy+math.sin(angle)*r)
  end
  local dl=g.GetWindowDrawList()
  for i=1,10 do dl:AddLine(points[i],points[i%10+1],color,favorites[ruleId]==true and 2.5 or 1.3)end
  if starHover then g.SetTooltip(favorites[ruleId]==true and 'Убрать из избранного' or 'Добавить в избранное')end
 end
 ui.finish(p.x,p.y,w,h)
 return pressed
end
local function notice(title,text)
 local p=ui.cursor();local w=g.GetContentRegionAvailWidth();local inner=math.max(1,w-28)
 local h=ui.measure(title,inner,14,true)+ui.measure(text,inner,13)+32
 ui.rect(p.x,p.y,w,h,integration.palette.surface,8,.96)
 local y=p.y+12;y=y+ui.text(p.x+14,y,inner,title,'accent',14,true)+6
 ui.text(p.x+14,y,inner,text,'muted',13);ui.finish(p.x,p.y,w,h)
end
local function header()
 local p=ui.cursor();local w=g.GetContentRegionAvailWidth();local tw=math.max(120,w*.65-32)
 local target=state.target
 local title='Безопасная выдача наказаний'
 local h=math.max(140,ui.measure(title,tw,24,true)+ui.measure(target.name,tw,18,true)+68)
 ui.rect(p.x,p.y,w,h,integration.palette.surface,10)
 local texture=art:get('punishment-header')
 if texture then
  local origin=g.GetWindowPos();local sx,sy=origin.x+p.x-g.GetScrollX(),origin.y+p.y-g.GetScrollY()
  local crop=math.min(1,(texture.width/texture.height)/(w/h))
  g.GetWindowDrawList():AddImage(texture.texture,g.ImVec2(sx,sy),g.ImVec2(sx+w,sy+h),g.ImVec2(0,(1-crop)/2),g.ImVec2(1,(1+crop)/2),ui.color('accent',.78))
 end
 local y=p.y+14;y=y+ui.text(p.x+18,y,tw,'X-TOOLS / ПОМОЩНИК','accent',12,true)+6
 y=y+ui.text(p.x+18,y,tw,title,'normal',24,true)+7
 y=y+ui.text(p.x+18,y,tw,target.name,'normal',18,true)+4
 ui.text(p.x+18,y,tw,target.id and ('ID '..target.id..' · в сети')or 'Ник указан · офлайн','muted',12)
 ui.finish(p.x,p.y,w,h)
 local steps={'01  Кого наказать','02  Нарушение и срок','03  Проверка выдачи'}
 local available=g.GetContentRegionAvailWidth()
 for i,label in ipairs(steps)do
  if available>650 then if i>1 then g.SameLine()end;g.PushItemWidth(available/3-8)end
  g.TextColored(integration.color(i==state.step and integration.palette.accent or integration.palette.muted),label)
  if available>650 then g.PopItemWidth()end
 end
 g.Spacing()
end
local function chooseRule(r)
 state.rule=r;state.option=1;state.preview=nil;state.error=nil;ack.v=false;unknownAck.v=false
 term.v=r.options[1]and r.options[1].min or 0
 reason.v=r.title:gsub('^[%d%. /]+%.%s*','')
end
local function build()
 if state.identity~=integration.access.identity or state.revision~=integration.access:revision()then return nil,'Права или подключение изменились. Откройте /nakaz заново.'end
 if sampGetGamestate()~=3 then return nil,'Нет подключения к серверу.'end
 return model:plan(state.target,state.mode,state.rule and state.rule.id,state.option,term.v,reason.v,unknownAck.v)
end
local function summary(plan)
 local rows={{'Игрок',plan.target.name..(plan.target.id and ' ['..plan.target.id..']'or ' · офлайн')},
 {'Режим',plan.mode=='family'and 'Член семьи · причина + /msg' or 'Обычный игрок'},
 {'Раздел',catalog.category(state.rule.category)},{'Нарушение',state.rule.title},
 {'Наказание',catalog.labels[plan.kind]..(plan.amount and (' · '..plan.amount..(plan.kind=='ban'and ' дней'or ' мин.'))or '')},
 {'Причина',plan.reason},{'Отправка',plan.requestOnly and 'Запрос старшему администратору в /a' or 'Выдача напрямую'}}
 ui.table('nakaz_review','ПРОВЕРЬТЕ ПЕРЕД ВЫДАЧЕЙ',{{label='Поле',weight=.27},{label='Значение',weight=.73}},rows)
 notice(plan.requestOnly and 'Запрос в /a' or plan.mode=='family'and 'Команда до добавления семьи'or 'Команда',plan.outgoing)
 if plan.requestOnly then notice('Недостаточно прав для полной выдачи','Наказание самостоятельно не выдаётся. В /a уйдёт запрос старшему администратору с выбранной командой и сроком.')end
 if plan.mode=='family'and plan.requestOnly then notice('Запрос по семье','После /offst к причине добавится название семьи. В /a уйдут команда наказания и отдельный запрос на /msg. Само уведомление семье не отправляется.')
 elseif plan.mode=='family'then notice('Семейная выдача','Будет запрошен /offst. Название семьи добавится к причине, затем уйдёт сообщение в выбранный канал /msg, как у /fj, /fw и /fb. Если семья не определена — выдача отменяется.')end
end
local function submit()
 if state.sent then return end
 local plan,err=build()
 if not plan then state.error=err;state.preview=nil;state.step=2;return end
 if not state.preview or state.preview.key~=plan.key then state.error='Данные игрока изменились. Проверьте обновлённую команду.';state.preview=plan;ack.v=false;return end
 if not ack.v then state.error='Подтвердите игрока, обстоятельства и срок.';return end
 if testMode.v then state.result='Тест завершён. Команда не отправлена.';state.sent=true;return end
 state.sent=true
 local ok,result=pcall(function()
  if plan.mode=='family'then return integration.queueFamilyPunishment(plan)end
  if plan.requestOnly then return sampSendChat(u8:decode(plan.outgoing))end
  if plan.kind=='ban'then return integration.sendBan(plan.command)end
  return sampSendChat(u8:decode(plan.command))
 end)
 if not ok then state.result='Ошибка отправки. Проверьте чат перед повторной выдачей.'
 elseif result==false then state.result='Запрос отклонён. Проверьте сообщения X-Tools.'
 elseif plan.mode=='family'then state.result='Запрос передан семейному модулю. Дождитесь ответа сервера в чате.'
 elseif plan.requestOnly then state.result='Запрос отправлен в /a. Дождитесь решения старшего администратора.'
 else state.result='Команда отправлена. Результат проверьте по ответу сервера в чате.'end
end
local function details()
 local r=state.rule
 if not r then notice('Выберите причину','Нажмите на нарушение слева. Здесь появятся варианты наказания, сроки и исключения.');return end
 notice(catalog.category(r.category),r.title)
 if r.note~=''then notice('Условия и исключения',r.note)end
 if #r.options==0 then notice('Без персональной команды','Этот пункт требует отдельного решения по мероприятию. Кнопки выдачи нет.');return end
 g.TextColored(integration.color(integration.palette.accent),'Вид наказания')
 local optionLabels={};for i,o in ipairs(r.options)do optionLabels[i]=(catalog.labels[o.kind]or o.kind)..' · '..catalog.term(o)end
 local selected=g.ImInt((state.option or 1)-1)
 g.PushItemWidth(-1)
 if g.Combo('##nakaz_action',selected,table.concat(optionLabels,'\0')..'\0\0')then state.option=selected.v+1;term.v=r.options[state.option].min or 0;unknownAck.v=false;state.error=nil end
 local o=r.options[state.option]
 if o.kind=='jail'or o.kind=='mute'then
  g.Text('Срок, минуты')
  if o.min and o.max and o.min~=o.max then g.SliderInt('##nakaz_term',term,o.min,o.max)
  elseif o.min and o.max==o.min then term.v=o.min;g.Text(tostring(o.min)..' мин. — фиксированный срок')
  else g.InputInt('##nakaz_term',term)end
  if o.unknown or o.additive then g.Checkbox('Срок проверен отдельно по регламенту##nakaz_unknown',unknownAck)end
 elseif o.kind=='ban' then g.TextWrapped(o.min and ('Срок: '..o.min..' дней'..(o.atLeast and ' — нижняя граница указанного диапазона'or ''))or 'В этом пункте не указан срок бана. Выберите другой пункт.')end
 g.Text('Причина в команде');g.InputText('##nakaz_reason',reason)
 g.PopItemWidth()
 local plan,err=build()
 if not plan then g.TextWrapped(err)
 elseif g.Button('Проверить выдачу##nakaz_review',g.ImVec2(g.GetContentRegionAvailWidth(),0))then state.preview=plan;state.step=3;state.error=nil;ack.v=false end
end
local function draw()
 if not opened.v or not state.target then return end
 local sw,sh=getScreenResolution()
 g.SetNextWindowSize(g.ImVec2(math.min(1100,sw-32),math.min(800,sh-40)),g.Cond.FirstUseEver)
 g.SetNextWindowPos(g.ImVec2(sw/2,sh/2),g.Cond.FirstUseEver,g.ImVec2(.5,.5))
 if state.focus then g.SetNextWindowFocus();state.focus=nil end
 g.Begin('Безопасная выдача наказаний###xt_nakaz',opened,g.WindowFlags.NoCollapse)
 header()
 if state.step==1 then
  g.TextWrapped('Кого хотите наказать?')
  if rowCard('nakaz_player','Игрок','Обычная выдача. Без семейной причины и сообщения в /msg.',false)then state.mode='player';state.step=2 end
  if rowCard('nakaz_family','Член семьи','Название семьи в причине + уведомление /msg через семейный модуль.',false)then state.mode='family';state.step=2 end
  notice('Регламент из вашего списка','Одинаковые нарушения разделены по контекстам. Учтите исключения и выберите подходящий пункт. Выдача начинается только после отдельного подтверждения.')
 elseif state.step==2 then
  if g.Button('Назад: кого наказать##nakaz_back_mode')then state.step=1 end
  local columns=integration.layout.begin('nakaz_columns',940)
  g.PushItemWidth(-1)
  g.Text('Категория')
  local labels={'Все категории'};for _,c in ipairs(catalog.categories)do labels[#labels+1]=c.name end
  if g.Combo('##nakaz_category',category,table.concat(labels,'\0')..'\0\0')then state.page=1 end
  g.Text('Поиск причины')
  if g.InputText('##nakaz_search',search)then state.page=1 end
  g.PopItemWidth()
  local favoriteCount=0
  for _,r in ipairs(catalog.rules)do if favorites[r.id]==true then favoriteCount=favoriteCount+1 end end
  if g.Button((favoritesConfig.main.only and 'Показать все причины' or 'Избранные ('..favoriteCount..')')..'##nakaz_favorites')then
   favoritesConfig.main.only=not favoritesConfig.main.only;state.page=1;saveFavorites()
  end
  local found=catalog.search(category.v>0 and catalog.categories[category.v].id or nil,search.v)
  if favoritesConfig.main.only then
   local filtered={};for _,r in ipairs(found)do if favorites[r.id]==true then filtered[#filtered+1]=r end end;found=filtered
  end
  local pages=math.max(1,math.ceil(#found/6));state.page=math.min(state.page,pages)
  g.TextDisabled('Найдено: '..#found..' · '..state.page..' / '..pages)
  if state.page>1 and g.Button('< Назад##nakaz_page')then state.page=state.page-1 end
  if state.page<pages then if state.page>1 then g.SameLine()end;if g.Button('Далее >##nakaz_page')then state.page=state.page+1 end end
  for i=(state.page-1)*6+1,math.min(#found,state.page*6)do
   local r=found[i];local parts={};for _,o in ipairs(r.options)do parts[#parts+1]=(catalog.labels[o.kind]or o.kind)..' '..catalog.term(o)end
   if rowCard('nakaz_rule_'..r.id,r.title,catalog.category(r.category)..' · '..(#parts>0 and table.concat(parts,' / ')or 'Особое решение'),state.rule==r,r.id)then chooseRule(r)end
  end
  if #found==0 then g.TextWrapped(favoritesConfig.main.only and 'Нет избранных по этому фильтру. Откройте все причины и нажмите звёздочку справа от нужной.' or 'Ничего не найдено. Измените запрос или категорию.')end
  integration.layout.next(columns);details();integration.layout.finish(columns)
 elseif state.step==3 then
  if state.sent then
   notice(testMode.v and 'ПРОВЕРКА ЗАВЕРШЕНА'or 'ЗАПРОС ОБРАБОТАН',state.result or '')
   if state.preview then summary(state.preview)end
   if g.Button('Закрыть##nakaz_done')then close()end
  else
   if g.Button('Назад: причина и срок##nakaz_back_rule')then state.step=2 end
   summary(state.preview)
   if state.rule.note~=''then notice('Проверьте исключения',state.rule.note)end
   if g.Checkbox('Тестовый режим — не отправлять команды##nakaz_test',testMode)then ack.v=false end
   g.Checkbox('Проверил игрока, нарушение, исключения и срок##nakaz_ack',ack)
   if ack.v and g.Button(testMode.v and 'Проверить без отправки##nakaz_submit'or 'Подтвердить и отправить##nakaz_submit',g.ImVec2(g.GetContentRegionAvailWidth(),0))then submit()end
  end
 end
 if state.error then g.PushStyleColor(g.Col.Text,integration.color(integration.palette.danger));g.TextWrapped(state.error);g.PopStyleColor()end
 g.End()
end
integration.hudActive=function()return opened.v,opened.v,true end
integration.drawHud=draw
integration.onDisconnect=close
integration.onAccessChanged=close
integration.stop=function()close();art:shutdown()end
integration.open=open

    end
    sources["modules/observer_extras.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/observer_extras.lua
-- Original third-party credits, where present, are retained below.
-- Selected sp_plus features and DeathMatch Informer, on shared X-Tools HUD.
local g=require('imgui')
local events=require('lib.samp.events')
local bit=require('bit')
local u8=require('encoding').UTF8
local settings=integration.service('combo_settings.lua')
local path=integration.storage:path('settings','observer-extras.ini')
local cfg=integration.storage:loadIni({
    keys={enabled=false,x=30,y=200,mode=0},
    gaze={enabled=false,x=30,y=400,length=5,width=2},
    chat={enabled=false,x=400,y=180,lines=13,font=14},
    warnings={enabled=false,x=500,y=350,lines=8,debug=false,rapid=true,obstacles=true,medkit=true,deagle=0.3,m4=0.01},
    dm={enabled=false,x=700,y=220,lines=8,font=9,mode=0,logVisible=true,damageVisible=true,killsVisible=true,damageX=30,damageY=450,killsX=350,killsY=450}
},path)
local samples,aims,chat,warnings,shots,rapid,medkits={},{},{},{},{},{},{}
local lastTarget=nil
local offsets={chat=0,dm=0,warnings=0}
local function now()return getGameTimer()/1000 end
local function save()integration.storage:saveIni(cfg,path)end
if not cfg.chat.nativeVersion then cfg.chat.nativeVersion=1;if cfg.chat.font==14 then cfg.chat.font=8 end;save()end
if not cfg.dm.topVersion then cfg.dm.topVersion=1;cfg.dm.font=9;save()end
local dm=integration.service('dm_informer.lua').new(_G,cfg.dm,save)
local farChat=integration.service('far_chat.lua').new(_G,cfg.chat,save)
local hud=integration.service('hud_panels.lua').new(g,_G,save)
local labels={keys='Клавиши наблюдаемого игрока',gaze='Куда смотрит игрок',chat='Дальний чат',warnings='Варнинги',dm='Информер попаданий'}
for _,id in ipairs({'keys','gaze','chat','warnings','dm'}) do
    integration.keys:register('observer_'..id,labels[id]..': включить / выключить',{key=id=='chat' and 116 or 0,second=0})
end
local function usable()return sampGetGamestate()==3 and not isPauseMenuActive() and isGameWindowForeground()end
local function player(id)
    if not id or not sampIsPlayerConnected(id) then return end
    return tostring(u8(sampGetPlayerNickname(id)))
end
local function streamed(id)
    if not player(id) then return false end
    local localFound,localID=sampGetPlayerIdByCharHandle(PLAYER_PED)
    if localFound and id==localID then return true end
    local found,ped=sampGetCharHandleBySampPlayerId(id)
    return found and ped and doesCharExist(ped)
end
local function push(list,row,limit)
    list[#list+1]=row
    while #list>limit do table.remove(list,1) end
end
local function signed(v) v=tonumber(v) or 0;return v>32767 and v-65536 or v end
local function sample(id,data,vehicle)
    if not cfg.keys.enabled or not streamed(id) then return end
    local observation=integration.observation();if not observation or observation.id~=id then return end
    samples[id]={nick=player(id),time=now(),x=signed(data.leftRightKeys),y=signed(data.upDownKeys),bits=tonumber(data.keysData) or 0,vehicle=vehicle}
end
local function warn(id,text)
    if not player(id) then return end
    local line=player(id)..'['..id..']: '..text
    push(warnings,os.date('%H:%M:%S')..' '..line,100)
    sampAddChatMessage('{FF6060}[Warning] {FFFFFF}'..u8:decode(line),-1)
end
local function onFoot(id)
    if not streamed(id) then return false end
    local own,localID=sampGetPlayerIdByCharHandle(PLAYER_PED)
    local found,ped=sampGetCharHandleBySampPlayerId(id)
    if own and id==localID then found,ped=true,PLAYER_PED end
    return found and ped and doesCharExist(ped) and not isCharInAnyCar(ped)
end
local function checkMedkit(id,data)
    local item=medkits[id]
    if not item then return end
    if not cfg.warnings.enabled or not cfg.warnings.medkit or not usable()
        or not onFoot(id) or item.nick~=player(id) or now()>=item.expires then medkits[id]=nil;return end
    if tonumber(data.animationId)==1157 then item.started=true
    elseif item.started then warn(id,'возможный сбив анимации аптечки');medkits[id]=nil
    elseif now()>item.check then warn(id,'не появилась анимация аптечки');medkits[id]=nil end
end
function events.onPlayerSync(id,data)
    sample(id,data,false)
    checkMedkit(id,data)
end
function events.onSendPlayerSync(data)
    local ok,id=sampGetPlayerIdByCharHandle(PLAYER_PED)
    if ok then
        if cfg.warnings.debug then checkMedkit(id,data) else medkits[id]=nil end
    end
end
function events.onClearPlayerAnimation(id) medkits[id]=nil end
local function startMedkit(id,duration)
    if not cfg.warnings.enabled or not cfg.warnings.medkit or not usable() or not onFoot(id) then return end
    duration=math.min(10,math.max(1,tonumber(duration) or 4))
    medkits[id]={nick=player(id),expires=now()+duration,check=now()+duration-2.1}
end
function events.onVehicleSync(id,vehicle,data) medkits[id]=nil;sample(id,data,true) end
function events.onAimSync(id,data)
    if not cfg.gaze.enabled or not streamed(id) then return end
    local ob=integration.observation();if not ob or ob.id~=id then return end
    local v=data.camFront;if not v then return end
    local x,y,z=tonumber(v.x),tonumber(v.y),tonumber(v.z)
    if not x or not y or not z or x~=x or y~=y or z~=z then return end
    local length=math.sqrt(x*x+y*y+z*z)
    if length<0.001 or length>100 then return end
    aims[id]={nick=player(id),time=now(),x=x/length,y=y/length,z=z/length}
end
function events.onApplyPlayerAnimation(id,lib,name,delta)
    if name=='gum_eat' then startMedkit(id,delta) end
end
function events.onPlayerChatBubble(id,color,distance,duration,text)
    if not streamed(id) then return end
    text=tostring(u8(text)):gsub('{%x%x%x%x%x%x}','')
    if cfg.warnings.enabled and cfg.warnings.medkit and color==-1721303041 and text:match('%+%d+%s+Hp') then
        startMedkit(id,4)
    end
    if not cfg.chat.enabled then return end
    for _,pattern in ipairs({'На паузе %d+:%d+','На паузе %d+ сек.','%d+ hp','%+%d+%s+Hp','На паузе более часа'}) do if text:match(pattern) then return end end
    push(chat,os.date('%H:%M:%S')..' '..player(id)..'['..id..']: '..text,500)
    farChat:add(id,color,text)
end
local weapons={[22]='Glock',[23]='Silenced',[24]='Deagle',[25]='Shotgun',[26]='Sawn-off',[27]='SPAS-12',[28]='Uzi',[29]='MP5',[30]='AK-47',[31]='M4',[32]='TEC-9',[33]='Rifle',[34]='Sniper',[38]='Minigun'}
local function bullet(id,data,own)
    if not (cfg.warnings.enabled or cfg.dm.enabled) or not usable() or not streamed(id) then return end
    local name=player(id);local weapon=tonumber(data.weaponId) or -1;local target=tonumber(data.targetId)
    local hit=tonumber(data.targetType)==1 and player(target)
    if cfg.dm.enabled and hit then
        local ok,localId=sampGetPlayerIdByCharHandle(PLAYER_PED)
        if own or not ok or id~=localId then dm:bullet(id,data)end
    end
    if not cfg.warnings.enabled or own and not cfg.warnings.debug then return end
    if cfg.warnings.rapid and (weapon==24 or weapon==31) then
        local key=id..':'..weapon;local t=now();local row=rapid[key]
        if not row or row.nick~=name then row={nick=name,count=0,last=t,warning=t};rapid[key]=row
        else
            if t-row.warning>7 then row.count=0 end
            local threshold=weapon==24 and cfg.warnings.deagle or cfg.warnings.m4
            if t-row.last<threshold then row.count=row.count+1;row.warning=t end
            if row.count>=3 then warn(id,string.format('слишком быстро стреляет с %s {FF6060}%.2fs. / {60E890}%.2fs.',weapons[weapon],t-row.last,threshold));row.count=0 end
            row.last=t
        end
    end
    if cfg.warnings.obstacles and hit and data.origin and data.target then
        local o,t=data.origin,data.target
        local values={o.x,o.y,o.z,t.x,t.y,t.z};local valid=true;for i=1,6 do local n=values[i];if type(n)~='number' or n~=n or math.abs(n)>100000 then valid=false end end
        if valid and not isLineOfSightClear(o.x,o.y,o.z,t.x,t.y,t.z,true,false,false,false,true) then warn(id,'возможное попадание через препятствие в '..hit) end
    end
end
function events.onBulletSync(id,data)bullet(id,data)end
function events.onSendBulletSync(data)local ok,id=sampGetPlayerIdByCharHandle(PLAYER_PED);if ok then bullet(id,data,true)end end
function events.onSendGiveDamage(id,amount,weapon)dm:rpc(id,amount,weapon,true)end
function events.onSendTakeDamage(id,amount,weapon)dm:rpc(id,amount,weapon,false)end
function events.onPlayerDeathNotification(killer,victim,reason)dm:death(killer,victim,reason)end
function events.onGamemodeRestart()dm:reset()end
function events.onPlayerQuit(id)samples[id]=nil;aims[id]=nil;medkits[id]=nil;for key in pairs(rapid)do if key:match('^(%d+):')==tostring(id)then rapid[key]=nil end end end
local function change(id,value)
    cfg[id].enabled=value
    if id=='dm' and not value then dm:stop()end
    if id=='chat' and not value then farChat:stop()end
    if not value and hud.edit==id then hud:reset() end
    if id=='keys' then samples={} elseif id=='gaze' then aims={} elseif id=='warnings' then rapid={};medkits={} end
    save();integration.refreshInput()
end
integration.update=function()
    local ob=integration.observation();local identity=ob and (ob.id..':'..ob.nickname)
    if identity~=lastTarget then samples={};aims={};lastTarget=identity end
    local allow=usable() and not sampIsChatInputActive() and not sampIsDialogActive() and not sampIsCursorActive()
    for _,id in ipairs({'keys','gaze','chat','warnings','dm'}) do
        local toggle=integration.keys:pressed('observer_'..id)
        if allow and toggle then
            change(id,not cfg[id].enabled)
            integration.notifyToggle(({keys='Клавиши игрока',gaze='Взгляд игрока',chat='Дальний чат',warnings='Предупреждения',dm='Информер попаданий'})[id],cfg[id].enabled)
        end
    end
end
integration.prepareReload=save
integration.onDisconnect=function()save();dm:reset();dm:stop();samples={};aims={};chat={};warnings={};shots={};rapid={};medkits={};hud:reset();farChat:clear();farChat:stop();lastTarget=nil end
integration.stop=integration.onDisconnect
integration.hudActive=function()
    if not usable() then return false,false end
    local ob=integration.observation()
    local visible=cfg.dm.enabled or (ob and cfg.keys.enabled) or hud.edit~=nil or farChat.moving or dm.moving~=nil
    return visible==true,farChat.moving or hud.edit~=nil or dm.moving~=nil,false
end
local function listPanel(id,title,list)
    local p=cfg[id]
    hud:window(id,title,p,math.min(660,tonumber(p.width) or 600),80+math.min(50,p.lines)*22,function()
        local face=integration.fontFace(p.font or 14,false);if face then g.PushFont(face)end
        if #list==0 then g.TextWrapped('Пока нет событий.') end
        local offset=math.max(0,math.min(offsets[id] or 0,math.max(0,#list-p.lines)))
        if sampIsChatInputActive() or sampIsDialogActive() or hud.edit==id then
            if g.Button('< Раньше##history_'..id) then offset=math.min(math.max(0,#list-p.lines),offset+p.lines)end
            g.SameLine();if g.Button('Позже >##history_'..id) then offset=math.max(0,offset-p.lines)end
        end
        offsets[id]=offset
        for i=math.max(1,#list-offset-p.lines+1),#list-offset do g.TextWrapped(list[i]) end
        if face then g.PopFont()end
    end)
end
integration.drawHud=function()
    if not integration.hudActive() then return end
    local ob=integration.observation()
    if cfg.keys.enabled and (ob or hud.edit=='keys') then
        hud.noTitle=true
        hud:window('keys','Клавиши игрока',cfg.keys,396,(cfg.keys.mode==2 or ob and cfg.keys.mode==0 and ob and ob.mobile)and 150 or 88,function()
            local row=ob and samples[ob.id]
            if not row or now()-row.time>2 then
                if hud.edit=='keys' then row={time=now(),x=0,y=0,bits=0,vehicle=false}
                else g.Text('Ожидание данных игрока.');return end
            end
            local mobile=cfg.keys.mode==2 or cfg.keys.mode==0 and ob and ob.mobile
            if mobile then
                local p=g.GetCursorScreenPos();local draw=g.GetWindowDrawList();local center=g.ImVec2(p.x+55,p.y+55)
                draw:AddCircle(center,44,0xFFB5A0FF,32,2)
                draw:AddCircleFilled(g.ImVec2(center.x+math.max(-1,math.min(1,row.x/128))*32,center.y+math.max(-1,math.min(1,row.y/128))*32),12,0xFFB5A0FF)
                g.Dummy(g.ImVec2(115,112));g.Text('Мобильный джойстик')
            else
                integration.service('key_overlay.lua').draw(g,row,0xFFFFA0B5)
            end
        end,true)
        hud.noTitle=false
    end

end
integration.onD3DPresent=function()
    if usable() then farChat:draw();dm:draw()end
    if not cfg.gaze.enabled or not usable() then return end
    local ob=integration.observation();local a=ob and aims[ob.id]
    if not a or now()-a.time>2 or a.nick~=tostring(u8(ob.nickname)) then return end
    local found,ped=sampGetCharHandleBySampPlayerId(ob.id);if not found then return end
    local x,y,z=getCharCoordinates(ped);z=z+0.7
    local ex,ey,ez=x+a.x*cfg.gaze.length,y+a.y*cfg.gaze.length,z+a.z*cfg.gaze.length
    if isPointOnScreen(x,y,z,1) and isPointOnScreen(ex,ey,ez,1) then
        local sx,sy=convert3DCoordsToScreen(x,y,z);local tx,ty=convert3DCoordsToScreen(ex,ey,ez)
        renderDrawLine(sx,sy,tx,ty,cfg.gaze.width,0xFFB5A0FF)
    end
end
local expanded={}
local function controls(id)
    if settings.toggle(g,labels[id],cfg[id],'enabled') then change(id,cfg[id].enabled) end
    g.SameLine()
    if g.Button('Настройки##observer_settings_'..id)then expanded[id]=not expanded[id]end
    if not expanded[id]then return false end
    g.Spacing()
    integration.keys:draw(g,'observer_'..id)
    if id~='warnings' and id~='gaze'then
    if g.Button('Переместить##observer_'..id) then
        change(id,true)
        if id=='dm' then dm.moving='log'
        elseif id=='chat' then farChat.moving=true;farChat.placing=true
        else hud:move(id);hud.placing=true;hud.follow=true end
        integration.beginPlacement(function()dm.moving=nil;hud:reset();farChat.moving=false;farChat.placing=false;save()end)
    end
    g.SameLine();if g.Button('Сброс позиции##observer_'..id) then cfg[id].x=30;cfg[id].y=180;save()end
    end
    return true
end
integration.drawSettings=function()
    for _,id in ipairs({'keys','gaze','chat'})do
        g.Separator();if controls(id)then
        local p=cfg[id];local dirty=false;g.PushItemWidth(140)
        if id=='keys' then
            local mode=g.ImInt(p.mode);if g.Combo('Отображение##keys_mode',mode,'Авто\0Клавиатура\0Джойстик\0\0')then p.mode=mode.v;dirty=true end
        elseif id=='gaze' then
            dirty=settings.integer(g,'Длина линии, м',p,'length',5,1,30) or dirty
            dirty=settings.integer(g,'Толщина линии',p,'width',2,1,8) or dirty
        else
            dirty=settings.integer(g,'Строк на экране##'..id,p,'lines',13,1,50) or dirty
            dirty=settings.integer(g,'Размер шрифта##'..id,p,'font',id=='chat'and 8 or 14,6,22) or dirty
            if g.Button('Очистить##observer_'..id)then if id=='dm'then shots={}else chat={};farChat:clear()end end
            if id=='dm' then
                if g.CollapsingHeader('История попаданий (до 50)') then for _,line in ipairs(shots)do g.TextWrapped(line)end end
                g.TextWrapped('Показывает попадания по BulletSync, а не подтверждённый урон сервера. История: последние 50 попаданий.')end
            
        end
        g.PopItemWidth();if dirty then save()end
        end
    end
end
integration.drawHitHistory=function()
    g.Separator();g.Text('Информер · Урон и фраги')
    if controls('dm')then
        local p=cfg.dm
        local dirty=settings.integer(g,'Строк попаданий',p,'lines',8,1,30)
        dirty=settings.integer(g,'Размер текста информера',p,'font',9,6,18)or dirty
        local mode=g.ImInt(p.mode)
        if g.Combo('Счётчик урона',mode,'Оценка по попаданиям\0С вашим участием\0\0')then p.mode=mode.v;dirty=true end
        g.TextWrapped('~ — оценка урона. Режим «С вашим участием» учитывает урон, нанесённый и полученный вашим персонажем.')
        for _,row in ipairs({{'log','Попадания'},{'damage','Топ-10 по урону'},{'kills','Топ-10 по фрагам'}})do
            dirty=settings.toggle(g,row[2],p,row[1]..'Visible')or dirty
            if g.Button('Переместить '..row[2]..'##dm_'..row[1])then
                change('dm',true);dm.moving=row[1]
                integration.beginPlacement(function()dm.moving=nil;save()end)
            end
        end
        if dirty then save()end
    end
    if g.Button('Обнулить урон, фраги и историю##dm_reset')then dm:reset()end
    for i=math.max(1,#dm.rows-49),#dm.rows do
        local row=dm.rows[i]
        if row.red then g.TextColored(g.ImVec4(1,0.38,0.38,1),row.text)else g.TextWrapped(row.text)end
    end
end
integration.draw=function()
    local showSettings=controls('warnings')
    if showSettings then
    
    local p=cfg.warnings;local dirty=settings.toggle(g,'Отладка: свои выстрелы и аптечки',p,'debug')
    for _,v in ipairs({{'Слишком быстрая стрельба','rapid'},{'Попадания через препятствия','obstacles'},{'Сбив или отсутствие анимации аптечки','medkit'}})do dirty=settings.toggle(g,v[1],p,v[2])or dirty end
    g.PushItemWidth(140)
    for _,v in ipairs({{'Deagle: минимальный интервал, сек.','deagle',0.01,1.5},{'M4: минимальный интервал, сек.','m4',0.001,0.5}})do
        local n=g.ImFloat(p[v[2]]);if g.InputFloat(v[1],n,0,0)then p[v[2]]=math.max(v[3],math.min(v[4],n.v));dirty=true end
    end
    g.PopItemWidth()
    if dirty then save()end
    if g.Button('Очистить варнинги')then warnings={}end
    end
    for i=math.max(1,#warnings-30),#warnings do g.TextWrapped(warnings[i])end
end


integration.layoutItems=function()
 local out={}
 for _,entry in ipairs({{'keys','Клавиши игрока',396,90},{'chat','Дальний чат',420,150},{'dm','Информер попаданий',500,160}})do
  local id=entry[1];local p=cfg[id]
  out[#out+1]={name=entry[2],x=p.x,y=p.y,w=entry[3],h=id=='keys' and (cfg.keys.mode==2 and 150 or 90) or entry[4],preview=function(x,y)
   if id=='chat' then farChat:draw(true,x,y)
   elseif id=='dm' then dm:draw('log',x,y)
   else
    g.SetNextWindowPos(g.ImVec2(x,y),g.Cond.Always)
    g.SetNextWindowSize(g.ImVec2(396,cfg.keys.mode==2 and 150 or 90),g.Cond.Always)
    g.Begin('##layout_keys_preview',nil,g.WindowFlags.NoTitleBar+g.WindowFlags.NoResize+g.WindowFlags.NoInputs+g.WindowFlags.NoSavedSettings)
    if cfg.keys.mode==2 then
     local point=g.GetCursorScreenPos();local draw=g.GetWindowDrawList();local center=g.ImVec2(point.x+55,point.y+55)
     draw:AddCircle(center,44,0xFFB5A0FF,32,2);draw:AddCircleFilled(center,12,0xFFB5A0FF)
     g.Dummy(g.ImVec2(115,112));g.Text('Мобильный джойстик')
    else integration.service('key_overlay.lua').draw(g,{time=now(),x=0,y=0,bits=0,vehicle=false},0xFFFFA0B5)end
    g.End()
   end
  end,set=function(x,y)p.x=x;p.y=y;save()end}
 end
 for _,kind in ipairs({'damage','kills'})do
  local key=kind
  out[#out+1]={name=kind=='damage'and'Топ-10 · Урон'or'Топ-10 · Фраги',x=cfg.dm[key..'X'],y=cfg.dm[key..'Y'],w=300,h=180,preview=function(x,y)dm:draw(key,x,y)end,set=function(x,y)cfg.dm[key..'X']=x;cfg.dm[key..'Y']=y;save()end}
 end
 return out
end

    end
    sources["modules/online.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/online.lua
-- Original third-party credits, where present, are retained below.
-- Clear Online functions integrated into CasualTool; no independent updater/window.
local imgui,events=require 'imgui',require 'samp.events'
local encoding=require 'encoding'
local stats=integration.service('online_stats.lua')
local storage=integration.storage
local configPath=storage:path('settings','online.ini')
local legacy={}
for _,name in ipairs({'config.ini','goals_config.ini','historical_data.txt','week_data.txt','monthly_data.txt','stats_data.txt','counted_days.txt','reset_flag.txt','monthly_reset_flag.txt'}) do
    legacy[name]=storage:path('data','online_legacy/'..name,{integration.root..'/ClearOnline/'..name})
end
local config=storage:loadIni({main={enabled=true,auto=false,interval=60,notifications=true,report=false},
    goals={daily=120,weekly=840,monthly=3600}},configPath)
local settings,goals=config.main,config.goals
if not storage:exists(configPath) then
    local old=storage:read(legacy['goals_config.ini']) or ''
    for _,key in ipairs({'daily','weekly','monthly'}) do goals[key]=tonumber(old:match(key..'_goal=(%d+)')) or goals[key] end
    if old:match('notifications=false') then settings.notifications=false end
    local preferences=storage:read(legacy['config.ini']) or ''
    settings.interval=tonumber(preferences:match('auto_check_interval=(%d+)')) or settings.interval
    settings.report=preferences:match('display_mode=chat')~=nil
    -- Automatic server queries remain opt-in after migration.
    storage:saveIni(config,configPath)
end
local function bound(value,minimum,maximum,fallback)
    value=tonumber(value)
    if not value or value~=value then return fallback end
    return math.floor(math.max(minimum,math.min(maximum,value)))
end
settings.interval=bound(settings.interval,60,3600,60)
for _,key in ipairs({'enabled','auto','notifications','report'}) do settings[key]=settings[key]==true end
for key,limit in pairs({daily=1440,weekly=10080,monthly=44640}) do goals[key]=bound(goals[key],1,limit,120) end
local ledger,path,identity,pending,lastRequest,lastSnapshot,status
local historyPage=1
local function saveConfig() storage:saveIni(config,configPath) end
local function duration(minutes)
    minutes=math.floor(minutes or 0)
    return string.format('%d ч %02d мин',math.floor(minutes/60),minutes%60)
end
local function account()
    if not isSampAvailable() or sampGetGamestate()~=3 or not integration.access:can(1) then return end
    local found,id=sampGetPlayerIdByCharHandle(PLAYER_PED)
    if not found then return end
    local nickname=sampGetPlayerNickname(id)
    local server,port=sampGetCurrentServerAddress()
    if not nickname then return end
    -- Byte encoding avoids unsafe filenames and preserves distinct identities.
    local raw=server..':'..tostring(port)..'/'..nickname
    return (raw:gsub('.',function(char) return string.format('%02x',char:byte()) end)),nickname
end
local function sync()
    local current=account()
    if current~=identity then
        identity=current;pending=nil;lastRequest=nil;lastSnapshot=nil;historyPage=1
        ledger,path=nil,nil
        if current then
            path=storage:path('data','online/'..current..'.ini')
            ledger=storage:loadIni({days={},notified={},meta={}},path)
            for key,value in pairs(ledger.days) do
                if not stats.timestamp(key) or not tonumber(value) or tonumber(value)<0 or tonumber(value)>1440 then ledger.days[key]=nil end
            end
        end
    end
    return ledger~=nil
end
local function request()
    if not integration.access:can(2) then status='Сбор чистого онлайна доступен с 2 уровня.';return end
    if not settings.enabled then status='Включите учёт в настройках модуля.';return end
    if not sync() then status='Ожидание подтверждённых прав администратора.';return end
    if pending or lastRequest and os.clock()-lastRequest<10 then return end
    if sampIsDialogActive() or integration.queryBusy('time') then status='Дождитесь закрытия текущего диалога.';return end
    lastRequest=os.clock();pending={started=lastRequest,identity=identity,revision=integration.access:revision()}
    sampSendChat('/c 60');status='Ожидание ответа службы времени…'
end
local function accept(snapshot)
    ledger.days[snapshot.date]=snapshot.today
    if snapshot.yesterday then ledger.days[stats.shift(snapshot.date,-1)]=snapshot.yesterday end
    ledger.meta.lastDate=snapshot.date
    lastSnapshot=snapshot
    local summary=stats.summary(ledger.days,snapshot.date)
    for _,item in ipairs({{'daily',snapshot.date,'день'},{'weekly',stats.week(snapshot.date),'неделю'},{'monthly',snapshot.date:sub(1,7),'месяц'}}) do
        local key=item[1]..'_'..item[2]
        if settings.notifications and summary[item[1]]>=goals[item[1]] and not ledger.notified[key] then
            ledger.notified[key]=true;integration.message('Цель онлайна за '..item[3]..' выполнена: '..duration(summary[item[1]])..'.')
        end
    end
    local saved=storage:saveIni(ledger,path)
    status=saved and 'Обновлено по данным сервера: '..snapshot.date or 'Ошибка сохранения. Проверьте раздел «Система».'
    if settings.report then integration.message('Чистый онлайн: сегодня '..duration(summary.daily)..', неделя '..duration(summary.weekly)..', месяц '..duration(summary.monthly)..'.') end
end
function events.onShowDialog(id,style,title,button1,button2,text)
    if not integration.access:can(2) then pending=nil;return end
    if not settings.enabled or not sync() then return end
    local decoded=tostring(encoding.UTF8(text or ''))
    local snapshot,reason=stats.parse(decoded)
    if not snapshot then if reason then status=reason;pending=nil end;return end
    local owned=pending and os.clock()-pending.started<=30 and pending.identity==identity and pending.revision==integration.access:revision()
    pending=nil;accept(snapshot)
    -- Observe manually requested dialogs without swallowing or replacing them.
    if owned then return false end
end
function integration.update()
    if not sync() then return end
    if not integration.access:can(2) then pending=nil;return end
    if pending and os.clock()-pending.started>30 then pending=nil;status='Служба времени не ответила за 30 секунд.' end
    if settings.enabled and settings.auto and (not lastRequest or os.clock()-lastRequest>=settings.interval) then request() end
end
function integration.onDisconnect()
    identity,ledger,path,pending,lastSnapshot,lastRequest=nil,nil,nil,nil,nil,nil
end
function integration.queryPending(kind) return kind=='time' and pending~=nil end
function events.onSendCommand(command)
    if tostring(command):match('^/c%s+60%s*$') and integration.commandOwner()~='online' then pending=nil end
end
function integration.start()
end
function integration.draw()
    if imgui.Button('Обновить онлайн##online_refresh') then request() end
    if status then imgui.TextWrapped(status) end
    if not sync() or not ledger.meta.lastDate then
        imgui.TextWrapped('Запросите /c 60 или нажмите «Обновить онлайн». Время без AFK появится после ответа сервера.');return
    end
    local date=ledger.meta.lastDate
    local summary=stats.summary(ledger.days,date)
    imgui.TextWrapped('Последний серверный день: '..date..'. Суммы включают только сохранённые дни; пропущенные дни не восстанавливаются автоматически.')
    local columns=integration.layout.begin('online_summary',760)
    integration.layout.heading('Чистый онлайн и цели')
    for _,item in ipairs({{'daily','День'},{'weekly','Неделя'},{'monthly','Месяц'}}) do
        local value=summary[item[1]]
        imgui.Text(item[2]..': '..duration(value)..' / '..duration(goals[item[1]]))
        imgui.ProgressBar(math.min(1,value/goals[item[1]]),imgui.ImVec2(-1,16),string.format('%.0f%%',value/goals[item[1]]*100))
    end
    if lastSnapshot then imgui.Text('Всего сегодня: '..duration(lastSnapshot.total));imgui.Text('AFK: '..duration(lastSnapshot.afk)) end
    integration.layout.next(columns)
    integration.layout.heading('Рекорды и средние значения')
    for _,item in ipairs({{'dayBest','Лучший день'},{'weekBest','Лучшая неделя'},{'monthBest','Лучший месяц'}}) do
        imgui.TextWrapped(item[2]..': '..duration(summary[item[1]])..' · '..(summary[item[1]..'Date'] or '—'))
    end
    imgui.Text('В среднем за записанный день: '..duration(summary.average))
    imgui.Text('В среднем за записанную неделю: '..duration(summary.weekAverage))
    integration.layout.finish(columns)
    if imgui.CollapsingHeader('Динамика за последние 7 дней##online_trend') then
        for offset=-6,0 do
            local key=stats.shift(date,offset)
            local value=ledger.days[key]
            imgui.Text(key..': '..(value and duration(value) or 'нет записи'))
            imgui.ProgressBar(math.min(1,(tonumber(value) or 0)/goals.daily),imgui.ImVec2(-1,12),'')
        end
    end
    integration.layout.heading('История по дням')
    local dates={};for key in pairs(ledger.days) do dates[#dates+1]=key end;table.sort(dates,function(a,b)return a>b end)
    local pages=math.max(1,math.ceil(#dates/10));historyPage=math.min(historyPage,pages)
    for index=(historyPage-1)*10+1,math.min(#dates,historyPage*10) do
        local key=dates[index];imgui.Text(key..'    '..duration(ledger.days[key]))
    end
    if historyPage>1 and imgui.Button('Назад##online_history') then historyPage=historyPage-1 end
    if historyPage<pages and imgui.Button('Далее##online_history') then historyPage=historyPage+1 end
    imgui.TextDisabled(string.format('Страница %d / %d',historyPage,pages))
end
function integration.drawSettings()
    for _,item in ipairs({{'enabled','Учитывать чистый онлайн'},{'auto','Автоматически запрашивать /c 60'},
        {'notifications','Уведомлять о достижении целей'},{'report','Показывать сводку в моём чате'}}) do
        local value=imgui.ImBool(settings[item[1]])
        if imgui.Checkbox(item[2],value) then settings[item[1]]=value.v;pending=nil;saveConfig() end
    end
    local interval=imgui.ImInt(settings.interval)
    if imgui.InputInt('Интервал проверки, сек.',interval) then settings.interval=bound(interval.v,60,3600,60);saveConfig() end
    integration.layout.heading('Цели в минутах')
    for _,item in ipairs({{'daily','День',1440},{'weekly','Неделя',10080},{'monthly','Месяц',44640}}) do
        local value=imgui.ImInt(goals[item[1]])
        if imgui.InputInt(item[2]..'##online_goal',value) then goals[item[1]]=bound(value.v,1,item[3],120);saveConfig() end
    end
    imgui.TextWrapped('Неделя начинается в понедельник. Периоды определяются датой из ответа сервера. История разделена по серверу и нику; прежние дни сохраняются при смене недели и месяца.')
    local oldHistory=storage:read(legacy['historical_data.txt'])
    if oldHistory then
        imgui.TextWrapped('Прежние файлы ClearOnline скопированы в data/online_legacy. У них нет привязки к аккаунту. Импортируйте историю только в нужном аккаунте; существующие дни не заменяются.')
        if imgui.Button('Импортировать старую историю в текущий аккаунт##online_import') and sync() then
            local section,count=nil,0
            for line in oldHistory:gmatch('[^\r\n]+') do
                if line:match('^# Daily data') then section='daily'
                elseif line:match('^#') then section=nil
                elseif section=='daily' then
                    local date,minutes=line:match('^(%d%d%d%d%-%d%d%-%d%d):%s*(%d+)')
                    minutes=tonumber(minutes)
                    if date and stats.timestamp(date) and minutes and minutes<=1440 and ledger.days[date]==nil then
                        ledger.days[date]=minutes;count=count+1
                    end
                end
            end
            if not ledger.meta.lastDate then
                for date in pairs(ledger.days) do if not ledger.meta.lastDate or date>ledger.meta.lastDate then ledger.meta.lastDate=date end end
            end
            storage:saveIni(ledger,path);integration.message('Импортировано дней: '..count..'. Старые сводные файлы сохранены в архиве данных.')
        end
    end
end

    end
    sources["modules/punishment_log.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/punishment_log.lua
-- Original third-party credits, where present, are retained below.
local g=require('imgui')
local u8=require('encoding').UTF8
local events=require('lib.samp.events')
local path=integration.storage:path('logs','my-punishments.ini')
local data=integration.storage:loadIni({main={count=0}},path)
local page=1
local verbs={
 {'забанил оффлайн игрока','Бан'},{'заблокировал оффлайн игрока','Бан'},
 {'забанил игрока','Бан'},{'заблокировал игрока','Бан'},
 {'посадил в тюрьму игрока','Тюрьма'},{'посадил в тюрьму','Тюрьма'},{'посадил игрока','Тюрьма'},{'посадил в КПЗ игрока','Тюрьма'},
 {'поставил заглушку игроку','Мут'},{'поставил затычку игроку','Мут'},{'выдал затычку игроку','Мут'},
 {'выдал предупреждение игроку','Предупреждение'},{'кикнул игрока','Кик'}}
function events.onServerMessage(color,raw)
 local text=tostring(u8(raw)):gsub('{%x%x%x%x%x%x}','')
 local actor,body=text:match('^Администратор%s+([%w_]+)%[%d+%]%s+(.+)$')
 if not actor then actor,body=text:match('^Администратор%s+([%w_]+)%s+(.+)$')end
 if not actor then actor,body=text:match('^%[A%]%s+([%w_]+)%[%d+%]%s+(.+)$')end
 local ok,id=sampGetPlayerIdByCharHandle(PLAYER_PED)
 if not actor or not ok or actor:lower()~=tostring(sampGetPlayerNickname(id)):lower()then return end
 for _,v in ipairs(verbs)do
  if body:sub(1,#v[1]+1)==v[1]..' 'then
   local target,rest=body:sub(#v[1]+2):match('^([%w_]+)(.*)$')
   if not target then return end
   local reason=rest:match('[Пп]ричина:%s*(.+)$')or 'Не указана сервером'
   local duration=rest:match('на%s+(%d+%s*[^%.,]+)')or '—'
   local count=math.min(tonumber(data.main.count)or 0,1000)
   if count==1000 then for i=1,999 do data['row'..i]=data['row'..(i+1)]end;count=999 end
   count=count+1;data.main.count=count
   data['row'..count]={time=os.date('%d.%m.%Y %H:%M:%S'),actor=actor,target=target,kind=v[2],duration=duration,reason=reason,text=text}
   integration.storage:saveIni(data,path);page=1
   return
  end
 end
end
integration.draw=function()
 g.Separator();g.Text('Мои наказания · история')
 local rows={};local ok,id=sampGetPlayerIdByCharHandle(PLAYER_PED)
 local own=ok and tostring(sampGetPlayerNickname(id)):lower()or''
 for i=tonumber(data.main.count)or 0,1,-1 do local r=data['row'..i];if r and r.actor:lower()==own then rows[#rows+1]=r end end
 local pages=math.max(1,math.ceil(#rows/8));page=math.min(page,pages)
 if g.Button('<##punishments_prev')then page=math.max(1,page-1)end
 g.SameLine();g.Text(('Страница %d / %d · записей: %d'):format(page,pages,#rows))
 g.SameLine();if g.Button('>##punishments_next')then page=math.min(pages,page+1)end
 if #rows==0 then g.TextWrapped('Выданные наказания появятся после подтверждения в чате сервера.')end
 for i=(page-1)*8+1,math.min(page*8,#rows)do
  local r=rows[i];g.Separator()
  g.TextWrapped(r.time..' · '..r.kind..' · '..r.target)
  g.TextWrapped('Срок: '..r.duration..' · Причина: '..r.reason)
  if g.Button('Копировать##punishment_'..i)then setClipboardText(u8:decode(r.time..' '..r.text))end
 end
end

    end
    sources["modules/queue.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/queue.lua
-- Original third-party credits, where present, are retained below.
-- File-backed, explicitly started command queue. All UI belongs to CasualTool.
local imgui, sampev, u8 = require 'imgui', require 'samp.events', require('encoding').UTF8
local root=integration.root or getWorkingDirectory()
local storage=integration.storage
local primary=storage:path('data', 'command_queue.txt', {root..'/command_queue.txt', root..'/offban_commands.txt'})
local RESPONSE_TIMEOUT=22000
local settingsPath=storage:path('settings','queue.ini')
local settings=storage:loadIni({main={interval=30}},settingsPath)
settings.main.interval=math.max(1,math.min(300,tonumber(settings.main.interval) or 30))
local editor,editorSnapshot
local state={running=false,generation=0,page=1,index=0,total=0,done=0,status='Очередь не запущена.'}
local function message(text) state.status=text; integration.message(text) end
local function read(path)
    local file=io.open(path,'rb'); if not file then return end
    local text=file:read('*a'); file:close(); return text
end
local function write(path,text)
    local file,err=io.open(path,'wb'); if not file then return nil,err end
    local ok,reason=file:write(text); local closed,closeError=file:close()
    if not ok or not closed then return nil,reason or closeError end
    return true
end
local function utf8(text)
    local i=1
    while i<=#text do
        local a,b,c,d=text:byte(i,i+3)
        local function cont(x) return x and x>=128 and x<=191 end
        if a<128 then i=i+1
        elseif a>=194 and a<=223 and cont(b) then i=i+2
        elseif a>=224 and a<=239 and cont(b) and cont(c) and (a~=224 or b>=160) and (a~=237 or b<=159) then i=i+3
        elseif a>=240 and a<=244 and cont(b) and cont(c) and cont(d) and (a~=240 or b>=144) and (a~=244 or b<=143) then i=i+4
        else return false end
    end
    return true
end
local function loadQueue()
    local path=primary
    local raw=read(path)
    if not raw then return nil,'Файл не найден. Создайте шаблон и добавьте свои команды.' end
    if #raw>2*1024*1024 then return nil,'Файл очереди превышает 2 МБ.' end
    local bom=raw:sub(1,3)=='\239\187\191'
    local body=bom and raw:sub(4) or raw
    local isUtf8=utf8(body)
    if bom and not isUtf8 then return nil,'Повреждена кодировка UTF-8 в файле очереди.' end
    local data={path=path,raw=raw,bom=bom,utf8=isUtf8,newline=body:find('\r\n',1,true) and '\r\n' or '\n',lines={},items={},invalid=0,completed=0}
    for line in (body:gsub('\r\n','\n')..'\n'):gmatch('(.-)\n') do
        data.lines[#data.lines+1]=line
        local trimmed=line:match('^%s*(.-)%s*$')
        if trimmed~='' and not trimmed:match('^#') and not trimmed:match('^//') then
            if trimmed:match('%s%[[^%[%]]*%]$') then data.completed=data.completed+1
            else
                local ok,cp=pcall(function() return isUtf8 and u8:decode(trimmed) or trimmed end)
                local valid=ok and cp and cp:match('^/[%w_]+') and not cp:find('[%z\1-\31]') and #cp<=144
                local labelOk,label=pcall(function() return isUtf8 and trimmed or u8(trimmed) end)
                if not labelOk then valid=false; label='Некорректная кодировка строки' end
                data.items[#data.items+1]={line=#data.lines,command=valid and cp or nil,label=label,original=line}
                if not valid then data.invalid=data.invalid+1 end
            end
        end
    end
    return data
end
local function reload()
    if state.running then message('Сначала остановите очередь.'); return end
    local data,err=loadQueue(); state.data=data; state.page=1; state.done=0
    state.status=data and ('Ожидают отправки: '..#data.items..'. Уже отмечены: '..data.completed..'. Ошибок: '..data.invalid..'.') or err
    return data
end
local function mark(data,item,result)
    -- A stale UI snapshot must never overwrite a user's edits in their editor.
    if read(data.path)~=data.raw then return nil,'Файл изменён извне; очередь остановлена. Проверьте последнюю попытку перед повторным запуском.' end
    result=result:gsub('[\r\n%[%]]',' ')
    local suffix=data.utf8 and result or u8:decode(result)
    local previous=data.lines[item.line]
    data.lines[item.line]=item.original..' ['..suffix..']'
    local raw=(data.bom and '\239\187\191' or '')..table.concat(data.lines,data.newline)
    -- Keep the pre-write file recoverable if disk writing fails partway through.
    local backup,backupError=write(data.path..'.casualat.bak',data.raw)
    if not backup then data.lines[item.line]=previous; return nil,'Не сохранена резервная копия: '..tostring(backupError) end
    local ok,err=write(data.path,raw)
    if not ok then data.lines[item.line]=previous; return nil,'Не сохранён статус; очередь остановлена: '..tostring(err) end
    data.raw=raw
    return true
end
local function alive(generation)
    return state.running and generation==state.generation and isSampAvailable() and sampGetGamestate()==3
        and state.accessRevision==integration.access:revision() and integration.access:can(4)
end
local function delay(ms,generation)
    local deadline=getGameTimer()+ms
    repeat
        if not alive(generation) then return false end
        wait(math.min(200,math.max(0,deadline-getGameTimer())))
    until getGameTimer()>=deadline
    return alive(generation)
end
local function stop(reason)
    integration.cancelPending()
    state.running=false; state.generation=state.generation+1; state.waiting=nil; state.query=nil
    state.status=reason or 'Очередь остановлена. Уже начатые попытки не повторяются.'
end
local function start()
    if state.running then message('Очередь уже работает.'); return end
    if not isSampAvailable() or sampGetGamestate()~=3 then message('Дождитесь подключения к серверу.'); return end
    if not integration.access:require(4, message) then return end
    local data,err=loadQueue()
    if not data then message(err); return end
    state.data=data
    if data.invalid>0 then message('Исправьте строки с ошибками: '..data.invalid..'. Нужны команды с / длиной до 144 байт.'); return end
    if #data.items==0 then message('В файле нет команд без отметки результата.'); return end
    state.running=true; state.generation=state.generation+1
    state.accessRevision=integration.access:revision()
    state.total=#data.items; state.done=0; state.index=0
    local generation=state.generation
    lua_thread.create(function()
        for index,item in ipairs(data.items) do
            if not alive(generation) then break end
            local kind=item.command:match('^/(%S+)'):lower()
            while alive(generation) and integration.queryBusy(kind) do
                state.status='Ожидание завершения другого запроса /'..kind..'…'
                wait(100)
            end
            if not alive(generation) then break end
            state.index=index; state.response=nil
            -- Persist BEFORE invoking: a crash/disconnect cannot silently retry a punishment.
            local marked,why=mark(data,item,'X-Tools: попытка начата; результат не подтверждён')
            if not marked then stop(why); integration.message(why); return end
            state.query=kind
            item.result='Ожидание подтверждения';state.waiting=item.command:match('^/%S+%s+(%S+)');state.command=item.label
            local targetId=tonumber(state.waiting)
            state.expectedTarget=targetId and sampIsPlayerConnected(targetId) and sampGetPlayerNickname(targetId) or state.waiting
            local sent,sendError=pcall(sampSendChat,item.command)
            state.done=index
            if not sent then
                state.waiting=nil
                mark(data,item,'X-Tools: ошибка отправки; результат не подтверждён')
                stop('Ошибка отправки: '..tostring(sendError)); return
            end
            state.status='Попытка '..index..' из '..#data.items..'. Ожидание ответа…'
            local deadline=getGameTimer()+RESPONSE_TIMEOUT
            while alive(generation) and not state.response and getGameTimer()<deadline do
                state.response=integration.guardResult(item.label);wait(200)
            end
            state.waiting=nil; state.query=nil
            if not alive(generation) then break end
            local note=state.response and ('Результат: '..state.response) or 'X-Tools: запрос передан; ответ не подтверждён'
            item.result=state.response and ('Ответ: '..state.response) or 'Нет подтверждения сервера'
            local saved,reason=mark(data,item,note)
            if not saved then stop(reason); integration.message(reason); return end
            if index<#data.items then
                state.status='Отправлено попыток: '..index..'. Пауза '..settings.main.interval..' сек.'
                if not delay(settings.main.interval*1000,generation) then break end
            end
        end
        if generation==state.generation then
            stop('Очередь завершена. Попыток: '..state.done..'. Результаты проверьте в файле и на сервере.')
        end
    end)
end
function sampev.onServerMessage(_,text)
    if not state.waiting or state.response then return end
    local ok,decoded=pcall(function() return u8(text or '') end)
    if not ok then return end
    local clean=tostring(decoded):gsub('{%x%x%x%x%x%x}','')
    local found,id=sampGetPlayerIdByCharHandle(PLAYER_PED)
    local actor=found and sampGetPlayerNickname(id)
    if integration.service('queue_confirmation.lua').match(state.command,clean,state.expectedTarget,actor)then state.response=clean end
end
local function status() integration.message(state.status) end
local function template()
    if read(primary)~=nil then message('Файл очереди уже существует.'); return end
    local ok,err=write(primary,'\239\187\191# X-Tools: по одной команде с / на строку.\r\n# Комментарии начинаются с # или //.\r\n# Строки с итоговой отметкой [результат] повторно не отправляются.\r\n# Добавьте свои команды ниже. Запуск — кнопкой в меню.\r\n')
    if not ok then message('Не удалось создать файл: '..tostring(err)); return end
    reload()
end
integration.startQueue=start
integration.stopQueue=stop
integration.reloadQueue=reload
function integration.start() end
integration.draw=function()
    if not integration.access:can(4) then imgui.TextDisabled("Очередь команд доступна с 4 уровня.");return end
    local wide=imgui.GetContentRegionAvailWidth()>=680
    imgui.BeginChild('##queue_summary',imgui.ImVec2(0,state.running and 132 or 108),true)
    imgui.Text(state.running and 'ВЫДАЧА НАКАЗАНИЙ' or 'ОЧЕРЕДЬ НАКАЗАНИЙ')
    imgui.TextWrapped(state.status)
    local count=state.data and #state.data.items or 0
    imgui.TextDisabled('В очереди: '..count..'     Обработано: '..state.done..'     Ошибок: '..(state.data and state.data.invalid or 0))
    if state.running and state.total>0 then imgui.ProgressBar(state.done/state.total,imgui.ImVec2(-1,18),state.done..' / '..state.total)end
    imgui.EndChild()
    imgui.Spacing()
    imgui.Text('Управление очередью')
    local interval=imgui.ImInt(settings.main.interval)
    imgui.TextWrapped('Пауза между командами, сек. (1–300)')
    imgui.PushItemWidth(math.min(180,imgui.GetContentRegionAvailWidth()))
    if imgui.InputInt('##queue_interval',interval,0,0) then settings.main.interval=math.max(1,math.min(300,interval.v));storage:saveIni(settings,settingsPath) end
    imgui.PopItemWidth()
    if state.running then
        if imgui.Button('Остановить##queue_stop') then stop() end
    elseif editor then
        -- Editor replaces the journal. Its own scroll area never contains action buttons.
        if imgui.Button('Сохранить файл##queue_save') then
            if (read(primary) or '')~=editorSnapshot then message('Файл изменён извне. Сохранение отменено; перечитайте файл.')
            else
                local ok,err=storage:write(primary,editor.v)
                if ok then editor=nil;reload() else message('Ошибка записи: '..tostring(err)) end
            end
        end
        if wide then imgui.SameLine() end
        if imgui.Button('Закрыть редактор##queue_close_editor') then editor=nil end
    else
        if imgui.Button('Прочитать файл##queue_read') then reload() end
        if wide then imgui.SameLine() end
        if imgui.Button('Редактировать в игре##queue_editor') then
            editorSnapshot=read(primary) or ''
            local text=editorSnapshot:gsub('^\239\187\191','')
            if not utf8(text) then text=u8(text) end
            if #text>262140 then message('Для большого файла используйте внешний редактор.')
            else editor=imgui.ImBuffer(262144);editor.v=text end
        end
        if not editor and state.data and #state.data.items>0 and state.data.invalid==0 then
            if wide then imgui.SameLine() end
            if imgui.Button('Запустить очередь##queue_start') then start() end
        end
        if not state.data then
            if imgui.Button('Создать пустой шаблон##queue_template') then template() end
        end
    end
    if imgui.CollapsingHeader('Файл и отметки##queue_details') then
        imgui.TextWrapped(state.data and state.data.path or primary)
        imgui.TextWrapped('Отмеченные строки пропускаются. Отметка — попытка отправки, результат сверяйте с сервером. /offban проверяется через /baninfo.')
        if imgui.Button('Как подготовить файл##queue_help') then integration.openHelp('queue') end
    end
    imgui.Separator()
    if editor then
        imgui.TextDisabled('По одной команде на строку')
        local available=imgui.GetContentRegionAvail()
        imgui.InputTextMultiline('##queue_text',editor,imgui.ImVec2(math.max(1,available.x-1),math.max(80,available.y-8)))
        return
    end
    local data=state.data
    if data and #data.items>0 then
        local pages=math.max(1,math.ceil(#data.items/8))
        state.page=math.max(1,math.min(pages,state.page))
        imgui.Text('Страница '..state.page..' / '..pages)
        if imgui.Button('Назад##queue_prev') then state.page=math.max(1,state.page-1); imgui.SetScrollY(0) end
        imgui.SameLine()
        if imgui.Button('Далее##queue_next') then state.page=math.min(pages,state.page+1); imgui.SetScrollY(0) end
        for i=(state.page-1)*8+1,math.min(state.page*8,#data.items) do
            local item=data.items[i]
            imgui.BeginChild('##queue_item_'..i,imgui.ImVec2(0,110),true)
            imgui.TextWrapped((item.command and '' or 'Ошибка · ')..'Строка '..item.line..': '..item.label)
            imgui.TextWrapped(item.result or (i<=state.done and 'Попытка начата · результат в файле' or 'Ожидает отправки'))
            imgui.EndChild()
            imgui.Spacing()
        end
    elseif data then imgui.TextWrapped('Нет новых команд. Добавьте строки в редакторе или перечитайте изменённый файл.')
    else
        imgui.Spacing();imgui.Text('Подготовьте список наказаний')
        imgui.TextWrapped('1. Откройте файл или создайте шаблон.\n2. В редакторе добавьте по одной команде на строку.\n3. Проверьте список и нажмите «Запустить очередь».')
        imgui.Spacing();imgui.TextDisabled('Примеры формата')
        imgui.Text('/offban Nick_Name 3 Причина')
        imgui.Text('/mute 57 10 Причина')
        imgui.TextWrapped('Подтверждение учитывает администратора, игрока и вид наказания. Если сервер не подтвердил выдачу, строка остаётся с отдельной отметкой — повторной отправки не будет.')
    end
end
integration.onDisconnect=function() stop('Соединение потеряно. Автоматическое продолжение отключено.') end
integration.queryPending=function(kind) return kind=='offst' and state.query==kind and state.running end
function integration.stop() stop('X-Tools остановлен.') end

    end
    sources["modules/radar_restore.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/radar_restore.lua
-- Original third-party credits, where present, are retained below.
local patch=integration.service('radar_restore.lua').new(_G,integration.message)
integration.update=function()patch:update()end
integration.stop=function()patch:stop()end
integration.prepareReload=integration.stop

