-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/tpm.lua
-- Original third-party credits, where present, are retained below.
-- TPm locations, embedded in the common teleportation page.
local g=require('imgui')
local locations=integration.service('tpm_locations.lua')
integration.teleport=function(index)
    local item=locations[index]
    if not item or not integration.access:require(1,integration.message) or sampGetGamestate()~=3 then return false end
    if not sampIsLocalPlayerSpawned() or not doesCharExist(PLAYER_PED)then return false end
    if isCharInAnyCar(PLAYER_PED)then integration.message('Выйдите из транспорта перед телепортацией в интерьер.');return false end
    setInteriorVisible(item.interior);setCharInterior(PLAYER_PED,item.interior)
    setCharCoordinates(PLAYER_PED,item.x,item.y,item.z);setCharHeading(PLAYER_PED,item.heading)
    restoreCameraJumpcut();sampSendChat('/setvw '..item.world)
    return true
end
integration.draw=function()
    local search=integration.service('teleport_search.lua')
    if search.query and search.query~='' or g.CollapsingHeader('Интерьеры и площадки для мероприятий')then
        if not search.query or search.query=='' then g.TextWrapped('Интерьеры: виртуальный мир 555. Открытые площадки: мир 0.') end
        for i,item in ipairs(locations)do
            if search.matches(item.name) then
                search.count=(search.count or 0)+1
                if g.Selectable(item.name..'##tpm_'..i)then integration.teleport(i)end
            end
        end
    end
    if search.query and search.query~='' and search.count==0 then g.TextDisabled('Ничего не найдено. Измените запрос.') end
end
sampRegisterChatCommand('tpm',function()integration.openTeleportation()end)

    end
    sources["modules/weapon_skills.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/weapon_skills.lua
-- Original third-party credits, where present, are retained below.
local g=require('imgui');local u8=require('encoding').UTF8
local events=require('lib.samp.events')
local parser=integration.service('weapon_skills.lua')
local pending,current,queue,closeDialog=nil,nil,nil,nil
local status='Нажмите «Проверить», чтобы получить свои навыки.'
local internal=false;local lastSend=0
local function myName()
    local ok,id=sampGetPlayerIdByCharHandle(PLAYER_PED)
    return ok and tostring(u8(sampGetPlayerNickname(id))) or nil
end
local function clear()
    pending=nil;current=nil;queue=nil;closeDialog=nil
    status='Сессия изменилась. Запросите навыки заново.'
end
local function request(target)
    if pending then status='Дождитесь ответа на предыдущий /askill.';return end
    target=tostring(target or ''):match('^%s*(.-)%s*$')
    if not target:match('^[%w_]+$') or #target>32 then status='Укажите ник или номер аккаунта без пробелов.';return end
    if not integration.commandAllowed('/askill '..target) then return end
    queue=nil;current=nil
    pending={managed=true,target=target,started=getGameTimer(),own=myName() and target:lower()==myName():lower(),revision=integration.access:revision()}
    status='Ожидается /askill для '..target
    internal=true;local sent=sampSendChat('/askill '..target);internal=false
    if sent==false then pending=nil;status='Запрос не отправлен.' end
end
function events.onSendCommand(command)
    if internal then return end
    local text=tostring(u8(command or ''))
    local target=text:match('^/[Aa][Ss][Kk][Ii][Ll][Ll]%s+(%S+)%s*$')
    if target then
        if pending then integration.message('Дождитесь ответа на предыдущий /askill.');return false end
        if not myName() or target:lower()~=myName():lower() then return end
        queue=nil;current=nil
        pending={target=target,started=getGameTimer(),own=myName() and target:lower()==myName():lower(),revision=integration.access:revision()}
        status='Ожидается /askill для '..target
    elseif text:lower():match('^/setskill%s') then queue=nil;current=nil;status='Навыки изменены вручную. Обновите данные.' end
end
function events.onShowDialog(id,style,title,b1,b2,text)
    if not pending or style~=0 or tostring(u8(title or '')):gsub('{%x+}','')~='Навыки владения оружием' then return end
    if pending.revision~=integration.access:revision() or getGameTimer()-pending.started>10000 then pending=nil;return end
    local values,err=parser.parse(u8(text or ''))
    if not values then status=err;pending=nil;return end
    current={target=pending.target,own=pending.own,values=values,revision=pending.revision,updated=getGameTimer(),edit={{},{}}}
    for group=1,2 do for skill=1,11 do current.edit[group][skill]=g.ImInt(values[group][skill]) end end
    local managed=pending.managed
    pending=nil;status='Получены навыки: '..current.target
    if managed then closeDialog=id;return false end
end
local function start(rows)
    if pending or queue or not current or not current.own or current.target:lower()~=(myName() or ''):lower()
        or current.revision~=integration.access:revision() then return end
    if getGameTimer()-current.updated>60000 then status='Данные старше минуты. Нажмите «Проверить».';return end
    if not integration.commandAllowed('/setskill 1 1 100') then return end
    if #rows==0 then status='Все навыки уже имеют нужные значения.';return end
    queue={rows=rows,index=1,revision=current.revision,nick=myName()};lastSend=getGameTimer()-800
    status='В очереди изменений: '..#rows
end
integration.update=function()
    if closeDialog~=nil then
        local id=closeDialog;closeDialog=nil
        sampSendDialogResponse(id,0,0,'')
        return
    end
    if pending and getGameTimer()-pending.started>10000 then pending=nil;status='Нет ответа /askill. Повторите запрос.' end
    if not queue then return end
    if queue.revision~=integration.access:revision() or queue.nick~=myName() or sampGetGamestate()~=3 then clear();return end
    if getGameTimer()-lastSend<800 or sampIsDialogActive() then return end
    local row=queue.rows[queue.index]
    if not row then local nick=queue.nick;queue=nil;request(nick);return end
    local cmd=string.format('/setskill %d %d %d',row.group,row.id,row.value)
    if not integration.commandAllowed(cmd) then queue=nil;return end
    internal=true;local sent=sampSendChat(cmd);internal=false
    if sent==false then queue=nil;status='Отправка остановлена.';return end
    status=string.format('Отправлено %d из %d. Итог будет проверен через /askill.',queue.index,#queue.rows)
    queue.index=queue.index+1;lastSend=getGameTimer()
end
integration.draw=function()
    if not integration.access:can(4) then g.TextWrapped('Скиллы на оружие доступны с 4 уровня администратора.');return end
    g.TextWrapped('Ваши навыки владения оружием. Выберите значение или заполните все недостающие.')
    if g.Button('Проверить##weapon_skills') then local nick=myName();if nick then request(nick) end end
    g.TextWrapped(status)
    if queue then
        if g.Button('Остановить выдачу##weapon_skills') then queue=nil;current=nil;status='Очередь остановлена. Уже отправленные изменения сохранены сервером; обновите данные.' end
    end
    if not current then return end
    local editable=current.own and not pending and not queue
    if not current.own then g.TextWrapped('Просмотр чужого аккаунта. Для изменения своих навыков нажмите «Проверить».') end
    if editable then
        if g.Button('Выдать все недостающие##weapon_skills') then start(parser.plan(current.values,100)) end
        g.SameLine()
        if g.Button('Забрать все скиллы##weapon_skills') then start(parser.plan(current.values,0)) end
    end
    for group=1,2 do
        g.Separator();g.Text(group==1 and 'Базовые — скорость, меткость, мобильность' or 'Продвинутые — урон')
        for skill,name in ipairs(parser.weapons) do
            g.Text(string.format('%s: %d%%',name,current.values[group][skill]))
            if editable then
                g.SameLine();g.PushItemWidth(140)
                local value=current.edit[group][skill]
                g.SliderInt('##skill_'..group..'_'..skill,value,0,100)
                g.PopItemWidth();g.SameLine()
                if g.Button('Установить##skill_'..group..'_'..skill) then
                    start({{group=group,id=skill,value=math.max(0,math.min(100,value.v))}})
                end
            end
        end
    end
end
integration.drawSettings=integration.draw
integration.onDisconnect=clear;integration.onAccessChanged=clear;integration.stop=clear
integration.skillState=function()return {current=current,pending=pending,queue=queue,status=status} end

    end
    sources["modules/zone_wall.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: modules/zone_wall.lua
-- Original third-party credits, where present, are retained below.
local g=require('imgui');local bit=require('bit')
local events=require('lib.samp.events');local u8=require('encoding').UTF8
local styles=integration.service('zone_wall_styles.lua')
local Crossing=integration.service('zone_crossings.lua')
local watched={};local previousPlayers={};local previousZones={}
local function resetCrossings(id)
    if id==nil then watched={};previousPlayers={};previousZones={} else previousPlayers[id]=nil;for _,row in pairs(watched)do row.tracker:reset(id)end end
end
local model=integration.serverZones()
local path=integration.storage:path('settings','zone-wall.ini')
local cfg=integration.storage:loadIni({main={enabled=false,height=12,range=200,step=6,color=0xB040E8E0,style=0,warn_enter=false,warn_exit=false}},path)
local c=cfg.main
local function clamp(v,lo,hi,default)v=tonumber(v);if not v or v~=v then return default end;return math.max(lo,math.min(hi,v))end
c.height=clamp(c.height,3,40,12);c.range=clamp(c.range,30,400,200);c.step=clamp(c.step,3,20,6)
c.color=tonumber(c.color)or 0xB040E8E0
c.style=math.floor(clamp(c.style,0,9,0))
local lines={};local nextBuild=0;local revision=-1
local function clear()lines={};nextBuild=0 end
local watchTime=0
local function reset()clear();resetCrossings();watchTime=0 end
local function save()integration.storage:saveIni(cfg,path)end
local function enabled()return c.enabled and integration.access:can(1) and sampGetGamestate()==3 end
local function watch()
    if not integration.access:can(1) or sampGetGamestate()~=3 or not(c.warn_enter or c.warn_exit)
        or (getActiveInterior and getActiveInterior()~=0)then resetCrossings();return end
    local now=getGameTimer();if now<watchTime then return end;watchTime=now+250
    local zones=model:activeZones()
    local seen={};local players={}
    local minX,minY,maxX,maxY
    for id=0,math.min(1004,sampGetMaxPlayerId(false))do
        if sampIsPlayerConnected(id)then
            local found,ped=sampGetCharHandleBySampPlayerId(id)
            if found and ped and ped~=0 and ped~=PLAYER_PED and doesCharExist(ped)then
                local nick=sampGetPlayerNickname(id);local x,y=getCharCoordinates(ped)
                if model.finite(x)and model.finite(y)then
                    seen[id]=true;players[#players+1]={id=id,nick=nick,x=x,y=y}
                    minX=math.min(minX or x,x);maxX=math.max(maxX or x,x)
                    minY=math.min(minY or y,y);maxY=math.max(maxY or y,y)
                end
            end
        end
    end
    -- Player streaming defines the monitored area, independently of wall range.
    -- Keep existing trackers while players leave a square to observe that exit.
    for zoneId,zone in pairs(zones)do
        if minX and maxX>=zone[1]-2 and minX<=zone[3]+2 and maxY>=zone[2]-2 and minY<=zone[4]+2 then
            local old=watched[zoneId]
            if not old or old.zone~=zone then
                local tracker=Crossing.new()
                -- Only a newly relevant existing zone may use previous positions.
                -- Replaced server definitions must start without synthetic events.
                if not old and previousZones[zoneId]==zone then for id,p in pairs(previousPlayers)do
                    tracker:sample(id,p.nick,p.x,p.y,zone,p.time)
                end end
                watched[zoneId]={zone=zone,tracker=tracker}
            end
        end
    end
    local function near(x,y,z)
        return x>=z[1]-2 and x<=z[3]+2 and y>=z[2]-2 and y<=z[4]+2
    end
    for zoneId,row in pairs(watched)do
        if zones[zoneId]~=row.zone then watched[zoneId]=nil
        else
            local tracker=row.tracker;local zone=row.zone
            for _,p in ipairs(players)do
                -- Initialize outside too: otherwise the first step inside would
                -- become a baseline and suppress a real entry.
                local change=tracker:sample(p.id,p.nick,p.x,p.y,zone,now)
                if change=='enter' and c.warn_enter or change=='exit' and c.warn_exit then
                    integration.message('Внимание! '..tostring(u8(p.nick))..'['..p.id..'] '..(change=='enter' and 'вошёл на территорию квадрата' or 'покинул территорию квадрата')..' #'..zoneId..'.')
                end
            end
            local relevant=false
            for id,state in pairs(tracker.players)do
                if not seen[id]then tracker:reset(id)
                elseif state.inside or state.pending~=nil then relevant=true end
            end
            if not relevant then
                for _,p in ipairs(players)do if near(p.x,p.y,zone)then relevant=true;break end end
            end
            if not relevant then watched[zoneId]=nil end
        end
    end
    previousZones={}
    for id,zone in pairs(zones)do previousZones[id]=zone end
    previousPlayers={}
    for _,p in ipairs(players)do p.time=now;previousPlayers[p.id]=p end
end
function events.onPlayerStreamOut(id)resetCrossings(id)end
function events.onPlayerStreamIn(id)resetCrossings(id)end
function events.onPlayerQuit(id)resetCrossings(id)end
local function build()
    if not enabled()then clear();return end
    if getActiveInterior and getActiveInterior()~=0 then clear();return end
    local now=getGameTimer();if now<nextBuild and revision==model.revision then return end
    nextBuild=now+500;revision=model.revision;lines={}
    local x,y,z=getActiveCameraCoordinates()
    if not model.finite(x) or not model.finite(y) or not model.finite(z)then return end
    local ground={}
    local function point(px,py)
        local key=string.format('%.3f:%.3f',px,py)
        if ground[key]then return ground[key]end
        local ok,pz=pcall(getGroundZFor3dCoord,px,py,1000)
        if not ok or not model.finite(pz)then return end
        local p={px,py,pz+0.15};ground[key]=p;return p
    end
    for _,s in ipairs(model:segments(x,y,c.range,c.step))do
        local a,b=point(s[1],s[2]),point(s[3],s[4])
        if a and b then
            styles.build(a,b,c.height,c.step,c.style+1,lines)
        end
    end
end
integration.update=function()watch();build()end
local function project(p)
    local visible,x,y,depth=convert3DCoordsToScreenEx(p[1],p[2],p[3],true,false)
    if visible and model.finite(x) and model.finite(y) and model.finite(depth) and depth>1 then return x,y end
end
integration.onD3DPresent=function()
    if not enabled() or isPauseMenuActive() then return end
    local color=c.color
    if c.style==9 then
        local alpha=math.floor(bit.band(bit.rshift(color,24),255)*(.65+.35*math.sin(getGameTimer()/350)))
        color=bit.bor(bit.band(color,0xFFFFFF),bit.lshift(alpha,24))
    end
    for _,line in ipairs(lines)do
        local x,y=project(line[1]);local bx,by=project(line[2])
        if x and bx then renderDrawLine(x,y,bx,by,line[3]or 1,color)end
    end
end
integration.drawSettings=function()
    local value=g.ImBool(c.enabled)
    if g.Checkbox('Стенка активного квадрата капта',value)then c.enabled=value.v;clear();integration.storage:saveIni(cfg,path)end
    if c.enabled then
    local style=g.ImInt(c.style)
    if g.Combo('Вид стенки',style,styles.names,#styles.names)then c.style=style.v;clear();save()end
    for _,row in ipairs({{'height','Высота стенки',3,40},{'range','Дальность стенки',30,400},{'step','Размер ячейки',3,20}})do
        local v=g.ImInt(c[row[1]])
        if g.SliderInt(row[2],v,row[3],row[4])then c[row[1]]=v.v;clear();integration.storage:saveIni(cfg,path)end
    end
    local ref=g.ImFloat4(g.ImColor(bit.band(bit.rshift(c.color,16),255),bit.band(bit.rshift(c.color,8),255),bit.band(c.color,255),bit.band(bit.rshift(c.color,24),255)):GetFloat4())
    if g.ColorEdit4('Цвет стенки',ref)then
        c.color=bit.bor(bit.lshift(math.floor(ref.v[4]*255),24),bit.lshift(math.floor(ref.v[1]*255),16),bit.lshift(math.floor(ref.v[2]*255),8),math.floor(ref.v[3]*255));integration.storage:saveIni(cfg,path)
    end
    end
    if g.CollapsingHeader('Контроль входа и выхода из квадрата капта')then
        for _,row in ipairs({{'warn_enter','Предупреждать о входе в квадрат'},{'warn_exit','Предупреждать о выходе из квадрата'}})do
            local flag=g.ImBool(c[row[1]])
            if g.Checkbox(row[2],flag)then c[row[1]]=flag.v;resetCrossings();save()end
        end
        g.TextWrapped('Контролируется только активная мигающая зона капта. Обычные и невидимые территории не учитываются.')
        g.TextWrapped('Отслеживаются другие игроки в прорисовке. Появление, исчезновение и выход из игры не считаются пересечением. Вход и выход работают независимо от видимости стенки.')
    end
    local n=0;for _ in pairs(model:activeZones())do n=n+1 end
    g.Text('Активных зон капта: '..n)
    if n==0 then g.TextWrapped('Сервер не передал активную мигающую зону капта. Стенка и контроль границ не работают. После перезагрузки скрипта может потребоваться переподключение.')end
    g.TextWrapped('Визуальная сетка вдоль границ зон, без столкновений. В интерьерах скрыта.')
end
integration.stop=reset;integration.onDisconnect=reset;integration.onAccessChanged=reset

    end
    sources["msg_targets.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: msg_targets.lua
-- Original third-party credits, where present, are retained below.
-- /msg scope: 0 = standard broadcast, 1 = important broadcast, 20..300 = radius.
local M={}
function M.parse(text)
    text=tostring(text or ''):match('^%s*(.-)%s*$')
    local n=text:match('^%d+$') and tonumber(text)
    if not n or not (n==0 or n==1 or n>=20 and n<=300) then
        return nil,'Введите 0 — всем, 1 — важное всем или радиус от 20 до 300.'
    end
    return tostring(n)
end
return M

    end
    sources["nametag_layout.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: nametag_layout.lua
-- Original third-party credits, where present, are retained below.
-- Place screen-space labels without overlapping previously placed labels.
local M={}
function M.place(used,x,y,width,height,screenHeight)
 local gap=6
 local function collision(top)
  for _,r in ipairs(used)do
   if x<r.x+r.width+gap and x+width+gap>r.x and top<r.y+r.height+gap and top+height+gap>r.y then return r end
  end
 end
 local top=y
 for i=1,#used+1 do local r=collision(top);if not r then break end;top=r.y-height-gap end
 if top<4 then
  top=math.max(4,y)
  for i=1,#used+1 do local r=collision(top);if not r then break end;top=r.y+r.height+gap end
 end
 -- Hide only when there is no room; never force a label over another one.
 if top<4 or top+height>screenHeight-4 or collision(top)then return nil end
 used[#used+1]={x=x,y=top,width=width,height=height}
 return top
end
return M

    end
    sources["native_fonts.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: native_fonts.lua
-- Original third-party credits, where present, are retained below.
local Fonts={}
Fonts.__index=Fonts
local faces={'Segoe UI','Arial','Tahoma'}
function Fonts.new(api,preferences) return setmetatable({api=api,preferences=preferences,entries={}},Fonts) end
function Fonts:create(requested,size,flags,preserveFace)
    local face=preserveFace and requested or faces[self.preferences.data.main.font] or faces[1]
