-- X-TOOLS | Project and integration: Casual_Alvarez | Module: numeric_input.lua
-- Original third-party credits, where present, are retained below.
-- Keep active edit buffers alive, but publish each edit before the page can close.
local M={}
function M.install(g)
    local state={}
    for _,kind in ipairs({'InputInt','InputFloat'})do
        local original=g[kind]
        g[kind]=function(label,value,...)
            local step,fast,precision,floatFlags=...
            local id=kind..':'..tostring(g.GetID(label)or label)
            local entry=state[id]
            if not entry then
                entry={buffer=kind=='InputInt'and g.ImInt(value.v)or g.ImFloat(value.v)};state[id]=entry
            end
            local frame=g.GetFrameCount and g.GetFrameCount()
            -- A field absent for a frame no longer owns an editing session.
            -- Refresh before drawing, so reopening cannot flash its old draft.
            local reopened=frame and entry.frame and frame>entry.frame+1
            -- Compact fields use a persistent text editor. MoonImGui's scalar
            -- wrapper must not recreate the native edit buffer while typing.
            if step==0 and g.InputText and g.ImBuffer then
                local function format(number)
                    if kind=='InputInt'then return tostring(math.floor(number))end
                    return string.format('%.'..math.max(0,math.min(9,tonumber(precision)or 3))..'f',number)
                end
                if not entry.text then entry.text=g.ImBuffer(format(value.v),64)end
                if not entry.active or reopened then entry.text.v=format(value.v)end
                entry.frame=frame
                local flags=(kind=='InputInt'and precision or floatFlags)or 0
                flags=require('bit').bor(flags,(g.InputTextFlags or {}).CharsDecimal or 0)
                local edited=g.InputText(label,entry.text,flags)
                entry.active=g.IsItemActive()==true
                if edited then
                    local number=tonumber(entry.text.v)
                    if number and number==number and math.abs(number)<math.huge then
                        if kind=='InputInt'then number=number<0 and math.ceil(number)or math.floor(number)end
                        if kind~='InputInt'or(number>=-2147483648 and number<=2147483647)then
                            value.v=number
                            return true
                        end
                    end
                end
                return false
            end
            if not entry.active or reopened then entry.buffer.v=value.v end
            entry.frame=frame
            local changed=original(label,entry.buffer,...)
            local active=g.IsItemActive()==true
            entry.active=active
            entry.model=value.v
            if changed then
                value.v=entry.buffer.v;entry.model=value.v;return true
            end
            return false
        end
    end
end
return M

    end
