-- X-TOOLS | Project and integration: Casual_Alvarez | Module: observation_native.lua
-- Original third-party credits, where present, are retained below.
-- Read-only recovery of actual server rows after Lua reload (SA-MP 0.3.7-R1).
-- Packed SA-MP 0.3.7-R1 layouts: CNetGame, CMenuPool, CMenu.
local M={}
local function u32(s)
    if type(s)~='string' or #s~=4 then return end
    local a,b,c,d=s:byte(1,4);return a+b*256+c*65536+d*16777216
end
function M.read(read,base,id)
    if not base or base==0 or id~=nil and (id<0 or id>127 or id%1~=0) then return end
    if read(base,2)~='MZ' then return end
    local pe=u32(read(base+0x3c,4))
    if not pe or pe<0x40 or pe>0x1000 or read(base+pe,4)~='PE\0\0'
        or u32(read(base+pe+0x28,4))~=0x31DF13 then return end
    local function ptr(address)
        local value=u32(read(address,4));if value and value>=0x10000 and value<0x80000000 then return value end
    end
    local net=ptr(base+0x21A0F8);if not net then return end
    local pools=ptr(net+0x3CD);if not pools then return end
    local pool=ptr(pools+20);if not pool then return end
    local current=id==nil
    if current then
        local value=read(pool+0x400,1)
        id=value and value:byte(1)
        if not id or id>127 then return end
    end
    if u32(read(pool+512+id*4,4))~=1 then return end
    local menu=ptr(pool+id*4);if not menu then return end
    local bytes=read(menu,0x3B8);if not bytes or #bytes~=0x3B8 then return end
    local columns,count=bytes:byte(882),bytes:byte(947)
    if (columns~=1 and columns~=2) or count<1 or count>12 then return end
    local function str(offset) return bytes:sub(offset+1,offset+32):match('^(.-)%z') end
    local title=str(1);if not title then return end
    local items={}
    for row=0,count-1 do
        local label=str(33+row*64);if not label then return end
        items[#items+1]=label
    end
    -- If the native count exposes only a prefix after Lua reload, check
    -- whether all nine observation labels are still stored in the object.
    -- Recover only a complete, recognized layout from actual stored strings.
    -- Never manufacture labels or trust arbitrary unused menu slots.
    if count<9 and columns==1 then
        local expected={'exit','mute','slap','weap','skick','info','stat','update','exit'}
        local recovered={}
        for row=0,8 do
            local label=str(33+row*64)
            local key=label and label:gsub('{%x+}',''):gsub('~.-~',''):gsub('[%s_%-]',''):lower()
            if key~=expected[row+1] then recovered=nil;break end
            recovered[#recovered+1]=label
        end
        if recovered then items=recovered end
    end
    local result={id,title,548,157,columns==2,{{text=items}},{},true,n=8}
    if current then
        -- Last fields of packed CLocalPlayer: spectating (10 bytes), damage (12).
        local players=ptr(pools+24)
        local player=players and ptr(players+0x22)
        local kind=player and read(player+0x30F,1)
        local target=player and u32(read(player+0x310,4))
        kind=kind and kind:byte(1)
        if target and ((kind==1 and target<=1003) or (kind==2 and target<=1999)) then
            result.observedType,result.observedId=kind,target
        end
    end
    return result
end
function M.new(api)
    local ok,reader=pcall(function()
        local ffi=api.require('ffi')
        ffi.cdef[[int __stdcall ReadProcessMemory(void*,const void*,void*,size_t,size_t*);
            void* __stdcall GetCurrentProcess(void);]]
        local process=ffi.C.GetCurrentProcess()
        return function(address,size)
            local buffer=ffi.new('unsigned char[?]',size);local count=ffi.new('size_t[1]')
            if ffi.C.ReadProcessMemory(process,ffi.cast('const void*',address),buffer,size,count)==0
                or tonumber(count[0])~=size then return end
            return ffi.string(buffer,size)
        end
    end)
    if not ok then return function()end end
    return function(id)
        local success,result=pcall(function()
            if type(api.getModuleHandle)~='function' then return end
            return M.read(reader,api.getModuleHandle('samp.dll'),tonumber(id))
        end)
        if success then return result end
    end
end
return M

    end
