-- X-TOOLS | Project and integration: Casual_Alvarez | Module: offban_guard.lua
-- Original third-party credits, where present, are retained below.
-- Every ban is checked first. Existing bans require a new, explicit request.
local Guard={}
Guard.__index=Guard
function Guard.new(rt) return setmetatable({rt=rt,queue={},results={},requests={},acknowledged={}},Guard) end
function Guard:enqueue(owner,api,command)
    if self.releasing then return false end
    local verb=command:match('^(/%S+)')
    if not verb or not ({['/offban']=true,['/ban']=true,['/sban']=true})[verb:lower()] then return false end
    verb=verb:lower()
    local target,days,reason=command:match('^/%S+%s+(%S+)%s+(%d+)%s+(.+)$')
    if not target or #target>32 or tonumber(days)<1 or tonumber(days)>2147483647 or command:find('[%z\1-\31]') then
        self.results[command]='Неверный формат бана: укажите ник, положительный срок и причину.'
        self.rt:message(self.results[command]);return true
    end
    local id
    -- /sban accepts an account nickname, including disconnected players.
    -- Only numeric /sban targets and /ban targets refer to live player IDs.
    if verb=='/ban' or (verb=='/sban' and target:match('^%d+$')) then
        id=tonumber(target)
        if not id or not self.rt.api.sampIsPlayerConnected(id) then
            self.rt:message('Бан не отправлен: игрок не в сети.');return true
        end
        target=tostring(self.rt.api.require('encoding').UTF8(self.rt.api.sampGetPlayerNickname(id)))
    end
    local requester=self.requester
    local key=target:lower()..':'..(requester or 'manual'):lower()
    local now=self.rt.api.os.clock()
    for k,ack in pairs(self.acknowledged) do if now-ack.time>120 then self.acknowledged[k]=nil end end
    local acknowledgment=self.acknowledged[key]
    self.acknowledged[key]=nil
    self.results[command]=nil
    self.queue[#self.queue+1]={owner=owner,api=api,target=target,id=id,verb=verb,days=tonumber(days),reason=reason,
        requester=requester,key=key,acknowledgment=acknowledgment and now-acknowledgment.time<=120 and acknowledgment or nil,
        revision=self.rt.access:revision(),original=command}
    return true
end
function Guard:reset() self.queue={};self.pending=nil;self.releasing=false;self.requests={};self.acknowledged={};self.reply=nil end
function Guard:track(command)
    local target=tostring(command or ''):match('^/[Bb][Aa][Nn][Ii][Nn][Ff][Oo]%s+(%S+)')
    if not target then return end
    local row={target=target:lower(),pending=self.issuing,ambiguous=#self.requests>0}
    for _,request in ipairs(self.requests) do request.ambiguous=true end
    self.requests[#self.requests+1]=row
end
function Guard:cancel(owner)
    for key,ack in pairs(self.acknowledged) do if ack.owner==owner then self.acknowledged[key]=nil end end
    if self.reply and self.reply.owner==owner then self.reply=nil end
    for i=#self.queue,1,-1 do if self.queue[i].owner==owner then table.remove(self.queue,i) end end
    if self.pending and self.pending.owner==owner then self.pending=nil;self.cooldown=self.rt.api.os.clock()+11 end
end
function Guard:observe(name,...)
    local p=self.pending
    if not p and #self.requests==0 then return end
    local args={...};local u8=self.rt.api.require('encoding').UTF8
    if name=='onShowDialog' then
        local title=tostring(u8(args[3] or '')):gsub('{%x+}',''):match('^%s*(.-)%s*$')
        if args[2]~=0 then return end
        for i,request in ipairs(self.requests) do
            if request.target==title:lower() then table.remove(self.requests,i);break end
        end
        if not p or title:lower()~=p.target:lower() then return end
        local text=tostring(u8(args[6] or '')):gsub('{%x+}','')
        local days=text:match('дней до конца бана:%s*(%d+)') or text:match('Дней до конца бана:%s*(%d+)')
        if days then
            p.remaining=tonumber(days);p.banned=true;p.dialogId=args[1]
            p.admin=text:match('Ник администратора:%s*([^\r\n]+)') or text:match('Администратор:%s*([^\r\n]+)')
            if p.admin then p.admin=p.admin:match('^%s*(.-)%s*$') end
            return false
        end
        if text:find('не забанен',1,true) or text:find('не находится в бан',1,true) then p.remaining=0;p.dialogId=args[1];return false end
    elseif name=='onServerMessage' then
        local ok,decoded=pcall(u8,args[2] or '')
        if not ok then return end
        local text=tostring(decoded):gsub('{%x+}',''):match('^%s*(.-)%s*$')
        if text=='Игрок с таким ником (или номером аккаунта) не найден в банлисте'
            or text=='Игрок с таким ником (или номером аккаунта) не найден в банлисте.' then
            local request=table.remove(self.requests,1)
            if p and p.remaining==nil then
                if request and request.pending==p and not request.ambiguous then
                    p.remaining=0
                else
                    p.uncorrelatedReply=true
                end
            end
        end
    end
end
function Guard:query(p)
    p.started=self.rt.api.os.clock();p.remaining=nil;p.dialogId=nil;p.banned=false;p.uncorrelatedReply=nil
    self.issuing=p
    local ok=self.rt:send(p.owner,'sampSendChat','/baninfo '..p.target)
    self.issuing=nil
    if ok==false then self:fail(p,'Проверка /baninfo недоступна; бан не отправлен.') end
end
function Guard:fail(p,text)
    self.results[p.original]=text;self.rt:message(text);self.pending=nil
end
function Guard:release(p)
    local rt=self.rt
    if p.id and (not rt.api.sampIsPlayerConnected(p.id) or
        tostring(rt.api.require('encoding').UTF8(rt.api.sampGetPlayerNickname(p.id))):lower()~=p.target:lower()) then
        self:fail(p,'Игрок вышел или ID сменил владельца; бан не отправлен.');return
    end
    local command=string.format('%s %s %d %s',p.verb,p.id or p.target,p.total or p.days,p.reason)
    self.pending=nil;self.releasing=true
    local ok,result=pcall(rt.send,rt,p.owner,p.api,rt.api.require('encoding').UTF8:decode(command))
    self.releasing=false
    if not ok or result==false then self:fail(p,'Не удалось отправить бан: '..tostring(result)) end
end
function Guard:update()
    local rt=self.rt;local p=self.pending;local now=rt.api.os.clock()
    if p then
        if p.revision~=rt.access:revision() or not rt.access:can(1) then self:reset();return end
        if p.verifyAt then
            if now>=p.verifyAt then p.verifyAt=nil;self:query(p) end
            return
        end
        if p.remaining~=nil then
            if p.dialogId and rt.api.sampSendDialogResponse then rt.api.sampSendDialogResponse(p.dialogId,0,0,'') end
            if p.unbanning then
                if p.banned then self:fail(p,'Снятие бана не подтверждено; новый бан не отправлен.')
                else self:release(p) end
                return
            end
            if not p.banned then self:release(p);return end
            local admin=p.admin and p.admin~='' and p.admin or 'не указан'
            local ack=p.acknowledgment
            -- A changed ban must be reviewed again, even on the second request.
            if not ack or ack.admin~=admin or ack.remaining~=p.remaining then
                self.acknowledged[p.key]={owner=p.owner,time=now,admin=admin,remaining=p.remaining}
                local info=string.format('%s уже в бане. Забанил: %s. Осталось дней: %d.',p.target,admin,p.remaining)
                self.results[p.original]=info
                rt:message(info)
                rt:message('Если всё верно — повторите запрос на этот ник в течение 2 минут.')
                if p.requester and p.requester~='' then
                    rt:send(p.owner,'sampSendChat',rt.api.require('encoding').UTF8:decode('/a '..p.requester..', '..info))
                    self.reply={owner=p.owner,revision=p.revision,at=now+1,
                        text='/a '..p.requester..', если всё верно — отправь запрос на этого игрока ещё раз.'}
                end
                self.pending=nil;return
            end
            p.total=p.remaining+p.days
            if p.total>2147483647 then self:fail(p,'Слишком большой суммарный срок; бан не изменён.');return end
            if p.remaining>29 then
                if not rt:commandAllowed('/unban '..p.target) or rt:blockProtectedPunishment(p.original) then
                    self:fail(p,'Недостаточно прав или защищённая цель; бан не изменён.');return
                end
                -- Check target identity BEFORE removing the existing ban.
                if p.id and (not rt.api.sampIsPlayerConnected(p.id) or
                    tostring(rt.api.require('encoding').UTF8(rt.api.sampGetPlayerNickname(p.id))):lower()~=p.target:lower()) then
                    self:fail(p,'ID изменился; действующий бан не изменён.');return
                end
                local sent=rt:send(p.owner,'sampSendChat','/unban '..p.target)
                if sent==false then self:fail(p,'Не удалось отправить /unban; бан не изменён.');return end
                p.unbanning=true;p.verifyAt=now+1;p.remaining=nil
                rt:message(string.format('Повторный запрос: снимаю бан %s и проверяю снятие. Новый срок: %d + %d = %d дней.',p.target,ack.remaining,p.days,p.total))
            else self:release(p) end
        elseif now-p.started>10 then
            self:fail(p,p.unbanning and 'Не удалось проверить снятие бана. Новый бан НЕ отправлен; проверьте игрока вручную.' or
                (p.uncorrelatedReply and 'Ответ /baninfo без ника нельзя связать с игроком; наказание не отправлено.' or 'Нет ответа /baninfo; наказание не отправлено. Повторите запрос.'))
            self.cooldown=now+11
        end
        return
    end
    if self.reply then
        if self.reply.revision~=rt.access:revision() then self.reply=nil
        elseif now>=self.reply.at then
            rt:send(self.reply.owner,'sampSendChat',rt.api.require('encoding').UTF8:decode(self.reply.text));self.reply=nil
        end
        if self.reply then return end
    end
    if #self.queue==0 or rt.api.sampIsDialogActive() or (self.cooldown and now<self.cooldown) then return end
    p=table.remove(self.queue,1)
    if p.revision~=rt.access:revision() or not rt.access:can(1) then return end
    self.pending=p;self:query(p)
end
return Guard

    end
    sources["online_stats.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: online_stats.lua
-- Original third-party credits, where present, are retained below.
-- Calendar ledger: server snapshots replace a day, never accumulate twice.
local Stats={}
local months={'января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'}
function Stats.date(year,month,day)
    year,month,day=tonumber(year),tonumber(month),tonumber(day)
    if not year or not month or not day or year<2000 or year>2100 or month<1 or month>12 or day<1 or day>31 then return end
    local stamp=os.time{year=year,month=month,day=day,hour=12}
    local key=string.format('%04d-%02d-%02d',year,month,day)
    if stamp and os.date('%Y-%m-%d',stamp)==key then return key,stamp end
end
function Stats.timestamp(key)
    if type(key)~='string' then return end
    local year,month,day=key:match('^(%d%d%d%d)%-(%d%d)%-(%d%d)$')
    return select(2,Stats.date(year,month,day))
end
function Stats.shift(key,days)
    local stamp=Stats.timestamp(key)
    if not stamp then return end
    local date=os.date('*t',stamp);date.day=date.day+days
    return os.date('%Y-%m-%d',os.time(date))
end
function Stats.week(key)
    local stamp=Stats.timestamp(key)
    return stamp and Stats.shift(key,-((os.date('*t',stamp).wday+5)%7))
end
function Stats.parse(text)
    text=tostring(text or ''):gsub('{%x+}','')
    if not text:find('Вы позвонили в службу точного времени',1,true) then return end
    local day,name,year=text:match('(%d+)%s+([^%s%d]+)%s+(%d+)%s+г%.')
    local month
    for index,label in ipairs(months) do if name==label then month=index end end
    local date=Stats.date(year,month,day)
    if not date then return nil,'Не распознана дата сервера; статистика не изменена.' end
    local function duration(label)
        local hours,minutes=text:match(label..':%s*(%d+)%s*ч%s*(%d+)%s*мин')
        hours,minutes=tonumber(hours),tonumber(minutes)
        if hours and minutes and minutes<60 and hours*60+minutes<=1440 then return hours*60+minutes end
    end
    local total,afk=duration('Время в игре сегодня'),duration('AFK за сегодня')
    if not total or not afk or afk>total then return nil,'Не распознаны время и AFK за сегодня; статистика не изменена.' end
    local previous,previousAfk=duration('Время в игре вчера'),duration('AFK за вчера')
    return {date=date,today=total-afk,total=total,afk=afk,
        yesterday=previous and previousAfk and previousAfk<=previous and previous-previousAfk or nil}
end
function Stats.summary(days,date)
    local result={daily=tonumber(days[date]) or 0,weekly=0,monthly=0,dayBest=0,weekBest=0,monthBest=0,count=0,total=0}
    local weeks,months={},{}
    for key,value in pairs(days) do
        value=tonumber(value)
        if Stats.timestamp(key) and value and value>=0 and value<=1440 then
            local week,month=Stats.week(key),key:sub(1,7)
            weeks[week]=(weeks[week] or 0)+value;months[month]=(months[month] or 0)+value
            result.count=result.count+1;result.total=result.total+value
            if value>result.dayBest then result.dayBest,result.dayBestDate=value,key end
        end
    end
    result.weekly=weeks[Stats.week(date)] or 0;result.monthly=months[date:sub(1,7)] or 0
    local weekCount=0
    for key,value in pairs(weeks) do
        weekCount=weekCount+1
        if value>result.weekBest then result.weekBest,result.weekBestDate=value,key end
    end
    for key,value in pairs(months) do if value>result.monthBest then result.monthBest,result.monthBestDate=value,key end end
    result.average=result.total/math.max(1,result.count)
    result.weekAverage=result.total/math.max(1,weekCount)
    return result
end
return Stats

    end
