-- X-TOOLS | Project and integration: Casual_Alvarez | Module: organization_find.lua
-- Original third-party credits, where present, are retained below.
local M={}
local function clean(s)return (s or ''):gsub('{%x%x%x%x%x%x}','')end
function M.parse(id,style,title,body,selfId)
    title=clean(title)
    if id~=63 or style~=5 then return end
    local total,online=title:match('^В организации%s+(%d+)%s+чел%.%s*%(онлайн%s+(%d+)%)%s*$')
    if not online then return end
    local paused,own=0,false
    local players={}
    for line in clean(body):gmatch('[^\r\n]+')do
        local player=line:match('^%s*%d+%.%s+[^\t]+%[(%d+)%]')
        if player then
            players[player]=line:find('На паузе',1,true)~=nil
            local isSelf=tonumber(player)==tonumber(selfId)
            own=own or isSelf
            if not isSelf and line:find('На паузе',1,true) then paused=paused+1 end
        end
    end
    return {online=math.max(0,tonumber(online)-(own and 1 or 0)),paused=paused,total=tonumber(total),players=players,rawOnline=tonumber(online)}
end
function M.collect(state,page,button,selfId)
    state=state or {players={},pages={}}
    for id,paused in pairs(page.players)do state.players[id]=paused end
    local nextPage=clean(button):match('^%s*Стр%.%s*(%d+)%s*>>%s*$')
    if nextPage then
        if state.pages[nextPage] then return state,nil,nil end
        state.pages[nextPage]=true
        return state,nil,tonumber(nextPage)
    end
    local paused=0
    for id,value in pairs(state.players)do
        if tonumber(id)~=tonumber(selfId) and value then paused=paused+1 end
    end
    local own=selfId~=nil and state.players[tostring(selfId)]~=nil
    return state,{online=math.max(0,page.rawOnline-(own and 1 or 0)),paused=paused,total=page.total}
end
return M

    end
