-- X-TOOLS | Project and integration: Casual_Alvarez | Module: preferences.lua
-- Original third-party credits, where present, are retained below.
local Preferences={}
Preferences.__index=Preferences
Preferences.colors={{'Фиолетовый',0xC080FF,0x322B4C},{'Голубой',0x40CEFF,0x203B50},
    {'Мятный',0x35F4B3,0x203E37},{'Розовый',0xFF70BD,0x4A2B3B},{'Янтарный',0xFFD04A,0x493D29},
    {'Красный',0xFF4F70,0x4B2530},
    {'Аврора · ледяной голубой',0x59DFFF,0x203B45},
    {'Янтарь · тёплое золото',0xFFAB51,0x493322},
    {'Нефрит · изумрудный',0x62E9AB,0x234236},
    {'Рубин · красный кристалл',0xFF6086,0x482633},
    {'Космос · лавандовый',0xAA91FF,0x352C4D}}

local function finite(value,fallback)
    local number=tonumber(value)
    if not number or number~=number or number==math.huge or number==-math.huge then return fallback end
    return number
end

local function boolean(value,fallback)
    if value==true or value==1 or value=='true' then return true end
    if value==false or value==0 or value=='false' then return false end
    return fallback
end

function Preferences:validate()
    self.data=type(self.data)=='table' and self.data or {}
    self.data.main=type(self.data.main)=='table' and self.data.main or {}
    local p=self.data.main
    p.color=math.max(1,math.min(#Preferences.colors,math.floor(finite(p.color,1))))
    p.font=math.max(1,math.min(11,math.floor(finite(p.font,1))))
    for _,key in ipairs({'logoStyle','backgroundStyle'}) do
        p[key]=math.max(0,math.min(5,math.floor(finite(p[key],0))))
    end
    -- Migrate mixed legacy choices to the theme of the selected background.
    p.themeStyle=math.max(0,math.min(5,math.floor(finite(p.themeStyle,p.backgroundStyle))))
    p.logoStyle=p.themeStyle
    p.backgroundStyle=p.themeStyle
    p.color=p.themeStyle>0 and 6+p.themeStyle or 1
    p.statusPanelStyle=math.max(0,math.min(5,math.floor(finite(p.statusPanelStyle,0))))
    p.fishEyeAngle=math.max(30,math.min(150,math.floor(finite(p.fishEyeAngle,101))))
    p.scale=1 -- Migrate old interface zoom to the single supported size.
    p.timezoneEnabled=boolean(p.timezoneEnabled,false)
    p.timezoneMskOffset=math.max(-15,math.min(11,math.floor(finite(p.timezoneMskOffset,0))))
    p.compactSidebar=boolean(p.compactSidebar,false)
    p.wallpaper=boolean(p.wallpaper,true)
    p.motion=boolean(p.motion,true)
    p.windowManual=boolean(p.windowManual,false)
    p.windowMoved=boolean(p.windowMoved,false)
    p.windowPresetVersion=math.max(0,math.floor(finite(p.windowPresetVersion,0)))
    if p.windowPresetVersion<1 then
        -- Apply the shared home layout once, including existing manual sizes.
        p.windowWidth,p.windowHeight,p.windowX,p.windowY=0,0,0,0
        p.windowManual,p.windowMoved=false,false
        p.windowPresetVersion=1
        self.windowPresetPending=true
    end
    for _,name in ipairs({'windowWidth','windowHeight','windowX','windowY'}) do
        -- Zero means initial placement/size; the workspace clamps to the actual screen.
        p[name]=math.max(0,math.min(32768,math.floor(finite(p[name],0))))
    end
    for _,name in ipairs({'streamer','ghetto','families','roadFollowup','legoReplace','antiBH','blockF1F4','matrixJump','backFlip','cjMovement','fishEye','spectateChatN','invisibleOnStart'}) do p[name]=boolean(p[name],false) end
    for _,name in ipairs({'killidsKiller','killidsVictim'}) do p[name]=boolean(p[name],true) end
    if p.medkitMode~='ghetto' and p.medkitMode~='families' then p.medkitMode='none' end
    return p
end

function Preferences.new(storage)
    local path=storage:path('settings','interface.ini')
    local defaults={main={color=1,font=1,scale=1,compactSidebar=false,wallpaper=true,motion=true,
        windowWidth=0,windowHeight=0,windowX=0,windowY=0,windowManual=false,windowMoved=false,windowPresetVersion=0,
        streamer=false,ghetto=false,families=false,medkitMode='none',killidsKiller=true,killidsVictim=true}}
    local ok,data=pcall(storage.loadIni,storage,defaults,path)
    local recovery
    if not ok then
        local backupOk,backup=pcall(function()
            assert(storage:exists(path..'.bak'),'No backup')
            return storage:loadIni(defaults,path..'.bak')
        end)
        data=backupOk and backup or defaults
        recovery=backupOk and 'Настройки интерфейса восстановлены из резервной копии.'
            or 'Настройки интерфейса повреждены. Используется стандартное оформление.'
    end
    local self=setmetatable({storage=storage,path=path,data=data},Preferences)
    self:validate()
    if recovery then
        self.recoveryPending=true;self.recoveryNotice=recovery
        if not self:save() then self.recoveryNotice=recovery..' Сохранение недоступно; исходные файлы не перезаписаны.' end
    end
    return self
end
function Preferences:save()
    self:validate()
    if self.recoveryPending then
        local ok,saved=pcall(function()
            -- Preserve both original inputs before saveIni rotates .bak.
            for _,source in ipairs({self.path,self.path..'.bak'})do
                if self.storage:exists(source)then
                    local bytes=assert(self.storage:read(source),'Cannot preserve damaged settings')
                    local archive
                    for i=1,1000 do
                        local candidate=source..'.damaged.'..i
                        if not self.storage:exists(candidate)then archive=candidate;break end
                    end
                    assert(archive,'Too many recovery archives')
                    assert(self.storage:write(archive,bytes),'Cannot archive settings')
                end
            end
            return self.storage:saveIni(self.data,self.path)
        end)
        if not ok or not saved then return false end
        self.recoveryPending=false
        return true
    end
    return self.storage:saveIni(self.data,self.path)
end
function Preferences:mask(text)
    if not self.data.main.streamer or type(text)~='string' then return text end
    -- Presentation only: raw protocol messages and data stay available to parsers.
    return (text:gsub('%d+%.%d+%.%d+%.%d+', '[IP скрыт]'))
end
return Preferences

    end
    sources["punishment_assistant.lua"] = function()
-- X-TOOLS | Casual_Alvarez | Pure validation for the punishment assistant.
local M={}
function M.new(api,catalog)
 local self={}
 local function clean(s)return tostring(s or ''):match('^%s*(.-)%s*$')end
 function self:target(raw)
  raw=clean(raw)
  local id=raw:match('^%d+$')and tonumber(raw)
  if id then
   if id<0 or id>1003 or not api.connected(id)then return nil,'Игрок с таким ID не в сети.'end
   return {name=api.nickname(id),id=id,byId=true}
  end
  if #raw<3 or #raw>24 or not raw:match('^[%w_%.]+$')then return nil,'Укажите ID или полный ник игрока.'end
  for n=0,math.min(1003,api.maxId())do if api.connected(n)and api.nickname(n):lower()==raw:lower()then return {name=api.nickname(n),id=n,byId=false}end end
  return {name=raw,byId=false}
 end
 function self:plan(target,mode,ruleId,optionIndex,amount,reason,unknownConfirmed)
  if not target then return nil,'Сначала укажите игрока.'end
  local current,err=self:target(target.byId and tostring(target.id)or target.name)
  if not current then return nil,err end
  if current.name:lower()~=target.name:lower()then return nil,'ID уже принадлежит другому игроку. Откройте помощник заново.'end
  if current.id==api.localId()or current.name:lower()==api.localName():lower()then return nil,'Нельзя выдать наказание самому себе.'end
  if mode~='player'and mode~='family'then return nil,'Выберите игрока или члена семьи.'end
  local rule=catalog.find(ruleId);local option=rule and rule.options[optionIndex or 0]
  if not option then return nil,'Выберите нарушение и вид наказания.'end
  local kind=option.kind
  if (kind=='warn'or kind=='ban')and api.protected(current.name)then return nil,'Игрок есть в защищённом списке администратора или лидера.'end
  local time
  if kind=='jail'or kind=='mute'then
   time=tonumber(amount)
   if not time or time~=time or time%1~=0 or time<1 or time>100000 then return nil,'Укажите положительный целый срок в минутах.'end
   if option.min and time<option.min or option.max and time>option.max then return nil,'Срок выходит за диапазон этого пункта: '..catalog.term(option)end
   if (option.unknown or option.additive)and not unknownConfirmed then return nil,'Подтвердите отдельно проверенный срок.'end
   if option.additive and time<30 then return nil,'Итоговый мут должен включать дополнительные 30 минут.'end
  elseif kind=='ban'then
   time=option.min
   if not time then return nil,'Срок бана в этом пункте не указан. Выберите конкретный пункт регламента.'end
  end
  if not current.id and not ({jail=true,mute=true,warn=true,ban=true})[kind]then return nil,'Этот вид наказания доступен только онлайн.'end
  local command='/'..(current.id and kind or 'off'..kind)
  local requestOnly=not api.allowed(command)or(mode=='family'and not api.allowed('/msg'))
  if mode=='family'and not api.familyEnabled()then return nil,'Включите семейные функции перед выдачей.'end
  reason=clean(reason)
  if reason==''or reason:find('[%z\1-\31]')or reason:find('[{}]')then return nil,'Укажите причину без переносов и цветовых тегов.'end
  local subject=tostring(current.id or current.name)
  local args=subject..(time and ' '..time or '')..(kind~='spawn'and ' '..reason or '')
  local text=command..' '..args
  local outgoing=requestOnly and '/a '..text or text
  if api.bytes(outgoing)>144 then return nil,'Команда длиннее 144 байт. Сократите причину.'end
  return {target=current,kind=kind,amount=time,reason=reason,mode=mode,command=text,outgoing=outgoing,requestOnly=requestOnly,rule=rule.id,
   key=table.concat({requestOnly and 'request'or 'direct',mode,current.name,current.id or 'offline',kind,time or '',reason,rule.id},'|')}
 end
 return self
end
return M

    end
    sources["punishment_catalog.lua"] = function()
-- X-TOOLS | Casual_Alvarez | User-supplied regulations, experimental assistant.
-- Keep context-specific rules separate. A missing term is never invented.
local C={categories={},rules={}}
local category
local function section(id,name)category=id;C.categories[#C.categories+1]={id=id,name=name}end
local function rule(id,title,spec,note,level)
 local r={id=id,category=category,title=title,note=note or '',level=level or 1,options={}}
 for token in spec:gmatch('%S+')do
  local kind,term=token:match('^(%a+):?(.*)$')
  local lo,hi=term:match('^(%d+)%-(%d+)$')
  local minimum=term:match('^(%d+)%+$')
  local exact=term:match('^%d+$')and tonumber(term)
  r.options[#r.options+1]={kind=kind,min=tonumber(lo)or tonumber(minimum)or exact,max=tonumber(hi)or exact,unknown=term==''and(kind=='jail'or kind=='mute'or kind=='ban'),atLeast=minimum~=nil,additive=term=='+30'}
 end
 C.rules[#C.rules+1]=r
end
