C.labels={jail='КПЗ',mute='Мут',kick='Кик',skick='Тихий кик',warn='Предупреждение',ban='Бан',spawn='Респавн'}
function C.category(id)for _,c in ipairs(C.categories)do if c.id==id then return c.name end end;return id end
function C.find(id)for _,r in ipairs(C.rules)do if r.id==id then return r end end end
function C.term(o)
 if o.additive then return '+30 мин. к текущему сроку'end
 if o.unknown then return 'срок не указан'end
 if not o.min then return 'без срока'end
 local unit=o.kind=='ban'and ' дн.'or ' мин.'
 return tostring(o.min)..(o.max and o.max~=o.min and ('–'..o.max)or o.atLeast and '+'or '')..unit
end
function C.lower(s)
 return tostring(s or ''):lower():gsub('Ё','ё'):gsub('[\208\209][\128-\191]',function(c)
  local a,b=c:byte(1,2);if a==208 and b>=144 and b<=159 then return string.char(208,b+32)end
  if a==208 and b>=160 and b<=175 then return string.char(209,b-32)end;return c
 end)
end
function C.search(categoryId,text)
 local out={};text=C.lower(text)
 for _,r in ipairs(C.rules)do
  local hay=C.lower(r.title..' '..r.note..' '..C.category(r.category))
  for latin,cyrillic in pairs({dm='дм',db='дб',pg='пг',mg='мг',nrp='нрп',afk='афк',rk='рк',sk='ск',tk='тк',zz='зз'})do
   if hay:find('%f[%a]'..latin..'%f[%A]')then hay=hay..' '..cyrillic end
  end
  if hay:find('caps',1,true)then hay=hay..' капс'end
  if hay:find('зелёной зоне',1,true)then hay=hay..' зз zz'end
  local matches=true;for word in text:gmatch('%S+')do if not hay:find(word,1,true)then matches=false;break end end
  if (not categoryId or r.category==categoryId)and matches then out[#out+1]=r end
 end
 return out
end
return C

    end
    sources["punishment_target.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: punishment_target.lua
-- Original third-party credits, where present, are retained below.
local M={}
function M.normalize(command)
 local prefix,kind,target,tail=tostring(command):match('^(%s*/([%a]+)%s+)(%S+)(.*)$')
 if not prefix or not ({offwarn=true,offban=true,offjail=true,offmute=true,sban=true,unban=true})[kind:lower()]then return command end
 local nick=target:match('^([%w_%.]+)%[%d+%]$')or target:match('^([%w_%.]+)%(%d+%)$')
 if not nick or nick:match('^%d+$')then return command end
 return prefix..nick..tail
end
return M

    end
    sources["queue_confirmation.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: queue_confirmation.lua
-- Original third-party credits, where present, are retained below.
-- Match a server punishment announcement, never a quoted chat line.
local M={}
local actions={ban={'забанил игрока','забанил оффлайн игрока'},offban={'забанил оффлайн игрока','забанил игрока'},
 jail={'посадил в тюрьму игрока','посадил в тюрьму','посадил игрока','посадил в КПЗ игрока'},
 mute={'поставил затычку игроку','выдал затычку игроку'},warn={'выдал предупреждение игроку'},kick={'кикнул игрока'}}
actions.offjail=actions.jail;actions.offmute=actions.mute;actions.offwarn=actions.warn
local function trim(s)return (s:match('^%s*(.-)%s*$'))end
function M.match(command,text,target,actor)
    local kind,_,args=command:match('^/(%S+)%s+(%S+)%s*(.*)$')
    if not kind or not target or not actor then return false end
    kind=kind:lower();local verbs=actions[kind];if not verbs then return false end
    text=trim(text:gsub('{%x%x%x%x%x%x}',''))
    local issuer,body=text:match('^%[A%]%s+([%w_]+)%[%d+%]%s+(.+)$')
    if not issuer then issuer,body=text:match('^Администратор%s+([%w_]+)%[%d+%]%s+(.+)$')end
    if not issuer then issuer,body=text:match('^Администратор%s+([%w_]+)%s+(.+)$')end
    if not issuer or issuer:lower()~=actor:lower()then return false end
    for _,verb in ipairs(verbs)do
        if body:sub(1,#verb+1)==verb..' 'then
            local tail=body:sub(#verb+2)
            local nick,rest=tail:match('^([%w_]+)(.*)$')
            if nick and nick:lower()==target:lower()then
                rest=rest:gsub('^%[%d+%]','')
                if rest~='' and not rest:match('^[%s%.,:]')then return false end
                local reason=args
                if kind~='kick' and kind~='warn' and kind~='offwarn' then
                    local amount;amount,reason=args:match('^(%d+)%s+(.+)$')
                    local actual=rest:match('на%s+(%d+)')
                    -- /offban adds the existing ban duration before sending.
                    if kind~='offban' and amount and actual and tonumber(amount)~=tonumber(actual)then return false end
                end
                local reported=rest:match('[Пп]ричина:%s*(.+)$')
                if reported and reason and trim(reported):gsub('[.]$','')~=trim(reason):gsub('[.]$','')then return false end
                return true
            end
        end
    end
    return false
end
return M

    end
    sources["radar_restore.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: radar_restore.lua
-- Original third-party credits, where present, are retained below.
-- Lua port of the supplied SPRadarRestore.asi patch (static disassembly).
-- GTA SA 1.0 US: skip the radar suppression branch; independent of SA-MP version.
local M={}
local address=0x58FBF3
local original={0xA0,0xFB,0xA3,0xBA,0,0x84,0xC0,0x0F,0x85,0xA6,0,0,0,0xA0,0x65,0xF0,0xB6,0}
function M.new(api,notice)
    local self={owned=false,checked=false,started=api.getGameTimer()}
    local function match(patched)
        for i,v in ipairs(original)do
            if patched and i>=8 and i<=13 then v=0x90 end
            if api.readMemory(address+i-1,1,true)~=v then return false end
        end
        return true
    end
    function self:update()
        if self.checked or api.getGameTimer()-self.started<6000 then return end
        self.checked=true
        if type(api.readMemory)~='function' or type(api.writeMemory)~='function' then notice('Восстановление радара: API памяти недоступен.');return end
        if match(true)then return end -- Another copy owns this patch.
        if not match(false)then notice('Восстановление радара: код GTA отличается от поддерживаемого.');return end
        self.owned=true
        for i=8,13 do api.writeMemory(address+i-1,1,0x90,true)end
    end
    function self:stop()
        if self.owned then
            -- Restore only bytes still containing our patch, including partial writes.
            for i=8,13 do
                if api.readMemory(address+i-1,1,true)==0x90 then api.writeMemory(address+i-1,1,original[i],true)end
            end
        end
        self.owned=false;self.checked=false;self.started=api.getGameTimer()
    end
    return self
end
return M

    end
