    sources["report_reader.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: report_reader.lua
-- Original third-party credits, where present, are retained below.
-- Same report envelope for template replies and family questions.
local M={}
function M.parse(text)
    text=tostring(text or ''):gsub('{%x%x%x%x%x%x}',''):gsub('^%[%d%d?:%d%d:%d%d%]%s*','')
    local id,question=text:match('%[(%d+)%]%s*:%s*(.+)')
    return tonumber(id),question
end
return M

    end
