-- X-TOOLS | Project and integration: Casual_Alvarez | Module: rvanka_detector.lua
-- Original third-party credits, where present, are retained below.
-- Heuristic only: repeated fast horizontal jumps WITH reversals, not a single impact.
local D={};D.__index=D
function D.new()return setmetatable({tracks={}},D)end
local function finite(v)
    v=tonumber(v);return v and v==v and math.abs(v)<1000000 and v or nil
end
function D.position(value)
    local ok,x,y,z=pcall(function()
        return finite(value.x or value[1]),finite(value.y or value[2]),finite(value.z or value[3])
    end)
    if ok and x and y and z then return {x=x,y=y,z=z}end
end
function D:reset(id)self.tracks[id]=nil end
function D:sample(id,identity,mode,position,now)
    local p=D.position(position)
    if not p then self:reset(id);return end
    local t=self.tracks[id]
    if not t or t.identity~=identity or t.mode~=mode or now<t.time or now-t.time>500 then
        self.tracks[id]={identity=identity,mode=mode,p=p,time=now,hits={}};return
    end
    local dt=now-t.time
    if dt<60 then return end -- Coalesced packets do not imply extreme speed.
    local dx,dy=p.x-t.p.x,p.y-t.p.y
    local distance=math.sqrt(dx*dx+dy*dy)
    local speed=distance*1000/dt
    local anomalous=distance>(mode=='foot' and 8 or 15) and speed>(mode=='foot' and 85 or 160)
    local reversed=anomalous and t.dx and dx*t.dx+dy*t.dy<-.5*distance*math.sqrt(t.dx*t.dx+t.dy*t.dy)
    t.p=p;t.time=now
    if anomalous then
        t.hits[#t.hits+1]={at=now,reverse=reversed==true};t.dx=dx;t.dy=dy
    else t.dx=nil;t.dy=nil end
    while t.hits[1] and now-t.hits[1].at>1800 do table.remove(t.hits,1)end
    local reversals=0
    for _,hit in ipairs(t.hits)do if hit.reverse then reversals=reversals+1 end end
    if #t.hits>=4 and reversals>=2 then
        t.hits={};t.dx=nil;t.dy=nil
        return {speed=math.floor(speed),mode=mode}
    end
end
return D

    end
    sources["schedule.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: schedule.lua
-- Original third-party credits, where present, are retained below.
-- Daily server events. Moscow time is UTC+3 and never follows the PC timezone.
local Schedule={}
Schedule.__index=Schedule
local function defaults()
    local rows={}
    local function add(time,name,category)
        rows[#rows+1]={time=time,name=name,category=category,enabled=true}
    end
    add('00:02','Очки за онлайн','Особые события')
    add('05:04','Новые /tasks','Особые события')
    for _,time in ipairs({'14:30','17:30','20:30'}) do add(time,'Битва за семейный кейс','Семейный кейс') end
    for hour=0,21,3 do add(string.format('%02d:05',hour),'Гонка по случайному маршруту','Гонки') end
    for i,car in ipairs({'NRG-500','Sultan','NRG-500','Infernus','Sultan','NRG-500','Infernus','Sultan'}) do
        add(string.format('%02d:05',2+(i-1)*3),'Э. Гонка на '..car,'Экстремальные гонки')
    end
    for i,place in ipairs({'на ферме','под водой','на заводе','на полигоне','на ферме','под водой','на заводе','на полигоне'}) do
        add(string.format('%02d:05',1+(i-1)*3),'Казаки-разбойники '..place,'Казаки-разбойники')
    end
    for _,time in ipairs({'14:05','17:05','20:05'}) do add(time,'Квадрат','Квадрат') end
    return rows
end
Schedule.defaults=defaults
function Schedule.minute(time)
    if type(time)~='string' then return end
    local hour,minute=time:match('^(%d%d?):(%d%d)$')
    hour,minute=tonumber(hour),tonumber(minute)
    if hour and minute and hour<24 and minute<60 then return hour*60+minute end
end
local function normalize(rows)
    if type(rows)~='table' or #rows>128 then return nil,'Допустимо до 128 событий.' end
    local result={}
    for index,row in ipairs(rows) do
        local minute=type(row)=='table' and Schedule.minute(row.time)
        if not minute then return nil,'Строка '..index..': время должно быть в формате ЧЧ:ММ (00:00–23:59).' end
        local name=type(row.name)=='string' and row.name:match('^%s*(.-)%s*$')
        local category=type(row.category)=='string' and row.category:match('^%s*(.-)%s*$')
        if not name or name=='' or #name>180 or name:find('[%z\1-\31]') then return nil,'Строка '..index..': укажите название до 180 байт.' end
        if not category or category=='' or #category>100 or category:find('[%z\1-\31]') then return nil,'Строка '..index..': укажите группу до 100 байт.' end
        result[#result+1]={time=string.format('%02d:%02d',math.floor(minute/60),minute%60),
            name=name,category=category,enabled=row.enabled~=false}
    end
    return result
end
function Schedule.new(storage)
    local self=setmetatable({storage=storage,path=storage:path('settings','schedule.ini')},Schedule)
    if storage:exists(self.path) then
        local config=storage:loadIni({},self.path)
        local count=config.meta and tonumber(config.meta.count)
        local rows={}
        if count and count>=0 and count<=128 and count%1==0 then
            for index=1,count do rows[index]=config['event_'..index] or {} end
            self.rows,self.error=normalize(rows)
        else self.error='Не удалось прочитать число событий в schedule.ini.' end
        if not self.rows then self.rows={} end
    else self.rows=defaults() end
    return self
end
function Schedule:save(rows)
    local clean,reason=normalize(rows)
    if not clean then return nil,reason end
    local config={meta={count=#clean}}
    for index,row in ipairs(clean) do config['event_'..index]=row end
    local ok,err=self.storage:saveIni(config,self.path)
    if not ok then return nil,err end
    self.rows,self.error=clean,nil
    return true
end
function Schedule:nextEvents(timestamp,grouped)
    local current=(timestamp+3*3600)%86400
    local rows={}
    for index,row in ipairs(self.rows) do
        if row.enabled then
            local delta=(Schedule.minute(row.time)*60-current)%86400
            rows[#rows+1]={index=index,name=row.name,category=row.category,time=row.time,
                seconds=delta,tomorrow=current+delta>=86400}
        end
    end
    table.sort(rows,function(a,b) return a.seconds==b.seconds and a.index<b.index or a.seconds<b.seconds end)
    if not grouped then return rows end
    local result,seen={},{}
    for _,row in ipairs(rows) do
        if not seen[row.category] then result[#result+1]=row;seen[row.category]=true end
    end
    return result
end
function Schedule.countdown(seconds)
    seconds=math.max(0,math.floor(seconds))
    return string.format('%02d:%02d:%02d',math.floor(seconds/3600),math.floor(seconds/60)%60,seconds%60)
end
function Schedule.moscow(timestamp) return os.date('!%H:%M:%S',timestamp+3*3600) end
return Schedule

    end
    sources["schedule_ui.lua"] = function()
-- X-TOOLS | Project and integration: Casual_Alvarez | Module: schedule_ui.lua
-- Original third-party credits, where present, are retained below.
local View={}
local function draft(rt)
    if not rt.scheduleDraft then
        rt.scheduleDraft={}
        for _,row in ipairs(rt.schedule.rows) do
            rt.scheduleDraft[#rt.scheduleDraft+1]={time=row.time,name=row.name,category=row.category,enabled=row.enabled}
        end
    end
    return rt.scheduleDraft
end
function View.draw(rt)
    local g=rt.imgui
    local rows=draft(rt)
    rt.eventNotice:settings(g,rt)
    g.Separator()
    g.TextDisabled('Ежедневно · Москва, UTC+3 · '..#rows..' событий')
    if rt.schedule.error then g.TextWrapped(rt.schedule.error) end
    if rt.scheduleMessage then g.TextWrapped(rt.scheduleMessage) end
    if g.Button('Добавить событие##schedule_add') and #rows<128 then
        rows[#rows+1]={time='12:00',name='Новое событие',category='Особые события',enabled=true}
        rt.scheduleSelection=#rows;rt.scheduleInputs=nil
    end
    g.SameLine()
    if g.Button('Сохранить##schedule_save') then
        local ok,reason=rt.schedule:save(rows)
        rt.scheduleMessage=ok and 'Расписание сохранено.' or reason
    end
    g.SameLine()
    if g.Button('Отменить правки##schedule_cancel') then
        rt.scheduleDraft=nil;rt.scheduleInputs=nil;rt.scheduleMessage='Правки отменены.';return
    end
    g.Spacing()
    local width=g.GetContentRegionAvailWidth()
    local wide=width>=620
    local listWidth=wide and math.floor(width*0.48) or width
    local height=wide and 410 or 240
    rt.scheduleSelection=math.max(1,math.min(#rows,rt.scheduleSelection or 1))
    g.BeginChild('##schedule_list',g.ImVec2(listWidth,height),true)
    g.Text('События дня')
    g.TextDisabled('Выберите событие для редактирования')
    g.Separator()
    local order={}
    for i in ipairs(rows) do order[#order+1]=i end
    table.sort(order,function(a,b)
        if rows[a].time==rows[b].time then return a<b end
        return rows[a].time<rows[b].time
    end)
    for _,index in ipairs(order) do
        local item=rows[index]
        local label=item.time..'  '..item.name..(item.enabled and '' or ' · скрыто')
        if g.Selectable(label..'##schedule_row_'..index,rt.scheduleSelection==index) then
            rt.scheduleSelection=index;rt.scheduleInputs=nil
        end
    end
    if #rows==0 then g.TextWrapped('Здесь появятся ваши события. Нажмите «Добавить событие».') end
    g.EndChild()
    if wide then g.SameLine() else g.Spacing() end
    g.BeginChild('##schedule_details',g.ImVec2(wide and width-listWidth-12 or width,410),true)
    local row=rows[rt.scheduleSelection]
    if row then
        g.Text('Редактирование события')
        g.TextDisabled('Изменения применятся после сохранения')
        g.Separator();g.Spacing()
        if not rt.scheduleInputs then
            rt.scheduleInputs={time=g.ImBuffer(row.time,8),name=g.ImBuffer(row.name,256),category=g.ImBuffer(row.category,128)}
        end
        local fields=rt.scheduleInputs
        local enabled=g.ImBool(row.enabled)
        if g.Checkbox('Показывать событие##schedule_enabled',enabled) then row.enabled=enabled.v end
        g.Spacing()
        g.PushItemWidth(math.max(80,g.GetContentRegionAvailWidth()-8))
        for _,field in ipairs({{'time','Время по МСК · ЧЧ:ММ'},{'name','Название события'},{'category','Группа'}}) do
            g.TextDisabled(field[2])
            if g.InputText('##schedule_'..field[1],fields[field[1]]) then row[field[1]]=fields[field[1]].v end
            g.Spacing()
        end
        g.PopItemWidth()
        g.TextWrapped('Несколько событий могут начинаться одновременно.')
        g.Spacing();g.Separator();g.Spacing()
        if g.Button('Удалить событие##schedule_delete') then
            table.remove(rows,rt.scheduleSelection);rt.scheduleInputs=nil
        end
    else
        g.TextWrapped('Добавьте событие, чтобы задать время, название и группу.')
    end
    g.EndChild()
    g.Spacing()
    if g.CollapsingHeader('Восстановление расписания##schedule_restore') then
        g.TextWrapped('Вернуть стандартные события. Замена применяется только после сохранения.')
        if g.Button('Начальное расписание##schedule_defaults') then rt.scheduleResetConfirm=true end
        if rt.scheduleResetConfirm then
            g.TextWrapped('Заменить текущий черновик начальным расписанием?')
            if g.Button('Заменить черновик##schedule_reset_yes') then
                rt.scheduleDraft=rt:service('schedule.lua').defaults();rt.scheduleInputs=nil;rt.scheduleSelection=1;rt.scheduleResetConfirm=nil
            end
            g.SameLine();if g.Button('Оставить##schedule_reset_no') then rt.scheduleResetConfirm=nil end
        end
    end
end
return View

    end
