-- X-TOOLS | Project and integration: Casual_Alvarez
-- Code-only server policy. Change false to true to permit a listed server.
-- Unknown addresses remain denied; there is no interface setting for this list.
local P={port=7777,addresses={
    ['blue.adv-rp.com']=true,
    ['185.169.134.239']=true,  -- Blue
    ['185.169.134.195']=true,  -- Test
    ['185.169.134.237']=true,  -- Red
    ['185.169.134.238']=false, -- Green
    ['185.169.134.156']=false, -- Lime
    ['185.169.134.157']=false, -- Chocolate
}}
function P.allows(address,port)
    address=tostring(address or ''):lower():match('^%s*(.-)%s*$')
    if port==nil then address,port=address:match('^([^:]+):(%d+)$')end
    return tonumber(port)==P.port and P.addresses[address]==true
end
return P

