-- X-TOOLS | Project and integration: Casual_Alvarez | Module: toasts.lua
-- Original third-party credits, where present, are retained below.
-- Passive status notifications: bounded queue, no input or player ownership.
local Toasts={};Toasts.__index=Toasts
function Toasts.new(clock)
    return setmetatable({clock=clock,items={},states={}},Toasts)
end
function Toasts:push(label,enabled)
    label=tostring(label or ''):gsub('##.*',''):gsub('[\r\n]+',' '):gsub('^%s+',''):gsub('%s+$','')
    if label=='' then return end
    local now=self.clock()
    for i=#self.items,1,-1 do
        local item=self.items[i]
        if item.label==label then
            if item.enabled==enabled and now-item.time<150 then return end
            table.remove(self.items,i)
        end
    end
    self.items[#self.items+1]={label=label,enabled=enabled==true,time=now}
    while #self.items>3 do table.remove(self.items,1) end
end
function Toasts:observe(key,label,value)
    value=value==true
    local previous=self.states[key];self.states[key]=value
    if previous~=nil and previous~=value then self:push(label,value) end
end
function Toasts:visible()
    local now=self.clock()
    for i=#self.items,1,-1 do
        if now<self.items[i].time or now-self.items[i].time>=3000 then table.remove(self.items,i) end
    end
    return #self.items>0
end
function Toasts:frame(item)
    local age=math.max(0,self.clock()-item.time)
    local t=math.min(1,age/240,math.max(0,(3000-age)/400))
    return t*t*(3-2*t)
end
function Toasts:draw(rt)
    if not self:visible() then return end
    local g=rt.imgui;local sw,sh=rt.api.getScreenResolution()
    -- Crop transparent padding with UVs, keeping the original artwork's aspect.
    -- The ring belongs to the image; its centre also anchors the live status icon.
    local w=math.min(460,sw-32);local h=w*(724*.55)/(2172*.95)
    local iconX=w*.104;local iconY=h*.505
    local textX=w*.19;local textWidth=w-textX-24
    rt.art=rt.art or rt:service('art.lua').new(g,rt.base,rt.api)
    local themed=(rt.preferences.data.main.backgroundStyle or 0)>0 or rt.preferences.data.main.color~=1
    local artwork=rt.art:get(themed and 'event-notice' or 'status-toast')
    local flags=0
    for _,name in ipairs({'NoTitleBar','NoResize','NoMove','NoScrollbar','NoSavedSettings','NoInputs','NoFocusOnAppearing','NoBringToFrontOnFocus'})do flags=flags+(g.WindowFlags[name] or 0) end
    g.SetNextWindowPos(g.ImVec2(0,0),g.Cond.Always)
    g.SetNextWindowSize(g.ImVec2(sw,sh),g.Cond.Always)
    g.PushStyleColor(g.Col.WindowBg,g.ImVec4(0,0,0,0))
    g.PushStyleColor(g.Col.Border,g.ImVec4(0,0,0,0))
    g.Begin('##xt_status_toasts',nil,flags)
    local d=g.GetWindowDrawList()
    for i,item in ipairs(self.items)do
        local a=self:frame(item);local x=(sw-w)/2
        local y=sh-36-h-(#self.items-i)*(h+8)+(1-a)*18
        local function v(dx,dy)return g.ImVec2(x+dx,y+dy)end
        local function color(r,b,c,alpha)return g.GetColorU32(g.ImVec4(r,b,c,(alpha or 1)*a))end
        local accent=item.enabled and color(.25,.94,.64) or color(.98,.64,.34)
        local tint=rt.theme.color(g,rt.theme.palette.accent);tint.w=a
        if artwork then
            d:AddImage(artwork.texture,v(0,0),v(w,h),themed and g.ImVec2(0,0)or g.ImVec2(.025,.215),themed and g.ImVec2(1,1)or g.ImVec2(.975,.765),themed and g.GetColorU32(tint)or color(1,1,1))
            if themed then d:AddCircle(v(iconX,iconY),h*.31,g.GetColorU32(tint),32,1.5)end
        else
            d:AddRectFilled(v(0,0),v(w,h),color(.065,.048,.095,.97),16)
            for glow=6,1,-1 do
                d:AddRect(v(-glow,-glow),v(w+glow,h+glow),color(tint.x,tint.y,tint.z,.035),16+glow)
            end
            d:AddRect(v(0,0),v(w,h),color(tint.x,tint.y,tint.z,.9),16)
            d:AddCircle(v(iconX,iconY),h*.31,accent,32,1)
        end
        if item.enabled then
            d:AddLine(v(iconX-7,iconY),v(iconX-2,iconY+5),accent,2.5);d:AddLine(v(iconX-2,iconY+5),v(iconX+8,iconY-6),accent,2.5)
        else d:AddLine(v(iconX-7,iconY),v(iconX+7,iconY),accent,2.5) end
