            until #label==0 or g.CalcTextSize(label..'…').x<=textWidth
            label=label..'…'
        end
        d:AddText(v(textX,h*.27),color(.96,.93,1),label)
        d:AddText(v(textX,h*.54),accent,item.enabled and 'Включено' or 'Выключено')
        local remaining=math.max(0,1-(self.clock()-item.time)/3000)
        d:AddRectFilled(v(textX,h*.80),v(textX+textWidth*remaining,h*.80+2),accent,1)
    end
    g.End();g.PopStyleColor(2)
end
return Toasts

    end
