-- X-TOOLS | Project and integration: Casual_Alvarez | Module: totp.lua
-- Original third-party credits, where present, are retained below.
-- RFC 6238 / RFC 4226: SHA-1, 30 seconds, six decimal digits.
local bit=require('bit')
local M={}
local function word(n) return string.char(bit.band(bit.rshift(n,24),255),bit.band(bit.rshift(n,16),255),bit.band(bit.rshift(n,8),255),bit.band(n,255)) end
local function sha1(message)
    local length=#message
    message=message..'\128'..string.rep('\0',(55-length)%64)..word(math.floor(length/536870912))..word(length*8)
    local h={0x67452301,0xEFCDAB89,0x98BADCFE,0x10325476,0xC3D2E1F0}
    for offset=1,#message,64 do
        local w={}
        for i=0,15 do local a,b,c,d=message:byte(offset+i*4,offset+i*4+3);w[i]=bit.tobit(a*16777216+b*65536+c*256+d) end
        for i=16,79 do w[i]=bit.rol(bit.bxor(w[i-3],w[i-8],w[i-14],w[i-16]),1) end
        local a,b,c,d,e=unpack(h)
        for i=0,79 do
            local f,k
            if i<20 then f=bit.bor(bit.band(b,c),bit.band(bit.bnot(b),d));k=0x5A827999
            elseif i<40 then f=bit.bxor(b,c,d);k=0x6ED9EBA1
            elseif i<60 then f=bit.bor(bit.band(b,c),bit.band(b,d),bit.band(c,d));k=0x8F1BBCDC
            else f=bit.bxor(b,c,d);k=0xCA62C1D6 end
            local nextA=bit.tobit(bit.rol(a,5)+f+e+k+w[i])
            e,d,c,b,a=d,c,bit.rol(b,30),a,nextA
        end
        h[1],h[2],h[3],h[4],h[5]=bit.tobit(h[1]+a),bit.tobit(h[2]+b),bit.tobit(h[3]+c),bit.tobit(h[4]+d),bit.tobit(h[5]+e)
    end
    return word(h[1])..word(h[2])..word(h[3])..word(h[4])..word(h[5])
end
function M.normalize(secret)
    local value=tostring(secret or ''):upper():gsub('%s',''):gsub('%-',''):gsub('=+$','')
    if #value<16 or #value>128 or value:find('[^A-Z2-7]') then return nil end
    return value
end
function M.decode(secret)
    secret=M.normalize(secret);if not secret then return nil end
    local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
    local out,buffer,bits={},0,0
    for i=1,#secret do
        buffer=buffer*32+(alphabet:find(secret:sub(i,i),1,true)-1);bits=bits+5
        if bits>=8 then bits=bits-8;out[#out+1]=string.char(math.floor(buffer/2^bits));buffer=buffer%2^bits end
    end
    return table.concat(out)
end
function M.code(secret,time,digits)
    local key=M.decode(secret);if not key then return nil end
    local counter=math.floor((tonumber(time) or os.time())/30)
    local msg=word(math.floor(counter/4294967296))..word(counter%4294967296)
    if #key>64 then key=sha1(key) end
    key=key..string.rep('\0',64-#key)
    local inner,outer={},{}
    for i=1,64 do inner[i]=string.char(bit.bxor(key:byte(i),0x36));outer[i]=string.char(bit.bxor(key:byte(i),0x5c)) end
    local hash=sha1(table.concat(outer)..sha1(table.concat(inner)..msg))
    local offset=bit.band(hash:byte(20),15)+1
    local a,b,c,d=hash:byte(offset,offset+3)
    local number=bit.band(a,127)*16777216+b*65536+c*256+d
    digits=digits or 6
    return string.format('%0'..digits..'d',number%10^digits)
end
return M

    end
