-- Source text is UTF-8; native SA-MP messages and patterns use CP1251.
local cp1251Cache = {}
local function cp1251(text)
    local converted = cp1251Cache[text]
    if not converted then
        converted = u8:decode(text)
        cp1251Cache[text] = converted
    end
    return converted
end
