		if warnCountHmac == getHmac(warnCountCiphertext) then
			stats_warn_counter_all = tonumber(aesDecrypt(pass_stats_warn, warnCountCiphertext))
		else
			stats_warn_counter_all = tonumber(decrypt(stats_warn_counter_all))
		end
	end
