		local banCountCiphertext = string.sub(stats_ban_counter_all, 65)

		if banCountHmac == getHmac(banCountCiphertext) then
			stats_ban_counter_all = tonumber(aesDecrypt(pass_stats_ban, banCountCiphertext))
		else
			stats_ban_counter_all = tonumber(decrypt(stats_ban_counter_all))
		end
	end
	stats_ban_counter_all = tonumber(stats_ban_counter_all) or 0

