						local surfaceProbeOrigin = Vector3D(cursorRayCollision.pos[1], cursorRayCollision.pos[2], cursorRayCollision.pos[3]) - Vector3D(cursorSurfaceNormal[1], cursorSurfaceNormal[2], cursorSurfaceNormal[3]) * 0.1
