					carsp_car_count = carsp_car_count + 1
				elseif rows ~= carsp_row_count then
					setCharCoordinates(PLAYER_PED, carsp_X, carsp_Y, carsp_Z)

					carsp_X, carsp_Y, carsp_Z = getOffsetFromCharInWorldCoords(PLAYER_PED, 0, -8, 0)
					carsp_Z = getGroundZFor3dCoord(carsp_X, carsp_Y, 500)

					setCharCoordinates(PLAYER_PED, carsp_X, carsp_Y, carsp_Z)

					carsp_row_count = carsp_row_count + 1
					carsp_car_count = 1

					sampSendChat(string.format("/vec %d %d %d", car_id, color1, color2))

					carsp_tick = localClock()
				else
					text = cp1251("Создание транспорта завершено.")

					message(text)
					setCharCoordinates(PLAYER_PED, carsp_positionX, carsp_positionY, carsp_positionZ)

					vehicleSpawnBatchActive = false
				end
			end

			if first_sp == true and localClock() - first_sp_tick > 0.6 then
				local spectateRetryX, spectateRetryY = getCharCoordinates(PLAYER_PED)

				if spectateRetryX == 50 and spectateRetryY == 50 and sp_score > 0 then
					sampSendChat(string.format("/sp %d", sp_player_id))
				end

				first_sp = false
			end

			if godmode == true then
				local godmodePlayerHealth = getCharHealth(PLAYER_PED)

				if currentAdminLevel() >= 4 and godmodePlayerHealth < 80 and localClock() - lastGodmodeHealAt > 10 then
					local _, healPlayerId = sampGetPlayerIdByCharHandle(PLAYER_PED)

					sampSendChat(string.format("/hp %i 100", healPlayerId))

					lastGodmodeHealAt = localClock()
				end
			end

			if spectating_active == true and not integrationRuntime:menuOwnsKeys() and not show_main_window.v and localClock() - first_sp_tick > 1 then
				if not sampIsPlayerConnected(sp_player_id) then
					spectating_active = false

				end

				if integrationRuntime.keys:pressed('next') and not sampIsChatInputActive() then
					sp_player_id = tonumber(sp_player_id)

					if sp_player_id <= 999 then
						repeat
							sp_player_id = sp_player_id + 1

							if sp_player_id == 1000 and not sampIsPlayerConnected(sp_player_id) then
								sp_player_id = 0
							end
						until sampIsPlayerConnected(sp_player_id)

						sampSendChat(string.format("/sp %d", sp_player_id))
					else
						sp_player_id = 0

						repeat
							sp_player_id = sp_player_id + 1
						until sampIsPlayerConnected(sp_player_id)

						sampSendChat(string.format("/sp %d", sp_player_id))
					end
				elseif integrationRuntime.keys:pressed('previous') and not sampIsChatInputActive() then
					sp_player_id = tonumber(sp_player_id)

					if sp_player_id >= 1 then
						repeat
							sp_player_id = sp_player_id - 1

							if sp_player_id == 0 and not sampIsPlayerConnected(sp_player_id) then
								sp_player_id = 1000
							end
						until sampIsPlayerConnected(sp_player_id)

						sampSendChat(string.format("/sp %d", sp_player_id))
					else
						sp_player_id = 1000

						repeat
							sp_player_id = sp_player_id - 1
						until sampIsPlayerConnected(sp_player_id)

						sampSendChat(string.format("/sp %d", sp_player_id))
					end
				end
			end

			local multiBanDialogResponded, multiBanDialogButton = sampHasDialogRespond(713)

			if multiBanDialogResponded == true and multiBanTargetCount ~= 0 then
				if multiBanDialogButton == 1 then
					multiBanConfirmed = true
				else
					multiBanTargetCount = 0
				end
			end

			if multiBanConfirmed == true then
				if player1_mbanned == false then
					if sampIsPlayerConnected(mban_id1) then
						mban_temp_nick = sampGetPlayerNickname(mban_id1)

						if mban_temp_nick == mban_nick1 then
							player1_mbanned = true

							sampSendChat(string.format("/ban %i %i %s", mban_id1, mban_amount, mban_reason))

							mban_tick = localClock()
						else
							player1_mbanned = true

							sampSendChat(string.format("/offban %s %i %s", mban_nick1, mban_amount, mban_reason))

							mban_tick = localClock()
						end
					else
						sampSendChat(string.format("/offban %s %i %s", mban_nick1, mban_amount, mban_reason))

						mban_tick = localClock()
						player1_mbanned = true
					end
				end

				if player2_mbanned == false and localClock() - mban_tick > 2 then
					if sampIsPlayerConnected(mban_id2) then
						mban_temp_nick = sampGetPlayerNickname(mban_id2)

						if mban_temp_nick == mban_nick2 then
							player2_mbanned = true

							sampSendChat(string.format("/ban %i %i %s", mban_id2, mban_amount, mban_reason))

							mban_tick = localClock()
						else
							player2_mbanned = true

							sampSendChat(string.format("/offban %s %i %s", mban_nick2, mban_amount, mban_reason))

							mban_tick = localClock()
						end
					else
						sampSendChat(string.format("/offban %s %i %s", mban_nick2, mban_amount, mban_reason))

						mban_tick = localClock()
						player2_mbanned = true
					end
				end

				if multiBanTargetCount == 2 and player1_mbanned == true and player2_mbanned == true then
					multiBanLastCompletedTime = integrationRuntime.clock:date("%H%M%S")
					multiBanTargetCount = 0
				end

				if multiBanTargetCount >= 3 then
					if player3_mbanned ~= true and localClock() - mban_tick > 2 then
						if sampIsPlayerConnected(mban_id3) then
							mban_temp_nick = sampGetPlayerNickname(mban_id3)

							if mban_temp_nick == mban_nick3 then
								sampSendChat(string.format("/ban %i %i %s", mban_id3, mban_amount, mban_reason))

								mban_tick = localClock()
								player3_mbanned = true
							else
								sampSendChat(string.format("/offban %s %i %s", mban_nick3, mban_amount, mban_reason))

								mban_tick = localClock()
								player3_mbanned = true
							end
						else
							sampSendChat(string.format("/offban %s %i %s", mban_nick3, mban_amount, mban_reason))

							mban_tick = localClock()
							player3_mbanned = true
						end
					end

					if multiBanTargetCount == 3 and player1_mbanned == true and player2_mbanned == true and player3_mbanned == true then
						multiBanLastCompletedTime = integrationRuntime.clock:date("%H%M%S")
						multiBanTargetCount = 0
					end

					if multiBanTargetCount == 4 and player4_mbanned ~= true and localClock() - mban_tick > 2 then
						if sampIsPlayerConnected(mban_id4) then
							mban_temp_nick = sampGetPlayerNickname(mban_id4)

							if mban_temp_nick == mban_nick4 then
								sampSendChat(string.format("/ban %i %i %s", mban_id4, mban_amount, mban_reason))
							else
								sampSendChat(string.format("/offban %s %i %s", mban_nick4, mban_amount, mban_reason))
							end
						else
							sampSendChat(string.format("/offban %s %i %s", mban_nick4, mban_amount, mban_reason))
						end

						multiBanLastCompletedTime = integrationRuntime.clock:date("%H%M%S")
						multiBanTargetCount = 0
					end
				end
			end

			if change_ping_chart == true then
				local pingChartCursorX, pingChartCursorY = getCursorPos()

				ping_chart_x_pos, ping_chart_y_pos = convertWindowScreenCoordsToGameScreenCoords(pingChartCursorX, pingChartCursorY)

				if not integrationRuntime.placement and isKeyJustPressed(1) then
					change_ping_chart = false

					local pingChartPositionConfig = iniConfig.load(loadedCoreConfig, corePaths.config)

					pingChartPositionConfig.player_info_panel.ping_chart_xpos = ping_chart_x_pos
					pingChartPositionConfig.player_info_panel.ping_chart_ypos = ping_chart_y_pos

					iniConfig.save(pingChartPositionConfig, corePaths.config)
				end
			end

			if integrationRuntime:isChatVisible() then
				memoryApi.setint8(12216169, 1, false)
				memoryApi.setint8(12216172, 0, false)
			else
				memoryApi.setint8(12216169, 0, false)
				memoryApi.setint8(12216172, 2, false)
			end

			if show_main_window.v == false and sampTextdrawIsExists(420) then
				sampTextdrawDelete(420)
			end

			imgui.Process = show_main_window.v or spectating_active
			imgui.ShowCursor = show_main_window.v

			if os.clock() > ping_history_cleanup_tick + 15 then
				for pingSampleIndex, pingSample in ipairs(ping_list) do
					if os.clock() > pingSample.update_tick + 15 then
						ping_list[pingSampleIndex] = nil
					end
				end

				ping_history_cleanup_tick = os.clock()
			end

			if inSrvMsgHookCmd ~= nil then
				sampSendChat(inSrvMsgHookCmd)

				inSrvMsgHookCmd = nil
			end

			if togphonehookcmd then
				sampSendChat("/togphone")

				togphonehookcmd = nil
			end

		end
	end
end

