function utf8toansi(utf8Text)
	local wideCharacterBuffer = ffi.new("wchar_t[?]", 1024)
	local ansiBuffer = ffi.new("char[?]", 1024)
	local usedDefaultCharacterBuffer = ffi.new("int[?]", 1)

	ffi.C.MultiByteToWideChar(65001, 0, utf8Text, #utf8Text, wideCharacterBuffer, 1024)
	ffi.C.WideCharToMultiByte(1251, 0, wideCharacterBuffer, -1, ansiBuffer, 1024, nil, usedDefaultCharacterBuffer)

	return ffi.string(ansiBuffer)
end

function getcar(vehicleIdInput)
	if string.match(vehicleIdInput, "%d") then
		local _, vehicleHandle = sampGetCarHandleBySampVehicleId(vehicleIdInput)

		if doesVehicleExist(vehicleHandle) then

			if getDriverOfCar(vehicleHandle) == -1 then
				local playerX, playerY, playerZ = getCharCoordinates(PLAYER_PED)

				sampSendEnterVehicle(vehicleIdInput, false)
				warpCharIntoCar(PLAYER_PED, vehicleHandle)
				restoreCameraJumpcut()
				setCarCoordinates(vehicleHandle, playerX, playerY, playerZ)
			else
				text = cp1251("Транспорт занят водителем. Выберите свободный транспорт.")

				message(text)
			end
		else
			text = cp1251("Транспорт с этим ID не найден в зоне прорисовки.")

			message(text)
		end
	else
		text = cp1251("Формат: /getcar [ID транспортного средства].")

		message(text)
	end
end

function apay(paymentArguments)
	if autoPayActive == false then
		apay_player_id, apay_summ = string.match(paymentArguments, "(%d+)%s+(%d+)")

		if apay_player_id ~= nil and apay_summ ~= nil then
			apay_player_id = tonumber(apay_player_id)
			apay_summ = tonumber(apay_summ)

			if sampIsPlayerConnected(apay_player_id) then
				result, actor = sampGetCharHandleBySampPlayerId(apay_player_id)

				if doesCharExist(actor) then
					if locateCharAnyMeansChar3d(PLAYER_PED, actor, 3, 3, 3, false) then
						autoPayActive = true
						lastAutoPayAt = 0
					else
						text = cp1251("Игрок слишком далеко. Подойдите ближе.")

						message(text)
					end
				else
					text = cp1251("Игрок с этим ID не подключён.")

					message(text)
				end
			else
				text = cp1251("Игрок с этим ID не подключён.")

				message(text)
			end
		else
			text = cp1251("Формат: /apay ID сумма.")

			message(text)
		end
	else
		autoPayActive = false
		text = cp1251("Передача денег остановлена.")

		message(text)
	end
end

function rskin(skinRadiusArguments)
	if currentAdminLevel() >= 4 then
		if singleSkinBatchActive == false then
			rskin_skin, rskin_radius = string.match(skinRadiusArguments, "(%d+)%s+(%d+)")

			if rskin_skin ~= nil and rskin_radius ~= nil then
				rskin_skin = tonumber(rskin_skin)
				rskin_radius = tonumber(rskin_radius)

				if rskin_skin >= 1 and rskin_skin <= 311 and rskin_skin ~= 74 then
					if rskin_radius >= 3 and rskin_radius <= 80 then
						rskin_player_ids = sampGetMaxPlayerId(true)

						if rskin_player_ids ~= 0 then

							singleSkinBatchActive = true
						else
							text = cp1251("В зоне прорисовки нет игроков.")

							message(text)
						end
					else
						text = cp1251("Укажите радиус от 3 до 80 метров.")

						message(text)
					end
				else
					text = cp1251("Выберите скин 1–311, кроме 74.")

					message(text)
				end
			else
				text = cp1251("Формат: /rskin ID_скина радиус.")

				message(text)
			end
		else
			singleSkinBatchActive = false
			text = cp1251("Выдача скинов остановлена.")

			message(text)
		end
	else
		text = cp1251("Доступно с 4 уровня администратора.")

		message(text)
	end
end

