function carsp(vehicleGridArguments)
	if currentAdminLevel() >= 4 then
		if vehicleSpawnBatchActive == false then
			rows, car_count, car_id, color1, color2 = string.match(vehicleGridArguments, "(%d+)%s+(%d+)%s+(%d+)%s+(%d+)%s+(%d+)")

			if rows ~= nil and car_count ~= nil and car_id ~= nil and color1 ~= nil and color2 then
				rows = tonumber(rows)
				car_count = tonumber(car_count)
				car_id = tonumber(car_id)
				color1 = tonumber(color1)
				color2 = tonumber(color2)

				if car_id >= 400 and car_id <= 611 then
					if color1 >= 0 and color1 <= 255 and color2 >= 0 and color2 <= 255 then
						text = cp1251("Для остановки создания транспорта введите /carsp ещё раз.")

						message(text)

						carsp_positionX, carsp_positionY, carsp_positionZ = getCharCoordinates(PLAYER_PED)
						carsp_X, carsp_Y, carsp_Z = carsp_positionX, carsp_positionY, carsp_positionZ
						carsp_tick = 0
						carsp_car_count = 1
						carsp_row_count = 1
						vehicleSpawnBatchActive = true
					else
						text = cp1251("Цвет транспорта: допустимы ID 0–255.")

						message(text)
					end
				else
					text = cp1251("Модель транспорта: допустимы ID 400–611.")

					message(text)
				end
			else
				text = cp1251("Формат: /carsp [Кол-во рядов] [Кол-во Т/С в ряду] [ID Т/С] [Цвет 1] [Цвет 2].")

				message(text)
			end
		else
			vehicleSpawnBatchActive = false
			text = cp1251("Создание транспорта остановлено.")

			message(text)
		end
	else
		text = cp1251("Доступно с 4 уровня администратора.")

		message(text)
	end
end

function findd(organizationIdInput)
    if not integrationRuntime.access:require(4,function(reason)integrationRuntime:message(reason)end) then return end
	fraction_id = string.match(organizationIdInput, "%d+")

	if fraction_id ~= nil then
		fraction_id = tonumber(fraction_id)

		if fraction_id > 0 and fraction_id <= 13 then
			lastOrganizationQueryAt = 0

			if fraction_id == 1 or fraction_id == 2 or fraction_id == 5 then
				min_podfrac = 1
				max_podfrac = 4
			elseif fraction_id == 3 or fraction_id == 4 then
				min_podfrac = 1
				max_podfrac = 3
			elseif fraction_id >= 6 and fraction_id <= 10 then
				min_podfrac = 6
				max_podfrac = 10
			elseif fraction_id >= 11 then
				min_podfrac = 11
				max_podfrac = 13
			end

			dialogText = ""
			temp_frac = min_podfrac
			organizationLookupActive = true
		else
			text = cp1251("Организация: допустимы ID 1–13.")

			message(text)
		end
	else
		text = cp1251("Формат: /findd ID_организации.")

		message(text)
	end
end

function afindd(organizationIdInput)
    if not integrationRuntime.access:require(4,function(reason)integrationRuntime:message(reason)end) then return end
	fraction_id = string.match(organizationIdInput, "%d+")

	if fraction_id ~= nil then
		fraction_id = tonumber(fraction_id)

		if fraction_id > 0 and fraction_id <= 13 then

			if fraction_id == 1 or fraction_id == 2 or fraction_id == 5 then
				min_podfrac = 1
				max_podfrac = 4
			elseif fraction_id == 3 or fraction_id == 4 then
				min_podfrac = 1
				max_podfrac = 3
			elseif fraction_id >= 6 and fraction_id <= 10 then
				min_podfrac = 6
				max_podfrac = 10
			elseif fraction_id >= 11 then
				min_podfrac = 11
				max_podfrac = 13
			end

			temp_frac = min_podfrac
			dialogText = ""
			organizationReportActive = true
		else
			text = cp1251("Организация: допустимы ID 1–13.")

			message(text)
		end
	else
		text = cp1251("Формат: /afindd ID_организации.")

		message(text)
	end
end

function mban(multiBanArguments)
	if currentAdminLevel() >= 4 then
		if multiBanTargetCount == 0 then
			mban_usage = integrationRuntime.clock:date("%H%M%S")
			mban_last_usage_temp = mban_usage - multiBanLastCompletedTime

			if mban_last_usage_temp > 60 then
				mban_id1, mban_id2, mban_id3, mban_id4, mban_amount, mban_reason = string.match(multiBanArguments, "(%d+)%s+(%d+)%s+(%d+)%s+(%d+)%s+(%d+)%s+(.+)")

				if mban_id1 ~= nil and mban_id2 ~= nil and mban_id3 ~= nil and mban_id4 ~= nil and mban_amount ~= nil and mban_reason ~= nil then
					mban_id1 = tonumber(mban_id1)
					mban_id2 = tonumber(mban_id2)
					mban_id3 = tonumber(mban_id3)
					mban_id4 = tonumber(mban_id4)
					mban_amount = tonumber(mban_amount)

					if sampIsPlayerConnected(mban_id1) and sampIsPlayerConnected(mban_id2) and sampIsPlayerConnected(mban_id3) and sampIsPlayerConnected(mban_id4) then
						player1_mbanned = false
						player2_mbanned = false
						player3_mbanned = false
						player4_mbanned = false
						mban_tick = 0
						multiBanConfirmed = false
						multiBanTargetCount = 4
					else
						text = cp1251("Один из указанных игроков не подключён. Проверьте ID.")

						message(text)
					end
				else
					mban_id1, mban_id2, mban_id3, mban_amount, mban_reason = string.match(multiBanArguments, "(%d+)%s+(%d+)%s+(%d+)%s+(%d+)%s+(.+)")

					if mban_id1 ~= nil and mban_id2 ~= nil and mban_id3 ~= nil and mban_amount ~= nil and mban_reason ~= nil then
						mban_id1 = tonumber(mban_id1)
						mban_id2 = tonumber(mban_id2)
						mban_id3 = tonumber(mban_id3)
						mban_amount = tonumber(mban_amount)

						if sampIsPlayerConnected(mban_id1) and sampIsPlayerConnected(mban_id2) and sampIsPlayerConnected(mban_id3) then
							player1_mbanned = false
							player2_mbanned = false
							player3_mbanned = false
							multiBanConfirmed = false
							mban_tick = 0
							multiBanTargetCount = 3
						else
							text = cp1251("Один из указанных игроков не подключён. Проверьте ID.")

							message(text)
						end
					else
						mban_id1, mban_id2, mban_amount, mban_reason = string.match(multiBanArguments, "(%d+)%s+(%d+)%s+(%d+)%s+(.+)")

						if mban_id1 ~= nil and mban_id2 ~= nil and mban_amount ~= nil and mban_reason ~= nil then
							mban_id1 = tonumber(mban_id1)
							mban_id2 = tonumber(mban_id2)
							mban_amount = tonumber(mban_amount)

							if sampIsPlayerConnected(mban_id1) and sampIsPlayerConnected(mban_id2) then
								player1_mbanned = false
								player2_mbanned = false
								multiBanConfirmed = false
								mban_tick = 0
								multiBanTargetCount = 2
							else
								text = cp1251("Один из указанных игроков не подключён. Проверьте ID.")

								message(text)
							end
						else
							text = cp1251("Формат: /mban [ID1 ID2 .. ID4] дни причина")

							message(text)
						end
					end
				end
			else
				text = cp1251("Между запусками этой команды должно пройти 60 секунд.")

				message(text)
			end
		end

		if multiBanTargetCount ~= 0 and multiBanConfirmed ~= true then
			if multiBanTargetCount == 2 then
				mban_nick1 = sampGetPlayerNickname(mban_id1)
				mban_nick2 = sampGetPlayerNickname(mban_id2)
				dialogText = string.format(cp1251("{DCDCDC}Следующие игроки будут забанены на {EE7600}%i дней {DCDCDC}по причине: {EE7600}\"%s\"{DCDCDC}. Продолжить?\n\nНики игроков: {EE7600}%s[%i], %s[%i]."), mban_amount, mban_reason, mban_nick1, mban_id1, mban_nick2, mban_id2)
			elseif multiBanTargetCount == 3 then
				mban_nick1 = sampGetPlayerNickname(mban_id1)
				mban_nick2 = sampGetPlayerNickname(mban_id2)
				mban_nick3 = sampGetPlayerNickname(mban_id3)
				dialogText = string.format(cp1251("{DCDCDC}Следующие игроки будут забанены на {EE7600}%i дней {DCDCDC}по причине: {EE7600}\"%s\"{DCDCDC}. Продолжить?\n\nНики игроков: {EE7600}%s[%i], %s[%i], %s[%i]."), mban_amount, mban_reason, mban_nick1, mban_id1, mban_nick2, mban_id2, mban_nick3, mban_id3)
			elseif multiBanTargetCount == 4 then
				mban_nick1 = sampGetPlayerNickname(mban_id1)
				mban_nick2 = sampGetPlayerNickname(mban_id2)
				mban_nick3 = sampGetPlayerNickname(mban_id3)
				mban_nick4 = sampGetPlayerNickname(mban_id4)
				dialogText = string.format(cp1251("{DCDCDC}Следующие игроки будут забанены на {EE7600}%i дней {DCDCDC}по причине: {EE7600}\"%s\"{DCDCDC}. Продолжить?\n\nНики игроков: {EE7600}%s[%i], %s[%i], %s[%i], %s[%i]."), mban_amount, mban_reason, mban_nick1, mban_id1, mban_nick2, mban_id2, mban_nick3, mban_id3, mban_nick4, mban_id4)
			end

			sampShowDialog(713, cp1251("Подтверждение действия"), dialogText, cp1251("Да"), cp1251("Отмена"), 0)
		end
	else
		text = cp1251("Доступно с 4 уровня администратора.")

		message(text)
	end
end

function rotateCarAroundUpAxis(vehicleHandle, targetUpDirection)
	local rotationMatrix = Matrix3x3(getVehicleRotationMatrix(vehicleHandle))
	local rotationAxis = Vector3D(rotationMatrix.up:get())

	targetUpDirection:normalize()
	rotationAxis:normalize()

	local rotationAngle = math.acos(rotationAxis:dotProduct(targetUpDirection))

	if rotationAngle ~= 0 then
		rotationAxis:crossProduct(targetUpDirection)
		rotationAxis:normalize()
		rotationAxis:zeroNearZero()

		rotationMatrix = rotationMatrix:rotate(rotationAxis, -rotationAngle)
	end

	setVehicleRotationMatrix(vehicleHandle, rotationMatrix:get())
end

function readFloatArray(arrayAddress, elementIndex)
	return representIntAsFloat(readMemory(arrayAddress + elementIndex * 4, 4, false))
end

function writeFloatArray(arrayAddress, elementIndex, floatValue)
	writeMemory(arrayAddress + elementIndex * 4, 4, representFloatAsInt(floatValue), false)
end

function getVehicleRotationMatrix(vehicleHandle)
	local vehicleAddress = getCarPointer(vehicleHandle)

	if vehicleAddress ~= 0 then
		local matrixAddress = readMemory(vehicleAddress + 20, 4, false)

		if matrixAddress ~= 0 then

			local rightX = readFloatArray(matrixAddress, 0)
			local rightY = readFloatArray(matrixAddress, 1)
			local rightZ = readFloatArray(matrixAddress, 2)
			local frontX = readFloatArray(matrixAddress, 4)
			local frontY = readFloatArray(matrixAddress, 5)
			local frontZ = readFloatArray(matrixAddress, 6)
			local upX = readFloatArray(matrixAddress, 8)
			local upY = readFloatArray(matrixAddress, 9)
			local upZ = readFloatArray(matrixAddress, 10)

			return rightX, rightY, rightZ, frontX, frontY, frontZ, upX, upY, upZ
		end
	end
end

function setVehicleRotationMatrix(vehicleHandle, rightX, rightY, rightZ, frontX, frontY, frontZ, upX, upY, upZ)
	local vehicleAddress = getCarPointer(vehicleHandle)

	if vehicleAddress ~= 0 then
		local matrixAddress = readMemory(vehicleAddress + 20, 4, false)

		if matrixAddress ~= 0 then
			writeFloatArray(matrixAddress, 0, rightX)
			writeFloatArray(matrixAddress, 1, rightY)
			writeFloatArray(matrixAddress, 2, rightZ)
			writeFloatArray(matrixAddress, 4, frontX)
			writeFloatArray(matrixAddress, 5, frontY)
			writeFloatArray(matrixAddress, 6, frontZ)
			writeFloatArray(matrixAddress, 8, upX)
			writeFloatArray(matrixAddress, 9, upY)
			writeFloatArray(matrixAddress, 10, upZ)
		end
	end
end

function displayVehicleName(labelX, labelY, vehicleNameLabel)
	labelX, labelY = convertWindowScreenCoordsToGameScreenCoords(labelX, labelY)

	useRenderCommands(true)
	setTextWrapx(640)
