function guns()
	if currentAdminLevel() >= 1 then
		local desertEagleModelId = getWeapontypeModel(24)

		if desertEagleModelId ~= 0 then
			if not hasModelLoaded(desertEagleModelId) then
				requestModel(desertEagleModelId)
				loadAllModelsNow()

				while not hasModelLoaded(desertEagleModelId) do
					wait(0)
				end
			end

			giveWeaponToChar(PLAYER_PED, 24, 100)
			setCurrentCharWeapon(PLAYER_PED, 24)
		end

		local assaultRifleModelId = getWeapontypeModel(31)

		if assaultRifleModelId ~= 0 then
			if not hasModelLoaded(assaultRifleModelId) then
				requestModel(assaultRifleModelId)
				loadAllModelsNow()

				while not hasModelLoaded(assaultRifleModelId) do
					wait(0)
				end
			end

			giveWeaponToChar(PLAYER_PED, 31, 500)
			setCurrentCharWeapon(PLAYER_PED, 31)
		end

		local submachineGunModelId = getWeapontypeModel(29)

		if submachineGunModelId ~= 0 then
			if not hasModelLoaded(submachineGunModelId) then
				requestModel(submachineGunModelId)
				loadAllModelsNow()

				while not hasModelLoaded(submachineGunModelId) do
					wait(0)
				end
			end

			giveWeaponToChar(PLAYER_PED, 29, 500)
			setCurrentCharWeapon(PLAYER_PED, 29)
		end
	else
		message(cp1251("Доступно с 3 уровня администратора."))
	end
end

function relog()
