	sampConnectToServer(serverAddress, serverPort)
end

function explode_argb(argbColor)
	local alphaChannel = bit.band(bit.rshift(argbColor, 24), 255)
	local redChannel = bit.band(bit.rshift(argbColor, 16), 255)
	local greenChannel = bit.band(bit.rshift(argbColor, 8), 255)
	local blueChannel = bit.band(argbColor, 255)

	return alphaChannel, redChannel, greenChannel, blueChannel
end

