	while true do
		wait(0)


		if (organizationLookupActive == true or organizationReportActive == true) and localClock() - lastOrganizationQueryAt > 3 then
			if temp_frac <= max_podfrac then
				local organizationDialogBlock
				local organizationDisplayName
				local pausedPlayerCountText
				
				local organizationHtmlColor
				local organizationHistoryInputFile = io.open(corePaths.find, "r")
				local organizationHistoryHtml = organizationHistoryInputFile:read("*all")

				io.close(organizationHistoryInputFile)
				sampCloseCurrentDialogWithButton(1)

				if fraction_id >= 6 then
					sampSendChat(string.format("/templeader %i 0", temp_frac))
				else
					sampSendChat(string.format("/templeader %i %i", fraction_id, temp_frac))
				end

				integrationRuntime.organizationFindReply=nil
                integrationRuntime.organizationFindPages=nil
                integrationRuntime.organizationFindNext=nil
                integrationRuntime.organizationFindWaiting=true
				sampSendChat("/find")

