							dialogText = dialogText .. organizationDialogBlock
						else
							sampSendChat(string.format("/a " .. organizationDisplayName .. cp1251(": онлайн %d чел, на паузе %s чел."), onlinePlayerCount, pausedPlayerCountText))
						end
					else
						dialogText = string.format(cp1251("%s\nОпределить не удалось."), dialogText)
						organizationHistoryHtml = organizationHistoryHtml .. string.format("<tr><td>%s</td><td><span style='color:%s'>%s</span></td><td>-</td><td>-</td>\n", integrationRuntime.clock:date("%d-%m-%Y %H:%M:%S"), organizationHtmlColor, organizationDisplayName)
					end
				end

				local organizationHistoryOutputFile = io.open(corePaths.find, "w")

				organizationHistoryOutputFile:write(organizationHistoryHtml)
				io.close(organizationHistoryOutputFile)
			end

			if temp_frac == max_podfrac + 1 then
				if organizationLookupActive == true then
					if fraction_id >= 1 and fraction_id <= 5 then
						dialogName = cp1251("Онлайн организации")
					elseif fraction_id >= 6 and fraction_id <= 10 then
						dialogName = cp1251("Онлайн банд")
					elseif fraction_id >= 11 then
						dialogName = cp1251("Онлайн мафий")
					end

					sampShowDialog(700, dialogName, dialogText, cp1251("Закрыть"), "", 0)
				end

				local savedTemporaryLeadership = iniConfig.load(defaultCoreConfig, corePaths.config).auto_invite.organisation

				if savedTemporaryLeadership ~= "0 0" then
					sampSendChat(string.format("/templeader %s", savedTemporaryLeadership))
				end

				dialogText = nil
				organizationLookupActive = false
				organizationReportActive = false
			end

			temp_frac = temp_frac + 1
		end

		if singleSkinBatchActive == true then
			
			local singleSkinAssignedCount = 0

			for singleSkinPlayerId = 0, rskin_player_ids do
				if singleSkinBatchActive == false then
					break
				end

				if sampIsPlayerConnected(singleSkinPlayerId) then
					local singleSkinPlayerHandle

					_, singleSkinPlayerHandle = sampGetCharHandleBySampPlayerId(singleSkinPlayerId)

					if doesCharExist(singleSkinPlayerHandle) and locateCharAnyMeansChar3d(PLAYER_PED, singleSkinPlayerHandle, rskin_radius, rskin_radius, rskin_radius, false) and not isCharInAnyCar(singleSkinPlayerHandle) then
						sampSendChat(string.format("/skin %i %i", singleSkinPlayerId, rskin_skin))

						singleSkinAssignedCount = singleSkinAssignedCount + 1

						wait(3000)
					end
				end
			end

			if singleSkinAssignedCount > 0 then
				message(string.format(cp1251("Выдача временных скинов завершена. Всего выдано скинов: %d."), singleSkinAssignedCount))
			else
				message(cp1251("В указанном радиусе игроков нет."))
			end

			singleSkinBatchActive = false
		end

		if alternatingSkinBatchActive == true then
			local firstSkinAssignedCount = 0
			local secondSkinAssignedCount = 0
			local nextSkinVariant = 0

			for alternatingSkinPlayerId = 0, rskin_player_ids do
				if alternatingSkinBatchActive == false then
					break
				end

				if sampIsPlayerConnected(alternatingSkinPlayerId) then
					local alternatingSkinPlayerHandle

					_, alternatingSkinPlayerHandle = sampGetCharHandleBySampPlayerId(alternatingSkinPlayerId)

					if doesCharExist(alternatingSkinPlayerHandle) and locateCharAnyMeansChar3d(PLAYER_PED, alternatingSkinPlayerHandle, rskin_radius, rskin_radius, rskin_radius, false) and not isCharInAnyCar(alternatingSkinPlayerHandle) then
						if nextSkinVariant == 0 then
							sampSendChat(string.format("/skin %i %i", alternatingSkinPlayerId, rskin_skin))

							firstSkinAssignedCount = firstSkinAssignedCount + 1
							nextSkinVariant = 1
						else
							sampSendChat(string.format("/skin %i %i", alternatingSkinPlayerId, rskin_skin2))

							secondSkinAssignedCount = secondSkinAssignedCount + 1
							nextSkinVariant = 0
						end

						wait(3000)
					end
				end
			end

			if firstSkinAssignedCount > 0 then
				count2 = firstSkinAssignedCount + secondSkinAssignedCount

				message(string.format(cp1251("Выдача временных скинов завершена. Всего выдано скинов: %d."), count2))
				message(string.format(cp1251("Первый скин - %d ед., второй скин - %d ед."), firstSkinAssignedCount, secondSkinAssignedCount))
			else
				message(cp1251("В указанном радиусе игроков нет."))
			end

			alternatingSkinBatchActive = false
		end
	end
end

function warnlast(warningReason)
	if warningReason ~= "" then
		if sp_player_name ~= nil then
			if currentAdminLevel() >= 4 then
				if string.find(renderText, cp1251("Статус: Вышел из игры")) or string.find(renderText, cp1251("Игрок не подключен.")) then
					sampSendChat(string.format("/offwarn %s %s.", temp_name, warningReason))
				else
					sampSendChat(string.format("/offwarn %s %s.", sp_player_name, warningReason))
				end
			elseif string.find(renderText, cp1251("Статус: Вышел из игры")) or string.find(renderText, cp1251("Игрок не подключен.")) then
				sampSendChat(string.format("/a /offwarn %s %s.", temp_name, warningReason))
			else
