function sampOnServerMessage(messageColor, serverMessageText)
	local serverChatLogFile = io.open(corePaths.chat, "a")

	serverChatLogFile:write(string.format("[%s] %s\n", integrationRuntime.clock:date("%d.%m.%Y %H:%M:%S"), serverMessageText))
	io.close(serverChatLogFile)

	if string.find(serverMessageText, cp1251("Вы вошли как")) and messageColor == -65281 then

		if togphone == true then
			togphonehookcmd = true
		end
	end


	if messageColor == 1728027135 and sp_info == true then
		sp_IP = string.match(serverMessageText, "|  IP (%d+.%d+.%d+.%d+)")
	end

	if string.find(serverMessageText, cp1251("начали захват территории банды")) and messageColor == -10092289 then
		local captureDeathsResetFile = io.open(corePaths.captureDeaths, "w")

		io.close(captureDeathsResetFile)

		capture_active = true
		gangs = ""
		killedOnCapture = {}

		if string.find(serverMessageText, "Grove") then
			gangs = gangs .. " - Grove Street "
		end

		if string.find(serverMessageText, "Ballas") then
			gangs = gangs .. " - The Ballas "
		end

		if string.find(serverMessageText, "Vagos") then
			gangs = gangs .. " - Los Santos Vagos "
		end

		if string.find(serverMessageText, "Rifa") then
			gangs = gangs .. " - The Rifa "
		end

		if string.find(serverMessageText, "Aztecas") then
			gangs = gangs .. " - Varios Los Aztecas "
		end

	elseif string.find(serverMessageText, cp1251("провалилась")) or string.find(serverMessageText, cp1251("захватили территорию у банды")) and messageColor == -10092289 then
		killedOnCapture = {}

		capture_active = false

		if doesFileExist(corePaths.captureDeaths) then
			os.remove(corePaths.captureDeaths)
		end
	end

	local _, localPlayerId = sampGetPlayerIdByCharHandle(PLAYER_PED)
	local localNickname = sampGetPlayerNickname(localPlayerId)

	if string.find(serverMessageText, cp1251("Администратор ") .. localNickname) and messageColor == -6732289 then
		sessionAnswerCount = sessionAnswerCount + 1
		stats_ans_counter_all = (tonumber(stats_ans_counter_all) or 0) + 1
	elseif string.find(serverMessageText, cp1251("Администратор ") .. localNickname .. cp1251(" поставил затычку ")) and messageColor == -11521793 then
		sessionMuteCount = sessionMuteCount + 1
		stats_mute_counter_all = (tonumber(stats_mute_counter_all) or 0) + 1
	elseif string.find(serverMessageText, cp1251("Администратор ") .. localNickname .. cp1251(" кикнул игрока")) and messageColor == -11521793 then
		sessionKickCount = sessionKickCount + 1
		stats_kick_counter_all = (tonumber(stats_kick_counter_all) or 0) + 1
	elseif string.find(serverMessageText, "[SP] " .. localNickname .. "[" .. localPlayerId .. "]" .. cp1251(" кикнул игрока"), 1, true) or string.find(serverMessageText, "[A] " .. localNickname .. "[" .. localPlayerId .. "]" .. cp1251(" кикнул игрока"), 1, true) then
		if messageColor == -1717986817 then
			sessionSilentKickCount = sessionSilentKickCount + 1
			stats_skick_counter_all = (tonumber(stats_skick_counter_all) or 0) + 1
		end
	elseif string.find(serverMessageText, "[A] " .. localNickname .. "[" .. localPlayerId .. "]" .. cp1251(" посадил в тюрьму"), 1, true) and messageColor == -1717986817 then
		sessionJailCount = sessionJailCount + 1
		stats_jail_counter_all = (tonumber(stats_jail_counter_all) or 0) + 1
	elseif string.find(serverMessageText, cp1251("Администратор ") .. localNickname .. cp1251(" выдал")) and messageColor == -11521793 then
		sessionWarnCount = sessionWarnCount + 1
		stats_warn_counter_all = (tonumber(stats_warn_counter_all) or 0) + 1
	elseif string.find(serverMessageText, cp1251("Администратор ") .. localNickname .. cp1251(" забанил")) and messageColor == -11521793 then
		sessionBanCount = sessionBanCount + 1
		stats_ban_counter_all = (tonumber(stats_ban_counter_all) or 0) + 1
	end

	if chatid == true then
		getPlayersNickname()

		local messageLength = string.len(serverMessageText)
		local maximumOnlinePlayerId = sampGetMaxPlayerId(false)

		for nicknamePlayerId = 0, maximumOnlinePlayerId do
			if sampIsPlayerConnected(nicknamePlayerId) and PlayersNickname[nicknamePlayerId] then
				local nicknameMatchStart, nicknameMatchEnd = string.find(serverMessageText, PlayersNickname[nicknamePlayerId], 1, true)

				if nicknameMatchStart and nicknameMatchEnd and not string.find(serverMessageText, PlayersNickname[nicknamePlayerId] .. "[" .. nicknamePlayerId .. "]", 1, true) and not string.find(serverMessageText, "id " .. nicknamePlayerId, 1, true) and not string.find(PlayersNickname[nicknamePlayerId], ".", 1, true) and (string.find(serverMessageText, PlayersNickname[nicknamePlayerId] .. " ", 1, true) or string.find(serverMessageText, PlayersNickname[nicknamePlayerId] .. ".", 1, true) or string.find(serverMessageText, PlayersNickname[nicknamePlayerId] .. ":", 1, true) or messageLength == nicknameMatchEnd) then
					PlayerID = sampGetPlayerID(PlayersNickname[nicknamePlayerId])

					if PlayerID then
						serverMessageText = string.gsub(serverMessageText, PlayersNickname[nicknamePlayerId], PlayersNickname[nicknamePlayerId] .. "[" .. PlayerID .. "]")
					end
				end
			end
		end

		return {
			messageColor,
			serverMessageText
		}
	end
end

function sampGetPlayerID(searchedNickname)
	local maximumOnlinePlayerId = sampGetMaxPlayerId(false)

	for nicknamePlayerId = 0, maximumOnlinePlayerId do
		if searchedNickname == PlayersNickname[nicknamePlayerId] then
			return nicknamePlayerId
		end
	end
end

function getPlayersNickname()
	PlayersNickname = {}

	local maximumOnlinePlayerId = sampGetMaxPlayerId(false)

	for nicknamePlayerId = 0, maximumOnlinePlayerId do
		if sampIsPlayerConnected(nicknamePlayerId) then
			PlayersNickname[nicknamePlayerId] = sampGetPlayerNickname(nicknamePlayerId)
		end
	end
end

function sampOnSendCommand(outgoingCommand)
	local answerTargetId, answerText = string.match(outgoingCommand, "/ans%s+(%d+)%s+(.+)")

	if answerTargetId ~= nil and answerText ~= nil and auto_perenos == true and sampIsPlayerConnected(answerTargetId) then
		local _, localPlayerId = sampGetPlayerIdByCharHandle(PLAYER_PED)

		if string.len(cp1251("Администратор ") .. sampGetPlayerNickname(localPlayerId) .. "[" .. localPlayerId .. "] " .. cp1251("для ") .. sampGetPlayerNickname(answerTargetId) .. "[" .. answerTargetId .. "]: " .. answerText) > 125 then
			local answerHalfLength = string.len(answerText) / 2
			local answerSplitPosition = math.floor(answerHalfLength)
			local firstAnswerPart = string.sub(answerText, 1, answerSplitPosition) .. "..."
			local secondAnswerPart = string.sub(answerText, answerSplitPosition + 1, #answerText)

			sampSendChat(string.format("/ans %d %s", answerTargetId, firstAnswerPart))
			sampSendChat(string.format("/ans %d %s", answerTargetId, secondAnswerPart))

			return false
		end
	end

	if outgoingCommand == "/spinfo" then
		sp_info = false
	end

	local spectateTargetId = string.match(outgoingCommand, "/sp (%d+)")

	if spectateTargetId ~= nil and outgoingCommand == string.format("/sp %d", spectateTargetId) and sampIsPlayerConnected(spectateTargetId) then
		sp_player_id = spectateTargetId
		first_sp = true
		first_sp_tick = localClock()
		ping_list = {}

		if not spectating_active then
			spectating_active = true
		end
	end
end

function string.tohex(binaryText)
	return (binaryText:gsub(".", function(byteCharacter)
		return string.format("%02x", string.byte(byteCharacter))
	end))
end

function string.fromhex(hexText)
	return (hexText:gsub("..", function(hexPair)
		local decodedByte = tonumber(hexPair, 16)

		if decodedByte ~= nil then
			return string.char(decodedByte)
		end
	end))
end

function sampOnShowDialog(dialogId, dialogStyle, dialogTitle, _, button2, dialogBody)
    if integrationRuntime.organizationFindWaiting then
        local ok,myId=sampGetPlayerIdByCharHandle(PLAYER_PED)
        local result=integrationRuntime:service('organization_find.lua').parse(dialogId,dialogStyle,u8(dialogTitle),u8(dialogBody),ok and myId or nil)
        if result then
            local pages,complete,nextPage=integrationRuntime:service('organization_find.lua').collect(integrationRuntime.organizationFindPages,result,u8(button2 or ''),ok and myId or nil)
            integrationRuntime.organizationFindPages=pages
            integrationRuntime.organizationFindReply=complete
            integrationRuntime.organizationFindNext=nextPage
        end
    end
    -- Login is handled by the pre-authorization dispatcher.
end

function decrypt(encryptedCounter)
	if string.len(encryptedCounter) == 32 then
		encryptedCounter = string.fromhex(encryptedCounter)
		encryptedCounter = aeslua.decrypt(pass2, encryptedCounter)
		encryptedCounter = tonumber(encryptedCounter)

		if encryptedCounter == nil then
			encryptedCounter = 0
		end
	else
		encryptedCounter = 0
	end

	return encryptedCounter
end

function onExitScript(quittingGame)
	if quittingGame == false then

		if wallhackEnabled == true then
			nameTagOff()
		end
	end
end

function onScriptTerminate(terminatedScript, quittingGame)
	if terminatedScript == thisScript() then integrationRuntime:shutdown() end
	if terminatedScript == thisScript() then
		local savedStatistics = iniConfig.load(stats, corePaths.stats)

		if seconds_all and quittingGame then
			seconds_all = seconds_all + math.floor(gameClock())

			local totalSecondsText = tostring(seconds_all)

			aesstr = aesEncrypt(pass_stats_seconds, totalSecondsText)

			local authenticatedSecondsValue = getHmac(aesstr) .. aesstr

			savedStatistics.admin_stats.seconds_all = authenticatedSecondsValue
		end

		if stats_ans_counter_all then
			val = tostring(stats_ans_counter_all)
			aesstr = aesEncrypt(pass_stats_ans, val)
			val = getHmac(aesstr) .. aesstr
			savedStatistics.admin_stats.stats_ans_counter_all = val
		end

		if stats_mute_counter_all then
			val = tostring(stats_mute_counter_all)
			aesstr = aesEncrypt(pass_stats_mute, val)
			val = getHmac(aesstr) .. aesstr
			savedStatistics.admin_stats.stats_mute_counter_all = val
		end

		if stats_kick_counter_all then
			val = tostring(stats_kick_counter_all)
			aesstr = aesEncrypt(pass_stats_kick, val)
			val = getHmac(aesstr) .. aesstr
			savedStatistics.admin_stats.stats_kick_counter_all = val
		end

		if stats_skick_counter_all then
			val = tostring(stats_skick_counter_all)
			aesstr = aesEncrypt(pass_stats_skick, val)
			val = getHmac(aesstr) .. aesstr
			savedStatistics.admin_stats.stats_skick_counter_all = val
		end

		if stats_jail_counter_all then
			val = tostring(stats_jail_counter_all)
			aesstr = aesEncrypt(pass_stats_jail, val)
			val = getHmac(aesstr) .. aesstr
			savedStatistics.admin_stats.stats_jail_counter_all = val
		end

		if stats_warn_counter_all then
			val = tostring(stats_warn_counter_all)
			aesstr = aesEncrypt(pass_stats_warn, val)
			val = getHmac(aesstr) .. aesstr
			savedStatistics.admin_stats.stats_warn_counter_all = val
		end

		if stats_ban_counter_all then
			val = tostring(stats_ban_counter_all)
			aesstr = aesEncrypt(pass_stats_ban, val)
			val = getHmac(aesstr) .. aesstr
			savedStatistics.admin_stats.stats_ban_counter_all = val
		end

		iniConfig.save(savedStatistics, corePaths.stats)
		print(cp1251("Данные статистики успешно сохранены."))
	end
end

