    local retry=true
    sampRegisterChatCommand('xtsetup',function()retry=true end)
    while true do
        if retry then
            retry=false
            local ok,err=pcall(bootstrap.prepare,_G,root,packs,function(bytes)return hash(bytes,wait)end,function(text) print('[X-Tools SETUP] '..text);messages.chat(_G,root,text) end)
            if ok then break end
            print('[X-Tools SETUP ERROR] '..tostring(err))
            if isSampAvailable() then messages.chat(_G,root,'Запуск X-Tools остановлен. '..messages.reason(err));messages.chat(_G,root,'Введите /xtsetup, чтобы повторить подготовку. После сбоя или вылета перезапустите игру.')end
        end
        wait(100)
    end
    sampUnregisterChatCommand('xtsetup')
    factories=nil;packs=nil
    runCasualApplication()
    return main()
end
